Object.assign(window.__LB,{"2500": ["预后", "霍乱转筋、肢厥脉伏，脉伏为阳气内闭、不能外达之危候。转筋肢厥示寒邪深入，气血凝滞。脉伏与厥逆并见，提示正气欲脱，故原文直言“防厥脱”，强调病情凶险，需急防阳气暴脱。", ["伏"]], "2501": ["病机", "脉细主正气不足，寒邪痧秽格拒中枢，吐泻交作，脘格腹痛肢厥，为寒邪内闭、阳气不伸。脉细与肢厥并见，示正虚邪陷，高年局势未定，治以温运，温阳运脾以复升降。", ["细"]], "2502": ["预后", "脉细近伏，细主正虚，伏主阳郁不达。寒邪痧秽格拒中枢，清浊升降不调，上吐下泻、四肢厥冷、额汗脘闷，皆阳气欲脱之兆。舌尖绛根苔黄腻示湿郁化热。脉细近伏与厥冷额汗相应，故断“有厥脱之险”。", ["细", "伏"]], "2503": ["病机", "脉弦濡数，弦主寒邪痧秽，濡主暑湿，数主热。寒邪引动暑湿，肢麻呕吐、形寒发热，为外寒内湿、郁而化热之象。舌白糙示湿滞津伤。脉弦濡数与寒热并见相应，成疟乃佳，示邪有外达之机。", ["弦", "濡", "数"]], "2504": ["病机", "脉弦而数，弦主暑湿郁阻气机、肝脾不和，数主里热未清。原文“痧秽已止，暑湿未消，口渴里热，舌根黄腻”，脉数与里热相应，弦为湿阻气滞之象，故以芳香渗湿清透余邪。", ["弦", "数"]], "2505": ["病机", "脉弦滑数，弦主暑湿郁于少阳脾胃，滑主湿浊痰滞，数主暑热内盛。原文“痧后复泻，是暑邪下注，身热口渴，舌白糙”，脉象与暑邪下注、余邪未澈相应，故虑其转疟。", ["弦", "滑", "数"]], "2506": ["病机", "脉弦滑而数，弦为疟邪郁于少阳，滑为脾胃湿浊壅盛，数为暑热未清。原文“痧后暑邪尚盛，转为脾胃湿疟，发必吐泻交作”，脉象反映暑湿痰浊交阻中焦，故治以疏和。", ["弦", "滑", "数"]], "2507": ["病机", "脉伏，为寒邪痧秽格拒中枢、阳气不能外达之象。原文“霍乱转筋，肢厥脉伏，上吐下泻，舌白糙”，脉伏与肢厥并见，说明寒湿秽浊闭阻中焦，气血内伏，故法以温运开闭。", ["伏"]], "2508": ["病机", "脉濡弦，濡主湿浊内蕴、脾气不运，弦主寒邪痧秽郁阻气机。原文“寒邪痧秽，格拒中焦”，脉濡弦反映湿浊寒邪交阻中焦，气机不畅，故防其郁极动风而成急惊。", ["濡", "弦"]], "2509": ["病机", "脉濡弦，濡为脾虚湿盛，弦为肝旺气郁。原文“体本阴虚木旺，脾失健运，便溏身热，肝失疏泄，腹痛疝气”，脉象反映肝木乘脾、湿滞气阻之病机，故法当疏运。", ["濡", "弦"]], "2510": ["病机", "脉濡小弦，濡小主中气不足、湿渗不利，弦主肝失疏泄。原文“中气不足，溲便为之变。便溏溲涩”，脉象说明脾虚湿阻、肝郁不达，气化失司，故法当疏渗。", ["濡", "小", "弦"]], "2511": ["病机", "脉弦滑，弦主寒湿阻遏气机、肝脾不和，滑主湿浊内壅肠胃。原文“寒湿阻中，肠胃乃伤，腹痛便泻，身热肢酸”，脉象反映寒湿困阻中焦、肠胃传化失职，故法当疏渗。", ["弦", "滑"]], "2512": ["病机", "脉弦滑，弦主湿郁气滞，滑主湿热内蕴。原文谓“上焦湿热未清”，湿性黏滞，郁于上焦则气机不畅，故脉见弦滑。此脉象提示湿热未净，仍须清渗，与“复方湿止”后余邪未清之病机相应。", ["弦", "滑"]], "2513": ["病机", "脉弦数，弦为气滞，数为里热。原文谓“体素阴虚里热，气无依附”，阴虚阳亢则脉数，气滞腹痛则脉弦。此脉象反映阴虚阳亢、气滞食积之病机，与腹痛、便溏、舌黄腻等症相应，故先治其标。", ["弦", "数"]], "2514": ["病机", "脉濡弦，濡主湿滞，弦主气郁。原文谓“厥阴疏运失司”，肝失疏泄则气滞，湿邪内蕴则脉濡。此脉象说明湿郁气滞、肝脾不调之病机，与腹胀矢气、疝气渐消等症相应，故再以疏气渗湿。", ["濡", "弦"]], "2515": ["病机", "脉弦小数，弦主气滞，小为不足，数主有热。原文谓“胃钝神疲，夜寐欠安，腹痛且胀”，脾胃虚弱则脉小，气滞腹痛则脉弦，虚热内扰则脉数。此脉象提示脾胃虚弱、气滞热郁之病机，故当治脾胃。", ["弦", "小", "数"]], "2516": ["预后", "脉濡弦，濡主湿盛，弦主气滞。原文谓“暑湿下迫大肠，痢下赤白”，湿滞肠道则脉濡，气机不畅则脉弦。此脉象反映暑湿积滞、气血壅阻之病机，与饮食式微、夜寐欠安相应，故恐成噤口痢，属预后不良之兆。", ["濡", "弦"]], "2517": ["病机", "脉濡弦，濡主湿浊，弦主气滞。原文谓“肠胃积湿未清”，湿浊内蕴则脉濡，气机壅滞则脉弦。此脉象说明湿滞肠胃、气机不畅之病机，与痢次已减而腹痛后重未已相应，故治以疏渗。", ["濡", "弦"]], "2518": ["预后", "脉弦滑数，弦主气滞，滑主痰热，数主热盛。原文谓“咳呛身热，热迫便积，腹痛后重”，热邪壅盛则脉数，痰热内蕴则脉滑，气滞腹痛则脉弦。此脉象反映痰热壅盛、气滞积滞之病机，与咳呛、便积等症相应，故谓局势非轻。", ["弦", "滑", "数"]], "2519": ["病机", "脉濡弦，濡主湿盛，弦主气滞。原文谓“暑湿热挟食滞，蒸伤肠腑气血”，湿滞肠道则脉濡，气机壅阻则脉弦。此脉象说明暑湿热食滞交阻、气血蒸伤之病机，与痢下赤白、腹痛后重、舌黄腻等症相应，故法当疏导肠胃。", ["濡", "弦"]], "2520": ["病机", "脉右弦左细，右关候脾，弦为木贼土虚之象，左细乃肝血亏乏、疏泄无权。脾失运行则遍体虚浮、腹笥䐜胀、饮啖胀甚；肝乏疏泄则矢气乃舒。形消神惫、溲少口干，是气随血竭、脾土败坏，膀胱气化失司，津液不布。脉象紧扣土虚木贼、气血双亏之机，故治当养营培气、崇土泄肝。", ["弦", "细"]], "2521": ["病机", "由疟转痢，是经邪入腑，脉小弦。小为正气不足，弦主肝木乘脾、气机郁滞。疟邪本在少阳经，今内陷肠腑，故脉见小弦而非浮大。此脉示邪已入里而正渐伤，肝脾不和、气滞湿阻，故再以疏和，疏肝运脾、调畅气机以解痢疾后重。", ["小", "弦"]], "2522": ["预后", "痢久脾伤及肾，关闸大开，肾败胃阴亦败，已见谢谷不纳、痢次颇多、舌苔剥尖绛，脉小弦而数。小为气血衰少，弦为土虚木贼，数则阴伤火动、胃气败绝。脉症合参，乃脾肾两败、胃阴耗竭之危候，故用参苓白术散培土固本，然脉数不退则预后堪忧。", ["小", "弦", "数"]], "2523": ["预后", "赤痢两月，腹痛后重依然，痢次渐减，舌绛苔糙，脉濡数。濡主湿滞，数主热郁，湿热蕴结肠腑，气血壅滞，故后重未除。舌绛苔糙为阴伤之征，脉濡数示湿未化而热未清，正虚邪恋，故防成休息痢，即久痢脾虚、湿热留连、时发时止之候。", ["濡", "数"]], "2524": ["病机", "阴虚之体感受暑湿，蒸伤肠腑为赤白下痢，痢经两旬，腹痛后重，胃阴受劫火升，鼻衄喉颡起糜，里热自汗，舌绛苔薄，脉细而数。细为阴血亏虚，数为暑热内炽、火升动血。脉象示阴伤热炽并见，故以酸甘化阴、仿生脉大意，救胃阴而清暑热。", ["细", "数"]], "2525": ["病机", "休息痢经年，是脾虚有湿，右臂麻木不仁，脉濡弦。濡主湿浊内蕴，弦主肝木乘脾、气机不畅。脾虚运化失职，湿留肠腑则痢久不已；湿阻经络、气血不达则右臂麻木。脉濡弦正合脾虚湿困、肝脾不调之机，故姑先疏运，运脾化湿以治其本。", ["濡", "弦"]], "2526": ["主病", "黄疸脉濡，濡为湿象，主湿浊内蕴、脾运不健。黄疸多因湿郁发黄，脉濡则示湿邪偏盛而未化燥，脾土受困，胆汁不循常道外溢肌肤。此脉与黄疸之湿郁病机相应，故治以疏和，疏肝运脾、化湿退黄，使湿去则黄自退。", ["濡"]], "2527": ["病机", "湿郁留而不澈，太阴受困，纯热无汗，脉小弦。小为正气不足，弦主湿郁气滞、肝木乘脾。太阴脾土受湿困则运化失司，湿郁化热而纯热无汗，气机不畅故脉见小弦。此脉示湿郁脾困、气滞热蕴之机，故再以清渗，清其热而渗其湿。", ["小", "弦"]], "2528": ["病机", "脉小弦者，小为气血不足，弦主气机郁滞、木旺克土。本案湿阻中焦，阳明通降失司，湿浊内蕴则脉道不畅而见小，土壅木郁则见弦。脉小弦正合湿阻气滞、升降失常之病机，故法以疏和，疏其壅滞、和其脾胃，使中焦通降复常。", ["小", "弦"]], "2529": ["病机", "濡脉主湿，弦脉主气滞痰凝。原文谓湿著不化，痰气交阻，湿邪黏滞则脉道软而浮，痰气交阻则脉气紧张而弦。濡弦并见，正示湿浊内著、痰气互结之病机，故治以疏渗，疏化痰气、渗利湿浊，使湿去痰消而脉自和。", ["濡", "弦"]], "2530": ["病机", "濡主湿邪偏胜，弦主气机郁滞。本案湿阻气滞，腹痛便赤，湿浊内阻则脉濡，气机不畅则脉弦。濡弦相合，说明湿著于内、气滞不行，故腹痛便赤由湿滞交阻所致。治以疏渗，疏其气滞、渗其湿浊，湿化气通则诸症可解。", ["濡", "弦"]], "2531": ["病机", "小脉主气血不足或湿邪内阻，数脉主热。原文便血已止，阳明余湿未清，小溲短赤，脉小数。便血虽止而余湿未尽，湿郁化热则脉数，湿阻气机、正气未复则脉小。小数并见，示余湿夹热、正虚未复之病机，故再以清渗，清其余热、渗其湿邪。", ["小", "数"]], "2532": ["病机", "数脉主热。原文阳明被灼，湿热熏蒸，目糊微热，舌糙脉数。阳明热盛，湿热交蒸，热邪鼓动血脉则脉数；舌糙为热灼津伤之象。脉数在此正说明湿热熏蒸、阳明热炽之病机，故尚须清渗，清其湿热、渗其浊邪，使热退湿化而脉数自减。", ["数"]], "2533": ["病机", "小脉主湿阻气机、正气不畅，数脉主郁热。原文湿著不化，痰浊上扰，舌垢，脉小数。湿浊内著，痰浊上蒙则舌垢；湿郁化热、痰阻气机则脉小数。小数并见，示湿痰内蕴、郁而化热之病机，故治先分利三焦，使湿痰从三焦分消，热随湿去而解。", ["小", "数"]], "2534": ["病机", "濡脉主湿胜，数脉主热。原文气虚湿胜，健运失职，消化不良，得食易滞，脾胃受湿所困，神疲力懈，自汗盗汗，舌黄腻，脉濡数。气虚则运化无力，湿胜则脉濡；湿郁化热则脉数，舌黄腻亦为湿热之征。濡数相合，正示气虚湿胜、湿郁化热之病机，故治先疏运中枢、渗湿涤痰。", ["濡", "数"]], "2535": ["病机", "沉主里、主阳虚，弦主肝木乘脾，小软示正气不足。原文年近花甲，中阳衰馁，肝木乘间横克脾胃，呕恶嗳满，寒热往来，杳不思纳，按脉沉弦小软，舌绛苔剥。沉弦为肝木内郁、乘克脾胃，小软为阳气衰馁、气血不足。脉证合参，病在脾胃，中阳衰而肝木横，故论治当补土生金、佐通降阳明。", ["沉", "弦", "小", "软"]], "2536": ["病机", "脉沉弦，重按稍振，沉主里，弦主饮主痛，反映痰饮内停、脾胃升降失司。原文谓“高年中虚，痰饮泛滥，阳明容纳无权，贲门窄小”，呕恶、寒热、吞咽作梗皆由脾胃两经气机失调所致，故脉象沉弦与此病机相应。", ["沉", "弦"]], "2537": ["病机", "脉沉弦，较前略振，沉为在里，弦为饮为痛。原文指出“脾胃少元阳之助，脾不能为胃行其津液，水谷精微徒酿痰浊”，浊饮上泛致呕逆频仍、寒热往来，脉沉弦正是脾阳不振、痰饮内阻之象。", ["沉", "弦"]], "2538": ["预后", "脉虚弦，虚为阴血不足，弦为木旺。原文“血后阴伤木旺，金被火刑”，阴伤则木失涵养而亢，木火刑金，故脉虚弦。此脉示正虚邪亢，已“延入损途”，预后不良。", ["虚", "弦"]], "2539": ["病机", "脉右数，右寸主肺，数主热。原文“湿蒸热郁，肺金受灼，络道被蒙”，湿热郁蒸于肺，灼伤肺络，故咳呛肋痛。久咳阴虚，脉数示热郁阴伤，延成损怯之机。", ["数"]], "2540": ["病机", "脉小弦，小为津液不足，弦主气机郁滞。原文“病后复感，津液受劫，时交湿令，湿郁化热”，津伤而湿郁化热，气机不畅，故神疲纳懈、舌中剥，脉小弦反映津亏湿郁之病机。", ["小", "弦"]], "2541": ["病机", "脉弦数，弦主邪郁气滞，数主热。原文“病伤不复，复劳复感，发热形寒，脘闷泛呕”，劳复感邪，邪郁化热，气机不畅，故脉弦数。此脉示正虚邪郁，先治其标。", ["弦", "数"]], "2542": ["病机", "脉濡而弦，濡主湿，弦主气郁。原文“感邪已化，里热未澈，胃气似有来复”，湿邪未净，气机尚郁，故脉濡而弦。舌仍中剥示阴伤未复，再以通降阳明，调其气机。", ["濡", "弦"]], "2543": ["预后", "脉左弦大，左主肝，弦大为肝风内动之象。原文“内风暗动，夹感风邪，颈项强痛，肢厥类痉，自汗滂沱”，积虚成损，肝风鸱张，故脉弦大。此脉示虚风内动，厥变堪虞，预后险恶。", ["弦", "大"]], "2544": ["病机", "脉小弦为病后气阴未复之象。小脉示气血不足，弦脉主肝郁气滞，亦为阴血亏虚、筋脉失养之征。原文谓“神疲力懈，便难腰酸”，正是气阴两伤、肝脾不调所致。脉小弦与余热渐清、胃气渐复并见，说明正气未全复，故尚须清渗以除余邪。", ["小", "弦"]], "2545": ["病机", "脉小弦主病后元气未复、里热未澈。小脉为元气亏虚，弦脉为里热郁滞、肝木偏旺。原文“交阴微寒”乃热郁于里、阳气不达外之象。脉小弦与元气未复、里热未清相应，故治以清养为主，徐图恢复，不可峻补。", ["小", "弦"]], "2546": ["病机", "右脉小滑而数，主肺胃痰热殊甚、大肠湿火留连。滑脉主痰湿，数脉主热，小脉示阴分不足。原文谓“阴虚火旺”，痰热湿火内蕴，灼伤阴液，故脉小滑而数。治以滋清互施，既清痰火，又滋阴虚。", ["小", "滑", "数"]], "2547": ["病机", "脉芤弦主失血后阴血亏虚、肺火偏旺。芤脉为血去阴伤、脉道不充，弦脉为肺火偏旺、肝木失柔。原文“失血咳呛，喉疼气粗，舌绛”，皆阴虚火旺、灼伤肺络之候。脉芤弦与劳损之基相应，故切宜怡养。", ["芤", "弦"]], "2548": ["病机", "脉弦滑数主脾肺气虚、饮痰内凝化热。弦脉主饮主痛，滑脉主痰，数脉主热。原文“面浮腹膨”为饮痰内停、脾失健运之象；“曾经失血”示阴络受损。脉弦滑数与饮痰内凝、郁而化热相应，故防延入损途。", ["弦", "滑", "数"]], "2549": ["病机", "脉弦小数主饮痰未净、郁热未清。弦脉主饮，小脉示正气渐虚，数脉为余热未清。原文“咳缓喘平，腹膨渐消”，说明痰饮渐化而未尽，郁热尚存。脉弦小数与病情好转而余邪未澈相应，故仍宗原议增删。", ["弦", "小", "数"]], "2550": ["主病", "脉弦数主阳明胃火有余。弦脉主火主痛，数脉主热，弦数相合为火热炽盛之象。原文“上干清道而为鼻衄”，乃胃火循经上炎、灼伤阳络所致。脉弦数与胃火有余、迫血妄行相应，故当清营热以折火势。", ["弦", "数"]], "2551": ["病机", "脉弦数主湿郁化火、蒸烁肺金。弦脉主郁主饮，数脉主热，弦数并见为湿热郁蒸之候。原文“咳呛痰红，身热盗汗”，乃湿火灼肺、损伤肺络、迫津外泄所致。脉弦数与湿郁化火、肺金受烁相应，故先清燥救肺。", ["弦", "数"]], "2552": ["病机", "脉右数，右寸候肺，数主热。原文言\"木火刑金，烁络使然\"，肝木之火上刑肺金，灼伤肺络，故咳呛失血。数脉为火热内盛之征，右部独数，病位在肺，热由肝木而发，故法当平木清金，标本兼治。", ["数"]], "2553": ["兼症", "复诊气促较平而咳呛依然，脉右数未减，说明木火刑金之势虽稍缓，肺中火热仍盛。数脉不去，则咳呛难止，热未清则络未宁。原文\"再以清降\"，正因右数脉示热邪留恋肺金，须继续清降，不可因气促稍平而止。", ["数"]], "2554": ["病机", "失血咳呛兼身热气粗，脉右数。右数主肺热，身热为热蒸于外，气粗为热壅于肺、肺失肃降。热灼肺络则血溢，故原文以\"和络清金\"为法。数脉在此既示热盛，又示络伤未复，热不清则血难止，络不和则咳难平。", ["数"]], "2555": ["病机", "脉小数，小为阴血不足、络脉受损，数为火热内郁。原文\"木火刑金烁络，络破血溢\"，火热灼络则血溢，血去则脉道不充故小，热郁则数。小数并见，示火郁而阴伤，故法当平木清金兼调气火，既清火热，又顾阴血。", ["小", "数"]], "2556": ["病机", "脉芤弦，芤主失血、血去脉道中空，弦主肝木偏亢、络脉拘急。原文\"热灼阳络，血从上溢\"，热伤阳络则血上溢，血脱于外故脉芤；木火未平、络气不和故脉弦。芤弦并见，示出血与肝火并存，故以和络清金为治。", ["芤", "弦"]], "2557": ["病机", "久热伤络，络破血溢，咳呛气促，脉芤弦。芤为血溢脉空之象，弦为热灼络急、肝木不柔之征。久热不去则络伤难复，血溢不止则脉愈芤。原文以\"和络清金\"为法，正针对热伤血络、血去阴伤之机，弦芤并见示火与虚并存。", ["芤", "弦"]], "2558": ["预后", "脉弦小数，弦主肝火、小主阴伤、数主热盛。原文\"咳逆伤络，血从上溢，咳痰腥臭\"，热灼肺络则血溢，热壅血腐则痰腥臭。弦小数示火郁阴伤、络损日深，故原文断\"恐成肺痿\"，以热灼肺叶、久则叶焦痿弱，属预后警示。", ["弦", "小", "数"]], "2559": ["病机", "久咳伤络，络破血溢，咯血盈盏，身热气粗，脉芤弦。芤为大量失血、脉道空虚，弦为肝火未平、络气拘急。血随气载而上溢，气粗身热示火盛气逆。原文断为\"劳损之基\"，以血去阴伤、火灼络损，久则成虚劳，芤弦正是出血与火盛并见之象。", ["芤", "弦"]], "2560": ["病机", "失血之后脉见芤弦，芤为血去中空、阴血亏耗之象，弦乃肝木偏旺、肺胃火炽之征。血失则阴不制阳，木火刑金，故咳呛不止。脉芤弦正示血虚而火未清、肝肺同病之机，与失血咳呛相应。", ["芤", "弦"]], "2561": ["病机", "脉右数，右候肺，数主热。木火刑金，火性急迫故脉数，右部独显则热在肺金。火热灼肺，肃降失司，气逆而为咳呛，络伤则失血。此数脉示火旺之病机，非虚寒所致，故以平木清金为法。", ["数"]], "2562": ["病机", "脉芤弦，芤主失血伤阴、血脉空虚，弦主肝木亢盛。木火刑金，火灼肺络则失血，血去则脉芤；肝火未平则脉弦。此脉象揭示阴血已亏而木火犹炽，虚实夹杂，故咳呛与失血并见，治当平木清金兼顾。", ["芤", "弦"]], "2563": ["病机", "咯血盈盏，血随气载而上溢，脉见芤弦。芤为血脱于内、脉道不充，弦为气逆火升、肝木鼓动。气火上载则血不循经，血去则阴亏而脉芤。此脉示气火迫血、阴血两伤之机，故原文切宜怡养，以静摄为要。", ["芤", "弦"]], "2564": ["病机", "脉左弦，左候肝，弦为肝脉。木火刑金，肝火偏旺故左脉弦劲，火逆犯肺则失血咳呛。弦而不数，示火势尚郁于肝木，未至炽盛。此脉定位在肝，说明病本在木、病标在金的病机，故以平木清金为治。", ["弦"]], "2565": ["病机", "血后余热未清，脉仍芤弦。芤示失血后阴血未复、脉道空虚，弦示肝木余火未平、肺金失肃。热留则咳呛痰少、身热便难，舌糙亦津伤之征。脉芤弦说明血虚与余热并存，故再以清泄，清其余热而不忘养阴。", ["芤", "弦"]], "2566": ["病机", "脉细数，细主阴血不足、脉道不充，数主虚热内扰。阴虚肺热，肺失肃降，故咳呛；虚火内灼则脉数，阴亏则脉细。此脉象示阴虚为本、肺热为标，虚多实少之病机，治以清泄，清其虚热以复肃降。", ["细", "数"]], "2567": ["病机", "脉滑数，滑主痰湿壅盛、气血尚实，数主火热内炽。木火刑金，火炼津液成痰，痰火交阻于肺络，故咳呛痰红。滑数并见，示痰火实邪偏盛而非纯虚，与失血咳呛相应，法当和络清金以化痰火。", ["滑", "数"]], "2568": ["病机", "脉芤弦，芤主血虚失血，弦主热伤阳络、气机不和。热邪灼伤阳络，血从上溢，故见脉芤弦。此脉象说明热伤血络、阴血外溢而络脉失和，主咯血、吐血等上部出血，治当清阳明以和阳络。", ["芤", "弦"]], "2569": ["病机", "左脉芤弦，芤为失血伤阴，弦为劳倦阳弛、胃络不和。咯血盈盆盈盏，胃络抽疼，气逆脘闷里热，皆因劳倦伤阳、络伤血溢所致。脉芤弦正合血去络伤、气逆里热之机，治当和阳络清营热，并重怡养。", ["芤", "弦"]], "2570": ["病机", "脉沉芤弦，沉主病在里，芤主失血后阴血未复，弦主阳络未和、气机不畅。咯血初止而咳痰薄白，脉沉芤弦说明血去络伤、里气未和，余邪留滞，故再以清营和络为治。", ["沉", "芤", "弦"]], "2571": ["病机", "脉濡弦，濡主湿郁阴伤，弦主气机郁滞、络脉不和。湿郁化火，熏灼胃络，络破血溢，兼喉癣吞咽作梗、舌黄腻，皆由阴分不足、湿火内郁所致。脉濡弦正合湿郁化火、络伤血溢之机，调养为上。", ["濡", "弦"]], "2572": ["病机", "右脉濡数，濡主湿滞阴伤，数主热炽。失血咳呛、出痰薄白，因肺胃火炽，热灼阳络而血外溢。右脉候肺胃，濡数说明肺胃热炽兼阴分受伤，故切宜怡养，以清肺胃之火。", ["濡", "数"]], "2573": ["病机", "脉弦数，弦主气机郁滞、木火偏亢，数主热炽于里。血止咳缓而热炽于里，出痰仍薄，脉弦数说明肺胃热未清、木火内扰，故仍治肺胃，清其里热。", ["弦", "数"]], "2574": ["病机", "脉弦，弦主木火偏亢、气机郁滞。久咳不已，肺元自虚，木火闪烁，咳呛失血，乃肺虚不能制木，木火刑金所致。脉弦正示木火内动、肺金受灼之机，治以平木清金。", ["弦"]], "2575": ["病机", "脉小弦，小主阴血不足、脉道不充，弦主木火未平、气机郁滞。血止咳呛未已，脉小弦说明失血后阴分已伤，而肝木之火仍未清静，肺金受灼，故再以肝肺同治，清木火而益肺阴。", ["小", "弦"]], "2576": ["病机", "脉芤主络血外溢而阴血亏虚，弦主肝木失柔、络脉拘急。湿热伤络，血从上溢，咳血屡发，既耗阴血又留湿热，故脉见芤弦。此脉示络损未复、肝木偏亢，为劳损之基，与咳血屡发相应。", ["芤", "弦"]], "2577": ["病机", "阳络受伤，血从上溢，咯血脘闷，咳逆，舌尖绛苔腻，脉弦芤而数。弦为肝火偏旺，芤为络血外溢而阴伤，数为热象。三脉合见，示木火刑金、络热血溢，故以和络清金为法。", ["弦", "芤", "数"]], "2578": ["病机", "复方咯血未止，木火偏旺，气冲咳逆，火升头眩，嘈杂心悸，脉仍芤弦带数。芤示络血未止而阴血耗伤，弦为木火偏旺、气逆上冲，数主火热。脉仍芤弦带数，说明木火未平、络损未复，故佐平木火。", ["芤", "弦", "数"]], "2579": ["病机", "咯血已止而阳络未和，虚里穴呼吸抽疼，是血去气无依附所致。脉右小数，小为阴血亏少、脉道不充，数为余热未清。右部小数示肺胃络脉未和、虚热内扰，故法以和络调气，佐平木火。", ["小", "数"]], "2580": ["病机", "顿呛不已，挟感屡发，咳甚则痰中带红，脉右数。体素阴虚内热，热留痰恋，右脉数主肺金有热、痰热内恋。数脉示热邪未清，灼伤肺络则痰红，与阴虚内热、顿呛屡发相应，故用喻氏法。", ["数"]], "2581": ["病机", "肺胃火炽，阳明受灼，失血咳呛，脉芤弦。芤为阳明络伤、血失阴亏，弦为火炽木亢、络脉拘急。肺胃火灼阳明，血从上溢，故脉芤弦，与失血咳呛相应，治以和络清金。", ["芤", "弦"]], "2582": ["病机", "久咳不已，阳络震伤，失血气促，脉芤弦。久咳震伤阳络，血失而阴亏，故脉芤；肝木失柔、气逆不降，故脉弦。芤弦并见，示络伤血失、木亢气促，切宜怡养，不可再耗。", ["芤", "弦"]], "2583": ["病机", "痰火烁络，咳呛失血，脉小弦。小为阴血耗伤、脉道不充，弦为痰火郁于络脉、肝木失柔。痰火烁络则咳呛失血，脉小弦正示络伤阴亏而火未清，故以和络清金为法。", ["小", "弦"]], "2584": ["病机", "脉小弦，小为气血不足，弦主肝木乘脾、络脉拘急。前投疏运而便溏渐减，是脾运稍复；然咯痰带红，乃胃络受灼、血溢脉外。脉小示正气已伤，弦示木火内扰、络气不和，故主脾胃虚弱兼胃络受灼之病机，治当从脾胃入手。", ["小", "弦"]], "2585": ["病机", "脉弦小数，弦主木火内郁、络脉不和，小为阴血不足，数主热。湿气渐化而阳明热灼，故大便由溏转结；痰中带红，是热伤阳络、血从上溢。脉弦小数正合阳明热灼、络伤血溢之机，故治阳明而佐和阳络。", ["弦", "小", "数"]], "2586": ["病机", "脉芤弦，芤主失血、血去脉空，弦主木火内扰、络气不和。热灼阳明，迫血上溢，故咯血咳呛；血既外溢则脉道中空而见芤，热郁络脉则见弦。此脉主阳明热灼、阳络损伤、血从上溢之病机，故以和络清金为法。", ["芤", "弦"]], "2587": ["病机", "脉芤弦而数，芤为失血之征，弦主木火与络气不和，数主热盛。迭感咳呛，失血复萌，是肺络旧伤未复、火热再迫血溢。数脉示热势较甚，芤弦示血去络伤，合为肺火灼络、血热妄行之病机，故治以和络清金。", ["芤", "弦", "数"]], "2588": ["病机", "脉芤弦，芤主血去脉空，弦主络气拘急、木火内扰。屏伤阳络，络破血溢，故失血咳呛。血溢于外则脉道失充而芤，络伤气滞则脉见弦，二者并见，正合阳络损伤、血从上溢之病机，故以和络清金为治。", ["芤", "弦"]], "2589": ["病机", "脉芤弦，芤为失血、脉道中空之象，弦主络脉拘急、火热内郁。阳络受伤，血从上溢，咯血盈盏，血去既多则脉芤，络伤气逆则脉弦。此脉紧扣络破血溢之病机，说明失血与络热并存，故治以和络清金，清金以宁络、和络以止血。", ["芤", "弦"]], "2590": ["病机", "脉芤弦，芤主失血、血去脉空，弦主络气不和、久咳气逆。久咳伤络，络破血溢，故见芤弦之脉。久咳则肺气耗伤、络脉脆弱，一有所触即破而血溢；芤示血已外失，弦示络气仍滞。此脉主久咳伤络、络破血溢之病机，治以和络清金。", ["芤", "弦"]], "2591": ["病机", "脉芤弦，芤为失血、脉道空虚，弦主肺火内郁、络气不和。失血咳呛，肺火自旺而肺元自虚，火旺则灼络，元虚则脉失所养，故脉见芤弦。芤示血去正伤，弦示火郁络滞，合为肺火灼络、肺元亏虚之病机，故以西昌法清金和络。", ["芤", "弦"]], "2592": ["病机", "脉芤弦，芤主血虚失血，弦主气机紧张。热灼阳络，血从上溢，咯血盈盏，阴血骤伤故脉芤；热邪未清、络脉不和故脉弦。此脉示失血后阴血亏虚而热未净，与咳呛痰多并见，宜怡养以复。", ["芤", "弦"]], "2593": ["病机", "脉弦数，弦主热郁络脉，数主热盛。阴虚生热，热灼阳络，络破血溢，故鼻衄咯血俱至；舌黄腻为热兼湿。脉弦数正是内热炽盛、络伤血溢之象，故以和络清金为治。", ["弦", "数"]], "2594": ["病机", "脉虚芤弦，虚芤主正气阴血亏伤，弦为阳明生气受戕、络脉不和。便血虽止而饮啖式微、少寐神疲、眩晕盗汗，皆正气已伤之候；脉虚芤弦示气阴两伤而虚风内动，故云汗脱堪虞。", ["虚", "芤", "弦"]], "2595": ["病机", "脉小数，小主阴虚，数主内热。阴虚则生内热，脾不统血，故交阴身热盗汗、便溏肠红。脉小数正合阴虚内热、脾虚失统之机，虚实夹杂，故药难速效。", ["小", "数"]], "2596": ["病机", "脉细弦，细主阴血不足，弦主湿火郁遏、肠络受伤。湿火下趋蒸伤肠，肠红腑时红，便积溲涩，脉细弦示湿火内郁而阴分已伤，邪滞肠腑，故势颇纠缠。", ["细", "弦"]], "2597": ["病机", "脉濡弦，濡主湿滞，弦主气机郁滞。赤痢经久不已，腹痛后重，肠风气陷，脉濡弦示湿滞肠腑、气机下陷而郁滞不舒，故肠红是忧，病势缠绵。", ["濡", "弦"]], "2598": ["病机", "脉濡弦，濡为湿象，弦为气滞。肠红腹痛，后重气陷，脉濡弦示湿浊滞肠、气机郁陷，病在肠胃，湿滞气陷交阻，故难许速效。", ["濡", "弦"]], "2599": ["病机", "脉濡弦，濡主湿滞，弦主气郁。宿恙肠红历久年数，胃纳尚可，力能支持，脉濡弦示湿滞肠络、气机郁滞，病根深久，故以驻车丸、脏连丸早晚频服，断根极难。", ["濡", "弦"]], "2600": ["病机", "脉弦数，弦主肝郁湿火内蕴，数主热，合示阴分不足而湿火下趋，灼伤阴络，故为痔血漏卮。脉象与痔血漏下相应，治以滋清法，滋其阴、清其火。", ["弦", "数"]], "2601": ["病机", "脉濡弦，濡主湿，弦主肝郁，示湿火未清而阴分渐复。复方投滋清法后诸恙较减，脉仍濡弦，说明湿火余邪未尽，故再宗原议增删，续以滋清为治。", ["濡", "弦"]], "2602": ["病机", "脉濡弦，濡主湿，弦主肝郁化火，合示湿火下灼阴络，迫血妄行，故为痔漏便血。脉象与湿火下注、阴络受损之病机相应，治以滋清法，清湿火、滋阴血。", ["濡", "弦"]], "2603": ["病机", "脉濡数，濡主湿，数主热，合示湿火下注膀胱，蒸伤气血，故为赤淋。脉象与湿火蕴结下焦、气血受伤之病机相应，治以通利，通利膀胱以清湿火。", ["濡", "数"]], "2604": ["病机", "脉濡数，濡主湿，数主热，示劳倦挟湿，湿火蒸精化浊，故肢酸头疼、鼻衄身热。脉象与湿火内蒸、兼阳明热盛之病机相应，当治湿火，兼清阳明。", ["濡", "数"]], "2605": ["病机", "脉濡弦，濡主湿，弦主肝郁，合示湿火下注，蒸精化浊。脉象与湿火下趋、精浊不化之病机相应，故以刘松石法清渗湿火，使湿去火清而浊自化。", ["濡", "弦"]], "2606": ["病机", "脉濡弦，濡主湿，弦主肝郁，示气虚湿胜，湿火下趋，膀胱溲浊尿血。脉象与湿火下注、气虚不摄之病机相应，治以清渗，清湿火、渗浊邪。", ["濡", "弦"]], "2607": ["病机", "脉弦数，弦主肝郁，数主热，示湿火下趋，君相火炽，故遗泄淋浊并至。脉象与湿火下注、君相火旺之病机相应，治先清泄，清湿火、泄相火。", ["弦", "数"]], "2608": ["病机", "脉左弦主肝木偏亢，本案湿火下趋灼伤阴络而溲血不痛，乃肝火挟湿下迫、阴络受损之候。左弦为肝经气火内郁之象，火伤阴络则血溢，湿火下注故溲血而不刺痛，与一般淋证涩痛有别。治以清泄，正合清肝泄火、凉血宁络之法。", ["弦"]], "2609": ["病机", "脉弦小数，弦为木旺，小为阴亏，数为火烁。原文谓水亏木旺、火烁肺金，故身热盗汗、肢酸眩旋。阴虚无以制木，木火刑金则身热盗汗；肝阳上扰则眩旋肢酸。脉象与阴虚火旺之病机相合，法宜清熄，即滋水清火、潜降肝阳。", ["弦", "小", "数"]], "2610": ["病机", "前投清熄厥阴、潜阳敛汗而诸恙依然，脉仍小数。小为阴血不足，数为虚热内扰，此非实火，乃血虚生热之候。阴血亏虚不能涵养，虚热内生，故清熄潜降未能取效。转从血虚生热论治，当以养血滋阴、清退虚热为法，脉小数为辨证眼目。", ["小", "数"]], "2611": ["病机", "脉小弦，小为阴血偏虚，弦为厥阳未平。复方后胃气得降，而厥阳仍未潜降，故有时眩旋。此乃胃降而肝阳未戢，木气尚逆，风阳上扰清窍。小弦之脉示阴血不足、阳未潜藏，以钩麻温胆汤平肝潜阳、化痰和胃，正合病机。", ["小", "弦"]], "2612": ["病机", "脉左弦，左关候肝，弦为肝木气火偏旺。原文谓肝阴不足，气火风阳上僭，以致嘈杂眩旋。阴亏不能涵木，肝阳化风上扰，故眩旋；气火犯胃则嘈杂。左弦正是厥阴风阳僭越之象，治当厥阴，即养肝阴、潜肝阳、清熄风火。", ["弦"]], "2613": ["病机", "脉左弦，主肝胆气火。复方后痰蒙肝胆，心肾失交，气火风阳乘间升扰，左弦之脉示厥阴风阳未靖。痰浊蒙蔽肝胆，水火不能既济，风阳遂乘虚上扰。此非单纯攻伐可解，故切宜怡养，以舒情志、化痰宁神、交通心肾为要。", ["弦"]], "2614": ["病机", "脉小弦，小为阴血不足，弦为厥阳易僭。三诊心肝神魂不藏，故少寐惕怵；阴血亏虚，阳不潜藏，风阳上扰。心藏神、肝藏魂，神魂失守则寐少惊惕。小弦之脉正示阴亏阳浮，治厥阴少阴，即养心肝之阴、潜降浮阳、安神定志。", ["小", "弦"]], "2615": ["病机", "脉左弦，左关属肝，弦为木郁风动之象。原文谓无痰不作眩，由木郁不达、内风暗动所致。木郁则疏泄失常，气滞生痰，风痰上扰清窍而作眩。左弦示肝木郁而风阳内动，以桑麻温胆汤化痰熄风、疏木达郁，标本兼顾。", ["弦"]], "2616": ["病机", "左弦为肝气有余，右小数主痰火内郁。原文谓“肝家气火挟痰浊上升”，劳倦后眩旋屡作、时有遗泄，正是肝火挟痰上扰清窍、下扰精室之象。弦数并见，说明气火内动而非纯虚，故治厥阴少阴以清肝潜阳、化痰固精。", ["弦", "数", "小"]], "2617": ["病机", "脉来弦动不和，弦属肝、动主惊，与“惊怖动心”相应。惊则心阳浮越，肝阳失潜，故眩旋惊惕；阳不潜藏则脘闷纳减。此非外邪，乃心肝之阳失于潜藏，故以半夏泻心汤调中降逆、交通阴阳。", ["弦", "动"]], "2618": ["病机", "脉沉小弦，沉主里、小主虚、弦主风。原文“气虚饮聚，风阳逆举”，气虚则饮停，饮聚则风阳挟之上逆，故肢酸流涎。沉小示正气不足，弦示风阳内动，正虚邪扰并见，故断为“中风之渐”，属病机判断。", ["沉", "小", "弦"]], "2619": ["病机", "脉左弦，左关候肝，弦为肝旺之象。原文“血虚肝旺，阳明被劫”，血虚不能柔肝，肝气横逆犯胃，故脘满辄胀、甚则作痛。弦脉在此示肝木偏亢、劫夺阳明，故治当肝胃同调，属病机分析。", ["弦"]], "2620": ["病机", "脉濡弦，濡主湿、弦主肝。原文“中阳不足，肠为之苦鸣。湿阻气滞”，中阳不振则湿停，湿阻气滞则脘满嗳气；弦为肝木乘脾之象。濡弦并见，示湿阻与肝郁并存，故治肝胃以运中化湿、疏木和胃。", ["濡", "弦"]], "2621": ["病机", "左小数、右弦，左关小数主肝郁化热，右关弦主肝胃乘扰。原文“感寒食滞，肝胃乘扰”，寒食滞于中，肝胃之气失和，故腹痛呕吐、舌糙。小数示郁热，弦示气逆，故法当疏和，属病机与治法相应之分析。", ["小", "数", "弦"]], "2622": ["病机", "脉小弦，小主阳虚、弦主肝木。原文“胃脘当心而痛，痛及少腹，肢厥汗多出”，胃阳不足则寒凝气滞，肝木乘之则痛引少腹；肢厥汗多示阳衰不达。小弦并见，示虚寒与肝郁相兼，故法当温运，属病机判断。", ["小", "弦"]], "2623": ["病机", "脉左弦，左关候肝，弦为肝木上扰之象。原文“阳虚胃寒，肝木上扰”，阳虚胃寒则食运迟，肝木乘虚上逆则泛呕辄痛。弦脉在此示肝气偏亢而非实热，故防成关格，属病机与预后并见之分析。", ["弦"]], "2624": ["主病", "脉左弦，弦为肝脉，主气机郁滞、经脉拘急。胃脘当心而痛、痛甚肢厥，乃肝气犯胃、气滞血瘀，阳气不达四肢所致。左脉候肝，弦象独见于左，正合肝郁气滞、木克土之病机，故以仲景法疏肝和胃、通阳止痛。", ["弦"]], "2625": ["病机", "脉弦小数，弦主气滞，小为湿阻脉道，数为郁而化热。湿阻气滞、健运失司，故腹痛喜按；湿性黏滞，气机不畅，郁久微有热象，脉见小数。治以辛通，辛能散湿行气，通阳化滞，使湿去气畅则痛止。", ["弦", "小", "数"]], "2626": ["病机", "疟母聚于左腹，气失疏泄，输运无权，得食易滞而胃脘辄痛。脉弦小数，弦主气滞，小为阴血不足，数为阳亢有热；舌黄腻尖绛，湿浊内蕴而心营有热。合参乃阴虚兼阳亢、气滞湿阻之候，故治先疏和，调气机以缓其标。", ["弦", "小", "数"]], "2627": ["兼症", "脉右弦数，右脉候脾胃，弦主气滞，数主热。形寒甚而胃痛未已，脘满辄嗳，纳食渐增，舌仍黄腻，乃寒热错杂、气滞湿阻化热之象。弦数见于右关，示中焦气机不畅而郁热未清，故再以疏清互施，疏肝理气兼清郁热。", ["弦", "数"]], "2628": ["病机", "脉濡弦，濡主湿滞，弦主气郁。气滞血郁，络道失宣，故左胁抽疼。左胁为肝络所布，气郁血滞则络脉不和而抽痛；濡脉示湿邪内蕴，弦脉示肝气不舒。湿阻气郁、血行不畅，治以通络调气，使气行血畅、络道宣通则痛止。", ["濡", "弦"]], "2629": ["主病", "脉左弦，左脉候肝，弦主气滞。湿阻气滞，腹痛辄嗳，舌黄糙，足跗浮肿，湿注于下。肝气不疏则腹痛嗳气，湿邪下注则足跗浮肿。弦脉独见于左，正示肝郁气滞为病之本，湿浊为病之标，故治当疏渗互施，疏肝理气兼渗利湿邪。", ["弦"]], "2630": ["病机", "脉濡弦，濡主湿邪黏滞，弦主肝气郁结。湿阻中焦，肝脾不运，故脘痛腹胀、面目俱黄。湿困脾土则运化失司，肝气郁滞则疏泄不利，湿郁化热熏蒸则发黄。濡弦并见，示湿阻与气滞并存，肝脾同病，法当疏运，疏肝运脾以化湿浊。", ["濡", "弦"]], "2631": ["预后", "脉濡弦，濡主湿浊壅盛，弦主肝气郁滞。湿阻中焦，肝脾疏运失司，腹膨且胀，乃湿浊内停、气机壅塞之候。濡弦之脉见于肿胀，示湿邪深重而肝郁不疏，脾运难复，故原文谓「肿胀是忧」，提示病势缠绵、预后堪虑，当重视疏运化湿。", ["濡", "弦"]], "2632": ["病机", "脉濡主湿邪内蕴，小示气血不足，弦为气滞肝郁之象。原文“湿阻于中，气滞于下”正合濡小弦之脉：湿阻中焦则脉濡，气滞于下则脉弦，腹胀跗肿乃湿浊下注、气机不畅所致。此脉说明湿阻气滞为病机关键，故治以疏渗。", ["濡", "小", "弦"]], "2633": ["病机", "濡脉主湿，弦脉主风主痛，亦主气机郁滞。原文“风湿相抟”点明风湿合邪，面浮跗肿为风湿外袭、水湿泛溢之症。脉濡弦正是风湿相搏、气机不利之反映，故曰“肿胀是忧”，提示病机为风湿困阻、水气不化。", ["濡", "弦"]], "2634": ["病机", "脉濡为湿浊内盛，弦为气滞血瘀、肝失疏泄。原文“血阻气滞，腹膨如鼓”及“阴阳两络俱伤，血从上下溢出”，说明病机由气滞血瘀致络伤血溢，腹笥消而复大。濡弦脉反映湿瘀互结、肝脾两伤，故从肿胀治以疏渗。", ["濡", "弦"]], "2635": ["病机", "濡脉主湿阻，弦脉主肝郁气滞。原文“湿阻中焦，肝脾疏运失司”，致得食辄胀、肢节酸楚。脉濡弦正是湿困太阴、肝木乘脾之象，说明病机为湿阻气滞、肝脾不调，故治当太阴阳明，健脾化湿、疏肝理气。", ["濡", "弦"]], "2636": ["病机", "脉小为气血不足，弦为肝郁气滞。原文“肿胀势减而少腹䐜胀，肝脾疏运失司”，说明肿胀虽减，但肝脾疏运未复，气机仍滞。小弦脉反映正虚邪恋、气滞未解，病机重点在肝脾不调，故再以疏运为治。", ["小", "弦"]], "2637": ["病机", "脉小主正虚，弦主气滞水停。原文“湿著肝脾，疏运失职，足跗浮肿，渐入少阴”，说明湿邪困阻肝脾，渐及肾阳。小弦脉示正气渐虚而水湿未化，病机为肝脾不调、水湿下注，故仍宗原议疏渗，兼顾少阴。", ["小", "弦"]], "2638": ["病机", "濡脉主湿，弦脉主肝郁。原文“肝失疏泄，脾失运行，跗肿腹胀”，说明肝郁气滞、脾虚湿阻，水湿泛溢肌肤。脉濡弦正是湿阻气滞、肝脾同病之象，病机为厥阴太阴同病，故治当两经兼顾，疏肝健脾化湿。", ["濡", "弦"]], "2639": ["病机", "濡主湿浊内阻，弦主肝郁气滞。原文“湿阻中焦，肝脾疏运失司，腹胀跗肿”，脉濡弦正合湿困气滞之机。此脉提示湿浊未化、肝脾不调，若不及时疏渗，恐成肿胀，故曰“防成肿胀”，强调病机为湿阻气滞、肝脾失运。", ["濡", "弦"]], "2640": ["病机", "脉濡弦，濡主湿邪困阻，弦主肝气不疏。原文述投五皮饮后肿势稍退而腹胀依然，说明水湿虽减而肝脾不调、气机壅滞未解，故脉仍见濡弦。此脉象提示湿阻气滞为当前主要病机，腹胀持续即其相应症候，故仍宗原议继续化湿调气。", ["濡", "弦"]], "2641": ["病机", "脉濡弦，濡为湿盛，弦为肝旺。原文明言湿阻中焦、肝脾失运，得食辄胀、跗肿便溏，皆湿困脾土、肝木乘之之象。脉濡弦正合湿阻气滞之机，脾运不健则食后胀甚，水湿下注则跗肿便溏。防成中满，即虑湿浊久羁、气滞日甚而致腹大胀满。", ["濡", "弦"]], "2642": ["病机", "脉濡小弦，濡主湿，小为正气不足，弦为肝气不疏。原文谓肿势渐消而肝脾疏运依然失职，得食辄胀，是湿邪未净、脾气尚弱、肝木偏亢。脉濡小弦恰示湿阻气滞兼脾虚之机，故曰切宜调养，不可峻攻，当以缓调肝脾、化湿理气为要。", ["濡", "小", "弦"]], "2643": ["病机", "脉濡弦，濡主湿浊内蕴，弦主肝气郁滞。原文述湿阻气滞而腹膨如鼓，是水湿与气滞交结于中焦，肝脾疏运失司，气机壅塞日甚。脉见濡弦，正合湿阻气滞之病机，腹膨如鼓即其主症。恐成中满，乃虑气滞湿凝日久，腹胀难消而成臌胀之变。", ["濡", "弦"]], "2644": ["病机", "脉濡弦，濡为湿困，弦为肝郁。原文述湿阻中焦、肝脾疏运失司，跗肿腹胀、色㿠形寒，是湿浊内停、阳气不布、肝脾不调之候。脉濡弦正应湿阻气滞之机，色㿠形寒示湿遏阳气，腰圆脐凸则胀满已甚，故曰调治不易，虑其正虚邪盛、攻补两难。", ["濡", "弦"]], "2645": ["病机", "脉左弦，左关候肝，弦为肝气偏旺、疏泄失职。原文谓肝脾疏运失司而腹膨且胀，是肝木乘脾、气机壅滞所致。脉左弦独显，正示病机重在肝郁不疏，脾运因之不健，气滞于中则腹膨且胀。法当健运，即培土以抑木、理气以消胀之意。", ["弦"]], "2646": ["病机", "脉濡软，濡主湿邪，软为正气不足、脾土虚弱。原文述疟发连枝、身热痞聚、腹膨且胀，是疟邪久羁、湿浊内蕴、脾气受困之候。脉濡软正合湿盛脾弱之机，湿阻气滞则痞聚腹胀。防成单臌，乃虑疟湿久延、脾虚日甚、气滞血瘀而致臌胀。", ["濡", "软"]], "2647": ["病机", "脉沉濡弦，沉主病位在里，濡主湿浊，弦主肝气不疏。原文述疟止而痞聚、腹膨稍软，是疟邪虽止而湿浊未化、肝脾不调、气机壅滞仍在。脉沉濡弦正示湿阻气滞之机深入于里，腹膨稍软为邪有松动之象，故再以疏导法理气化湿、调畅肝脾。", ["沉", "濡", "弦"]], "2648": ["病机", "脉弦数，弦主肝郁，数主有热。本案寒凉伤中，中阳虚馁，肝脾失运，腹胀如鼓，舌光绛，乃阳虚而见阴伤，肝郁化热之象。脉弦数反映肝脾失调、虚中夹热之病机，主腹胀，与舌光绛相应，单胀为忧。", ["弦", "数"]], "2649": ["病机", "脉沉弦，沉主里主水，弦主饮主痛。阳虚饮胜，聚痰湿内留，脾失运行，故腹膨跗肿；腰部酸楚，病在脾肾。沉弦之脉正合水饮内停、阳气不运之机，以仲景法温阳化饮。", ["沉", "弦"]], "2650": ["主病", "脉濡弦，濡主湿，弦主肝主痛。伤于湿者下先受之，足跗浮肿渐及一身，病名风水。濡弦反映湿邪阻遏、肝脾疏运失司之病机，故以开鬼门洁净府法，从肺脾论治。", ["濡", "弦"]], "2651": ["病机", "脉濡弦，濡主湿，弦主肝郁。湿阻中焦，肝脾疏运失司，前投疏运中室，肿势渐消，而脉仍濡弦，说明湿邪未净、肝脾未复，故再以温中利湿，续理中焦。", ["濡", "弦"]], "2652": ["病机", "脉濡弦，濡主湿，弦主肝。三诊湿郁不达，肝脾失运，叠投疏气渗湿，胀势渐消，而脉仍濡弦，示湿郁未彻、肝脾运化未复，故仍宗原议，继续疏运渗湿。", ["濡", "弦"]], "2653": ["主病", "脉濡弦，濡主湿，弦主肝主气滞。湿阻气滞，瘕聚肠鸣，乃湿邪困阻、肝脾气机不畅所致。濡弦之脉正合湿滞气郁之机，恐成中满，故当早治。", ["濡", "弦"]], "2654": ["病机", "脉濡弦，濡主湿，弦主肝郁。湿阻中焦，肝脾失运，腹膨且胀，乃湿郁气滞、脾运不健之候。濡弦脉反映湿邪内阻、肝脾失调之病机，单胀是忧，须防胀满加重。", ["濡", "弦"]], "2655": ["病机", "脉濡弦，濡主湿，弦主肝。河白证乃湿邪为患，输运未复，故脉见濡弦，示湿阻气机、肝脾运化未健。当疏运，即疏肝运脾、化湿利水，以复中焦输运之职。", ["濡", "弦"]], "2656": ["主病", "脉小弦，小为气血不足，弦主肝郁。宿恙肝胃，肝气犯胃，近复湿困太阴，脾失健运，故腹膨如鼓。脉小弦示肝郁脾虚、湿阻气滞，正虚邪实，故难许完善。", ["小", "弦"]], "2657": ["病机", "脉濡弦，濡主湿，弦主肝。湿阻气滞，肝脾失调，脾运不健则脘满辄胀，湿困阳气则神疲力懈。脉象反映湿邪困阻、肝气郁滞之病机，治先疏渗以化湿疏肝。", ["濡", "弦"]], "2658": ["预后", "脉弦滑，弦主肝郁，滑主痰湿。失血后肝气被痰湿所阻，气机不畅，腹膨且胀。脉弦滑示痰湿壅盛、肝气郁滞，防成中满，即臌胀之渐，故当警惕。", ["弦", "滑"]], "2659": ["病机", "右寸关小弦而数，左关尚弦，两尺微数。体肥多湿多痰，嗜酒伤阳，阳虚不能通调水道，湿浊灌塞，脾不运行，故足跗浮肿渐及面部。脉小弦数示脾胃湿浊尚盛，肝家气火多升少降，本虚标实。", ["小", "弦", "数"]], "2660": ["病机", "右寸关小数，左关尚弦。脾弱湿生，湿阻中室，真阳不运，寒气乘之，浊阴凝聚为哕为肿。脉小数示湿郁化热，弦为肝升太过，胃降不及，故热潮起伏，舌苔黄腻，治先和胃平肝。", ["小", "数", "弦"]], "2661": ["主病", "脉濡数，濡主湿，数主热。湿阻中焦，肝脾不运，宿恙臌胀时起时伏，近复湿注膀胱，下部遍肿。脉濡数示湿郁化热、水湿下注，病机复杂，故调治不易。", ["濡", "数"]], "2662": ["预后", "脉仍濡数，濡主湿，数主热。投疏运肝脾后腹部肿胀依然，脘满食减，是湿阻气滞未解。脉仍濡数示湿郁化热持续，臌胀是忧，预后堪虑。", ["濡", "数"]], "2663": ["预后", "脉濡弦，濡主湿，弦主肝。湿阻中焦，肝脾疏运失司，下灼阴络，故腹膨便血。脉濡弦示湿阻肝郁、络伤血溢，蛊胀是忧，即臌胀之虞。", ["濡", "弦"]], "2664": ["病机", "脉弦为肝气郁滞、气机不畅，数为有热，弦数并见，示血阻气滞日久化热，肝脾失运而瘕块攻胀。舌白糙亦为气滞血瘀、津不上承之象。脉症合参，主气滞血瘀、肝脾不调，故防成蛊疾，即虑其积块日大、腹胀难消。", ["弦", "数"]], "2665": ["病机", "脉小弦而滑，小为营阴亏乏、脉道不充，弦主肝郁气逆，滑为痰热内蕴。咳痰如桃胶、眩旋心悸，正是热伤膈络、营阴亏耗而痰热未清之候。脉象反映虚实夹杂：阴亏为本，痰热为标，故先宜治肺，拟千金方清肺化痰。", ["小", "弦", "滑"]], "2666": ["预后", "脉弦滑数，弦主肝火，滑主痰热，数主热盛，三象并见，示痰热内炽、肝火犯肺。咳呛痰稠、气粗身热、舌绛苔剥，皆热灼肺津、阴液渐伤之征。脉象弦滑数而舌苔剥，说明邪热未退而正阴已损，故防入损途，虑其成虚劳之候。", ["弦", "滑", "数"]], "2667": ["预后", "脉弦小数，弦为肝火犯肺、络脉不和，小为阴血已伤、脉道不充，数为热象。咳逆伤络、血从上溢、咳痰腥臭，正是热伤肺络、血溢脉外而兼热毒蕴肺之候。脉小数示阴伤而热未清，故恐成肺痿，虑其肺叶焦损、咳唾脓血日甚。", ["弦", "小", "数"]], "2668": ["预后", "脉右滑数，右寸候肺，滑主痰热，数主热盛，独见于右，示痰热壅聚肺金。肺热叶焦、咳痰臭秽，正是热毒灼肺、腐肉成脓之象。脉滑数而症见臭痰，说明热毒炽盛、肺络受损，故恐成肺痿，虑其肺叶焦枯、咳唾脓血难愈。", ["滑", "数"]], "2669": ["预后", "脉弦，弦为肝木偏旺、气机郁滞，失血之后阴血亏虚，肝失柔养而脉见弦劲。咳呛、肺热叶焦、出痰腥秽，示热伤肺络、阴液耗损。脉弦而不数不滑，说明热势虽存而阴伤为主，肝木乘肺，故防成痿躄，虑其肺热叶焦、筋脉失养而致痿。", ["弦"]], "2670": ["病机", "脉濡弦，濡主湿邪困阻、脉道弛缓，弦主肝气不舒、络脉拘急。风湿相抟，肢节脉络酸楚，神疲力懈，胃钝纳减，正是湿困脾运、肝木不达之候。濡弦并见，示湿邪未化而肝气郁滞，故以仲景法祛风除湿、调和营卫，使湿去络通。", ["濡", "弦"]], "2671": ["病机", "脉小弦，小为年高中阳渐衰、脉道不充，弦为肝木偏旺、气机郁滞。中阳衰则肝木乘之犯胃为脘痛，痰阻络道则络痹。苔根腻中剥，示痰湿内蕴而胃阴已伤。脉小弦正合中虚肝犯、痰阻络痹之机，故先疏理肝胃、佐以和络。", ["小", "弦"]], "2672": ["病机", "脉沉弦，沉主里主水饮，弦主饮主风。体肥多湿多痰，气虚饮胜风胜，痰饮凝聚于里，故脉沉；内风暗动，风饮相搏，故脉弦。偶受感触则语塞神糊，正合痰饮蒙蔽、风动扰神之机，花甲年迈，本虚标实。", ["沉", "弦"]], "2673": ["病机", "便前血病经半载，营阴内耗，大腑燥结，腹踹浮肿，眩晕耳鸣，火升心悸少寐，脉弦舌绛。弦为肝脉，阴亏不能涵木，肝阳化火上扰，故脉弦舌绛；火升心悸少寐、眩晕耳鸣皆阳亢风动之候，治宗柔养以滋潜。", ["弦"]], "2674": ["病机", "复方肠痹腹胀，胃纳尚振，腰酸带淋，心惕耳鸣，脉弦舌淡绛。弦为肝旺乘脾，脾脏伤则运化失司，故腹胀肠痹；腰酸带淋、心惕耳鸣乃肝阳上扰、下元不固之象。舌淡绛示阴血暗耗，嗌非跗肿，病本在脾而涉肝。", ["弦"]], "2675": ["病机", "风湿窜经筋入络，右臂及膝红肿酸疼，脉濡弦，兼有寒热，属流火一类。濡主湿，弦主风主痛，风湿相搏于经络，故脉见濡弦；红肿酸疼、寒热并作，乃风湿化热、流火走注之候，以木防己汤祛风除湿通络。", ["濡", "弦"]], "2676": ["病机", "惊怖动心，心悸目直，脉迟弦。迟为心阳不振、神机迟滞，弦为肝风内动，心肝神魂不藏，故惊悸目直。脉迟弦并见，示心肝同病、神魂失守，防成怔忡，治当安神定志、镇肝宁心。", ["迟", "弦"]], "2677": ["病机", "初诊无痰不作眩，眩旋心悸，脉濡弦。濡主痰湿内蕴，弦主风木上扰，痰湿夹风上蒙清窍则眩旋，扰及心神则心悸。脉濡弦正合痰风为患之机，以桑麻温胆汤化痰熄风，标本兼顾。", ["濡", "弦"]], "2678": ["病机", "操劳过度，营阴受耗，心肝之阳偏亢，以致语言错乱，神识时糊，脉左弦。左脉候心肝，弦为阳亢风动之象；阴亏不能制阳，阳亢扰神，故语言错乱、神识时糊。是怔忡之渐，切须怡养以柔肝潜阳、宁心安神。", ["弦"]], "2679": ["病机", "病后元虚，气无依附，痞聚腹痛，痛甚肢厥，汗出舌糙，脉弦滑数。弦主气结，滑主痰聚，数主热郁；元气虚而气无所附，痰热内结，气机痞塞，故痞聚腹痛、痛甚肢厥。汗出舌糙示津伤热扰，以三甲饮子育阴潜阳、软坚散结。", ["弦", "滑", "数"]], "2680": ["病机", "脉濡主湿、主气虚，弦主气滞、主痛。原文“形寒身热，痞聚腹胀”为寒湿外束、气机内滞之象，濡弦并见，说明寒湿阻遏、气滞不行，故以仲景法温化寒湿、行气消痞。脉与症合，病机在寒湿气滞，非单纯表证。", ["濡", "弦"]], "2681": ["病机", "脉弦小滑，弦为阴虚阳扰、小为阴分不足，滑为湿郁化热。原文“阴虚湿郁化热，热迫大肠”致身热便溏，热伤营卫则盗汗，热迫血上溢则鼻衄。脉象反映阴亏为本、湿热为标，故用清骨散清虚热、化湿郁，脉症相应。", ["弦", "小", "滑"]], "2682": ["预后", "前投清骨散后“热势较减，疟退便溏亦止”，脉由弦小滑转为小数，说明湿热渐化、阴分未复而虚热尚存。小为阴血不足，数为余热未清，脉象示病情向缓但未全愈，故“仍宗原议增删”，守清虚热之法，属预后转归之判断。", ["小", "数"]], "2683": ["病机", "疟久伤阴，阴虚不能制阳，故身热盗汗；脉小为阴血亏少，弦为虚热内扰、肝脾不和。原文“疟久阴虚”点明病本，小弦之脉正合阴亏热扰之机，法当清养，即清虚热、养阴液，使脉象与骨蒸盗汗之症相应。", ["小", "弦"]], "2684": ["病机", "脉小主阴分不足，弦主虚热内扰、气机不畅。原文“阴分不足，骨蒸劳热，盗汗咳呛，痞聚腹痛”，阴亏则骨蒸盗汗，虚火上灼肺金则咳呛，肝脾不和则痞聚腹痛。小弦脉象概括阴亏热扰、气滞之病机，故以清骨散养阴清虚热。", ["小", "弦"]], "2685": ["病机", "右脉候肺胃，脉右数主肺胃有热。原文“阴分不足，肺失清肃，咳呛盗汗，身热纳减”，阴虚生内热，热灼肺金则咳呛，热扰营阴则盗汗，胃热则纳减。右数之脉定位肺胃热盛，故法当清泄肺胃，脉症相合。", ["数"]], "2686": ["预后", "投泻白法后“身热渐退，咳呛亦缓”，脉由右数转为右小数，说明肺胃实热渐减，但阴分未复、余热尚存。小为阴伤，数为余热，脉象示邪退正未全复，故“仍宗原议增删”，继续清泄余热，属预后转归之象。", ["小", "数"]], "2687": ["病机", "右脉候肺，脉右数主肺热。原文“阴虚生热，火烁肺金，咳呛盗汗”，阴虚为本，虚火灼肺则咳呛，热迫营阴则盗汗。右数之脉反映肺金受火烁之病机，故法当清泄肺热，脉象与咳呛盗汗之症相应，示热在肺金。", ["数"]], "2688": ["病机", "脉数主热，此案阴虚生热，热扰于内故脉数；然脾弱便溏，中焦不健，热由阴亏而发，非实热可比。脉数与阴虚骨蒸相应，提示虚热内灼，治以清骨散养阴退热，兼顾脾弱。", ["数"]], "2689": ["病机", "脉小数者，阴亏而热内生也。阴虚骨蒸内热，故脉数；阴分不足，脉道不充，故脉小。痞聚腹胀、鼻衄肢酸皆阴亏热扰、气机壅滞之候，脉小数正合虚热内蒸之机，调治不易。", ["小", "数"]], "2690": ["预后", "投清骨散后寒热止、痞聚渐消，而脉仍小数，说明阴分未复，虚热未尽。脉小数持续，提示阴虚内热之根未拔，故再以毓阴泄热，脉象未复即预后需继续调治之据。", ["小", "数"]], "2691": ["病机", "脉右数，右主气属肺，阴虚里热则右脉数；阴亏于内，卫外不固，故外感易侵。脉数在此示里热未清，与阴虚里热相应，佐玉屏风散固表，清骨散滋阴退热。", ["数"]], "2692": ["病机", "酸疟后阴分延虚，里热盗汗，脉见小数。小为阴血不足，数为热内生，脉小数正合阴虚里热之机。盗汗乃虚热迫津外泄，与脉数相应，治以清骨散养阴清热。", ["小", "数"]], "2693": ["预后", "投清骨散后里热减而未澈，盗汗痞聚仍在，脉仍小数。脉小数示阴分未复、余热未清，故虽热减而脉象未转，预后需仍宗原议增删，继续养阴泄热。", ["小", "数"]], "2694": ["病机", "脉小弦者，小为阴血不足，弦为火旺气逆。阴虚火旺，虚火上炎，故喉疼且肿；脉小弦正合阴亏火旺之机。治太阴阳明，即从肺胃清降虚火、滋养阴液。", ["小", "弦"]], "2695": ["预后", "阴分不足，热自内生，痞聚盗汗，脉见小数。小为阴亏，数为内热，脉小数与阴虚内热之候相应。童痨是忧，提示小儿阴亏成痨，脉象持续小数则预后堪虑，故以清骨散治之。", ["小", "数"]], "2696": ["病机", "脉小数者，小为阴虚不足，数为热象未清。原文谓「里热稍减」而脉仍小数，说明清骨散虽减里热，然阴分未复、余热内伏，故见痞聚腹痛。数脉主热，小脉示正虚，热与食滞互结，气机不畅，治以疏运，正合脉证。", ["小", "数"]], "2697": ["病机", "脉细数为阴虚内热之典型。原文「阴分不足，热自内生」，细主阴血亏少，数主热自内生；又因「饮食不节，物腐生虫」，虫积耗伤气血，腹膨如鼓。细数脉既示阴虚，又示虫热内扰，故断为童痨，属虚中夹实之候。", ["细", "数"]], "2698": ["病机", "脉小弦者，小为阴分不足，弦为气机郁滞。原文「阴虚生热，得食易滞，物腐生虫」，阴虚则脉小，食滞虫积则气机不畅而脉弦。腹膨且胀，正是虚热与虫滞交阻之象，故治以疏化，疏其滞、化其虫，兼顾阴虚之本。", ["小", "弦"]], "2699": ["预后", "脉小数而见「腹膨且胀，筋露脐凸，腹痛泻蛔，身热食滞」，乃阴虚内热、虫积食滞交结之重候。小示正虚，数示热炽，筋露脐凸为疳积危象。原文断「恐成疳瘵」，正因虚热虫滞日久，耗损气血，预后堪忧，故列于预后。", ["小", "数"]], "2700": ["预后", "三诊下蛔不多，腹膨稍减而身热依然，脉仍小数。小为阴分未复，数为内热不退，说明冯氏法虽下虫积，然阴虚生热之本未除，虫热余邪尚恋。原文谓「调治不易」，正因脉象未转、身热不退，提示病深难速愈，属预后判断。", ["小", "数"]], "2701": ["病机", "脉濡弦者，濡主湿，弦主郁。原文「湿郁化热，上熏阳明，鼻塞流涕」，湿郁则脉濡，郁而化热、气机不畅则脉弦。又谓「由阴分不足所致」，阴亏则湿郁更易化热，九窍不和咸推胃病，故从阳明胃治，濡弦正示湿郁化热之机。", ["濡", "弦"]], "2702": ["病机", "脉小弦者，小为阴分不足，弦为虚热内扰、气机不畅。原文「阴分不足，热自内生，失血咳呛，串疬盗汗」，阴虚生热则脉小弦，失血咳呛、盗汗串疬皆阴虚火旺、灼津耗血之症。脉证相合，故切宜怡养，以缓图本。", ["小", "弦"]], "2703": ["病机", "脉右数者，右主气分，数为热象。原文「阴分不足，热自内生，颈项串疬」，阴虚则热自内生，右脉数示热郁气分、结于颈项而成串疬。数脉主热，与阴虚内热、痰火凝结之病机相应，故以咸软坚，针对疬结而设。", ["数"]], "2704": ["病机", "脉弦数者，弦为肝热内郁，数为热盛疾急。痰热病一月，肺郁不宣则肝热不退，热极生风，故日痉厥数次。弦数并见，示热郁风动之势未减，原文谓“疾急变恐厥而不返”，正虑热盛风旋、痉厥不止；久延则热灼津液、痰蒙清窍，防成痫疾。", ["弦", "数"]], "2705": ["病机", "脉濡弦者，濡主湿浊内蕴，弦主肝木偏亢。湿热熏灼，清窍被蒙则耳鸣作胀，湿热困阻中焦则身热胃钝。原文“从九窍不和咸推胃病治”，点明九窍不利根在胃中湿热，濡弦之脉正合湿郁化热、木乘土位之机，故治从胃而不从窍。", ["濡", "弦"]], "2706": ["病机", "脉小数者，小为余邪未净、正气渐耗，数为热毒尚存。瘄后余毒未清，熏灼阳络则身热，胃气未复则胃钝。脉小而不洪大，知毒势已衰；数而不静，知余热未清。原文“治宜清解”，正是针对余毒熏灼阳络之病机，清其余热、解其毒邪。", ["小", "数"]], "2707": ["病机", "脉弦数者，弦主热郁肝肺，数主热盛。时令温痘已露三朝，点粒稀朗为顺，然咳呛鼻衄乃热毒上熏肺窍、迫血妄行。弦数之脉示温毒内蕴、肺胃热盛，故原文“治以清透”，透邪外出、清其内热，使痘毒从表而解，不致内陷。", ["弦", "数"]], "2708": ["病机", "脉弦数者，弦为风温袭于肺胃、气机郁滞，数为温热内盛。风温外袭，肺胃先受，则寒热脘闷、气粗咳逆；舌黄糙为热已入里。弦数并见，示表邪未解而里热已炽，原文“尚防发瘄”，正虑风温之邪郁于肺胃、外透为瘄，故脉见弦数。", ["弦", "数"]], "2709": ["预后", "脉弦数者，弦主热毒郁于肺胃，数主壮热不退。温痘面部繁密、壮热烦躁、舌尖绛苔糙罩垢，皆热毒炽盛之象；微咳神糊、便溏口渴，示毒火内扰。原文谓“得以浆充满，粒点放白，方是邪化之机，否防昏喘”，弦数脉不减则毒陷昏喘，故以此脉察邪化与否。", ["弦", "数"]], "2710": ["病机", "脉右数者，右候肺胃，数为热盛。瘄后毒火尚留肺胃，故右脉独数；毒火上熏则咳呛，灼伤阳络则鼻衄。原文“治以清解”，正对毒火留于肺胃之病机。右数而不弦不洪，知毒火虽留而未至炽张，清解即可使肺胃之热得平。", ["数"]], "2711": ["预后", "脉小数者，小为气血壅滞、正气受困，数为热郁于里。腹痛映及少腹、痛甚拒按、身热畏寒，乃热毒壅结肠腑、气血瘀阻之象。脉小而非洪大，数而不静，示热毒内结而未外张。原文“久痛不已，恐成肠痈”，正虑瘀热腐肉成痈，小数之脉可察其热郁之深。", ["小", "数"]], "2712": ["病机", "脉弦未和，说明少腹痛虽缓而肝气郁滞、经脉不和之病机仍在。弦为肝脉，主气机郁结、疼痛。二诊痛势稍缓而脉仍弦，提示病本未除，故仍宗原议增删，继续疏肝理气。", ["弦"]], "2713": ["病机", "脉右数，右寸主肺，数主热。诸气𪱥郁皆属于肺，咳呛喉疼、呕吐痰涎，为肺气郁而化热、痰热上逆之象。脉右数正说明肺中有热，故从三焦咳状、咳而呕逆论治。", ["数"]], "2714": ["病机", "脉右数，右候肺，数主火。咳呛依然、火升喉疼，为肺胃之火未清；呕逆稍缓是胃气渐降。脉右数说明肺胃热盛，火性上炎，故当治肺胃，清降火热。", ["数"]], "2715": ["病机", "脉右数，右寸候肺，数主热。痰火留肺、肺气𪱥郁，故咳呛气促。脉右数正是痰火内蕴、肺失清肃之征，火与痰搏则气促，治当降气涤痰以清肺火。", ["数"]], "2716": ["病机", "脉右弦数，弦为肝旺，数为火盛。血虚生热，火烁肺金，故形寒身热、咳呛痰稠、舌白糙。右脉弦数说明木火刑金，肝火犯肺，恐热伤血络而见痰红。", ["弦", "数"]], "2717": ["病机", "脉弦小数，弦主肝旺，小为阴血不足，数主火热。胎前产后咳呛，肺元自虚，音嘶面浮，是木火刑金、虚火上炎之候。弦小数正示肝火偏亢而阴血亏虚，故以西昌法养阴清火。", ["弦", "小", "数"]], "2718": ["病机", "脉小数，小为血虚，数主热。体本血虚肝旺，近挟暑风，咳呛身热，是标热引动本虚。脉小数说明阴血不足而暑热内扰，先治其标，清暑透邪以解身热咳呛。", ["小", "数"]], "2719": ["预后", "脉右小数，右候肺，小为血虚，数主虚热。产后寒热咳呛，脉见右小数，是肺阴亏虚、虚热内蒸之象。产后得此，防成蓐劳，故当及早调治，勿使虚损日深。", ["小", "数"]], "2720": ["病机", "脉右数，右寸候肺，数主热。产后咳呛，肺虚火盛，虚火内灼故脉数。此脉主肺阴不足、虚火上炎之病机，症见咳呛，治当养肺阴、清肺火，与产后阴血亏虚、肺失濡润相应。", ["数"]], "2721": ["病机", "脉右数，右寸应肺，数主火。子嗽居经七月，胎火上冲，肺金受灼，气逆咳呛，故脉右数。此脉主胎火犯肺、肺气上逆之病机，症见咳呛气逆，治以宣泄，与妊娠胎火上冲相应。", ["数"]], "2722": ["病机", "脉弦滑数，弦主气滞，滑主痰，数主热。暑风袭肺，肺气郁，饮食不节，痰阻络道，右胁抽痛，发热形寒，舌糙。此脉主痰热阻络、气滞不通之病机，症见胁痛发热，治当通络导痰兼疏气滞。", ["弦", "滑", "数"]], "2723": ["病机", "脉右数，右寸候肺，数主热。血虚生热，痰火蒙肺，音嘶咳逆，故脉右数。此脉主血虚痰火壅肺之病机，虚热与痰火交灼肺金，症见音嘶咳逆，治以清燥救肺，与肺燥津伤相应。", ["数"]], "2724": ["病机", "脉小弦，小主虚，弦主肝。病伤不复，咳呛不已，脉小弦，示久病阴伤、肝木偏亢。此脉主肺阴亏虚、木火刑金之病机，症见咳呛不已，以喻氏法养阴清燥，与虚损渐成相应。", ["小", "弦"]], "2725": ["病机", "脉右数，右寸候肺，数主热。卫阳薄弱，外感易侵，身热咳呛，故脉右数。此脉主卫阳不固、外邪犯肺之病机，症见身热咳呛，以玉屏风散固表，与表虚易感相应。", ["数"]], "2726": ["病机", "脉左弦，左关候肝，弦主肝旺。木火刑金，气粗咳逆，痰出薄白，脉左弦。此脉主肝木偏旺、上刑肺金之病机，症见气粗咳逆，以平木清金，与肝火犯肺相应。", ["弦"]], "2727": ["预后", "脉小弦，小主阴虚，弦主木旺。肺阴延虚，木火偏旺，入夜身热尤甚，不耐炎暑蒸逼，脉小弦，示阴亏火旺。此脉主痨损之渐，预后堪虑，与肺痨阴虚火旺、入夜热甚相应。", ["小", "弦"]], "2728": ["病机", "脉右数，右主气分，数主热。失血后阴亏，里热内炽，故脉数；热迫血络则失血，热灼肺金则咳呛；热盛于里而阳不外达，故形寒；热扰冲任则月事愆期，时觉腹痛。治先和络清金，正合清泄里热、和血宁络之法。", ["数"]], "2729": ["病机", "脉右数，右候气分，数主热。前案失血已止而咳呛未已，形寒时作，癸停三月，脉仍数，似属孕象。盖孕后血聚养胎，阳气偏旺，亦可见数脉；然余热未清亦可致数。原文以紫苏饮姑试，正是辨孕与辨热之两难，故曰似属。", ["数"]], "2730": ["病机", "脉右小滑而数，小为阴血不足，滑为痰湿内蕴，数为热邪炽盛。临产遭感，热甚即产，产后热势不退，兼咳呛脘满、腹胀便结口渴、舌绛苔剥，显系产后阴伤而邪热未清，痰热内阻，故亟以清魂之属清透邪热、养阴宁神。", ["小", "滑", "数"]], "2731": ["病机", "脉小数，小为阴血亏虚，数为余热未清。产后感邪渐化，然余热未澈，故脉仍数；腰部酸痛乃肾阴不足、络脉失养；饮食式微为脾胃未复。脉小示正虚，数示邪恋，故再以疏泄，清余热而调气机。", ["小", "数"]], "2732": ["病机", "脉弦而数，弦主邪郁气分、肝胃不和，数主热。肺胃吸受温邪，化热酿痰，故咳呛头疼；邪郁气分，气机不畅则脘闷肢酸；舌糙根腻为湿浊内蕴。脉弦数正合邪郁化热之机，故以银翘散辛凉透表、清热解毒。", ["弦", "数"]], "2733": ["病机", "脉沉弦，沉主里、主水饮，弦主饮邪内停、气机不利。气虚饮胜，水饮上逆犯肺，故哮嗽气促、痰稠；饮郁化热则身热。脉沉弦正是饮停于里、气机被遏之象，故以《金匮》方温化水饮、降气平喘。", ["沉", "弦"]], "2734": ["病机", "脉弦而滑，弦主邪郁气分，滑主痰热内蕴。春温乘劳倦而发，化热酿痰，邪郁气分，故白㾦层出、咳呛痰稠、汗多气促；便难食懈、舌剥尖绛为阴津已伤。脉弦滑示痰热未清而正已虚，故曰正虚邪恋，治以甘凉承津、清养。", ["弦", "滑"]], "2735": ["病机", "脉弦滑数，弦主邪郁气分，滑主湿痰内蕴，数主热。湿温胎气，邪在气分，湿热交蒸，故寒热如疟、㾦点微露、胸脘略爽、汗出颇多；舌糙黄腻罩灰为湿浊未化。脉弦滑数示湿热尚盛，胎气内动，故曰尚在险途。", ["弦", "滑", "数"]], "2736": ["病机", "春温袭肺，化热酿痰，痰热壅阻肺络，故脉右弦滑。弦主痰饮气逆，滑主痰热内盛，右部候肺，与头疼形寒、身热咳呛、舌黄糙相应，示邪在肺卫气分而痰热已酿，故以宣豁为治。", ["弦", "滑"]], "2737": ["病机", "秋温失表，邪郁两旬，病起天癸适至，邪入血室，舌干绛苔少，脉细而沉。细为阴血亏耗，沉为邪郁于里，正虚邪陷，故汗出滂沱、肢厥烦渴、神识昏迷、红疹隐约，虚弱之体厥脱堪虞，脉示正不胜邪之危候。", ["细", "沉"]], "2738": ["预后", "红疹隐而未露，厥潮起伏无常，汗出滂沱，脉沉虚细。沉为邪陷于里，虚细为气血阴阳俱亏，正气不能托邪外达，故疹隐不透而厥汗交作，脱象已萌，脉无神韵，故断难图万一，属危重预后。", ["沉", "虚", "细"]], "2739": ["预后", "投桂枝白虎合龙、蛎、复脉后四肢得温、厥潮已止、自汗未至，脉仍虚细，重按稍有神韵，左关微弦。虚细为气血未复，重按有神示胃气渐回，左关微弦为肝木未和，故虽逾险岭而未入坦途，脉示正复而余邪未清。", ["虚", "细", "弦"]], "2740": ["病机", "劳倦阳弛，秋温乘袭，痰热壅于肺胃，故脉右滑大。滑主痰热，大主邪盛，右部候肺胃，与咳呛痰稠、气促脘闷、少腹䐜胀、便不通、舌黄腻相应，高年正虚邪实，故称逆象，法当宣肺涤痰佐和肝胃。", ["滑", "大"]], "2741": ["预后", "高年右脉滑大为逆，滑大示肺胃痰热依然蒙蔽，与轰热懊𢙐、便溏不爽、舌光苔浮相应。痰热内壅而正气已伤，舌光为阴伤之兆，故有昏喘之虞，脉象未减即示邪热未清、预后可虑。", ["滑", "大"]], "2742": ["病机", "痰阻络道，咳痰抽疼，身热烦渴，便通且溏，脉弦数，舌黄糙。弦主痰阻气滞、络道不通，数主热盛，弦数相合示痰热郁阻络脉，与咳痰抽疼、身热烦渴相应，故再以清解为治。", ["弦", "数"]], "2743": ["预后", "冬温痰热上蒙肺胃，宿饮泛滥，咳痰气促，脉滑数。滑主痰饮壅盛，数主热邪内炽，痰热交蒸上逆，肺胃失降，故防昏喘。脉滑数示邪势方张，痰热蒙蔽清窍之危可虑。", ["滑", "数"]], "2744": ["病机", "脉弦滑数，弦主肝郁，滑主湿痰，数主热。伏暑旬日，邪从膜原外腾为疟，转出气分为白㾦，壮热多汗，脘闷气粗，舌灰，显系暑湿痰热壅阻气分，肝胆郁热。脉象与症相符，故主病机为暑湿痰热内蕴，气分邪盛。", ["弦", "滑", "数"]], "2745": ["病机", "脉细而软，细主阴血不足，软主正气虚弱。体素肝胃不和，劳倦感寒，挟暑湿，致脘痛呕吐，白㾦微露，瞀闷神疲，额汗烦渴，舌黄糙。脉细软示正虚邪恋，虚弱之体，汗脱堪虞，故主病机为正气虚馁，邪气留恋。", ["细", "软"]], "2746": ["病机", "脉右小数，小主正虚，数主邪热。红白㾦沛露，潮热起伏，呕逆频仍，脘闷神倦，口渴躁烦，舌糙罩灰。脉右小数反映邪未尽澈而正气先虚，肝胃不和，故论治以肝胃立法，主病机为邪恋正虚，肝胃失调。", ["小", "数"]], "2747": ["病机", "脉小弦而数，小主正虚，弦主肝郁，数主热。红㾦渐隐，白㾦透露，暑湿由气分外泄，潮热起伏，汗出不多，呕恶，舌绛灰色已退。脉小弦数示肝胃通降失调，余邪未清，故治以甘凉佐芳香，主病机为肝胃不和，暑湿余邪未净。", ["小", "弦", "数"]], "2748": ["病机", "脉弦滑数，弦主肝风，滑主痰湿，数主热。素体虚，感秋温引动伏暑，红白㾦遍体，厥阳风木升扰，热迫便溏，呕恶，潮热汗出，舌黄腻尖绛，腹痛。脉弦滑数示痰热内盛，肝风欲动，有痉厥之险，主病机为痰热动风，瘀凝气滞。", ["弦", "滑", "数"]], "2749": ["预后", "脉小数，小主正虚，数主邪热。便泻已止，腹痛依然，红白㾦沛露胸项连及四肢，潮热起伏，汗出滂沱，舌黄腻尖绛。脉小数而症见汗多㾦露，正虚邪盛，势颇凶险，故主预后不良，示邪热未清而正气已伤。", ["小", "数"]], "2750": ["病机", "脉右小数，左关微弦，小主正虚，数主热，弦主肝郁。伏暑逆入血室，潮热汗出，㾦点微露，彻夜不寐，惊惕抽掣，烦渴，神识乍清乍糊，舌黄腻罩垢。体肥多湿多痰，湿重于热，易化燥伤津，有液涸风动昏愦之变，主病机为湿遏热伏，肝风内动。", ["小", "数", "弦"]], "2751": ["病机", "脉右滑数，滑主痰湿，数主热。风寒外袭，喉痛，颈项两臂风痧沛露，热甚有汗，不咳呛，舌尖起刺。脉右滑数示风热挟痰湿壅于气分，天癸适至，血室空虚，尚防邪入血室，主病机为风热痰湿外袭，有内陷血室之虞。", ["滑", "数"]], "2752": ["病机", "脉濡弦，濡主湿邪内伏，弦主疟邪郁于少阳。湿伏三阴，发为痎疟，故见头疼泛恶、肢酸腰痛。濡弦并见，说明湿邪未化，络脉被阻，法当搜剔络邪，以透达伏湿。", ["濡", "弦"]], "2753": ["病机", "脉弦数，弦为疟邪留于少阳，数为热象。疟发不畅，邪留不澈，潮热起伏，汗出不衰，说明邪热内郁，未能外透。弦数并见，主邪在少阳阳明，治以清透，使邪从外解。", ["弦", "数"]], "2754": ["病机", "脉弦数，弦主肝胆，数主热。疟发不畅，湿留胆胃，扰动肝邪，脘格泛恶，说明湿浊内阻，胆胃不和，肝邪上逆。弦数之脉，反映少阳阳明同病，故仍以和解少阳阳明为治。", ["弦", "数"]], "2755": ["病机", "脉虚弦，虚为气阴不足，弦为疟邪未净。疟发太多，气阴延虚，眩旋耳鸣，神疲力懈，说明正虚邪恋。高年尚防热象，因虚弦之脉，正虚而邪热未清，须防热势复炽。", ["虚", "弦"]], "2756": ["病机", "脉濡弦，濡主湿浊未化，弦主疟邪余滞。复方疟止，气阴未复，精神委顿，说明邪退而正未复，湿浊尚恋。濡弦之脉，反映余邪未清，正气渐虚，故宜徐图恢复，不可峻补。", ["濡", "弦"]], "2757": ["妇人", "脉弦滑，弦主寒邪外束，滑主妊娠气血壅盛。怀珍足月，偶感寒邪，腰酸腹胀，形寒发热，舌糙，说明外寒引动胎气。弦滑之脉，为妊娠常见，今兼外感，故以紫苏饮解表安胎。", ["弦", "滑"]], "2758": ["病机", "脉弦滑数，弦主外感风寒，滑主食滞内停，数主伏湿化热。外感风寒，内停食滞，引动伏湿，形寒发热，脘格泛恶，舌干绛尖糙，说明表里同病，寒热错杂。弦滑数并见，故以辛散为法。", ["弦", "滑", "数"]], "2759": ["妇人", "脉弦小滑，弦主胎气不宁，小为气血受损，滑为妊娠之象。疟后震伤胎元，腰酸带下，说明疟邪虽退，胎元已伤。弦小滑之脉，反映胎气不安，故防半产，治当固摄胎元。", ["弦", "小", "滑"]], "2760": ["病机", "脉右小弦而数，左关弦象尤甚，乃肝邪上扰、厥阳未平之象。疟后津液受劫，中气不足，故右脉小；弦主肝旺，数主热，合之渴喜热饮、烦躁脘满、潮热起伏，症脉合参病在肝胃，最虑液涸风动。", ["小", "弦", "数"]], "2761": ["病机", "脉濡弦，濡主湿滞，弦主肝旺。疟后余湿未澈，肝木偏旺，故右胁抽痛、形寒脘满。湿阻气机则濡，肝郁不舒则弦，治以辛酸，辛以散湿，酸以柔肝。", ["濡", "弦"]], "2762": ["病机", "脉弦数，弦主少阳肝胆，数主热。湿著胆胃，邪从膜原外腾，寒热继于间疟，故脉见弦数。治以和解，即和少阳、清胆胃，使膜原之邪得解。", ["弦", "数"]], "2763": ["病机", "脉细弦数搏指，细为营气不充，弦为肝邪内动，数为热。产后月余，八脉、太冲亦惫，恶露久停，痎疟十发无汗，寒热并甚，肢节酸楚，乃三阴营气亏虚兼疟邪内迫，故拟充三阴之营气兼固八脉。", ["细", "弦", "数"]], "2764": ["病机", "脉弦数，弦主肝，数主热。胎前寒热炽伤胎元，产后寒热复来，咳呛便泄，瘀凝少腹攻痛，汗多，乃产后营虚、肝热内炽、瘀滞未化之候，势非轻藐。", ["弦", "数"]], "2765": ["病机", "脉小弦，小为营卫不足，弦为肝络不和。疟退后小有寒热，营卫迭偏，泻止瘕散，惟咳呛、少腹抽痛、卧醒轰热，舌腻，乃痰阻络脉、营卫未和，故再以通络导痰佐和营卫。", ["小", "弦"]], "2766": ["病机", "脉弦数，弦主肝热，数主火。劳倦引动伏暑，但热不凉，咳呛少痰，热迫便溏，舌黄腻，乃暑热内蕴、肝火犯肺迫肠之象，法当清解暑热。", ["弦", "数"]], "2767": ["预后", "脉弦滑数，弦主肝热，滑主痰，数主火。热势转剧，白㾦隐约，咳呛痰少，热迫便泻，舌黄垢罩灰，乃痰热内闭、邪有内陷之势，故曰有昏喘之险。", ["弦", "滑", "数"]], "2768": ["病机", "脉濡主湿，为湿热内留之象。原文“舌垢脉濡”并见，舌垢示浊湿未化，脉濡则湿邪困阻、气血运行不畅。寒邪外袭而湿热内留，表里同病，故以栀豉汤清宣郁热。濡脉不主虚而主湿滞，与此案湿热内蕴、气机被遏之机相合。", ["濡"]], "2769": ["预后", "脉沉弦为饮邪内伏、气机郁滞之象。宿饮哮喘，痰饮泛滥，喘促不相接续，吐泻腹痛，肢厥汗出，皆饮邪上逆、阳气不布所致。沉主病在里，弦主饮主痛，脉证相合，而喘促汗出肢厥已露喘脱之兆，故原文断为“喘脱堪虞”，属危重预后。", ["沉", "弦"]], "2770": ["病机", "脉小弦为脾胃受戕、生气未醒之象。食滞不化而消导过度，脾胃受损，便泻腹痛虽止，然脉小示正气不足，弦示土虚木乘、气机未和。高年脾胃本弱，攻伐之后生气难复，故脉见小弦，原文强调“切宜调养”，示病机以脾胃气虚为主。", ["小", "弦"]], "2771": ["病机", "脉弦滑数为痰浊内盛、气逆化热之象。复方泻后便结，浊饮泛滥，气促咳痰不爽，舌白腻，皆痰饮壅阻肺胃所致。弦主饮癖气逆，滑主痰浊，数示郁而化热。脉证合参，病机为痰浊上逆、肺胃气壅，故治以降气涤痰，使浊饮下行则气促可平。", ["弦", "滑", "数"]], "2772": ["预后", "脉虚弦为产后气血已伤而木邪未平之象。前投理中合生化、失笑，恶露通、呕逆止，而腹痛便泻依然，脉虚弦，虚示正气不足，弦示肝木乘脾、气机郁滞。产后本虚，又兼木旺克土，局势非轻，原文直言“局势非轻”，示正虚邪恋、调治棘手之预后。", ["虚", "弦"]], "2773": ["病机", "脉来弦滑而数，为产后阴伤、痰热内扰之象。泄泻月余，腹痛虽缓而夜寐不安，交阴身热口渴，舌光绛苔剥，示阴液已亏；弦主木旺，滑主痰，数主热。脉证相参，病机为脾虚阴伤、痰热未清，故原文谓“当顾脾胃”，以扶脾养阴为要。", ["弦", "滑", "数"]], "2774": ["病机", "脉弦小数为产后挟感、瘀热内阻之象。初起呕吐，继则身热便溏，恶露少通，少腹攻痛，神疲少寐，舌白腻，皆产后感邪、瘀滞未行所致。弦主痛主瘀，小示正虚，数示邪热。脉证合参，病机为脾虚瘀阻兼感外邪，故以健脾逐瘀为治。", ["弦", "小", "数"]], "2775": ["预后", "脉弦小数见于产后，便泻虽止而形寒身热、脘闷气粗、少腹作痛、恶露少通、舌糙尖绛，示瘀热未清、气机壅滞。弦主痛瘀，小示正虚，数示郁热。产后本虚，又兼瘀热内阻，攻补两难，故原文谓“得之产后，调治不易”，属预后审慎之论。", ["弦", "小", "数"]], "2776": ["病机", "脉小弦者，弦为肝木之象，小为正气不足。土不生金则咳呛，脾虚不运则便溏，寅时肺金主令而尤甚，正合脾肺两虚、木气乘之之机。脉小示脾肺之气亏，弦示肝木偏旺，故治当培土生金、兼以抑木，治脾肺为要。", ["小", "弦"]], "2777": ["兼症", "居经五月而迭感寒邪，腹痛便溏，脉弦滑。弦主肝木气滞，滑主痰湿内蕴，亦见于妊娠之脉。寒邪外袭、肝脾不和，气机郁滞则腹痛，湿浊下趋则便溏。脉弦滑示邪滞与胎气并存，故治以疏和，调畅肝脾而不伤胎。", ["弦", "滑"]], "2778": ["预后", "胎前咳呛，产后未已，木火刑金，又侮脾土，腹痛便溏，脉小弦。小为气血不足，弦为肝木偏亢，木火灼金则咳，木乘土则腹痛便溏。产后气血本虚而肝木不平，脉小弦正示正虚邪恋，故恐成蓐劳，预后堪虑。", ["小", "弦"]], "2779": ["病机", "产后肝脾失运，腹痛便溏，跗肿面浮，脉濡弦。濡主湿、主气虚，弦主肝木乘脾。产后脾运不健，湿浊内停则跗肿面浮、便溏；肝气不疏则腹痛。脉濡弦正合湿滞与肝郁并见之机，故治以疏和，疏肝运脾化湿。", ["濡", "弦"]], "2780": ["兼症", "痢次稍缓而腹痛后重、脘满辄胀、眩旋腰酸，脉濡小弦。濡为湿滞未清，小为脾虚气弱，弦为肝木乘脾。湿浊留恋则后重脘胀，脾虚肝乘则眩旋腰酸。脉濡小弦示正虚湿滞、肝脾不调，故再以疏渗，疏肝渗湿兼顾其虚。", ["濡", "小", "弦"]], "2781": ["预后", "痢下赤白、腹痛后重、身热脱肛、烦渴泛呕、舌干绛起糜点，脉弦小。弦为气滞邪恋，小为正气已伤。痢久脾伤则气陷脱肛，胃阴劫夺则舌绛烦渴起糜。脉弦小示邪未净而正已亏，阴伤气陷并见，故治难速效，预后须慎。", ["弦", "小"]], "2782": ["治法", "痢次渐减而腹痛后重、气陷脱肛、舌剥干绛少津，脉小弦。小为气血亏虚，弦为余邪气滞。痢久中气下陷则脱肛后重，津伤则舌剥干绛。脉小弦示正虚为主、余邪未尽，故再以补中益气之属，升举中气以托邪，正合脉证。", ["小", "弦"]], "2783": ["兼症", "居经六月，腹胀且痛，便积后重，脉弦小滑。弦主肝木气滞，小为正气偏弱，滑主湿积内蕴，亦应妊娠之脉。气滞湿积则腹胀痛、便积后重，胎气与邪滞相争。脉弦小滑示邪滞未甚而胎气可虑，故治以疏和，并防胎坠。", ["弦", "小", "滑"]], "2784": ["病机", "脉濡主湿，弦主肝木乘土、气机壅滞。暑湿热挟食滞蒸伤肠腑气血，故见赤白下痢、腹痛后重；濡弦正合湿滞与肝木疏泄失常之机，治以疏和，即疏肝化湿、调气和血。", ["濡", "弦"]], "2785": ["病机", "复感食滞，赤痢复作，腹痛后重，脉仍濡弦。濡为湿滞未化，弦为肝木犯脾、气机不畅，食滞与湿热互结肠腑，气血受伤，故恐成肠红，示病机缠绵、有伤络下血之虞。", ["濡", "弦"]], "2786": ["病机", "泻止恶露停而脘满嗳酸、得食辄胀，脉濡弦。濡主湿浊内蕴，弦主肝失疏泄，木不疏土则胃失通降，湿阻气滞故胀满嗳酸，防延中满，正言肝胃不和、湿阻气滞之病机。", ["濡", "弦"]], "2787": ["病机", "腹胀渐消而便泻复作、寅卯尤剧，脉小弦。小为正气不足，弦为肝木偏旺，寅卯属木旺之时，木旺克土故泻剧，显系土虚木乘之机，故当培土抑木，以扶脾抑肝为治。", ["小", "弦"]], "2788": ["病机", "脉濡小弦，苔黄腻，腹膨且胀、面浮肢肿。濡主湿阻，小主正虚，弦主肝木乘脾，湿阻中焦、疏运失司，水湿泛溢肌肤，肿胀已成，故言调治极难，示正虚湿盛、肝脾同病之机。", ["濡", "小", "弦"]], "2789": ["病机", "咳呛肢肿、身热气粗而脉濡弦。濡为湿邪留着，弦为肝木偏亢，湿郁犯肺则咳呛气粗，脾失运化、水湿泛溢则肢肿，脾肺同病而肝木乘扰，故当治脾肺，化湿肃肺以调气机。", ["濡", "弦"]], "2790": ["妇人", "居经七月，阳明司胎，脘痛辄胀，脉弦滑。滑为胎孕之常脉，弦为肝邪偏旺、乘扰中焦，木郁气滞故脘痛胀满，属妊娠肝邪乘扰、胎气不和之候，故治以疏和，佐安胎元。", ["弦", "滑"]], "2791": ["病机", "湿著不化，面浮肤肿，脉濡弦。濡主湿邪黏滞，弦主肝木失疏，湿困脾运则水湿不化、泛溢肌肤，肝脾不运而湿著为肿，故当治肝脾，疏肝运脾以化湿消肿。", ["濡", "弦"]], "2792": ["病机", "脉濡数为湿与热并见之象。血不养肝则肝失柔润，肝横犯脾，气机壅滞，故腹胀膨如鼓。濡主湿、主气虚，数主热，湿热内蕴而肝脾不调，水湿停聚，恐成单胀（臌胀）。脉症合参，病机为肝血不足、湿热壅阻、气滞水停。", ["濡", "数"]], "2793": ["病机", "脉弦小数，弦为肝旺，小为阴血不足，数为热炽于里。疏泄肝脾而腹胀依然，说明木郁化火、热灼阴伤，肝脾不和未解。弦小数并见，主厥阴肝经郁热、太阴脾土受克，故再治厥阴、太阴，清肝泄热兼运脾。", ["弦", "小", "数"]], "2794": ["病机", "脉小弦，小为气血不足，弦为木郁气滞。木郁不达则肺金失于肃降，气机壅塞，故肢肿腹胀、咳呛失血。此属肝郁犯肺、气逆血溢之候。从经旨“金郁泄之，木郁达之”，正合脉小弦所主之肝肺气郁病机。", ["小", "弦"]], "2795": ["病机", "脉细数为阴虚内热之典型脉象。年已二七而天癸未至，阴血亏虚，虚热内生，故夜热盗汗；带下白腻为兼湿。细主阴血不足，数主虚火，阴亏火旺、冲任失养，故虑成童痨。脉症相应，病机为阴虚内热、精血亏耗。", ["细", "数"]], "2796": ["病机", "脉小数为阴分不足、虚火内炽。木火刑金，肝火犯肺，肺失清肃，故咳呛气促、时或痰红。小主阴血亏，数主火旺，火灼肺络则痰红，久延则成损怯。脉小数正示阴虚火旺、肺金受灼之病机。", ["小", "数"]], "2797": ["病机", "脉右小数，右寸关候肺脾，小数为阴血枯涸、虚热内扰。癸停载余，血液枯涸，冲任空虚，虚热上灼肺金，故身热咳呛。小主血少，数主虚火，阴亏火旺、肺失濡润，恐成痨损。脉症合参，病机为血枯阴亏、虚火灼肺。", ["小", "数"]], "2798": ["病机", "脉小数仍为阴血不足、虚热未清之象。寒热虽止而月事未通，咳呛有痰，说明阴血未复、虚火灼肺、冲任未充。小主阴亏，数主虚热，热灼肺津则咳痰，血海空虚则经闭。防延入损途，即虑其阴损及阳、成痨。", ["小", "数"]], "2799": ["病机", "脉细虚带软，细主血少，虚主气衰，软主不足。产多伤血、烦劳伤气，气血两耗，营血偏虚，故心悸眩旋、肉𥆧惊惕、形寒轰热、四肢麻木，厥阳时僭。虚软之脉正应气血两亏、阴阳不相维系之虚损末候，故曰非草木所能获效。", ["细", "虚", "软"]], "2800": ["病机", "脉细弦，细为阴血亏虚，弦为肝木亢盛。产后阴血本虚，木火刑金则咳呛，肝木乘脾则腹痛便泄。脉象反映肝郁化火、脾土受侮之病机，故恐延成蓐劳。", ["细", "弦"]], "2801": ["预后", "脉细主阴血不足，产后咳缓便溏、后重腹痛肠鸣、舌剥，皆脾阴两亏之象。脉细与舌剥并见，说明营血虚少、脾运失健，故断为产后蓐劳，调治极难。", ["细"]], "2802": ["病机", "脉小弦，小为营血虚少，弦为肝气偏旺。产后营虚，气无依附，肝气横逆则腹笥臌膨胀，神惫里热。脉象示营虚气滞、肝木失养，久防延成蓐劳。", ["小", "弦"]], "2803": ["病机", "脉细主血虚，小数主内热。居经四月，身热形消，腹痛，脉细而左右小数，是血虚气滞、郁热内生之象，非孕脉之滑数，故难凭孕象。", ["细", "数"]], "2804": ["病机", "脉小数，小为血虚，数为肝旺化热。血虚肝旺，木乘土位，营卫迭偏，致脘痛便溏、跗肿寒热。脉象示血虚肝郁、脾土受克，调治不易。", ["小", "数"]], "2805": ["治法", "脉小数，小为脾虚，数为里热。腹胀痛、便溏后重、纳减胃钝、里热跗肿，皆土虚木乘之候。脉象示肝旺脾弱，故当治扶土抑木法。", ["小", "数"]], "2806": ["病机", "脉来右软，左部小弦而数。右软为脾阳不足，左小弦数为肝阴亏虚、肝火偏亢。血虚癸停，肝旺克脾，便溏肢肿，阳虚自汗，舌光剥，脉象示肝旺脾弱、阴阳两虚。", ["软", "小", "弦", "数"]], "2807": ["预后", "脉象左右上部俱见沉细而数，沉细为阴血亏耗，数为虚热内扰。胃阴日渐败坏，肝家气火升腾无制，太阴输运无权，致一身尽肿。脉象示胃阴败、肝火亢、脾运衰，脱象已萌，难图万一。", ["沉", "细", "数"]], "2808": ["病机", "脉右数，右寸主肺、右关主胃，数则为热。原文点明「热灼肺胃」，热邪内灼，肺失清肃则咳呛，灼伤血络则失血。脉数应热，右部独数说明热在肺胃气分，久延则阴液受耗，故曰「防延入损途」，提示热盛伤阴、虚损将成之病机。", ["数"]], "2809": ["病机", "产后营血亏虚，脉道不充故脉小；阳不潜藏、肝木失养则脉弦；营虚不能充盈脉体故按之软。原文「产后营虚，阳不潜藏」正合小弦而软之象，弦为阳浮不敛，软为营虚不充，虚阳外浮而根本已亏，故「恐成蓐劳」，示产后虚损难复之机。", ["小", "弦", "软"]], "2810": ["病机", "六部俱见细数，细为气血两虚、脉道不充，数为厥阳气火偏旺、内热鼓动。原文「气血两虚，厥阳气火偏旺」正与此合；肝左升太过、肺右降不及，木叩金鸣而咳呛痰红，火扰心神则心悸少寐、自汗盗汗。细数并见，虚中夹火，故症脉合参而定泄金达木、宁神之法。", ["细", "数"]], "2811": ["病机", "脉右滑小数，右部主肺胃，滑为痰湿内蕴，小为营阴不足，数为热象。原文由疟致产后复疟，疟邪留恋、痰热阻肺，故咳呛面浮气促；产后营虚未复，脉体偏小。滑数示痰热未清，小示正虚，正虚邪恋，故「防成蓐劳」，虑其久延成损。", ["滑", "小", "数"]], "2812": ["预后", "脉右数，右寸候肺，数主热。原文「病伤不复，迭感咳呛」，是病后正气未复，又屡感外邪，肺热内蕴故脉数。数脉见于右部，说明肺中火热未清，久延则灼津耗气，故曰「久延防损」，属提示病势趋向、防其成损的预后之论。", ["数"]], "2813": ["病机", "脉弦滑，弦为肝木偏旺、气机郁滞，滑为痰热内蕴。原文产后里热未清，咳呛迄今，形神日渐消瘦，是产后阴伤、木火刑金，痰热阻肺则咳呛，热耗肌肉则消瘦。弦滑并见，示肝旺痰热交阻，久则营阴愈亏，故「恐延成蓐劳」，虑其成虚劳之候。", ["弦", "滑"]], "2814": ["治法", "脉右数，右寸主肺，数主火。原文「失血咳呛，已历三载，肺火盛也」，肺火灼伤血络则失血，火逆于肺则咳呛，脉数正是肺火内盛之应。既明肺火盛之病机，故立「和络清金法」，和络以止失血，清金以泻肺火，脉象直接指导治法确立。", ["数"]], "2815": ["病机", "脉右小数，右寸候肺，小为肺虚阴亏、脉道不充，数为虚火内盛。原文「肺虚火盛，咳呛身热」，虚火灼肺则咳呛，虚热外蒸则身热；曾经失血、天癸延期，皆阴血亏耗之征。小与数并见，示虚中夹火、本虚标热，故「切宜怡养」，以静养复其阴。", ["小", "数"]], "2816": ["病机", "脉芤主失血伤阴，弦主肝郁络滞。失血后阴血亏虚，脉道不充故芤；肝郁化火刑金，络脉不和故弦。咳呛身热脘闷，乃络伤气逆、金不清肃之象，故以和络清金为法。", ["芤", "弦"]], "2817": ["病机", "脉右数，右寸主肺，数主热。阴虚湿郁化热，肺金受灼，故咳呛失血；热扰冲任则月事先期，腰酸带下亦湿热下注之征。舌黄糙为热郁津伤，故治以和络清金兼调八脉。", ["数"]], "2818": ["病机", "脉右数，右寸候肺，数主火。咳呛经久，肺火自旺，痰火尚留，故身热痰红。脉数不减，示火未清，治以清渗降，清肺火、渗痰湿、降气逆。", ["数"]], "2819": ["预后", "脉右滑数，滑主痰，数主热。失血咳呛而形寒发热，痰热内蕴，肺络受损。滑数并见，痰火胶结，耗伤气阴，故断为劳损之基，调治不易。", ["滑", "数"]], "2820": ["病机", "脉弦滑数，弦主木火，滑主痰，数主热。木火刑金烁络，络破血溢，故咳呛痰红；形寒身热，热炽于里。舌尖绛苔糙，皆火盛伤津之象，故用喻氏清燥救肺法。", ["弦", "滑", "数"]], "2821": ["预后", "脉芤弦而数，芤主失血阴伤，弦主木火，数主热炽。投喻氏法后咳呛依然，热炽于里，形瘦气促，舌黄中剥，阴液已亏。脉症合参，似属劳损之基，故切宜怡养。", ["芤", "弦", "数"]], "2822": ["病机", "脉弦数，弦主肝郁，数主热。热灼阴络，血从下溢为便血，瘀衃肛门酸痛；热炽于里，兼咳呛少寐口渴，舌尖绛苔糙，皆营热阴伤之征，故当和阴络以清营热。", ["弦", "数"]], "2823": ["病机", "脉右数，右寸候肺，数主热。复方便血渐止，而咳呛未已，脉仍右数，示肺热未清，余邪留恋。故再以清解，清肺热、解余毒，以竟全功。", ["数"]], "2824": ["病机", "脉濡数，濡主湿、数主热，合为湿火之象。原文言“湿火下趋，热结膀胱，气化窒碍”，湿火蕴结下焦，膀胱气化不利，故脉见濡数。此脉主湿热下注膀胱之病机，与小便不利、淋浊等症相应，治以疏泄厥阴，使湿热从肝经疏达而下。", ["濡", "数"]], "2825": ["病机", "脉小弦，小为血少，弦为肝旺。原文言“经来后期，崩漏尿血，是奇经冲任少贮”，冲任血海空虚，肝失濡养而偏旺，故脉小弦。此脉主血虚肝旺、冲任不充之病机，与经期延后、崩漏尿血相应，切宜调养以复冲任之贮。", ["小", "弦"]], "2826": ["病机", "脉小弦，小示阴血不足，弦示肝经郁热。原文言“小溲涓滴，兼有尿血”，又谓“热迫膀胱，冲海受灼”，热灼膀胱血络则尿血，气化受阻则涓滴，冲任受灼故脉小弦。此脉主热迫膀胱、冲海受灼之病机，与尿血、小便艰涩相应。", ["小", "弦"]], "2827": ["主病", "脉弦数，弦主肝郁气滞，数主热。怀孕四月，二便倏闭，乃胎气壅遏、肝郁化热，下焦气化不通所致。弦数之脉反映气滞热结之病机，与妊娠期二便闭塞之症相应。原文以葵子汤主之，取滑利通窍、清热行滞之意，脉象正是其辨证依据。", ["弦", "数"]], "2828": ["病机", "脉右弦，右关候肝脾。原文言“血液不足，肝木偏旺”，血虚不能濡养肝木，肝气郁而不达，气失疏泄，故乳旁结核不红肿酸疼，脉见右弦。此脉主肝郁不达、气失疏泄之病机，与乳旁结核而无红肿之症相应，故强调怡养为先。", ["弦"]], "2829": ["病机", "脉左弦，左关候肝。原文言“血不养肝，肝旺辄胀”，血虚肝失所养则肝气偏旺，横逆犯胃，故脘痛胀及肩背，甚则呕吐。左弦之脉正示肝旺气逆之病机，与脘胀、肩背痛、呕吐等症相应，治以辛酸，辛以散肝、酸以柔肝。", ["弦"]], "2830": ["病机", "脉左弦右部小滑，左弦示肝木偏旺，右小滑示中阳不足、痰湿内停。原文言“中阳不足，肝木犯胃”，肝气犯胃则晨起呕吐、得食尤甚，甚则脘痛彻背。此脉主肝胃不和、中虚痰滞之病机，与呕吐、脘痛彻背相应，病在肝胃，切宜怡养。", ["弦", "滑"]], "2831": ["病机", "脉小弦，小为血虚，弦为肝旺。原文言“血虚肝旺，中气虚馁”，血虚则肝失柔养而气旺，中气虚则运化无力，气滞血瘀而成瘕，攻冲脘痛、腹胀气滞，故脉小弦。此脉主血虚肝旺、中虚气滞之病机，与瘕攻脘痛、腹胀相应，治以辛酸仿仲景法。", ["小", "弦"]], "2832": ["病机", "脉细弦，细为血虚，弦为肝气偏旺。原文寒热互滞引动肝气，肝气横逆则脘痛肢厥；鼻衄便结乃肝郁化火、血热上溢、肠燥失润。脉象反映寒热错杂中肝气郁滞、阴血不足之病机，故治先散寒疏气，痛定则吉。", ["细", "弦"]], "2833": ["病机", "脉左弦，左关候肝，弦为肝木亢盛之象。原文中阳不足，肝木犯胃，脘痛呕酸腹胀，皆肝气横逆、胃失和降所致。血虚则肝失柔养，故弦而不柔。此脉主肝胃不和、木旺克土之病机，以仲景辛酸法柔肝和胃。", ["弦"]], "2834": ["病机", "脉左弦，左关属肝，弦主肝郁气滞。胃脘痛甚则肢厥汗出，乃肝气犯胃、气机闭阻、阳气不达；痛伤胆汁、面目俱黄，为肝郁胆溢；便闭咳逆亦气逆所致。脉弦揭示肝郁气滞、胆胃失和之病机，故治以苦辛通降。", ["弦"]], "2835": ["病机", "脉小弦，小为血虚不足，弦为肝木偏旺。原文血不养肝，肝木犯胃，脘痛彻背、肢节酸楚，皆血虚肝失柔养、肝气横逆、筋脉失濡之象。脉小弦正合血虚肝郁之病机，故以仲景法养血柔肝和胃。", ["小", "弦"]], "2836": ["病机", "脉左弦，左关候肝，弦为肝气偏亢。原文脘痛缓而未止，血不荣筋，肩背腰疼，乃肝血不足、筋脉失养，肝气仍郁。脉弦示肝郁未解，血虚筋急。此脉主血不养肝、肝气横逆之病机，故治肝首先养血，血充则筋柔痛止。", ["弦"]], "2837": ["病机", "脉濡弦，濡为湿滞中阳不足，弦为肝木偏旺。原文中阳不足，肝胃失调，耳鸣眩旋，乃清阳不升、肝风内动、湿浊上蒙所致。濡弦并见，示中虚湿困与肝木亢逆并存之病机，故治厥阴阳明，温中柔肝并调。", ["濡", "弦"]], "2838": ["预后", "脉细类伏，细为血少，伏为脉气沉匿不显。新产血去太多，虚厥眩晕、不省人事，乃血脱气陷、阳气不能上承。脉细类伏示气血衰微、脉道不充，故防脱。此脉主血脱气陷之危候，预后当警惕虚脱。", ["细", "伏"]], "2839": ["病机", "脉左弦，左关候肝，弦主肝阳偏亢。原文惊怖动心，心悸眩旋，得食则胀，脘痛彻背，乃心肝阳亢、气机逆乱、木旺克土。脉弦示肝阳亢逆之病机，故谓心肝之阳偏亢，切宜怡养以平其亢。", ["弦"]], "2840": ["病机", "脉右弦提示肝气偏亢，结合血不养肝、气火风阳上僭，可知阴血亏虚致肝阳化风上扰，故见眩旋心悸；脘满辄胀为肝气犯胃、气机不畅；舌糙为阴伤之征。弦脉主肝病、痛证、气逆，此处右弦更偏气分，说明病机重点在肝风上僭与中焦气滞。", ["弦"]], "2841": ["预后", "脉虚弦而数，虚为正气不足，弦主痛与积，数示邪热内扰。少腹积聚攻痛、痛甚肢厥汗出，乃肾积奔豚，气上冲逆，阴阳气不相顺接；舌干绛中剥为阴液耗伤。脉症合参，正虚邪实，故断为肾积难许完善，预后堪忧。", ["虚", "弦", "数"]], "2842": ["病机", "脉小弦，小为血少，弦主气滞积痛。从肾积奔豚治后攻痛稍缓，但少腹辄胀、大便不通，说明积块未消，气机仍阻，肝郁乘脾，传导失职。脉小弦反映正虚邪恋、气滞未解，故仍宗原议增删，继续攻补兼施。", ["小", "弦"]], "2843": ["病机", "脉濡弦，濡主湿、主血虚，弦主风、主肝。血不荣筋则筋脉失养，风淫热郁则四肢酸楚。濡弦相合，示血虚为本，风湿热郁为标，筋脉痹阻。治先养血舒筋，再商补调，正是标本兼顾之法。", ["濡", "弦"]], "2844": ["病机", "脉小弦，小为血虚，弦为肝郁。血液不足则周行失度，冲任失养，故月事愆期、经来悉紫。紫为寒凝血瘀之象，从后期属寒例治，说明此脉小弦主血虚肝郁兼寒，冲任虚寒致经行后期。", ["小", "弦"]], "2845": ["病机", "脉小弦，小主血虚，弦主肝旺。血虚肝旺则冲任失调，月事先后无序。冲任隶于肝肾，肝旺则疏泄无度，血虚则冲任不盈，故经期紊乱。治当治奇经，即调补冲任，以平肝养血为要。", ["小", "弦"]], "2846": ["病机", "脉濡弦，濡主湿滞，弦主气郁。肝肾下虚则经迟，湿阻气滞则带多、脘痛辄胀。濡弦相合，示血虚湿阻、肝郁气滞，本虚标实。法当养血润肝兼疏气滞，标本同治。", ["濡", "弦"]], "2847": ["病机", "脉小弦，小为血虚，弦为木郁。木郁不达则肺金失肃，故咳呛身热；肝郁乘脾则腹痛；肾虚则腰酸。脉小弦反映肝郁血虚、肺失宣降，故用金郁泄之、木郁达之治法，以疏肝宣肺。", ["小", "弦"]], "2848": ["病机", "脉小为血虚不足，弦为气机郁滞、瘕攻作胀，数为热自内生之象。血虚不能濡养，虚热内扰，故见交阴寒热；瘕块攻冲腹胀，亦由血虚气滞、奇经失养所致。脉小弦而数正合血虚生热、瘕攻之病机，故治当从奇经入手。", ["小", "弦", "数"]], "2849": ["病机", "脉迟为血虚寒滞、冲任失调，弦为气机不畅、腰栙腹痛之征。血液不足则经行迟滞，月事两三月一至；冲任失养、气血郁阻，故腰栙腹痛。迟弦并见，示血虚而兼气滞寒凝，非单纯热象，故当治奇经以调冲任。", ["迟", "弦"]], "2850": ["病机", "脉小为血虚，数为热自内生。血虚生热，临期腹痛、腰酸带下，皆由血海不足、虚热扰动、带脉失约所致。小数之脉正合血虚内热之机，故当治奇经，养血调冲以清虚热。", ["小", "数"]], "2851": ["病机", "脉濡为阴血不足、湿滞不化，弦为气机郁滞。养阴润肝、通经之后月事仍不至而不腹痛，脉濡弦，说明非孕象，乃血虚气滞、经隧不通。濡弦并见，正合血虚兼气滞之病机，故断为难凭孕象。", ["濡", "弦"]], "2852": ["病机", "脉小为血虚，弦为气机不畅。半产后冲带少贮，血海空虚，形寒身热由营卫失和、虚而不足所致。小弦之脉示血虚气滞、八脉失养，故当治八脉以调冲带。", ["小", "弦"]], "2853": ["病机", "脉小为血液不足，数为热自内生。血虚生热，内扰心神则心悸眩旋，营卫失和则倏寒倏热；舌白糙亦示虚热伤津。小数之脉紧扣血虚内热之机，故以加味逍遥散养血疏肝、清退虚热。", ["小", "数"]], "2854": ["病机", "脉濡为血虚，弦为气滞、营卫不和，数为热自内生。血液不足则虚热内扰，寒热往来、月事愆期；气滞血涩则经来腹痛。濡弦数并见，正合血虚生热、营卫不和之病机，故当治奇经以调营卫。", ["濡", "弦", "数"]], "2855": ["病机", "脉小为血虚，数为虚热内生。投逍遥散后寒热止而复来、腹痛依然，说明营卫未和、奇经未调，血虚生热之本未除。小数之脉仍示血虚内热之机，故仍当和营卫、兼顾奇经以治其本。", ["小", "数"]], "2856": ["病机", "脉小数，小为血少，数为有热。原文“血液不足，木失润养，癸停气滞”，血虚不能濡养肝木，肝失疏泄则气滞，故腰酸腹疼、癸停。数脉示血虚生内热，热扰冲任。此脉主血虚肝郁化热之病机，与腰酸、腹疼、经停症候相应，法当养血润肝以复其疏泄。", ["小", "数"]], "2857": ["病机", "脉小数，小主血虚，数主内热。原文“血虚肝旺，冲任失调，月事先期，身热形寒”，血虚则肝体失养，肝阳偏旺，冲任不固故月事先期；内热则身热，营卫不和则形寒。数脉为热自内生之征。此脉主血虚肝旺、冲任失调之病机，与月事先期、身热形寒相应，治当调八脉。", ["小", "数"]], "2858": ["病机", "脉右弦，右关候肝脾。原文“产后营虚，肝脾失运，冲带无隶，腹痛便难，月事不调”，产后营血亏虚，肝失柔养则弦，脾运不健则腹痛便难；冲带失约故月事不调。弦脉主肝郁气滞、脾运受困。此脉主肝脾失运、冲带不约之病机，与腹痛、便难、月事不调相应，治以疏肝调冲。", ["弦"]], "2859": ["病机", "脉濡弦，濡主湿滞，弦主气郁。原文“腹痛未已，脘胀气滞，舌腻”，舌腻为湿浊内蕴，濡脉应之；脘胀气滞，弦脉应之。湿阻气机，肝脾不和，故腹痛缠绵未已。此脉主湿滞气郁、肝脾不和之病机，与脘胀、舌腻、腹痛相应，治再疏和以化湿理气。", ["濡", "弦"]], "2860": ["病机", "脉右数，右脉候气，数主热。原文“体本骨蒸里热，二九天癸未至。近复热灼阳络，咯血脘闷”，里热炽盛，灼伤阳络则咯血；热壅气滞则脘闷；热扰冲任，经水不行。数脉为里热内盛之征。此脉主里热灼络、冲任受阻之病机，与骨蒸、咯血、脘闷、经停相应，防成倒经。", ["数"]], "2861": ["病机", "脉小数，小为血虚，数为有热。原文“血虚有热，冲任失调，气滞腹痛”，血虚则冲任失养，热扰则冲任不调；血虚气弱，运行不畅则气滞腹痛。数脉示虚热内生。此脉主血虚有热、冲任失调、气滞腹痛之病机，与腹痛、月事不调相应，当气血两调。", ["小", "数"]], "2862": ["病机", "脉细数，细主营阴不足，数主内热。原文“产后崩漏，营阴不足，热自内生，月事不调”，崩漏伤营，阴血亏虚，脉道不充故细；阴虚不能制阳，虚热内生故数。热扰冲任则月事不调。此脉主营阴不足、虚热内生之病机，与崩漏、月事不调相应，法当养血调冲。", ["细", "数"]], "2863": ["病机", "脉小弦而数，小主阴血不足，弦主肝郁气滞，数主里热。原文“去岁崩漏，近复癸停两月，里热咳呛”，崩漏伤阴，肝失柔养则弦；阴虚内热则数；热灼肺金则咳呛；热扰冲任则癸停。此脉主阴亏肝郁、里热内盛之病机，与崩漏、经停、咳呛相应，防其复萌。", ["小", "弦", "数"]], "2864": ["病机", "脉小弦者，小为血少，弦为肝失柔和。原文言“血不养肝，肝失疏泄”，肝血不足则脉体细小，疏泄失常则脉气紧张而弦。肝失疏泄，气机不畅则腹痛；肝血亏虚，带脉不固则带下。此脉主血虚肝郁之病机，与腹痛、带下症候相应，故当调肝肾以养肝疏肝。", ["小", "弦"]], "2865": ["病机", "脉小弦，小主营阴不足，弦主冲带失调、脉气不和。原文谓“产后营阴不足，奇经冲带失调”，产后阴血亏耗，脉道不充故小；冲任失养，气血运行不畅故弦。营阴不足、奇经失约，则月事不以时下。此脉示虚中夹滞之病机，主产后经水失调，治当调治八脉。", ["小", "弦"]], "2866": ["病机", "脉小弦，小为血虚，弦为内热与冲带失调之象。原文言“血虚生热，冲带少贮”，血虚则脉体细小，虚热内扰、冲带失和则脉气紧张而弦。血虚生热，冲任不固，故月事先期；胞脉失养、腰府不利，故腹痛腰酸。此脉主血虚有热、奇经不调之病机，治当调治奇经。", ["小", "弦"]], "2867": ["病机", "脉弦，为营虚生热、气血失和之象。原文谓“营虚生热，迫血妄行，经漏脉弦”，营阴亏虚则内热由生，热迫血海则经漏不止；血去而脉道失柔，气机偏亢，故脉见弦。此弦非实邪，乃虚热扰动、冲任不固之病机，主经漏，治当调治八脉以和营清热。", ["弦"]], "2868": ["病机", "脉细弦，细为血虚阴亏，弦为虚热内扰、气不摄血之象。原文言“血虚生热，气不摄血”，血虚则脉道不充而细，虚热与气机失和则弦。血热上逆则齿血咳逆，下注则崩漏带下。舌白腻示兼湿，脉细弦主血虚热扰、气不摄血之病机，切宜怡养以复营阴。", ["细", "弦"]], "2869": ["病机", "脉右小滑，右候气分，小为营血不足，滑为血热与邪扰。原文谓“烦劳动血，血热妄行，经讯淋漓”，血热妄行则脉滑；营血耗伤则脉小。腹笥䐜胀、兼挟外感，故右脉小滑示血热妄行兼外感之病机，主经讯淋漓，当标本兼顾。", ["小", "滑"]], "2870": ["病机", "脉沉小，沉为气机失展、病在里，小为营阴虚耗。原文言“冲血因热妄行，营阴虚耗，带脉不固，气机失展”，营阴亏耗则脉体细小，气机郁滞于里则脉沉。热迫冲血妄行而带脉不固，故脉沉小主营虚气滞、带脉失固之病机，当养营阴以调八脉。", ["沉", "小"]], "2871": ["病机", "脉右小滑而数，小为气阴俱伤，滑为瘀热与痰，数为热与邪。原文谓半产后“瘀下如崩，月余不断，带多有汗，兼挟感邪咳呛”，血去过多则脉小，瘀热内蕴则滑，感邪化热则数。此脉示气阴两伤、瘀热未清兼外感之病机，最虑汗脱变端。", ["小", "滑", "数"]], "2872": ["病机", "脉右虚弦而数，虚为营血不足，弦属肝木偏旺，数为余热未清。瘀露白带虽止、自汗已敛，然营卫迭偏故寒热往来；虚弦不静，神疲善卧，示气血未复、肝脾未和。原文谓“逾险岭，未入坦途”，正合此虚弦数脉所主之营虚热扰、卫气不固病机。", ["虚", "弦", "数"]], "2873": ["病机", "原文未出脉名，以“营不足，气有余，肝脾失运”立论。营虚则冲任失养，气余则肝木横逆，故瘕气留着为痛为胀、便艰脘闷；任脉不约束则经迟色淡、白带绵绵、腰脊时楚。近夹湿邪小疟，皆气营失调、八脉不固之病机，治法宗逍遥调和肝脾、参固涩以摄奇经。", []], "2874": ["病机", "脉小弦，小为血虚，弦为肝旺。原文谓“血虚生热，冲带失贮，气无依附”，故瘕聚腹胀、月事愆期、色紫带多；气无依附则营卫不和而时或寒热。小弦之脉正示营血亏虚、肝木偏亢、奇经失约之病机，故以养血润肝兼顾奇经为治。", ["小", "弦"]], "2875": ["病机", "本段未录脉象，先引任脉为病“女子带下瘕聚”之旨，溯其源为营虚血亏，木火失涵。营血亏则任脉不充、带下瘕聚由生；木火失养则肝用偏亢。治法仍宗原议增删，即养血涵木以调奇经。全段重在阐发带下瘕聚本于营虚血亏之病机，非据脉立论。", []], "2876": ["妇人", "居经五月，脉弦而滑。滑为血盛养胎之象，弦则肝木偏旺、里热内蕴，故见里热带下。曾两次半产，恐肝热扰动冲任、胎元不固，故亟用千金保孕之属以防覆辙。弦滑并见，示胎已结而肝热未清，属妇人孕产防堕之候。", ["弦", "滑"]], "2877": ["妇人", "经停两月，瘕攻腹痛、腰酸带下，脉小弦。小为营血不足，弦为肝气偏旺，冲任失调则经停；气血郁滞、瘕攻故腹痛腰酸，带脉不约则带下。小弦非孕脉之滑利，故原文“预防孕象”，示当辨瘕聚与妊娠，属妇人经停瘕痛之病机。", ["小", "弦"]], "2878": ["病机", "疟后气阴两虚，脉小弦。小为气阴不足，弦为肝木偏旺。肝旺乘脾则瘕攻腹胀、甚则脘痛；营卫不和则倏寒倏热。此脉示虚中夹实、肝木偏亢而气阴未复之病机，故治以辛酸，辛以散肝、酸以敛阴，正合小弦所主。", ["小", "弦"]], "2879": ["病机", "脉小弦，小主血虚，弦主肝旺。血虚则冲任失调，故癸停身热；肝旺则瘕攻腹痛；木火刑金则兼有咳呛。原文“切宜怡养”，示此脉非峻攻所宜，当以养血柔肝、怡情调养为要。小弦并见，正示血虚肝旺、冲任失和之病机。", ["小", "弦"]], "2880": ["病机", "脉左弦，左关候肝，弦为肝脉，主气机郁滞、寒凝收引。寒邪伤中，中阳受困，肝失疏泄，气结血瘀，日久成瘕，攻冲腹痛。弦脉应指如按琴弦，紧而有力，正合寒凝气滞、瘕块攻痛之病机，故以仲景温散通阳之方治之。", ["弦"]], "2881": ["病机", "脉弦滑，弦主肝郁气滞，滑主痰湿与胎孕。居经七月，少腹作痛，气滞辄胀，身热口渴，舌淡绛，乃胎气上逼，厥阴气滞，郁而化热。弦滑并见，既示胎元壅盛，又示肝经气滞，故以紫苏饮子佐安胎元，理气安胎并行。", ["弦", "滑"]], "2882": ["病机", "脉弦小滑，弦为肝郁，小为气血内敛，滑为胎孕之象。居经三月，脘满泛呕，得食辄胀，身热形寒，舌糙，似属孕象。弦小滑三字合参，示肝胃不和、胎气初结，故以紫苏饮子大意疏肝和胃、安胎为治。", ["弦", "小", "滑"]], "2883": ["病机", "脉弦数，弦主肝郁，数主热。居经四月，挟感寒邪，寒郁化热，肝气不舒，故脉见弦数。此非单纯外寒，乃寒邪外束、肝郁化热之象，治以疏和，疏肝解郁、和营透邪，使气机调畅则寒热自解。", ["弦", "数"]], "2884": ["病机", "脉弦小滑，弦主肝气郁滞，小为胃气不和，滑为胎孕之征。经停呕吐，肝胃升降不调，似属恶阻。弦小滑并见，示肝郁犯胃、胎气上逆，胃失和降，故呕恶由生，治当调肝和胃、降逆安胎。", ["弦", "小", "滑"]], "2885": ["病机", "脉弦小数，弦主肝郁，小为营血不足，数主热。产后八朝，恶露少通，复感寒邪，寒热俱甚，腹痛呕逆，头疼汗多。弦小数示营卫不和、瘀热内郁，寒邪外束，故治以辛散，两和营卫，兼通恶露，使邪解瘀行。", ["弦", "小", "数"]], "2886": ["病机", "脉小弦，小为血虚，弦为气滞血瘀。初产两朝，恶露稀少，腹大不收，瘕攻作痛，乃瘀血内停、气机不畅。小弦之脉示产后血虚而瘀滞未行，故以生化汤加失笑散，养血活血、化瘀止痛，防血瘀上冲。", ["小", "弦"]], "2887": ["病机", "脉小弦，小主血虚，弦主瘀滞。新产三朝，瘀凝少通，少腹瘕攻作痛，乃产后瘀血内阻、气机不利。小弦之脉正合血虚瘀滞之机，故以生化、失笑之属，温经化瘀、行气止痛，使瘀去新生而痛止。", ["小", "弦"]], "2888": ["病机", "脉弦小数，弦主瘀滞，小为血少，数为郁热。产后恶露少通，瘀血内停，故腹痛胀及少腹；舌糙苔腻为湿滞。脉弦小数反映瘀阻化热、中运不健之病机，法当健运中室兼逐瘀。", ["弦", "小", "数"]], "2889": ["病机", "脉弦小数，弦主瘀结，小为血虚，数为热象。产后百日恶露少通，少腹攻痛，瘀聚于内；腰酸带下、眩旋脘闷为兼症。脉象示瘀血内结、郁而化热，尚防崩漏，故当活血化瘀。", ["弦", "小", "数"]], "2890": ["病机", "脉小弦，小为血少，弦主瘀滞。产后瘀凝不通，月事五月不下，少腹攻痛，聚块形似症瘕。原文明言“并无弦滑之象”，故难凭孕征。脉小弦提示瘀血内结、血虚不畅之病机。", ["小", "弦"]], "2891": ["病机", "脉小弦，小为血虚，弦主气滞。新产五朝，气血未复，偶感风寒，身热脘闷，腹痛汗多，舌黄腻。脉小弦示产后血虚、气机郁滞，兼感外邪，故以清魂、失笑之属活血理气。", ["小", "弦"]], "2892": ["病机", "脉弦数，弦主瘀滞，数为热盛。产后瘀月余，恶露早断，少腹攻痛，瘀血内停，郁而化热。脉弦数示瘀热互结，恐成肠痈，故当警惕。", ["弦", "数"]], "2893": ["其他", "本段未识别出脉名，仅述独立老人用药方及脉论精当，可资医则。原文未及具体脉象，故脉象要素为空。主旨为附录医方与脉论，属其他类。", []], "2894": ["病机", "左脉沉滑，右脉沉紧时一止。沉主里，滑主痰食，紧主气郁，止为结代。因焦虑太甚，心脾郁结，食滞不化，故脉沉紧而时止。此气郁食滞之病机，非归脾汤所能独治。", ["沉", "滑", "紧", "止"]], "2895": ["病机", "十二经脉并绝，四末稍厥，唯脐间动气应手，脉沉弱微。沉弱微为阳气衰微，气血不能外达，故脉不应手。此卒中险症，元气败绝之病机，预后凶险。", ["沉", "弱", "微"]], "2896": ["病机", "脉沉滑，沉主里，滑主痰食。患者卒倒、牙关紧急、身冷，乃七情气逆、食滞内闭，气机壅塞，痰食交阻，故脉沉滑。此非虚寒急症，不可妄用三生饮峻伐，当以苏合香丸开窍行气。", ["沉", "滑"]], "2897": ["病机", "脉浮弦而促，浮主表，弦主饮，促主热。患儿痰喘声闻阃外，癍疹搔痒，乃胎毒未尽，痰热内蕴，外发肌肤，肺气壅逆。浮弦促为痰热交争之象，故喘与疹并作。", ["浮", "弦", "促"]], "2898": ["预后", "脉弱甚，为脾胃气绝之候。疟疾日久，寒热虽退，而四体羸尪、断食吐涎，胃气已败。脉弱甚示中焦化源告竭，故断为脾胃绝症，预后不良。", ["弱"]], "2899": ["病机", "脉浮弦而小，浮弦主风木乘土，小主正虚。飧泄完谷不化、腹痛消瘦，乃肝木克脾，脾失健运，清浊不分。脉症合参，属土虚木贼之泄泻，非痢疾也。", ["浮", "弦", "小"]], "2900": ["病机", "左手关尺弦微，关候肝脾，尺候肾。弦为肝郁，微为阳衰。患者年高久泻，肠鸣漉漉，溏泄如冷水，乃肝经虚寒，脾肾阳弱，水湿不化。脉沉弦缓小，正合虚寒泄泻之机。", ["弦", "微"]], "2901": ["病机", "脉沉弦缓小，沉主里，弦主肝，缓小主虚寒。腹内久冷、肠鸣泄痢，服补脾胃药不应，乃肝经虚寒，木不疏土，寒湿内盛。高良姜汤温肝暖脾，故投之必效。", ["沉", "弦", "缓", "小"]], "2902": ["病机", "脉洪而软弱，洪为气分热盛，软弱为气阴不足。痔疾下血日久，气随血脱，故脉洪大而软，甚则两手俱绝、脉如蛛丝。此气不摄血、阴伤阳浮之候，急宜人参补气固脱。", ["洪", "软", "弱"]], "2903": ["病机", "脉左右沉中带弦，沉主里，弦主郁。患者年高郁滞，腹胁虚胀、二便不利、面目浮肿，乃怒气郁结，肝失疏泄，升降失常，水湿停聚。脉沉弦正是肝郁气滞、水气内停之应。", ["沉", "弦"]], "2904": ["病机", "脉甚微提示阳气衰微，纵饮冷酒吐血后，阳气随血脱而式微，气血大亏，故脉微。脉色稍和说明胃气尚存，但脉微主病机为阳气虚衰，与吐血、昏倒相应，需急固元气。", ["微"]], "2905": ["病机", "脉虚弦，虚为气血亏虚，弦主痛或气机不畅。高龄发疡溃后脓清稀，血气必亏，脉虚应之；弦为疮疡局部气血壅滞，亦示元气不足而邪留。故主血气亏虚、疮口不敛，与咽膈不利、咳嗽黏痰相应。", ["虚", "弦"]], "2906": ["病机", "左沉弦有神，右沉滑流利。沉弦主气郁，滑主痰，脉有神为胃气未败。患者性直少言，常气滞腹胁痞满，痈疽由气郁血涩壅结而成，脉象反映气郁痰滞、血行不畅之病机，与背疡、便秘相应。", ["沉", "弦", "滑"]], "2907": ["病机", "脉轻缓重紧，轻取缓为表虚或湿滞，重取紧主寒主痛。背痈肿不高不光泽，胸腹䐜胀，手背足趺微肿，乃寒湿凝滞、气血壅遏，脉紧应寒凝，缓为湿滞，病机为寒湿阻络、疮毒内陷。", ["缓", "紧"]], "2908": ["病机", "脉六部俱四动半和，带弦如条条然。四动半为平和之象，弦如条条主气机郁滞。动气冲或升沉，饮食不爽，皮厚气不畅，皆气郁不舒、升降失常之病机，弦脉应之。", ["弦"]], "2909": ["病机", "两手微弦，两尺微弦而滑。弦主气郁或木旺，滑主痰湿。尺部弦滑提示下焦痰湿或肾气不和。服养胃丸不应，说明病机非单纯胃虚，涉及肝脾气滞与痰湿内阻，与久病不愈相应。", ["弦", "滑"]], "2910": ["病机", "脉弦而似长，弦主气郁，长主气机有余或邪实。年高气易闭，肾气动恶燥，动气冲不收，脉弦长反映气逆上冲、肾气不纳之病机，故白术不可轻用，需待动气收后再议。", ["弦", "长"]], "2911": ["病机", "脉浮细数六动有奇，浮为阳气外越，细为阴血不足，数为有热。肾间动气冲鼓，温药后动气收，脉数乃寒气将散、阳气来复之象，但胃欠谷气，脉色不润，病机为阳气虚浮、胃气未复。", ["浮", "细", "数"]], "2912": ["病机", "脉浮细数，浮为邪在表，细为阴血不足，数为热象。原文谓\"微热至\"而脉见浮细数，说明外邪未解、内热渐生，正虚邪恋之象。医者\"疑\"而\"主意不定\"，正因脉症不符单纯表证或里证，提示病机复杂，虚热与外邪交织，故难骤下断语。", ["浮", "细", "数"]], "2913": ["病机", "脉和五动而带弦滑，五动为常至数，弦主气机郁滞、饮邪内停，滑主痰湿。原文\"动气收、足膝温\"示药后阳气渐复，但弦滑未去，说明水饮痰湿尚未尽化，气机仍有郁滞。众医恐\"药力胜病\"生变，正因弦滑脉提示余邪未清，不可遽停温药。", ["弦", "滑"]], "2914": ["误治", "脉六动许而尺弦带滑，数为热，弦滑主饮聚气滞。原文\"面瘦倦睡、肌体弱\"\"胸胁下似有物相碍腹牵强\"，显系阴亏热扰、饮邪内结。医欲用人参养胃汤，然草果厚朴辛温苦燥，正犯\"脉数肌热困倦\"之忌，故予固拒之，指出辛燥淡渗失佐则\"反燥胃液以成伐\"，属误治之戒。", ["数", "弦", "滑"]], "2915": ["其他", "原文未识脉名，仅载加藤氏诊\"五动六部和利贴肉而有力\"，一斋摩腹谓\"中气想弱\"。脉虽和利有力，腹诊却示中气不足，二者似相矛盾。此段重在记录诊法互参，脉象描述为纯叙述，未出具体脉名，故脉象要素从缺，主旨属诊察记录而非主病判断。", []], "2916": ["兼症", "脉五动有奇、似滑而润，五动为平至数，滑润主痰饮内停。原文\"侯觉胸满\"\"腹间少有动气\"，正合滑脉主饮、饮停气滞则胸满动气。众医\"强药言后自宽\"，说明脉虽带滑而胃气尚和，故可进药，滑润之象提示饮邪未深，属兼症观察。", ["滑"]], "2917": ["预后", "原文先记\"泄一次\"\"吐留饮五盏余\"又\"泄一次\"，吐泄交作，似饮邪外出。至亥时\"脉和\"，和脉为胃气调和之象，说明经吐泄后邪去正安、胃气渐复。前有\"伤湿之语\"，吐泄留饮正是湿邪外解之途，脉转和提示病势向愈，故归预后。", ["和"]], "2918": ["病机", "脉五动有奇而和带滑，五动为常，和示胃气未败，滑主痰饮余邪。原文\"神气和\"\"尿少清\"，尿少清提示水湿代谢未复，滑脉正应饮邪留滞。虽神气安和，然滑象未除，说明留饮未尽，病机仍属饮停气化不利，需继续观察。", ["滑"]], "2919": ["兼症", "脉五动余而和带滑，有动气在中下二脘。原文\"上脘如有物碍\"\"按之肌肉间并无著手者\"，说明非有形积块，乃\"留饮之余\"。滑脉主饮，动气示饮邪冲动，和脉则胃气尚存。食饮少进、言语声清为兼症，脉滑提示饮邪未净，故归兼症。", ["滑"]], "2920": ["病机", "脉左和利而滑，有弦势，右三部和利中有动荡之形。滑为痰饮内蕴，弦主气机不畅，动荡示痰气交阻。胸膈不快乃痰气上扰所致，脉证相符，说明痰饮内停、气机失和之病机。", ["滑", "弦"]], "2921": ["病机", "原文述脉既利，然滑形，结合前文痰饮聚而声浊、胃失液则口燥咽干，滑脉主痰饮内盛。医者去白术加干姜，恐其燥闭，脉滑示痰饮未化，故以六君调之，说明痰饮内聚、气机不利之病机。", ["滑"]], "2922": ["病机", "晚脉左右五动有奇带滑，亥后更衣泄止。滑脉主痰饮，亦主宿食，泄止而脉滑，示痰饮宿滞未净，气机尚欠通利。此脉象反映痰湿内蕴、脾胃运化未复之病机。", ["滑"]], "2923": ["病机", "脉左右六部平静而流利，肾间动脉亦静，大有复元之机，然更有邪之余动。动脉主惊、主痛，亦主气机躁动，此处示余邪未清、气机偶有扰动，但整体脉静流利，为向愈之象。", ["动"]], "2924": ["病机", "晚脉五动静带滑形，心脉躁。滑主痰聚，动主气机躁扰，心脉躁因思虑所役。原文疑痰将聚或疝气，说明痰浊欲聚、心神被扰之病机，与思虑劳心、气机不畅相应。", ["滑", "动"]], "2925": ["病机", "脉左右宁静五动少躁，有上下去来之势，冲阳太谿脉俱和，动气依前未全收。动脉示气机仍有轻微扰动，然脉宁静少躁、冲阳太谿和，说明胃气渐复、病势向安，唯动气未全收为余波。", ["动"]], "2926": ["病机", "经曰阴不胜其阳则脉流薄疾，此段引经以论脉疾之由。脉流薄疾乃阴虚阳亢、阴不制阳所致，故医者主张加养血之品以润脉息、复瘦燥、养其阴，说明阴虚阳扰、脉行急疾之病机。", ["疾"]], "2927": ["病机", "左关弦滑，右关弦，左腹有气自五枢上循天枢至期门而动，小水不清，食饮不爽。弦主肝木气盛，滑主痰饮，木气独专、干乎土而胃气未周，故食饮不爽；原有疝症乘势而变，说明肝气横逆、脾受木克之病机。", ["弦", "滑"]], "2928": ["病机", "脉五动和，然六部中尚在弦势，弦为肝木之象，示肝气未全平复，中气尚欠调畅。虽脉率已和，但弦势未除，说明病机重点在肝脾不和、中气未复，故停汤药而以饮食调理中气，防药过伤中，亦示脉象为病机转归之兆。", ["弦"]], "2929": ["病机", "左关带弦滑形，余部和，弦滑为肝胆余邪未尽之象。引《难经》少阳之至乍大乍小、乍短乍长，释为阳气尚微、阴气未退，进退未定。脉见少阳生发之机，故知余邪未清而正气渐复，内养精气、外调饮食可指日复元。", ["弦", "滑"]], "2930": ["病机", "脉六部和五动，左关少有弦形。六部虽和，而左关独见弦形，弦为肝脉，示肝气尚有微郁未畅，余邪未尽。脉率五动为和缓之象，说明整体胃气渐复，但肝木偏旺之机尚存，故以‘少有弦形’提示病机在肝脾调和未彻。", ["弦"]], "2931": ["病机", "六部机荡有弦形，左关弦滑，右尺有力。弦滑主痰饮气滞，左关应肝，右尺应肾，脉见机荡不宁，示痰气交阻、肝脾不调。原文问‘清晨漱口误吞熟水’、‘食稀粥而使然’，说明脉象反映水食停滞、气机不畅之病机，非单纯虚候。", ["弦", "滑"]], "2932": ["病机", "诊脉数，至丑时寒热作，少顷寝汗。数为热，脉数而见寒热、寝汗，示邪正交争、营卫不和，食滞于胃口而胀，进而化热。原文‘昨晡进膳少许，至更深不消，滞于胃口而胀’，说明脉数为食积化热、胃气壅滞之象，故进补养不当反致此。", ["数"]], "2933": ["病机", "脉五动浮，左似和而滑，右似和而微滑。浮为气机上浮，滑主痰聚，微滑示痰轻。原文‘少机神而上下去来之势微’、‘中脘有滞气’、‘痰聚则滑，气滞则欠神’，说明脉浮滑为痰气交滞、中焦气机不畅之病机，故以治中汤调气化痰。", ["浮", "滑", "微"]], "2934": ["病机", "本段未识脉名，但言‘脉欠机神’，结合前文‘少机神而上下去来之势微’，知脉象缺乏和缓之神，示中气虚弱、痰食阻滞。原文‘数日食阻’、‘半夜寒热’、‘腹有碍滞’，说明病机为脾虚气弱、痰食不化，故以参甘补之、青陈平之、茯苓导之。", []], "2935": ["病机", "脉五动和利似滑，腹间动气微，肾间动气浮，左腹冲者缓。和利似滑示胃气渐复而痰饮未净；动气微、冲者缓说明气机渐平。原文‘晡后觉鸠尾下宽畅，不日能进食’，脉证相合，示痰气渐化、中焦渐通之病机转归。", ["滑"]], "2936": ["病机", "脉六部机神荡动，按之似滑，举之和缓五动许，为胃气尚存而虚风内动之象。机神荡动者，阳气不藏，故见巨阙下微痛、腹间动气；滑为痰饮内停，缓为胃气未绝。动气在中脘建里间，乃中焦气机逆乱，水饮与虚风相搏，主病在脾胃，症见微痛、动气，属虚实夹杂之候。", ["滑", "缓"]], "2937": ["病机", "脉左五动、右五动半，按之有力，举之似涩，为实中夹瘀之象。有力主邪实内结，涩主气滞血瘀，故腹间建里有块碌碌而响，期门不容水分俱有动气，独中脘建里最甚。动气聚于中焦，块响不散，乃痰瘀互结、气机壅塞，主病在肝脾，症见癥块、动气、泄而少。", ["涩", "实"]], "2938": ["病机", "脉五动余，按之肌肉而得似静，佥曰脉和，而予独谓少气。脉虽似静和，然五动余而按之肌肉方得，举之不足，是胃气虚弱、中气不能鼓动之象。静而无力，非真和也，乃少气之候，主中焦气虚，症见倦怠、少食，与后文“胃乏水谷精气”相呼应。", ["静", "和"]], "2939": ["病机", "晚脉五动似静，脉数减动，佥曰大好，而予谓因便后肠胃无物使然。脉数减动非真和，乃泄后胃乏水谷精气、血脉空虚所致。引《明理论》“出者为虚”，自达和十余日进膳甚少，前泄四次，仓廪传导失职，不能留水谷，故脉虽似静而实虚，主胃气虚损、中气不足。", ["数", "虚"]], "2940": ["病机", "晚诊似和，由欠谷气使血脉虚而然耶。脉似和而实虚，因少食谷气不充，血脉空虚，故动气虽静而中气将惫。加藤氏曰动气静矣，予曰精气少、中气将惫，是脉之和乃胃气勉力支撑，非真元充实。虚脉主气血不足，症见少食、动气虽静而根本已亏。", ["虚"]], "2941": ["病机", "脉五动余，细滑，动气自丹田起脐旁，中脘不容俱动，左期门尤盛，足趺阳脉浮弱，太谿微。细滑为痰饮内停、气血不足；动气起于丹田，冲脉上逆；趺阳浮弱主胃气虚，太谿微主肾气弱。是脾肾两虚、冲气上逆、痰饮内动之候，主病在脾肾，症见动气、少食。", ["细", "滑", "浮", "弱"]], "2942": ["病机", "晚脉五动零，细滑，佥曰脉如常，予谓脉宽者稍与病相称，脉似沉和乃少膳及更衣之多使然。细滑为痰饮未化，沉和为胃气尚存但谷气不足；动数未减，是邪未全退。因天寒雪冻、少膳多便，中气受戕，故脉虽似和而实未复，主病在脾胃，症见少膳、便多。", ["细", "滑", "沉"]], "2943": ["病机", "辰时脉五动，似和静，少上下去来机神，佥曰大好而动气不息。脉虽似和静，然少上下去来之机神，是胃气虽复而鼓动无力；动气不息，乃冲气未平、中焦气机未畅。似和静而机神不足，主中气虚弱、冲脉不宁，症见动气持续，虽曰大好而根本未固。", ["静", "和"]], "2944": ["其他", "原文以“脉五动似辰脉”为候，众人以为“和”，而作者独疑“动气如晨”，并联系“食物则胀”之症。五动近于常度，然动气应晨时，食后作胀，提示胃气壅滞、脾运不健，非纯然平和之脉。作者未明言病机，仅存疑待考，故列其他。", ["动"]], "2945": ["病机", "“午后脉五动，冲阳太谿脉有力”，冲阳候胃气，太谿候肾气，二脉有力说明胃肾之气尚充。然脉五动而兼症见脚及肢瘦，动数之象提示胃气偏亢或虚阳扰动，谷气不能充养四肢，故肢瘦脚弱。脉动与冲阳太谿有力并见，主胃肾本实而脾运不布。", ["动"]], "2946": ["病机", "“脉左右五动，机神流利”较前“失调”为转机，冲阳太谿有力，示胃肾气复；然“宗气脉应手弱”，宗气不足则推动无力。动气在中脘建里，谷气壅于中焦。作者疑“药必去其攻剂”，恐攻伐伤中。脉动而宗气弱，主中气不足、谷气不运，兼有药伤之虑。", ["动", "弱"]], "2947": ["病机", "“脉五动无力，气口涩”，动而无力为气虚，涩主脾虚血少、津液不布。原文述尊年气弱、中气劳倦、膳少、足趺虚浮、肢体困倦，引《难经》“虚为不欲食”，论脾虚转输失职、饮食不磨、胃病痞满飧泄。脉涩无力正合脾虚不运、中气亏乏之机。", ["动", "涩"]], "2948": ["其他", "仅记“卯时脉左右四动半有奇”，未附症候与论断。四动半较前五动略减，近于常度而稍偏数，然无兼症可参，不能遽定病机。原文止于脉候记录，故列其他，存脉待参。", ["动"]], "2949": ["病机", "“左四动半有奇似滑，右四动有奇似涩”，左脉似滑主谷食碍胃、痰食内滞，右脉似涩主胃气不畅。作者断曰“动气上乎左，谷食碍乎胃”，正以左滑右涩分候肝胃。动气上逆、谷食不化，故脉见动而兼滑涩，主中焦壅滞、胃气不降。", ["动", "滑", "涩"]], "2950": ["病机", "“脉四动沉静，动气在中脘下而静”，四动近常，沉静示气机内敛不浮。前日动气上逆、谷食碍胃，今动气下移中脘而静，脉亦沉静，说明中焦气机渐得安和，逆气下行。脉沉静而动气静，主气逆渐平、胃气复降之机。", ["动", "沉"]], "2951": ["病机", "“晚脉四动半似滑，动气在中脘而静”，四动半稍数，似滑主谷食痰滞；动气在中脘而静，较前上逆之势已缓。脉动而滑、动气静守中脘，说明谷食碍胃未全化，然气逆已平。主中焦食滞渐消、胃气未复之候。", ["动", "滑"]], "2952": ["病机", "晨脉五动而左躁右似滑，躁为阳动之象，滑主痰湿内蕴。侯断“夜来心动”，是左寸躁动应心，心阳不宁；足脉静、右趺肿退，说明病势偏于上焦心神浮动，而下焦水湿渐退。脉数与滑并见，提示邪热与痰湿相合扰心，故以心动为候，非纯虚之象。", ["数", "滑"]], "2953": ["病机", "脉五动弱而太谿脉微，弱为气血不足，微为阳气衰微。太谿属肾，其脉微提示肾气不振、水湿不化，故趺肿虽退而未尽。侯言“食物如嚼砂、胃口不快”，正是脾胃虚弱、纳运失司之候。脉弱主脾胃不和，邪气似退而中焦未复，病机重心在脾肾两虚。", ["弱", "微"]], "2954": ["病机", "晚脉四动半有奇而弱似涩，弱主气虚，涩主血少或湿滞。脉弱涩并见，说明气血不足兼有运行不畅，脾虚失运、湿浊内阻。侯议服参苓白术散、异功散加升麻柴胡苡仁，皆从补脾升清、化湿立法，正合脉弱涩所反映的脾胃气虚、清阳不升、湿滞不化之病机。", ["弱", "涩"]], "2955": ["病机", "脉五动弱，冲阳太谿无力，宗气应手而气冲和，趺肿退三之二。弱脉主脾胃气虚，故侯自述“口不渴、头不眩、心不怔、二便无碍，唯四肢无力、食物不味”，病在脾胃。动气降于脐之上下四围，是脾气不足、气机升降无力之象。诸医议用参苓白术散、归脾汤、异功散，皆补土之治。", ["弱"]], "2956": ["病机", "晚脉左右五动，气口似有生发之机，人迎以下似有疾在。五动偏数，主阳动有热；气口属肺脾，其有生发之机说明脾胃之气渐复；人迎以下似有疾，则提示病邪留于下焦或阴分。脉数而分部有别，反映正复邪恋、上下病势不均之病机，非单纯虚损可比。", ["数"]], "2957": ["病机", "脉四动余而不流利，按之浑浑然，涩滞之象明显。涩主血少、气滞或湿阻，脉道不畅故不流利；浑浑然则示湿浊蒙蔽、清浊不分。侯脉天晴则清、天阴则浑，说明湿邪随天气阴阳而进退，湿浊内蕴为病机关键，脉涩正是湿阻气机、血行不畅之应。", ["涩"]], "2958": ["病机", "午间天霁，脉色清而五动弱。脉弱主气血不足、脾胃气虚，天晴脉清说明湿浊暂退、脉道稍通，然弱象仍在，示正气未复。此段以脉弱应脾胃虚弱之本，天气转晴仅使湿浊稍减，病机重心仍在气虚，不可因脉色清而误认为邪退正复。", ["弱"]], "2959": ["病机", "早脉五动半有奇而浮弱，两尺极无根。浮为阳气外浮，弱为气血不足；两尺候肾，极无根是肾气衰败、根本动摇之象。脉浮弱而尺部无根，说明虚阳上浮于外、下元空虚于内，病机属脾肾两虚、阳气不藏，预后当须留意，非寻常气虚可比。", ["浮", "弱"]], "2960": ["预后", "脉五动半有奇而浮弱数散无根，浮弱为正虚，数而散为元气浮越无根，故言“尊侯大疲”，众医不及言候而退，示正气衰败、胃气将绝之危候，预后不良。", ["浮", "弱", "数", "散"]], "2961": ["病机", "原文论动气，谓“痞块冲动奔走，筑筑然不息，如豚之奔”，乃二十年旧疴，升浮降沉不时，非新症误攻所致；今动气一止，非药力将应，而是“正气内亏，气血不能守卫”，邪气内陷之机。", []], "2962": ["兼症", "脉五动有奇弱，弱为气血不足；是日卯午酉三时泄下其色青，青为肝色，泄下青色示肝木乘脾、疏泄太过，脉弱主脾虚不运，与泄下青水相应。", ["弱"]], "2963": ["预后", "午脉五动零弱，较昨之浮散不同，脉“不似昨之浮散，至是而敛，且将静耳”，浮散为元气外越，今敛而静，示正气渐复、浮越之势得收，为向安之兆。", ["弱"]], "2964": ["兼症", "晚脉五动弱，弱主气虚；趺肿退十之八，示水湿渐化，而“动气浮动矣”，动气浮动为正气未复、气机不稳之象，脉弱与肿退、动气并见，属虚实夹杂。", ["弱"]], "2965": ["病机", "脉常带弦形，弦主肝病；素有疝症及肝气，昨溏泄、面惨寒、脉浮弱、色青、寒热、痛弦急，共属肝部之症，故用当归补肝血、肉桂行肝气、良姜温肝、干姜理肝，疏泄止则诸症平。", ["弦", "浮", "弱"]], "2966": ["兼症", "脉四动半有奇，似弦形，左关应之，左关候肝，弦为肝脉；一斋按摩言“胃之上口，痰将聚矣”，弦主饮癖，肝气犯胃、痰饮内聚，故脉见弦而应左关。", ["弦"]], "2967": ["病机", "晚脉四动有奇，左右似弦而缓，弦为肝气，缓为胃气尚存；弦而兼缓，示肝木虽亢而未至劲急，胃气未败，病机以肝郁为主，尚属可调。", ["弦", "缓"]], "2968": ["病机", "原文谓“脉左似滑，形欠流利，又有神在”，滑而欠流利，是痰食内滞、气机不畅之象，然有神在则胃气未败。左脉候肝，滑主痰饮，形欠流利示痰滞未甚，故此时病机为痰食初滞、正气尚能抗邪，非危候。", ["滑"]], "2969": ["病机", "“脉似滑而不利，欠升降不至五动”，滑而不利主痰浊内滞、气机升降失司。原文言脾气虚弱，精微滞于胃口，似痰非痰、似胀非胀，久则变饮变浊变溏变肿，正合滑脉主痰湿、不利主气滞之机，故以辛温升剂分清浊、调津液、提精微。", ["滑"]], "2970": ["病机", "“脉四动有奇，有上下之势，无涩弱之形”，四动有奇即至数偏数，有上下之势示气机尚能鼓动，无涩弱则阴血未大伤。原文自问“药应之耶，病将复耶”，说明此数而有力之脉为药后阳气来复、邪欲外达之象，非纯虚之候。", ["数"]], "2971": ["病机", "“晚脉四动有奇，大抵同辰诊”，仍为至数偏数、有上下之势之脉。辰晚同诊，说明阳气来复之势持续，非一时之变。数而有力示正气尚能抗邪，病机为阳气渐复、邪正交争，故原文以“同辰诊”相参，判断药后反应。", ["数"]], "2972": ["病机", "“脉四动有奇，大抵同前”，连续三日脉数而有势，说明药后阳气持续来复，非偶然之象。原文用人参粳米汤，正是补气养胃以助正气。数而有力在此非热盛，乃阳气渐充、胃气来复之征，故脉象稳定为佳兆。", ["数"]], "2973": ["治法", "此段未出具体脉名，仅言“脉色正”，即脉象与面色皆复常。原文以用兵喻用药，谓“阴阳虽未全周，趺肿退，动气止，肌体泽，脉色正”，说明大邪已去、正气渐复，唯食艰、痞难畅、泄未止，故暂憩补阴、特遣调阳，属治法权衡之论。", []], "2974": ["病机", "“晚脉四动半，上下去来有机”，四动半为至数偏数，上下去来有机示脉势从容有根，非涩弱无力。此数而有神之脉，说明阳气来复、胃气尚存，病机为正气渐充、邪退正复之候，故原文以“有机”许之。", ["数"]], "2975": ["病机", "“辰脉四动半有奇，大抵相若”，脉数而有神，与前数日一致。原文用固真饮、人参汤，正是固护元气。此数脉非热盛，乃阳气来复、正气渐充之象，脉势稳定说明药后气机渐调，病机为虚损渐复、元气来复。", ["数"]], "2976": ["病机", "脉四动半有奇，约当数脉，右气口躁而满指下，气口候中焦脾胃，躁动满指提示邪滞气壅，胃气不舒，主中焦气机壅滞，与脘腹满闷、纳运失畅相应。", ["数", "躁"]], "2977": ["主病", "脉五动半有奇而躁，数躁主热，鸠尾下疼痛按之张弦，弦为痛为气滞，热与气搏结于胸膈，故脉躁而痛处张弦，主热郁气滞之胸膈痛。", ["数", "躁", "弦"]], "2978": ["误治", "原文未及脉象，述鲫羹滞于胃口发痛，以橄榄芦根解毒、香砂藿梗通氣、橘朴消物、苏梗下气，属食滞胃脘、气机不通之误治调治，主消导通下以复气机。", []], "2979": ["病机", "晚诊六动躁，数躁为热，痛渐止而体倦食减，乃疝溏寒热交作、正气已虚，热由疝溏而发，故用温丸固溏调疝，温能除大热，主正虚邪滞、寒热错杂之病机。", ["数", "躁"]], "2980": ["兼症", "夜子后脉五动余，数而乏力，侯曰倦耳，数脉主热亦主虚，此数而倦，为正气不足、虚热内扰之象，与体倦乏力相应，主气虚发热之兼症。", ["数"]], "2981": ["治法", "卯时脉五动，尚有昨夜之余气，数势未静，进昨午煎成固真饮后侯觉畅快、体倦自和，示数脉为虚热未靖，固真饮温固下元、引火归原，主虚阳浮越之治法。", ["数"]], "2982": ["预后", "午脉五动势似和，晚脉大抵相若，数中见和，为胃气渐复、邪热渐退之兆，故归脾料不可忽，主病势向愈、当培补心脾以善后之预后。", ["数", "和"]], "2983": ["其他", "二十二日辰脉四动半有奇，较前五动余稍减，数势渐缓，示邪热渐退、胃气渐和，属病势向安之候，主数脉渐平、正气来复之象。", ["数"]], "2984": ["兼症", "原文仅言“脉大抵相若”，未及具体脉象，故脉象要素为空。所载“腹和”示中焦暂安，而“舌燥胸满、足趺余肿”则提示津伤气滞、水湿下聚未化。脉无显著变化，说明病势未进亦未退，属余邪未清、正虚水停之兼症阶段。", []], "2985": ["病机", "“脉四动有奇”即一息四至余，属数脉范畴，示阳气偏动。然“大抵相若”说明非新病进。医按胸腹良久致寒气外袭，恶心欲吐，进二姜丸即已，可知脉数非里热，乃按摩引动阳气、寒袭胃气之暂象，病机在气机怫郁而非实热。", ["数"]], "2986": ["兼症", "“脉大同”指脉与前相若，无具体脉形可录。原文“舌润耳”是对前“舌燥”的改善，示津液渐回。脉无变化而舌象转润，说明药后气阴得养，病机由燥转润，属向愈之兼症观察，非主病脉。", []], "2987": ["预后", "“脉四动半有奇宁”承前数脉而稍增，然着一“宁”字，示脉虽数而和缓有神。数而不躁，为阳气渐复、胃气未败之象。前方加味归脾汤减人参，说明病机在气血未充、虚阳偏动，脉数主虚热而非实火，预后可期。", ["数"]], "2988": ["病机", "左尺弦滑流利，右尺弦而和。弦为春生之象，滑为气血流利。原文“立春在迩，宜乎左部之弦得”，说明弦非病脉，乃应时生发之气。脉色和流，故“非其痞也”，胀为正气聚于气海，非邪滞。病机在气血渐充、气聚为胀，非实痞。", ["弦", "滑"]], "2989": ["预后", "“脉四动半宁”与前日脉数相若而称“宁”，示脉数中已有和缓之神。数而不失胃气，为虚阳渐敛、气血未复之象。原文仅此一句，结合前文归脾汤调补，可知脉数主气血不足、阳气偏动，预后平稳。", ["数"]], "2990": ["其他", "“脉大抵与昨晨同”为脉象对比之辞，无具体脉形可录。脉无变化，说明病势稳定，未生新变。结合前日“脉四动半宁”，可知仍属数而和缓之虚象，气血渐复而未全，故仅记脉同，属病程观察之其他类。", []], "2991": ["预后", "“脉四动半有奇”为数，“有上下之神，无涩弱之形”为和。数而和，两尺有神而荡，冲阳太谿脉和，示胃气、肾气渐复。原文“阴阳气血未周，瘦弱未复”，说明脉数主气血未充而非邪热，趺肿愈退，预后向愈。", ["数", "和"]], "2992": ["病机", "六脉虚微，为元气虚弱、心神虚损之象。大病后谷消水去精散卫亡，脾失健运，津液不布，故便利枯渴。脉虚微主正气大虚，与饮食不思、心神虚损相应，治宜补中益气，佐以辛润苦泄，待胃气一充则津液自行。", ["虚", "微"]], "2993": ["预后", "脉四动半，有上下去来之神，为胃气渐复之象。跗肿将平、饮食顺、言亮声响，皆脾胃运化恢复、水湿渐消之征。脉虽未至平和，但已有神有胃，故预后向好，诸症随之减轻。", []], "2994": ["预后", "脉四动半有奇，流利尺滑，为胃气渐充、肾气未衰之象。尺脉滑主下焦水谷之气尚能运化，与跗肿将平、饮食顺相应，示病势向愈，正气渐复，故脉见流利有神。", ["滑"]], "2995": ["预后", "脉四动半有奇，清和流利，为胃气调和、正气渐复之佳象。清和者无邪扰，流利者有胃神，示病后脉象由病转和，脏腑功能渐趋恢复，故为向愈之征。", []], "2996": ["病机", "脉四动半有奇，流利，机神动矣，然久不食则脾胃脉虚弱。数而减半、五动，为胃气渐复而余热未清；脾胃脉虚弱，主中焦气馁，与多日不食相应。心脉未荡，示心神尚欠宁静，故脉象虽流利而机神动。", ["数", "虚", "弱"]], "2997": ["病机", "久病血气阴阳未复，营卫宗气未周，脉当浮弱而涩，或兼虚数。浮为气虚，弱为久病，涩如病蚕食叶、雨沾沙，主血虚气弱。今脉反荡利，乃重病就轻、将复未复之际，脉先荡利，非病与脉相反，实为胃气渐复之兆。", ["浮", "弱", "涩", "虚"]], "2998": ["病机", "脉数次，或浮滑、或弦数、或滑数，两关前甚，为风邪外袭、内传骨蒸之象。浮滑弦数主风热痰火交争，关前甚则病在上焦。秋仲外感失治，邪入腠理骨髓，内作骨蒸而成风劳，与晡热痰红、头痛龈肿、痰嗽声重相应。", ["数", "浮", "滑", "弦"]], "2999": ["兼症", "诸症如失，唯鼻塞耳，脉左右关尚弦。关脉弦主肝脾不和、气机郁滞，余邪未清。鼻塞为肺气不宣，关弦示中焦气滞尚存，故于前方再加二味以调气和营，虑一味之和滞不专而姑置之。", ["弦"]], "3000": ["平脉", "原文述鼻气通畅、头面爽快、饮食自若，六脉平和，为邪退正安之象。虽岁末出入繁而初觉恶风，今已平快，脉不复浮紧，故断为平和，非病脉。", ["和平"]], "3001": ["平脉", "前服升葛诸症速痊，昨似风寒而脉既平和，知表邪已微，不可过服表剂，亦不可峻补。脉平为正气未伤、邪不内陷之征，故宜合补益汤料调之。", ["和平"]], "3002": ["病机", "吐痰泻利、四肢怠倦，脉左关弦数右弱。左关弦数乃肝木乘脾、湿热内扰；右弱为脾土受困、中气不足。弦数主邪郁，弱主正虚，故病机属土虚木乘、湿热吐泻。", ["弦", "数", "弱"]], "3003": ["病机", "小腹弦缩、饮食不甘、屎结尿数、肛门肿痛脓汁不断，脉弦弱数。弦为肝郁气结，弱为脾虚，数为郁热酿脓。弦弱数并见，示肝郁脾虚、湿热下注成肛痈。", ["弦", "弱", "数"]], "3004": ["病机", "壮年患浊茎痛发疳，愈后清汁不干梦遗，兼淋浊阴囊肿核，脉数而弦。数为湿热内盛，弦为肝经郁火，湿热下注精室溺道，故主淋浊、梦遗、阴肿。", ["数", "弦"]], "3005": ["病机", "目疾上盛下虚，饮食不成肌肉，脉举之似缓、按之全无。缓为胃气本象，然按之全无则中虚无力，非真缓也。示脾胃虚馁、气血不充，故上盛下虚而肌肉削。", ["缓"]], "3006": ["病机", "疟后嗳气嘈杂、腋汗腰痛足弱、疝动溺黄、脐腹痛、夜寐身麻、右胁筑块，脉弦而少数。弦主肝郁痰结，数少为郁热伤阴，疟邪久羁、肝脾失调，故见症纷纭。", ["弦", "数", "少"]], "3007": ["病机", "身体衰弱、吐痰、胸痛上气、不寐、小腹无力，脉细数弱而不调。细弱为气血两虚，数为虚热扰神，不调示阴阳失和。虚劳内伤、心肾不交，故胸痛失眠。", ["细", "数", "弱"]], "3008": ["病机", "上部滑数，下部五动弱，示上焦痰热壅滞而肾元不足。右喉结软核、临夜咽干口渴，为痰热结于咽喉；嗳出气则胸宽、不嗳则紧，乃气机郁滞、痰随气聚。滑主痰，数主热，上部独显则病位偏上；下部弱为下元虚象，故本段以痰热气郁为主，兼肾虚。", ["滑", "数", "弱"]], "3009": ["病机", "下疳愈后耳鸣身痛，一医用药鸣定而呕逆，脉转浮细弱。浮为虚阳上浮，细弱为气血两虚。下疳久耗阴精，耳窍失养故鸣；身痛无定所乃血虚不荣。药后呕逆，是胃气本弱、更被药扰。脉浮细弱正合虚人外浮、中气不足之机，非实邪为患。", ["浮", "细", "弱"]], "3010": ["病机", "疮愈后伤风吐痰，左手足不便、左胁冲气、左耳鸣聋、脚膝弱，脉左右上部浮弱数、下部弱数。浮弱数为上焦气浮兼热，下部弱数为下元虚而热扰。疮后阴血耗伤，虚风挟痰上扰清窍，故耳鸣不闻；气血不充经络，故偏废脚弱。总属上实下虚、虚风痰热之机。", ["浮", "弱", "数"]], "3011": ["病机", "头痛不食吞酸上气、耳聋鸣、目昏足膝麻痹、舌强咽干、眩晕吐痰、健忘遗精、小便溷浊，脉上部弱数、下部似滑。上部弱数为上焦气阴不足而虚热上浮，下部滑为下焦痰湿内蕴。虚热挟痰上扰清窍则眩晕耳鸣，下注则遗精溷浊；本虚标实，上虚下实之候。", ["弱", "数", "滑"]], "3012": ["病机", "日晡潮热、头面无汗、四肢觉冷、恶闻食气吐逆、将发斑、头痛，脉沉数或弦数。沉为邪郁于里，数为热，弦为气机郁滞。热郁阳明不得外达，故潮热无汗而肢冷；热毒内蕴迫血外发则见斑；胃气上逆则吐逆。脉沉数正是里热郁结、将发斑疹之机。", ["沉", "数", "弦"]], "3013": ["预后", "气郁腹围作聚、少食白浊，脉左右俱涩，五动一止或三动一止。涩主气滞血少，结代主脉气不续。气郁日久，气血瘀滞，脉道不利，故见涩而歇止。医断为恶候，原文引「疝之变症，恶候百出」，说明此脉示病深根固、变症难测，属预后不良之象。", ["涩"]], "3014": ["其他", "本条为初用、次用、终用方药记录。次用三和散后觉脐上下气动，脉三十动一止、二十五动一止，为气机攻动、脉气不续之象，较前涩而止者歇止更频。终用方转用人参干姜肉桂温补，佐黄柏知母清降，示由行气攻散转为温补兼清，属治法用药过程，非单纯脉诊主病。", []], "3015": ["主病", "因食鱼生腹痛、左甚作泻，常患腹胀、面赤上气，脉实。实脉主邪气盛。食生冷伤中，积滞内阻，腑气不通则腹痛作泻；气滞壅盛则腹胀；面赤上气为实热上冲。脉实与腹满面赤上气相应，说明此腹痛腹胀属食积气滞、邪实内结之证，非虚寒所致。", ["实"]], "3016": ["病机", "脉沉细无力，沉主里，细主阴血不足，无力为气虚；或细动似弦，弦主痛、主肝郁。患者用心太过，耗伤心脾，阳气虚衰，故小腹冰冷、腰脊冷痛；腹内如转索、肚腹如絮柔痰支心下，为寒痰内结、气机不畅之疝瘕。脉症合参，病机为阳虚寒凝、痰气交阻。", ["沉", "细", "虚", "弦"]], "3017": ["病机", "脉滑数，右关无力。滑主痰湿，数主热，右关候脾胃，无力为脾虚。患者肚弱伤食，脾运不健，痰湿内生，郁而化热，故右胁痞气、脐下亦然；痰阻气机则肩背紧、痰支咽喉；痰热扰心则怔忡；口舌咸、便燥为脾虚湿停、津液不布。病机为脾虚痰热中阻。", ["滑", "数"]], "3018": ["病机", "脉七动无力，即数而无力。数主热，无力为虚。产后丧孩，情志抑郁，阴血亏耗，虚热内生，故晡时发热、盗汗、面赤；脾虚不运则不食、体瘦弱；虚火灼津成痰，结于项侧则生疬；经水或居为血海失调。病机为阴虚内热、脾虚痰凝。", ["数", "虚"]], "3019": ["预后", "脉左寸不应，余部浮弱，或弱数五动半。浮弱为卫气败，弱数为营气将夺，左寸不应则心阳衰微。劳役后泻，面肿色青黄、痰喘不眠、言语呢喃，皆脾肾阳衰、痰浊蒙窍之危候。虽药后外症悉平，而脉不复，终至不救，故曰弱则卫气败，弱数营将夺，主预后不良。", ["浮", "弱", "数"]], "3020": ["病机", "脉滑主痰湿内蕴。患者咳嗽，身暖愈嗽，说明痰湿内伏，得温则痰动气逆，故咳嗽加剧；饮食、睡卧时亦嗽，乃痰湿随气上逆所致。脉滑与痰湿之咳相应，病机为痰湿蕴肺、肺失宣降。", ["滑"]], "3021": ["病机", "右脉滑，滑主痰湿。棱骨痛五六年，兼咽干、龈肿、头痛、面目肿，为痰湿郁久化热，循经上攻头面，阻滞经络，故痛肿并见。右脉候肺脾，滑脉主痰，说明痰湿内盛为病本，病机为痰湿化热、上扰清窍。", ["滑"]], "3022": ["病机", "脉五动，即一息五至，稍数于平脉。前年患疸，愈后右胁筑块，左足麻痹而弱，左半身不便，耳鸣、梦泄，为湿热久蕴，肝脾失调，痰瘀互结，阻滞经络，气血不能濡养肢体。脉数主热，示余邪未清，病机为湿热痰瘀阻络、气血不荣。", ["五动"]], "3023": ["病机", "脉弦涩，弦主气滞、主饮，涩主血少、主瘀。六旬男，伤风后咳嗽夜剧，头汗如流，为年高气阴不足，痰饮内停，气机郁滞，血行不畅。夜剧者，阳虚阴盛，痰饮乘夜上逆；头汗如流，为虚阳上越、津液外泄。病机为痰饮内停、气滞血瘀、虚阳上浮。", ["弦", "涩"]], "3024": ["病机", "痰嗽兼脚腿痹弱、腰腹沉重，是痰湿内蕴、下流经络之候。脉滑主痰，数主郁热或邪扰，弦则示痰阻气机、筋脉不利。秋日似伤风，为外风引动内痰。滑数、弦数并见，说明痰热与气郁并存，故既见咳嗽，又见痹弱沉重，病机重在痰湿阻络、气机不畅。", ["滑", "数", "弦"]], "3025": ["病机", "鱼口愈后结块，手足时发红点，脉实，说明余毒未清、气血壅滞。实脉主邪气盛而正气未虚，结块为痰瘀毒邪凝聚，红点乃毒热外透之象。脉实与此相应，提示病机为毒瘀互结、壅遏脉络，非虚证可比，治当消散通络。", ["实"]], "3026": ["病机", "内障失明兼头重耳鸣、鼻塞眼暗上气，脉左浮弦、右弱弦。浮弦为风阳上扰、清窍不利，弱弦示中气不足而肝木偏亢。前用补中益气、益气聪明等剂右眼复光，今因路途劳神复发，说明劳倦伤脾、清阳不升，风阳乘虚上干，病机属脾虚气陷兼肝风上扰。", ["浮", "弦", "弱"]], "3027": ["病机", "性急而左胁冲动攻筑，头痛目眩、吐痰鼻塞、盗汗晡热，脉滑而无力带弦。滑主痰，弦主肝郁气逆，无力示正气不足。肝郁化火、痰随气升，故见冲筑、头痛目眩、吐痰；晡热盗汗为痰热内扰、营阴不守。病机为肝郁痰凝、虚实夹杂。", ["滑", "弦"]], "3028": ["病机", "八旬老人休息痢二年，又伤食泄利加重，呕吐头痛腹满，脉弦细。弦为肝木乘脾、气机郁滞，细为久痢阴血耗伤、正气已衰。高年久痢，脾肾俱损，肝木犯土，故泄利与呕逆腹满并见。脉弦细正示正虚邪滞、肝脾不和之病机。", ["弦", "细"]], "3029": ["病机", "咳血兼寝汗，脉数。数脉主热，热灼肺络则咳血，热迫营阴外泄则寝汗。咳血与寝汗并见，说明热在肺与营分，阴液受灼。脉数为火热内盛之征，病机属肺热伤络、营阴不守，故血外溢而汗出。", ["数"]], "3030": ["病机", "内痔结粪疼痛，夜甚，脉左弦尺弦实、右浮弦五动余。弦主痛、主气滞，实主邪壅，尺实示下焦湿热瘀结，浮弦为风热上扰。痔结粪痛夜甚，乃湿热瘀血壅阻魄门、入夜阴盛而痛增。脉象示下焦实滞兼风热，病机为湿热瘀结、气血不通。", ["弦", "实", "浮"]], "3031": ["预后", "疳疮逾年不愈，状如烛残，脸肿遗脓，脉弱散而似滑，或弱数。弱散为气血耗败、正气涣散，似滑为腐脓痰浊未清，弱数示虚热。疮久形损而脉见散弱，是正虚邪恋、气血难复之候，故列于预后，提示病深正衰、缠绵难愈。", ["弱", "散", "滑", "数"]], "3032": ["病机", "脉动而弱，动为邪气搏结、气血相争，弱为正气不足。疮毒下疳愈后肢体弱，两腿紧痛，缺盆肩井发块或溃或愈，乃余毒未清、气血已伤，正虚邪恋之象。脉动示毒邪尚在搏结，脉弱示气血亏虚不能托毒，故见溃愈反复、肢体无力。", ["动", "弱"]], "3033": ["病机", "左脉弦数，右弦数弱。弦为肝风内动，数为热，弱为气虚。患者右手风战、唇缓舌强、不能言语，显系肝风挟热上扰清窍、筋脉失养。左弦数主肝经风热有余，右弦数弱示气分不足而热郁，故晨起发作、口无食味，属风热内动兼气虚之候。", ["弦", "数", "弱"]], "3034": ["病机", "脉浮滑数，浮为邪在肌表，滑为痰湿或血盛，数为热。痘疮发热见点，经水适行，满面根窝不润、咽喉干渴、肌体尚热，乃痘毒炽盛、热入血分，兼经水适行致血虚而毒滞。浮滑数示表热与血热并见，故用四物补血、葛根解肌，使脉自和。", ["浮", "滑", "数"]], "3035": ["病机", "脉虚缓，左尺涩。虚缓为气虚，涩为血少或气滞。年六十余头项肿痛不能摇动，前医误用败毒散耗气，致中气下陷。左尺涩、转身皱眉、眼看身下，知素患脱肛，乃气虚下陷、清阳不升之证。脉虚缓正合补中益气升提之法。", ["虚", "缓", "涩"]], "3036": ["病机", "两手弦数六动余，弦为肝郁，数为热，六动余为脉数太过。两胁有物冲上、口干燥、头痛目眩面热足冷、便涩少，少思虑则发，显系肝气有余、郁而化火，前医补之过致脉数不减。服药后脉五动，示郁热渐退，故曰必有十全。", ["弦", "数"]], "3037": ["病机", "脉浮滑，浮为气虚阳浮，滑为痰湿壅盛。肥白之人常用心机，猝然晕倒、痰壅喉鸣、鼻鼾，乃气虚痰厥、痰随气上蒙蔽清窍。虞天民谓肥人多湿作痰治，脉浮滑且喉鸣鼻鼾，正合痰厥之机，故用三生饮加人参以益气化痰。", ["浮", "滑"]], "3038": ["病机", "左寸沉数，关尺沉带细涩，右三部沉数、寸数大。沉为热郁于里，数为热，细涩为阴血不足兼滞。热郁于中不得上散，胃中火滞，故上部多见色黄。脉见乎上而寸数大，示郁热偏聚上焦，胃火滞而阴血受灼，故细涩并见。", ["沉", "数", "细", "涩"]], "3039": ["预后", "九日脉同前，但左寸些浮而和。前诊左寸沉数，今转些浮而和，示郁热渐透、气血渐调，为向愈之兆。故本方去薄荷之散，加当归防风秦艽以养血疏风通络，脉象由沉数转浮和，正合病情好转之预后判断。", ["浮", "和"]], "3040": ["病机", "左尺沉弱为肾气不足之象，然已'安'，说明较前好转；右手机神动荡，是阳气未靖。原文谓'不似昨朝脉之沉涩'，沉涩主阴血滞涩、阳气郁遏，今涩减而尺微弦，弦为木气初动，示肾水渐复而肝木尚欠柔和，病机由郁滞转向虚中夹郁。", ["沉", "弱", "涩", "弦"]], "3041": ["病机", "寸脉数大，数为热、大为火盛，寸候上焦，故断'热郁于中不上散''胃中火滞'。用薄荷防风升散，致'郁火升动'，肌肤热不退。原文以'火炎则水干''燥万物者莫甚乎火'推演阴热将发、羸瘦不生肌肉、善谷，皆火盛耗阴、传化过速之机，故以苦寒甘凉泻火存阴。", ["数", "大"]], "3042": ["病机", "脉气由沉渐浮，是郁热自里向外升动之征。原文谓'热郁自得升动'，浮脉主邪出于表、阳气外达，故知郁火有外透之势；然'不无热动'，说明浮中仍带热象，尚未全平。此为郁热外达之正治效验，脉浮与肌肤热相应，属病机转枢之候。", ["浮"]], "3043": ["其他", "本段脉象失录，仅记'热申时发至亥时'，属申酉至亥时定时发热。申时属膀胱、酉时属肾，热发于此时段，提示阴分伏热、阳入阴分而争，与前期郁火伤阴之病机相承。因无脉可凭，只能就发热时辰推断热在阴分，不能据脉立论。", []], "3044": ["治法", "脉象失录，本段主旨为便结加桔梗以升气通便。原文'谓其气少升，则大便通矣'，是取升提肺气、气机升降相因之法，非单纯攻下。反映前证热郁气滞、腑气不降，故以升助降。因脉缺，病机只能从'大便燥结''气少升'推知为气机郁滞、津亏肠燥。", []], "3045": ["治法", "脉象失录，记'因数日便结，制通大便方'。数日便结示热灼津伤、肠腑传导失司，前用桔梗升气未效，故转制通便之方。此段属治法记录，病机当为燥热内结、津液不足，与前述'火炎水干'之阴虚燥热一脉相承，因无脉象，不作脉诊推断。", []], "3046": ["病机", "六部些数而和，数而未甚、尚有胃气，故曰和；然两尺沉涩，沉主里、涩主滞，尺候肾与下焦，示肾阴不足、下焦血滞；右寸弱，寸候肺，肺气亦虚。合观为热势渐退而气阴两伤、下焦郁滞未解，故数中带涩、和中有弱，属虚实夹杂之候。", ["数", "和", "沉", "涩"]], "3047": ["病机", "原文谓'脉数虽和，沉而无力'，数主火，沉而无力则为'几而无水'，即阴液将竭、火无所附。引经'一水不胜五火'，说明五脏之火偏亢而真水不敌，故以泻火存水为治，佐陈皮甘草养胃气、石斛清肺源。脉数而沉无力，正是火盛水亏、本虚标实之机。", ["数", "沉"]], "3048": ["预后", "原文以“脉神旺长”为佳，反衬“涩滞”为病。脉神旺长示正气尚充、胃气未败，虽邪热致阴时发热、便通，仍属可调；涩滞则营卫不利、邪滞血分。故以脉神旺长为顺，强调“调其气而和之”，属预后判断。", ["长", "涩"]], "3049": ["平脉", "“脉六部和带少弱之意”指六部脉虽和缓而略偏弱，非病脉之弱，乃胃气柔和、邪退正复之象。前有邪热，今脉转和而少弱，说明邪气渐去、正气未复，属病后平脉，故仅记晨脉以观转归。", ["弱"]], "3050": ["病机", "左脉和而右寸关涩，右寸关主肺胃。涩为血少气滞、郁结不行，故断“恐是胃口闭郁”。左和示肝心无病，右寸关涩独见，说明郁在肺胃，气机不畅，与胃口闭郁相应，属病机分析。", ["涩"]], "3051": ["兼症", "原文脉失录，仅述“申时热发，胸膈烦热，咳嗽”。申时热发属阳明或肺热，胸膈烦热、咳嗽为热郁胸肺、肺失清肃之兼症。因无脉象可凭，故只就症候言病机，属兼症记录。", []], "3052": ["治法", "“脉沉而致嗽”说明沉主里、主气滞，香附砂仁虽止下，但恐其辛温耗气、引邪入里致嗽，故“宜去香砂”。脉沉为里气不和，嗽因药扰，故去香砂以调气，属据脉议治法。", ["沉"]], "3053": ["病机", "右寸关浮大带涩，右寸关主肺胃。浮大为邪热壅盛于上，涩为气滞血少、郁结不通。浮大而涩并见，说明肺胃热壅而气机郁滞，热郁于中，与胸膈烦热、咳嗽等症相应，属病机分析。", ["浮", "大", "涩"]], "3054": ["治法", "原文注“尺脉沉火不息故暂用矣”，尺沉主肾，沉而火不息为肾经郁火。因肾无实不可轻泄，故暂用黄柏二分以清肾火，待火息即止。此据尺脉沉火而设暂用之治，属治法。", ["沉"]], "3055": ["病机", "右寸浮数，浮应秋、肺金独旺，数为热。用枳柴发动右阳、二母润肺金，药后“脉得和，喘少热微”，说明浮数乃肺热郁遏、右阳不宣之病机，得和则热退喘减，属病机与转归。", ["浮", "数", "和"]], "3056": ["预后", "前诊右寸关浮数，今减大半而敛，六部亦和而敛，是浮数之邪渐退、气机由张转收之象。浮数主热在表分，减大半则热势已杀；敛为胃气收敛、脉道不散，故知病向愈而非传变。原文以『减大半而敛』并言，正示邪退正复之机，非主新病。", ["浮", "数", "和", "敛"]], "3057": ["治法", "右关土位而脉弦，是木邪泄土、土中挟木之象，故用芍药酸寒敛木以治土热。今脉已和，则木不乘土，芍药酸收反恐碍和，故去之。原文『右关土位脉弦，乃泄土中之木』点明弦为木旺克土之机；『今脉和故去之』示脉和则邪已解，治法当随脉转，不可执方。", ["弦", "和"]], "3058": ["预后", "左三部如无力，是阴血不足、肝脾之气未充；右上部始得平和，则肺胃之气渐复。嗽止、夜热退、小便些淡，皆邪退正复之征。原文以『始得平和』与『如无力』对举，说明病势由剧转缓，然左脉仍弱，阴分未全复，故属向愈之候而非全安，须继续调养阴血。", []], "3059": ["病机", "燥症本应发热，反见恶寒，原文以『六脉无寒热之至』释之，谓脉中不见寒热偏胜之象，非真感外寒，乃燥伤阴血、阴不敛阳而外怯。阴血虚则阳气失附，故恶寒；脉无寒热之至，正说明非表邪实寒，而是内燥致虚。此段以脉辨恶寒之因，归之于阴血虚。", []], "3060": ["预后", "六部和而弱，和则胃气未败、脉道不乖，弱则正气尚虚、气血未充。前数日脉浮数、弦、沉涩等邪象渐去，今见和弱，是邪退而正未复之候。原文单举『和而弱』，示病势平稳向愈，然弱为不足，须防虚而再变，故属预后判断而非主病之脉。", ["和", "弱"]], "3061": ["病机", "左寸发动，关尺沉，右寸关沉涩如有物应指，尺沉数，是燥屎内结、腑气不通之象。沉涩应指如有物，原文断为『燥屎也』；动为气机被阻而躁动，数为郁热。金燥火郁日久，润剂不效，脉见沉实应指，故宜推下。此段以脉定燥屎内结之病机，非单纯燥热在表。", ["动", "沉", "涩", "数"]], "3062": ["预后", "右关浮涩，右关属脾胃，浮为气机外达、涩为津液未充。前日右寸关沉涩如有物，今转为浮涩而『颜色轻和』，是燥屎已下、郁结渐开之象。浮涩不主实邪，乃邪去而津未复、脉道尚欠流利，故原文以颜色轻和佐证病势向安，属预后之脉。", ["浮", "涩"]], "3063": ["病机", "两寸实数，寸主上焦心肺，实为邪壅、数为热盛，故见微热而嗽。原文谓『寸热而发于夜，宜降阴耳』，是热郁上焦、入夜阴气当降而热不降，故发夜热与嗽。实数并见，说明非虚热，乃上焦实热壅遏，治当降阴以泄上焦之热，此段以脉明病机与治法方向。", ["实", "数"]], "3064": ["病机", "脉左三部沉而缓，沉主里，缓主湿或脾虚，寸些大、右寸关大，示里虚湿滞，气机不畅。沉缓为脾虚湿困之象，大则虚阳外浮，故病机在脾虚湿盛，气不运化。", ["沉", "缓", "大"]], "3065": ["病机", "左脉沉中些数带弦，沉主里，数主热，弦主郁，左脉不浮泛则热郁于里不易退；右寸关大而冲上，应指如有物，为胃有积滞。高年病久，不宜重加寒降，宜少甘温以生达生气，使脉浮泛，后再推下。", ["沉", "数", "弦", "浮"]], "3066": ["病机", "左三部俱平，右上部些数，下部平，大抵共见缓弱。缓弱为脾虚气弱之象，数则虚热，故用补剂。脉象示正气渐复，虚象未全退，病机在脾虚气弱，当以补益为主。", ["数", "缓", "弱"]], "3067": ["病机", "左三部数沉中有生动之机，右寸关数有泛发之气，尺涩。数主热，沉主里，生动之机示正气尚能抗邪；尺涩为阴血不足或湿滞。北政之年太阴司天右尺不应，故不论右尺。病机为里热未清，阴血略伤。", ["数", "沉", "涩"]], "3068": ["病机", "左上部数有浮泛之气，下部起动似数，右寸平，关平而长，尺似涩。数而浮泛为热有外达之势，关长主气机尚畅，尺涩为下焦阴血不足。病机为热邪渐透，阴分略亏。", ["数", "浮", "长", "涩"]], "3069": ["病机", "左上部脉和，尺弦数，右寸关和，尺些数。弦主郁主痛，数主热，尺部弦数示下焦郁热或肝经郁热。上部脉和，病势较缓，病机为下焦郁热未清。", ["弦", "数"]], "3070": ["病机", "左三部平少数，尺有生发之气，右寸缓，关长，尺涩带缓。少数为余热未清，尺有生发之气示肾气渐复；右寸缓、关长、尺涩带缓，为脾虚湿滞。病机为余热未清，脾虚湿滞。", ["数", "缓", "长", "涩"]], "3071": ["病机", "左寸平，关数些大，尺平有根起浮之形；右寸平，关长而大，尺平。六部虽平，有数脉之形，数主热，大主虚或实，长主气机有余。病机为热邪未净，气机尚旺，有外浮之势。", ["数", "大", "长", "浮"]], "3072": ["病机", "两关脉大，关候中焦脾胃。脉大主邪气盛或正气浮越，此处未言他部，独举两关，提示中焦气机壅滞或肝脾不和，气血偏聚于关部。结合上下文连续数日诊察，当属邪正交争、气机升降失常之象，非单纯虚证。", ["大"]], "3073": ["病机", "右关些长，右关候脾胃。脉长主气机有余或邪气留滞，些长示程度不剧。较前两关脉大，此段右关独见长象，说明中焦气机仍有郁滞，但较前略缓，病势未退而稍减，属脾胃气机不畅之征。", ["长"]], "3074": ["病机", "左上部些数，尺沉阔，右寸关大，尺阔大低，六部些数。数主热，沉主里，大主邪盛。左尺沉阔、右尺阔大低，示下焦水湿偏盛；寸关大数，示上中焦有热。整体为湿热内蕴、上下气机不调之象。", ["数", "沉", "大"]], "3075": ["病机", "左寸关些数，尺数而沉细，右寸些数而些大，关数而大，尺平，六部些数，隐隐有上升之气。数主热，沉细主阴伤，大主邪盛。左尺沉细数示下焦阴亏有热，寸关数大示上焦热盛，上升之气为热势上炎之征。", ["数", "沉", "细", "大"]], "3076": ["病机", "左寸关些数而和，尺有敛起上行之意，右寸平些数，关大尺平。数而和示热势渐缓，尺敛起上行示下焦气机有升发之象。右关大仍示中焦气机偏盛。整体较前数大之象稍和，为邪热渐退、气机欲复之候。", ["数", "大"]], "3077": ["病机", "左三部平和有圆活之意，右寸和，关尺数中有动动之意。左脉平和圆活示正气渐复，右关尺数中带动，数主热，动主气机躁动不安。右关尺候中下焦，示中下焦仍有郁热扰动，气机未全宁静，较前数大之象已减。", ["数", "动"]], "3078": ["病机", "左三部平不泛起于上而中体大，右上部数中冲动少和。左脉中体大示阴血有充但气机偏滞，不泛起于上示无上逆之势。右上部数中冲动少和，数主热，冲动少和示气机躁扰欠和。整体为气机渐平而余热未清之象。", ["大", "数"]], "3079": ["病机", "左上部平和，尺中有发动圆活之意，右寸关些数而大，尺中少动。左尺发动圆活示下焦气机渐复，右寸关数大示上中焦余热未清，尺中少动示下焦扰动已减。整体为邪热渐退、气机向和之候，病势趋缓。", ["数", "大", "动"]], "3080": ["病机", "左上部数、右上部些数，示上焦有热；关数而些大，为中焦热势偏盛。然两尺圆活利动，是下元尚存生机，故病机重点在上中二焦之数热，而非根本虚败。尺微则下焦略弱，数大与微并见，提示热扰于上而根气不足，属虚实夹杂之候。", ["数", "大", "微"]], "3081": ["病机", "六部大抵微而有些些数意，原文断为「脉微气微」，正言正气衰微、推动无力，故见气急，乃「不能上下」之升降失司。两尺之微尤显下元不足，故治法在「补下」，使根本得充，则寸关虚数自息。此段以微为本、数为标，主下虚气逆之病机。", ["微", "数"]], "3082": ["病机", "左三部些数中带圆活升降之意，是虽有热而气机尚能流转；右寸圆活，关数而虚大，虚大为中气不足兼热，数则热象。尺平示下元未伤。合观之，病机为中焦气弱、虚热内扰，而脾胃升降之机未绝，故脉见圆活而非僵数。", ["数", "虚", "大"]], "3083": ["病机", "左三部和平但少力，是阴血虽和而气分不足；右三部圆活，关些些数，为脾胃略蕴虚热。全段以「和平」「少力」「圆活」并见，说明病势已趋缓和，正气渐复而余热未清，关部些数即中焦余热之征，非实热壅盛之候。", ["数"]], "3084": ["病机", "左三部圆活有生气，尺脉二十余日未得此机神，是下元生机渐复之佳象。右关些数，为中焦余热；寸尺似沉涩而微，沉涩微并见，示气血运行不畅、阳气不足。合观之，病机为下元渐复而中上二焦余热未清、气血尚欠流畅，属恢复期虚实并见之候。", ["数", "沉", "涩", "微"]], "3085": ["病机", "左三部和缓而尺些弱，是阴分渐和而下元偏弱；右寸沉而缓，关些大数，尺沉而弱。关大数示中焦有热，寸尺沉弱缓则阳气不振、推动乏力。合观之，病机为中焦蕴热而脾肾阳气偏弱，热不甚而虚象明显，属虚中夹热、下元不足之候。", ["缓", "弱", "数", "大"]], "3086": ["病机", "左上部和，右关大些数，是上焦已和而中焦热势偏盛，大数为脾胃蕴热之象。然两尺活动而和，下元生机流畅，故病机重点在中焦之热，而非根本虚损。尺和则热有出路，治当清中焦之热而不伤下元，脉象示病位偏于关部。", ["数", "大"]], "3087": ["病机", "左三部融和、尺有生气，右寸和而关尺旺，六部皆有圆活之机。原文以「融和」「生气」「圆活」连言，示气血调畅、脾胃旺盛、下元充盛，病机为正气恢复、脏腑功能和调之象，非病脉，属向愈之候，与前述数大微涩诸段形成对照。", ["和"]], "3088": ["平脉", "原文谓「同晚脉和如早脉，但右关长，尺寸和」，脉和示气血调匀，右关独长，关候脾胃，长而和缓为胃气尚充、脾土健运之象，非病脉；尺寸俱和，则上下气机无乖。全段以脉之和平为主，故归平脉，提示中焦略有偏旺而整体无病。", ["长", "和"]], "3089": ["病机", "「左三部如绵裹石，隐隐有生活冲动之气」，绵软之中裹石，是脉体细而兼沉实之象，左候肝肾，绵裹示阴血不足、脉道失柔，石示沉实内着，隐隐冲动为阳气尚存、欲振不能。右寸关些大而和，上焦肺胃尚和。合观为阴弱阳郁、虚中夹实之机。", ["细", "石"]], "3090": ["治法", "原文「尺沉弱，或诊六脉弱而不旺」，沉弱为阳气不振、气血亏虚之脉，尺沉弱尤关肾气。段中提出「补以敛气，而益其神，则旺自得矣」，是据脉弱不旺而立补敛益神之法，故本段主旨属治法，说明脉弱当补，非攻伐所宜。", ["沉", "弱"]], "3091": ["病机", "「早脉如绵裹石而生活动」，绵裹石为细而沉实之象，活动示生气未绝；右关既旺，关主脾胃，旺则中焦有热，故见「日晡热至」。日晡属阳明，热盛于申酉，与右关旺相应，说明脉虽绵裹石而中焦郁热内蒸，属虚中夹实、阴弱阳亢之病机。", ["细", "石"]], "3092": ["病机", "原文「左上部冲动流利，下部旺动，右三部活动，六部动且大而数」，动为气机躁动，大为邪盛，数为热象，六部俱动大而数，示阳气亢奋、热扰气血，非和平之候。左主血、右主气，上下俱动，说明气血两分皆受热鼓动，属阳热内盛、气机不宁之病机。", ["动", "大", "数"]], "3093": ["病机", "「左上部旺而有力，尺有活动之机，右寸虽和少定神，关大些数，尺有生活」，左旺有力、关大数，示肝胃有热；右寸少定神，为肺气不足、神气不敛；尺有活动之机，是肾气尚存。合观为上有热扰、中有郁火、下元未竭而神气偏弱之虚实夹杂病机。", ["大", "数", "弱"]], "3094": ["病机", "「左关些大而数，寸尺和而缓，右关大数，寸尺和弱」，两关俱大数，关候肝脾，大数为邪热内盛；寸尺和缓为心肺肾尚调，而右寸尺和弱则肺肾之气偏虚。合观为肝脾郁热偏亢于中、肺肾气弱于上下，属中焦有热、本元不足之病机。", ["大", "数", "缓", "弱"]], "3095": ["预后", "原文述服耆参十余贴后「脉神大旺」，停一伏时「脉神又弱」，再加以助脉神。脉神由旺转弱，说明药力一过则元气复衰，根本未固，依赖参耆扶持。此段以脉神盛衰判断正气消长与用药进退，属预后之论，示补益不可骤停。", ["弱"]], "3096": ["病机", "右关脉数，尺脉沉，左三部虽和而右关独数，说明热郁于中焦脾胃；尺沉为下焦气机不畅。脉数主热，沉主里，热在里而不外扬，故关数尺沉并见，提示内热壅滞、气机不得宣通之病机。", ["数", "沉"]], "3097": ["病机", "右关滑数而短，滑主痰湿食积，数主热，短主气郁或痰食阻滞；左关及寸尺些数而和，说明热势不剧而偏于中焦。滑数短并见，为痰热内蕴、胃气壅滞之象，故关部独显而寸尺尚和。", ["数", "滑", "短"]], "3098": ["病机", "左三部缓小而和，右寸小而和，为气血渐复、脉道柔和之象；右关些数更有升动之气，说明中焦尚有郁热未清，气机有升动之势。缓小为不足中之和缓，数而升动则示余热未靖，故整体为邪退正复而余热未尽之病机。", ["缓", "小", "数"]], "3099": ["治法", "原文明言「左三部沉中见数体，而不见弦，现而平沉，则热在内」，沉中见数主热郁在里；右关少数而弱，为脾胃气弱兼有热。故治法「先治其数，后补其弱」，即实者先泻、虚者后补，先清内热再补脾弱，体现泻实补虚之序。", ["数", "弱", "沉"]], "3100": ["病机", "左三部和中有活动之气兼弱，右关些数而往来明白，寸尺和而少数。脉弱为气血不足，数而往来明白为热象尚浅、胃气未败。整体示正气偏弱而余热未清，活动之气渐复，属虚中夹热、正虚邪恋之病机。", ["弱", "数"]], "3101": ["治法", "脉力少而弱，左三部些数中似弱而少力，右三部平和而些数。弱为阴血不足，数而少力为虚热内生。原文提出「宜大补阴血，以燥自润」，说明此脉主阴血亏虚、虚热内扰，治当滋补阴血以润其燥，非苦寒泻热所宜。", ["弱", "数"]], "3102": ["预后", "六部沉而无力曰缓，沉主里、无力为虚，缓为胃气尚存之象。原文谓「老人脉缓，是病之常」，说明高年气血虽衰而胃气未绝，故脉缓不属恶候；但「未能亟起矣」提示正气已虚，恢复缓慢，预后需缓图。", ["沉", "缓"]], "3103": ["病机", "左寸关和有圆活之意，尺弱，右寸平，关些数无力，尺弱。关数无力为脾胃虚热，两尺弱为下焦不足。圆活之意示胃气尚存，然数而无力、尺弱并见，说明虚热未清而肾气偏衰，属脾虚有热、下元不足之病机。", ["弱", "数"]], "3104": ["病机", "脉虚而弦，两寸较大，是心肺两虚而又有痰。虚为气血两虚，弦主痰饮、风动。老年气血两虚，春夏之交火气升泄，虚阳化风挟痰火勃动于中，外阻络脉则右肢不用、舌蹇语涩，内扰神志则神思昏乱、错语少寐。脉症合参，属中络兼腑，病机为气血虚而痰火风动。", ["虚", "弦"]], "3105": ["病机", "此段未言脉，从症测机。痰渐化而火未熄，阳明肠胃津液虚耗，故寐少便闭、痔翻。阳明外主肌肉，内主津液，津液虚则无以濯输肌肉、束筋骨利机关，右肢不仁由此而致。不仁则不能用，总属津液虚耗、络脉失养之病机。", []], "3106": ["病机", "脉象沈滞，大便艰涩，不仁为气血不通。沈滞示气血郁滞不行，涩为血虚津少。老年风闭多责血液之虚，近年痔血去多，血虚则风动。右肢渐知痛痒，是脉络渐有流通之意，但肠胃充和、气通血润尚远，故脉仍沈滞，当以通养阳明为治。", ["涩", "沉"]], "3107": ["病机", "此段未出脉，以症推机。肢体热痒而疼，是血虚风燥所致，络脉如此，肠胃益可知，所以便难必越数日。高年中风大都为血液不充、内风旋扰，便难一症尤为血虚的证。今未入秋而先形内燥，治从清燥救肺、和络养胃，冀府通络和。", []], "3108": ["病机", "脉虚涩，虚为气血不足，涩为血少络滞。烦劳伤阳，阳虚风动，旋扰清空，络脉弛懈，故右肢痛而左肢不用。呕吐痰饮已止，右额微肿而痛，食少便结，此腑络兼中之症，痰为虚痰，风为内风。曾有便血，当燥令尤须远刚用柔，清养阳明、柔息厥阴。", ["虚", "涩"]], "3109": ["病机", "脉得滑而右寸关尤甚，显属肺感风燥未清，痰火上扰脉络。滑主痰，右寸关候肺胃，尤甚则痰火壅于肺胃。忧悲伤肺，风燥伤肺，痰出即火熄，痰不出即火复炽，故舌蹇涎流等症能暂退亦能复盛。此痰火乃外感风燥之火，非内伤虚痰，宜滋肺气、存胃津以化痰。", ["滑"]], "3110": ["病机", "脉寸关俱滑数而促，滑主痰，数主热，促为热盛而气急。冬温风燥之邪实于肺卫，燥热气急，痰浓而少，咳引胸胁隐痛，此冬温容肺之重症。八旬高年津液久虚，邪无出路最易劫津涸液，痰胶气喘，头汗防脱，故以滋气化痰、急救肺以存津液为要。", ["滑", "数", "促"]], "3111": ["病机", "脉象仅得濡缓弦虚，不致模糊难以寻按。濡缓为风为胃，神虚则阳为湿遏，弦为湿酿痰浊。春夏之交感症，风为春之余气，湿为夏之王气，湿温二气薰蒸郁遏，似烟似雾，蒙蔽清明，肺气窒痹不能宣化，则周身之气皆痹，故昏昏如醉、蒸热舌黄、溺赤便闭、㿀疹隐隐。", ["濡", "缓", "弦", "虚"]], "3112": ["病机", "脉象濡滞，濡为湿象，滞示气机不畅。原文谓“暑退而湿未化”，暑湿阻气郁而化热，虽咳嗽疹出诸症渐退，但气火蒸腾、干咳目赤，显系湿浊未化、气机壅滞。濡滞脉正合湿邪黏滞、气郁不宣之机，故治宜甘平淡渗以清气化湿。", ["濡"]], "3113": ["病机", "脉象弦数已平，转为虚弱濡消。弦数主疟邪与湿温郁热，今热退食进而脉见虚弱濡消，是邪退正虚之象。原文谓“气液之消亡甚矣”“津气内夺”，虚体感邪，邪未化而正已疲，故脉虚弱，深虑虚脱骤见。", ["弦", "数", "虚", "弱"]], "3114": ["病机", "脉弦数，弦主痛、主痹，数主热。风寒湿三气杂至，经腑表里皆痹，故寒热咽痛、肢节肿痛、紫斑谵语、便少溲涩。弦数示邪郁化热、痹阻不通，与“喉间痰气有声”“扬手掷足”等症相应，挽救大难。", ["弦", "数"]], "3115": ["病机", "脉涩，涩主气滞血瘀、邪郁不宣。风温上受，郁于肺分，故肿见于上、颈领尤甚、鼻壅痰从腭来，肌肤青紫似癍非癍。涩脉示风温郁肺、气机不利、血行不畅，与风水有别，宜轻扬上治。", ["涩"]], "3116": ["病机", "脉濡数弦，濡主湿，数主热，弦主气机郁滞。原文谓“复感”风温，烦劳伤阳，风温乘隙而入，故微寒而热、咳嗽痰黄夹粉红、气急头汗溺黄。濡数弦示湿郁化热、肺气不降，急宜清热化邪，毋使喘汗复盛。", ["濡", "数", "弦"]], "3117": ["预后", "脉虚小和缓，虚小示邪退正虚，和缓为胃气渐复之象。原文谓“肠腑已通”“寝食俱安热退痰少”，症情已臻安善。脉虚小和缓与热退痰少、耳聪目明相应，示病后体虚而未复，治宜清养肺胃，不宜骤补。", ["虚", "小", "缓"]], "3118": ["病机", "脉虚而弦，虚主正虚，弦主风湿郁阻、气机不畅。肠风下血经年，阳明腑络皆虚；风湿未清，郁蒸为热，故寒热发斑、汗多溺黄、痰壅咳嗽。虚弦示正虚邪恋、风轻湿重，治宜通阳化湿为主，先退郁蒸之热。", ["虚", "弦"]], "3119": ["病机", "脉弦迟，弦主气机郁阻、疝痛，迟主湿滞阳郁。原文谓“湿蒸热郁腑络皆痹”，疝气横膈，升降之气受阻，厥阴不调，阳明壅塞，故右胯疝阻与右髀痹痛相连、转侧屈伸不能。弦迟示湿郁气滞、痹阻不通，治宜疏厥阴、通阳明。", ["弦", "迟"]], "3120": ["病机", "脉滞提示湿邪内阻，气机不畅。患者阳虚湿胜，起居饮食不慎，致胸闷、便溏、梦泄、面黄形瘦、舌白，诸症反复，皆因湿滞中焦，运化失司。脉滞与湿胜之体相应，故治宜丸剂缓图，谨慎调摄。", ["滞"]], "3121": ["病机", "脉弦而数，弦主肝旺，数主热，显属胃不降而肝反升。阳明湿火上蒸，右颧发疡，厥阴湿火亦升，致足大趾痛、气逆由足及腹上至脘胁䐜胀、减食消渴口苦舌黄。脉症合参，宜通宜降，去病即顾正。", ["弦", "数"]], "3122": ["病机", "脉弦数，弦为肝气挟湿，数为热。肝阳循络上行，犯胃过鬲抵咽，致头面肩背气焰所及，汗多少寐烦躁、䐜胀舌黄口渴足冷。今脉弦稍柔和、数象已退，大便渐溏，示湿热未清化，仍宜调肝化湿，主通主降。", ["弦", "数"]], "3123": ["病机", "脉滑大弦搏，滑大主痰湿壅盛，弦搏为肝阳亢逆。秋燥胜于长夏湿热余气，肺胃大肠结涩，津气不行，肝脾升者益升，故便燥、舌边黄燥中心光、口燥胃钝胁腹胀痛。宜滋养肺胃津气，通润大肠，肠通则胃和，痰湿顺降。", ["滑", "大", "弦", "搏"]], "3124": ["病机", "脉小弦数，小为湿阻，弦主肝郁，数为热。秋深晚发，余热蒸蒸，汗多便溏溺黄，胸腹白疹续发，乃湿热余邪未尽，阻痹蒸郁，腑阳未通降，宿痞升逆。治宜疏腑通阳，湿热渐化则痞和。", ["小", "弦", "数"]], "3125": ["病机", "脉濡主湿邪困阻，阳气郁遏。患者嗜酒湿凝，四肢疼痹、乳结核、咳痰稠、体疲、舌黄目昏耳钝，皆湿邪上蒙、络脉不宣所致。络病宜清，腑病宜通，时值夏令，收效难速，故拟和阳化湿、清气宣络缓图。", ["濡"]], "3126": ["病机", "脉濡涩，濡为湿困，涩为血滞。阳虚嗜酒，屡为湿困，腰重、臂痛、疮痍、便难肛痔、囊风腿癣，皆湿邪由阳明深入厥阴，经隧不利。濡涩之脉示湿滞血涩，不宜刚药燥劫，议养阳明以清厥阴，冀其缓效。", ["濡", "涩"]], "3127": ["病机", "脉濡滑缓，濡主湿，滑主痰，缓为胃气尚和。身热已退，大便干而尚顺，耳聪神清食进溺淡黄舌薄白，示湿热渐退，症情向安。此时宜清养阳明，使肠胃通和，则未尽湿热渐次清化。", ["濡", "滑", "缓"]], "3128": ["病机", "脉细弦迟，细为阴血不足，弦主少阳风火，迟则阳明痰滞。原文谓“外风内袭”“胸腹气火上升”，风火痰三邪交织，故见鼻渊齿衄、胸痹痰多、痔疡便难或溏。细弦迟正合少阳阳明风火痰为病之机，非单纯虚寒之迟。", ["细", "弦", "迟"]], "3129": ["病机", "脉弦左尤甚，弦为肝木亢盛之象。原文“五志火动神明内扰”，肝热由于胆寒、脾瘅由于胃滞，故易怒多疑、舌腻口甜、内如焚起灭无定时。左甚者肝阳偏亢，隆冬蛰藏之时宜育阴潜阳，正针对弦脉所主之肝热内扰。", ["弦"]], "3130": ["病机", "脉弦实，弦主肝胆郁热，实为邪气内结。原文“肝胆包络尚有郁热”“郁热之冲原无定时”，故晨易心悸、易怒多疑懊𢙐，目泪鼻血齿痛口干舌黄便溺不了。弦实相因而来，说明郁热非虚，宜清肝用、养肝体以调疏泄。", ["弦", "实"]], "3131": ["病机", "右脉虚凝，左小弦数。虚凝为肺胃气津两伤、秋燥痹肺，小弦数为肝阳内动、邪热未清。原文“秋燥之邪大队尚聚胸鬲”“病邪伤阳”“伤阴”，故寒热咳嗽面浮、耳鸣汗出、腹痛便瘀。脉象示正虚邪恋、阴阳两伤，宜养胃存津、宣肺化燥。", ["虚", "凝", "小", "弦"]], "3132": ["病机", "两关见弦，关候肝脾。素体操劳郁久，心脾营虚为本，复感风燥之火，金不制木，肝阳化风火上扰清空，故齿痛头额颧颊痛、耳脓、烦躁不寐、咽腭干燥、咯血。弦脉主肝风内动，虚实混淆，宜甘凉濡润存津化燥。", ["弦"]], "3133": ["病机", "左脉静小而虚，右关稍有弦象。左小虚为肝营不足、风阳渐熄，右关弦为阳明津虚、燥气未净。原文“燥为虚邪”“素虚之体易受燥邪”，故咽腭燥减而鼻窒、便涩、寐未酣。脉示虚多实少，宜滋养肺胃、充润津液，使金清木平。", ["小", "虚", "弦"]], "3134": ["病机", "六部缓小，右关滑形已退。缓小为胃气渐和、燥火稍杀，滑退则痰热减轻。然原文“咽腭仍干上及于鼻”“鼻息不得卧眠阳明病也”，说明风燥之火仍上伤清窍、津液不能上承。脉虽转缓小，病机仍在津亏燥结，故叠投甘凉而效未大。", ["缓", "小", "滑"]], "3135": ["病机", "原文未出脉名，仅言“八脉郁火尚未清化”。脏燥渐减而稍劳怒即火升鼻干、心神不自主，带重腰酸、左足易热、经来参差色紫黑，皆奇经郁火、冲任不调之候。病机在八脉郁火未清，故宜静剂专清奇经，非独治脏腑也。", []], "3136": ["病机", "脉浮弦数而阳部为甚，浮主燥火外薄，弦主肝木内郁，数主燥热内炽。原文谓'燥火上薄肺金'，秋初至今不愈，鼻干有血、胃钝少纳，皆燥火伤肺胃之津；便溏则肺与大肠两金皆困，老年失血气血俱耗，故脉浮弦数示燥火未清而正气已虚。", ["浮", "弦", "数"]], "3137": ["病机", "右寸及左三部皆近数急，数主热，急主势迫。原文谓外风引动内饮、继引内风，痰饮肝风扰攘不解，咳逆痰薄、左胁引痛、呃逆咽痛、气冲巅顶耳鸣，皆肝阳化风郁而为热之象。脉数急示风火痰饮交争，肺金不宣而肝木易逆，故须清金制木、通阳和饮。", ["数", "急"]], "3138": ["预后", "脉象静小，静为邪退，小为脉和，与'诸恙皆退、胃纳已增、舌色润泽'相应，示风燥之火渐平、津气渐复。惟寐后干咳、得汤饮即痰出、卧须倚枕，是风燥余火易劫津气、肺胃尚欠濡润，故脉虽静小而未全复，治以甘凉濡润滋气存津。", ["小"]], "3139": ["病机", "脉虚凝如毛，虚为肺气损，凝如毛示阳气不充、饮浊内踞；右部间露弦象，弦主饮、主肝逆。原文谓晨咳呕浊、久则哮嗽上气、夜不著枕、行艰报息头汗舌腻，皆饮浊阻肺、气逆不降之候。脉虚而弦，正合'和饮通阳平逆定喘'之治，示本虚标实、饮逆为患。", ["虚", "弦"]], "3140": ["病机", "脉虚濡，虚为肺气损，濡为肺阴不足；右手兼小弦，弦主肝郁。原文谓易感善咳、咳逆痰清，是肺气损而卫外阳弱；多年肺阴已虚，故音气易涩。脉虚濡示肺之气阴两亏，小弦示肝木微逆，故宜滋肺气养肺阴，防失血失音之弊。", ["虚", "濡", "弦"]], "3141": ["病机", "脉左偏弦，左主肝，弦主郁主饮。原文谓肺虚失降、肝郁易升、胃弱饮聚，饮踞于中则外寒一引即动，故咳逆至冬为甚；消渴为肺热，舌苔黄厚。脉左弦正是肝郁化热、饮聚不化之征，故调郁清肝，使肺胃之阳和而热平饮涤。", ["弦"]], "3142": ["病机", "脉体本弦长，今弦兼滑、长兼洪，左尤甚。弦长主肝气有余，滑洪主痰饮挟火。原文谓咳复作痰少不厚、肝气左升腹痛、呕泄始平，是肝升有余、肺降不及，痰滞凝血。脉由弦长转弦滑长洪，示饮咳日久湿痰挟火，故从湿痰挟火之例，非单纯甘温和饮所宜。", ["弦", "长", "滑", "洪"]], "3143": ["病机", "脉弦左仍带滑，洪滑较减，弦为肝气，滑为湿痰，洪减则火势稍衰。原文谓咳势较缓、痰厚者仍少、舌苔白里半黄腻，是饮咳既久挟湿又兼肝气。脉弦滑未除，示肝气湿痰仍踞，故当先清肝化湿以衰其助，兼因时届湿土而制宜。", ["弦", "滑", "洪"]], "3144": ["病机", "原文谓「脉右较平左仍弦滑寸部尢甚」，弦滑主痰饮内停，寸部尤甚说明痰饮壅于上焦肺系。痰饮未和则肺气失清，又挟时令之热上攻咽喉，故见喉糜音欠爽亮。人迎脉盛提示外感时邪，非心阳上亢，故治法取金水化痰兼清外感。", ["弦", "滑"]], "3145": ["病机", "原文「脉象沉弦在手兼数，沉弦为饮，左数为肝胆虚热」。沉主里、弦主饮，饮踞于胃则右降不及，故气逆胃钝、嗳气失气；左数反映肝胆虚热。新寒引动宿饮，身热汗多咳呕络痛，皆饮邪与虚热交争之象，非单纯阳虚可比。", ["沉", "弦", "数"]], "3146": ["病机", "原文「形瘦脉弦，明属湿郁生热，热蒸成痰」。弦脉主郁主饮，湿郁化热蒸痰，痰热恋肺则咳逆已久、身热舌干绛苔厚黄。脉弦在此非肝阳亢盛，而是湿郁痰热内阻之征，故只宜清化，不可补壅助邪。", ["弦"]], "3147": ["病机", "原文「脉小弦，大便未畅，小便又浑，自是湿热未曾净尽之症」。小弦为湿热黏滞、气机未畅之象，非阳虚脉微。胃知味渐思食为胃气渐复，但湿热黏腻难化，故便溏溺浑，宜静养缓调，欲速反弊。", ["小", "弦"]], "3148": ["病机", "原文「脉弦溺黄便溏不爽，总属湿酿为痰，痰气与肝气相抟，阻遏于胆胃之间」。弦主肝郁痰阻，湿痰与肝气交抟，阻遏胆胃，故左膺结肿按之酸疼。积久不清竟能成痈，治宜清肝胆、化湿痰、理气络。", ["弦"]], "3149": ["病机", "原文「细参脉症，不但肝胆火升痰气上阻，且有秋燥之邪乘虚而入，燥火劫金，痰气胶结愈甚」。虽未明写脉象，然由脉症合参知燥火与痰气胶结，无形之病渐致有形左膺之肿，病异源同，故仍用前法濡润通和。", []], "3150": ["病机", "原文「脉右虚弦左沉涩，精气既虚，肺咳难化」。右虚弦为肺胃阳虚、饮聚不化；左沉涩为精血亏虚、脉道不利。饮聚多年痰稠呕酸喘急，皆阳虚饮泛之候，根株难除，惟希作止有时。", ["虚", "弦", "沉", "涩"]], "3151": ["病机", "原文「脉数而大，此属脾胃素虚，气血少资生之本，本郁则乘土，火炎则烁金」。数大为虚火内炎之象，脾胃素虚则气血无源，肝郁乘土、火炎烁金，故干咳痰血、经行迟而腹痛，久延最易成损，调复难速。", ["数", "大"]], "3152": ["病机", "脉虚滞右滑数，虚滞为气血两虚，右滑数为胃中饮浊停聚化热。原文“血去络空胃脉逆上遂至饮聚咳逆”，说明失血后络脉空虚，胃气上逆，饮邪聚于胃，故脉见右滑数；形寒食少便溏上气不得卧，为脾肾阳虚、饮邪上泛之候。此上损及中，病机为气血亏虚、饮聚胃逆。", ["虚", "滞", "滑", "数"]], "3153": ["预后", "脉数而促，数为热，促为急促不匀，主胃气衰败、虚热内扰。原文“血后咳逆至三月余自然胃脉虚易以逆举”，说明失血后胃气虚逆，饮浊虽少而痰浓难出、咳逆不得卧、便溏，为损症及中。脉数促示胃气将绝，故曰“本难挽回”，姑拟静药养胃以阖阳明，属预后不良之候。", ["数", "促"]], "3154": ["病机", "脉濡左小弦数，濡为湿，小弦数为肝胆郁热。原文“肺胃湿热蒸郁伤络则失血阻气则作咳”，说明湿热郁于肺胃，伤及血络则咯血，阻遏气机则咳嗽。右胁背痛、蒸热、舌胖苔黄，皆湿热之征。体虽气血两虚，但湿热为害，故宜急清养肺胃以和络止嗽，毋使久嗽成损。", ["濡", "小", "弦", "数"]], "3155": ["病机", "脉芤虚弦迟，芤为失血，虚为气血不足，弦迟为肝升太过、肺降不及。原文“血屡去则阴亦虚”“肝升太过肺降不及”，说明咳久阳络勃动，失血屡发，阴血亏虚，肝阳上逆。身热晡盛、口燥咽痛、胁痛气逆，皆阴虚阳亢之候。脉尚无燥扰动数之弊，故宜耐心调养，缓缓热退嗽止。", ["芤", "虚", "弦", "迟"]], "3156": ["病机", "脉象弦数，弦为肝郁，数为热。原文“嗜酒之体”“过投辛燥热药动营壅腑”，说明辛燥助热，动营伤络则鼻血，壅腑则腹胀，进肾气丸后腹胀未敛、咳嗽失血失音。弦数示气血乖远、大失冲和，木火刑金，肺失清肃，故见失血失音，病机为燥热伤营、肝肺不和。", ["弦", "数"]], "3157": ["病机", "脉弦搏，弦为肝郁，搏为有力，主肝阳郁勃化风化火。原文“肝阳郁勃化风化火挠金侮土”，说明肝火犯肺则咳嗽失血，犯胃则呕逆不食；左眦赤、两额痛为肝火循经上炎。脉弦搏有力，正是肝阳亢盛、化火生风之象，故急宜清息。", ["弦", "搏"]], "3158": ["治法", "原文为按语，指出“既有咳呕则此种脉症当用清镇如旋覆代赭等”，虽未直接描述脉象，但承前段脉弦搏之肝阳上逆，咳呕并见，故治法当以清镇降逆为主。旋覆代赭汤能镇肝降胃、化痰止呕，适用于肝阳挟痰上逆之咳呕，属治法范畴。", []], "3159": ["病机", "脉象六部皆弦，弦为肝脉，主木火内燃。原文“肝胆郁勃之火过升无制扰动阳络之血遂沸腾而出”，说明肝火有升无降，迫血妄行，故屡发吐血，量多浓厚；脘下气聚上冲、头额胀、嗳气矢气，皆肝胃气逆之候。脉弦为木火内燃、有升无降之征，故治当平逆镇肝降气安络。", ["弦"]], "3160": ["病机", "脉象虚弦，虚为肝胃血虚，弦为气逆。血止后诸恙已平，惟脘有瘀痞、气逆辄咳、便溏不畅、舌鲜口燥，乃肝胃血虚而气易逆，故宜柔剂通养。", ["虚", "弦"]], "3161": ["病机", "脉濡如弦，弦为饮，濡为气虚。酒热引动心胃之火，阳络血溢，胃络空而水谷精微酿痰浊，阻遏升降，冲和之气失布，故脉见濡弦，宜和阳治饮为先。", ["濡", "弦"]], "3162": ["病机", "脉象弦数，左甚于右，弦主肝阳，数主热。暑湿之邪纠缠四月，络气震动血溢，湿由气分伤及血分，肺胃失降则肝阳易升，故身热舌黄胸闷便溏喉痒咳，宜通络化瘀清邪。", ["弦", "数"]], "3163": ["病机", "右三部虚涩和静，左三部数象已退，小弦未尽。虚涩为血去阴伤，小弦为肝郁不调，挟内蕴之湿蒸为热，上熏则食少咳逆，故脉象虽静而肝郁湿蒸未清，须通腑清湿调肝肃肺。", ["虚", "涩", "数", "弦"]], "3164": ["病机", "左部迟濡，右关尺同，右寸濡滑。迟濡为阳虚湿胜，濡滑为痰湿内蕴。湿热郁蒸肺胃，非伊朝夕，故舌苔凝黄、溲黄、阴囊湿痒、痰咳厚而喉痒，宜滋润肺胃三焦以理气化存津。", ["迟", "濡", "滑"]], "3165": ["预后", "右细促数，左细弦数。细为阴血亏，促数为阳不恋阴，弦数为木火内炽。酒客吐血多年，血去既多，胃脉上逆，入夜著枕即咳，论症颇非轻浅，脉象示阴伤阳扰，预后堪虑。", ["细", "促", "数", "弦"]], "3166": ["病机", "脉右浮滑数，浮为热蒸于上，滑数为痰热内蕴。肺胃素有郁热，烟酒辛泄耗气，咳久咯血，热势夜甚，头晕舌黄，此胃湿因时而蒸动，故议清气络以消痰化湿除热为先。", ["浮", "滑", "数"]], "3167": ["病机", "脉弦数，弦为肝胆木火，数为热。经行太早阳明不充，咯血后郁怒烦劳即发，热咳时作，舌黄而刺，咳呕便溏，乃肝胆木火挟湿上扰肺胃，宜先清气熄热，莫作虚症用补。", ["弦", "数"]], "3168": ["病机", "脉芤弦，芤主失血阴伤，弦主肝郁。失血屡发三四年，阴血亏耗则脉芤；肝郁化火犯胃，胃热上冲则咳逆痰稠带血、额胀耳鸣头晕口渴；暑热内蕴则胸闷溺黄。故断为肝郁致胃热、血虚复受暑，先清暑化气治标，徐止咳治本。", ["芤", "弦"]], "3169": ["病机", "右脉细弦、左反虚小而静脉左静。细弦为肝邪阴脉，今偏见于右，是木乘中土，胃不降而肝过升，阳络之血上溢不止。吐血屡发、不能左卧、咳而兼呕、滑泄，皆肝胃同病、胃钝舌白之象。左虚小为血症佳兆，治当肝胃皆降，以静药降之。", ["细", "弦", "虚", "小"]], "3170": ["预后", "脉微弱、神虚怯，为阳虚胃弱、根蒂未固之象。血止后咳逆未罢、仍难左卧、畏寒，偏卧是气竭肝伤。脉微弱说明正气大虚，虽血暂止而根本未固，风浪难经，再发可虑。故言血之暂止不足恃，宜乘平时急为补养，属预后判断。", ["微", "弱"]], "3171": ["病机", "脉数主内热，咯血后胁痛咳逆迁延，内热脉数，咳既不止则左胁复痛，自然络血复动。咳久不止最易成损，是阴虚内热、肝络受伤之病机。故急宜养阴滋气，先期热退胁和，然后力图咳止，紧扣脉数与络血复动。", ["数"]], "3172": ["预后", "脉象虚数，虚为阳虚气弱，数为虚热内扰。烦劳嗜酒阳虚久矣，饮咳年余两次失血，先伤气后动营，病势入里，气息短促，故不免有成损之虑。虚数脉示正气已亏而虚热未清，非息心静养不能充复，属预后告诫。", ["虚", "数"]], "3173": ["病机", "右虚而静，左弦而大。弦为肝阳勃动，大则为虚，左膺痛止而复作是肝阳未靖，时冲其络脉。素有嗳气属肝郁，劳冗伤肝，当春木发动之初咯血，皆肝阳上冲、络脉受伤之病机。故宜柔静之剂育阴潜阳，紧扣弦大与肝阳勃动。", ["虚", "弦", "大"]], "3174": ["病机", "脉芤弦虚数，芤主阳络空洞失血，弦为肝，虚数为阳明虚耗、虚热内蒸。吐血经旬去多，寒热盗汗、口腻舌滑，痰涎蒸聚，阳明虚耗极矣。肺火下移大肠则咳止而脏毒下，今复吐血，故急宜充养阳明，为峻补肝肾先导，节劳戒怒防成损。", ["芤", "弦", "虚", "数"]], "3175": ["病机", "脉象沉细虚数，沉细为胃肾两虚，虚数为虚热内扰。咳嗽吐血过多，两年来咳不肯止，内热时寒、痰多食少、舌光口燥、肉削神疲，皆胃肾两虚、虚则成损之象。故治法先宜养胃，不可紊，兼须恬神静养，尚有挽回之望。", ["沉", "细", "虚", "数"]], "3176": ["病机", "脉弦右甚，右脉候肺胃，弦为肝木亢盛之象。原文谓“胃湿内蒸肝阳上逆”，湿郁于胃则脘腹痞胀，肝阳上逆则头胀、汗多、消渴；木火刑金，肺失清肃，故咳嗽痰薄、络血时动。脉弦右甚正示肝胃同病、肺金受侮之机，故治宜清肝胃以理肺。", ["弦"]], "3177": ["病机", "脉芤弦虚迟，芤主失血，弦为木旺，虚迟示暑湿郁阻、胃气不充。原文谓“暑湿蒸郁胃脉逆上络血随溢”，胸闷能食溺黄乃湿郁化热之征；胃络逆上则吐血旬余不止。脉芤弦虚迟正合暑湿蒸郁、胃气上逆、络伤血溢之病机，故急宜清胃理气化邪以和络止血。", ["芤", "弦", "虚", "迟"]], "3178": ["病机", "此段辨似阳虚而实为暑湿蒸郁，关键在“胸闷能食溺黄”三症。脉芤弦虚迟虽似阳虚，然芤主失血，弦主木郁，虚迟可因湿阻气机而非纯虚。原文明言“脉之芤弦虚迟尚未足为凭”，强调凭脉须合症，不可拘泥，故列病机以纠偏。", ["芤", "弦", "虚", "迟"]], "3179": ["病机", "脉虚濡而静，左按良久稍见弦象，虚濡为血脱气弱，弦为厥阴风木内动。原文谓“血后阳明空洞厥阴风木易动难熄”，故见左卧不便、头量耳鸣、口淡便泻、溺短数等症。脉虚濡静示胃气尚和，弦象久按方见示肝风未熄，治宜血脱益气、和胃熄肝。", ["虚", "濡", "弦"]], "3180": ["病机", "脉虚涩，虚为气血不足，涩为冲任瘀滞、血行不畅。原文谓“冲任不足易致逆举”，故咳呕吐血、不能平卧、食少内热、经候愆期。冲任亏虚则气逆上冲，非仅肺胃为病。脉虚涩正合积年虚症、冲任不足之机，调复不易。", ["虚", "涩"]], "3181": ["病机", "脉弦大，弦为湿热郁蒸、木气不舒，大为邪盛。原文谓“肺胃大肠湿热蒸郁久而不化阴阳之络皆伤”，故咳嗽失血、便血溏薄、溺浑。弦大示湿热壅盛、络伤血溢之机，治咳难而治血易，宜先戒酒以绝湿热之源。", ["弦", "大"]], "3182": ["病机", "脉芤虚而静小，芤主失血，虚为气弱，静小示胃气尚和、病势未张。原文谓“心火凌金之咳”“络血妄动烦渴内炽”，乃心火炽盛、肺金受灼、阳络损伤之机。脉静小则症情尚可无碍，但肺金素虚、心火易炽，静养善调不可忽。", ["芤", "虚", "静", "小"]], "3183": ["病机", "脉弦，弦为肝木亢逆、饮瘀内踞。原文谓“阳虚痰饮内踞久则胃络血涌”，血去后痰饮瘀血郁于中宫，故喘咳短气、胸次隐痛、舌黄。脉弦示胃脉逆上，血家大忌，论症颇非轻浅，乃阳虚饮瘀交阻、胃络损伤之危候。", ["弦"]], "3184": ["病机", "脉象静小，说明咳血后阳络虽伤而气火未清，阳明气火上壅未能通降，故咳引胸痛、便难口燥多梦纷纭；脉小为胃热内郁、络血易复之象，急宜清肺疏腑以化热安络。", ["小"]], "3185": ["预后", "脉数主热，咳逆咽痛、吐血痔疡之后脉数，为热郁营络、血热沸涌，最防络血大来；附桂等剂助热，故咳逆益炽，脉数示热势未清，预后当虑出血复作。", ["数"]], "3186": ["病机", "脉虚为素来酒多谷少、中阳大虚之征，脾运不健则痰湿内生，咳逆蒸热、舌白溺黄、胃钝，皆中虚湿郁化热之象；脘痛十数年亦由中阳不足、气机不和所致。", ["虚"]], "3187": ["病机", "脉濡弦为湿热蒸郁之象，濡主湿、弦主郁，心胃虚热与湿火下注，故滑泄、舌心光苔腻、溺黄；冬来咯血蒸热亦湿热伤络，未可遽进壅补，反助相火。", ["濡", "弦"]], "3188": ["病机", "右三部弦而虚，弦见于浮中两候，为气滞水壅、脾土受困；关位微细寸尺尤甚，按之至骨，示中阳式微、水湿泛滥，故肿自下起、茎囊俱肿、小溲淋漓、气逆不能平卧。", ["弦", "虚", "微", "细"]], "3189": ["治法", "此段虽未言脉，然承上案色脉神气皆惫，肿盛溺少，指出水病在肾为本、在肺为标，脾土无堤防、肝风鼓荡，愈逐愈壅；力主停药，反对专科峻利攻逐，强调去病当以顾护中州为要。", []], "3190": ["病机", "脉浮而濡，浮为风邪在表、水气上行，濡为湿胜脾弱；肿自面起渐及腹肢，食减便泄，舌黄有刺，是风水挟湿、脾胃土德已薄，堤防失职，故当开鬼门发汗，并虑喘逆。", ["浮", "濡"]], "3191": ["病机", "脉沉郁为水湿内壅、肺气痹阻、腑气下滞之象；风水为病，体素湿胜，肺失宣降则不能平卧，便溺赤涩，舌光干燥，肿极最虑喘逆，故治当疏府理气、宣肺以通水道。", ["沉", "郁"]], "3192": ["病机", "原文谓肿喘俱减七八而微咳便溏气易上逆，脉右濡左弦大。濡为湿胜脾弱，弦大为肝木偏亢，右濡左弦大提示中土湿困而肝风内动，水气易泛。故曰水肿最易翻覆，暂效未足全恃，宜和阳调中为御水之本、熄风养肝为因时之制，正合濡弦大所示脾虚肝旺、水风相煽之机。", ["濡", "弦", "大"]], "3193": ["病机", "咳嗽音窒气逆数年，易发难已，原文断为肺气之虚痹，治节不行则通调水道下输膀胱之职弛，水气泛滥，中土卑湿不能枢连。脉濡正应湿胜气虚、脾肺不运。肿喘并盛而脉濡舌鲜，说明病本在气化不行、湿浊内壅，故宜先理中上，慎勿遽投温热滋腻碍脾。", ["濡"]], "3194": ["预后", "素体平弱阳虚湿胜，肝积便溏下血多年，今腹满肉削肌羸、咳嗽痰气有音、饥不能食、便数溺少，脉象濡弱舌干齿燥。濡弱为脾胃肺气虚极、健运之权弛而气化之机废，故断为臌症极重，喘泻一见便难措手，补泻两难，惟宣气疏腑希冀万一，属危重预后之判。", ["濡", "弱"]], "3195": ["病机", "喘虽不盛而痰气尚逆，脉濡舌白，先咳而后肿，肿势盛于下半。濡主湿，舌白主寒湿，说明湿蒸府痹、气化不利，水湿下聚。原文明言治腑以理气为先，故专理痰气之逆，以肺气不降、湿浊阻痹为病机关键，非单纯虚喘可比。", ["濡"]], "3196": ["病机", "疟肿迁延，湿热薰蒸于内、风阳鼓动于外，肿及周身胀至废食，齿燥口干舌砂白，脉左弦数右沉弦数实，脐突背平。弦数实为肝气横逆、湿热壅实，沉主病在里，说明脾肺大失通降之权而肝气益横，故急须缓剂理气平逆为先。", ["弦", "数", "沉", "实"]], "3197": ["病机", "咳嗽后两胁走注作痛，入秋腹满足肿、筋见青色、食少䐜胀，脉弦沉附骨。弦为肝郁，沉附骨主病深在里，说明郁怒伤肝、痰阻气痹，肝木乘土，中满已成。筋青、胁痛、腹胀皆肝郁痰凝之征，故断为难许见效。", ["弦", "沉"]], "3198": ["预后", "上呕痰饮下泻瘀血，阳明似有通运之机，饮食稍进、脉象稍起，然蕴蒸之湿外达为黄、内阻为胀满。原文未识脉名，仅言脉象稍起，说明正气略复而湿热蕴结未化，黄与胀满并见，邪势仍盛，故论症仍在险途，属预后审慎之判。", []], "3199": ["病机", "幼有哮嗽，痰饮内聚阻肺胃升降之气，加以肝郁不调顺乘中土，入夜腹必攻胀，汤饮香燥皆不能受，脉象小弦。小弦为肝郁而中气不足之象，弦主肝木乘土，小示正气偏弱，故宜缓调，议通阳涤饮条肝法，正合肝脾两伤、痰饮内聚之机。", ["小", "弦"]], "3200": ["病机", "关尺弦坚而数，弦主肝木乘土，坚为燥气内结，数示燥热郁蒸。原文谓燥令大行、大肠燥金气𪱥，脘腹膨胀疼痛、泄利不爽已三月，正是燥湿交迫、脾胃失通和之序，肠腑传导失司。脉坚数应燥热内结，故取效难速，议通养肠腑以阖阳明。", ["弦", "坚", "数"]], "3201": ["病机", "脉沉迟，沉主里、主水湿内停，迟为阳虚不能鼓动。原文谓嗜酒烦劳伤阳，湿胜于下，足跗先肿渐及腿髀茎囊腰腹，溺少而黄、肤腠似癍似瘰，皆湿火内蕴；舌胖大鲜赤示阳明有火。沉迟正合阳虚湿盛、湿浊上干清阳之机，故宜扶阳化湿、缓以图功。", ["沉", "迟"]], "3202": ["病机", "脉沉微迟涩，沉主里，微迟为阳虚鼓动无力，涩示湿滞血行不畅。原文谓恣啖生冷伤中阳，上逆为呃、下壅为肿，汗多食减、便干溺涩而赤，皆阳虚湿胜之征。然阳虽虚而湿又甚，一味补阳反助湿，故用通阳调中疏腑，使呃止肿缓，并嘱樽节饮食。", ["沉", "微", "迟", "涩"]], "3203": ["病机", "脉沉涩，沉主里、主水气内停，涩为气机壅滞、肺失治节。原文谓饮食骤伤中阳，呃逆由作，水肺旧恙复作，肿由下渐及于上，便涩溺少、舌鲜苔白、喉间痰气有音、杳不思谷，显系肺失治节、胃不致布，水浊上潜清阳。故宜宣肺养胃、调气化资谷气，缓冀肿退。", ["沉", "涩"]], "3204": ["病机", "脉弦数右甚急，弦主肝木乘脾、痰气郁结，数急为湿热内蕴、燥邪搏肺。原文谓秋间泄痢脾胃湿热未清，入冬燥邪搏肺，肺失清肃则承流宣化益滞，咳嗽肿满交作，腹膨妨食、囊足即肿、溺浑便溏不爽。右甚急应肺胃痰热壅滞，故先疏理痰气以润输运。", ["弦", "数", "急"]], "3205": ["病机", "脉迟弦而虚，迟为阳运不及，弦主肝横，虚示中气不足。原文谓劳郁太过、阳淤肝横，顺侮所胜，饮食不化精而聚为饮，痛呕交作多年，脘胁胸背皆受凌□，面黄筋掣，舌淡白而黄，主客两虚。弦为肝旺、虚为脾弱，故平时丸养肝和胃，发时煎温中御侮。", ["迟", "弦", "虚"]], "3206": ["病机", "寸关濡弦滑数，濡为痰湿，弦主肝胆易动，滑数示痰火胶结。原文谓体丰阳虚饮聚气滞，交春木气司令，肝胆顺乘阳明、逼动心营，致脘腹攻胀、心悸头晕耳鸣、舌光少寐多汗、火升足清。脉证合参，总属痰火交病、气即是火，故平气清火、敛汗和阳、涤饮和胃为治。", ["濡", "弦", "滑", "数"]], "3207": ["病机", "脉左浮弦，浮主饮邪留踞中州、病位偏表，弦主肝阳易动。原文谓进通阳饮后寒热退、饮咳减六七，然舌苔白腻、右胁隐痛、大便仅一度、小便短赤，尚属余饮未尽，致便溺未通、肝阳不免易动。浮弦应余饮未清而肝木偏亢，故仍以通阳和饮为主，疏腑润肝为佐。", ["浮", "弦"]], "3208": ["病机", "脉来弦滑，弦主饮邪内踞、气机不和，滑主痰饮壅盛。原文谓\"寒遏卫阳饮踞中脘\"，故见肢体畏寒、晨起痰饮涌溢、食少便坚、脘中不和。痰饮停于中脘，胃气不降则食少便坚，卫阳被寒邪郁遏则畏寒，脉弦滑正合寒饮内阻之象，故拟和阳涤饮以通中州。", ["弦", "滑"]], "3209": ["病机", "脉弦主饮，原文明言\"脉弦有饮\"，又谓\"痰饮之聚原由阳虚\"，高年脾胃运化力迟，水谷之湿酿为痰饮。今精气饮食已复而脉仍弦，说明饮邪未净、脾胃运化尚迟。时当湿土，湿易困脾，故宜参和胃益脾以助谷气之运，从本治之。", ["弦"]], "3210": ["病机", "脉尚沈著，沉主里、主水饮。新凉外束则卫阳被遏而身凝热，宿饮内动则痰饮虽不多而左臂大痛，四五十日才得痰少痛缓。脉沉说明余邪与饮俱未尽化，病位在里，非表邪独盛，故身热与臂痛并见，当从饮与余邪两解。", ["沉"]], "3211": ["病机", "脉滑而坚，两关尤甚。滑主痰饮，坚主肝阳亢逆。原文谓\"支饮未和肝阳又逆肺胃益难通降\"，故痰多脘痞、食少欠连、不能平卧。饮聚于中则滑，肝阳上逆则坚，关部应肝胃，故两关尤甚，正合饮与阳逆并见之机。", ["滑", "坚"]], "3212": ["病机", "脉坚弦，原文自释\"弦为饮坚为肝阴虚\"。阴虚则肝无以养，饮聚则气易上逆，故寒热咳嗽、动辄气逆。向有失血、外感咳久肺伤，皆耗阴之由。弦坚并见，既示饮邪内聚，又示肝阴不足、气逆上动，故病机在阴虚饮聚、气逆不降。", ["坚", "弦"]], "3213": ["病机", "本段未明言脉象，专论病机。原文谓\"胃中蕴结之痰饮湿浊亦无不随气以动\"，痰饮湿浊皆阴属，阳虚则郁而不敷布，故晨起恶风、右胁漉漉有声、厥气上逆、痞聚梗塞、沃沫呕嗳、便干溏泄不一。总属阳虚胃弱、湿浊内蒸、痰饮内聚，久病至此难求速效。", []], "3214": ["病机", "脉象濡弦，右部兼滑。濡主湿、弦主饮、滑主痰浊。原文谓\"阳明水谷之湿易酿痰浊，以致脾肺之输运难速\"，故痰饮黏腻、舌苔黄滑、肤腠𥆧惕麻痹。右部兼滑应脾肺，湿痰内蕴则输运迟滞，故宜清养肺胃之阴以连脾气，远刚用柔。", ["濡", "弦", "滑"]], "3215": ["病机", "脉濡主湿、主痰饮稽留。原文谓\"痰饮稽留于肝胆之格而为痛\"，故晨刻呕沫、头运耳鸣、左胁痛渐及左背肋、舌苔黄灰、胃钝。前次濡泻自春至秋才止，亦属痰泻。脉濡正合湿痰内踞、肝胆气机不利之机，未可竟作血虚肝病论治。", ["濡"]], "3216": ["病机", "脉沉弦，沉主里、弦主饮，合之则阳虚饮踞。原文谓“阳虚之体酷嗜茶酒久而聚饮”，饮邪内聚，阳气不运，故右胁痛控引胸背、短气、便溏溺涩、吐涎沫、肠鸣辘转。沉弦正是饮停阳弱之象，非外感弦脉，故断为阳虚饮踞无疑，治宜节饮节劳、常服甘药和之。", ["沉", "弦"]], "3217": ["病机", "脉左弦且数，左关候肝，弦为肝郁筋急，数为郁而化热。原文谓“素有筋疝”“筋疝必易举而善泄”，睪丸上控自幼如此，乃肝经筋脉失养、郁热内扰。弦数示肝郁有热而非肾虚，故宜养肝以治疝；若误投壮阳补肾，反滋梦泄淋滑，正因脉不主虚寒而主肝郁热。", ["弦", "数"]], "3218": ["病机", "脉沉而涩，沉主里、涩主气滞血不畅。原文谓腹痛无定时定所、攻鸣有声无形、得嗳与矢气则舒、经久不已，此厥阴气郁而为冲疝。气郁于里故脉沉，气机不利、血行不畅故脉涩，非实积有形，故攻鸣无形而嗳气矢气可缓，治宜柔养疏调。", ["沉", "涩"]], "3219": ["病机", "脉左弦，左关属肝，弦为肝郁。原文谓冲气自左上逆、俶扰脘腹胸胁、或呕或痛作止不常、时有寒热，即厥阴之为病。肝阳郁结，气聚为冲疝，气逆则痛呕，郁而寒热，故脉弦。治宜滋养肝阴以调其气，弦脉示郁结而非虚寒。", ["弦"]], "3220": ["病机", "脉得弦而近数，弦主肝、数主郁热。原文谓幼患冲疝、睪丸控引入腹而痛，后因疟致衄、脘痛由右而上、妨食便闭、快吐便行乃平，此疝之上逆。弦为冲疝之本脉，近数则久病郁而化热、衄后阴伤，故仍从疝冲论治，丸以缓调，病根深非速效。", ["弦", "数"]], "3221": ["病机", "本段未出脉象，纯论狐疝偏右多年之病机。原文谓疝为任脉之病，有所触忤实则下连肝气，虚则内连冲逆，春初即发腹痛攻逆，是二者兼有。指出疝病关乎任脉与肝气、冲逆虚实夹杂，治法仍以疝为主，脉象原文未及，故脉要素从缺。", []], "3222": ["病机", "脉濡弦，濡主湿、主虚，弦主肝郁气逆。原文谓初冬疝攻腹痛属劳倦伤阳、饮食阻腑，厥阴之气挟任脉逆行；冬底复感温邪，咳嗽咽干、口渴舌鲜。濡示肺胃津伤兼湿，弦示任脉肝气未调，故宜清养肺胃兼调任脉，弦不尽属寒疝。", ["濡", "弦"]], "3223": ["病机", "脉弦滑搏指，弦主厥阴气逆，滑主痰饮内聚，搏指则邪气偏盛。原文谓寒疝宿饮二者为病，疝攻于下则饮聚于中，冲逆于上则眩晕耳鸣咳呕、络脉阻痹。弦滑正合疝与饮迭为宾主之机；又曾失血，刚药难投，故取效难速，宜缓调。", ["弦", "滑"]], "3224": ["病机", "右脉虚滞，主阳虚痰湿内蕴、气机不畅；左脉弦数，主肝风失调、升动太过。原文谓“肝升太过必致胃降不及”，故脘痛彻背、便艰；风动于中则耳鸣痉搐、心悬如饥；饮溢于外则肢面浮肿。脉象与阳虚痰湿、肝风胃逆之病机相应。", ["虚", "滞", "弦", "数"]], "3225": ["病机", "脉濡弦为肝郁气滞、痰湿阻络之象，右关沉滑尤显痰阻中焦。原文谓“肝郁气滞挟痰阻络，由少阳渐及太阳阳明络病”，故腰脊痛连中椎、转侧不便，兼心悸头眩耳鸣、火升汗泄。濡主湿、弦主郁、沉滑主痰，正合络病宜通腻补益之论。", ["濡", "弦", "沉", "滑"]], "3226": ["病机", "脉沉全属气机壅塞，原文明言“气痹久则津燥，津燥则痰凝，痰凝则络益痛”。痰气阻络由外感发热而来，郁极欲达故咳逆；气痹津燥故舌白口干。沉脉主里主气滞，与胸背络痛、痰凝络阻之病机紧相呼应。", ["沉"]], "3227": ["病机", "右脉虚主肺胃大肠津气大虚，左脉弦为木来乘土。原文谓“肺胃大肠津气大虚，加以木来乘之”，故当脐痛喜按、便燥结、嗳气矢气则快；屡经下血致音窒不扬、喉粗气促，亦津气亏虚之征。虚弦并见，正合柔药通和、不可沾沾治痛之旨。", ["虚", "弦"]], "3228": ["病机", "脉沉郁而虚涩，主气机郁滞兼营血不足。原文谓脘腹痞满、食与动辄痛甚拒按、便溏，乃气滞不通、脾运不健之候。沉主气郁于里，虚涩主营虚涩滞，故宜宣气通痹后转柔剂养肝和胃，仿塞因塞用之法，脉症相合。", ["沉", "虚", "涩"]], "3229": ["病机", "脉犹滞，示气滞痰凝未解。原文谓“气滞痰凝，肝胆脾胃失和久矣”，故脘腹膨痛、寝食俱废、便结气逆、脘右症瘕有形；痛止而脉滞、舌白腻黄、溺未清澈，说明气机升降未复、痰湿尚蕴。滞脉与气扰于中之病机相应，宜通调升降以和之。", ["滞"]], "3230": ["病机", "脉沉郁右甚，主气机郁滞、痰浊内阻。原文谓便坚下血、血燥生风、风阳内扰，蒸痰酿浊弥漫清空、堵塞隧络，故呕逆痞满、头重肢痹、左胁痛连肩背。沉郁之脉正合痰浊弥漫、隧络不通之病机，宜滋液息风、清气化痰缓调。", ["沉", "郁"]], "3231": ["病机", "右脉沉小弦，主肺胃阳虚、饮聚于内，故咳而寝食皆乖；左脉弦大坚，主肝脾气郁、营虚不荣，故少腹痛三月不止。原文谓“肝脾营虚气郁故腹痛”“肺胃阳虚饮聚故咳”，弦大坚为郁而偏亢之象，沉小弦为阳虚饮聚之征，故汤丸缓治。", ["沉", "小", "弦", "大"]], "3232": ["病机", "两手皆弦，左尤甚，右弦为饮，左弦为肝郁乘脾，故环脐痛，痛甚于暮，乃肝胆旺时。肝阳扰肺则咳逆气急，胃不和则疲倦少食。脉弦主饮、主肝郁，与腹痛、咳逆、倦怠相应。", ["弦"]], "3233": ["病机", "右芤弦，左寸关牢急。芤主血虚，弦主肝郁，牢急主阴络伤而气血枯燥。便血三年，去血过度，阴络大伤，血无统摄，肝脾肾三阴枯燥，津液气血告匮，故脉见芤弦牢急，症见心悸气逆咳逆、便溏失血。", ["芤", "弦", "牢", "急"]], "3234": ["病机", "右脉滑数，滑主痰湿，数主湿热。多痰多湿之体，湿热下迫大肠，痔血五年，肠枯血燥，传导失职，胃滞痰凝，中脘结块，气机阻遏，故吐痰、气逆、足软、心荡、肠鸣、神疲，舌苔黄腻，脉右滑数，主痰热内蕴。", ["滑", "数"]], "3235": ["病机", "原文未出脉象。肠枯血燥，胃滞痰凝，阳明络脉阻遏，故左膝肿痛，肩项肘背皆痹。病机为燥痰阻络，气血不宣，虽难速效，尚不致废。", []], "3236": ["病机", "右虚小而静，左三部原文未全。虚小主气血不足，静主无火。素体肝阴不足，郁火挟燥，肠血杂下，去血多而风燥火炽，肠不润则胃虚痰饮上溢，故口燥恶汤饮、喜温。脉虚小静示久病正虚，与肠风燥火兼痰饮相应。", ["虚", "小", "静"]], "3237": ["病机", "脉弦，关尺欠柔。弦主肝阳上逆，欠柔示阴血亏耗。烦劳饥饱，阳气久虚，便血百日，营阴又耗，肝阳挟冲气上逆，故手指冷、懊𢙐、呕吐、晕厥。脉弦关尺欠柔，主肝阳冲逆、阴不柔肝。", ["弦"]], "3238": ["病机", "脉弦小滑。弦主肝风，小主胆虚，滑主痰涎。惊气通肝，肝热胆寒，胃不和，痰涎沃胆，风木内震，故心悸、头眩、耳鸣、心神不自主，甚则运仆搐搦。脉弦小滑，主内风与痰涎搏击。", ["弦", "小", "滑"]], "3239": ["病机", "脉右芤弦近数。芤主血虚，弦主肝郁生风，数主热。劳妇痫症夜发，经事不调，头运耳鸣心悸食少，乃肝郁生风，胆虚聚涎，猝犯胞络，神明遽蒙。脉芤弦数，主阴血亏而肝风痰热内扰。", ["芤", "弦", "数"]], "3240": ["病机", "脉虚而静，虚为气血不足，静为无邪扰之象。患者肝郁生风、胆寒聚液，发为痫症，痰涎潮流，昏不知人，平时脉虚而静，说明病本在虚，风痰为标。头痛脊酸、耳鸣心悸、经事不调，皆血虚失养之征。前投熄风化痰已效，今拟养血液以治其本，正合脉虚而静之旨。", ["虚", "静"]], "3241": ["病机", "脉迟弱虚涩，迟弱为阳气不足，虚涩为阴血亏少，右寸独大乃风燥之火上刑肺金。患者神思困倦、饮食少进、干咳耳鸣、心虚少寐、手臂振掉，皆虚风内动、肺胃津伤之候。舌苔滑白边白胖、中心黑腻，为痰湿内蕴。此风燥之火中劫肠胃，故宜滋肺养胃、泄风化燥。", ["迟", "弱", "虚", "涩"]], "3242": ["病机", "脉滑主痰湿内盛。患者素有痰火风发痫厥，眩悸耳鸣、消渴便难，肺胃津气既虚，则痰湿愈益凝聚。今湿令气蒸，胸次欠舒、知饥不运、足酸、干咳音涩，皆津虚痰阻之象。脉滑印证痰湿为患，故宜滋养肺胃津气以化痰湿，标本兼顾。", ["滑"]], "3243": ["病机", "脉濡长而数，濡主湿，长为邪热有余，数主热。暑热之邪由少阳直迫阳明，阴痹三焦，故寒战热甚、汗多消渴、额胀胸闷胁痞、烦冤疲惫、便硬色黑、小溲赤热。舌红苔凝白，为暑湿内蕴。幸得战汗畅达，邪有外解之机，故宜辛凉清解阳明，可望渐愈。", ["濡", "长", "数"]], "3244": ["病机", "脉濡主湿，患者中年以后劳郁形气易虚，秋感湿邪作疟，胃易钝、气易滞，舌黄、阳事不充，皆阳明湿困之征。湿浊困阻阳明，气化不利，故先宜和阳明以祛弊，后商培补以复元。脉濡一症，正合湿邪内蕴之机。", ["濡"]], "3245": ["病机", "脉虚涩似弦，虚涩为阳衰津耗，弦为疟邪留连、土受木乘。患者阳虚之体，湿热不能化，致肿满疮痍，舌质光红，津液渐耗。疟为经邪留连，暑湿之疟阳明多而少阳少，经邪传腑，内阻气化，外遏肌肉隧络，浸淫漫衍为肿为胀。故急须存津液和气，佐开太阳阖阳明以止疟消肿。", ["虚", "涩", "弦"]], "3246": ["病机", "脉左迟濡、右较大而流利，迟濡为湿滞阳气不运，右大为阳明宿垢内结。暑湿为疟为痢，三焦主病，湿流连肠胃，夹食夹痧，肠腑气奔迫而下，夹溏夹痰夹血，腹痛滞下，干黑宿垢错杂而来。舌黄燥不渴、纳少频转矢气，皆大肠宿垢留滞之征，故宜疏腑化滞、理气调中。", ["迟", "濡", "大"]], "3247": ["病机", "脉濡而微弦，濡主湿滞，微弦非少阳之弦、非乘土之弦，乃涩滞去而渐有流利之机。患者疟后便下黑溏，似痢非痢，腹痛轻微，稍能纳粥，但舌心苔老黄且厚、口渴溺少、上嗳下转矢气，显属肠腑宿滞与湿浊尚未净尽，阻其气机，故疏滞化湿为要图。", ["濡", "微", "弦"]], "3248": ["病机", "脉弦大而数，弦主肝胆，大数主邪盛热炽。原文谓\"湿热之邪郁蒸未化，阻遏气腑，充斥三焦\"，故见寒热烦冤、呕恶消渴、神昏错语；热退肢冷乃阳郁不达。脉症合参，似虚实混淆而实以三焦湿热为病，非纯虚可补，亦非单纯表证。", ["弦", "大", "数"]], "3249": ["病机", "脉弦滑之中反似有力，弦主饮邪搏结，滑主痰湿内盛。原文谓\"新凉引动伏饮\"\"无痰不成疟\"，痰饮阻遏肺胃则寒热交战、呕逆便溏、咳痰黄稠。脉象示痰饮留中尚多，故须缓为清化，不可峻攻，亦不可温补，以免逗遛生变。", ["弦", "滑"]], "3250": ["治法", "脉濡右滑，濡主湿盛阳虚，右滑主痰湿壅于中焦。原文谓\"阳虚积湿，体肥多痰，湿热内酿\"，致大筋软短、小筋弛长而成痿躄，酒容便燥即是见端。脉濡滑示湿痰未化，故慎勿杂投热补表散，宜通养阳明腑络并调，使湿有出路。", ["濡", "滑"]], "3251": ["病机", "原文未明写脉象，以症测机：素体阳虚湿胜，湿酿成痰，易汗畏风，肠痔便涩，今夏软脚肿满而赤。阳虚者阴亦不足，湿当渗导下趋，若误温补则壅滞，湿反随气蒸腾而上。脉症参看，虑其成痿成肿，急宜疏通阳明腑络，使湿热下行。", []], "3252": ["病机", "脉浮濡滑，浮主湿蒸于外，濡主湿滞，滑主痰热。原文谓\"阳明湿痰蒸热，气络皆弛而为痿躄\"，故足肿而软、步履维艰、大指微痹、溺涩而黄、时有气逆。此湿热壅滞将成痿象，与虚寒痿症截然两途，急清阳明以化通之。", ["浮", "濡", "滑"]], "3253": ["病机", "脉沉迟，沉主病在里，迟主湿郁阳遏。原文谓\"湿热郁于肺胃而成痿躄\"，肺病则治节不行，痰多不耐右卧；胃病则大筋软短、小筋弛长，两足皆痿、曳行不良。病已两年，沉迟示郁滞深久，故难望全愈，仅可扶杖徐行。", ["沉", "迟"]], "3254": ["病机", "脉濡涩，濡主湿盛，涩主络脉滞涩。原文谓痹痛起于长夏，手足关节痛肿，\"湿甚于风则兼肿\"，今左膝犹肿挛难伸，闻木声亦痛，乃痹在阳明兼少阳。舌黄不渴、胃钝少纳、易汗，皆湿盛之征，故宜专治阳明通络化湿，兼养络熄风。", ["濡", "涩"]], "3255": ["病机", "原文仅言\"和脉\"，未列具体脉象，故脉素从缺。以症推机：烦劳伤阳，阳虚气痹，升降不和，脉络滞痛，自左肩下至右腰及尻，作止不常，呕逆头疼，舌黄便结。此病在气络，非太阳表证，故和阳平肝、通络化痰，未可专用太阳之药。", []], "3256": ["病机", "脉来弦滑，弦主痛、主饮，滑主湿浊痰热。原文谓湿热之邪混杂三阳，邪势留经入腑，膀胱气痹，少腹高突拒按，小溲淋沥，大便闭结，已成胞痹。弦滑正合湿热痰浊壅阻下焦、气机痹塞之象，故急宜宣通少腑，防湿浊阴邪上逆喘脱。", ["弦", "滑"]], "3257": ["病机", "脉右弦实，弦主气滞，实主邪结。原文虽大小便俱通，然宿矢未尽、胞痹未平、舌黄，右脉弦实说明湿热积滞仍结于阳明腑络，邪势未衰。故仍宜通利，不可因二便暂通而松懈，原文断为犹在险途，正合此脉实邪未去之机。", ["弦", "实"]], "3258": ["病机", "右脉滑大而数，左弦数。滑大属湿酿成痰、胃热及肺，数主热，弦主痛属风。原文谓阳明热痹，痹在脉络不在筋骨，湿热郁蒸，痰热内偪心胃，故见惊惕少寐、错语、神思不清。脉象正示痰热壅盛于阳明络脉，故急宜滋肺胃、养心营，化热化痰。", ["滑", "大", "数", "弦"]], "3259": ["病机", "脉弦数，弦主痛、主络脉拘急，数主湿热。原文谓流火乃湿热阻遏阳明之络，非伤科病，症见舌黄便干胃钝。弦数正合湿热阻腑、络脉不通之机，故急宜疏腑以化湿热，使腑气通而络热解，肿痛可消。", ["弦", "数"]], "3260": ["病机", "左脉弦数，右尺同而寸关虚弱。弦数主燥火，虚弱主津气不足。原文见咽痛、涎沫自溢、口燥便难、身凝热，断为秋燥之气劫夺津液为多，肺热痿躄可虑。左弦数示燥火未清，右寸关弱示肺胃津伤，故议清燥救肺、养胃存津为主。", ["弦", "数", "弱"]], "3261": ["预后", "脉弦而数，弦主气燥津伤、木火内郁，数主虚火。原文谓喉癣迁延半年，肺虚耗而子救母，少阴之火上炎，痰涎涌溢、食物梗涩。脉弦数而势颇可尤，说明虚火燥痰交炽，正虚邪恋，故惟宜返视内听、静药滋养金水，希冀获效，预后未可轻许。", ["弦", "数"]], "3262": ["病机", "脉搏数，数主虚火。原文谓肾脏风，食后少腹胀、溺孔有精、茎中掣痛，断为阴液不足、肝肾虚火游行上下，有失血溺血之虑。数脉在此非实热，乃阴亏火动之象，故戒以火济火，急急加数月静养以涵养阴液，使虚火归藏。", ["数"]], "3263": ["预后", "脉浮大数，右手为甚。浮主肺气上浮，大主邪壅正耗，数主热。原文见咳嗽音哑、痰多吐血、喉间臭气，断为内喉痈，病不在咽故纳食无碍。然高年肺气大耗，浮大数之脉示热毒壅肺而正气已伤，故原文深虑其难支，预后堪忧。", ["浮", "大", "数"]], "3264": ["预后", "脉虚小而弦，虚为气虚，小为血少，弦主痛主饮。肺痈吐脓月余，气秽色浊，汗多食少，正虚邪恋。虚小示气血耗伤，弦为痰浊壅滞、络脉不和。原文虑其久不得寝、汗多食少，以咳嗽爽利、汗敛食增为吉，脉证合参，预后堪忧。", ["虚", "小", "弦"]], "3265": ["病机", "脉弦且劲，弦主肝郁，劲为火亢。肝胃郁火上扰，龈齿痛成牙痈，脓从鼻腭来，顿车不舒，咽梗便燥，皆火郁络脉之象。弦劲之脉正合郁怒化火、肝胃气逆，故治当息虑戒怒、静养肝胃。", ["弦", "劲"]], "3266": ["病机", "脉小弦数而沉滑，小为气虚，数为血虚，弦主郁火，沉滑为痰。体肥多痰，痰出遽少乃气化郁极生火，火勃于中，痰随火上壅络脉，致咽腭颈颌皆肿。脉证相合，示气虚痰难化、血虚火易炎，吞吐日艰，精气日削。", ["小", "弦", "数", "沉滑"]], "3267": ["预后", "脉小弦近数，小为气虚，弦主痰气凝聚，数为郁热。腹右块溃脓成腹皮痈，半年未敛，痰气因循，正气日耗。脉小弦数示虚中夹郁热，脓久不收，原文断为不治，正合痰气缠绵、气血难复之机。", ["小", "弦", "数"]], "3268": ["病机", "脉濡弦数，濡为湿为虚，弦主痰火郁结，数为火。三阴亏虚，虚则痰火易生，颈疬串发、咽干蒂丁下垂，皆痰火浮游上扰之象。濡弦数正合虚体痰火，故宜清理浮游痰火以消颈疬为先。", ["濡", "弦", "数"]], "3269": ["病机", "脉濡，濡主湿、主气虚。鼻衄而脉濡，非实火迫血，乃肺脾络伤、瘀阻饮聚，湿浊内停。原文防成内痈，正因濡脉示湿饮不化、络脉瘀滞，故慎勿轻视，当察其饮聚瘀阻之机。", ["濡"]], "3270": ["其他", "此段论编纂体例，非论脉象。原文强调治病所凭在脉，叙证兼叙脉者始选；不载脉象而侈治验者入选无益。盖识病难于识脉，故不载脉者必辨证详明、治法新奇或立论高超方略备数条，以扩识见，纯属凡例说明。", []], "3271": ["其他", "此段亦属编纂凡例，非脉证论述。原文言削去鄙俚矜夸之语，只存脉证方论以为认病之法；文繁词晦者僭为修饰，不敢窜改其意，仅条达其辞以便观览。全段无脉象内容，旨在说明整理原则，故归其他。", []], "3272": ["其他", "此段为编纂体例说明，非论脉象。原文强调对“脉病因证候紧要关键处均加密点”，以示精要，而作者自按之语不加密点，以待教正。故无具体脉象可析，亦不主病机，仅属文献整理凡例。", []], "3273": ["病机", "柳太后感风不能言，脉沉而口噤。沉脉主里，风邪内客，气血壅滞，故脉沉；口噤为风痰闭阻络窍。允宗以汤气熏蒸，令药入腠理，邪从汗解而愈，说明此脉沉非虚寒，乃邪闭于里，属风中经络之病机。", ["沉"]], "3274": ["病机", "罗谦甫案脉浮紧、按之洪缓，为风寒客于阳明经表，故浮紧；赵僧判六脉弦数，为脏腑俱受邪，壅滞化热。原文以“中藏者多滞九窍，中府者多著四肢”析机，浮紧主表邪，弦数主里热壅滞，二案脉象各示风中表里之不同病机。", ["浮", "紧", "弦", "数"]], "3275": ["病机", "郑君年近六旬，膏粱厚味，久患滞下又犯房劳，忽然昏仆、撒手遗尿、目上视、汗大出、喉如拽锯，脉大而无伦次部位。大而无伦为阴虚阳暴绝，阳气浮散无根，故脉失常序，属脱证危候，急灸气海、服人参膏以回阳固脱。", ["大"]], "3276": ["病机", "陈学士跪拜间倒仆，汗如雨，脉大而空虚。大而空虚为阳气暴散，阴血不足，气不内守，故汗出如雨。原文谓“阳气暴散”，与丹溪治郑义士之病同，皆属脱证。后现哭笑，为阴虚火动、五精相并，加连柏泻火而愈。", ["大", "虚", "空"]], "3277": ["病机", "妇人年六十余，手足左瘫、不言而健、有痰，春时脉伏而微。伏微主痰浊闭阻，阳气不伸，故脉伏而微。丹溪先以吐法涌痰，继以健脾化痰、活血通络，后微汗、手足微动而言，说明此脉伏微为闭症痰阻，非脱症虚候。", ["伏", "微"]], "3278": ["病机", "震按前条脱症脉大无伦，此条闭症脉伏而微，两路重药须凭确见。原文强调“症与脉宜合参”，左瘫不言而健有痰，得间在此。脉大无伦主阳脱，脉伏而微主痰闭，同见中风而病机虚实迥异，故治法不同。", ["大", "伏", "微"]], "3279": ["其他", "此段述丹溪治肥人中风，口㖞、手足麻废，左右俱作痰治，以化痰通络为法，随症加减。原文明言“皆不载脉象若何”，故无脉可析，亦不主具体病机，仅示中风痰治之大法及诸案不录脉象之由。", []], "3280": ["主病", "六脉浮大弦滑，右甚于左，为风痰壅盛之象。浮主风邪，大主阳热亢盛，弦主肝风内动，滑主痰湿内蕴。身肥白者多痰湿，春初风木当令，风挟痰上扰，蒙蔽清窍，故暴仆不知人事、口噤不语、喉如拽锯。右脉甚于左，右属气分，痰气壅盛于上，故以吐痰取效。", ["浮", "大", "弦", "滑"]], "3281": ["病机", "六脉沉细而涩，沉主里，细主虚，涩主寒湿凝滞、气血不畅。薛立斋谓此中寒湿，非中风也。寒湿内闭，阳气不达，故牙关紧、不能言、左体瘫、神昏欲绝。沉细涩为虚寒之脉，与实邪中风之浮大弦滑迥异，故用吐痰及至宝丹，继以五积散加木香、南星、附子温散寒湿而苏。", ["沉", "细", "涩"]], "3282": ["病机", "六脉洪数而虚，洪数为阳热之象，虚为不足。薛立斋以为肾经亏损，不能纳气归源而头晕，不能摄水归源而为痰，阳气虚热而麻痹，虚火上炎而作渴。洪数而虚，乃虚阳外浮、真阴不足之候，非实火也。故用补中益气合六味丸，补气摄水、滋肾纳气而愈。", ["洪", "数", "虚"]], "3283": ["病机", "肝脾肾脉洪大而数，重按则软涩。洪大数为有余之象，软涩为不足之征，此虚火挟痰湿为患。左半身不遂、汗出神昏、痰涎上涌，似实而本虚。洪大数属虚阳上浮，软涩示精血亏虚、痰湿内阻。立斋用补中益气加知、柏、麦冬、五味，晚用地黄丸，补虚泻火而诸证悉退。", ["洪", "大", "数", "涩"]], "3284": ["病机", "六脉沉伏，沉主里，伏主邪闭。卒中昏愦、口眼㖞斜、痰气上涌、咽喉有声，而脉沉伏，此真气虚而风邪所乘，痰气壅塞气道，阳气不能外达。沉伏非无热，乃寒痰闭阻、真气不伸之候。故用三生饮行经络治寒痰，加人参驾驭其邪而补助真气，否则取败。", ["沉", "伏"]], "3285": ["病机", "肥人脉沉伏，无火象者，可用三生饮；若脉微细者，必加人参。沉伏为寒痰壅塞、阳气闭郁，微细为元气虚衰。三生饮乃治中寒寒痰壅塞气道之药，非中风通剂。若虚火冲逆、热痰壅塞者，状类中风，乌附非所宜。故须辨脉之虚实寒热，不可妄投。", ["沉", "伏", "微", "细"]], "3286": ["病机", "六脉皆滑大而数，浮而不敛。滑大为痰，数为热，浮为风。体肥善饮多湿，湿生痰，痰生热，热生风；荒于色则真阴竭而脉浮。手指掉硬不舒、口角牵扯引动，乃中风之兆。面色苍紫、其神藏，虽病犹可治。治以二陈汤加滑石、芩连健脾消痰撤湿，胆星、天麻定风。", ["滑", "大", "数", "浮"]], "3287": ["病机", "脉上盛下虚，上盛为痰与火，下虚为精元弱。左弦大，右滑大。弦大为肝风内动，滑大为痰热壅盛。阳痿为精元下虚，痰火上升，热生风，将有中风之患。果因酒色诱发，左手颤动、左瘫、口㖞、唇麻，皆痰盛使然。治以二陈汤加全蝎、僵蚕、天麻、芩、菖蒲、红花、秦艽，涤痰熄风通络。", ["弦", "大", "滑"]], "3288": ["病机", "脉滑大为痰浊内盛、正气未衰之象。原文谓病初无卒仆昏愦之症，且脉滑大，说明痰浊虽阻络隧而神机未乱、胃气尚强，故可先散后补、从容施治。滑主痰，大主邪实而正未虚，若脉不滑大而见虚细，则不可径用疏通磨痰之法，此正喻氏辨证用药之依据。", ["滑", "大"]], "3289": ["病机", "脉软滑中时带劲疾，软滑为脾湿蒸痰、痰浊内蕴之象，劲疾则风邪内动、热势鼓激之征。原文断为痰与风杂合、内热与外寒杂合之症，因膏粱蕴热蒸脾湿为痰，痰阻窍隧，卫气不周，外风易入。软滑见其本虚痰盛，劲疾见其风热相搏，故非单纯温补所能尽。", ["软", "滑", "劲", "疾"]], "3290": ["病机", "左三部洪数、关部尤甚，洪为热盛气壅，数为热迫急疾，关候肝脾，故知肝经血虚而肝气痞塞、肝火炽盛。原文以胸乳胀痛为肝气痞塞，四肢不收为血虚不能养筋，自汗为肝热迫津妄泄，便不实为木盛克土。洪数见于左关，正合肝经郁热化火之病机，故用犀角散清之。", ["洪", "数"]], "3291": ["病机", "六脉皆伏而气口独动，为食填胸中、阴阳痞隔、升降不通，脉气被遏故伏；吐后六脉尽见而左关弦大，弦主气郁，大主邪盛，左关候肝，知为大怒伤肝、气食交阻。原文先言食满胸中致脉伏，后言左关弦大知为怒伤，脉象随病机显露而变，故断为食中兼气中。", ["伏", "弦", "大"]], "3292": ["病机", "左脉七至大而无伦，右脉三至微而难见，两手脉如出两人，至数悬殊、大小迥异，非脏腑常度，原文称为祟凭之脉。数而大者阳扰于上，微而难见者正夺于下，阴阳不相维系，神失所主，故昏晕狂言、喃喃不休。此恶中之候，脉象乖戾即其病机外现。", ["数", "大", "微"]], "3293": ["病机", "六脉沉细紧滑、愈按愈有力，沉主里、细主虚、紧主寒、滑主痰湿，合为寒湿相搏、凝滞经脉之象。原文断为痓症属膀胱，因体虚而岁火不及、寒水用事，寒湿乘虚袭入，筋脉失柔故身体强硬、牙关紧闭。紧滑有力非虚寒纯证，乃寒湿实邪搏结，故用羌活胜湿汤。", ["沉", "细", "紧", "滑"]], "3294": ["病机", "六脉浮洪、重按豁然，浮为邪在表，洪为热盛，重按豁然则示里无实邪、热未深结。原文谓醉饮当风，名曰漏风，酒热内蕴而风邪外袭，故头痛发热、自汗盗汗。浮洪见于外而按之空豁，说明热在肌表、卫气不固，故以白术泽泻酒煎渗湿清热，非里实可下之证。", ["浮", "洪"]], "3295": ["病机", "脉豁大而空，大而无根、按之空虚，为阳气浮越于上、下元虚寒不能固摄之象。原文见头面赤红、躁扰不歇，全似伤寒戴阳，断为平素下虚、真阳失守，故急用人参附子温补下元、收回阳气。豁大而空正是虚阳外越之脉，若误作表实再服麻黄，必致大汗脱阳。", ["豁", "大", "空"]], "3296": ["病机", "脉细紧而伏，细为阳虚，紧主寒痛，伏示寒邪深伏于里。患者暑月远行，渴饮泉水，单席卧地，寒邪深入，虽值盛夏而现中寒之象。身痛如刀刮、寒热吐泻不得，皆寒邪内闭、阳气不伸所致。前医误作中暑，投寒凉之剂，更伤阳气，故随服随厥。此脉此证，当以附子理中汤温中散寒，方得奏效。", ["细", "紧", "伏"]], "3297": ["病机", "脉浮数而无力，浮为表证，数为热，无力为虚；尺以下迟而弱，迟弱主营气不足。此伤寒发热头痛烦渴，虽似麻黄证，但尺中迟弱，营虚不可发汗。许学士用建中汤加当归、黄耆调营，待尺部应而后发汗，终得汗解。若不循次第，强发其汗，必致亏损五脏。此脉示表实里虚，当先顾其里。", ["浮", "数", "虚"]], "3298": ["预后", "脉弦者生，涩者死。此案伤寒便闭、潮热、撮空、直视、喘急，已属恶候。许叔微引仲景云：循衣妄撮、怵惕不安、微喘直视，脉弦者生，涩者死。弦为肝脉，肝热淫于胃经，以承气泻之，得弦脉则肝平胃和，故生；涩则营血枯竭，故死。本案下后脉且微弦，是肝气渐和之象，故半月愈。", ["弦", "微", "涩"]], "3299": ["兼症", "脉代主气血虚衰，运行不及。楼全善治寻衣撮空，皆用大补气血之剂，惟一人兼𥆧振脉代，于补剂中加桂二分，振止脉和而愈。寻衣撮空多属肝热，然此例兼𥆧振脉代，显系气血大虚、筋脉失养，故非清泻所宜，而用温补。加桂者，助阳化气以复脉也。脉代在此为虚候，非死脉。", ["代"]], "3300": ["病机", "脉洪滑，洪为热盛，滑主里实。此伤寒吐下后八九日，内外发热，口大渴，欲饮水，舌干燥而烦，显系热结在里、表里俱热。前医见吐下而疑白虎，许叔微引仲景云：吐下后七八日不解，热结在里，表里俱热者，白虎加人参汤主之。洪滑之脉，正是阳明热盛、气分大热之征，故非人参白虎不可。", ["洪", "滑"]], "3301": ["病机", "脉洪大而实，洪大为热盛，实主邪结。此伤寒心烦喜呕、往来寒热，似柴胡证，但脉洪大而实，知热结在里，非小柴胡所能和解。许叔微引仲景云：伤寒十余日，热结在里，复往来寒热者，与大柴胡汤。洪实之脉，示里热成实，故用大柴胡汤表里双解，三服而病除。", ["洪", "大", "实"]], "3302": ["病机", "脉浮而大，浮为表未解，大为虚阳外浮。此太阳症发汗不止，恶风，小便数，足挛急，屈而不伸。许叔微辨为桂枝加附子汤证，因汗漏不止、阳虚液脱，故用桂枝加附子汤温经复阳，佐以芍药甘草汤缓急舒筋。浮大之脉，在此非实热，乃汗多亡阳、营卫不和之象，故不可再汗。", ["浮", "大"]], "3303": ["预后", "脉已和矣，示邪退正复。此武官伤寒自汗而鬲不利，医者误下误汗，杂治数日，渐觉昏困，上喘息高。许叔微断为太阳下之、表未解、微喘者，桂枝加厚朴杏仁汤主之。一啜喘定，再啜热缓微汗，至晚身凉而脉和。脉和乃胃气恢复、表里通和之征，故为向愈之候。原文未及具体脉象，仅以脉和言预后。", []], "3304": ["病机", "脉沉细且微数，沉为里病，细为气衰，微数乃“五性之火内煽”，非表邪所致。气奄奄勿属，正是中气虚极之象。发热恶风自汗貌似伤寒，然脉不浮紧而沉细，知非外感，乃内伤劳倦，故以补中益气甘温之剂取效。", ["沉", "细", "微", "数"]], "3305": ["其他", "此段为震按，辨内伤与伤寒之异。原文谓“内伤之脉，皆虚大无力，或微数无力”，以脉之虚大无力为辨，非另有一种情形。其药以补中益气汤甘温为主，随兼证加减。震氏删去内伤门，编入伤寒温暑，意在免滋眩惑，非论具体脉象主病。", []], "3306": ["误治", "伤寒发热误投白虎大寒，致面黑如墨、本证不复见，脉转沉细、小便不禁。沉细为阳郁不升、经络不行之象，非本病自然之脉，乃寒药抑遏阳气所致。东垣以温药升阳行经，使隐于经络之本病复现而愈，示误治后脉变之机。", ["沉", "细"]], "3307": ["病机", "脉七八至，数之极也，然“按之不鼓击”，重按无力，是脉至而从、按之不鼓，乃阴盛格阳于外，非真热也。目赤烦渴为假热，脉数而虚为真寒。东垣断为阴盛格阳，与姜附之剂，汗出而愈，示数脉亦有虚寒之辨。", ["数"]], "3308": ["病机", "脉沉细而身热发斑狂言，是阴症似阳；脉沉数有力而脚膝痿弱、阴汗精滑，是火郁于内、逼阴于外，名阳盛拒阴。刘宗厚举此水火征兆之微，示同一沉脉，有阴寒内盛与火郁于内之异，脉证治例之妙在于细辨。", ["沉", "细", "数"]], "3309": ["病机", "脉极沉细，内寒外热，斑出狂乱，王海藏断为“阳为阴逼，上入于肺，传之皮毛”，神不守舍故错语如狂，非谵语也。肌表虽热，按之冷透如冰，真寒之征。后脉又沉迟、不大便，与理中丸而愈，明沉细迟主阴寒内盛。", ["沉", "细", "迟"]], "3310": ["病机", "伤寒服凉药太过，身凉厥冷、通身黑斑，惟心头温暖，六脉沉细，昏沉不语，状似尸厥。沉细为阳气衰微、阴寒内盛之脉，斑由阴寒逼阳外浮所致。用人参三白汤加附子干姜，斑红肢暖而苏，示沉细主阳衰寒厥。", ["沉", "细"]], "3311": ["病机", "两手脉皆沉数，外证身凉、四肢厥逆、发斑微紫、唇龈破裂、咽干声哑、便闭，罗谦甫断为“热深厥亦深”，变成狐惑。沉数主热郁于里，阳热内闭不能外达，故外反厥冷。以承气下之、黄连解毒清之而愈，示沉数主里热深伏。", ["沉", "数"]], "3312": ["病机", "脉数而微细，数主热，微细主气血不足。狐惑病见声哑、多眠、目不闭、恶闻食臭、不省人事，为湿热虫毒内扰，气血亏耗。半月后手足拘强，乃热灼筋脉、血不荣筋。脉数微细反映正虚邪恋，故先以竹沥、姜汁化痰开窍，继用参、术、归、陈补益气血，佐竹沥、姜汁以清余邪。", ["数", "微", "细"]], "3313": ["病机", "寸口皆长而弦，长主气机有余，弦主邪郁少阳。伤寒三阳合病，因涉海受惊，血菀神慑，血为热搏而吐血、胁痛烦渴谵语。左尺不应乃岁运使然，非病脉，故称“天和脉”。长弦之脉示三阳热盛、气血壅滞，故用小柴胡汤减参加生地凉血，后以承气下之。", ["长", "弦"]], "3314": ["病机", "尺脉迟弱为营气不足，迟主阳虚，弱主血少，尺部候肾，故营血亏虚。吕沧洲以左尺不应为天和脉，乃岁运之常，非病脉。二义皆古书所载，引证恰当，说明诊候需结合时令、部位，不可拘泥。迟弱脉提示营气不足，当补养营血；左尺不应则须辨岁运，勿妄作虚治。", ["迟", "弱"]], "3315": ["病机", "六脉尽伏，三部举按皆无，然舌胎滑、两颧赤如火、语言不乱，乃热邪搏血，淖而为斑，外见皮肤，脉气一时隐伏。原文以“脉血之波澜”为喻，沟渎无水则风不成澜，斑消则脉自出。此非阳病见阴脉之死候，故用白虎加人参汤化斑，脉复常后继以承气下之。", ["伏"]], "3316": ["病机", "脉伏不见而肌热灼指，非阳虚阴盛，乃荣热致斑、热郁血分，脉气被遏。前医误以脉虚自汗进真武汤，致神昏如熟睡。元膺凭肌热灼指断为斑毒内郁，见赤斑、脐下石坚拒按，知兼蓄血。故先化斑汤透斑，斑消脉出，继以生地黄汤、桃仁承气逐瘀，瘀去则愈。", ["伏"]], "3317": ["病机", "此段论发斑蓄血可见脉伏之候。斑未出而脉伏，热郁血分、脉气不达，理或有之；斑既透而脉伏，则当思蓄血内阻。吴又可“脉厥”用承气微下则脉出，与此用白虎化斑相仿。然发斑脉伏势危，上条语言不乱、次条误服真武致神昏，皆凭证施治。翁云“见斑则应候”，思及蓄血，已属勉强推断。", ["伏"]], "3318": ["病机", "此段举数案论发斑脉伏及辨治。夏月饮火酒，烦热面赤发斑，脉绝无，乃火郁热极、脉气壅遏，用栀豉汤加葛根、厚朴、黄连清透，斑出脉见。又伤寒过经，遍体黑斑，唇口焦枯，脉大便秘结，热毒深重，用三黄石膏汤。朱奉议谓“凡见斑不可专以斑治”，须察脉之浮沉、病之虚实，分别用药，是为至言。", []], "3319": ["病机", "关及尺中皆滑数且芤，滑数主热盛，芤主血虚或痈脓。脉数不时则生恶疮，关内逢芤则内痈作。胁及小腹偏左满，毒循宗筋流入睾丸赤肿，刺溃后胁肿痛如故，乃内痈作脓。滑数芤并见，示热毒壅聚、血腐成脓，故用保生膏丸、硝黄汤下之，下脓而痊。", ["滑", "数", "芤"]], "3320": ["其他", "此段为震按语，评述以伤寒变肠痈之案，指出所引两句分别出自仲景《伤寒论》与高阳生《脉诀》，并感慨明以前皆用此诀而近贤痛诋。原文未出具体脉象，仅论脉诀源流与接受史，故不涉主病病机，属医史评述之其他类。", []], "3321": ["病机", "原文谓“六脉沉伏不见，深按至骨则若有力”，沉伏主阴寒内盛、阳气被遏，故断为“阴中伏阳”。阳郁于内不能外达，则头疼身温而指末皆冷、胸满恶心；沉伏非纯虚寒，深按有力正是伏阳之征，故须破散阴气、导达真火，使水升火降得汗而解。", ["沉", "伏"]], "3322": ["病机", "脉沉紧而见头汗出、手足冷、心下痞闷、大便秘，似少阴阴结，然少阴多自利、额上冷汗，今大便硬、头汗出，知非少阴。沉紧在此主半表半里、阳郁不达，故仲景谓“脉虽沉紧，不得为少阴病”，属阳症似阴，以小柴胡和解枢机而愈。", ["沉", "紧"]], "3323": ["病机", "原文引“尺脉弱者，营气不足，不可发汗”。尺弱主营气不足、肾气怯，故汗出多而汗不来，心悸目眩身战掉。太阳病得汗不解，欲解必复作汗，而肾气不足则难汗，故以真武汤温肾和营，肾气得行则微汗自出而解，此尺弱主肾气怯之病机。", ["弱"]], "3324": ["病机", "脉细如线主气血虚少、阳微不能温煦，故伤寒汗下后病去而背独恶寒，汤熨不应。背为阳位，细脉示阳气虚衰、寒凝经脉，故内服理中汤加姜桂附子温中回阳，外敷大辛热药于背，内外合治而愈，属阳虚寒凝之病机。", ["细"]], "3325": ["病机", "脉细欲绝主阳气衰微、气血大虚。因多服小柴胡升发太过，多汗亡阳，表虚极故恶寒甚；里虚极而阳不复，故肉𥆧筋惕。细欲绝正是亡阳之候，故以真武汤温阳固表，进七八服而愈，此脉细欲绝主亡阳表里俱虚之病机。", ["细"]], "3326": ["病机", "脉动惕指经脉动惕，原文与潮热、大便秘结、小便赤涩、脐旁硬痛并见，其肉不𥆧，知非虚证。此燥屎内结、腑气不通，热邪鼓动经脉故动惕，潮热来尤甚亦阳明腑实之征，故用加味大柴胡汤下之而愈，属实证动惕之病机。", ["动"]], "3327": ["病机", "脉动惕而见肉𥆧身振摇，原文明言“此汗多气血俱虚故也”。伤寒十余日屡发汗过多，气血两伤，筋脉失养则动惕振摇，与上条燥屎实证之动惕不同。故用加味人参养营汤补气养血，二剂而愈，此动惕主气血俱虚之病机。", ["动"]], "3328": ["其他", "原文未载脉名，仅述“首条载脉，三条不载脉”，强调肉𥆧筋惕四条治法不同，须凭病因病形分别。脉象缺如，故无从论其主病，但提示临证不可拘于脉，当合病因病形辨析，方能用方恰当。", []], "3329": ["病机", "六脉浮大，按之豁然，左为甚，是浮大无力之象。浮为风邪在表，大而按之豁然则为极虚，左甚尤关精血不足。故断为极虚受风寒，虽遍身疼痛如被杖、微恶寒，仍以人参为君大补，佐表药取汗而解。", ["浮", "大", "虚"]], "3330": ["病机", "脉沉迟涩，面黄神倦二年，下血日久，显系里虚血少、阳气不运。沉迟为虚寒，涩为血少。后因劳倦感寒，脉三部不调、微带数、重取虚豁，左大于右，乃虚体再感寒，故用参、芪、术补虚，少佐麻黄解表。", ["沉", "迟", "涩", "虚"]], "3331": ["病机", "脉洪大而数，大发热谵语、喜冷饮、肢体不能举，似属阳明实热，然丹溪用黄芪、茯苓浓煎凉水调服而愈，知此洪数为虚阳外浮、气分大虚之象，非实热。洪大无力，数而按虚，故以补气取效。", ["洪", "大", "数"]], "3332": ["病机", "脉洪数而左甚，老人饥寒作劳，头疼恶寒发热无汗，似伤寒表实，然丹溪断为内伤胃虚，不可攻击。洪数左甚乃虚阳浮越，误汗后脉虽不散而洪数尚存，谓“洪当作大论”，示洪大与实热有别，当大补其虚。", ["洪", "数"]], "3333": ["病机", "震按四案皆作虚证治，所凭在脉虚豁；后二条脉洪数不虚豁而亦用补，一凭肢体不能举，一凭老年饥寒作劳。指出“脉洪当作大论”，洪与大原有分别，洪数不虚豁者亦当审证求因，不可概作实热。", ["虚", "豁", "洪", "数"]], "3334": ["病机", "脉浮沉皆有不足意，其间得洪数一种随热进退不时，知非伤寒。浮沉皆不足为气血两虚，洪数随热进退乃酒毒内蕴、虚阳浮动。因过饮烧酒、房劳致虚，故用补气血加解酒毒，一帖微汗而愈。", ["浮", "沉", "虚", "数"]], "3335": ["病机", "震按脉浮沉皆有不足意，大象是虚；间见洪数随热进退，须久诊方得。下条问知素有下疳疮，则脉之弦数为疮毒。示脉虚为气血不足，弦数主疮毒，四诊合参方不致误。", ["浮", "沉", "虚", "弦"]], "3336": ["病机", "脉弦甚七至，重取则涩，弦主厥阴肝经，数主热，涩为血瘀。患者素有下疳疮，忽头痛发热自汗，前医作伤寒治反剧，丹溪断为病在厥阴，与证不对。此脉示肝经湿热毒邪内蕴，热盛血瘀，故以柴胡加龙胆草、黄连清肝解毒而安。", ["弦", "数", "涩"]], "3337": ["治法", "脉浮紧而数，浮主表，紧主寒，数主热，为伤寒表实热郁之象。吐血虽见，然因当汗不汗，热毒蕴结，迫血妄行。陶氏据脉断为表邪未解，进麻黄汤发汗，使热越血止。此案示脉浮紧数当汗，虽衄家亦可用麻黄，以脉证合参，非一概禁汗。", ["浮", "紧", "数"]], "3338": ["误治", "脉来虚数无力，虚为气阴两伤，数而无力为阴虚内热。患者积劳感寒，误进麻黄汤发汗，致目赤血衄、痰中带血，继服小柴胡而舌干乏津。此脉示劳倦兼阴虚，误投热药动血竭液，故以地黄汤滋阴、生脉散益气，后加葛根引药透表，得微汗而津生。", ["虚", "数"]], "3339": ["病机", "脉六七至而弦劲，数为热盛，弦劲为实热内结、肝风内动。患者夏月劳役食冷，遗精发热，误汗误下后身强如痉、腹胀喘急、舌胎黄黑，此燥实内结、热极生风之候。脉弦劲急，故用黄龙汤下黑物，通腑泄热，热退痉止。", ["数", "弦", "劲"]], "3340": ["病机", "脉长大而实者，邪热内结阳明，腑实燥屎，故用承气下之；脉大而虚者，津液亏耗，肠燥便结，故用蜜煎导之。同是阳明便闭，脉实可下，脉虚当润，此示脉象虚实为攻下与润导之关键，不可卤莽灭裂，一法废诸法。", ["长", "大", "实", "虚"]], "3341": ["误治", "右三部浮洪略弦而无力，左三部略小亦浮软不足，浮洪似外感，然无力、软不足为内伤虚证。患者劳倦发热，误服羌活、柴胡，热愈甚，又欲承气下之。虞氏据脉断为内伤虚证，非阳明内实，若下必死。此脉示虚阳外浮，当补不当攻。", ["浮", "洪", "弦", "软"]], "3342": ["病机", "脉洪大而无伦且有力，洪大为热盛，无伦为脉失常度，有力似实。然患者年高入房，头痛发热、眩晕喘急、舌刺唇裂、面赤烦躁，此肾经虚火游行于外，真寒假热之象。脉洪大无伦乃虚阳外越，故用十全大补合六味、生脉加附子，温补引火归元。", ["洪", "大"]], "3343": ["病机", "脉洪大有力，似实热内盛，医者必思白虎泻心。然患者年七十九，入房后发病，口渴舌刺、面赤烦躁，实为肾虚火浮。震按指出此脉易惑人，惟景岳可与谈心，强调脉洪大有力不可一概作实热治，当合年高入房、证候辨其虚火。", ["洪", "大"]], "3344": ["病机", "原文述阴虚伤寒，舌黑芒刺干裂，身热便结，大渴喜冷，而“脉则无力”，神昏沉。脉无力说明并非实热阳证，而是阴液亏虚、虚阳浮越之象，故群医误判“阳证阴脉”。张景岳以甘温壮水救本，佐凉水滋标，正是针对阴虚为本、虚热为标之病机，脉无力为辨证关键。", []], "3345": ["病机", "脉洪大而空，浮取无伦，沉取无根，伴身大热、口渴、面赤娇红、四肢厥冷过肘膝，舌黑滑胖润。此非实热白虎证，乃格阳戴阳，虚阳外越。洪大为空，说明阳气浮散于外而内里虚寒，故用大剂八味加人参温补回阳，冷饮以顺其势。", ["洪", "大", "空"]], "3346": ["病机", "脉洪大躁疾而空，重按全无，舌干燥焦黄而胖壮。原文强调“果系实证，则脉必洪大躁疾而重按愈有力者也”，今重按无脉，说明非实火，乃虚阳浮越、阴血亏耗之假热。洪大躁疾为虚性亢奋，按之空豁为根本无根，故用养营汤加参附温补收功。", ["洪", "大", "躁", "疾"]], "3347": ["病机", "六脉皆无，四肢俱冷，似阴证，但按腹两手护之、眉皱作楚，趺阳脉大而有力。趺阳候胃气，大而有力说明胃有燥屎内结，腑气不通，脉气被遏故六脉皆无。此乃大实有羸状，燥屎内结为本，脉伏为标，故用大承气汤下之，得燥屎后脉复能言。", []], "3348": ["其他", "此段为震按语，评述前案“六脉无而诊趺阳”之法，赞其鉴于仲景自叙，读书有用。原文未直接描述具体脉象要素，主旨在于强调诊脉当全面，手不及足则可能误判垂绝之证，趺阳脉可补六脉之不足，属诊法心得，非主病或病机专论。", []], "3349": ["病机", "六脉沉数，下利不止，懊𢙐腹胀，按脐则痛。沉主里，数主热，沉数说明热邪内结于里；下利而脐痛，是协热自利，中有结粪，热迫津液旁流。脉沉数结合按脐痛，辨为里实热结，故用小承气倍大黄下其结粪，利止懊𢙐安。", ["沉", "数"]], "3350": ["病机", "脉浮而大，伤寒六日，谵语狂笑，头痛有汗，大便不通，小便自利。浮主表，大主邪盛，脉浮大说明病邪仍在表而未入里；小便自利更证里无热结。谵狂由汗多神昏所致，非阳盛腑实。故用桂枝汤和其荣卫，表解则谵狂自止，大便自通。", ["浮", "大"]], "3351": ["病机", "脉浮大无伦，热盛汗多如云雾，昏不识人，舌短眼瞀。浮大无伦为虚阳外越、心液散漫之象，非表邪实热。原文谓“寒水为邪，必然心火受病”，本从思虑受寒，心火不及而受水侮，又屡行发散重虚其心，故脉浮大无伦。用参附温补心阳，使精神有主。", ["浮", "大"]], "3352": ["主病", "脉洪大而实，为阳明热盛之象。洪大主热盛，实主邪实。原文见头痛壮热、渴甚且呕、鼻干燥不得眠，皆阳明热炽、气逆上冲之症。脉证合参，断为阳明实热证，故用白虎汤清泄里热，加麦冬、竹叶以清热生津。", ["洪", "大", "实"]], "3353": ["病机", "脉微细欲绝，似阴证，然王肯堂据素禀充壮、酷暑酒炙内炎，断为热气怫郁不得伸，故脉伏而微细。若热邪外达，则当洪数有力。此脉微细乃热郁于里、阳不外达之假象，非真阴寒。故用大柴胡汤下之，使郁热得伸，脉即出。", ["微", "细", "数", "实"]], "3354": ["病机", "脉洪大无伦，重按无力，为阳虚欲脱、外显假热之象。洪大无伦似热盛，然重按无力则根本已虚，乃虚阳浮越于外。原文身寒目赤、索水不饮、异常大躁，皆真寒假热之征。故断为阳虚欲脱，用附子、干姜、人参、甘草回阳救逆。", ["洪", "大"]], "3355": ["病机", "震按比较诸案脉象：脉大无伦重按无力主阳虚欲脱；脉微细欲绝主热郁于里；脉浮大沉小主表里同病。喻案脉浮大沉小，兼漱水不欲咽，为热郁阳明；王案脉微细欲绝，因壮盛人暑月醉饱，热郁于里；薛案脉大无伦且有力，似阳证阳脉，然高年御女、气喘溺频，为肾虚阳浮。", ["大", "微", "细", "浮"]], "3356": ["病机", "脉弦浮大而短气，为阳明中风、表里俱病之象。弦主少阳，浮大主阳明热盛。原文鼻干不得汗、嗜卧、一身及面目悉黄，与阳明中风条过经不解同例。脉未大坏，故九分可治。但筋脉牵掣不停，恐手足痿废，故用防风通圣散两解表里，兼治痿。", ["弦", "浮", "大"]], "3357": ["病机", "六脉俱无，乍有则甚细，为阳虚阴盛、脉气欲绝之象。外证面赤谵语口碎，似阳证，然脉微细欲绝，乃阳病见阴脉。慎柔断为阳虚，从脉舍证，用附子理中汤冷服。服后脉渐出，口碎愈，脉如常而谵语未已，知胃有燥粪，以猪胆汁导之而愈。", ["细"]], "3358": ["病机", "六脉不至，手足厥逆，独左寸厥厥动摇，为欲作战汗之候。脉不至乃邪郁于表、阳气一时不达，非真阳绝。左寸动摇，为心阳欲伸之象。故令勿服药，但与热姜汤助其作汗，汗出则脉自复。若误服药，必热不止。", ["动"]], "3359": ["病机", "震按比较慎柔案与海藏案，皆以温补得愈，与金坛治余云衢案大相反。谵语属虚者十居八九，然亦有邪传阳明、热与燥矢抟结而谵语者。虚寒谵语与实热谵语，辨之诚难。此段总结谵语三路，强调脉证合参，不可偏执。", []], "3360": ["其他", "此段为震氏评论伤寒治法与注家得失，非论脉象。原文虽标'平脉、脉'，实无脉象描述，仅言'必熟读仲景书''临证方有把握'，强调研习仲景原文及诸家注解之重要，批评方、喻三家各以己意布置致原文无定局。故无脉可析，主旨属治学方法之其他类。", []], "3361": ["病机", "伤寒得汗病退数日，忽身热自汗、脉弦数、心不得宁，许学士断为'真劳复'。脉弦数者，弦主劳伤神气、营卫失度，数主虚热内扰；心藏神，劳心则神舍未复，虚热外浮故身热自汗。此非实邪，乃劳心伤神、营卫失调之虚热病机，故以补脾汤合小柴胡补子以益脾，脾王则感之于心。", ["弦", "数"]], "3362": ["主病", "感冒已汗而愈，数日复大发热恶寒、头痛眩晕、呕吐却食、烦满咳而多汗，滑伯仁诊得'两手皆浮而紧'。浮主表邪未尽、仍当汗解，紧主寒邪束表；虽病后众医图温补，然脉浮紧说明表寒仍在，故用麻黄葛根汤三进更汗而愈。此脉证实为劳复兼表寒，浮紧即其主病之据。", ["浮", "紧"]], "3363": ["病机", "初病太阳证，'尺寸脉俱浮数，按之无力'，浮数似表实而按之无力，海藏断为内阴虚，与神术加干姜汤。愈后犯房，外阳内收，'脉反沉小'，始见阴候，沉小为阳虚阴盛之征。经与已寒丸等温阳，脉复生，终以大建中取汗而解。此段以浮数无力转沉小，示阴虚阳浮转为阴寒内盛之病机演变。", ["浮", "数", "沉", "小"]], "3364": ["病机", "伤寒四五日身微斑、渴饮，海藏诊得'沉弦欲绝'，断为厥阴脉。沉主里、弦主肝，沉弦欲绝乃阴寒内盛、阳气衰微之危候，故服温药、姜附以回阳，阳回脉生。后因渴私饮，脉复退、头不举目不开，知犯阴易，以吴茱萸汤调烧裩散温散寒邪，作大汗而愈。脉由沉弦欲绝转生，正是阳回阴退之机。", ["沉", "弦"]], "3365": ["病机", "夏月阴阳易，腰痛少腹急、烦躁谵妄、舌青紫、心下硬痛失气，挟宿食也。所虑者'六脉虚大，而两尺则弦，按之皆无根'。虚大为气血虚浮于外，两尺弦而无根，乃肾元不固、根本欲脱之象；然宿食内结属实，故先以逍遥汤加大黄下黑秽，诸证悉除，再以烧裩散、五苓散收功。虚大无根示正虚，弦主积结。", ["虚", "大", "弦"]], "3366": ["妇人", "此段引范汪方华旉视顾子献脉事，及巢氏病源论妇人伤寒瘥后未满百日合阴阳之害。原文仅言'视脉''虽瘥尚虚，未平复，阳气不足'，未出具体脉象，故脉要素为空。主旨论病瘥未健、气血骨髓未牢实而犯女劳，致百节解离、经络缓弱、气血虚、骨髓空，属妇人瘥后调摄禁忌，归妇人类。", []], "3367": ["妇人", "引千金方论妇人温病虽瘥未平复、'血脉未和'、尚有热毒而交接成阴阳易，并举张苗说婢瘥后数日六人奸之皆死。原文'脉未和'为笼统描述，未出具体脉名，故脉要素为空。主旨言瘥后血脉未和、热毒未尽即犯房事则病复甚至致死，属妇人瘥后禁忌与阴阳易病机，归妇人类。", []], "3368": ["主病", "原文述夏至后热病“其脉洪大”，洪大为阳热亢盛之象，热邪充斥内外，故脉体阔大而来势汹涌。此脉主热病，与“天道壮热”相应，属外感热邪所致，非伤寒比。", ["洪", "大"]], "3369": ["病机", "妊娠冬温，咳嗽咽痛、下血如崩，脉反小弱而数。数主热，小弱为阴血亏耗、脉道不充。热伤手太阴血分，血下夺则脉失充盈，故较平时反小弱，非虚寒之象。", ["小", "弱", "数"]], "3370": ["病机", "风温脉气本浮，此因热邪久伏少阴，从火化发出太阳，少阴之脉不能内藏，故反浮。浮为热邪外达、元气被鼓激之象，与壮热神昏、舌黑燥等症相应，属两感危候。", ["浮"]], "3371": ["病机", "轻取微数，寻之仍不数，寸口似动而软，尺部重按则无。数而无力、动软不实，示热邪伤阴而正气已馁，寒热错杂，故脉证难分，似厥阴麻黄升麻汤证之阴阳错杂。", ["数", "动", "软"]], "3372": ["病机", "关前濡、关后数，濡弱见于阳部为湿气搏暑，小急见于阴部为暑气蒸湿。暑湿相搏，脉见濡数，主湿温，与胸项多汗、足冷谵语相应，乃先受暑后受湿之候。", ["濡", "数"]], "3373": ["病机", "六脉弦细芤迟，按之欲绝，弦细为阴寒内盛、脉道拘急，芤迟为阳衰血少、鼓动无力。舌淡白、阳缩精滑如冰，显系肾中真阳虚极，阴寒挟暑入中少阴，故脉微欲绝。", ["弦", "细", "芤", "迟"]], "3374": ["病机", "原文论春温失治，驯至脉微且数。微为阳气衰微，数为阴液耗竭、虚热内扰，脉微数并见，示正虚邪陷、汗下温皆不能救之危候，故嘉言以为不必论脉而重证。", ["微", "数"]], "3375": ["预后", "脉已散乱，忽有忽无，状类虾游，为胃气将绝、真阴耗竭之死脉，故断不可治。后脉接续分明、洪数鼓指，是阴液渐复、邪热外透之象，故喜曰可活，脉象转归关乎预后。", ["散", "乱", "洪", "数"]], "3376": ["预后", "原文以“脉类虾游”为初起危候，虾游脉浮散无根、去来无定，主胃气将绝、真阴耗竭。若误认“证实脉虚”而投参术姜附温燥，则助热劫阴必死；后狂热复发若用白虎承气苦寒攻下亦危。其得生在于养阴血痢止而“脉即应指”，脉由散乱转为敛圆，是胃气渐复、阴血得养之兆，故虽谵妄昏热而不至厥冷声喑，预后可期。", ["虚"]], "3377": ["病机", "脉浮数无序，浮为风热在表，数为热盛，无序则示热邪鼓动、气机失序而非单纯表证。原文症见发热、两项臃肿、臂膊磊块、狂躁发渴、不食不便，显系燥热生风、肝血亏虚、风火内扰。医误作伤寒发毒，高鼓峰断为“燥逐风生”，用疏肝益肾汤大剂熟地滋水涵木，五剂肿退便解，十剂热除食进，正合脉浮数无序乃虚风燥热之象。", ["浮", "数"]], "3378": ["其他", "本段无脉象可录，主旨为辨析伤寒与温热病之异同。原文强调“太阳病发热而渴不恶寒者为温病”，温病在太阳已现热象，麻桂不可用；又驳“温热病只究三焦不讲六经”为妄言，认为仲景六经百病不出其范围。并辨伏气自内而发与吴又可温疫论不可牵混。所论重在病机归类与辨证纲领，非凭脉断病，故脉象要素从缺。", []], "3379": ["预后", "脉沉细而弦，三四动一止，沉细为年高气弱、正气内衰，弦为邪气内结、脉道拘急，动而一止是胃气衰败、脉结不续之象。原文述总帅年近七旬，新虏之人惊忧冻馁，邪气传染，相公痛饮后发病，症见头疼咳嗽、自利腹痛，与俘虏同病。脉证合参，正虚邪盛、结代频见，故“三日而卒”，引《内经》“乘年之虚，遇月之空”以明其危。", ["沉", "细", "弦"]], "3380": ["病机", "原文引“寸口脉阴阳俱紧”，紧脉主寒主痛，阴阳俱紧示清浊之邪上下交争。喻嘉言阐发为清邪中上从鼻入阳，浊邪中下从口入阴，在阳则发热头痛项强，在阴则足膝逆冷、便溺妄出。瘟疫之邪由口鼻直达三焦，三焦相溷、内外不通，故见口烂舌断、声嗢咽塞、痈脓下血等变。脉紧在此标示邪气壅盛、表里俱受，与伤寒递传六经者不同。", ["紧"]], "3381": ["病机", "初日脉细弱而数，细弱为房劳后肾阴亏虚、正气不足，数为热；次日转浮弦而数，浮弦示邪郁少阳、风热外扬，数仍主热。原文症见洒洒恶寒、自汗发热、头背胃脘痛、唇赤舌强、呕吐、眼胞青，汪石山断为“疫兼两感，内伤重外感轻”，脐下痛为肾水亏。脉由细弱转浮弦数，正是虚人感疫、正虚邪郁之机，故宜补降兼施，不可峻下。", ["细", "弱", "数", "浮"]], "3382": ["病机", "两手俱伏，伏脉主邪气闭阻、气血壅遏不能外达，非必阳气衰绝。他医见伏断为“阳证见阴不治”，欲用阳毒升麻汤升提。壶仙翁指出“风热之极，火盛则伏”，火盛气壅、脉道反伏，乃热邪内闭之象，非阴寒脉。若误升则助火燎原必死，故用连翘凉膈之剂清透郁热，一服而解，说明伏脉须辨火郁与阳衰。", ["伏"]], "3383": ["其他", "此条为震按语，总结温疫病当“以证为则，勿专以脉为凭”。原文未出具体脉象，故脉象要素从缺。其意承上条壶仙翁治时疫两手俱伏、断为火盛而伏之案，说明温疫之脉可变幻不常，或伏或数，单凭脉易致误判，须合参症候如狂躁、肿毒、便闭等以定病机，属方法论之提示，非论具体脉主何病。", []], "3384": ["病机", "六脉俱微数，极无伦次，又若虾游状，乃瘟疫经水适来，里虚邪陷，正气欲脱之象。微为阳微，数为邪热，脉无伦次如虾游，是胃气衰败、脉失根本，故胸中气筑作痛、不能卧，为结胸危候。", ["微", "数", "滑"]], "3385": ["病机", "六脉沉弦而数，沉主里，弦主痛主饮，数主热，乃疫后阴阳易，邪热内陷、气机壅滞之候。症见大热头疼、胸胁迸痛、二便俱秘，脉沉弦数正合里实热结，故以生脉散加柴芩桂枝，扶正兼解邪。", ["沉", "弦", "数"]], "3386": ["预后", "喘汗脉促，神气昏愦，脉促为阳盛而阴不能和，邪热壅盛、气机急促之象。然四围红晕鲜泽如痘疮根脚，紧附如线，他处肉色不变，是毒邪虽盛而正气尚能约束，故许以可治，先解肌表毒邪。", ["促"]], "3387": ["病机", "脉浮数，按之弦细，浮数为热在表，弦细为阴寒内束，故断上热下寒。头面肿痛、咽嗌不利为热壅于上，身半以下寒、足胫尤甚为阳虚于下，脉象与症合，故用刺血泄热、艾灸温下。", ["浮", "数", "弦", "细"]], "3388": ["病机", "六脉细数，右手尤细软，略一重按即无，细数为阴虚有热，濡微为阳气虚馁，右脉应指不微细而反细软无力，是虚阳上攻，非实热大头天行。故唇黑舌白、泄泻足冷，皆虚寒确据，不可妄用芩连升麻。", ["细", "数", "濡", "微"]], "3389": ["病机", "脉皆浮弦而数，浮为邪在表，弦为少阳主脉，数为热盛，故头大如斗、寒热昏愦，是疫毒壅于少阳阳明。服柴胡剂后弦减而洪大，知邪传阳明，脉随病转，故改贯众、葛根、花粉清解阳明而愈。", ["浮", "弦", "数", "洪"]], "3390": ["误治", "六脉皆小弱而急，小弱为阳微，急为邪热内迫，本伤暑阳微厥而脉小无力，众医误作阴证，投阴病药致腹满不省人事。胫冷臂不冷，知非下厥上行，乃阳微厥，故用五苓、白虎解暑热而愈。", ["小", "弱", "急"]], "3391": ["误治", "脉虚而洪数，虚为暑伤元气，洪数为热盛，本伤暑自汗面赤口燥，医误认亡阳，服术附刚剂，致脉洪数病益甚。脉虚身热得之伤暑，暑家多汗，刚剂助热，故撤幔开窗，制黄连人参白虎汤清暑益气而安。", ["虚", "洪", "数"]], "3392": ["主病", "脉皆虚微细弱而数，虚微细弱为气劳而虚，数主暑热。其人好赌致劳，暑伤气，故脉虚；暑为热，故数。此暑病脉象，与发热大汗、恶寒战栗、烦渴相应，治以人参竹叶汤调四苓散，补气清暑。", ["虚", "微", "细", "弱"]], "3393": ["病机", "暑脉必虚必数，虚者暑伤气，数者暑为热。细与洪不同，小弱而急，急亦数也，数主热又主虚。故暑病宜凉宜补者多，宜温者少。下条脉细数而实，为热药伤血，见解更进一层。", ["虚", "数", "细", "洪"]], "3394": ["病机", "脉细数而实，细数者暑也，暑伤气脉宜虚，今不虚反实，乃热药伤血，药为之也。实为邪实，非正气实，故以白虎饮清暑热，热退则脉自平。此脉与病甚、医皆以为瘵相应，实为暑热伤血之候。", ["细", "数", "实"]], "3395": ["主病", "脉虚而无力，类乎伤暑。妇冬月恶寒发热、恶食干呕、大便欲去不去，诸医以虚弱痰饮治不效。究因绵套夹暑气，体虚者得之易入，故脉虚无力。用黄连香薷饮而愈，证明伤暑之病机。", ["虚"]], "3396": ["病机", "震按绵套久收暑气几何，顿令寒热呕吐烦渴绵延不愈，殊未可信。但脉虚无力，用黄连香薷饮而愈，则诚暑矣。脉虚无力为暑伤气之征，留作疑案以待试，强调凭脉辨证之重要。", ["虚"]], "3397": ["病机", "脉皆浮缓，浮为阳热外浮，缓为气耗脾伤。儿本气怯，暑月过劳，劳则气耗，劳倦伤脾，阳气亢极变为邪热，故身热头痛吐泻。此内伤证，虽在暑月，非外感暑邪，脉浮缓与气怯劳倦相应。", ["浮", "缓"]], "3398": ["主病", "脉虚豁，二三至一止，虚豁为气阴两伤，歇止为暑热耗气伤津，脉道不续。岳母年六十余，劳倦中暑，身热如火、口渴饮冷、头痛如破，脉虚豁歇止，投人参白虎汤而愈，此暑伤气阴之候。", ["虚", "豁"]], "3399": ["病机", "六脉滑数无力，滑为痰，数为热，无力为气阴不足。暑热内蕴，炼液为痰，故滑数；取汗过多，气阴两伤，故无力。此暑风之脉，与梦遗畏寒、舌强语癫、目瞪不识人相应，治以清暑益气、熄风化痰。", ["滑", "数", "无", "力"]], "3400": ["病机", "脉浮小而缓，按之虚豁，为暑热伤气、劳倦伤脾之象。浮小为暑热耗气，缓而虚豁为脾虚不运。心藏神，脾藏意，二脏俱伤，故身热汗出、昏懵语乱。脉证合参，病机为暑伤心、劳伤脾，法宜清暑益脾。", ["浮", "小", "缓", "虚"]], "3401": ["病机", "脉弦数无力，弦为食滞气壅，数为热，无力为虚。发热头痛、胀满喘逆、大汗如蒸、面赤戴阳、足冷阳缩，乃伤暑夹食而复夹阴，虚阳上浮。脉弦数无力正合本虚标实、寒热错杂之机，故用温中兼通下而愈。", ["弦", "数", "虚"]], "3402": ["其他", "此段无脉象描述，专辨暑暍阴阳之名。张洁古以动得为阳证中暍、静得为阴证中暑，作者非之，谓暑暍如冬之寒冷，当以时令别病名，病暑有阴阳如伤寒有阴阳。大顺散等为纳凉食冷之阴证，非中暑。故脉象要素缺如，主旨属概念辨析。", []], "3403": ["病机", "脉行涩，为湿伤而过汗，津血耗伤、脉道不利之象。伤湿失于过汗，元气起于肾间，汗多则元阳外泄，百脉失充，故脉涩。症见昏愦、狂言、撮空、瘛疭、目左视、肌肉蠕动，皆津枯风动、筋脉失养之候，非实邪，乃虚风内动。", ["涩"]], "3404": ["治法", "脉迟小涩，迟为湿阻阳郁，小涩为湿滞血行不畅。此段震按列湿病治法，分气分湿、湿热、湿热作痞、脘中阻痛等，随证加减，取轻清走气道以除湿。脉迟小涩提示湿邪黏滞、阳气不宣，故治法重在化湿通阳，而不专补。", ["迟", "小", "涩"]], "3405": ["病机", "此段未出脉名，但言诊得脾脉极热、肾脉不衰。脾脉热为酒果积热在脾，肾脉不衰则非肾败消渴。多食多饮、小便频数，由脾热消谷、饮多溺多，非消渴也。故脉象要素空，病机为积热在脾，与消渴之脾衰肾败相鉴别。", []], "3406": ["病机", "脉皆细弱而缓，右脉尤弱，细弱为气血不足，缓为脾虚湿滞，右脉尤弱则脾虚尤甚。症见消渴善饥、脚弱、冬亦不寒、小便白浊如油，为脾瘅，乃脾虚不运、膏脂下流。脉不数不洪，非实火，故宜甘温助脾、甘寒润燥。", ["细", "弱", "缓"]], "3407": ["预后", "脉犹带缓，缓为胃气尚存之象。症见神困食减、通宵不寐、溺浊如膏、尫羸至极，似属危候，然脉缓肉未脱，知胃气未败，故可治。此神消于上、精消于下之证，消有阴阳，不得尽言火。脉缓在此判断预后，非主病脉。", ["缓"]], "3408": ["病机", "脉大而无力，按之不鼓，是阳气虚衰、不能鼓动之象。下消日久，腰膝软弱、饮食减半、神色大瘁，皆下元不足、无气升腾所致。脉大非实火，乃虚阳外浮，故法当温补下焦，用桂附等温阳化气，使阳复而渴止。", ["大", "虚"]], "3409": ["病机", "六脉皆数，伏而且牢，浮取不应，是火郁于内、不得发越之象。夜热五心烦热半年，热郁阴分，脉数主热，伏牢主郁闭。故用升阳散火汤发散郁火，后以四物加知柏滋阴降火收功，炒干姜从治以防寒凉太过。", ["数", "伏", "牢"]], "3410": ["病机", "震按夜热脉数本属阴虚，然脉伏且牢、浮取不应，说明火郁于内而非单纯阴虚。故先用升阳散火汤发越郁火得效，继以阴药收功。妙在芎归合知柏，及炒干姜从治，使郁火散而阴血得养，非一味滋阴所能奏效。", ["数", "伏", "牢"]], "3411": ["病机", "脉甚大，症见头痛腹痛、十指酸痛、心志纷纭、鼻息粗甚，是火盛气壅之象。壮年妇人欲近男子不可得，郁火内炽，故脉大而症见纷纭。用凉膈散、青木香丸疏导，更服三黄丸泻三焦之火，火降则脉平症愈。", ["大"]], "3412": ["病机", "尺脉洪而数，时或无力，是肾水不足、虚火上炎之象。发热饮冰、寒药益甚、形体日瘦，皆无水以制火。王太仆谓热之不热责其无火，寒之不寒责其无水，故用加减八味丸补肾，使水足火降而愈。", ["洪", "数"]], "3413": ["病机", "左手心脉浮数而滑，肾肝沉弱颇缓，右手肺脉虚浮而快，脾脉偏弦而快，命门散弱而快，是上焦有热、下元虚衰、脾肾不足之象。身热盗汗、腰以下冷、食则腹胀，皆虚火浮越、脾肾阳虚所致，脉象虚实夹杂。", ["浮", "数", "滑", "沉"]], "3414": ["病机", "脉沉小带伏，症见昏晕昏睡、身凉不食，似阴证而实为真火内郁。沉小伏主邪闭于内，火郁不得外达，故小便一二日不解。周慎斋断为真火，以冷水救之，大汗而解，继用补中益气加炮姜、泽泻温中泻水而愈。", ["沉", "小", "伏"]], "3415": ["病机", "六脉洪大，症见身凉内热、水泻二月、上热下冷、面目红肿，是伏火内郁、火性炎上之象。洪大主火盛，然火伏于内不得发越，故上热下冷。用四物加柴葛升麻升散伏火，栀芩柏清降，使小水行、泻止而愈。", ["洪", "大"]], "3416": ["病机", "六脉俱伏、遍体俱冷、无汗，貌似阴寒，然三日不死、气未绝，慎斋断为\"热极似寒\"，乃热邪深伏于内，阳气不能外达，故脉伏、身冷。以湿布外敷、饮冷水而身热大汗，正是郁热得泄之征。此脉伏非虚寒之伏，乃实热内闭之伏，故用补中益气加黄柏收功。", ["伏"]], "3417": ["病机", "右关独弦、左尺微数、余皆微细搏指，石顽断为\"阴火内伏之象\"。劳心太过、精气滑脱、怵惕恐惧，致阴亏于下、虚火上逆，故尺微数而关弦；余脉微细搏指，是精气内夺、脉道不充。前医峻用参、桂、附导火归源无效，反增牵引掣痛，正见阴火非温补可解。", ["弦", "数", "微", "细"]], "3418": ["病机", "脉七八至、洪大有力，头热如火、足冷如冰、半身不遂、牙关紧急，罗谦甫断为年高气弱、暑气极盛、阳明得令之中暑。洪大数乃暑热炽盛、阳明热壅之象；足冷如冰是热郁于上、阳气不达于下。故用桂苓甘露饮甘辛大寒泻热补气，暑去而脉证俱平。", ["洪", "大", "数"]], "3419": ["病机", "脉皆浮数、按之无力，因食酒肉、多饮潼乳而霍乱吐泻、精神昏愦。浮数为暑热外扰、邪在阳分；按之无力则示所伤之物已出、正气已伤，非实邪壅盛。故罗氏以桂苓白术散、地浆水清暑调中，不用峻攻，吐泻渐止而安。", ["浮", "数"]], "3420": ["病机", "形瘦弱之人，上吐下泻、水浆不入七日，脉八至。汪石山断为\"当夏而得是脉，暑邪深入也\"。数而至于八至，是暑热内逼、正气耗伤之候，故用人参白虎汤清暑益气，后减知母、石膏而加参、柏、麦冬，随兼症佐使，一月平复。", ["数"]], "3421": ["病机", "左右寸关皆伏不应、尺极微，吐泻转筋、足冷多汗、囊缩、口渴欲饮冷水，是暑湿内闭、阳气不达，故寸关伏而尺微。医以伤寒温散则增剧。江氏先以五苓分利，继灸丹田、理中，脉稍出而按之无根、形脱呃逆，终以竹叶石膏汤清解而愈。", ["伏", "微"]], "3422": ["病机", "六月中旬霍乱吐泻转筋，误投藿香正气散反增烦躁面赤、揭衣卧地，脉虚无力而身热引饮。江应宿断为伤暑，脉虚无力是暑热伤气、正气不足之征，非寒湿可温。故用五苓加石膏、滑石辛甘大寒泻其火热，吐泻定后再与桂苓甘露饮收功。", ["虚"]], "3423": ["病机", "震按盛暑霍乱多因暑湿，然亦有因寒者。所举真武汤案，吐泻腹痛、四肢冷、恶寒不渴而脉微细，微细为阳气衰微、寒湿内盛之象，与暑热案之洪数、虚数迥别，故敢用真武汤温阳散寒，取效甚速，且未尝用人参，正见辨证在脉证合参。", ["微", "细"]], "3424": ["病机", "原文谓“弦脉令虚多言之故”，指出弦脉主阳气衰弱，不能舒伸而伏匿于阴中，故脉虽弦而按之虚。此阴盛乘阳，故见视听半失、气短、精神不足。又值霖雨阴寒，湿多成五泄，体重肢痛、大便泄泻、小便秘涩，皆阳气不伸、湿邪内盛之候。", ["弦", "虚"]], "3425": ["主病", "两手脉皆浮数，浮为病在表，数为风邪化热之象。春伤于风，久风入中，肝木克脾土，故米谷不消、腹鸣、飧泄。风邪在表，当汗之，风随汗出则泄愈。此脉浮数正是表邪未解、风客脾胃之征，非脾受大寒，故温补不效。", ["浮", "数"]], "3426": ["病机", "脾脉浮而弦，浮主风，弦主湿，又弦为肝脉。风湿外伤，肝木刑于脾土，而为洞泄、飧泄。原文谓“春伤于风，邪气留连，乃为洞泄”，其利下物浑白而完出，正是风邪乘脾、水谷不化之象。此脉揭示风湿外袭、肝脾相克之病机。", ["浮", "弦"]], "3427": ["预后", "仓公诊赵章病，脉滑，谓“是内风气也”，饮食下咽辄出不留，名曰迵风，法五日死。脉滑主内风，风性急迫，故食入即出。然犹能嗜粥，安谷者过期，后十日乃死。震按指出直肠泻多死，不可概以风药能治，此脉滑示内风洞泄之危候。", ["滑"]], "3428": ["病机", "两寸脉皆滑，戴人断为水饮内停，非寒证。滑脉主水饮痰湿，水气上泛则腹鸣如雷，下注则泻利不止、坐则下注如倾。诸医误作寒证温补，迁延二十年。此脉滑揭示水饮内蓄之病机，故用涌吐、通下、渗利诸法，通因通用而愈。", ["滑"]], "3429": ["病机", "六脉浮濡且微数，濡者湿也，数者脾有伏火也。浮为湿邪在表，微为阳气不足。此湿热内蕴，非沉寒痼冷，故热剂不效。原文谓“病由湿热”，当苦寒逐之，先升阳散火，继以神芎丸下之。脉浮濡微数正是湿热伏火、阳气不伸之征。", ["浮", "濡", "微", "数"]], "3430": ["病机", "脉沉细而微，沉主里，细主虚，微主阳气衰微。年高气弱，形寒饮冷，履于卑湿，清湿袭虚，病起于下，故脐腹冷疼、足䟰寒、完谷不化。此寒湿相合，阳不能外固，非灸不能已其病。脉沉细而微正是寒湿内盛、下焦阳虚之病机。", ["沉", "细", "微"]], "3431": ["病机", "原文未识脉名，然述富翁泄泻弥年，子厚悟为“气不能举，为下脱也”。以艾灸百会三四十壮而泄止。百会属督脉，居顶巅，主一身之气。元气下脱，脾胃无凭，故久泻不止。此条虽无脉象，其病机为气虚下陷、元气不举，与脉之虚软无力相应。", []], "3432": ["病机", "脉微涩为少阴下利之脉。微为阳气衰微，涩为阴血不足，阳虚不能温煦，故呕而汗出；阴血亏虚，肠道失润，故数更衣而反少。此脉象揭示少阴病阴阳两虚、虚寒下利之病机，主泄利不止，与呕、汗出、更衣反少等症相应。", ["微", "涩"]], "3433": ["病机", "两手脉俱涩而颇弦，涩主积滞，弦主痰饮。患者年高形瘦，久泻不止，小便涩少，膈闷食减，脉涩弦提示多年沉积僻在肠胃，积痰在肺，肺与大肠相表里，肺气壅遏则大肠不固而泻。此脉象说明痰积致泻之病机，主积痰在肺、大肠不固之泄利。", ["涩", "弦"]], "3434": ["病机", "右手脉浮大洪数，浮主上焦，洪数为痰热壅盛之象。老人风挛多年，泄泻百药不效，脉见浮大洪数，说明太阴经有积痰，肺气壅遏不能下降，大肠虚而作泻。此脉象揭示痰热壅肺、肺失肃降而致泄泻之病机，主上焦积痰、大肠虚泻。", ["浮", "大", "洪", "数"]], "3435": ["病机", "富儿面黄善啖易饥，非肉不食，泄泻一月，脉大。脉大本主湿热，然湿热当困而食少，今反形健食多不渴，故非湿热，乃疳虫内积，虫耗谷气故善饥，脾失健运故泄泻。脉大在此提示虫积内扰、脾胃不和之病机，主疳虫致泻，与面黄、善啖、便蛔等症相应。", ["大"]], "3436": ["病机", "脉涩重取略弦数，涩主积滞，弦数主肝火。患者性狡躁，素患下疳疮，夏初自利，膈微闷，医与理中汤反致闷厥。脉涩弦数说明下疳深重，湿热毒邪蕴结肝经，肝木乘脾而致自利。此脉象揭示肝经湿热、下疳致利之病机，主下疳深重兼泄利。", ["涩", "弦", "数"]], "3437": ["病机", "右脉洪数，为积痰在肺之征，故丹溪凭此用吐。又吕沧洲案两尺寸俱弦大，右关浮于左关一倍，弦大为肝风之象，右关浮倍说明肝风传脾，目外眦如草滋亦肝风之色。此脉象揭示肝风传脾、飧泄之病机，非藏寒所致，主肝风乘脾之泄泻。", ["弦", "大", "浮", "数"]], "3438": ["病机", "脉双弦而浮，弦主肝风，浮主虚风。御史内飧泄弥年，当秋半见此脉，说明惊风内传，肝主惊，虚风自甚，因乘脾而成泻。此脉象揭示内风相传、肝乘脾土之病机，主惊风致飧泄，与失铜符而惊惧之病因相应，至春病将益加。", ["弦", "浮"]], "3439": ["病机", "六脉虚微，为气阴两虚之象。暑月泄泻，小便赤，四肢疲困，自汗微热口渴，素羸瘠，医误作虚劳欲峻补。伯仁诊得六脉虚微，断为夏月中暑、饮食劳倦，非虚劳也。此脉象揭示暑伤气阴、脾胃虚弱之病机，主中暑挟湿之泄泻，宜清暑益气汤。", ["虚", "微"]], "3440": ["病机", "脉皆濡弱而缓，右脉略大犹弱，濡弱缓为脾虚湿盛之象。患者幼时误服毒药损脾，复伤食大泻，致脾虚不运，故不作肌肤、嗜卧懒语；脾虚湿蕴则喉中痰、小便不利、大便或结或溏。右脉缓弱直接反映毒药损脾。左脉三五不调为动欲摇精，非本段主脉。", ["濡", "弱", "缓", "大"]], "3441": ["其他", "原文为震按语，称“脉甚奇，论脉亦奇”，纯属评述，未出具体脉象。其意在于提示学者此案脉象特殊、论述精妙，可广见闻，非直接主病或病机。故脉象要素为空，主旨归为其他。", []], "3442": ["病机", "脉濡缓而弱，濡缓主湿，弱主虚。程明佑据此断为“脾伤于湿”，因患者饮酒过多，酒湿伤脾，脾恶湿，故下泄、勺水粒米不纳、服汤药即呕。脉象直接反映脾虚湿困之病机，与饮酒致湿、脾失健运之症相应。", ["濡", "缓", "弱"]], "3443": ["病机", "震按指出“濡缓而弱是虚脉，亦是湿脉”，明确濡缓弱兼具虚与湿双重病机。前案以参、苓、术作糕代汤，既补脾虚又不助湿，正是针对虚湿相兼之机。此段虽为评述，但紧扣脉象说明虚湿为病本，故归病机。", ["虚"]], "3444": ["病机", "久患泄泻，暖药补脾及分利小水不应，一医诊得“心脉独弱”，遂以益心气药兼补脾药而愈。心脉独弱提示心火不足，不能生脾土，故脾运失职而泄泻。此脉主心火虚衰、脾土失养之病机，与久泻不止、补脾无效之症相应。", ["弱"]], "3445": ["病机", "六脉皆浮，浮主表。患者素纵饮喜瓜果，忽大泻，分利燥湿不效。李士材引“春伤于风，夏生飧泄”，断为风邪外袭、内陷致泻，故脉浮。用麻黄、升麻取大汗以解表邪，表解则泻愈。此浮脉主风邪伤表、表邪内陷之病机。", ["浮"]], "3446": ["病机", "脉洪大且数，洪大为热盛，数为热急。患者泄泻清水、白脂上浮、肛门火灼、腹中绞辣，诸症皆火热之象。缪仲淳据此断为“火热所生病”，用黄连、白芍等清热。此脉主火热内盛、迫津下泄之病机，与泻下急迫、灼肛之症相应。", ["洪", "大", "数"]], "3447": ["病机", "两手寸关洪滑，两尺沉伏。洪滑主实热痰积，沉伏主积滞内闭。孙一奎断为“肠胃中有食积痰饮”，因积滞内阻，气血壅滞于寸关而现洪滑，尺部沉伏为积滞深结。此脉主食积痰饮内停之病机，与五更倒饱、腹脹痛泻之症相应。", ["洪", "滑", "沉", "伏"]], "3448": ["病机", "原文谓“尺寸脉隐伏不见，惟两关沉滑”，因“积胶于中”，中焦食积痰滞胶结，气机壅塞，故尺寸之脉隐伏不见；两关沉滑，正是食积痰浊内阻之象。积滞不去则脉道不利，非六脉将绝。下其积后“次日六脉齐见”，反证脉伏由积滞所致，主病机为食积痰泄。", ["沉", "滑"]], "3449": ["病机", "原文述下利日久，“血尽而下尘水，水尽而去肠垢”，阴血阳气耗伤，脉见“虚软无力”，为气血俱损、脾阳下脱之候。然喻氏据“双眸尚炯”“汗出不过偶有”断上焦阴与他脏阳犹存，故脉虚软无力主脾中阳气下脱，而非阴阳离绝，属可治之候。", ["虚", "软"]], "3450": ["病机", "原文谓“两寸脉浮而空、关尺脉微而细”。便后寒热，因努挣伤气，阴乘阳位，故寸脉浮空；误用滑利驱导，致阴虚泉竭，肠澼下注，关尺脉微细，为下焦阴亏、脾肾气弱之象。浮空非表邪，微细非实滞，乃内伤虚损、阴阳不相接续之病机。", ["浮", "空", "微", "细"]], "3451": ["病机", "原文谓“脉气口大二倍于人迎，右关尤有力”。气口主脾胃，右关候中焦，因炙肉潼乳“饮食自倍，肠胃乃伤”，食积填塞肠胃，气机壅实，故右关脉大而有力。气口大于人迎二倍，明非外感，乃内伤饮食、肠胃俱填塞之实滞病机，故用峻剂斩关夺门。", ["大"]], "3452": ["病机", "原文谓“寸口脉促，而两尺将绝”。啖马肉过伤，食积壅塞胸中，新邪与宿食相搏，气机逆乱，故寸口脉促；误用大黄巴豆攻下，反夺其正气，致两尺将绝。促脉主胸中邪实、气逆不降，故项氏曰“胸有新邪，故脉促”，宜引之上达而用涌剂。", ["促"]], "3453": ["病机", "原文谓“寸关弦紧”。暑月过啖瓜果，寒湿淫胜，困阻中焦，气机收引，故寸关脉弦紧。弦主寒、主痛，紧主寒实，寸关候上中二焦，正合瓜果寒湿伤于胸膈、胀痛之证。前医以二陈平胃加查芽不应，因非一般食滞，乃寒湿胶结，故用辛温香窜之品消之。", ["弦", "紧"]], "3454": ["病机", "原文仅言“六脉俱有”，未载具体脉象，故脉象要素为空。腊月赌食羊肉数斤，冷油冻住，堵塞胸膈，胀闷欲死，乃食积寒凝、气机闭塞之实证。六脉俱有，说明脉气未绝，正气尚存，故可施吐泻之法以去壅塞，非死候也。", []], "3455": ["病机", "原文谓“六脉虽皆涩弱模糊，而心下按之大痛，舌上灰”。夏月伤食，呕吐发热自利，脉涩弱模糊似虚，然心下按痛、舌灰，乃食积痰热内壅，气机阻滞，脉道不利所致。涩弱非纯虚，模糊非阳脱，故石顽断为实证，主病机为食积化热、壅遏中焦。", ["涩", "弱"]], "3456": ["预后", "两寸关涩数模糊，主宿食痰湿壅滞中焦；两尺沉弦按之益坚，为陈寒疝积少腹。脉少冲和，胃气已败，加之食积与疝瘕上下交攻，正气无容身之地，故断为必死。", ["涩", "数", "沉", "弦"]], "3457": ["病机", "脉沉涩短小，重取皆有，沉主里，涩主瘀，短小为元气虚。情志不遂，气郁胃口，久病入络，瘀血内结，又因勉强进食，郁而生痰，故脉见沉涩短小，主气郁血瘀兼元气已虚。", ["沉", "涩", "短", "小"]], "3458": ["平脉", "六脉匀平，形色不变，起居如常，虽长期不食粥饭而仅啖杂食，脉象冲和，说明胃气未败，故许以无事。此段以脉平辨非病，强调胃气为本，与绝食者不同。", ["匀", "平"]], "3459": ["主病", "脉弦数，弦为疟脉之常，数为热盛。远行劳役，暑气酒热相搏，阳盛阴虚，但热不寒，发为瘅疟。脉弦数正合疟邪内郁、热盛于里之机，故主多热之瘅疟。", ["弦", "数"]], "3460": ["病机", "脉微数，微为正气虚，数为虚火动。久痢伤阴，悲哀伤气，又服湿热之药助火，正气愈虚，汗出如雨，阴虚阳散，故脉微数，主正虚邪少、阴阳将脱之危候。", ["微", "数"]], "3461": ["病机", "脉伏，为实热痰浊内闭，阳气不能外达。痎疟间日发，寒多热少，口干喜热饮，面惨晦，脉伏而证似实热痰结，故以十枣汤峻逐痰饮，脉伏主痰实内伏之病机。", ["伏"]], "3462": ["病机", "原文未出脉名，以症测机。入房感寒，足阳明与冲脉之气夺于所用，寒乘虚入舍二经，阳气衰不能渗荣经络，故疟作而寒热久羁。此段重在阐明寒伤二经、阳虚不能托邪之病机。", []], "3463": ["病机", "两手尺数而有力，尺主肾，数而有力为湿热伏结于肾。中焦湿热下流，伏结肾中，心火不得下交，上连于肺，故疟嗽俱作。脉数有力，主肾中伏热，非虚火可比。", ["数"]], "3464": ["病机", "原文载“两手脉俱无”，非气血衰绝，乃“积痰生热，结伏其脉而不见”。痰热壅阻，脉道不利，故脉伏不见；经不行亦因痰碍而非无血。丹溪初疑虚寒，后见梳妆言语如常，知为痰热实证，以三花神佑丸下之，脉渐出而带微弦，疟未愈，示痰热未尽。此脉伏主痰热内结，与形神不衰、经闭相应。", []], "3465": ["病机", "原文述脉“或洪大，或微细，或弦紧，或沉伏，难以名状”，为久疟后气血大虚、阴阳乖乱之象。洪大微细交替，弦紧沉伏杂见，非一脉可定，反映正气溃散、邪气未净。薛立斋用六君子加炮姜温补脾胃，脉证渐得，继以参术膏、归脾汤百余剂而痊，说明此脉象主气血虚败、疟邪深入，与“百病蜂起”相应。", ["洪", "大", "微", "细"]], "3466": ["病机", "脉“濡弱近快稍弦”，濡弱为气血两虚，稍弦示疟邪深入厥阴。汪石山据色脉断为“气血两虚，疟已深入厥阴”，故专用血药恐损胃损肺，久疟成劳。以补中益气汤倍参、耆、术，佐川芎、黄柏、枳实、神曲、麦冬，诸证稍除而疟未止。此脉主虚中夹邪，与寒少热多、自汗体倦、头痛胸痞、略咳而渴、恶食相应。", ["濡", "弱", "弦"]], "3467": ["病机", "脉“濡小而驶，脾部兼弦”，濡小为暑湿伤气，驶为热，弦主痛、主疟。汪石山辨为风暑乘虚入于阴分，非阴证脉绝，故不可进附子汤。果见寒少热多、头痛躁渴、痞闷呕食、自汗、大便或泻或结，皆暑湿郁遏、脾胃不和之候。用清暑益气汤加减，二十余帖而愈。此脉主暑湿内蕴、气虚邪伏，与上述症候相应。", ["濡", "小", "驶", "弦"]], "3468": ["其他", "此段为震按语，非论脉象，乃评汪石山“姑待以观其变”之法。原文谓“脉证有可疑处，猛浪投以重药，脱有所误，噬脐何及”，强调脉证未明时不可孟浪，待其变而后议药，方为老医老到处。所主不在病机，而在诊治态度，故脉象要素为空，归入其他。", []], "3469": ["病机", "脉“数，皆六至而无力”，数而无力为气虚有热，非实火。汪石山据形瘦色黑、间日午后发，本属血分，但汗多阳虚、消谷善饥为胃虚火乘，俱为气虚之证，故凭证不凭脉，作气虚治。用参、耆、术、芍、麦冬、归、地等，二十余帖而安。此脉主气虚发热，与汗多、善饥、疟发午后相应。", ["数"]], "3470": ["病机", "震阅石山治疟案二十二条，所载脉象或浮濡无力、或浮而欲绝、或濡小而缓、或浮大而濡、或濡弱近驶稍弦、或数而无力，总以濡软虚象为主。震谓“分明参耆术草之病”，即脉示气虚，少分寒热自易取效。此段归纳脉象，主气虚疟疾，与参、耆、术、草证治相应，故仅登三条，余可类推。", ["浮", "濡", "数"]], "3471": ["病机", "六脉沉细，沉主里、细主虚，为太阴中寒之象。李士材断为“疟伤太阴，中寒蛔动”，故吐蛔、闷不思食。用理中汤加乌梅、黄连，温中安蛔，四剂后胸中豁然，寒热减、蛔不吐；去黄连加黄耆、生姜，五剂而疟止。此脉主中焦虚寒、蛔虫扰动，与吐蛔、闷不思食相应。", ["沉", "细"]], "3472": ["病机", "脉弦细而濡，弦细为虚为暑，濡为湿。暑邪成疟，湿热乘虚内陷而腹痛。此脉示暑湿内陷、正气已虚，故见但热不寒、热躁谵语、腹痛昼夜无间、勺水不进、疟发时厥去等症。", ["弦", "细", "濡"]], "3473": ["病机", "六脉虚数，虚为阴虚，数为暑热。此阴虚而暑入阴分，故疟发于暮、热甚于夜。脉虚数示正虚邪伏，最难治，当先升举其阳，后以丸方滋阴清热、健脾和营。", ["虚", "数"]], "3474": ["预后", "脉豁大空虚，且寒不成寒、热不成热、气急神扬，知为元阳衰脱之候。豁大空虚乃阳气外浮、根本已离，故预后险恶，次日果大汗不止、昏不知人、口流白沫，几于不救。", []], "3475": ["病机", "六脉止歇，按之二至一止，举指三五至一止，寒热之际则不止歇，热退则止歇如前。此真气衰微，不能贯通于脉，故止歇不前；寒热时邪气冲激经脉，反得开通。乃虚中伏邪之象。", ["结", "代"]], "3476": ["其他", "此条论歇止脉最有见，用常山法为巧作。然寒热不止、脉止如前，巧且无益，惟日进人参一两不兼他药，真大巧若拙。强调歇止脉属真气衰微，当以补虚为要，非巧法可愈。", []], "3477": ["病机", "内经论瘅疟纯是实热证，中气实而不外泄，用力出汗，风寒舍于皮肤分肉，阳气盛而不衰。经文虽不言脉，谅脉之洪实有力可知。此脉示实热内盛，故谵语遗尿不死，然八旬之外死者甚多。", ["洪", "实"]], "3478": ["病机", "六脉如丝，面青唇白，乃阳气衰微、气血大虚之象。疟发辰戌丑未而子午卯酉增小寒热，示中土无权、邪并至阴。用六君子加桂附、重用人参，脉证渐复，终以独参汤送八味丸调理而安。", ["细"]], "3479": ["病机", "六脉但微数，无他异，此肾脏本寒、闭藏不密、易于招风，下寒则虚火上僭故脉数。疟后脉弦细而数，面青足冷，寒甚不甚热，乃下寒虚火之象，用八味地黄三倍桂附温补而愈。", ["数", "弦", "细"]], "3480": ["治法", "原文强调“不以六脉带数而畏投温药”“不以脉之细数而不倍加桂、附”，脉数本主热，细主虚，然此案脉数细而仍用温补，说明病机为虚寒内盛、格阳于外之假热，非真热证。脉数在此非实热，乃虚阳外越之象；细为气血不足。故治疗当温肾助阳，不可因脉数而畏用桂附，体现辨脉须结合症候、不可拘泥于脉数的思想。", ["数", "细"]], "3481": ["病机", "脉弦涩而结，尺中倍弱，弦主肝郁，涩主血少，结为气滞血瘀，尺弱为肾虚。原文断为“内伤重而外感轻，得之劳倦且郁，病在肝脾两经”，劳则伤脾，郁则伤肝，肝脾气血两伤，邪气内结。故脉象反映虚中夹实、气血郁滞之病机，治当大顾元气、微兼治邪，用人参、桂枝、黄连、肉桂等扶正达邪。", ["弦", "涩", "结", "弱"]], "3482": ["其他", "此段为震按，述印机草中寒热痞闷中州结痛等案，用药多端。原文仅言“脉象浮涩、脉症和”，浮涩为表虚兼涩滞之象，脉症相合，故可随证施治。浮主表，涩主气血不畅，脉症和提示病机与脉象一致，治疗或温或清，总以调和为要。此段主旨在于讨论不同脉症下的治法选择，故归为其他。", ["浮", "涩"]], "3483": ["病机", "少年疟后白浊，寒热渐重，口渴烦躁，舌赤唇焦，两足如烙，似属热证，然“脉虚而软”，虚软为阳气不足、虚阳浮越之象。前医误用白虎汤而热益甚，更伤阳气。沈尧封用人参、熟附子、茯苓、白芍温补回阳，一剂热定。脉虚软说明病机为真寒假热、阳气虚衰，故温补得效，体现脉诊辨虚实之关键。", ["虚", "软"]], "3484": ["预后", "此段论疟疾轻重及脉象预后。原文提及“脉不数者”“脉弦数或洪数者”“脉散”“脉细软者”“脉洪实者”，弦数洪数主热盛，散为正气涣散，细软为虚，洪实为邪实。脉象不同，预后各异：脉数而有力者邪盛，脉散者正衰，脉细软者虚，脉洪实者实。结合疟发渐早渐晏，判断正气虚实与邪气盛衰，以定吉凶，故主预后。", ["弦", "数", "洪", "细"]], "3485": ["病机", "叶仪病滞下，前医日服补药而病日增，朱彦修诊“气口脉虚”，然形症俱实，痰窒咽如絮、呻吟昼夜，脉虚为假象，实为积滞内阻、正气被遏。彦修断为实证，用小承气汤攻下，药下咽即觉所苦自上下，一再行而愈。脉虚在此非真虚，乃邪实阻滞、脉气不充之假虚，故攻下取效，说明辨脉须参合形症。", ["虚"]], "3486": ["其他", "此段为震按，比较许学士治伤寒太阳病因尺脉不应用黄耆建中与本案先补后攻之法，强调“把握得定，故嫌疑不避”。原文未直接描述脉象，仅提及“尺脉不应”，属脉症不符时凭脉断病之例。主旨在于讨论治法先后及医者决断，非专论脉象主病，故脉象要素为空，归为其他。", []], "3487": ["病机", "痢久不愈，脉沉细弦促，右为甚。沉细主里虚，弦主痛主瘀，促为气滞血瘀、郁而化热。丹溪断为“瘀血痢”，因饱食疾走、大怒不泄、补塞太过等致瘀血内停。脉沉细弦促反映瘀血内阻、气血不畅之病机，故用乳香、没药、桃仁等活血化瘀，佐以木香、槟榔、大黄攻下，下秽物而愈。", ["沉", "细", "弦", "促"]], "3488": ["病机", "脉弦数主肝郁化热，独胃脉沉滑则示酒湿积滞于胃。老人面白，饮酒作痢、下淡水脓血、腹痛里急后重，正是湿热积滞下注大肠、气机壅滞之象；小便不利为湿阻下焦。弦数应肝热，沉滑应胃中湿滞，故丹溪以参术扶脾、滑石槟榔木香苍术化湿行滞，药证相合。", ["弦", "数", "沉", "滑"]], "3489": ["病机", "脉皆弦而涩、似数稍长而不甚浮大，弦主气郁，涩主血少，数而长为郁热，不浮大则非外感实邪。原文谓'忧虑所致，心血亏，脾气弱'，故见滞下褐色、后重食减、微热、神气大减。弦涩相合正是气血两亏兼郁滞之机，故以参术为君补脾，归芍川芎养血，少加黄连清郁热。", ["弦", "涩", "数", "长"]], "3490": ["病机", "左脉弦大似数、右脉弦大稍减亦似数、重取似紧，弦大为虚寒中气不运，紧为寒积内结。原文断为'醉饱后食寒凉太多，当作虚寒治之'，故腹痛痢下而服干姜暂定。虽服干姜三斤，脉仍弦紧，示寒滞未化、气血已伤，故用四物加参术陈皮桃仁姜汁，温养兼行滞。", ["弦", "大", "数", "紧"]], "3491": ["病机", "脉稍大不数，大而无力为气阴两伤、虚热内扰之象，不数则非实热。原文述质弱多怒、大饥索饭、暑月滞下，又饮冷水生蜜，久下伤阴，故倦甚发呃。'脉稍大不数'正合虚证，故用人参白术汤调益元散补气清暑，反对用姜附，恐助热伤阴。", ["大", "数"]], "3492": ["预后", "脉皆大豁，大而豁然无力，为久病胃气衰败、阴血亏耗之象。患者年近七十、厚味久喘、新秋患痢、食减呕逆发呃，脉证相符，众以为难。丹溪以'形瘦者尚可为'断其可治，用黄柏丸配参术苓浓汤，补脾坚阴，忌丁香热药，示大豁之脉虽危而胃气未绝犹可挽回。", ["大", "豁"]], "3493": ["病机", "脉沉而滞、尺涩，原文自释'沉滞则气不和，涩则精血伤'。沉滞主气机郁滞，尺涩主精血亏伤，合之则为气血滞郁。病由积郁强食，气血俱伤，故滞下腹痛腰胀。治当调血和气，投四物五苓木香，倍当归通经而痢止，正合'气血滞郁'之病机。", ["沉", "滞", "涩"]], "3494": ["病机", "脉皆濡散颇缓，濡为湿滞、散为气虚不敛、缓为胃气尚存。年逾六十患滞下，自用利药伤正，后重未除，脉见濡散，示脾气已虚而湿滞未清。故用人参归芍升麻补气升提兼和血，后重除而滞下止；后生核胀痛，亦因努责气血下滞，仍以参芪升麻收功。", ["濡", "散", "缓"]], "3495": ["病机", "脉皆细弱而数，细弱为气血两虚，数为虚热，非实火。病痢半载，医投四物凉血及香连丸愈增，脘腹痛甚、里急后重、嗳气烦热，皆久下肠胃虚而寒凉助降之害。原文断'肠胃下久而虚'，引'下者举之，虚者补之'，故以参术为君、升麻升举，补虚举陷而安。", ["细", "弱", "数"]], "3496": ["病机", "两尺脉紧而涩，紧主寒，涩主血瘀，尺部候肾与下焦，故知寒伤营血。原文谓“血被冷水所凝，瘀血归于大肠”，经期饮冷致血凝，瘀阻大肠而痢下黄黑、痛而急迫，此脉正合寒凝血瘀之病机。", ["紧", "涩"]], "3497": ["病机", "震按重申尺脉紧涩为寒伤营之据，紧涩相合，寒凝血脉，营气不通。前医误用薷、连寒凉，其患愈剧，正因未识此脉所主之寒瘀。虽后重急迫似宜下，然脉紧涩示寒，故仍以承气加逐瘀，佐证脉象对病机判断之关键。", ["紧", "涩"]], "3498": ["病机", "脉洪数按之微细，洪数为假热之象，微细乃真虚之本质。原文谓“假热而治以假寒”，停食患痢，过用疏导致足肿食少、烦热作渴，洪数应假热，微细示中虚。故以六君子加姜桂吴萸温补，冷饮取假寒之意，脉证合参方识真假。", ["洪", "数", "细"]], "3499": ["病机", "脉鼓指而有力，原文断为“真气虚而邪气实”。年八十患痢，腹痛呕恶不食，热渴引汤，手按痛止，脉虽鼓指有力却属虚阳外越、邪实内阻之候。故急用人参术苓附子等温补，服后脉证顿退，此取证不取脉，示暴病当从证辨虚实。", []], "3500": ["病机", "震按补充立斋“取证不取脉”之论，若证现实热而脉微细或按之空豁，则当从脉不从证。微细主气血虚衰，空豁为虚甚，纵有实热假象，亦须顾护正气。此段强调脉证相参，不可偏执一途，脉微细在此提示真虚本质。", ["微", "细"]], "3501": ["病机", "左脉浮紧为外感风寒，右脉滑大为内伤食积，原文断为“内伤挟外感”。浮紧应表寒，滑大主里实痰食，故先用败毒散解表，表证退后以平胃散加理气消食，终下黏硬物而愈，脉象先后对应表里病机层次。", ["浮", "紧", "滑", "大"]], "3502": ["病机", "左脉浮弦为郁怒伤肝、气机不畅，右关略滑主中焦食积，六脉微数示积热内蕴。原文谓“郁闷中食物所致”，素恼怒则肝郁，食积化热，故以舒郁理气调中取效。另一案六脉微数，肥甘积热，以酒蒸大黄清利，脉数应内热之机。", ["浮", "弦", "滑", "数"]], "3503": ["预后", "六脉大数，人迎偏盛，原文断为“风邪热毒”。大数为邪热亢盛之象，人迎主外，风热毒邪充斥。虽人参败毒散二服即愈，而六脉仍前大数，龚氏谓“数则烦心，大为病进”，预言痰喘之患，后逾月果如其言，此脉示邪热未清、病势进展之预后。", ["大", "数"]], "3504": ["病机", "原文指出“病退脉不退”而脉仍“数大”，说明邪热虽退而阴液未复，虚热内生，故脉数大。数主热，大主虚，此脉数大乃阴虚阳浮之象，非实热可比。震按质疑何不用补阴药以治其脉之数大，正点出此脉所主为阴亏不能制阳之病机，与口干发热、饮食不进等症相应。", ["数", "大"]], "3505": ["病机", "脉大而数，按之豁然，乃内真寒外假热之象。火衰不能生土，故下痢完谷不化；虚阳外浮，故脉大而数。按之豁然无力，说明非实热，而是阳气衰微、阴寒内盛，格阳于外。与腹痛喜按、小便清利等症相应，故用附子理中汤温补取效。", ["大", "数"]], "3506": ["病机", "脉滑而有力，为积滞内阻、邪实壅盛之象。滑主痰饮食积，有力主实，故士材断为“失下之故”。积滞不去，脉仍有力，故继用前方下积滞如鱼肠者。此脉所主为肠胃积滞、实邪内结之病机，与痢下不爽、腹痛等症相应，下后脉力和缓则愈。", ["滑", "有力"]], "3507": ["其他", "此段为震按评语，未出具体脉象，仅言“其得手处总在于能审脉也”，强调前案成功关键在于审察脉象以断病机。虽无脉象要素可录，但主旨在于脉诊在辨证中的决定性作用，故归为其他，提示临证须以脉参证，不可仅凭症状。", []], "3508": ["病机", "脉大而滑，病久身凉而脉大，祝氏细视胃脉乍大乍小，断为胃上积寒、胃下积热之寒热错杂证。大主虚，滑主积，脉大而滑说明久病正虚而积滞未去，寒热互结于中焦，故见噤口痢、饮食不进。与面热身凉、便出脓血等症相应，治以温凉并用。", ["大", "滑"]], "3509": ["病机", "两手皆滑大，尺部尤搏指，孙氏断为积滞内结下焦，非逆证。滑主积，大主实，尺脉搏指说明邪积在下，故虽噤口多日不食，仍可“引而竭之”。此脉所主为实积壅遏、邪在下焦之病机，与里急后重、昼夜三十余行等症相应，下之则生。", ["滑", "大"]], "3510": ["病机", "左脉沉弦，右脉滑数，沉弦主肝郁气滞，滑数主湿热积滞。孙氏以病人禀薄多劳，不敢疏下，先以胃风汤加黄连，不效。此脉所主为湿热积滞与肝郁并存、虚实寒热错杂之病机，与里急后重、口渴汗出、胸膈焦辣等症相应，故治难取效。", ["沉", "弦", "滑", "数"]], "3511": ["病机", "六部俱豁大，浮中沉无力，四至，虽痛虽发热而脉无力，慎柔断为虚寒。大而软主气虚，数而无力主虚热，脱血益气正宜。此脉所主为气血两虚、中阳不足之病机，与下红血一桶、痛不可忍、发热流汗等症相应，故用六君子、异功散温补取效。", ["大", "软", "数"]], "3512": ["病机", "两寸关弦数，弦主气滞，数主热，示热邪壅滞肠胃，气机不畅，故里急后重、白积兼鲜血；两尺似有似无，因高龄尺脉本弱，非肾虚主证。高果哉凭寸关断为实热，用清理而愈，说明病机在肠胃湿热积滞，非虚寒。", ["弦", "数"]], "3513": ["病机", "脉沉数有力，沉主里，数主热，有力为实，示阳邪陷入阴分，热郁于里，故休息痢昼夜十余行；面目浮肿、肌肤晦黑为邪郁日久。喻嘉言谓“阳邪陷入于阴”，用逆流挽舟法提邪从表出，正是针对此沉数有力之脉所反映的里热壅遏病机。", ["沉", "数"]], "3514": ["病机", "脉弦紧劲急、不为指挠，弦紧主痛、主实，劲急示邪势鸱张，故断为“一团毒火蕴结肠胃”，症见痛甚、肛门如火烙、躁扰无奈。火毒炽盛，脉应其势；后脉势和柔，知毒火已衰，病可愈。此脉直接反映实火内结之病机。", ["弦", "紧", "急"]], "3515": ["病机", "脉数大空虚，尺脉倍加洪盛。数大主热，空虚为正气不足，尺洪盛示少阴受邪。喻嘉言判为“两病凑于一时”：内有湿热欲成痢，又犯房劳骤寒乘少阴。故发热身重、昏沉不食，下利变色。此脉示正虚邪实、太少两感之复杂病机。", ["数", "大", "虚", "洪"]], "3516": ["预后", "六脉弦细欲绝，弦细为阴血亏少、阳气衰微，欲绝示胃气将败，故噤口痢、发呃神昏、痈毒陷伏。张路玉谓“幸脉无旺气，气无喘促，体无躁扰，可进温补”，以脉无实象为可补之据。此脉主正气虚极，预后虽危而尚可温补图救。", ["弦", "细"]], "3517": ["其他", "此段无脉象描述，主论痢疾无正形、治痢无正形，引儒门事亲食甜瓜愈痢及刘宗厚“脾胃伤冷”之说，强调生冷太过致积滞下痢，咎在“太过”。所论为病因与治则，非脉诊病机，故脉象要素为空。", []], "3518": ["病机", "脉洪弱而数，或一二至辄一止，洪数主热毒，弱为正气不足，歇止示毒陷少阴、心气不续。孙见心断“毒及少阴，当急顾阳明”，用生地、归芍、黄连等。后洪数减、至数相续，午后弦脉亦减，说明邪退正复；歇止随病减而缓，非死候。", ["洪", "弱", "数", "弦"]], "3519": ["预后", "脉促止，即洪数而歇止。震按此案与朱孔阳弦动不为指挠者有别，故以生地换大黄，从炙甘草汤得法。洪数歇止为阳热有余而脉道时阻，尚属可治；若细涩无神而歇止，则正虚邪陷，断不可治。此段以脉之促止辨预后吉凶，兼以能食腹痛为吉。", ["促", "洪", "数"]], "3520": ["病机", "脉软不数，软为虚象，不数为无热，提示便血日久，脾气已虚，非实热迫血。前医凉血不效，叶氏以温运脾阳、化湿消滞取效，说明病机在脾虚湿滞，统摄无权，故脉不数而软。", ["软", "数"]], "3521": ["病机", "脉弦而微如蛛丝，弦为寒湿滞脉，微为阳气衰微，如蛛丝则真气衰弱已甚。寒湿久淹，脾胃阳伤，故身体沉重、手足寒逆、麻木、痞满呕逆。形气病气俱不足，针所不为，灸之则宜，治以温补。", ["弦", "微"]], "3522": ["病机", "脉虽沉迟，按之有力，沉主里，迟主寒，有力为实，说明积暑伏痰与食滞内结，虽下利不食而邪实未去。沉迟非纯虚寒，故可下之，消滞丸通利后宿积去而思食，继以和平调之。", ["沉", "迟"]], "3523": ["病机", "脉沉有力，沉主里，有力为实，结合中满而痛，知病在里不在表，为食积痰滞内结。故以消导药愈，与专事发散者不同。著眼在脉沉有力，确指里实，非表邪未解。", ["沉", "有力"]], "3524": ["预后", "下痢脉洪大者死，细微者生，洪大为邪热炽盛、正气反伤之逆象。此案寒热大作、痢下八十余行、腹痛恶心、神气倦甚，脉洪大预示正虚邪盛，预后不良，故客言脉不吉。", ["洪", "大"]], "3525": ["病机", "案载脉洪大，不载有力无力，洪大可为实热，亦可为虚阳外浮。孙公以温补取效，说明此洪大非暑邪实热，乃阴盛格阳、虚阳上浮之象。若果暑邪，少量石膏滑石岂能敌大剂参术姜附，故当辨虚实。", ["洪", "大"]], "3526": ["病机", "左脉浮弦而数，浮为风邪在表，弦为疟邪内郁，数为热；右软弱，中部稍滑，为内伤饮食、脾虚湿滞。合之头疼口渴、下午发热、小水涩痛，乃外感风邪、内伤饮食，疟痢并作，故先解表清里，后调补中焦。", ["浮", "弦", "数", "软"]], "3527": ["治法", "右关脉大，为腑实邪滞，故可加厚朴以通降；右脉耎弱为虚，示脾虚不足，不可过用攻伐。此案疟痢并作，初起发散提邪外解，右关大加厚朴，右脉耎弱则当顾虚，体现凭脉辨虚实以定治法。", ["大", "耎", "弱"]], "3528": ["病机", "左关沉弦为肝郁，右寸微数为热，沉弦主郁，微数主热，郁热不行，肝气上逆致呃逆。原文“沉弦为郁，微数为热”点明病机，恼怒伤肝，木郁达之，故用涌剂疏肝平气。", ["沉", "弦", "微", "数"]], "3529": ["病机", "脉不可诊，视形气实，因大怒而呃逆，举身跳动，神昏，此肝气暴逆，痰随气升，蒙蔽清窍。形气实提示邪实，故用参芦涌吐顽痰，痰去气降则安。", []], "3530": ["病机", "老人素厚味，久喘患痢，食减数日呃作，脉豁大。豁大示胃气虚弱，虚气上逆为呃，形瘦可治，故用参术汤下大补丸补益脾胃，七日而安。", ["豁", "大"]], "3531": ["病机", "伤寒误补发呃，脉长而实大，此阳明内实，燥热内结，腑气不通，胃气上逆。长实大为邪实壅盛之象，故用大承气下之，热退呃止。", ["长", "实", "大"]], "3532": ["其他", "震按对比前条脉长实大易辨，豁大用参术佐黄柏，因形瘦素厚味有郁热；女子脉不可诊，凭形气实用参芦涌吐，为稳著。此段评述脉症合参之难，非直接论病机。", ["长", "实", "大", "豁"]], "3533": ["病机", "伤寒热退后呃大作，脉沉细无力，人倦甚，此中气大虚，虚寒上逆。沉细无力为阳气衰微，故用补中益气汤加姜附，兼灸气海乳根，温补元气而呃止。", ["沉", "细"]], "3534": ["病机", "呃十余日，热药益甚，脉阳明大而长，右口之阳数而躁，此胃热致呃，热药助热误矣。大长数躁为阳明热盛，胃火上逆，故用竹茹汤清胃热而愈。", ["大", "长", "数", "躁"]], "3535": ["病机", "震按服热药益甚，脉长大数躁，宜大剂白虎，有下证佐承气，竹茹汤恐不济。长大数躁示阳明热炽，非轻剂可解，此强调脉症合参以定治法。", ["长", "大", "数", "躁"]], "3536": ["病机", "肝脉弦数且滑，弦主肝郁，数主火，滑主痰。怒而饮酒，肝火挟痰上扰，故病不知人、号叫复昏。此脉象揭示怒火痰浊交阻之病机，主痰火蒙窍之证，与昏厥、号叫相应。", ["弦", "数", "滑"]], "3537": ["病机", "脉虚甚，重取则散，虚为气弱，散为阳浮不敛。疟后多汗，汗多亡阳，阳气外越，故见昏厥、闻声即作。此脉主汗多亡阳之病机，与惊厥、汗出相应。", ["虚", "散"]], "3538": ["病机", "脉结止，苏则如常，但浮虚耳。结主血少气劣，浮虚为气血不足。病发时气血壅滞故结，苏时流通故如常。此脉示虚病，主气血两虚，与瞀昧、目系急、昏懵相应。", ["结", "浮", "虚"]], "3539": ["病机", "六脉俱微，若有若无，欲绝非绝，微为阳气衰微。气虚极则阳不达四末，故手足厥冷、不知人；少顷发热则渐省，乃阳气暂复。此脉主气虚极之证，与厥冷、昏不知人相应。", ["微"]], "3540": ["病机", "六脉俱伏，今左寸短涩。伏为邪闭气机，短涩为血瘀不行。瘀血阻于心胸，气机不通，故晕厥、心痛、汤水难入。此脉主瘀血内阻之病机，与晕厥、心痛、气促相应。", ["伏", "短", "涩"]], "3541": ["病机", "三部脉象虚软无力，虚为正气不足，软为脾弱。惊痰堵塞窍隧，邪盛正衰，故虚软无力。此脉示正虚邪盛，主惊痰内闭而脾肺气虚，与痰厥频发、四末肿麻相应。", ["虚", "软"]], "3542": ["病机", "脉弦紧而急如真弦，或细而弦劲带数。弦紧主风动，急为筋脉挛急，细数为血虚有热。劳倦伤血，疮后血虚，风寒乘虚入，故发痉。此脉主血虚风动之病机，与抽搐、跳跃、震动相应。", ["弦", "紧", "急", "细"]], "3543": ["病机", "六脉沉伏，沉为病在里，伏为气机闭阻。身热误补，中焦实而脾不运，胃阳不行于肌肉，故身体强硬、气喘不能吸。此脉主中焦实滞、脾不运之病机，与身强、气喘相应。", ["沉", "伏"]], "3544": ["其他", "本案未载脉象，仅述脐腹冷痛、引胁、闷乱不得卧，先灸中庭，后以当归四逆汤加味温通而愈。从症测机，属寒凝任脉与厥阴，气血痹阻，故痛引胁下、反复闷乱。原文无脉，不能以脉析机，然治法温散可反证其病性属寒实。", []], "3545": ["病机", "脉得沉小而急，沉主里、小主收引、急主痛，合为寒实内结之象。原文引《难经》谓任脉为病，男子内结七疝，皆积寒于小肠所致。寒实非虚，故脉不急微而急，治用大热之剂，以沉香桂附丸、天台乌药散逐寒积，旬日良愈。", ["沉", "小", "急"]], "3546": ["病机", "脉两手沉结不调，沉为在里，结为气机阻滞、寒凝不散。原文谓寒疝自脐下上至心胀满攻痛、胁疼尤甚、呕吐烦懑，断为寒在下焦，宜亟攻其下。沉结不调正合寒实积于下焦、气血不通之机，故灸章门气海中脘，佐温通温利而效。", ["沉", "结"]], "3547": ["病机", "震按总括三案：次案脉沉小而急，与沉微细软不同，断为寒实非寒虚，妙在天台乌药散逐寒积；三案脉又沉结不调，痛且胀，亦属积寒实证，但不进饮食元气亦虚，故灸法妙极。沉小急结皆主寒实内结、气血壅滞，非虚寒之微细软。", ["沉", "小", "急", "结"]], "3548": ["其他", "此段未载脉象，述震按及景岳全书吐法，以咽气作嗳提气、使气至下焦走肋下，痰涎随气而出，吐后淡粥养胃、凉水漱咽。全段论吐法之运用与保养，非凭脉断病，故脉象要素空缺，主旨属治法与调摄。", []], "3549": ["病机", "脉皆细弦而缓，按之似涩，细弦主痛、缓主湿滞、涩主血瘀，故断为血病，以疝痛有磊块起落如滚浪为据。初用小承气加桃仁下之，痛失；三日复作，脉轻取弦大、重取散涩，知有食积阻隔，探吐尽出而痛解。弦涩为瘀血之凭。", ["细", "弦", "缓", "涩"]], "3550": ["病机", "脉皆濡缓，濡缓无力为气虚之象。原文谓脉缓无力者气虚也，引经云膀胱者津液之府，气化则能出焉，气虚不足无能运化，故阴囊胀大、茎皮光肿如泡。渗湿行气不效，正因未补其气，遂以补中益气汤升阳补气而愈。", ["濡", "缓"]], "3551": ["病机", "震按总括前二条凭脉断病之正法：前案以弦涩断为瘀血，后案以濡缓断为气虚，应手取效，皆得力于指下。弦涩主瘀血内阻，濡缓主气虚不运，故前案变温散为寒下，后案去归、柴加苓、膝，各中其机。", ["弦", "涩", "濡", "缓"]], "3552": ["病机", "六脉滑数，滑主湿痰食积，数主热，合为湿热内蕴之象。患者夙有脾泄便血脚痛，乃湿热下注伤及脾络。初用酒煮黄连为君佐参术，清湿热兼健脾而泄血止，属热中。越年余患狐疝，昼出夜入，不时疼痛，乃久病湿热伤及肝肾，从虚寒治而愈。此始热中久寒中，药物寒热迥别俱效，示久病从虚治之理。", ["滑", "数"]], "3553": ["病机", "本段未识脉名，以症测机。六月受寒，次年二月小腹与腰急痛，紧挽外肾稍松欲死，合《经》云小肠病者腰脊控睪而痛，乃寒邪郁火入太阳小肠之府。用羌活入太阳佐黄柏茯苓肉桂，并刮委中，痛止而足软，因太阳未尽。至五月天热身发紫斑汗至足而健，乃寒邪郁火得夏时火力血脉通而邪去，示伏邪因时透解之机。", []], "3554": ["病机", "脉皆浮濡而缓，浮为气虚外浮，濡为气弱不敛，缓为气虚不运，合为气虚之候。形肥色紫，气从脐下逆冲，睡卧不安，饮食少，精神倦，汪公据形与脉断为气虚，非丹溪阴火之说。肥人气虚，脉缓亦气虚，故以参耆为君，白术白芍为臣，归身熟地为佐，少佐黄柏甘陈，补气为主兼调升降，服之而安。", ["浮", "濡", "缓"]], "3555": ["病机", "震按此条仍合丹溪二说同用，非专主气虚。汪公于濡缓脉多以参耆加麦冬黄柏，不加附子，乃其一生得手处。陈皮加作七分气即冲上，尤见气虚之显然，前方可操券取效。震忆生平治气冲证，用熟地归杞牛膝紫石英胡桃肉坎气青铅等而愈者不计其数，又有用肾气丸、大补阴丸、三才丸而愈者，总不出丹溪之训，示濡缓脉主气虚而气冲有虚实之辨。", ["濡", "缓"]], "3556": ["病机", "两脉虚涩，虚为正气不足，涩为血少气滞；右尺独见弦急，弦急为下焦浊气上逆之象。小腹厥气上冲即吐，得饮则吐愈甚，诸药不效，乃下焦浊气上胜，胸中阳气不布，饮入于胃上壅而不下达。宜通其地道，用调胃承气汤下宿秽甚多，继培中气而愈。此虚涩中见弦急，示本虚标实、浊气上逆之机。", ["虚", "涩", "弦", "急"]], "3557": ["病机", "本段未识脉名，震按凡病皆有虚实，勿谓气冲证皆系阴虚气虚，故选此条别开一例。然必是暴病或便秘，乃从右尺脉印其机耳。昔与杜良一先生治下焦肾虚上焦气冲者，用六味地黄汤合五磨饮子去木香，以汁和服而效，又一新翻式样。示气冲证有虚有实，当参右尺脉及暴病便秘之症以别之，不可一概而论。", []], "3558": ["病机", "左尺和平，右尺如控弦如贯索，上冲甚锐，喻曰枝叶未有害本实已先拨，必得之醉而使内。夫人生之阴阳相抱而不脱，阳欲上脱阴下吸之则不脱，阴欲下脱阳上吸之则不脱。惟大醉后大犯房劳，五脏翻覆，百脉动摇，二气乘之脱离。今真阳不能潜藏常欲飞腾泄越，故闭目转盼则身非己有恍若离魂。治以涩固脱、重镇怯、补理虚，佐介类沉潜。", ["动", "摇"]], "3559": ["病机", "六脉皆促，或七八至一歇，或三四至一歇，促为阳盛热结兼歇止，示壮火烁阴而兼肝风上扰之兆。年逾古稀头目眩晕，服补中益气加参至三钱，遂痞满不食，坐不得卧，喃喃不休，面赤进退不常，左颊聂聂𥆧动，皆壮火肝风之症。与生料六味去茱萸易钩藤，大剂煎服酣寝，后加鳖甲龙齿枣仁，怒火则秋石汤送灵砂丹，盛夏小剂生脉散代茶。", ["促", "散", "代"]], "3560": ["病机", "脉滑大有力为实痰实火之征，滑主痰，大主火盛，故壮盛人眩晕属实证，治以二陈、芩、栀清火化痰；脉濡大或细软为气虚痰湿，濡软主气虚，大而无力为痰湿内停，肥白人眩晕属虚证，治以六君加耆、附补气化痰。", ["滑", "大", "濡", "细"]], "3561": ["病机", "脉浮数按之无力，浮为虚阳外越，数为热，无力为虚，正合“脏中积冷营中热”之旨，乃脾胃虚寒、营中郁热之证，故见发热消瘦、盗汗、便溏、不思食，治以灸中脘、气海、三里温补脾胃，甘寒泻热，甘温养中。", ["浮", "数"]], "3562": ["病机", "左脉散大而缓，右脉缓大不及左，重按皆无力，散大主气虚外散，缓大无力为脾胃大虚，故头目昏眩而重、手足无力、吐痰相续，乃大虚证，非风药所宜，治以大补气血，参、耆、归、芍、白术等浓煎，下连柏丸。", ["散", "大", "缓"]], "3563": ["病机", "脉缓大重按无力，缓大为气虚，无力为虚，故用参、耆、术补气；连柏丸之用，或因微渴、大便四日一行，或疑缓大为热，然实为虚中夹热之辨，非单纯热证，故震按提出质疑，示人脉证合参。", ["缓", "大"]], "3564": ["病机", "脉四至，浮大而虚，浮大主虚阳外浮，虚为气血耗散，此因多服燥热药致气散血耗，内有湿痰，故见恶风怕地气、动止呼吸言语皆不能，当夏令本虚，赖胃气尚存，治以参、耆、术熬膏补气，五味子收散，竹沥化痰。", ["浮", "大", "虚"]], "3565": ["病机", "脉浮大而虚，恰合虚寒之象，浮大无力为气散血耗，因多服燥热药所致，故热天畏风怕地气、动止呼吸言语皆不能，丹溪断为湿痰，用参、耆、术煎膏补气，淡五味子汤收散濡血，竹沥消痰，药证相符。", ["浮", "大", "虚"]], "3566": ["病机", "脉大力薄，大而无力为虚，然兼气郁，因抑郁致病，误用补药反加气急，吴球问而知之，断为气郁，用四七汤宽快而愈，示人同脉异经，须问诊合参，不可概行补药。", ["大"]], "3567": ["病机", "脉大力薄仍属虚脉，大而无力为虚，然病加剧由于郁，用补转增，当寻别因，震按强调须问而知之，不可仅凭脉断，虚中夹郁，脉证合参方得其实。", ["大"]], "3568": ["病机", "六脉皆洪缓，重按若牢，右手为甚。洪缓主湿郁，牢脉示湿邪深着。患者房事后渡河湿衣，湿邪外侵，郁阻气机，故憎寒壮热、肢节烦疼；湿困脾胃则满闷不食。虞氏作湿郁治，用平胃散加苍术等，药后发红丹、大汗而愈，正合湿郁外透之机。", ["洪", "缓", "牢"]], "3569": ["病机", "震按指出，患者虽房事后病，但脉仍非虚损脉，故前医作虚损治不效。脉不虚损，说明病机非虚，乃湿郁为患。湿郁阻遏气机，虽病延半年，脉象未现虚损，反证湿郁之实。以湿郁治即愈，强调病因辨证不可忽视。", []], "3570": ["病机", "左脉浮虚而缓，右脉浮弦而缓。浮虚缓为阳虚气弱，浮弦缓为脾胃阳虚兼气机不畅。患者伤寒过汗亡阳，足冷身寒，能食易饥而消瘦，梦遗筋骨疼痛，皆阳虚不能温煦、脾胃气弱之象。汪氏断为阳虚，非阴虚火动，故滋阴降火罔效。", ["浮", "虚", "缓", "弦"]], "3571": ["病机", "六脉弦数。弦主肝旺，数主热。患者酒豪，醉后呕血，咳不止，潮热咳嗽咽哑，烦躁喘满，肌食递减，乃酒热伤肺、肝火犯肺，灼伤肺阴，故脉弦数。江氏用四物加贝母、丹皮、麦冬等养阴清肺，佐白术、茯苓、人参健脾，渐愈。", ["弦", "数"]], "3572": ["病机", "脉大而数，按之极软。大数似热，然按之极软，乃中气大寒、虚阳外浮之象。患者虚损梦遗盗汗，羸顿已极，前服知柏芩连二冬等苦寒，更伤中阳。李氏断为中气大寒，以归脾汤加肉桂、人参温补中气，阳复则汗止精藏。", ["大", "数", "软"]], "3573": ["预后", "震按脉大而数、按之极软，宜温补，得数脉退则愈，不退则仍不愈。若细而数、按之极软，则死期已近，温补无益。大数极软为虚阳外浮，尚可温补；细数极软为真阴耗竭、虚阳无根，故预后不良。此以脉象辨温补之宜忌与生死。", ["大", "数", "软", "细"]], "3574": ["病机", "六脉不数，惟左寸涩而细，右关大而软。左寸涩细为思虑伤心、心血不足；右关大软为劳伤心脾、脾虚气弱。患者劳心太过，吐血有痰，喉间如鲠，日晡烦热，皆心脾两虚、虚火上炎之象。六脉不数，说明非实热，故以归脾汤补益心脾。", ["涩", "细", "大", "软"]], "3575": ["病机", "六脉数大，两颊俱赤，发热干咳，呼吸喘急。数主热，大主邪盛，两颊赤为热象。患者服苏子降气不应，服八味丸喘益急，说明非虚寒，乃肺肝蕴热，热邪壅肺，肺失清肃，故喘急。士材以逍遥散加丹皮、苡仁、兰叶清肝肺之热，热清则喘止。", ["数", "大"]], "3576": ["病机", "原文通过对比上条“脉之不数”与此条“脉之数大”，说明新病脉数大主实证，脉不数主虚证。数大之脉反映邪气盛实，正气未衰，故虽服温纳不应，仍可从脉象辨其病因。此段强调脉象在虚实辨证中的关键作用，数大主实，不数主虚，二者易辨。", ["数", "大"]], "3577": ["预后", "原文述吐血痰嗽，两尺如烂绵、两寸大而数，肺脉当浮涩反洪大，为贼脉见，秋令可忧。后洪变细数、软变疾劲，尺寸反者死。脉象由洪大转为细数疾劲，反映火盛灼金、肾阴耗竭，肺金将绝，故预后凶险，死期可卜。", ["大", "数", "洪", "细"]], "3578": ["预后", "患者发热咳嗽、吐鲜血、大肉消陷、大便溏泄、沉困著床，脉来七至。脉数七至为虚阳外越、气血衰败之象，法在不救。然李用参附桂术等温补，日投三帖，竟得渐愈，说明脉数七至虽主危候，若辨证准确、峻补脾肾，尚可挽回十中之一。", ["数"]], "3579": ["病机", "左寸短弱、右关略弦、余皆洪大。左寸短弱主心神不足，右关弦主谋为不遂，洪大主火。原文断为心病非肾病，因两颧不赤、声音不哑、耳轮不焦，肾水未涸。脉洪大不细数，说明火未炽盛，故许可治，强调色声脉合参以辨病位。", ["短", "弦", "洪", "大"]], "3580": ["病机", "震按此条辨证甚佳，所谓是心病非肾病者，亦缘脉洪大不细数耳。洪大脉主火盛，细数主阴虚火旺。脉洪大而不细数，说明火虽盛而未伤阴，病在心而不在肾，故与上条左寸短弱、右关略弦相应，强调脉象细数与否是辨病位的关键。", ["洪", "大", "细", "数"]], "3581": ["病机", "六脉俱数，肝脉甚弦。数主热，弦主木旺。原文谓气虚血热，肝脉甚弦则木气太旺，脾土受亏，不能统血；又为寒凉所伤，致饮食恶心、肌肉瘦削。弦脉反映肝木乘脾，数脉示血热，故咳嗽声哑、左胁胀疼，病势危矣，喜在青年犹可措手。", ["数", "弦"]], "3582": ["病机", "吐血发热喘，服生脉散热更甚，脉或大或小、或紧或数、或浮或涩，改变不常。原文断为脾阴虚而脉失信，脉者血之府，脾统血，血枯故脉改变不常。脉象无常反映脾阴亏虚、血枯失养，故用保元汤重用人参补脾，二帖效，二十帖愈。", ["大", "小", "紧", "数"]], "3583": ["病机", "震按脾阴虚而脉失信，为脉之不常寻一别解。吐血发热喘，服生脉散热更甚，脉散。散脉主气血耗散、脏腑虚衰。脾血枯则脉失统，故改变不常。慎斋不用补血而重用人参，补脾以生血，非识力兼到者不能，与张饮光服八味而喘益急病情相类。", ["散"]], "3584": ["病机", "六脉俱九至为脉数，原文谓“真气已虚而脉数也”，引经“数则元气虚”“数则脾气虚”，明言数脉主虚而非实热。独脾肾二脉洪大，是“金虚不能生肾水”，虚阳浮越之象。故病机为肺金虚不能生水制火，脾土失养，属不足之证，与咳嗽面赤、懒言怕闹相应，治当补肺生水以平木扶土。", ["数", "洪", "大"]], "3585": ["病机", "脉细带数，细为阴血不足，数为热，然叶氏不从阴虚论治，反用芦根、滑石、杏仁、通草等清渗之品，可知此数非虚火，乃暑湿郁于气分、热伤血络所致。症见夏月咳嗽带血、寒热、牙宣龈肿，皆湿热熏蒸之候；脉细为湿阻气机、血络受伤，非纯虚之细。故主暑湿内郁、络伤血溢之病机。", ["细", "数"]], "3586": ["病机", "脉散为精气耗散之象。原文谓“精血内夺为虚，虚不能自复为损”，病始于饮酒劳心，营气先伤，心阳下溜，肾阴不主涵蓄，络伤血溢，“阳气动极无制”，譬诸飓风波涛。散脉正应阳气浮越无制、阴不内守之机，与梦遗、泄泻、痎疟、络伤血溢诸症相应，故主虚损精夺、阳动无制之病机。", ["散"]], "3587": ["病机", "本段未识脉名，全凭症推病机。经闭年余而汗出如蒸笼气水，原文谓“经血内闭，止有从皮毛间透出一路，以汗亦血也”，说明血瘀内闭、郁热蒸腾，逼津外泄为汗。前医误认汗多为虚，投参术转剧，反证非虚。故病机为瘀热内闭冲脉、血不循经而外蒸为汗，与发热食少、肌削多汗相应，治以极苦敛血下行。", []], "3588": ["病机", "震按提出“设脉象细数无力，兼见便溏食减，此方其可用乎”，以脉之数、大、有力与否辨苦寒可否。细数无力为真阴亏损、虚火内扰之脉，若兼便溏食减则脾阳亦败，苦寒必伤中。故本条借假设之脉说明损怯证以真阴亏损居多，细数无力主阴虚火旺而中气不足，与食减便溏相应，警示苦寒之禁。", ["细", "数"]], "3589": ["病机", "脉弦数为震按辨传尸痨之论。原文谓一家递以痨病死者“由其人禀赋虚弱，气血衰损而致，并非痨虫为害”，弦为气血郁滞、脏气不和，数为虚热内扰，合而示禀赋虚弱、气血衰损之机。故主虚损痨怯而非虫祟，与父子兄弟相继病死者相应，斥五凤丸、雷公丸等附会之说不可深泥。", ["弦", "数"]], "3590": ["病机", "左脉弦为肝木偏旺、气郁风动，右脉滑为痰浊内壅，两寸稍短示上焦气机不畅。原文载夜梦魇惊、晕厥、精神恍惚、咳嗽面青、不思谷食，前医认寒痰投附桂而厥加，说明非寒痰乃痰火风动。弦滑相合主肝风挟痰、上扰神明，与惊厥恍惚、面色青、食少相应，故断为传尸瘵证之痰风内扰。", ["弦", "滑", "短"]], "3591": ["病机", "脉细神呆，气夺色夭，而食饮如常，说明病不在脾胃谷气，而在神气受夺。原文名之“殗殜”，谓受室晦之邪而未近女，邪中神明而未伤精室。细脉主营血不足、神气内馁，故主神气被夺、血脉不充之病机，与神呆、气夺、色夭相应，治以牛黄丸清透邪浊而安。", ["细"]], "3592": ["其他", "原文直言“此不载脉”，故无从取脉辨证。震按质疑痰裹米团在腹当有痞块、痛胀攻冲等症，而原文并未言及，因而“何所凭据而云然”。此段主旨在于批评缺脉之案难以凭信，强调脉诊在辨证中的必要性，非论具体病机。", []], "3593": ["病机", "脉弦而似缓，弦为气机郁滞、痰饮内结，似缓非真缓，乃痰热壅阻、脉道不利之象。壮年恶寒多服附子，热郁于内，燥热伤血，故以吐痰泄热、通圣散加减取效。原文“燥热已多，血伤亦深”，终致附毒发疽，说明脉弦似缓主痰热内郁、血伤火炽之病机。", ["弦", "缓"]], "3594": ["病机", "脉沉而涩，重取似数，沉主里，涩主血滞，似数乃郁热内伏。形瘦面黑、喜热恶寒，热郁于里而阳气不达，故外现寒象。三黄丸下以姜汤，借辛温为导，微汗而安，说明此脉主里热郁滞、血行不畅之病机，非真寒证。", ["沉", "涩", "数"]], "3595": ["病机", "脉沉涩，重取稍大，沉涩为血虚热郁，稍大示热甚。老妇形肥多汗、恶寒战栗而喜啖热，乃热深厥深、血虚不荣之象。初药大泄、目无视、口无言，为药无反佐；炒热煎服则利止，说明脉沉涩主热甚血虚，治当凉血补血兼以反佐。", ["沉", "涩", "大", "弱"]], "3596": ["病机", "脉微欲绝，为阳气衰微、汗多亡阳之候。病发热误服小柴胡升发太过，致多汗亡阳，恶寒甚，筋惕肉𥆧，正是阳虚不能温煦、筋脉失养。真武汤温阳利水，服附子八枚而痊，说明此脉主亡阳重证，与少阴阳虚水泛病机相应。", ["微"]], "3597": ["病机", "脉数而大且不弱，数主热，大主邪盛，不弱说明非虚寒。长夏畏寒、食饮必热而微温即呕，乃火极似水、热郁于内格阴于外之假寒。椒、硫、鸡助火生痰，病愈亟；大承气下之、黄连导痰汤清之而瘳，说明脉数大主实热内郁之病机。", ["数", "大"]], "3598": ["病机", "脉七八至，按之则散，数而散为无根之火、虚阳外越之象。东垣治目赤烦渴引饮而用姜、附、人参取愈，正属假寒假热。震按以此与诸案互参，说明辨恶寒非寒须凭脉之微弱与否；脉散主虚阳浮越，与实热脉数大不弱者迥别。", ["散"]], "3599": ["预后", "脉浮数而短涩，两寸极小。浮数似热，短涩为血少气衰，两寸极小示心肺不足。劳役忧思、盗汗燥热而脉反短涩，是阳浮于外、阴伤于内，故罗谦甫断为危证，谓至春必死。原文“令不固其阳，时不胜其热”，说明此脉主阴阳离决、预后不良。", ["浮", "数", "短", "涩"]], "3600": ["死脉", "脉沉细而疾，沉细为阴亏，疾为虚阳外越。原文谓“孤阳绝阴，必死之证”，消渴躁热而脉反沉细疾，是阴液枯竭、阳气无附，故主死候。", ["沉", "细", "疾"]], "3601": ["病机", "脉洪而无伦，洪为阳盛，无伦为虚阳外浮。原文谓“肾阴虚阳无所附而发于外，非火也”，故虽大热而脉洪无伦，主肾阴虚、虚阳上浮之假热证。", ["洪"]], "3602": ["其他", "本段为震按评述，未出脉象。讨论前案阴虚用肉桂之疑，及与伤寒证候鉴别，属医案评议，故脉象要素为空。", []], "3603": ["病机", "脉洪大鼓指、按之如无，为内真寒外假热之象；服温补后脉顿微细如丝，是真寒显露。原文谓“此内真寒而外假热也”，脉由洪大转微细，正合虚寒本质。", ["洪", "大", "微", "细"]], "3604": ["病机", "脉洪大鼓指、按之如无，主内虚寒而外假热；又洪大无伦、按之有力，则属真实火象。原文强调“证同脉异，更宜细参”，示脉之有力无力为辨假热真火之关键。", ["洪", "大"]], "3605": ["病机", "六脉微洪，微为气分热势未盛，洪为肺热鼓动。原文述骨蒸发热、肤如火燎、吐痰烦渴，李时珍以一味黄芩泻肺经气分火而愈，故脉微洪主肺经气分热。", ["洪", "微"]], "3606": ["病机", "脉微无力、右尺伏而不起、尺脉沉伏，原文断为“肾虚也”，又谓“肾火之浮游”。尺脉沉伏主肾虚，火不归原而浮游，故见上下循环发热、足底热甚。", ["微", "伏", "沉"]], "3607": ["其他", "本段为震按评述，未出具体脉象。评前案“肾虚火不归原”之治，谓“与脉似乎未合”，属医案评议，故脉象要素为空。", []], "3608": ["病机", "左弦大、右滑大搏指，弦为肝火，大为火盛，滑为痰凝。原文断为「肝胆之火为痰所凝」，因过思不决、木火不得通达，郁而致右胁胀痛、咳嗽吊疼、夜热更甚，乃肝邪实也。误作疟治燥动其火，补以参术闭塞其气，故舌胎如沉香色而热极，脉象正示痰火郁实之机。", ["弦", "大", "滑"]], "3609": ["病机", "脉涩主血行不畅。患者嗽而咯血、发热肌瘦，医误补数年，又因好色多怒、精神耗少，补塞药多致「荣卫不行，瘀血内积，肺气壅遏，不能下降」，故脉见涩。涩为瘀血内阻、营卫不通之象，非单纯虚损，故治以倒仓法吐泻兼施，兼灸肺俞以通壅。", ["涩"]], "3610": ["病机", "脉洪而滑，洪为热盛，滑主痰与血壅。患者盛暑出行、大醉饱后吐血胸痛体热，原文断为「胃血壅遏，为暑迫血上行」，洪滑正合胃中热壅、血随暑迫之机。故先以犀角地黄汤凉血，继以桃仁承气去瘀血宿积，后治暑而安，脉象与治法相印。", ["洪", "滑"]], "3611": ["病机", "脉弦急，弦主肝、急主气逆。患者素无恙而骤吐血半缶，得之大怒，原文断为「薄厥」，谓「气逆，阴阳奔并」。大怒则肝气上逆，血随气奔，故脉弦急而暴吐。弦急正是肝气逆乱、阴阳相并之征，故饮六郁汤以疏解郁逆而愈。", ["弦", "急"]], "3612": ["病机", "右脉大无伦、时复促而中止，左略小而软亦中止。大为虚阳外浮，促结为气血不续，软为不足。原文断为脾肺肾三经之病：燥热伤肺、劳倦伤脾、女色伤肾，母病子失养、子伤盗母气，肺愈虚。脉之大小促结无常，正示三经虚损、气血不相接续之机。", ["大", "促", "结", "软"]], "3613": ["病机", "两手寸关浮软，两尺独洪而滑。浮软为气分不足，尺部洪滑为下焦火旺。患者形瘦咳嗽咯血、吐黑痰，误服参术而病甚，原文断为「肾虚火旺而然」。尺脉洪滑正是肾中相火偏旺、灼肺动血之象，故以四物加知柏滋肾泻火，待尺脉稍平而肾热减。", ["浮", "软", "洪", "滑"]], "3614": ["其他", "此段为震按评语，非诊脉原文，故不取脉象要素。其要在申明四物加知柏合两尺洪滑、白术麦冬合寸关浮软之配伍妙处，并指出前用参术病甚而后尺脉稍平仍加人参，非高明不敢复蹈前辙，收功于枳术丸加参栀及地黄丸加柏，属对前案治法之评议。", []], "3615": ["病机", "左脉沉弱而缓，右脉浮软无力，续诊心肺脉浮虚按不应指，脾脉轻按阁指重按不足，且变动无常。原文谓「脉不常，血气虚也」，譬之虚伪之人朝更夕改。沉弱缓为气虚不足，浮虚为气不内守，诸脉无常正示血气俱虚、中气不固，故以脉参证其虚无疑。", ["沉", "弱", "缓", "浮"]], "3616": ["病机", "上条脉软无力、变动不常，为气虚阳弱之象；此条脉浮细弦数，浮细为阴血不足，弦数为肝火内郁，故汪氏判为肾虚肝旺、虚火内扰，非气虚可比。若仍以参、芪补气，则助火灼阴，故曰“不以滋肾清肝，治更难及”，点明脉象已由气虚转为阴虚火旺之机。", ["软", "浮", "细", "弦"]], "3617": ["主病", "脉细濡而滑，细濡为肺津亏耗、阴血不足，滑为痰热内蕴。久嗽咯脓血、日轻夜重，正合肺痿津枯、虚火挟痰之候。前医误用参、夏，一助伏火，一燥津液，故病益加。汪氏以脉断为肺痿，径用天麦冬、阿胶、贝母润肺化痰，五剂而安，脉象与病机丝丝相扣。", ["细", "濡", "滑"]], "3618": ["预后", "此段震按前案用滋阴凉药后“竟得脉缓不数”，缓为胃气渐和、热退阴复之象，不数为火平之征，故视为转机。然震氏又叹“此种药效者殊少”，暗示血证阴虚火旺者，脉缓不数虽属佳兆，实为侥幸，非可恃为常法。脉象由数转缓，反映邪热渐退而胃气未败，故列于预后。", ["缓"]], "3619": ["病机", "初诊脉濡细而近快，濡细为阴血亏虚，快即数，为虚火内动，合形色苍白、咳血声哑、夜热自汗，断为色欲伤阴、虚火上炎。药后脉转缓弱，快象已去，知阴虚火退，而缓弱为脾胃气虚之征，故改用甘温养脾。同一病而脉由濡细近快转为缓弱，揭示病机由阴虚火旺转为脾胃虚弱。", ["濡", "细", "缓", "弱"]], "3620": ["病机", "左脉近大而快、右略敛少带弦而快，大为邪盛，弦为肝旺，快即数，为火动。嗽血而便溏，乃肝火犯肺、脾虚不摄并见。用人参、白术、紫菀等培土生金，佐白芍、丹皮柔肝凉血，脉弦快稍减，加黄芪、百部而嗽止血少。脉由弦快渐减，说明肝火渐平、脾气渐复，病机重在肝脾失调、火灼血溢。", ["大", "弦", "快"]], "3621": ["病机", "孙氏诊得两关洪滑有力，洪滑为实热痰瘀壅盛之象，与阴虚“脉数无力”迥异。怒伤肝、犬肉伤脾，肝脾二经有余，瘀血滞于胸背，故胀痛而上下出血。前医误作阴虚，用滋阴降火，愈滞其瘀。孙氏以脉之洪滑有力断为实瘀，调气消导、化瘀清热，正合“脉既不同”之辨。", ["洪", "滑", "数", "虚"]], "3622": ["病机", "左脉弦大，右脉虚大，两关洪滑有力。弦大为肝火亢盛，虚大为暑热伤气，洪滑为痰火壅盛。作文劳心、暴怒伤肝、暑热外逼，木火上升，故大吐痰沫、呕血眩晕。孙氏引“脉虚身热，得之伤暑”，又谓“诸风掉眩，皆属于肝”，以脉证合参，断为木火挟暑上逆，非单纯阴虚血热。", ["大", "弦", "虚", "洪"]], "3623": ["预后", "原文未出脉名，然“夏得秋脉”即夏季见秋令之脉，属非时之脉。夏当见洪，反见秋脉之毛，为金气早至、火令不及，脏气逆时，故李士材断为“当其时不能再见”，果如期而殁。此段以时令与脉象相违为据，说明脉逆四时者预后不良，虽未明写脉形，实属死脉之论。", []], "3624": ["病机", "脉紧数见于大下后，紧主寒主痛，数主热，此紧数并见，非实热，乃虚阳外越、阴寒内盛之象。原文“脉益紧数”伴“困惫垂危”，说明攻下后阳气更伤，阴寒愈甚，故景岳以人参、熟地、干姜、甘草温补，从脉象认病根，非热证可知。", ["紧", "数"]], "3625": ["病机", "左弦大右虚大，弦为肝旺，大为虚阳，虚为不足，尺中甚乱乃肾气不固。原文“少阴之脉系舌本”“肾家之血汹涌而出”，脉乱主房劳伤肾、元气欲脱，故喻嘉言用丸药镇安元气，从尺脉乱识肾虚失血之危。", ["弦", "大", "虚", "乱"]], "3626": ["病机", "原文“脉不洪盛”为纯描述，未列具体脉象。体肥嗜酒、失血而脉不洪盛，说明非实火，乃酒湿伤胃、气动血动。上气喘促、喉间窒塞、胸前紧逼，皆气逆血瘀之候，故人参阿胶不效，三七酒研血止咳定，示病机在胃气上逆、血不归经。", []], "3627": ["病机", "六脉短数，短主气损，数主虚热。原文“酒是邪阳，色亦邪阳，邪阳胜则正阳衰”，又兼怒气伤肝、思虑伤脾，中气大虚，血不归络，积血中焦。短数脉示正虚邪滞，故先以六君子汤升发阳气，使阴寒消而积血行。", ["短", "数"]], "3628": ["病机", "脉弦大而虚，弦为肝急，大为劳伤，虚为血脱。原文“失血势如泉涌”“自汗喘乏”，脉虚主气随血耗，弦大乃肝阳不敛。与当归补血汤补气生血，后下紫黑血块，知兼瘀阻，故弦大而虚非纯虚，乃虚中夹瘀之候。", ["弦", "大", "虚"]], "3629": ["病机", "脉弦大而虚，又见脉散，散主气散不收。原文“自汗喘乏”“夜间烦扰不宁”，虚弦大示血脱气浮，散脉则元气欲散。震按“不混投地黄汤、生脉散”，用补血汤者，以夜间烦扰属阳浮，故补气以摄血，消瘀以除胁痛。", ["弦", "大", "虚", "散"]], "3630": ["病机", "脉数而涩，数主虚热，涩主血少。原文“半产咳嗽吐血”“胃满脾泄”，数涩示失血后阴亏而脾阳亦弱，故理气降火益甚。投理中汤倍参术而血止，说明脉数非实火，乃中虚不摄、血不归经，涩为血涩，数因虚阳。", ["数", "涩"]], "3631": ["病机", "脉散主气散血脱，原文引“血来汹涌，必须止之”，散脉示血脱气散之危。震按止血贵辨虚实寒热，散脉见则不可任其吐，当急止以固气，否则气随血脱。此段以脉散明脱血之机，非行血所宜。", ["散"]], "3632": ["病机", "脉躁疾为阳热亢盛、火迫血溢之象。患者体肥气盛，多服暖宫药积久火盛，迫血上行而衄，面赤、神恍如痴，皆火盛上冲之候。躁疾之脉反映血气俱盛，溢而上行，故当用下导之法，桃仁承气汤下瘀热而愈。", ["躁", "疾"]], "3633": ["病机", "六脉微弱，寸为甚，为心虚不能司血之象。衄血三年，过服泻心凉血之剂益困，衄仅数滴辄昏，乃心脾两虚，血失所主而妄行。寸口脉微知心虚，故法当养心补脾，实其子使心不虚，用琥珀诸补心药而安。", ["微", "弱"]], "3634": ["误治", "此段未识脉名，述衄血屡用寒苦攻伐致害。患者膏粱嗜饮，医见血即投清凉、黄连解毒，虽暂止复作，渐至肌寒时躁、言语无声、口气臭秽、恶吸冷风。苦寒泻土，脾胃本伤，火未除而土已病，故曰下工不可不慎，以平为期。", []], "3635": ["病机", "脉大如指，非热乃肺气虚也。形魁伟色黑善饮，衄如注喘嗽不能伏枕，医投寒凉愈甚。脉诀虽云鼻衄沉细宜、浮大倾危，然此脉大非热，乃金极似火，肺气虚极而现假热之象。补肺气则火自退，用人参、黄芪等甘温而愈。", ["大"]], "3636": ["其他", "此段为震按总结四案，未出具体脉象。首条实热脉躁疾，次条心脾两虚脉微弱，三条因热过用苦寒，四条脉形似热而实由气虚脉大如指。四案脉症不同如此，示临证须细辨虚实寒热，不可见血即谓热而妄攻。", []], "3637": ["预后", "脉濡而滑，按皆无力，为水不制火、肺金枯涸之候。鼻衄久流涕不休、鼻秽难近，渐至目昏耳重、食少体倦，乃肺热津泄，燥者枯矣，头面诸阳之液走泄。脉无力而濡滑，正气已衰，故断病不起，月余果作痈疮而卒。", ["濡", "滑"]], "3638": ["预后", "脉濡滑而无力，滑脉类数，仲景云数脉不时则生恶疮。流涕鼻秽即鼻渊，参芪罔效，无路可寻。流涕不休定然枯涩，营气不从逆于肉里，为病之指归。脉无力而濡滑，正虚邪恋，故断必死，虽用滋水生肝养肺亦难效。", ["濡", "滑", "数"]], "3639": ["病机", "脉弦急如循刀刃，为阴火上乘、载血于上之象。鼻衄如崩，服寒凉转盛，寒凉伤胃中清阳，故脉变弦紧。弦急如刃示阴火亢盛，非实热可攻，与六味加五味子、肉桂末引火归元，血顿止而愈。", ["弦", "急", "紧"]], "3640": ["病机", "脉小而衰，小为气血不足，衰为阳气式微，故衄血虽似热证，实由气虚不能摄血、阳衰不能固阴所致。沈宗常据脉断非实热，径投参附温补而愈，正合《内经》'形不足者温之以气'之旨。若执见血为热而用寒凉，则阳气愈伤，血愈不止。", ["小", "虚"]], "3641": ["病机", "脉弦细而微迟，弦为阴结，细为血少，迟微为阳气内衰。罗氏引《内经》'结阴者便血'，谓阴气内结不得外行，渗于肠间而便血。手足稍冷、恶冷物、食则呕酸，皆阴寒内盛之征，故非芍药柏皮丸寒凉所宜，当以升阳温通为治。", ["弦", "细", "迟", "微"]], "3642": ["其他", "此段为震按语，评罗谦甫治史侯男案，谓其证因易辨、脉又可凭，妙在制方升温通补、分量轻重合宜，属东垣高弟手笔。原文未出具体脉象，纯为医案评述，故脉象要素从缺，主旨归于对前人治法方药的品评。", []], "3643": ["病机", "左脉浮大虚甚，浮大为气虚阳浮，虚甚为血亏；久取滞涩不匀，右沉涩细弱、寸沉欲绝，乃气郁生涎、涎郁胸中，心气不升，经脉壅遏，心血不能自养。故下血十余年，食减形困、心摇如烟熏，皆由气郁痰阻、升降失司所致，非开涎行气则血不归隧道。", ["浮", "大", "虚", "涩"]], "3644": ["其他", "此段为震按语，评丹溪治老妇便血案，谓其脉证似虚似实、非寒非热，较罗案难辨，而讲病源与用药轻重去取俱有精义，十年之病半月而愈。原文未载具体脉名，属医案评述，故脉象从缺，主旨归于对前人辨证用药的品评。", []], "3645": ["病机", "惟脾部浮而缓，浮为风湿外乘，缓为土气本虚，合之则土虚而风湿交乘。脾虚不能统血，风湿扰于肠间，故肠风屡发不止、面色颇黄。久用四物芩连槐花寒凉，愈伤脾土，故以苍术、茯苓、参耆升柴防风健脾升阳祛风，血止而愈。", ["浮", "缓"]], "3646": ["病机", "两寸皆数，数为热；两关弦而无力，弦为木郁、无力为胃气不足；两尺洪滑左尤甚，洪滑为湿热壅于下焦。合观乃胃寒肠热之证：大肠喜清恶热，故燥结便血；脾胃喜温恶寒，故关脉无力。治以肠风脏毒药为君，外裹养血之剂使不伤胃气。", ["数", "弦", "洪", "滑"]], "3647": ["病机", "左脉沉涩，沉为病在里，涩为血行不畅，主瘀血内停；右脉漏出关外，诊不应病，故初难凭脉断证。孙氏因便血久下而月汛如期，知经隧必有瘀血停蓄，先以升提兼补兼涩探其虚实，既得病情，乃用下法除根，体现凭脉参症、以脉探病之巧。", ["沉", "涩"]], "3648": ["病机", "右脉沉细为内伤寒凉太过、阳不鼓动，故血不归络；尺脉豁大乃火浮于中，虚阳外越。肠风下血日久，头晕倒地，皆因阳气不升、血失所摄。脉沉细主阳虚，豁大主虚火，二者并见，说明寒凉伤中、阳衰火浮之病机，非实热便血。", ["沉", "细", "豁", "大"]], "3649": ["病机", "脉弦劲带数，弦劲为肝郁化火、木气横逆，数为热象。患者积劳便血，腹胀不思食、易怒，显系肝郁脾虚、郁火内扰。前用温补得止，复因劳心触发，脉转弦劲数，说明肝火偏亢、脾土受克，故逍遥散不应，反见口干咳嗽等阴伤之象。", ["弦", "劲", "数"]], "3650": ["病机", "脉洪数有力为实热，洪数无力为虚热。溺血属热者多，因胞移热于膀胱。实热则脉洪数有力，宜导赤散加栀芩；虚热则洪数无力，宜生地归芍等。此段以脉之有力无力辨溺血虚实，说明热伤血络、迫血妄行之病机，久病则变虚寒。", ["洪", "数", "有", "力"]], "3651": ["病机", "尺脉沉大，慎斋断为脾气下陷。脾虚则肺失所养而自汗，脾阳不舒、肾气亦郁，故足冷不能行动。沉主里，大主虚阳不敛，非实热之象。此脉说明中气下陷、阳气郁于下焦，故以启脾养肺为本、温肾为标，稍加肉桂而愈。", ["沉", "大"]], "3652": ["病机", "震按自汗足冷显系下焦虚寒，尺脉当沉细，反见沉大，粗工凭症温补肝肾则误，缪工凭脉认湿热亦误。沉大非实热，乃脾气下陷、虚阳不敛之象。慎斋只稍加肉桂，正因尺脉沉大提示中气下陷而非纯肾阳虚，故与温补肝肾隔一层。", ["沉", "细", "大"]], "3653": ["其他", "此段述庄先生治喜乐之极而病者，切脉后佯称取药而不返，使病者悲泣，以惧胜喜而愈。原文未载具体脉象，只言切脉失声。主旨为情志相胜治法，非脉象主病，故脉象要素为空。", []], "3654": ["病机", "二寸脉微伏，寸部候心肺，微伏为气血郁滞、阳气不伸。僧法靖断为忧思致病，因梦吞蛇过忧成疾。忧思气结，心脉不畅，故寸脉微伏。此脉说明情志郁结、气机不展之病机，当治意而不治病，非真有蛇在腹。", ["微", "伏"]], "3655": ["病机", "两手脉俱缓，缓为脾脉，戴人断为脾受之，脾主思故也。伤思虑过甚，二年不寐，气机郁滞于脾，脉见缓象。以怒激之，汗出困眠，食进脉得其平，说明思虑伤脾、气结不运之病机，情志相胜则脉复和平。", ["缓"]], "3656": ["病机", "肝脉弦出寸口，为思虑气结之象。女子思男子不得，气结于脾，脾主思，过思则脾气结而不食，故困卧如痴。弦为肝脉，出寸口示肝气郁而乘脾，木克土，故治以怒激，令气升发冲开脾气，此脉象揭示情志致病的病机关键。", ["弦"]], "3657": ["其他", "原文未识脉名，仅言“脉稍充”，为补益后脉象渐复之象。僧因思母忧泣，黄瘦倦怠，气血亏耗，故脉不充；经牛肉猪肚甘肥补养半月，脉稍充，示正气渐复，方可与桃仁承气下其血块痰积。此段以脉之充否判断攻下时机，属治法中的凭脉施治。", []], "3658": ["病机", "六脉俱长，三部九候往来有力，寸尺特盛，为太过之脉。富商惊悸遗泄、湿烂脓下，似虚而脉反长盛，王中阳断为湿痰为患，非虚脱也。长而有力主邪气壅盛，痰湿郁而化热，上扰心神则惊悸，下注则湿烂，故以滚痰丸攻逐，此脉示实邪内蕴之病机。", ["长"]], "3659": ["病机", "此段为案语评述，未出具体脉象，然承前案“太过之脉”而论。洞虚子谓“水火亢行，心不摄血”，震改为“湿热生痰，上壅下注”，指出脉之太过由湿热痰浊壅盛所致，上壅则神不宁，下注则肌肤湿烂，与火炎水滥本同标异，阐明湿热痰浊为病机核心。", []], "3660": ["病机", "脉浮微弦而芤，左寸厥厥动摇。浮为虚阳上浮，弦主痰饮，芤为血虚，左寸动主心神不宁。产后虚羸，咳青黑结痰，惊悸麻木，乃胎前风热、坐草迸力，痰血随气上逆冲过膈膜流入心包。脉象揭示痰瘀上逆、虚阳浮越之病机，故用异功、独参、来复丹搜涤瘀积。", ["浮", "弦", "芤"]], "3661": ["病机", "气口数盛而促，人迎弦大而芤。数盛主痰热，促为痰气中结，非代脉之元气败绝；弦大而芤主惊怒伤肝、失血后阴血亏虚。患者神气愦乱、口噤目瞠、扯摘衣被，脉证合参，断为挟惊挟怒、痰气中结，故用钩藤、竹沥、姜汁清痰平肝，次日六脉稍平而促未退。", ["促", "数", "弦", "芤"]], "3662": ["病机", "三焦脉洪大侵上，脾肺二脉微沉。洪大为火，侵上示肺火亢盛；微沉为脾肺气虚。患者倦怠呵欠、经月不食、肌消骨露，诸医杂治不效，易思兰断为肺火病，火灼津气故倦怠不食。洪大侵上为火之源，微沉为气弱之标，故以栀子清肺火，人参、麦冬、乌梅益气生津。", ["洪", "沉", "微"]], "3663": ["病机", "六脉涩滞，为气机郁滞、浊气不降之象。胁痛吐臭痰、恶心食不下，因清气不升，浊气郁于少阳之络，故痛；浊气上逆，故吐臭痰恶心。涩滞主气滞血郁，少阳清阳不升则肝不能散精，食不下。治以柴胡、白蔻升清，山栀、丹皮降浊，茯苓、广皮化痰，归身、麦冬养血润燥。", ["涩"]], "3664": ["其他", "脉象“气口和平”“脉不应证”，即脉和而证危，脉象与症状不符。张景岳由此沉思，疑为诈病，复诊仍“安然如故”，故断为诈病。脉和说明气血未乱，与危重症状相悖，故非真病。", ["和平"]], "3665": ["其他", "脉伏“渺若脱”，似气厥危候，但患者“十指交叉于腹”“力强且劲”，脉伏因“肉厚气滞”或“两腋夹紧”所致，非真虚脱。脉伏主气机郁闭，与诈病相应，故以恐胜之而愈。", ["伏"]], "3666": ["病机", "脉沉细数弱，沉细为阴伤，数弱为虚热，口渐渴、手心热、喜暗处，皆阴虚内热之象；脉渐伏而妄语，为痰热蒙蔽心窍。此室女素强健而病痰热，脉沉细数弱主阴虚痰凝，故以妙香丸下痰而愈。", ["沉", "细", "数", "弱"]], "3667": ["病机", "尺脉浮大，按之则涩，浮大为肾虚阳浮，涩为痰饮内阻。症见气短有痰、小便赤涩、足跟痛，皆肾虚痰饮之候。脉浮大按涩，主肾虚不能化饮，故用四物送六味丸补肾逐痰而康。", ["浮", "大", "涩"]], "3668": ["病机", "尺脉浮大按之涩，与梁厚斋案同，主肾虚痰饮。震按强调此脉涩为肾阴不足，非独痰饮，故用六味丸专补肾阴；若加桂附则成肾气丸，补而逐之。脉浮大涩，示肾虚不固，与气短足跟痛相应。", ["浮", "大", "涩"]], "3669": ["预后", "脉沉而涩，两尺尤甚，沉涩为精血亏虚、痰瘀内阻。劳而醉使内，汗出多痰，尺涩甚为精伤之象，故断为不治。涩象不减、脉法无根，主根本已败，预后不良，果十余日而殁。", ["沉", "涩"]], "3670": ["病机", "震按比较两案涩脉：梁案尺浮大按涩，此案六部沉涩、两尺尤甚，且“脉法无根”，想是沉细涩按之欲绝。沉涩主精血枯竭，无根为胃气已败，故死生不同。涩脉轻重之别，反映精伤程度。", ["沉", "涩", "细"]], "3671": ["病机", "关以上溜而滑，按之沉而有力，滑主痰饮，沉有力主积滞内实。症见胸中痞满、头目昏痛、欲吐不吐、臂偏痹，皆痰饮横于胸膈所致。脉滑沉有力，说明痰涎宿饮上甚，故用探吐法夺之而愈。", ["滑", "沉"]], "3672": ["病机", "左寸涩、右寸滑且按之如黄豆大鼓指，关尺皆弦小，是积痰郁滞于肺、上焦气壅之象。滑主痰，涩主滞，弦小为郁结不畅。痰积肺中不能宣降，大肠之气因之不固而食后即便、腹皮胀急。左尺迢迢有神，示肾气未败，故可探吐去上焦痰积而大便自实。", ["涩", "滑", "弦", "小"]], "3673": ["病机", "原文未识脉名，然述遗精日久、肾窍漏气如烟雾、形瘁骨痿、大便艰涩色黑，屡用苦寒导之愈秘。此属久漏精血枯竭、肠腑失润之病机，非实热秘结。苦寒刮削脂膏反伤津液，故求润弥燥；胸膈痞闷、食停嗳气，乃虚滞上逆。文末言「因虚致滞」，正点出本段辨虚损夹滞之旨。", []], "3674": ["病机", "六脉大小不等，参以唇红脸黄、嘈杂难忍、得肉痛作吐酸稠涎，断为虫证。脉大小不匀，是虫扰气机、阴阳错杂之象，非祟非虚。虫动则嘈杂欲死，虫静则稍安，故需肉以救急。雄黄、腻粉、使君子下长蛲十余条而愈，正验脉象所主之虫积病机。", ["大", "小"]], "3675": ["预后", "呕吐痰涎、发热作渴、胸膈痞满，本属胃气虚寒、脾弱不运，误服清化降火而虚证悉至，见饮食不入、呃逆泄泻、手足逆冷之五虚。此时脉洪大非实热，乃虚阳外越、脉欲绝之候，故断死期迫矣。洪大见于五虚并现之际，为胃气将败之真脏外露，当殒于昼。", ["洪", "大"]], "3676": ["病机", "心腹冷痛、呕吐宿汁清涎不止、百药不纳，而六部弦细而长。弦主痛主饮，细为阳衰，长为气机郁滞不降。此痰饮痼结中焦、胃气上逆之病机，故滚痰丸下其痰积，呕逆即止，继以茯苓半夏、白术散调理而饮食如旧。脉弦细长正合痰饮冷痛之候。", ["弦", "细", "长"]], "3677": ["治法", "本段引千金方，论粥食汤药皆吐不停者灸手间使穴；若四肢厥、脉沉绝不至，灸之便通。脉沉绝为阳气闭阻、脉道不通之候，非气绝，故灸厥阴间使穴以通阳复脉。后附史载之「食挂」用清润肺药之说，江篁南斥为邪说妄托，本段主旨仍在灸法通脉之治。", ["沉", "绝"]], "3678": ["预后", "不能顿食而喜频食，忽咽膈壅塞、大便燥结，脉涩似真脏脉。然形瘦色紫黑、病见于冬，冬主闭藏，形色与令相得，故断有生意。涩主血少津枯、瘀滞不行，以四物加白术、桃仁养血润燥兼行瘀，多食诸血助药力，四十帖便润、百帖而安，示涩脉未必尽死。", ["涩"]], "3679": ["病机", "丹溪治噎膈反胃数条，跌仆、饮酒、劳欲所致者脉皆涩，涩主瘀血内阻、胃脘枯槁；又有脉涩不匀、重取大而无力，及脉缓而弱、浮洪弦虚者，皆瘀血夹虚之候。故以韭汁、牛乳、甘蔗汁、竹沥等润养行瘀而效。震按叹其病重药轻而奏捷，正见涩脉主瘀膈之病机。", ["涩", "缓", "弱", "浮"]], "3680": ["病机", "脉弦涩而缓，尺脉浮而无根。弦属肝木，涩为血少，缓为脾脉，尺浮无根主肾水亏乏。肝木凌脾，血液枯槁，故主噎膈。胸膈微碍即其症候，预后不良。", ["弦", "涩", "缓", "浮"]], "3681": ["病机", "震按强调尺脉浮而无根，主肾水亏乏，真元不固。若仅见弦涩而缓，易误认为有胃气，而忽略尺脉无根之危候，故特为拈出。", ["浮"]], "3682": ["病机", "脉紧且滑，紧主寒，滑主痰，痰湿壅盛于上脘，故食辄噎而膈中隐痛。用二陈加姜汁、竹沥，湿痰满中非此不治，后改大半夏汤而愈。", ["紧", "滑"]], "3683": ["病机", "六脉细软，为虚寒之候，中阳不足，故噎而吐食。用理中汤加人乳、姜汁等温中补虚，后以十全大补收功。另案脉按有力，为气闭血瘀，非死证，下燥屎干血而愈。", ["细", "软"]], "3684": ["病机", "震按此非噎膈，乃忧忿气闭血瘀，暂时关格。脉有力，病暴起，故易愈。前二案脉细软、弦涩，病久正虚，未必见效。", []], "3685": ["病机", "左右寸关俱沉大有力，两尺浮中沉俱紧，按之无力。寸脉当浮反沉，左寸神郁，右寸气郁，大者火也，火郁在上故胸膈饱闷、吐酸。尺紧为寒邪从虚而入，主腰腿酸疼。此气膈病也。", ["沉", "大", "紧", "浮"]], "3686": ["病机", "六脉俱无胃气，惟胃脉略缓，脾脉微缓。胸前微痛无休，乃丹田阳气不到胸中，膈气无疑。脾脉微缓，调理脾胃犹可迁延，用保元汤加山药、沉香。", ["缓", "微"]], "3687": ["病机", "六脉沉涩，按久则衰，举指即应，为痰瘀内结而正气渐衰。体肥痰逆者可治，枯癯津衰者多不可治。用六君子汤下狗宝，呕止食进，后以六味丸等调理而康。", ["沉", "涩"]], "3688": ["病机", "右关浮滑，余部无恙，右关属脾络胃，挟舌本。浮为风邪，滑为痰浊，风痰阻络，廉泉闭塞，故喑。醉卧当风，风邪乘虚入中，与痰相搏，独显右关，说明病位在脾胃，病机为风痰阻窍。", ["浮", "滑"]], "3689": ["病机", "脉虚、略数、缩急，示三脉虚而痰涎乘虚闭塞脉道。足少阴、太阴、手少阴别脉皆系舌本，三脉虚则舌失血养，痰涎阻络，故舌不能转运言语。脉虚为气血不足，数为痰热，缩急为脉道拘急，总属虚中夹痰。", ["虚", "数", "急"]], "3690": ["病机", "震按此案脉必濡滑无力，濡为气虚，滑为痰湿，数而无力为虚热。伤寒后神昏而喑，身热人静，欲言不能，脉不实，故断为体虚有痰，非实热闭窍。濡滑无力反映正气不足、痰浊内阻，与参芪术补虚化痰相应。", ["濡", "滑", "数"]], "3691": ["病机", "脉虽沉涩，按之益力，举之应指，体丰色泽，非阴虚之候。沉涩似阴伤，但按之有力、举之应指，说明痰浊内壅、气血不畅，金实不鸣。沉为病在里，涩为痰阻血瘀，力则为实，故用涤痰疏导而声渐出。", ["沉", "涩"]], "3692": ["病机", "脉弦大散弱，左大为甚，劳倦感寒，服燥热动血。弦为肝急，大为邪盛，散弱为气耗血伤。散大未收敛，人倦食少，示正气耗散、血失统摄。此脉主劳倦感寒、燥热伤络，故见咳痰如脓、吐血线，恐成肺痿。", ["弦", "大", "散", "弱"]], "3693": ["病机", "脉浮紧而数，左大于右，表盛里虚。浮紧为风寒束表，数为里有热，左大为邪盛于外。素嗜酒肉有积，接内涉寒，饱食后病，故表邪闭郁、里虚有积。先以人参麻黄并用，散表补虚，后以丸药消痞。", ["浮", "紧", "数"]], "3694": ["其他", "震按讨论咳嗽痰血声不出及暴嗽恶风寒之治法，未出具体脉象。文中强调暴嗽脉证属表邪而因系里虚，敢以人参、麻黄并用；又言善医者法门广大，不善医者小心与大胆均误。此段为医案评述，非脉象主病之文。", []], "3695": ["病机", "脉虚小而数，质弱产后，咳嗽痰臭，脚肿便溏，腹胀发热面红气促，不能右卧。虚小为脾虚气弱，数为虚热。脾虚湿郁酿痰，湿胜内渗于肠，故便溏；脾虚夺母气，心虚发热见于午；壅遏道路，故咳促不能右卧。此脉主脾虚湿盛、本虚标热之逆候。", ["虚", "小", "数"]], "3696": ["病机", "脉虚而数，虚为劳思梦遗、精血耗伤，数为阴不升而火独亢。原文谓“水不升而火独亢”，龙雷之火载血上溢，故吐血碗余；火亢刑金则微咳气促，外证畏风寒、呕恶、倦动、粪溏，正是“金极似火”之象，非真热实火，乃虚火挟龙雷上僭。", ["虚", "数"]], "3697": ["预后", "“脉数减，嗽渐平”，是虚火渐敛、肺金得宁之兆。前案脉虚而数，火亢水亏；今数势既减，说明参、耆、干姜温补脾肺、引火归原见效，故曰“信非熟地、阿胶所能胜任”，点明此证非纯阴腻补可解，脉数之减为转愈之机。", ["数"]], "3698": ["病机", "震按以意度脉，谓“脉必虚数”，又言“若脉虚软不数，谁不能用六君、八味哉”。虚数为火亢水亏之候，故前医用芩、连苦寒折火；虚软不数则属脾肾虚寒，当用六君、八味温补。此段借脉之虚数与否，辨火亢与虚寒之异，脉象为辨证眼目。", ["虚", "数", "软"]], "3699": ["主病", "“脉不数不虚，惟右寸浮大而滑”，明非虚痨。右寸主肺，浮大而滑为风痰壅肺之象；因多服酸收，痰不得解而久咳弥盛。故用麻黄、杏仁、半夏、前胡等宣肺化痰，五剂知、十剂已。脉不数不虚，正是排除虚痨、断为风痰未解之关键。", ["浮", "大", "滑"]], "3700": ["病机", "左关弦大，左关属肝，弦大为肝火亢盛、怒气伤肝之象；右寸下半指累累如薏苡子状，为痰壅肺窍之征。原文谓“酒属湿热，助火生痰”“怒气伤肝，故血妄行”，火炎迫肺则失音，肝火迫血则吐尿血。脉弦大证实为有余之证，非瘵也。", ["弦", "大"]], "3701": ["病机", "“六部皆沉弦而细”，沉为水寒内伏，弦细为寒饮凝滞。原文断为“水冷金寒之候”，因醉卧渴引冷饮，寒伤肺金，故咳吐清痰、咽痛、下瘀晦血。沉弦细之脉正合寒饮内盛，故用麻黄附子细辛汤温经散寒，血止咽可，继以真武、附子汤温阳化饮而安。", ["沉", "弦", "细"]], "3702": ["其他", "此段为震按评语，未出具体脉象，然点明前案“咽痛下血”不以风火治、始终用辛温燥热获效，全在“善于识脉”。即凭六部沉弦而细，识得水冷金寒之本，不为咽痛下血之标所惑，故辛温不疑。脉象虽未复述，识脉之功为全案枢要。", []], "3703": ["病机", "“六脉皆濡大无力，右手寸关独盛而涩”，濡大无力为气津两伤，右寸关独盛而涩为热伤肺气、燥痰内滞。原文谓“热伤肺气”，前医和解逼汗、苦寒折火，致肺气益燥、火郁不散，故喘咳灼热自汗、胎动不安。脉象示虚中夹燥，故用葳蕤益气生津、固肌敛肺而愈。", ["濡", "大", "涩"]], "3704": ["病机", "六脉浮滑应指，浮主风邪在表，滑主痰饮内盛，合为风邪挟饮上攻之象。前医误用疏风润肺止嗽，未及痰饮，故不应而转加呕渴咽痛。石顽以半夏、桂枝开通经络、迅扫痰涎，正合浮滑所主风痰暴嗽之机，风痰散则咽痛燥渴自止，说明此脉非燥热伤津，乃痰湿阻络、津液不布所致。", ["浮", "滑"]], "3705": ["病机", "肺脉沉而涩，沉主病在里，涩主气机郁滞不畅。原文明言外有风凉湿气遏其内热不得舒，外寒湿束表，内热郁闭于肺，肺气失宣则喘不得卧。沉涩非虚寒，乃邪郁气滞之征，故用麻黄、桂枝、苏叶散外寒，黄芩、黄连清内热，木通、陈皮通利气机，寒湿散而内热舒，喘自愈。", ["沉", "涩"]], "3706": ["病机", "两关脉动，尺寸皆虚无，关候中焦，动主邪气搏结、气血壅滞，尺寸虚无示下元不足。产后洗浴感寒，污血内停，寒凝血瘀，上逆迫肺则气喘坐不得卧，恶寒得暖稍宽为寒象。丹皮、桃仁、桂枝活血散寒，茯苓、干姜、五味温化，枳、朴、桑皮、苏子降气，正合污血感寒之病机。", ["动"]], "3707": ["其他", "震按评首案定喘汤未妥，因黄连与沉涩脉不合。沉涩主寒湿郁遏、气机不畅，非实热壅盛，故苦寒之黄连不宜。次案用药虽杂而与病情恰对，说明脉证相合则杂药亦可奏效。此段以脉象为用药取舍之据，强调沉涩之脉当避苦寒，体现凭脉辨证、不可拘泥成方之旨。", ["沉", "涩"]], "3708": ["预后", "脉浮洪六七至中或有一结，浮洪主痰热壅盛、气逆于上，故痰喘声如曳锯、夜不能卧。洪为阳脉，形证相符故曰可治；结者原文谓痰碍经隧，非气血衰败之结，故用生脉汤加竹沥养正化痰。后医误用三拗、五拗辛散，势渐危，复前方久服而安，说明洪结并见当辨痰碍而非虚败。", ["浮", "洪", "结"]], "3709": ["预后", "脉浮而洪，似命绝之状，然素有嗽病、忽大喘痰出如泉、身汗如油，乃痰气上逆、肺气欲脱之危候。浮洪为气逆于上、痰壅于肺之象，非真元外脱之微细脉，故急用生脉散敛肺固气，一帖喘定汗止，说明洪脉在此主痰逆而非绝候，与微细之真脱脉当别。", ["浮", "洪"]], "3710": ["死脉", "脉皆萦萦如蛛丝，即微细欲绝之象，年逾六十病气喘而见此脉，乃肺气衰竭、真元将脱之死候。蛛丝细脉主气血衰微、胃气将绝，与喘证之痰壅气逆迥异，故汪氏断为病不出是夜，果如期而逝。此段以微细之脉定死期，示喘病见细弱无根者预后极差。", ["细"]], "3711": ["预后", "震按总结石山三案，以脉洪为可治、脉微细为不治，着眼处正在脉之有力无力。洪主痰热壅盛而正气尚能抗邪，形证相符故可治；微细主气血衰微、真元欲脱，喘而见此则正不胜邪，故不治。此段以脉象洪微判喘证吉凶，强调凭脉断预后当辨邪盛与正衰之别。", ["洪", "微", "细"]], "3712": ["病机", "脉颇洪滑，洪为阳盛，滑主痰热，合之则内有郁热之象。秋凉外束，皮肤致密，内热不得发泄，故痰嗽气喘作；春暖腠理疏泄，郁热得散则安。前医徒用发散疏内，反虚其外、耗其津，愈增郁热。汪以三补丸加大黄、贝母、栝蒌清泻郁热，更于立秋先服滚痰丸，治本而病渐安。", ["洪", "滑"]], "3713": ["病机", "脉皆浮缓而濡，浮为表虚，缓濡为气弱不御风寒，故秋冬痰嗽气喘、自汗体倦、恶心作呕，乃表虚激内郁热而然。次年滞下，脉转濡细稍滑，濡细仍属体弱，稍滑则内郁热欲下之征。汪以参、耆、术补表，黄芩清郁热；滞下则径用小承气因势利导，终以补中益气加枳壳、黄芩、芍药收功。", ["浮", "缓", "濡", "细"]], "3714": ["其他", "此段为震按语，未出具体脉象，然明言秋凉喘嗽之证虚实不同，必辨之以脉乃无差误。前案洪滑为内郁热实，此案浮缓而濡为表虚，同是秋冬喘嗽而虚实迥异，故脉诊为辨证关键。文中『外寒束其内热』仅述证之一端，强调不可执一而论，当以脉别虚实。", []], "3715": ["主病", "脉则浮而且大，浮为风邪在表，大为阳盛气壅，合目胀出、鼻鼓扇、喘甚烦躁，显系风邪外束、痰热内壅之肺胀实证。前用顺气化痰清金降火不效者，未散外邪也。越婢加半夏汤外散风邪、内蠲痰热，故一剂减、再剂愈。李戒以参术补元助金，竟因循不补，再发不救，见肺胀虽实，攻后须顾本。", ["浮", "大"]], "3716": ["病机", "两手脉浮而洪，两关滑大有力，浮洪为风邪外闭，关滑大为中焦积热痰火内壅。痰火为风邪所闭，复加怒气，血随气上逆，故痰中大半是血、喘急不能卧、舌焦黄芒刺。议者以高年见红、脉大发热为惧，孙断为有余实证，非阴虚，法当先驱中焦痰火积热，后以地黄补血收功，此舍脉从证之要。", ["浮", "洪", "滑", "大"]], "3717": ["主病", "脉来虚数，虚为气阴两伤，数为虚热内扰，合吐清痰、肢体痿软不能举动，乃肺痿喘嗽之候。肺热叶焦，津液不布，故痿软无力；虚数之脉正示气阴耗伤而余热未清。喻嘉言以蛤蚧、人参、黑参蜜丸噙化，补肺气、益肺阴兼清虚热，不终剂而痊，可见虚数脉主肺痿虚热，非实火可攻。", ["虚", "数"]], "3718": ["病机", "脉浮大而重按豁然，即虚大之象，浮大似实，重按中空无力，乃耗气药过多、正气虚馁之征。肺胀本多实证，然此脉虚大，饮食不入而溺清便坚，知非痰热壅实，故不当以寻常肺胀论。张路玉与局方七气每剂用人参三钱，补虚行气，四剂霍然，正合『脉虚大』当补之旨。", ["浮", "大", "虚"]], "3719": ["病机", "脉得气口弦细而涩，弦主气郁，细涩为血少气滞、肺气收敛不利。尼师喘鸣肩息，服下气止嗽药不应，渐至胸腹胀满，乃劳力气上，误饮冷水伤肺，肺气不能收敛所致。越脾汤减麻黄加细辛、葶苈，大泻肺气而安，可见弦细涩非纯虚，乃气壅水停、肺失肃降之候。", ["弦", "细", "涩"]], "3720": ["病机", "原文未明言脉象，但论及“伏饮内踞有年，阳衰浊泛”，指出哮喘日久，阳衰不能化饮，饮邪上泛；又“痰中杂以血点，阴分亦渐损伤”，说明久病及阴，阴阳两伤，病机复杂，故用药需兼顾刚柔。", []], "3721": ["病机", "气口脉大两倍于人迎，关脉沉缓有力，为饮食过度、湿热内盛之象。湿热上攻于肺，肺气壅盛，故喘满腹胀，声闻于外，不得安卧，大小便涩滞。脉沉缓有力主实，邪气盛则实，实者宜下。", ["大", "沉", "缓"]], "3722": ["病机", "脉沉而滑，沉主里，滑主痰。痰滞经络，脏腑痞塞，气机不畅，故生䐜胀气喘。前医误补误下，喘益甚，程氏断为痰病，投滚痰丸下痰而愈，正是“痰滞经络”之明证。", ["沉", "滑"]], "3723": ["病机", "原文“视脉无他”，脉象未见异常，说明病非内伤脏腑，而是食羊脂后脂冷凝滞，阻碍气机，致胀而喘、食不下咽。温熨得利而愈，提示病机为寒凝食滞，非脉所能独见。", []], "3724": ["其他", "此段为震按，讨论针灸与切脉之难，未涉及具体脉象与病机。原文强调“切脉与取穴同一难”，意在说明诊脉处方不可轻视，非论病机。", []], "3725": ["病机", "原文虽未直接以脉论病，但引孙一奎案，臌胀而脉滑数，滑主痰湿，数主热，湿热生虫，故腹大如箕、四肢瘦削、发热昼夜不退。虫积日久，耗伤气血，故形瘦而腹大。", ["滑", "数"]], "3726": ["病机", "脉洪而大，为湿热内盛之象。湿热蕴结，化生虫积，故腹胀大，按之有块，四肢瘦削，发热不退。饮食如常，非臌胀，乃虫积为患，故以石榴根皮、槟榔杀虫而愈。", ["洪", "大"]], "3727": ["病机", "脉弦而涩，弦主气滞，涩主血少。嗜酒伤脾，疟久伤气，气滞湿阻，血行不畅，故手足瘦而腹大如蜘蛛状。重按则大，说明邪实而正虚，治以补气行湿，使疟愈胀消。", ["弦", "涩"]], "3728": ["误治", "脉皆大，按则散而无力，大而散为气散不收、中气大虚之象。患者胸腹胀满，本非实邪，却自用下药利十数行，徒伤中气，致脉散无力。朱氏断为表证反攻里，当死，赖禀厚可救。此脉示误下后气散正虚，故用四物加参、术等补益，后去芍地加芪术，皆从虚治。", ["大", "散"]], "3729": ["病机", "震按中引女子脉大而散，大散为气血耗散、营阴亏虚之候。前案女子腹胀，脉大散而无力，朱氏用四物加参术，未用附子，震疑其何以不用附子而犹用四物。此脉示营阴先亏、气不收敛，故慎用热药，以补血益气为治，反映大散脉主虚损、忌温燥之病机。", ["大", "散"]], "3730": ["病机", "六脉弦滑而数，项氏断为弦主气结、滑主血聚，气薄血室，实邪也。弦滑数并见，示气滞血瘀、郁而化热。故先顺气，投苏合香丸，后以硝黄逐瘀。又二女病同，一脉虚、一脉纯弦，皆辞不治。虚为正气已衰，纯弦为邪盛无胃气，故主死。此段以脉辨实邪可攻与虚弦不治。", ["弦", "滑", "数", "虚"]], "3731": ["病机", "脉浮大不及于寸口，浮大为虚阳外浮，不及寸口示中气不足、根本亏虚。患者屡服化痰行气、导痰理脾、分气利水、破血消导之剂，愈伤正气，致腹大胁痛、两足皆肿。此脉示脾肾两虚、水气不化，故朝用金匮肾气丸、夕用补中益气汤，温补脾肾而愈。", ["浮", "大"]], "3732": ["主病", "脉皆洪滑，洪为热盛，滑为湿聚，洪滑并见主湿热内蕴。患者年逾四十，瘦长善饮，酒湿化热，蕴于中焦，故腹胀。汪氏引脉诀“腹胀浮大，是出厄也”，以洪滑为湿热有余之实脉，可治。遂用香连丸清热燥湿，并嘱远酒色，月余良愈。此脉示湿热鼓胀，属实可攻。", ["洪", "滑"]], "3733": ["病机", "脉浮缓而濡，两尺尤弱，浮缓濡为水湿泛溢、正气不足，尺弱示肾虚。患者水肿面光、腹大如箕、脚肿如槌，汪氏断为酒色伤肾，水极似土，虚象也。若通利渗泄则下多亡阴，肾水益耗。故用地黄丸补肾，佐四物加柏、通、朴、陈、参、术，标本兼治，肿减而愈。此脉主肾虚水泛。", ["浮", "缓", "濡", "弱"]], "3734": ["其他", "震按汪公论病甚佳，用药非是。就脉之缓濡为湿热，认为宜六君子汤送济生肾气丸，反疑地黄丸、四物汤为阴湿柔黏之药，更佐黄柏。此段以缓濡脉辨湿热，然震对汪氏三十帖愈未敢深信。缓濡主湿，兼热则濡缓，震据此议治法，属评述性文字，非直接主病。", ["缓", "濡"]], "3735": ["预后", "一妇脉细濡近快，一妇脉缓弱无力，俱病鼓胀大如箕。细濡近快为阴血亏虚、虚热内扰，缓弱无力为脾气大虚。石山断腹皮宽缒已定，非药可敛，惟宜安心寡欲保命。后皆因产而卒，因气病血未病，产则血亦病，阴阳两虚。此脉示鼓胀至气血两虚，预后不良。", ["细", "濡", "缓", "弱"]], "3736": ["病机", "原文以“脉必细而紧，或沉而涩”推测胀满之脉，细紧主气机收引、津液枯涩，沉涩主气滞血少、水气不布。喻案因“腹中之气散乱不收”，津水随气横决四溢而胀，故脉不当滑大数实；若见滑大数实，则为实热壅结，此方不可用，正说明细紧沉涩主气散水溢之虚胀。", ["细", "紧", "沉", "涩"]], "3737": ["其他", "此段为震氏读案按语，明言“只恨不载脉象若何，难以摩仿”，故无脉可辨。其议论高爽，作为胀病之大训，强调胀病辨证须参脉象，否则难仿其治。原文未出脉名，只可视为对前案缺脉的叹惜，非论具体病机。", []], "3738": ["病机", "原文“六部皆不出”指脉气闭遏不显，非无脉，乃水湿壅盛、气机闭塞所致。赵氏用紫苏、桔梗宣肺开闭，服后“胸有微汗”“身尽汗”，继而“六部和平之脉皆出”，说明脉闭由气水壅遏，汗出气通则脉复，证实胀病脉伏主气机闭塞、水湿内停。", []], "3739": ["病机", "脉左沉、重取不应，主水气内郁、阳气不达；右短小却和滑，短小主气弱，和滑示中焦尚存胃气。症见头肿目闭、膈如筑、足麻至膝、恶风、阴器挺长，皆水湿壅遏、风邪外袭之象。脉沉不应与短小和滑并见，说明正虚水停、风扰于上，故用白术探吐、麻黄防风得汗而肿退。", ["沉", "短", "小", "滑"]], "3740": ["病机", "“六脉坚实”主水饮暴停、邪实壅盛。何氏夏月饮水十余碗，归寓胀闷不能食，旬日胀如抱瓮、气高而喘，皮薄而光，皆水停不化、邪实于里之征。脉坚实与暴成之病相应，故法当利之，用舟车丸峻下，二便涌决如泉而愈，说明坚实脉主水饮内结之实证。", ["坚", "实"]], "3741": ["其他", "此段为震氏按语，评“峻补急攻”二案如狮子抟象，全副神力，劝学者“要看其病因，观其论脉”，即知前贤非蠹心大胆。原文未出具体脉象，主旨在于强调脉证合参、因证施治，非论某脉主某病，故归其他。", []], "3742": ["主病", "脉大而数、右尺为甚，大主邪盛，数主热壅，右尺应下焦，故主大肠痈。症见腹满而痛、喘急异常、大便不通、饮食不进，按腹手不可近，皆肠痈脓成、热毒壅结之候。原文明言“脉数为脓已成”，数脉在此主热盛肉腐成脓，故用黄芪、角刺、白芷、银花排脓解毒而愈。", ["大", "数"]], "3743": ["病机", "两手皆滑大、两尺尤有力，滑主痰食壅盛，大主邪实，尺部有力说明下焦积滞深重。马氏过食鳗肉卷饼，又连服硝黄、承气、备急丸等攻下，大便不行、小便点滴、胀大如覆箕，脉滑大有力正示实邪壅结、气机不通，非虚胀可比，故孙氏骇然，当从实积论治。", ["滑", "大"]], "3744": ["预后", "原文载“脉无根，仅如蛛丝”，此脉象提示正气衰败，胃气将绝，故断为“不可为矣”。病起于跌仆水中，感冷湿之气，又误用金石寒冷药镇坠，致邪深陷、食停不运，胸高息微，神识不清，皆由脾胃衰败、气机壅塞所致。脉无根而细如蛛丝，正是元气欲脱之兆，故预后凶险。", []], "3745": ["病机", "脉浮大无力，浮为气虚外浮，大为虚阳外越，无力主中气不足。患者哮喘日久，嗜酒纵欲，耗伤元气，致气虚中满，腹大如覆箕，两腿光肿，气喘身热而畏寒甚，皆由下焦气不充、水湿不化。孙东宿断为“气虚中满”，法当温补下元，正合此脉。", ["浮", "大", "无", "力"]], "3746": ["病机", "原文未明言脉象，但述“胀而脉觉”，结合慎斋用黄柏、青盐、升麻而愈，其病机为命门火郁，肾之真阳不升，心之真阴不降，水火不交，脾肺气机壅滞而胀。药用黄柏解命门壮火，青盐润心降火，升麻提青气升浊气降，使水火既济，胀证得愈。本在肾而标在心。", []], "3747": ["病机", "六脉沉细如丝，沉主里，细如丝为阳气衰微、水湿内停之象。患者呕逆水肿，溲便涓滴不通，前用五苓八正不应，知非单纯湿热壅塞，乃下焦阳虚不能化气行水。与金液丹温补下元，溺如泉涌而势平，后以济生肾气培养而安，脉证相合。", ["沉", "细", "如", "丝"]], "3748": ["病机", "脉沉而大，沉主水，大主虚，此水气内停而正气已虚。患者腰以下胕肿，面目俱肿，喘急欲死，不能伏枕，大便溏泄，小便短少，乃病后冒风，风水相搏。用千金神秘汤加麻黄宣肺利水，喘定肿消，继以胃苓汤吞深师薷术丸，正合沉主水、大主虚之旨。", ["沉", "大"]], "3749": ["其他", "此段为震按，评述金液丹、神秘汤之运用，非论脉象。原文“脉散合二陈汤”系指神秘汤乃生脉散合二陈汤加减，非脉象描述。震强调古方须对证而用，神秘汤施于水气上逆之证恰好，加麻黄更好，非通行之方。故脉象要素为空，主旨属其他。", []], "3750": ["病机", "脉皆细弱而缓，细弱为气血不足，缓为脾虚湿滞。患者心悸，常若有人捕之，恐恐然不能安寐，前医作心病治不效。汪石山断为胆病，因胆虚痰扰，决断失职，故惊悸不安。用温胆汤化痰宁胆而安，脉细弱缓正是胆虚痰湿内蕴之征。", ["细", "弱", "缓"]], "3751": ["病机", "原文未明言脉象，但许学士“以脉言之，肝经受邪”，结合卧则魂飞扬、惊悸多魇、通宵不寐，断为肝经受邪，魂不得归于肝。肝主怒，小怒则剧。用真珠母、龙齿安魂定魄。此段以脉测证，脉象虽未录，病机在肝经邪扰、魂不归舍，非心病。", []], "3752": ["病机", "原文脉细弱而缓，震按提出当凭兼证辨为肝胆之病，而非阳气两虚。细弱缓本可主虚，但结合不寐之肝胆证，则示阴血不足、阳气不交，神不归舍。文中强调心肾不交、水火未济则目不瞑，故此脉在此非单纯阳虚，而是肝胆失调、阴阳出入失序之机，须合兼症方定。", ["细", "弱", "缓"]], "3753": ["病机", "脉虚大而数，虚为思虑伤心、内伤不足，大为气浮不敛，数为厥阴相火扰动。原文谓思虑过度、厥阴之火为害，相火一扰能为百病。此脉示心气已虚而火不归位，故见怔忡善忘、多汗发热、小便白浊，非茸附温补所宜，当补中兼清火安神。", ["虚", "大", "数"]], "3754": ["病机", "脉豁豁然虚大而浮，因恐怖惊惕而致。虚大示心神浮越、气不内守，浮为风动于上、无形之邪。原文谓疾走无形，从风家治之，兼化痰散结。此脉说明惊则气乱、厥阴风木化风上扰，故心常惕惕如畏人捕，体热多汗，治当息风安神。", ["虚", "大", "浮"]], "3755": ["病机", "左脉弦而大，右浮滑不匀。原文断为血少火旺、气盛痰多。弦大为肝火亢盛、阴血不足，浮滑不匀为气盛痰壅。火旺痰多上扰心神，故怔忡惊惕时发时止。此脉示肝胆火旺兼痰气交阻，非金石镇心可安，故用温胆汤化痰清火而效。", ["弦", "大", "浮", "滑"]], "3756": ["病机", "诊得心脉独虚、肝脉独旺。心脉独虚示惊惧伤心、心血不足而神不守舍；肝脉独旺示惊恐动肝、肝阳偏亢。原文述因寇盗风声鹤唳日夜惊惧而致怔忡不寐，正合心虚肝旺之机。此脉说明惊则神伤、肝木偏旺，治当养心安神兼平肝，故用生地麦冬枣仁等而效。", ["虚"]], "3757": ["病机", "脉举弦按涩，至骨则沉滞数。举弦为肝风内动，按涩为血行不畅、痰瘀阻络，沉滞数示郁热深伏于里。原文痫发手足扬掷、面紫黑、流涎昏愦，皆风痰瘀热蒙蔽清窍之象。此脉说明肝风挟痰瘀、郁热内扰，故治以通圣散加桃仁红花，吐下瘀滞而愈。", ["弦", "涩", "沉", "数"]], "3758": ["病机", "脉微弦六至，轻重有。微弦示厥阴肝木之象，六至为数，示相火内动。原文谓内素有湿热，因羞怒激起厥阴相火，又值时令相火。此脉说明肝火挟湿热上扰，故发昏搐搦如狂、面紫黑、睪丸能动。肝病当先救脾土，诸香燥药坏脾，故以黄连为君清火、人参扶脾。", ["弦", "数"]], "3759": ["病机", "脉皆缓弱颇弦。缓弱为脾胃气虚，颇弦为肝木偏旺。原文断为木火乘土之病，晨盥阳分发作、目击异物而仆，皆胃虚为木火所乘之象。此脉说明土虚木亢、肝火乘胃，故宜实胃泻肝而火自息，用参耆归术补中、黄芩麦冬清火，正合泄肝缓中之旨。", ["缓", "弱", "弦"]], "3760": ["病机", "脉累累如薏苡子，且喘且搏，为滑数有力之象，主阳明胃实。滑为痰食内壅，数为热盛搏急，胃热上蒸，扰乱神明，故发狂谵语、视人皆鬼。喘而搏者，热壅气逆，脉道急迫，与《素问》阳明血气并盛之旨相合。", ["滑", "数"]], "3761": ["病机", "上部脉弦滑，左部劲于右，弦主惊风，滑主痰涎。惊气入心，风痰上溢膻中，灌于心胞，蒙蔽神明，故终日奔走、自贤自贵、或泣或笑。左劲于右，示病偏于血分及心肝，风痰内扰，非虚候也。", ["弦", "滑"]], "3762": ["病机", "三部皆弦直上下行，左寸口尤浮滑。弦直为风，浮滑为痰，风痰上壅心胞，神明被蒙，故病狂。左寸候心，浮滑独显，正合风痰留心胞之机。涌吐痰沫后熟睡病去，可证痰去则神安。", ["弦", "浮", "滑"]], "3763": ["病机", "脉浮而涩，浮为神气外浮，涩为血少思虑伤脾。女子瘦弱性急，思虑过度，暗耗心血，神不守舍，故发颠疾，哭笑裸走。浮涩并见，非外邪，乃内伤神志，血虚而神荡也。", ["浮", "涩"]], "3764": ["其他", "原文仅言脉空风动，未列具体脉象，故脉素从缺。所述颤掉搐搦、角弓反张、叫号而心却明白，显系虚风内动、神不守舍之候。前医消痰清火不效，叶天翁以脉空风动为辨，提示病本在虚，风由虚生，非实痰实火可比。", []], "3765": ["病机", "脉沉坚而结，沉主里，坚主实，结主积滞。忧愤沉郁，气机郁结，痰与血交积胸中，阻滞脉道，故脉沉坚而结。痰血互结，上扰神明，则狂歌痛哭、裸裎妄骂；问之瞪视默默，亦郁结神蒙之象。涌吐积痰裹血，去其壅塞则愈。", ["沉", "坚", "结"]], "3766": ["病机", "脉俱沉，沉主里、主积。妇人哭笑不常，似鬼所凭，而脉沉不起，知非外邪，乃胃脘积痰为患。痰积于中，气机不畅，故必作疼；痰蒙心窍，则哭笑无常。二陈汤导吐痰涎，积去则神清，所谓积痰类祟也。", ["沉"]], "3767": ["病机", "脉濡缓而虚，按之不足，濡缓为湿为虚，按之无力则中气大虚。形肥色白，酒中受辱，情志伤中，阳明虚弱，痰湿内停，虚风上扰，故病心恙、持刀逾垣、披头大叫。汪断为阳明虚，宜实之，与前医清心泻火致狂倍发相印证。", ["濡", "缓", "虚"]], "3768": ["误治", "原文未识脉名，但强调“狂至持刀上屋，大渴恣饮”为痰火实证，若误用吐下或黄连、石膏等正治，则“狂愈甚则元气脱”。此段借脉论治，指出实证误攻致元气脱散，脉当由实转虚，故列误治。", []], "3769": ["病机", "脉乍大乍小、乍长乍短，为气血不匀、邪气伤正之象。罗谦甫断为“鬼击”，因夜梦妇人击胁而痛、寒热不食，邪正交争故脉乍变。此脉反映邪扰气血，非固定之病脉。", ["大", "小", "长", "短"]], "3770": ["兼症", "寸脉乍大乍小，似鬼祟，但两关弦滑且大，断为痰饮。弦主饮癖，滑主痰聚，痰饮上扰心神则见鬼、口舌糜烂。脉乍大乍小为痰气交阻、气血不匀之兼症表现。", ["大", "小", "弦", "滑"]], "3771": ["病机", "脉虚弦带沉数，数为有热，虚弦是惊，沉主里。因大劳而渴，恣饮梅浆停郁中脘，又连大惊，故脉虚弦而沉数。虚为气馁，弦为惊扰，沉数为郁热内停，主补虚清热导滞。", ["虚", "弦", "沉", "数"]], "3772": ["病机", "两手洪数而实，似实热，但形肥面赤带白、露筋，脉本不实，乃凉药所致。洪数实为假象，真为劳倦内伤、阳气外浮。服温补后脉稍软，渐收敛而小，示元气渐复，病机由虚阳外越转内敛。", ["洪", "数", "实", "软"]], "3773": ["病机", "脉乍疏乍数而虚，为气血不匀、心神虚扰之象。妇如醉如痴、颊赤面青、潮热不食，虚数主虚热，乍疏乍数为神气不宁。此脉示正虚邪扰，非实热，故八物汤补虚安神。", ["疏", "数", "虚"]], "3774": ["其他", "震按三条奇案，首条脉虚弦因大劳，次条脉本不实因凉药，三条邪魅。此段评述脉证难效法，强调识脉守方之要。虚弦为劳倦惊扰，脉本不实为假实真虚，示辨脉须审体质与药误。", ["虚", "弦"]], "3775": ["预后", "脉来寸盛尺微、前大后小、按之忽无举之忽有，为神气浮散之候。寸盛尺微示上下不交，前大后小、忽有忽无乃根本动摇、精气下脱。故断为神气浮散，预后险，治以六君子加龙齿、菖蒲、远志送养正丹。", ["盛", "微", "大", "小"]], "3776": ["其他", "原文未出具体脉名，只言“从其脉象以施治法”，强调鬼祟之病多属痰或虚，当据脉辨其虚实而施治。脉象为辨痰虚之凭据，非直接主病，故列其他。", []], "3777": ["病机", "脉旦弦搏而大，午尤洪大，弦主郁滞，大洪为郁热鼓动。原文断为“有郁滞”，故先用滚痰丸下之；涩药反甚，改用导赤散而止，说明病机在郁热而非单纯肾虚不固。", ["弦", "大", "洪"]], "3778": ["病机", "脉或浮濡而快，或沉弱而缓，脉之不常，原文断为“虚之故也”。浮濡为气虚外浮，沉弱缓为里虚，反映心脾肾三经亏虚、心火亢而脾弱，故以补脾为主兼滋肾养心。", ["浮", "濡", "沉", "弱"]], "3779": ["病机", "左脉浮濡无力，右寸浮散近快，两尺尤弱不任寻按，为虚损之象。浮濡无力主气虚，浮散近快为虚阳不敛，尺弱为肾亏，故见头晕腰痛骨酸畏风，属肾虚不固兼脾肺气虚。", ["浮", "濡", "散", "弱"]], "3780": ["病机", "六脉滑大，原文断为“酒味湿热，不干精藏”。滑主湿，大主热，湿热下注扰动精室，故小便毕有白精数点；非虚滑不固，故固涩无效，用清利湿热而效。", ["滑", "大"]], "3781": ["病机", "两寸短弱，两关滑，两尺洪滑，原文断为“湿痰下流证也”。寸短弱为心肺气虚，关滑为湿痰，尺洪滑为阳乘于阴、湿热下注，故白浊久不愈，治当从阴引阳、顺时升提。", ["短", "弱", "滑", "洪"]], "3782": ["病机", "脉沉数无力，原文知“气与火转郁于小肠”。沉主里，数主热，无力为虚，故属气郁化火之虚热，非实热；前医以苦寒厚味攻之，寒极伤气而愈剧，当用清凉薄剂。", ["沉", "数", "无", "力"]], "3783": ["病机", "脉沉缓，时时带数，原文谓“膏粱湿热内蓄，不得施化，膀胱窍涩”。沉缓主湿滞于里，带数为湿热郁蒸，故小便数而少、脐腹胀满，治以甘淡渗泄、缓之泄之。", ["沉", "缓", "数"]], "3784": ["病机", "脉短涩，左微似弦。涩为败血，短为血耗，乃乌、附积毒凝滞，蓄血膀胱，兼忍痛叫号伤气耗血。脉证合参，知溺后有如败脓，故先治淋，用土牛膝通滞血，四物生血。", ["短", "涩", "弦", "微"]], "3785": ["病机", "震按脉涩者，血瘀也，亦主血虚。土牛膝汁能疏通滞血，故涩脉宜之。丹溪合四物同用，因脉兼短，短为血耗，即不短亦宜。涩短并见，示瘀滞兼血虚之机。", ["涩", "短"]], "3786": ["主病", "淋久囊大茎肿，服利药多而痛甚，脉微弱如线。微弱为气血虚衰，过利伤正，脉道不充。虽淋证多宜利，此则虚象显著，故以参、耆、归、术补益为主，佐肉桂、元胡等温通。", ["微", "弱", "细"]], "3787": ["治法", "震按服利药多，脉微弱如线，法必宜补。然仍兼延胡、赤芍、木通等利血利水者，以证仍痛甚也。若果阳虚脉微，当用金匮肾气丸，与知、柏不宜。此示脉微当补，而兼痛可佐通利。", ["微", "弱"]], "3788": ["兼症", "脉仅四至，两寸软弱，脉尚不数。四至为缓，软弱示气血不足，不数则无实热。患者孀居茹素，屡怒吐血，里急后重，二便交替疼痛，经闭带下，面浮肌消，脉证合参，属虚中夹滞、肝郁痰凝。", ["缓", "软", "弱", "数"]], "3789": ["病机", "血淋复发，痛极尿血块，诸通利清热不应，脉俱洪数。洪数为湿热壅盛、血分瘀热之象。前服补下元药过多，助热留瘀，故以五灵脂、蒲黄等消瘀清热，痛减血止。", ["洪", "数"]], "3790": ["其他", "震按上条不用补，次条不用养阴，认证最清。设效立斋、景岳，狃于归脾汤、补中益气、六味、生脉者，必为二证之戈矛矣。此评述前案治法，强调认证准确，不盲目套用补益养阴。", []], "3791": ["病机", "脉左寸短弱，关弦大，右寸下半指与关皆滑大，两尺俱洪大。短弱示心血不足，弦大滑大洪大主中焦痰盛、肝经瘀血、下焦湿热。年高病久血去多，故当去瘀生新、提清降浊，兼补兼消。", ["短", "弱", "弦", "大"]], "3792": ["病机", "左寸沉弱，关尺弦细，右寸略滑。沉弱主气血不足，弦细为肝经瘀血，滑为肺经浊痰。酒后纵欲，淫火交煽，精离故道，凝滞经络，流于溺道，新血阻塞而成淋浊。脉象反映痰瘀互结、本虚标实之病机。", ["沉", "弱", "弦", "细"]], "3793": ["病机", "脉弦细而数，两尺按之益坚，右关涩大少力。弦细数主肾水素亏、肝木乘脾；尺坚为阴火下溜，右关涩大为脾土受克。劳心思虑伤脾，肝木乘之，气化不利，故膏淋溺痛。法当实中土以堤水。", ["弦", "细", "数", "涩"]], "3794": ["其他", "此段无具体脉象，震按强调淋证治法有经权之别，皆审脉以辨。引庄子“诊其梦”释“诊”为审，四诊皆须细审。脉象虽未明言，但脉诊为辨证关键，体现审脉以别病机之要。", []], "3795": ["病机", "脉右寸颇弦滑，右寸候肺，弦滑主积痰在肺。肺为上焦，上焦闭则下焦塞，如滴水之器上窍不通则下窍不出。故小便不通，医用利药益甚。吐法通上窍，痰去则水自下，病如失。", ["弦", "滑"]], "3796": ["病机", "六脉见结，结脉主气滞。郁怒之余，又当盛夏，气机壅滞，小便不通，气高而喘。服胃苓汤不效，以枳壳、生姜行气散结，气通则溺通。脉结反映气滞不行之病机。", ["结"]], "3797": ["病机", "脉滑数，滑主痰湿，数主热。心中如火一烧，便入小肠，急去小便，大便随时亦出，此相火送入小肠经。滑数脉示相火妄动、湿热下注，故以四物加炒连、柏、小茴、木通清利相火。", ["滑", "数"]], "3798": ["病机", "六脉沉迟，沉主里，迟主寒。饮食不进，小便不禁，水泉不藏，是无火也。沉迟脉示下焦命门火衰，不能温煦固摄，故以八味丸、六君子加益智、肉桂温补。", ["沉", "迟"]], "3799": ["病机", "六脉举之则软，按之则坚。软为不足，坚为有余，此肾肝之阴有伏热也。忧忿经旬，肝郁化热，伏于阴分，故小便不禁。误补则热炽，以丹皮、茯苓、苦参、黄连清伏热，后以龙胆泻肝汤泻肝热。", ["软", "坚"]], "3800": ["病机", "脉或虚大或细数，左关尺必显弦象，虚大为肾气不固，细数为阴亏火动，弦为水不涵木、肝失疏泄。合之溺涩与遗溺并见，显系肾气大亏、下元不固而为下脱之兆，故用地黄饮子、八味丸加减温补收涩。", ["虚", "细", "数", "弦"]], "3801": ["病机", "脉软大而涩涩不调，软大为气虚湿盛，涩为湿阻血瘀、脉道不利，散则气不收敛。酒湿乘虚袭入髓窍，胞痹日久，溲从谷道点滴而渗，中有结块，皆湿浊瘀阻、气化失司之象，故以渗湿通窍为治。", ["软", "大", "涩", "散"]], "3802": ["病机", "两寸短弱，关缓大，两尺洪大。寸短弱为心肺气虚，关缓大为暑湿伤中、脾运不健，尺洪大为湿热下注膀胱。暑湿内蕴、气化不利，故卧则溺流、立则点滴不出，非单纯气虚下陷，乃余暑未清、湿热阻遏之机。", ["短", "弱", "缓", "洪"]], "3803": ["预后", "左尺脉洪数，为肾经虚热，法当滋补；误服知母、黄柏苦寒年余，反伤肾气，致高骨肿痛、小便淋沥，肺肾二脉洪数无伦。洪数无伦乃真阴耗竭、虚阳外越之象，子母俱败，故断为鲜克济矣，果寻卒，示脉失和缓之预后不良。", ["洪", "数"]], "3804": ["治法", "脉实者、沉实者，为邪实内结、脾胃气滞不转输，痰饮食积阻碍浊道，故二便秘涩。体健神旺者可用八正散倍大黄或升、柴、二陈、二术汤以攻邪行滞；若形弱及老人、病后产后，则从虚秘治，润燥养阴为主，示凭脉辨虚实以定攻补之法。", ["实", "沉"]], "3805": ["病机", "六脉皆沉伏而结涩，沉伏为气血内滞、阳气不达，结涩为血虚津枯、脉道不利。年五十余、体瘦、便燥、食少、腹痛，作血虚治，用四物加桃仁、麻仁、大黄。然胃气虚不能久留速药，故以蜡匮备急丸达下，示沉伏结涩主血虚肠燥兼胃弱。", ["沉", "伏", "结", "涩"]], "3806": ["病机", "脉洪大，重按微细，洪大为虚阳浮越、痰热内扰，微细为肝肺肾真阴亏损。年七十三，痰喘内热、便闭不寐，乃本虚标实之候，故朝用六味丸、夕用逍遥散滋补肝脾肾，待饮食渐进、腹痞闷时以猪胆汁导下，终用十全大补收功。", ["洪", "大", "微", "细"]], "3807": ["病机", "脉皆濡细近快，心脉颇大，右脉觉弱。濡细为气血不足，近快为虚中有热，右脉弱为脾虚气弱。劳倦忧惧伤脾，脾失健运，气滞不行而致秘结，前医误用硝、黄但利血不能利气，故随通随闭，病增胸膈胃脘胀痛，治当补脾行气。", ["濡", "细", "大", "弱"]], "3808": ["病机", "肾脉沉小而无神，沉为在里，小为不足，无神则肾阳肾精俱亏。肾司二便，肾虚则大肠传导无力，故大便燥结不通；肾不纳气、中焦不运，故胸膈塞闷而不食。此非实热燥结，乃虚秘，故用苁蓉温润、枳壳宽中而效，后以当归、首乌养血润肠全愈。", ["沉", "小"]], "3809": ["病机", "六脉无力而头面身热、口不渴、足冷至股，脉症合参知非外感实火，乃阴虚受邪、虚阳浮越之阴证。脉无力为根本虚衰，足冷为阳气不能下达。前医滋阴清火反剧，张景岳以理阴煎加参、柴温补托邪，热退而便通腹胀，仍守前方加姜、附，正合“肾恶燥，急食辛以润之”之旨。", []], "3810": ["病机", "六脉弦促，弦主气郁、惊扰，促主气机急促不宁。钱女因邻居被盗受惊，惊则气乱，痰随气逆，袭于窍端，致清浊相干、便溺易位而成交肠。脉弦促正是惊气乱、痰气交阻之象，故以四七汤下礞石滚痰丸开通痰气而安，与产后恶露不行、血痢稀粪前阴之案同属交肠而病因各异。", ["弦", "促"]], "3811": ["兼症", "脉微数、脉散加百合，微为阳气虚衰，数为虚火浮动，散则心神涣散不敛。孟堂因思子郁结，虚火上升，自汗不止，心神恍惚，欲食不能食、欲卧不能卧，口苦溺难，皆虚火扰心、百脉失和之候。诸药杂投辄增一病，正见其虚不受攻，惟人参入粥和服以扶元气。", ["微", "数", "散"]], "3812": ["其他", "此段为震按语，辨孟夫人病形大半似百合病，由思子郁结、病在心肝，非真百合病。原文未及脉象，故脉象要素为空。震评石顽附会百合之名而不用金匮成方，然其辨病在心肝郁结、不泥成方，自有老手之处，属对前案的评述而非脉诊病机。", []], "3813": ["病机", "脉浮小而濡、按之不足，浮为气虚外浮，小濡为营血不足、脉道不充，按之无力更证实虚。形长瘦、色白脆，合脉症知为虚证。身如虫行淫淫循行，即伤寒论“身如虫行，汗多亡阳”之虚风内动，非虫非火，故用补中益气汤多加参、耆补气升阳，少佐黄柏而愈。", ["浮", "小", "濡"]], "3814": ["病机", "四肢厥冷、六脉沉伏，沉伏为邪闭于里、阳气不能外达，非真阳衰绝。此人吞金，金重坠闭阻气机，气血壅遏，故脉沉伏而肢厥，属“大实有羸状”之闭证。江应宿以硼砂制金、承气汤通下，金从大便出而安，脉伏正示邪实内闭、当以通下为治。", ["沉", "伏"]], "3815": ["病机", "此段未载脉象，张锐切脉后戒其忍饥，以黄土搅温酒吞之，再送宣药，泻出马蝗千余。病由夏夜饮涧水，蚂蝗入喉，居肠胃吮咂精血，故肌肉消瘦、食入腹如虫攒攻且痒且痛，形似劳瘵而实为虫积。脉象原文未述，故脉象要素为空，主旨在于辨虫积之病机而非凭脉。", []], "3816": ["病机", "六脉弦细而微，为气虚阳弱之象。患者年高气弱，误汗伤阳，清阳不升，故头昏痛、恶风寒；气短懒言、不喜饮食，皆中气不足。弦为清阳不升之脉，细微为气血亏虚，故罗氏断为气虚头痛，治以顺气和中汤补益升提。", ["弦", "细", "微"]], "3817": ["病机", "六部皆滑大有力，滑主痰，大主热，有力为实。痰热壅盛，上蒙清窍，故头痛如破、晕倒不省人事；痰阻中焦，则胸膈饱闷、吐蛔。孙氏断为痰厥头痛，先吐后下，正合脉实可攻之旨。", ["滑", "大"]], "3818": ["病机", "右关细涩，左关洪，左尺亦涩。细涩为阳气不达，洪为阴火上冲。下焦无阳，阴火上攻，故齿痛头肿。服羌活散火汤后细涩转粗大，是阳气下行；脉益和，则阳气已至病所，故知将愈。", ["细", "涩", "洪"]], "3819": ["其他", "此段为震按总结诸家头痛案，未载具体脉象。文中列气虚、积热、肝火、肾虚、痰厥、阳升不降六种内因，及风、寒、湿外因，强调头痛多兼风，久则成头风。所论以证候分类为主，非专论脉，故脉象要素从略。", []], "3820": ["其他", "此段为震按评述，未载脉象。文中强调“治病必以脉为凭”，但所录四条医案不载脉，证颇疑难而法殊整暇。又批评江篁南、翟文炳二条只叙见证、未可摹仿。全段主旨在于脉证合参之重要，非论具体脉象。", []], "3821": ["病机", "脉弦细而微，为脾胃虚寒、阳气衰微之象。患者久疟服寒药，损伤中阳，故手足冷、面青黄、食少痞闷、呕吐酸水、冷汗气促。弦为寒痛，细微为阳衰，罗氏引《内经》上气不足、中气不足、下气不足以明病机，主以温补。", ["弦", "细", "微"]], "3822": ["病机", "三部俱微短沉弱，不应呼吸，为阴寒极盛、阳气欲绝之脉。盛暑洞泄，厥逆恶寒，胃脘痛引胁，滞下呕哕，皆阴寒内盛、格阳于外。滑氏断为阴寒极，亟用姜附温之，正合《内经》“有假其气则无禁”之旨。", ["微", "短", "沉", "弱"]], "3823": ["病机", "脉迟弱弦而涩，迟弱为阳虚，弦为痛为饮，涩为血瘀湿滞。患者酒饮牛乳，湿滞血瘀，久痛入络，故心疼年久、吞酸、便或秘或泄。丹溪以二陈加芩连桃仁等，涌出黑水，脉涩渐退、纯弦渐满，是瘀滞渐化、血气渐充之兆。", ["迟", "弱", "弦", "涩"]], "3824": ["病机", "脉沉细涩，稍重则绝，轻似弦而短，为阳气郁遏、湿热内阻之象。手足寒过肘膝、须绵裹火烘似虚寒，然胸畏热喜凉、渴喜热饮，知非真寒；沉细涩主气血不畅、湿浊中阻，故心脾疼而腹胀满、不食。丹溪以草豆蔻丸加黄连、滑石，正是从脉沉细涩辨为湿热停饮，非虚寒可比。", ["沉", "细", "涩"]], "3825": ["病机", "震按指出脉沉细涩为据，稍重则绝者以细涩故也，与阔大而软之虚寒不同。脉弦细涩者俱不用温药，因弦主气郁、细涩主血少湿滞，合之知为湿热停饮而非虚寒。胸前畏热喜凉亦佐证热象。此段以脉涩、沉细涩辨虚实寒热之机，强调凭脉认病，不可见寒症即投温补。", ["沉", "细", "涩", "弦"]], "3826": ["病机", "六脉洪数而滑，洪为阳盛，数为热，滑主痰饮。前医作胃寒治，用姜桂丁沉等反剧加口渴、小水淋漓，正因痰饮郁而化热。脉洪数滑说明痰热内盛、随气升降，故胸膈痛与膝䯊痛互作。虞氏据此断为痰病，先熬竹沥清热化痰，继用吐法涌痰，皆从洪数滑之脉象定病机为痰热而非寒。", ["洪", "数", "滑"]], "3827": ["病机", "脉皆平常弦大，六脉伏，弦大为气郁痰壅，伏为邪遏经络、气血不行。许案因食积痰饮续冒寒湿，抑遏经络，津液不通，痰饮上升为痹疼、下降为胯痛，故脉见弦大而伏。朱氏谓多年郁结一旦泄之徒引猖狂之势，随用吐剂，更以朴硝、滑石、芩、石膏等清泄，正合脉伏弦大所示郁结壅遏之机。", ["弦", "大", "伏"]], "3828": ["病机", "六脉弦数，弦主痛、主气滞，数主热。怒后食鱼、硬物压骨伤胃脘，瘀血停蓄膈间，食管被逼在背后，故饮食从背后而下、胸膈胀痛、恶寒发热。弦数为瘀热内郁之征，孙氏据此断为瘀血而非骨哽未下，用五灵脂为君消瘀，佐以山楂、延胡、桃仁等，使瘀去食管复元，饮食乃从右边而下。", ["弦", "数"]], "3829": ["病机", "两寸脉洪大，两尺沉微，寸洪大主上焦热盛、气火上逆，尺沉微主下元不足。胃脘痛、两胁胀急、汗出、两颧唇口皆红、饮之立吐，为热郁于上、胃气上逆；尺沉微示下虚。孙氏用阴阳汤调元明粉通下泄热，痛减便行，后断有虫，以乌梅、川椒等安虫，皆从寸洪尺微之脉辨上热下虚、虫扰之机。", ["洪", "大", "沉", "微"]], "3830": ["病机", "脉洪大而涩，洪大为热盛气浮，涩主血行不畅、瘀滞。膈痛而脉洪大涩，王金坛先用山栀、赤曲、通草、麦芽、香附、芎归加韭汁、童便、竹沥行血通气而止，是治其瘀热；后劳倦忍饥痛大发，服二陈平胃等如刀割，知为虚，改十全大补一剂而痊。同一洪大涩脉，先实后虚，凭脉与因合参。", ["洪", "大", "涩"]], "3831": ["其他", "此段为震按总评，未出具体脉名，纯论凭脉辨证之法。李公二案一峻下一大补，皆以脉为凭；王公一案先用行血通气、后用十全大补，先凭于脉、后凭于因。震按赞丹溪以脉因证治名书，扼其要而病无遁情，强调脉与因证合参，不可偏执一端，故列其他类。", []], "3832": ["其他", "原文未载脉象，仅述右胁胀痛至中脘、吞酸吐水、肢冷等症，属肝胃虚寒、气滞湿阻。震按以二陈汤加香附、白芍、苍术、良姜等温中理气化湿，服之颇效，但易复发。后改用升阳益胃汤，得力于东垣，惜不载脉象，难以凭脉辨治。", []], "3833": ["病机", "六脉弦数，弦主肝郁，数主火郁。病起郁结生火，阴血受伤，肝肾枯干，燥迫成痛，故胃脘痛而勺水不入、寒热往来。前医误投苦寒辛热，胃脘重伤。高鼓峰断为肝痛非胃脘，以滋肾生肝饮急救，弦数脉示郁火伤阴之机。", ["弦", "数"]], "3834": ["病机", "六脉弦数，弦为肝郁，数为火郁。江应宿治心脾痛，断为火郁，投姜汁炒黄连、山栀泻火，川芎、香附开郁，陈皮、枳壳顺气，反佐炮姜从治，一服而愈。此案脉同治异，与前案滋肾生肝法可合参，示弦数脉主郁火之病机。", ["弦", "数"]], "3835": ["病机", "脉沉弦细实，重取如循刀责责然，沉主里，弦主痛，细实主积。因寒湿入腹，瘀血内结，故小腹痛甚、大汗。丹溪以大承气加桂下之，瘀下痛止，脉仍责责然，加附子温下，终以脉和用小建中汤收功。脉象反映寒瘀结实之病机。", ["沉", "弦", "细", "实"]], "3836": ["其他", "原文未直接列脉，但述“脉如循刀责责”“指下认得真”，强调脉诊关键。震按赞丹溪凭脉断寒瘀结实，攻补有序；若认脉不清，必致两误。此段以脉象辨识真伪，非真脏脉，乃寒瘀实邪之脉，故温下得效。", []], "3837": ["病机", "六脉沉伏而实，沉伏主里，实主邪结。壮年寒月入水，饥食冷粥，大寒直中下焦，燥矢内结，故腹大痛、面青黑。前医误下寒药，痛愈甚。虞天民断为大寒证，先温补艾灸，继以巴豆丸温下，沉伏实脉示寒结深重之病机。", ["沉", "伏", "实"]], "3838": ["病机", "六脉沉伏，两尺绝无，沉伏主里，尺绝非死血，乃结粪下焦作痛。前医作死血治不效，虞天民以稻藁灰汁合枳实导滞丸催下黑粪而痛止。脉沉伏而尺绝，示燥屎内结、气机壅塞之病机，非瘀血之涩脉。", ["沉", "伏"]], "3839": ["病机", "震按尺脉沉实主下焦结粪，今两尺绝无亦断结粪，见取脉之巧。若死血则脉必涩，前案已载。此段强调沉实与涩脉之别：沉实主燥屎，涩主瘀血。脉象虽异，辨病机关键在脉理圆通，非执一途。", ["沉", "实", "涩"]], "3840": ["病机", "脉浮细而结，浮为虚阳外浮，细为阴血不足，结为气血涩滞。原文以止脉疏密辨热之进退：止脉疏而痛甚，是热动脉速；止脉频而反轻，是热退脉迟。故断为阴虚火动，起于劳欲，劳伤心火、欲伤肾水，与午后血滞阴分之痛相应。", ["浮", "细", "结", "迟"]], "3841": ["病机", "脉皆微弱，似有似无，或一二至一止，或三五至一止，是阳气大虚、鼓动无力之象。原文谓四肢为诸阳之末、头为诸阳之会，阳虚则阴乘而恶寒，故指冷从头面起而腹大痛；阳衰不能温运，故过食不食皆痛。独参补阳而愈，正合此机。", ["微", "弱"]], "3842": ["其他", "此段为震按语，未载具体脉象，只就上条大冷后发大热而用参不用附加以评说，认为宜补不宜温，提示学者体会寒热虚实之辨。因原文无脉名可录，脉象要素从缺，主旨属临证议论而非脉诊主病。", []], "3843": ["病机", "脉皆细快，右大于左，脾脉弦而且滑，右脉亦细数。细为阴伤，数为热，弦滑主痰饮食积。原文谓素好酒色犬肉，酒食房劳交伤，故腹痛日夜叫号、汗出食阻。弦滑见于脾部，正示酒肉痰积滞于中焦，细数则示郁热伤阴，与连下后脉隐肢冷相应。", ["细", "弦", "滑", "数"]], "3844": ["其他", "此段为震按，评述前案反复用药、寒热互用而终以补收功，指出身不热、神不昏故与伤寒温疫有别；连下致虚极则逆冷脉绝，通脉四逆非误而白虎殊误。原文未出具体脉名，故脉象要素从缺，主旨属治法得失之论。", []], "3845": ["病机", "六脉弦长劲急，两畔别有细脉沸然如烂绵。弦长劲急主实邪壅滞、气逆上攻，故冷气满腹、大痛拥上而吐冷涎；细脉状如烂绵，是痰浊胶结、脉道不利之象。原文断为胸膈有臭痰，投滚痰丸吐黑绿冷涎而愈，正合弦劲主实、细绵主痰之机。", ["弦", "长", "细", "急"]], "3846": ["其他", "此段为震按，评王隐君治病不曰痰即曰火，可承戴人之法；并指出腹痛因痰确有之，此种脉象更要留心。原文未列具体脉名，仅提示弦长劲急兼细脉之痰证脉象须细辨，故脉象要素从缺，主旨属临证评述。", []], "3847": ["病机", "震按立斋治腹痛兼胸胁作胀、呕吐吞酸、手足厥冷，皆谓肝木乘脾，其载脉皆曰弦紧、弦长或弦洪、弦数。弦为肝旺，紧主寒痛，长为气逆，洪数为郁热，合示肝木横逆、乘克脾土之机，故用参、术补脾以御肝，佐左金、香砂之类。", ["弦", "紧", "长", "洪"]], "3848": ["病机", "脉仅四至，重按伏而有力，乃攻克太过、寒凉伤脾，脾虚中气不运，积反凝滞。脉伏为气血郁滞，有力为积滞未消，故虽泻而痛不减。脾虚中气不足，故手足清冷、形神俱倦。治当建立中气，中气一回则痛止。", ["伏", "数"]], "3849": ["主病", "六脉皆洪数，面色苍黑，皮肤燥若老松树皮，左脚不可动，动即痛应于心，此肠痈之征。洪数为热毒壅盛，气血瘀滞，故痛剧而脉洪数。非死候，治以营卫返魂汤加金银花清热解毒、活血消痈。", ["洪", "数"]], "3850": ["病机", "两寸关俱伏，独两尺实大，按之愈甚。起自暴怒，风木郁于地中，肝气郁滞，故寸关伏；郁于下焦，故尺实大。投升散之品，嗳气数十声而痛立已，已而作喘，乃升之太骤，以四磨饮降气遂平。", ["伏", "实", "大"]], "3851": ["病机", "露宿寒湿，腰痛不能转侧，胁搐急，作痛月余。此足太阳、少阴血络有凝血作痛，间有少阳外络脉病。寒湿凝滞，血络不通，故痛。冬三月禁针，只宜服药通经络、破血络中败血，以活血温经之剂酒煎服愈。", []], "3852": ["病机", "坠马腰疼，六脉散大，重取则弦小而长稍坚。散大为元气外散，弦小长为瘀血内结。年六十余，恶血虽有未可驱逐，先以补接，散大渐敛，食进，后以熟大黄汤调下自然铜等逐瘀，一月而安。", ["散", "大", "弦", "小"]], "3853": ["病机", "脉之散大，为元气虚散之象。跌伤有瘀，似宜先逐瘀，然年老祖脉散大，反先补而后逐瘀。元气果虚，则补药惟元气受之，而或邪或瘀不相干涉；若元气不虚，则补药为邪助长。要在辨其虚与不虚耳。", ["散", "大"]], "3854": ["病机", "脉伏于下，极重按之振指有力，乃阳证似阴，火热过极，反兼胜己之化。火郁于内，故脉伏；实热内结，故重按有力。小便当赤，必畏沸汤，询之果然。以苦寒直折，加生姜向导，乘热顿饮，三剂痛失。", ["伏"]], "3855": ["病机", "脉洪滑而小水不通，乃湿热壅盛，下焦气化不利。洪滑为湿热内蕴，小水不通则湿无出路，腰痛由是而作。治用大分清饮倍加黄柏、胆草，清利湿热，小水通而腰痛顿止。", ["洪", "滑"]], "3856": ["病机", "原文未明言脉象，仅推测“于脉中见相火之强”。瘀血腰痛本有行瘀治法，然行房时肾摇血即不瘀，说明肾虚可致瘀滞。用知、柏而非肉桂，正是因脉中察得相火亢盛，故以清相火为治，反证病机为肾虚火旺兼瘀。", []], "3857": ["主病", "左脉弦细、右脉滑大俱六至，弦细为阴虚血少，滑大为湿热壅盛。患者疟后气血不足，旧毒（杨梅疮余毒）伏于经络，因虚而发，故腰痛暴作、白浊咳嗽。脉象示正虚邪实，毒热内蕴，故用土茯苓等解毒通络而效。", ["弦", "细", "滑", "大"]], "3858": ["预后", "脉亦平顺而痛反大减，喻氏以为可忧。盖痛如刀刺乃邪正互争之象，脉平痛减则邪正混为一家，正气全虚而邪深入腰，血脉久闭。脉平顺非佳兆，反示攻邪无力，故用桃仁承气加桂附温通攻散，仿附子泻心汤法。", ["平"]], "3859": ["病机", "脉皆缓弱无力，为脾虚气弱之象；左脉滑者，血热也。患者行房多汗、晚浴近色，致白浊、目痛、口苦、膝肿、背痛，皆脾虚湿停、血热内蕴所致。缓弱主脾虚，滑主血热，故治以参、芪、苓、术补脾益气，佐黄柏清血热。", ["缓", "弱", "滑"]], "3860": ["治法", "暴痛背痛当辨脉：浮紧为伤寒，寒邪束表，太阳经气不利；沉缓为寒湿，湿邪留着，阳气不布。故麻黄汤、羌活胜湿汤可酌用。此以脉之浮沉紧缓分伤寒与寒湿，示背痛暴痛之治法，久痛则分阴虚阳虚，各求其因。", ["浮", "紧", "沉", "缓"]], "3861": ["主病", "两手俱沉实而有力，沉主里，实主邪积。患者冷饮数升，左胁下闷痛结硬如石，乃酒湿寒饮积于胁下成块。脉沉实有力，证明积块为实邪，非虚证，故戴人以独圣散涌吐积饮，痛止后和脾安胃而愈。", ["沉", "实"]], "3862": ["主病", "左寸尺弦数而涩，关脉芤而急数，右三部数而虚。弦数主热，涩主血瘀，芤主血虚，急数主瘀热内迫。跌扑后左胁胀痛，脉见芤涩急数，明是死血证，瘀血内结而血虚，故用抵当丸下黑血，后以四物汤调理。", ["弦", "数", "涩", "芤"]], "3863": ["主病", "两关脉促，促主阳盛热结、气血瘀滞。患者左胁痛不可近，渐大右胁亦痛，神气如痴，面色黄，乃蓄血已深，瘀热内结。脉促证实为瘀血内蓄，非虚证，故用桃仁承气汤加干漆、大黄峻下血块，遂痛止神清。", ["促"]], "3864": ["病机", "脉洪大无伦，按之微细，是外显假实、内本真虚。洪大无伦为肝脾血虚、阳气浮越之象，按之微细则根本不足。原文谓“此属肝脾二经血虚”，故虽见狂言热炽、胸胁胀痛，乃血虚发热、肝脾失养，非实火可攻。若用疏通之剂，则犯虚虚之戒，脉证合参，当以补益为要。", ["洪", "大", "微", "细"]], "3865": ["病机", "初诊脉弦濡而弱，弦为肝木乘脾，濡弱为脾胃气血受伤，故胁痛虽减而中气未复，以橘皮枳术丸加黄连、当归调之。越五年复痛，脉皆濡弱而缓，缓属脾虚，濡弱为气血两亏，故断为虚证，非前属实可比。原文“前病属实，今病属虚”，脉由弦濡弱转为濡弱而缓，正示病机由实转虚。", ["弦", "濡", "弱", "缓"]], "3866": ["病机", "震按指出先后脉皆濡弱，惟弦与缓不同。弦而濡弱，非纯肝火，乃郁怒伤肝脾、土虚木贼之象；右关弦长按之软弱，左关弦洪按之涩滞，皆弦中带虚。原文“弦脉又不得尽责之肝火”，说明弦脉主郁主痛，兼濡弱则属脾虚肝郁，故用六君加芎、归而愈，不可一味清肝。", ["弦", "长", "濡", "弱"]], "3867": ["病机", "脉七至而弦，数则为热，弦则为痛为肝。患者受热过劳、性躁，左胁痛发水泡疮，夜重于昼，医作肝经郁火治而反剧，红及半身、水泡增至百数。此非寻常肝火，乃热毒壅滞、肝经郁结，弦数脉示热盛而痛急。古潭用大栝蒌、甘草、红花，从痰热瘀毒论治，痛势急而脉弦数，正合“痛则不通”之机。", ["数", "弦"]], "3868": ["病机", "左脉弦数，右关洪滑。弦数为肝胆热盛，洪滑为痰火壅盛。患者经行后发病，胸胁大腹作痛、谵语如狂、午后夜剧，显系热入血室、痰火交作。原文“误服刚燥之剂而动痰火，以致标本交作”，弦数洪滑正示肝胆火炽、痰热内扰，故虽似热入血室，实兼痰火为患，非独血室证。", ["弦", "数", "洪", "滑"]], "3869": ["病机", "原文“脉罔辨”，即脉象模糊难辨，故不取脉象要素。徐可豫据膝肿痛、左右攻冲、雷鸣上胸、面黛色等症，断为“湿淫所中，继复惊伤胆”。湿邪流注关节则肿痛，惊伤胆则气逆面青，脉虽难辨而症候可凭，涌吐青白涎沫后病减，说明湿痰惊郁为病机关键。", []], "3870": ["病机", "六脉沉缓，原文自释“沉为里有湿，缓为厥为风”，故断为风湿毒，俗名湿脚气。沉主里，缓主湿与风，湿毒下注则两足如柱、溃黄水，逾月乃已而复发。脉沉缓与足肿溃水相应，示湿邪深伏、风气内动，故用神芎丸、舟车神佑丸大下浊水，从里逐湿。", ["沉", "缓"]], "3871": ["病机", "三部皆大，搏手如葱管无力，大而中空无力，是精血不足、湿热壅盛之象。患者身半以上肥盛，膏粱妾御、嗜欲无穷，精血亏于下，湿热盛于上，故足酸重肿痛。原文“益精血于其下，清湿热于其上”，脉大无力正示本虚标实，脚气不可概用泻法，虚实之辨至关重要。", ["大"]], "3872": ["主病", "脉紧主寒主痛。妇人脚患筋挛骨痛，诸药不应而脉紧，说明寒邪凝滞筋脉、气血不通，故见挛急疼痛。紧脉如转索无常，为寒邪收引之象，寒性收引则筋脉拘急，气血涩滞则骨节作痛。用大防风汤温散寒邪、舒筋活络，二剂顿退，正合紧脉主寒之病机。", ["紧"]], "3873": ["病机", "脉沉细而涩，沉主里、细主虚、涩主血少，说明下焦元气不足、不能荣养筋骨，故足胫痛三年。再诊脉兼浮数，浮为虚阳外浮、数为元气愈耗之象，故曰元气愈耗。此脉由沉细涩转为浮数，反映虚损加重、阴不敛阳，与滋补后因劳复作相应。", ["沉", "细", "涩", "浮"]], "3874": ["病机", "脉洪大而有力，洪大为阳明气盛、数为热，有力为实。患者体肥盛、素膏粱，积热于胃，阳明多血多气，本实则风热上行，诸阳会于头，故头目昏闷、面赤热。洪大有力正合阳明经气盛有余之实热病机，故先以调胃承气疏利撤其本热。", ["洪", "大", "数"]], "3875": ["病机", "脉弦细而微，细为气血不足、微为阳气衰微，弦为经络拘急。僧年高体瘠、食素诵经损气，胃气虚则经络之气亦虚，不能上达头面，故头面不耐寒、恶风。此脉说明阳明经本虚、中气不足，与文中“气不足则身以前皆寒栗”相应，故用附子理中温中、升麻汤加附行经。", ["弦", "细", "微"]], "3876": ["病机", "本段未识脉名，以证论病机。忧思不已、饮食失节，脾胃气结不行、气耗不足，传化失职则四脏失养。阴气上溢于阳中，故面色黧黑不泽、环唇尤甚；水反侮土，黑色见于唇。心悬如饥、饥不欲食、气短而促，皆脾胃气伤、冲和失运之候，属阴阳相反之逆证。", []], "3877": ["病机", "脉洪数，尺脉为甚。洪数为热，尺部候肾肝，尺甚说明热在下焦肝肾。患者耳内出水作痛年余，属肝肾二经虚热，虚热上扰耳窍则出水作痛。洪数虽似实热，但久病年余、尺甚，结合用加减地黄丸料一剂而愈，可知为阴虚内热之病机，非实火。", ["洪", "数"]], "3878": ["病机", "此段论尺脉辨虚实用药。尺脉必微弱或虚大，为肾阳不足、虚阳无根，故用加减八味丸加温药导纳浮阳；若尺脉洪数，则为肾阴亏虚、相火偏旺，宜知柏地黄丸滋阴降火。同一耳病，尺脉微弱与洪数反映肾虚之阴阳偏衰不同，故温补与清滋异治。", ["微", "弱", "洪", "数"]], "3879": ["病机", "左手心脉浮小而快，肝肾沉小而快，右脉皆虚散而数。浮小为气血不足，数为有热，虚散为正气耗散。汪氏虑其乘舆远来脉未定，来早脉稍敛、不及五至，说明前数乃暂象。久服祛风去热逐痰燥剂，少血之经更燥，血愈虚少则涩滞壅肿，郁而化热腐肉成脓，故耳肿溃脓、右耳亦聋。", ["浮", "小", "数", "虚"]], "3880": ["其他", "原文为汪公议论之按语，强调“脉未定”时不可凭脉断病，属诊法注意事项。文中“不足凭之说”指初诊时脉象未稳定，不可据以辨证，非论具体病机，故无脉象要素可录。", []], "3881": ["主病", "脉数滑主湿热内蕴。数主热，滑主痰湿，湿热痰浊上扰清窍，故耳鸣重听；人事烦冗亦助心火。江氏以二陈加瞿麦、萹蓄、木通、黄柏清利湿热，一服知，二服已，证明脉数滑所主为湿热实证。", ["数", "滑"]], "3882": ["其他", "原文引王万里耳痛案，魏氏谓“恐则伤肾”，而用药阴阳各别，强调“要当以脉辨之”。此段未出具体脉象，主旨在于脉诊可辨耳痛之阴阳虚实，非论某脉主某病，故脉象要素为空。", []], "3883": ["病机", "右寸浮洪带结，余部沉细而软。浮洪为热郁于上，结为气滞血瘀；沉细软为气血两伤。苦寒驱风败血久服，伤气伤血，故倦怠、目不欲开。脉象反映虚其虚之误，治宜化滞血、生新血。", ["浮", "洪", "结", "细"]], "3884": ["病机", "脉微弦而涩，轻重皆同。弦主气郁湿痰，涩主血少瘀滞。厚味成熟，湿痰在膈，复食酸梅，湿热痰随上升之气至头，熏蒸发根之血，故发脱。脉象示湿热痰瘀阻络、血枯不荣之病机。", ["弦", "涩"]], "3885": ["病机", "脉数主血热生风。发乃血之余，忽然脱落，头皮痒须眉亦落，乃血热生风、风摇木落之象，酒客膏粱多此。数脉为热，热极生风，风动则发落，故用通圣散宣泄风热，次以六味地黄丸滋水制火。", ["数"]], "3886": ["病机", "原文未出脉象，而论瞳子散大之病机：多食辛热，辛主散，热助火，上乘于脑，精散则视物散大。壮火食气，火与气不两立。此段以病机推演为主，非凭脉断证，故脉象要素为空。", []], "3887": ["病机", "原文未出脉象，而谓“诸脉皆属于目，脉病则目从之”。目翳暴生，从下而起，色绿，东垣断为肾肺合病，泻肾肺之邪入阳明。此段强调经络不调则目病不已，当视所不调者治之，属病机分析。", []], "3888": ["其他", "原文未载具体脉名，仅引“诸脉皆属于目”经文，强调目病当参脉象以辨脏腑失调。震按辨翳色巧而复发三次，翳色各异，合脉皆属目之经旨，虽不载方药，而云“视所不调者治之”，示人凭脉察色以意会调治，非专主一病机。", []], "3889": ["病机", "六脉弦细而无力，为脾胃虚衰、气血不荣之象。年近七十，胆汁减而目不明，唇黑肤槁，皆土虚不能营运荣卫。罗谦甫谓苦寒泻土则脾胃愈虚，故戒服黄连诸风药；宜慎言语、节饮食以保胃气。后脉亦和平，正不妄服寒药之效。", ["弦", "细", "虚"]], "3890": ["病机", "脉缓大四至之上，重按散而无力，缓大为湿盛，散而无力为气虚。壮年忽视物不见，食减倦甚，询知卧湿地半月，湿伤脾阳，清阳不升则目暗。故以白术为君，耆、苓、陈为臣，附子为使，温运脾阳、化湿升清，十余帖愈。", ["缓", "大", "散"]], "3891": ["病机", "脉涩为血行滞涩之征。形实好热酒，酒热伤胃，胃气污浊，血死其中，瘀阻目络，故忽目盲。朱氏以苏木汤调人参末行血益气，服后鼻掌紫黑，知滞血已行，继以四物加苏木、桃仁、红花、陈皮调人参末，数日而愈。", ["涩"]], "3892": ["病机", "左关浮促，余部无恙，左关候肝胆，浮促为气逆上焦、胆府倒置之象。因大醉尽吐，上焦反复，致倒其胆府，故视物倒植。吕氏断为不内外因致内伤，法当复吐以正胆府，用藜芦、瓜蒂涌之，涌毕视物不复倒植。", ["浮", "促"]], "3893": ["其他", "原文未载脉象，仅言“既诊脉后”施以醉饮展转之法。富翁子视正为斜，因醉中闪倒肝叶搭肺，令复饮至醉，肺胀展转，肺叶垂下而愈。此案不凭脉断病，示人内伤跌仆致脏腑移位，非药所能治，当以法复其位。", []], "3894": ["病机", "肝脉弦滑，弦为肝旺，滑为血盛，非壅热也。孙真人诊乳妇眼疼，众医或寒或补致脏腑不和，真人据肝藏血、脉弦滑知血盛不通，问得月经三月不行，用通经药经行而愈。此脉主肝血壅盛、经闭目疼。", ["弦", "滑"]], "3895": ["病机", "震按肝脉弦滑，易误作风痰病眼，因肝藏血而知血盛不通，切当。然真人犹问宫人停经三月之信，不先据脉断经，示人脉证合参。此段重申弦滑主肝血壅盛，非风痰，临证当问明经候，勿讳疾困医。", ["弦", "滑"]], "3896": ["病机", "脉皆细弱，脾部尤近弦弱，细弱为气血不足，弦弱见于脾部则示脾虚而肝木乘之。脾虚则五脏六腑精气失司，不能上贯于目，故两眼昏昧；清阳不升、邪乘虚入眼系上脑，故脑鸣头痛；劳役动相火侮所胜，故咳嗽恶心。此脉主脾虚为本、目病为标。", ["细", "弱", "弦"]], "3897": ["病机", "脉大而虚，大为劳心过度、百脉沸腾之象，虚为脾胃亏损、气血不充之征。因饮食失节、心烦事冗，脾虚则五脏精气失所，不能走于目而为精、走于耳而为听，故目赤不明、畏明重听。此脉主脾胃亏损、心火太甚而邪害孔窍，故以补中益气、十全大补纯补取效。", ["大", "虚"]], "3898": ["其他", "此段为震按语，未出脉象，专论汪、薛二案皆治脾虚而目愈，说明诊脉得要领则治脾即所以治目。汪案脉细弱弦而兼咳嗽头痛，故佐麦冬、贝母、川芎、黄芩、菊花以带一二分客邪；薛案脉大而虚且曾服祛风散热，故纯补兼酸收。二案凭脉分虚实兼夹，故用药有佐散与纯补之别。", []], "3899": ["病机", "两寸关脉俱滑大有力，两尺沉微。滑大有力主中焦痰盛、肝胆火旺，故眼赤肿痛、白泡突生、呕吐眩晕；尺沉微示下元不足，火乘于络上而不行。原文谓诸风掉眩皆属肝木、诸逆冲上皆属于火，无痰不能运，故断为中焦有痰、肝胆有火，为怒气所触而然。", ["滑", "大", "沉", "微"]], "3900": ["病机", "震按提出假设之脉：脉若弦大而且数，弦为肝木、大为火盛、数为热急，合目肿痛而赤、口渴内热，则属肝火上逆、木寡于畏之实热证。原文以此反衬独参汤之用，警示若见此脉此症而投补，恐痛之丧明，说明脉症合参方能辨虚实、定治法。", ["弦", "大", "数"]], "3901": ["病机", "此段未出脉名，石顽据症断为水亏而阴火用事。服祛风清热药过多，耗伤阴精，真水内涸不能泛滥其光，故视灯火大如斗、视月光小如萤，兼耳鸣嘈嘈、大便燥结。以眼镜铅料轻重为喻，说明阴精亏虚、阴阳偏胜失调之病机，主眼疾属虚。", []], "3902": ["病机", "脉浮数，按之沉细而弦。浮数为表热上攻，故咽嗌疼痛、耳前后赤肿、舌本强、涎唾稠黏；沉细而弦为里虚，故下利清谷、腹痛肠鸣。罗氏引仲景先救里后救表，谓胃气不守下利清谷虽急，比之咽嗌猛疽犹可少缓，示此脉主表里同病、虚实夹杂，治当分缓急。", ["浮", "数", "沉", "细"]], "3903": ["其他", "此段未出脉象，杨吉老明言不须看脉已知其病。患者喉间生痈溃脓、脓血流注不止，因官南方多食鹧鸪，此禽好啖半夏，积毒而发。先啖生姜片一斤，辛散解毒，脓血顿尽。说明喉痈有因食毒所致者，凭症即可断，不必拘于脉诊，属其他类辨治验案。", []], "3904": ["病机", "脉数而无力，数虽似热，无力则非实火，乃虚损阴亏、虚阳浮越之象。前医误用退热清火，更伤中阳，致大便溏泄，喉痛愈清愈甚，显系格阳于上。景岳以理阴煎、大补元煎温补收功，正合“数而无力”为虚火、为格阳之机，非实热可清。", ["数", "虚"]], "3905": ["病机", "脉细数微弱之甚，细为阴伤，数为虚阳，微弱则正气大衰。喉痹而头面浮大、咽肿声哑，似实热而脉反微弱，乃寒盛于下、格阳于上之危候。前服芩连知柏更伤阴逼阳，故景岳用镇阴煎引火归元，脉证合参，知非实火。", ["细", "数", "微", "弱"]], "3906": ["预后", "脉小而数、按之无力，小细为阴血不足，数为虚热，无力则中气亦弱。震按指出此案温补得效，然亦有投温补而不效者，即“阳证阴脉”之死候。脉小细数无力而见喉肿热痛之阳证，脉证相反，故预后凶险，不可概以温补活人。", ["小", "数", "细"]], "3907": ["病机", "原文“大肠之脉散舌下”，非指脉象散乱，乃言大肠经脉络散于舌下。舌下牵强、手大指次指不仁，为大肠血虚风热，循经上扰。薛立斋以逍遥散加槐角、秦艽养血疏风清热，紧扣“血虚风热”之机，非以脉散主病。", []], "3908": ["病机", "二尺洪数有力、愈按愈坚，洪数为火，坚为邪实，见于肾部，是心火乘肾、所不胜侮所胜。胃脉平和，故清胃无益；肾主骨，齿为骨余，火盛则齿长。易公以黄柏滋水泄火、青盐引经、升麻升散火邪，正合尺脉洪数坚之肾火病机。", ["洪", "数", "坚", "平"]], "3909": ["其他", "此段为震按评述，无脉象描述。其要在于“脉象诊得的真”而后运巧思，强调脉诊真确方能发无不中。清胃散泛用滋阴皆难应手，易公三味铨解分明；叶案取酸盐下降引火归肾，义各不同，皆示脉真则治巧。", []], "3910": ["误治", "原文未识脉名，述脾胃虚损之人目黄、便不调、气短怠惰，医以泻肝散下数行而增剧。东垣谓大黄、牵牛重虚胃肺，标实未去本愈虚，又值暑雨，黄证增剧。此段主在误下致虚，当于脾胃肺本脏泻外经湿热，清神益气汤主之。", []], "3911": ["病机", "脉浮而缓，浮为风，缓为痹；跗阳脉紧为伤脾。风寒相搏，谷气不消，浊气下流，小便不通，热流膀胱，身体尽黄，名曰谷疸。罗谦甫引《金匮》以脉释疸，浮缓紧三脉合见，正示风、湿、寒、热交杂伤脾之病机。", ["浮", "缓", "紧"]], "3912": ["病机", "脉紧细主湿温初起，寒湿困表；两寸脉短不及本位，示湿阻上焦，阳气不布。原文见“头痛、肢节疼、身重、胸满不食”，为湿温由表入里、误汗误下后湿热内蕴，致“身目俱黄、心下痞硬”，脉象反映湿浊壅滞、气机不畅之病机。", ["紧", "细", "短"]], "3913": ["主病", "左脉弦数，弦主肝胆，数主热，为湿热郁蒸肝胆之黄疸脉。右脉原不应指，重按隐隐，示脾虚湿困。原文“皮肤目睛皆黄、小溲赤、午后发热”，脉证合参，主湿热黄疸；后脉近弦，转为疟疾之象，故以疟治而愈。", ["弦", "数"]], "3914": ["病机", "右关脉杳然不见，非气血虚极，乃“怒则气并于肝”，肝气横逆，脾土受邪，中焦气机壅塞，脉道不通。原文“形色尫羸而神气安静”，说明非死候；关脉不见反映肝郁乘脾、脾有积滞，故“目中微带黄色”，终发黄疸。", []], "3915": ["预后", "此段以“关脉不见”为例，讨论黄疸预后。关脉不见示中焦气机壅滞，但“数剂而痊”，说明脉象虽怪，若元气实、能逐邪，仍可向愈。原文强调黄疸“半月一月内退尽则他病可治”，久黄不退者预后不良，脉象变化当结合病程判断。", []], "3916": ["病机", "左关浮盛，右口沉实，浮盛主风热外扰，沉实主酒食内积。原文“肩背上下患痒，屡以艾灼暂止复作”，为酒食滋味酿生湿热，郁于肌腠，风热与积滞相搏，故脉左浮右沉实。清热化食行滞，脉象即反映食积化热、外发肌肤之病机。", ["浮", "沉", "实"]], "3917": ["病机", "六脉俱数，左手三部细，右手三部微实。细为血虚，微为水不足，相火妄行；右寸实为热在肺分，右关微实为火在土分。原文“上身头面俱痒，刺痛起块”，脉象示血虚水亏、相火无制，火热郁于肺脾肌腠，故痒痛起块。", ["细", "微", "实", "数"]], "3918": ["病机", "六脉弦洪缓相合，按之无力，弦在其上，为风热下陷阴中，阳道不行。原文“闭目则浑身麻木，昼减夜甚”，开目则阳道行而麻退，说明麻木非风邪，乃气不行。脉弦洪缓而无力，反映风热内陷、阳气不布、痰湿阻滞之病机。", ["弦", "洪", "缓"]], "3919": ["病机", "左手洪大而有力，为邪热客于经络。原文“体热麻、股膝无力、妄喜笑、善饥、痰涎不利、舌强难言、声嗄”，皆火邪阳并于阳、热伤元气、心火盛、脾胃热、肺金衰之候。脉洪大有力，紧扣“热淫所胜”之病机，主火邪炽盛、流散周身。", ["洪", "大"]], "3920": ["病机", "六脉大而无力，大则为虚，无力为气血不足，故主气血皆损。气血不能充养四末，故两足麻木，渐至两手亦麻，左胁下不知痛痒，此即经所谓著痹。脉症合参，非痰非瘀，乃气血虚馁，卫行迟滞，故用神效黄耆汤、十全大补温补气血而安。", ["大", "虚"]], "3921": ["病机", "寸口脉大，两尺独涩，大为心火有余，涩为肾精不足。心肾不交，水泛为痰，上蒙清窍，故手足麻痹、目中睹一成两。脉大非实热，乃虚阳上浮；尺涩为根本亏虚，故取地黄丸料滋肾，倍泽泻、茯苓以渗痰浊，少佐青盐引药入肾，使水火既济而愈。", ["大", "涩"]], "3922": ["病机", "两尺脉涩，涩主精血亏少，肾脉不充，故先用地黄汤补肾填精。麻为气虚风痰，然此案尺涩为根，补肾后兼进参、耆，仍是治麻成法。震按指出病根在痰火者，则开眼则麻，与东垣所言合眼则阳气不行之麻木不同，讲得最好，示人辨脉求因。", ["涩"]], "3923": ["病机", "脉虚大而数，按之则散，举之应指，此心火浮散之象。因艰产受惊，痰饮乘虚袭入心包络，留伏膈上，故眩晕心悸、神魂离散、开眼则遍体麻木如在云雾。昼日烦躁，夜则安静，昼甚夜轻，明是上焦阳位痰火为病，与东垣合眼则阳气不行之麻木迥殊。", ["虚", "大", "数", "散"]], "3924": ["病机", "麻多在于手足，因四末道远气馁，卫行迟而难到。脉浮而软或大而弱，为气虚；脉浮而滑，按之不衰，为风痰。若麻木兼作，则有寒湿积痰死血之殊，其脉有沉迟滑实与沉涩而芤之分。此段以脉辨麻之病因，示人详辨气虚、风痰、寒湿、死血之异。", ["浮", "软", "滑", "芤"]], "3925": ["病机", "六脉弦甚，按之洪大有力，弦为风寒外束，洪大为内有实热。冬时风气暴至，风寒伤于四肢脾土，故手挛急；素饮酒内有实热乘于肠胃，故大便秘涩、面赤热。外则足太阴脾经受风寒，内则手足阳明受邪，寒则筋挛，正谓此也。", ["弦", "洪", "大"]], "3926": ["病机", "脉涩而数，右甚于左，涩主血虚，数主有热，右甚则病在气分。贫劳之人，秋深发热，手足疼如煅，昼轻夜重，形瘦如削，乃血虚有热之热痹。服风药愈痛，气药不效，因风药燥血，气药耗气。后因多服麻黄，虚阳上升而喘，以酸收补血镇坠，数脉减大半而涩如旧。", ["涩", "数"]], "3927": ["病机", "震按身发热、疼如煅、脉涩而数、右甚于左，应属血虚有热，即热痹证，宜生地、龟板、黄柏等清热养血。苍术、附子、麻黄皆非所宜，麻黄五分太过，致虚阳上升而喘。议酸收是矣，遽用人参二钱恐痹痛转增，或脉数无力耶？则前之麻黄已误，后之桃仁、槟榔义又何居。", ["涩", "数", "大"]], "3928": ["病机", "脉弦而数，弦主肝胆，数主火。重取左豁大于右，左脉候肝胆，火郁于胆经。原文谓“小肠火乘胆木，子来乘母，是为实邪”，故痛从背胛小肠经起，延及胸胁胆经。弦数为实火之象，与谋事不遂、思虑伤心之因相应，主小肠火郁乘胆之实邪病机。", ["弦", "数"]], "3929": ["病机", "脉弦大颇实，寸涩甚，大率皆数。弦主木，大实主邪盛，数主热，寸涩主上焦气滞。原文断为“饮食痰积在太阴阳明”，厚味多怒致湿热痰积壅于脾胃，流注髀枢膝骭。脉实大数示邪实，寸涩示痰阻上焦，故痛处恶寒、昼静夜剧、膈痞食减，皆痰积化热之候。", ["弦", "大", "实", "涩"]], "3930": ["病机", "脉弦而数实，右为甚。弦主痛主经气不利，数实主热邪壅盛，右脉甚则病在气分、太阳经。原文作“痰热客太阳经”治，项强动则微痛，正是痰热阻遏太阳经脉、经气不舒之象。弦数实三象合见，说明痰热内壅、邪实于经，故以二陈加芩、羌、红花清化痰热而愈。", ["弦", "数", "实"]], "3931": ["病机", "脉沉弦而涩，沉主里、主水气，弦主痛主筋脉拘急，涩主血滞不通。背伛偻、足挛成废疾，乃寒湿痰瘀深伏筋骨、气血涩滞之候。沉弦涩示邪结在里、气血不畅，故以煨肾散吐下攻逐，使痰湿从上下分消，三四帖而愈，正合“脉沉弦而涩”所主之里实瘀滞病机。", ["沉", "弦", "涩"]], "3932": ["病机", "脉洪大，按之微细。洪大为热盛于外之假象，按之微细乃元气虚衰之本质。历节作痛、发热作渴、饮食少思、月经过期，诸药不应，正是虚阳外浮、气血不足之候。洪大无力、重按细微，说明本虚标热，故用附子八物温补而痛止，非实热可攻，此为脉证合参辨虚实之要。", ["洪", "大", "微", "细"]], "3933": ["病机", "身重脉缓，缓主湿、主脾虚。体胖内热、月经失调，湿与热合，流注下焦则下身微肿、小便频数，痹阻经络则痛风痛甚。原文断“证属风湿，而血虚有热”，脉缓正合湿邪困脾、阳气不运之机。故先以羌活胜湿汤祛风胜湿，继以清燥、逍遥、补中益气调补，脉缓为湿盛脾弱之征。", ["缓"]], "3934": ["病机", "脉浮细缓弱，按之无力，尺脉尤甚。浮缓为虚风外扰，细弱为血衰不足，尺候下焦，尺尤甚则肾肝精血亏虚。年逾五十，左脚膝挛痛不能履地、夜甚于昼，正是血衰不能濡养筋脉之候。原文断“病属血衰”，脉之细缓弱无力与血虚筋失所养相应，故以四物加牛膝、红花养血通络而安。", ["浮", "细", "缓", "弱"]], "3935": ["其他", "本段为震按评语，未出脉名，纯属议论。原文承前案“脉浮细缓弱、按之无力、尺脉尤甚”而言，谓“人尽知其宜补”，然又疑“病深药浅，岂能十余剂而安”，是对前案补法效验的评述。既无独立脉象，亦不主具体病机，故脉象要素为空，归入其他类，不作病机推断。", []], "3936": ["病机", "脉涩为气血滞涩、经络奇邪之象。原文谓“非十二经中正疾，乃经络奇邪”，因忧愁转抑、气机郁结，血行不畅，故脉涩；气血壅滞不通则筋骨百节皮肤无处不痛。涩非虚非寒，故补则气滞、散则气耗，主以清燥汤清润通络，正合涩脉所主郁滞络阻之机。", ["涩"]], "3937": ["病机", "寸口脉沉而滑，两尺弦，沉主水湿内停，滑主痰饮，弦主饮邪搏结。原文断为“溢饮湿痰”，因卧卑湿之地，湿邪浸渍，痰饮溢于经络四肢，故头目眩晕、寒热时作、历节疼痛。虽形瘦弱，脉非虚象，故不宜补，当汗吐逐饮，控涎丹取效。", ["沉", "滑", "弦"]], "3938": ["病机", "原文谓“筋脉为之引急”，脉象引急反映寒邪伤荣、筋脉拘挛之机。寒主收引，客于荣血，血涩不行，筋脉失濡而挛急，故遍体疼痛、尻髀皆肿、足膝挛急，即《内经》痛痹。脉急与症之挛急相应，治以乌药顺气散温通，加白术、桂枝而愈。", ["急"]], "3939": ["病机", "脉弦细而数，弦主痛、主筋急，细为阴血不足，数为有热。原文谓禀气弱、下虚伤阴，阴血虚则筋失养，气为寒束则百骸拘挛，荣卫不行故肢节肿痛而热，病名周痹。弦细数正合阴血亏虚、寒束热郁之机，故治当养血舒筋、流湿润燥，继以大补阴血。", ["弦", "细", "数"]], "3940": ["病机", "原文未识脉名，然诊得“六脉俱在，惟沉伏耳”，沉伏为邪闭气阻、痛极气机暂遏之象。患者湿痰凝滞经络作痛，服燥湿流动之剂后泻下稠痰，继而腹中大痛而厥、冷汗面青，手冷如冰，脉沉伏乃痛极使然，非脉绝，故知可治，与湿痰闭阻、气机一时不通之病机相应。", ["沉", "伏"]], "3941": ["病机", "左寸忽洪忽涩、迟数无定栖，脉象杂乱不定，反映寒热相搏、气血失调之机。原文谓好饮冷酒，酒性热燥而冷饮犯寒湿，寒热交争，故脉乍洪乍涩、乍迟乍数；寒湿搏结筋脉则腿疼筋缩、寸步不能行。脉无定栖正合寒热错杂之病机，故以川乌、麻黄、苍术温散取汗而愈。", ["洪", "涩", "迟", "数"]], "3942": ["病机", "脉沉细带数，沉细为阳虚阴弱、湿着于下，数为郁热。原文体厚色苍，膝热足冷、痛处肿、夜间痛甚、巅顶如芒刺、小便赤涩，乃阳气虚衰、寒湿痹阻而郁热于上。沉细数正合阳虚湿痹、虚热内郁之机，故用黄耆、术、附子温阳益气，佐独活、细辛、防己通痹。", ["沉", "细", "数"]], "3943": ["病机", "尺中微浮而细，尺候肾，浮为风雨外犯，细为肾虚不足。原文年高挛废，时当九夏而自膝至足寒冷如从水中出，知为肾虚风雨所犯。脉浮细正合肾虚夹外邪之机，故诸祛风通络药不效，八味丸亦不应，授安肾丸补肾而能步履，连服绝无痿弱之状。", ["浮", "细"]], "3944": ["主病", "脉沉数而有力，沉主里，数主热，有力为实，说明下焦湿热或相火亢盛。原文见脚膝痿弱、脐下尻臀冷、阴汗臊臭、精滑不固，此非虚寒，乃湿热郁遏、相火妄动，故以滋肾丸泻命门相火，寒因热用，引药下行。", ["沉", "数", "实"]], "3945": ["病机", "脉沉数有力，沉为病在里，数为热，有力为实，显系下焦湿热。原文阴汗臊臭、精滑不固，正是湿热下注、相火不藏之象；东垣谓泻相火之胜，即针对此病机。肾热则骨痿，故见脚膝痿弱，脉症相合。", ["沉", "数", "实"]], "3946": ["误治", "脉常沉涩，沉主里，涩主郁滞，形肥味厚多忧怒，气机郁滞可知。春病痰气，医误作虚寒，用燥热香窜之药，至夏两足弱、气上冲、食减，朱丹溪断为热郁脾虚、痿厥之证。脉沉非死脉，但药邪太盛，当火旺之令，终至大汗而死，书为误药之戒。", ["沉", "涩"]], "3947": ["预后", "震按气冲即喘逆，又食减、两足弱，显属下虚上盛之候。形肥而脉沉，未是死证，即平脉篇肥人责浮之义，谓脉非应死之脉，实死于药。此段以脉沉判断预后，强调脉证合参，非独凭脉断死生。", ["沉"]], "3948": ["病机", "脉洪大而虚濡，洪大为热盛，虚濡为气阴不足，此热盛伤津、湿阻之象。原文疟后久服桂附，积火燔炽，消谷善饥、目昏足弱、肌肉虚肥，伯仁断为痿证，乃长夏过服热药，火湿俱甚，肺热叶焦，故脉见洪大虚濡，主湿热成痿。", ["洪", "大", "虚", "濡"]], "3949": ["病机", "脉濡缓而弱，左脉较小或涩，尺脉尤弱，濡缓主湿，弱主气虚，尺弱主肾虚。原文久坐腰痛，渐延四肢不能行动，误作风治、血虚治而痛甚，汪石山断为痿证，谓诸痿起于肺热，湿重则筋缓痿软，热多则筋急作痛，脉症合参，知痿亦有痛。", ["濡", "缓", "弱", "涩"]], "3950": ["病机", "脉沉细而数，约有七至，沉细主里虚，数主热，七至为热盛。原文形肥色黑、素畏热好饮，病自汗如雨、四肢俱痿、恶寒、小便短赤、饮食减，汪机断为痿证，谓皆起于肺热，胃土亏则四肢不举，肺金伤则自汗如雨，脉沉细数正合郁热深而气阴伤之机。", ["沉", "细", "数"]], "3951": ["治法", "震按脉沉细而数，约有七至，郁热深矣。然痿本虚证，自汗如雨、饮食减少，肺胃愈虚，故不直清其热，而用清燥汤清补兼施，补土生金、益水制火以治本，连柏苦寒、苓泻淡渗以治标。脉沉细数示郁热，而虚象亦著，故治法审慎周到。", ["沉", "细", "数"]], "3952": ["病机", "脉洪数而有力，洪为火盛，数为热炽，有力为邪实，合参两腿痿软无力、劳则痛如针刺，知非外风，乃肝肾阴虚，邪火内盛，火性急迫故痛如锥，阴亏失养故痿软，脉症相合，故用壮水益肾而愈。", ["洪", "数", "实"]], "3953": ["病机", "震按此脉洪数有力，故主火盛邪实，宜壮水益肾；若脉数而无力，则数而无力为虚火，当用地黄汤合生脉散补血汤。下案虚象显然而误用风药，脉虚证实，误治必死，此以脉之有力无力辨虚实，定治法。", ["洪", "数", "实", "虚"]], "3954": ["预后", "六脉弦数，又既泄且痢，弦为木旺，数为热，脾传肾为贼邪，病极故断不出八月。内人寸关洪数、尺微欲绝，上实下虚，足三阳逆上，合悲哀胞络绝、数溲血、肌痹脉痿，知为痿证，病虽久可治，以脉辨预后。", ["弦", "数", "洪", "微"]], "3955": ["病机", "脉缓筋弛，缓为土气不足、约束无力，筋弛则关键尽撤，故身软目瞪不食。香极开窍，诸窍大开，脉缓筋弛，合土坎复生气、独取阳明之义，明脾主肌肉四肢，土虚则痿软。", ["缓"]], "3956": ["病机", "六脉有力，饮食如常，八年痿废而脉反有力，知非虚损，乃实热内蒸，心阳独亢，证名脉痿。故用承气下积滞，继以芩连大黄蜜丸清火，参汤送服，积滞尽而四肢展舒，脉实证实，攻下取效。", []], "3957": ["病机", "脉大而无力，大为劳，无力为虚，四年不能起于床，知营卫交虚，非实热。故用十全大补加秦艽、熟附，夕用八味丸加味，温补肝肾，三月机关利，脉虚证实，以补取效。", ["大"]], "3958": ["病机", "脉皆冲和，按之不甚虚，惟脾部重取涩而无力，涩为血少气滞，无力为虚，知土虚下陷，不能制水，湿坠下焦，故膝胫酸软。进补中益气倍升柴而愈，若用牛膝下行则愈陷，脉症合参，辨在脾部。", ["涩"]], "3959": ["病机", "震按前案以药对脉，总归取阳明。此论下虚上实，用犀角地黄汤加减，清营熄风，想其人脉必弦数，弦为肝风，数为热，热甚生风，故头目如蒙，入夏阳升为甚，脉弦数主热盛风动之机。", ["弦", "数"]], "3960": ["病机", "原文虽未明言脉名，但切脉循尺见“尺索刺粗而毛美奉发”，此为虫气之征。尺肤粗糙如刺，乃寒湿郁久化虫，虫积于腹，故腹大、上肤黄粗、循之戚戚然。虫气内扰，气血不畅，故脉象虽未详述，然由尺肤与毛发润美、色泽光泽，可知中藏无邪气及重病，病机在虫积而非外感寒热。", []], "3961": ["其他", "震按此条辨证最佳，强调“上肤黄粗”“循之戚戚然”“尺索刺粗”等枯燥之象，然仓公望毛发润美、面色光泽，知为虫病。原文未及具体脉象，仅言“不讲证，但讲脉”之条辞义古奥难明，故不敢录。此段主旨在于辨析虫病之证候与望诊，非论脉，故脉象要素为空。", []], "3962": ["其他", "此段述蛟龙瘕案，患者饮食如故，发则如癫，面色青黄，小腹胀满如妊孕，医诊其脉与证皆异而难明。原文未载具体脉象，仅言“脉与证皆异”，强调脉证不符，难以常规辨治。后得山叟识为蛟龙瘕，因食芹菜得之，服寒食饧吐蛟龙而愈。脉象要素缺如，主旨为异病奇治。", []], "3963": ["主病", "右关脉伏结，伏主气机郁闭，结主积滞内停。右关候脾胃，伏结并见，说明惊气入于脏腑，气机郁结，积于右胁，故右胁有声如虾蟆，常欲手按之。惊则气乱，气乱则积，积久成形，故脉诀以右关伏结为积病之脉，正当作积病治，用六神丹泄下青涎而瘥。", ["伏", "结"]], "3964": ["病机", "脉涩而小，涩如刀刮竹行，主血瘀气滞；小主脉道不利。戴人诊此，断为块病而非孕，因涩脉主丈夫伤精、女人败血。患者有孕岁半而屡发痛，实为瘀血内结，块阻胞宫，故脉涩小。治法当下，用舟车丸、承气汤等泻下青黄脓血，瘀去则病已。此脉说明瘀血内结之病机。", ["涩", "小"]], "3965": ["病机", "震按子和治积，脉象不曰沉细则曰沉迟，此条则曰小而涩。沉细迟涩皆主积滞内停、气血不畅。积在上者吐之，在下者下之，在中者兼用。然壮盛人无积，虚人则有之，洁古养正积自除之论最有见识。此段通过脉象说明积病多因虚而致，攻下须顾正气，不可妄施。", ["沉", "细", "迟", "涩"]], "3966": ["误治", "此段论倒仓法及三圣三花辈之弊，强调“六脉无力者，皆不可用”。六脉无力即虚损之脉，元气已亏，若妄用吐泻去积，则正气愈伤，往往杀人。原文未列具体脉象，但以“六脉无力”为禁忌之征，说明虚损劳瘵鼓胀反胃等真病已成时，脉无力者不可攻伐，否则误治致死。", []], "3967": ["病机", "六脉俱沉涩而小，按之不为弱，皆数，右甚。沉主里，涩主瘀滞，小主脉道收引，数主热。右甚则病在脾胃。患者好酒，暑途得疾，上脘有块如拳，牵引胁痛，乃酒热与暑湿互结，瘀滞中焦，故脉沉涩小数目右甚。大便如常、小便赤色，热郁于内。用大承气汤加减下之，块减证除。", ["沉", "涩", "小", "数"]], "3968": ["主病", "脉微而短涩，微为气弱，短涩为血少气滞，弦为肝郁。患者面白形瘦、性急、乳房下结块，乃肝郁气滞、血瘀成积，兼胃气不足。脉微短涩提示气血两虚，涩主血瘀，弦主气郁，故月经不来，结块渐长。", ["微", "短", "涩", "弦"]], "3969": ["主病", "脉虚微短涩，虚微为气血亏虚，短涩为血少瘀滞。妇人家贫多劳、性急，经断后小腹结块，腹渐肿胀，食减发热，乃劳伤气血，瘀血内结。左脉尤甚，左主血，故血瘀偏著。脉症合参，属正虚瘀结之候。", ["虚", "微", "短", "涩"]], "3970": ["病机", "脉皆涩，重按稍和，涩主血瘀，重按稍和示胃气尚存。块按则痛甚，经不行三月，小腹块如炊饼，乃瘀血内结。丹溪以涩脉断无孕，因孕脉当滑。药后脉稍虚豁，知攻药伤正，故改四物倍术以扶正，候脉充再攻。", ["涩", "虚"]], "3971": ["病机", "脉涩而弱，涩为血瘀，弱为气血不足。因经水过多，过用涩药，致败血不行，气滞血瘀，胸腹结块十三枚，遇夜痛甚。涩弱并见，示瘀血内停而正气已伤，故丹溪用活血化瘀兼扶正，缓缓下之。", ["涩", "弱"]], "3972": ["病机", "脉三部虽强，而细涩不流利，细为阴血不足，涩为血行不畅。患者体弱咳血，左胁块痛，似肝积而实为阴虚。细涩不流利乃阴血亏虚、脉络失养之象，故以四物加知、柏、元参、丹皮滋阴降火而愈。", ["细", "涩"]], "3973": ["其他", "震按总结前二条：一系饮积，以证与因断之；一系阴虚似肝积，以脉断之。强调诊积块当脉证合参，圆机活法，不可见块治块。本条无具体脉象描述，故脉象要素为空。", []], "3974": ["病机", "脉两尺洪盛，余俱微细。两尺候肾，洪盛为肾气传于膀胱，因破气药多，膀胱之气不能传前后二便而出，结为石块；余脉微细示他部气弱。此非血块，乃气结，故治当内收肾气、外散膀胱之气。", ["洪", "微", "细"]], "3975": ["病机", "两尺脉洪盛，喻嘉言释为肾气传于膀胱，因克伐太过，膀胱之气不能传前后二便而出，结为石块。震按此解紧切不泛，非通套治痞成法可比。脉洪盛主气结膀胱，非实热之洪，故以温补肾气为善后。", ["洪"]], "3976": ["主病", "脉浮大而长，浮主外候，大长主邪实壅盛，故断为脾有大积；两尺按之软，示下元尚虚，不可峻攻。攻积后脉转为大而虚，关部豁如，说明积去而脾气受损，故以补中益气调补收功。脉象由实转虚，正合积去正伤之机。", ["浮", "大", "长", "虚"]], "3977": ["病机", "震按指出脉浮大而长为脾有大积，与丹溪诸案之沉涩而小且数、微而短涩、虚微短涩、涩而弱者大不同。浮大长主积实壅盛，涩弱主气血滞虚，故须参合形色病情，不可执一脉以峻攻。两尺软为虚，然亦须灵变，不可概认作虚。", ["浮", "大", "长", "涩"]], "3978": ["病机", "脉大而数，大主邪壅，数主热，合腹痛呕涎、面色痿黄，断为虚而有湿、湿热相兼生虫。虫积内扰则腹痛嘈痛，湿热上泛则呕涎，脾虚湿郁则面黄。脉大数非纯实，故当以人参汤送槟黄丸，补虚与下虫并行。", ["大", "数"]], "3979": ["主病", "右关脉豁大，右关候脾胃，豁大主中焦气机壅滞、积块内结。左胁下有块，乃肝脾络脉瘀滞，故用乌药磨服行气，附子浓煎制其寒性，俟积行动再以补中益气加附子、六君子调补，示攻补兼施、以平为度。", ["大"]], "3980": ["治法", "脉弦而数，弦主积结气滞，数主郁热，然震按此段主旨在于论积不可峻下，当用消积药使之溶化，积去须大补。所举桃仁煎、黑神丸、五积丸等皆峻厉之品，妄试鲜不败事，故以脉弦数示积结有热，而治法重在消补迭进、适至病所。", ["弦", "数"]], "3981": ["病机", "原文未识脉名，然论前阴臊臭因连日饮酒、腹中不和，断为酒之湿热合风燥热客于下焦为邪。前阴为足厥阴肝脉络循之处，臭入肝为臊，故泻行间治本、泻少冲治标，以龙胆泻肝汤决前阴去湿热，体现下焦如渎、在下者引而竭之之旨。", []], "3982": ["病机", "原文未识脉名，专论肾间动气为人之根本，即命门真火，生长元气、煦燠元阴。动气禀于生初，厚则阳刚不痿，亏则早衰阳痿。壮年无病而阳痿多夭，少年虚损而阳痿死至，皆由动气早衰；若以兴阳药强求御女，反促其寿，故当任其自然、绝意淫欲以延龄。", []], "3983": ["主病", "尺脉洪数，尺候下焦，洪数主湿热壅盛。脱肛肿痛出水，其人好酒形实，故断为湿热下注，非气虚下陷。若气虚下陷则脉当虚软，今洪数有力，故用樗根白皮、川柏清湿热，诃子、没石子、鳖头灰收涩固脱，湿热去则脱肛自愈。", ["洪", "数"]], "3984": ["预后", "脉洪大而数，按之无力，左尺绝无，乃肾水不能制心火，虚阳外浮之象。冬见夏脉，非时之脉，提示根本已亏。洪数无力为假实真虚，火不归元，故痰涎上涌、日夜不寐、足膝逆冷。薛氏断其殁于夏，正合五行火旺之时，肾水枯竭，不能镇阳光，预后凶险。", ["洪", "大", "数"]], "3985": ["主病", "脉数而洪，数主热，洪主邪盛，见于感冒瘴气、寒热头疼、胸膈饱闷、眩晕恶心，乃瘴气外袭，邪正交争，热势鸱张之象。洪数为实，故用藿香正气散加厚朴、槟榔、羌、防、苏叶以解表化浊，一剂而寒热退，脉证相应，主病在表实。", ["数", "洪"]], "3986": ["主病", "脉弦而数，弦主痛、主气滞，数主热，见于头疼身痛发热、恶心饱闷，乃瘴气郁遏，表里俱实，气机不畅。弦为木旺，数为热盛，故用羌、防、芎、苏解表，藿、半、槟榔、苍、朴、橘、草化湿行气，二服而减，因饱胀未全退加草果、草豆蔻，知恶心饱胀为瘴气之异于感冒。", ["弦", "数"]], "3987": ["预后", "脉空数无根，如水上羹，刻刻欲脱，乃精气两虚、邪气正炽之候。空为虚，数为邪，无根则元气败散，神气散乱，寒热间作，补泻兼施无效。受病既深，正虚邪盛，法在不治，虽勉拟五积散加附子、人参，亦难挽回，预后不良。", ["空", "数"]], "3988": ["病机", "脉数无力，数主热，无力为虚，见于十龄童子感冒风暑，二十余日，神昏喘急，寒热间作，泄泻似痢，腹痛，虚汗不已。此外邪初感为药所解，久积未清，饮食失调，元气欲脱，故虚象显露。数而无力为元气亏虚、邪热未净，救本为急，用理中汤加桂、附，腹痛缓而泄泻减。", ["数", "无力"]], "3989": ["病机", "脉空豁，恍惚不定，重按无根，乃元气虚败、神不守舍之象。病已月余，夏秋暑湿风寒兼感，汗而不解，清痰退热亦不应，寒热更甚，咳嗽痰喘，胸膈饱闷，足冷恶寒。空豁无根为精气内夺，邪气未透，故先用五积散得汗如淋，咳嗽减而寒热未退，积久病深。", ["空", "豁"]], "3990": ["预后", "脉已细紧而数，细为阴伤，紧主邪结，数主热，见于似疟非疟、饮食不进，乃病深日久，精神殆尽，邪气深入而元气已竭。细紧数并见，为正虚邪盛、胃气已败之候，故曰虽病笃而元气尚在，今病已深，何药可施，旋毙，预后凶险。", ["细", "紧", "数"]], "3991": ["预后", "脉恍然不定，重按已绝，虽饮食尚可，乃邪火浮载、真精告竭之候，所谓行尸耳。似痢非痢，寒热间作，医以香、连、硝、黄消攻清理，日剧尫羸，又误进补，热亦不减。脉重按已绝为根本已败，邪火独浮，故辞之，阅二日而死，预后不良。", []], "3992": ["其他", "原文未出脉名，仅言“脉证茫然”，指感受瘴疠之气后症状模糊、脉象难辨。此类证候似风寒、似痢、似疟，实为地气时令之邪乘虚而入，虚弱者即发，敦厚者积久而成，故脉无定象，辨证困难，属难治之候。", []], "3993": ["病机", "原文未出具体脉象，但论瘴疠“必乘人本虚”而发。阳虚火衰者，瘴后转为虚寒腹胀泄泻；阴虚火旺者，瘴后现头晕发热便赤。此段强调脉证当参体质素常偏患，非单一脉象可定，故脉象要素为空。", []], "3994": ["病机", "脉寸滑大而弦，关尺皆弦大急，尺小于关，关小于寸，所谓前大后小。滑主痰饮，弦主痛、主水气，大急为邪实壅盛。经行先小腹大痛、吐涎水，乃痰水内结、气机壅滞，前大后小示病偏上焦，故用化痰行气破血之剂。", ["滑", "大", "弦", "急"]], "3995": ["病机", "原文以“脉弦大而数耶”推测病机。弦主肝郁，大主邪盛，数主热。初来血黑、后来血淡，本虚标热；来多倦怠食少，虚象显然。弦大而数示肝经郁热、血分有火，故虽虚而暂不宜纯补，当先清解。", ["弦", "大", "数"]], "3996": ["病机", "脉弦而大，不数。弦为肝气偏旺，大为形肥气弱之象。年十五经来多而倦怠，乃禀受弱、气不足摄血。脉弦大而不数，说明非热迫血行，而是气虚不能统摄，故用参、芪、术补气摄血。", ["弦", "大"]], "3997": ["病机", "脉辰时寸关滑有力，午后关滑寸否。滑主痰饮，有力主实。辰时气血注胃，胃满甚连及上焦，故寸关俱滑；午后仅关滑，独显胃实。痞塞不食、吐水、经停色黑，乃痰食湿热郁阻中焦、下则瘀阻，实证似虚。", ["滑", "有", "力"]], "3998": ["病机", "辰时寸关脉滑有力，午后惟关滑。滑为痰湿内壅，有力为实邪结聚。辰时气血注胃，胃中痰食积热壅盛，上连寸关；午后关滑独显胃实。痞塞吐水、经停色黑，乃内火食积郁成湿热，上饮停、下瘀阻，故主消痰消食破气活血。", ["滑", "有", "力"]], "3999": ["病机", "脉乍大乍小，非正常脉象，主祟病。面色乍赤乍白为愧，脉乍大乍小为祟，病因与色脉相符。腹大如娠而不月，实为鬼灵所凭、气血紊乱，故脉无定体，乍大乍小，以桃仁煎下血块而愈。", ["乍大乍小"]], "4000": ["其他", "原文未识别出脉名，仅言“病因与色脉符”，强调鬼胎之病须色脉相合以辨识。虽剧无苦，为鬼胎特征，脉象虽未明言，但色脉相符是诊断关键，故列其他类。", []], "4001": ["病机", "脉细濡近滑，两尺重按略洪而滑，细濡主湿，滑主热，洪为热盛。汪公断为血热，虽恶寒喜热，乃热极似寒。经水紫色、临行腹痛，皆血热瘀滞之象，故用黄连清热，佐香附、五灵脂行滞。", ["细", "濡", "滑", "洪"]], "4002": ["病机", "震按脉细濡近滑，两尺重按略洪而滑，不兼数，认为难辨大热。然汪公重用黄连而愈，说明细濡滑洪之脉，虽不数，亦可主血热。细濡为湿，滑洪为热，湿遏热伏，故脉不数而病热。", ["细", "濡", "滑", "洪"]], "4003": ["病机", "脉细软而快，尺沉弱近快。细软属湿，快为热，尺沉为郁滞。经行腹痛如刮，湿热郁滞胞宫，故脉见细软快而尺沉。汪公以黄连清热，香附、五灵脂行滞，久服得子，说明湿热郁滞为病机。", ["细", "软", "快", "沉"]], "4004": ["病机", "震按细软而数为湿热，洪滑无力为虚寒，此辨脉要旨。细软主湿，数主热，洪滑无力主虚寒。汪公前案用黄连，终嫌太过，久服不换非宜，提示湿热与虚寒须辨脉分明，不可过用苦寒。", ["细", "软", "数", "洪"]], "4005": ["病机", "脉皆濡弱，濡弱主脾虚湿盛。经行必泻三日，乃脾血先流注血海，脾虚不能运行其湿，故经行作泻。濡弱之脉，正合脾虚湿困，故用参苓白术散健脾渗湿，月余经行不泻。", ["濡", "弱"]], "4006": ["病机", "右脉浮软而大，左脉虚软而小近快。浮软大主气虚湿盛，虚软小近快主血虚有热。经水过多、白带时下、泄泻无时，下多亡阴，血虚湿滞，故脉见虚软。脚痛夜重，亦血虚失养之征。", ["浮", "软", "大", "虚"]], "4007": ["病机", "震按此案脉亦易认为虚，惟近快而合足之延痛，颇似湿热。虚软近快，虚为不足，快为热，湿热下注则足痛。然久泻复疟、经多带下，显系脾虚，参术对证，治法殊常实为辨脉精微。", ["虚", "软", "快"]], "4008": ["其他", "本案妇人两手脉皆不应，右关轻按隐隐微动，汪氏疑脉出部，寻按经渠列缺亦不应，后知为禀赋脉不应，孕时亦无脉。原文强调“此由禀赋本来脉不应也”，非病脉，故不主病机，属脉象变异之特例，提示诊脉不可拘泥常理。", []], "4009": ["其他", "震按一手无脉者多，两手无脉者少，乃襁褓时蹙锉经隧致脉不通，非病也。又述反关脉多洪大且可推动，不足以审病情。原文“反关脉多洪大”说明脉位变异，洪大非主实热，乃脉道改易所致，故列其他。", ["洪", "大"]], "4010": ["病机", "产后经行不止八月，面黄白头眩脚软，右脉濡弱无力，左脉略洪而快。汪曰“右脉弱者，非病也。左脉偏盛，遂觉右脉弱耳”，主左脉偏盛之热，故以凉血之剂取效。濡弱非虚，洪快为血热妄行之机。", ["濡", "弱", "洪", "数"]], "4011": ["病机", "震按右脉濡弱无力，汪公以左脉偏盛为主，曰“右脉弱非病”，因曾用参耆而病益加，故舍右取左，专主凉血。濡弱在此非脾虚之据，乃左脉偏盛映衬所致，提示脉象取舍须参病史。", ["濡", "弱"]], "4012": ["病机", "年逾三十无子，脉近和惟尺部洪滑，汪曰“子宫有热，血海不固也”，每行人道经水即来。尺部洪滑主下焦胞宫热盛，热扰血海则经水不固，故用大补丸加止涩之药清补兼施。", ["洪", "滑"]], "4013": ["病机", "妾证同前，两尺沉迟而涩，用补血散寒之剂不愈，后以蛇床子散外纳遂愈。尺脉沉迟涩主下焦虚寒、血行凝滞，寒客胞宫则血海不固，故内服温补不应，外治温散寒湿而效。", ["沉", "迟", "涩"]], "4014": ["其他", "震按三案病同而治法各异，可见“病以脉为断”。立斋首案不载脉，然凉血止痛不效则舍补无他法，此又以意会。原文强调脉诊对辨证立法之关键，无具体脉象，故列其他。", []], "4015": ["病机", "妇人经候过期，发热倦怠，误用四物黄连反两月一度且少成块，峻药通之则两目如帛所蔽。薛曰“脾为诸阴之首，目为血脉之宗”，此脾伤五脏失所不能归目。虽未载脉，然从证测机，主脾胃损伤、气血失养之病机。", []], "4016": ["病机", "脉洪数，洪为火盛，数为热炽。患者误服风药后发热抽搐，肝脉洪数，乃肝家血虚火盛而生风。血虚为本，火盛为标，风动为变，故脉象洪数反映肝经火旺、血虚风动之病机，主肝热生风之抽搐。", ["洪", "数"]], "4017": ["病机", "脉洪数而虚，左关尤甚。洪数为火郁，虚为气血不足。腹内结块渐大，经水三月一至，肢体消瘦，齿颊似疮，乃肝脾郁结，火盛血虚。左关候肝，尤甚说明肝火偏亢，郁结化火，灼伤阴血，故脉虚数。", ["洪", "数", "虚"]], "4018": ["其他", "本段未涉及具体脉象，主要辨析天癸非月事，乃天一之真水，为精血之源头。论述男女皆有精，天癸与男女之精偕至，入任脉而成胎。脉象描述缺失，故不列脉素，主旨为理论辨析，非脉诊病机。", []], "4019": ["病机", "三部无寒邪脉，但厥阴弦长而上鱼际。弦长为肝气有余，上鱼际为肝火逆上。尼姑寡居，情志不遂，肝郁化火，故见恶风倦怠、乍寒乍热、面赤心悸、自汗。脉弦长上鱼际，主肝郁火盛，非伤寒表证。", ["弦", "长"]], "4020": ["病机", "肝脉弦紧，弦主肝郁，紧主寒主痛。寡妇因怒致寒热久不已，肝气郁结，气机不畅，营卫不和，故寒热交作。脉弦紧反映肝郁气滞，木克脾土，脾胃气虚。后见风寒热仍作，乃脾虚卫外不固。", ["弦", "紧"]], "4021": ["病机", "肝脉弦出左寸口，弦为肝郁，出寸口为肝气上逆。贵妇寡居，月候不调，寒热，手足麻木，心虚惊悸，心头觉辣，诸症皆由郁而有欲心不遂，肝郁化火，疏泄失常。脉弦出寸口，主肝郁气逆，相火内郁。", ["弦"]], "4022": ["病机", "肝脉弦出寸口，谓肝主疏泄。欲男子而不得，相火内郁，郁久气血暗耗，阴阳交争，自生寒热。脉弦出寸口为肝火不泄，逆而上行。然魏氏云脉上鱼际者阴虚火盛多见，不可定为郁病，须结合症候辨之。", ["弦"]], "4023": ["治法", "本段未出具体脉象，强调血热崩漏治法，但悲哀太过伤肺伤心致元气暴虚而崩者，当用人参、归脾汤，断不可用凉膈散。须以脉辨之，脉虚者宜补，脉数实者宜清，示人凭脉辨证以定治法。", []], "4024": ["病机", "脉举之略弦、按之略大而无力，弦为饮为劳，大而无力为血虚，合之则气血俱虚。气虚不运故麻痹，血虚不荣亦致麻痹；误用寒凉损伤脾胃，阳气失陷，遂成崩疾。岁运风木在泉，木盛克土，脾土受亏，土陷而血崩，脉证相参，皆由气血虚损、木贼土衰所致。", ["弦", "大"]], "4025": ["病机", "震按脉大而无力为气虚确据，非独血虚；麻属气虚，气虚不能摄血则崩。左手举之略弦，似有风邪，故少加荆、防。此段辨大而无力主气虚，弦主风邪，脉证合参，以气虚为本、风邪为标，议论借司天运气以张大其说，反觉宽泛。", ["大", "弦"]], "4026": ["病机", "肝脉弦大时一结，弦大主气郁，结主气滞；肺脉沉大有力，脾胃沉涩，两尺沉而无力。因怒致气郁，气滞血瘀，崩久不止。气郁化火，痰喘面青爪黑，皆气郁血瘀之象。脉沉涩为气滞血少，结为郁滞，故用香附、乌药等开郁行气，气行则血行，崩可止。", ["弦", "大", "结", "沉"]], "4027": ["病机", "右关洪滑，左寸洪数，两尺洪大。洪滑主痰热，数主火，大主邪盛。浊痰流滞血海，误服安胎之剂益加其滞，血去多而神魂无依，痰迷心窍故昏冒乱语；痰热在心包络与胆经，故夜半发病。脉洪滑数大，皆痰火壅盛之征，治当调气开痰、安神养血。", ["洪", "滑", "数", "大"]], "4028": ["其他", "此段为震按，评前案不用脱血益气之法，察脉审证高矣。病根在痰火，误服补涩药以致崩，非久崩不痊者比。若久崩虚证，虽归脾汤数百帖亦难起。文中未出脉象，纯论治法与预后，强调暴病实证易治、久病虚证难医。", []], "4029": ["病机", "脉沉而结，沉主里，结主蓄血。病得之天癸至而怒，因怒经止，血随气滞，蓄积不散，壅塞隧道，溢而妄行，故成崩中。脉沉结为蓄血之确征，治当决壅去滞，用桃仁、大黄行血破瘀，使血归经，崩自止。", ["沉", "结"]], "4030": ["病机", "脉洪大而数，洪大主邪盛，数主热。产后恶露不尽，留泊血海，新化之血迷失故道，妄行而崩，发热口渴、胁痛狂叫，皆瘀热内盛之象。脉洪大数，证实非虚，故用醋制大黄、桃仁、干漆峻下瘀血，瘀去则新生，诸病如失。", ["洪", "大", "数"]], "4031": ["其他", "震按前二案皆实证，一攻即愈；虚证难医，屡补无功。治虚须审脏腑经络奇经，虚在何处，有无寒热湿风兼挟，细细分别。风入胞门，古人有一味防风丸等方；肝风内动，则未之及。肝属风木主藏血，因怒因郁皆致斯病。文中未出脉象，纯论治法与病机。", []], "4032": ["病机", "脉细如丝，为阳气衰微、不能营阴之象。前医误投寒凉，致下泄、肌肉如削、四肢厥逆、不能言，皆阳气欲脱之候。细脉主虚，此非血虚，乃阳微不能温运，故法当温补，阳生则阴长而血自止。用人参、附子回阳，正合脉证。", ["细"]], "4033": ["病机", "右寸滑、左寸短弱、两关濡、两尺软弱，孙氏断为心肾俱不足而中焦有湿。白崩日久，气血日败，脉见短弱濡软，皆虚象；右寸滑为湿痰上贮。故治以燥脾兼补心肾，既济丹补心肾、断下丸燥中宫之湿，脉证相应。", ["滑", "短", "濡", "弱"]], "4034": ["病机", "经闭五月，下白或赤，午后发热，咳嗽呕吐，似痨瘵而两尺脉皆实。尺脉主胞宫，实为胎孕之征，非虚劳之候。外受风邪搏激，故有发热咳嗽等症。凭尺实断孕，饮清和之剂而安，后生子，证明脉实主胎而非病。", ["实"]], "4035": ["病机", "寸口脉洪滑，洪为气盛，滑主痰湿。孕妇七月，胎气凑上，中焦蓄湿热，湿生痰，痰结聚而上吐如小肠寸许之物，病名子悬。洪滑非虚，故用紫苏饮加芩、连、贝母清热化痰降气，十剂获全，脉证相合。", ["洪", "滑"]], "4036": ["病机", "六脉洪大，汗出如雨，喘息不休，邻医谓吐血脉忌洪大、妊妇禁汗。孙氏审证，知洪大由酷暑楼居热逼所致，非内热迫血。汗多血去胎失养，故用益元散清暑、紫苏汤调服，汗敛喘定痛止，再固胎。示脉须合证而断。", ["洪", "大"]], "4037": ["病机", "两寸俱短弱，寸主上焦，短弱为元气大虚。妊七月因惊胎动，血下、二便急、腰腹胀疼，皆上焦元气虚不能固摄所致。故骤补元气，人参、芪、术、阿胶等补气养血安胎，一剂血止，四剂证除，足月而产。", ["短", "弱"]], "4038": ["病机", "左寸关短弱、尺滑，右寸滑、关濡弱、尺沉微。左寸短弱为心不足，关濡弱为脾不足，故断心神脾志大不足、肺经有痰，非孕脉。前二胎九月而产、手足面目完全而水火不分、无舌，皆心脾二经不足之征，脉逐部细诊可验。", ["短", "弱", "滑", "濡"]], "4039": ["其他", "震按总结两寸短弱为上焦元气大虚、左寸短弱为无孕，乃阅历老到之言，强调察脉须逐部细诊。又质疑既云心脾二经不足，何但补心而不补脾。此段为评按，非脉象主病，故脉象要素从缺，归入其他。", []], "4040": ["病机", "尺部微涩艰推，为下焦阴血不足、胎元失养；独肺部洪大无伦，是水气太过、肺失肃降，上壅会厌胸膈。原文谓“上壅者，以肺脉之洪”，洪大无伦与尺涩并见，示下闭上壅、气血逆奔，故食入痛楚、喘声如曳锯、手臂青紫肿亮，属危重之候。", ["涩", "洪", "微"]], "4041": ["病机", "脉弦左为甚而且弱，弦主肝气逆，弱为胃气受参术壅补所伤；怒气激肝，挟胎气上逆，故呕吐头眩。药后脉略数、口苦口酸，为膈间滞气未尽、肝热未平。终至两手脉平和而右甚弱，右脉主脾胃，弱则胎失所养，故断胎必堕。", ["弦", "弱", "数"]], "4042": ["预后", "右脉弱而胎必堕，右脉候脾胃，胎赖脾胃气血以养。脉弱则中气不足、胎系不固，虽投参术亦难挽回。震按称丹溪“试验数次，故确信不疑”，说明右脉弱在此为胎元欲堕之预后征象，非一般脾虚可比。", ["弱"]], "4043": ["兼症", "脉和而右手寸高，寸候上焦，高则气结于胸膈。症见寅卯小腹气冲上、膈满而吐、面赤微躁头眩，乃肝火挟冲脉之火冲上。脉和示病不在血脉而在气分郁结，故用沉香化抱龙丸香窜开结，气不上冲则吐止眩减。", ["和"]], "4044": ["病机", "本条无脉象原文，震按承前案“右寸脉高”而发。抱龙丸乃香窜辛散之药，似非孕妇所宜，竟获大效者，因妇多郁多思，气结而右寸脉高。诸香药能破郁开结，气机通畅则膈宽吐止，说明右寸高主气郁结聚，非虚证可补。", []], "4045": ["妇人", "脉皆细微近滑，尺脉不绝。细微似虚，然滑而尺不绝，是妊娠恶阻之脉，非经闭劳损。原文谓“脉虽细微，似近于滑，又尺脉不绝，乃妊娠也”。形瘦面紫、呕吐声哑、手指挛拳，皆胎气上逆、胃失和降所致，故以四君子加二陈和胃安胎。", ["细", "微", "滑"]], "4046": ["妇人", "尺脉虽小，按之滑而不绝。小为不足，滑为妊娠之象，不绝则胎气尚存。前医以经不行、呕哕眩晕为二阳之病，法在不治；江氏凭尺脉滑不绝断为妊而恶阻，非凶候。说明尺脉滑不绝是辨妊娠恶阻之关键，不可因脉小径作虚损论。", ["小", "滑"]], "4047": ["病机", "左脉稍和而右涩，右脉候气，涩主气伤血滞。原文谓“饱食气伤，胎系弱，不能自举而下堕，压膀胱”，故小便闭三日、脚肿形瘁。左稍和示血分未大伤，右涩示气分壅滞，法当补血养气，血气正而胎系自举，水窍乃通。", ["涩", "和"]], "4048": ["病机", "脉细弱为气血两虚之象。孕妇七月，小便不通，非实闭，乃气血虚不能乘载其胎，胎压膀胱下口所致。细弱示正气不足，无力托举，故溺不得出而急胀。治以补药升提、手法托胎，正合虚则补之、陷则举之之理。", ["细", "弱"]], "4049": ["病机", "脉左大无力，重取则涩，乃血少之征。左脉候血，大而无力为血虚不充，涩为血行不畅。孕三月即堕，因血少不能养胎。丹溪以妙年只补中气，使血自荣，浓煎白术汤调黄芩末，补脾清热以安胎，终得保全。", ["大", "涩"]], "4050": ["病机", "尺脉涩或微弱，为子宫真气不全，阳不施、阴不化，精血虽凝终不成形，故产血块或血胞。若脉洪盛者，胞不堕，洪盛示气血尚充，胎元得养。此以尺脉强弱辨胎之成否，涩微为不足，洪盛为有余。", ["涩", "微", "弱", "洪"]], "4051": ["病机", "震按尺脉涩或微弱与微滑按之不绝者，分别胎与非胎。微滑按之不绝为胎脉，涩微为真气不全。下案尺脉必不滑、按之无根，示肾气衰败。石山案两尺浮弱不任寻按，竟以大补保胎，乃事之变，说明脉辨胎须合神色，不可执一。", ["涩", "微", "弱", "滑"]], "4052": ["病机", "脉皆柔软无力，两尺浮而弱不任寻按，为气血耗甚之象。长瘦色黄白、性躁急，屡堕胎已七八次，气血大伤，胎无滋养，譬之水涸禾枯、土削木倒。三月五月属少阳火动，性躁激发，故堕多在三五月。治以大补汤去桂加柏、芩，补虚清火，服半年胎固。", ["软", "弱", "浮"]], "4053": ["病机", "脉洪盛为胎未堕之征。堕下逾旬而腹肿发热气喘，面赤口臭舌青黑，陈氏断为心火盛而血干、肝绝而胎死。洪盛脉示邪火尚盛，正气未绝，故胎未即堕。以蛇蜕煎汤下平胃散加芒硝、归尾，攻逐死胎，须臾腹鸣阵痛，死胎堕下而愈。", ["洪", "盛"]], "4054": ["预后", "产后气喘脉洪，法在不治，洪为邪火亢盛、气逆上脱之象。此案得生，全在逾旬二字，若非胎未堕，决不能至逾旬。说明脉洪虽主危候，但须结合病程长短判断，逾旬而胎未堕，正气尚存一线，故可挽回。", ["洪"]], "4055": ["病机", "六脉微弱为禀气素弱、损伤脾气之象。自去其胎后腹胀如鼓、吐不能食，乃脾气损伤而作胀。脉微弱示正虚，但胀急标实，当急则治标，用桃仁承气加朴、实倍硝、黄攻下，通后以参、耆、归、芍等补养而安。", ["微", "弱"]], "4056": ["误治", "六脉微细之极，本为气血大虚之候，脉虚而病形实，乃虚中夹实。医者误认诸痛不可补气，反用青皮、香附、吴茱萸等理气破气之品，虽暂愈而元气转脱，致六脉如丝欲绝。此案说明脉微细主元气虚衰，理气之剂损真，当以参、芪、归、术、附子、姜、桂温补，方得六脉全复。", ["微", "细"]], "4057": ["病机", "震按屡发心脾痛者，脉必弦小而坚，或更带数。弦主痛、主肝木，小坚为气结血滞，数则为郁热。此脉象反映气滞血瘀、郁而化热之病机，故痛屡愈屡发，渐频至危。若脉微细如丝欲绝，则属虚候，非此弦小坚数之实象，温补自不可缺。", ["弦", "小", "坚", "数"]], "4058": ["病机", "六脉数而微弦，数主热，弦主肝，微弦为火象不剧。江氏断为厥阳之火泛逆，因服打胎药下血如崩，阴血暴伤，阳失所附而化火上逆，故见鼻衄。脉数微弦正是阴亏火旺之征，投四物加阿胶、山栀、蒲黄养血清火而愈。", ["数", "弦"]], "4059": ["兼症", "六脉俱数，左寸滑大，右关搏指，左关软弱。数主热，滑大主痰火与胎气壅盛，软弱为气血不足。此孕五月下血发战，脉象示虚火内扰、胎热不安，故见寒热、头痛、腹块硬、下血块多。后现白泡面肿、指爪皆黑，乃虚火游行无制，脉数滑大与症相应。", ["数", "滑", "大", "弱"]], "4060": ["预后", "脉急疾如狂风骤雨，十余至则不至，顷之复至如前，此脉来急疾而歇止，主胎气上逼、气血逆乱，非好胎之兆。急疾为邪盛正危，歇止为气机断续，故断其胎必感震气所结，安之无益。下异胎后脉息微和，神思恍惚，恶露多，又示气血骤虚，需安神调血。", ["急", "疾"]], "4061": ["病机", "脉来微结，微为气血虚衰，结为脉气阻滞。孕十七月不产，胎已死而枯，脉微结正合气血不足、胎失所养而枯滞之机。张石顽治孕十三月不产，脉来微结，用十全大补汤下枯胎色白，亦证明微结主虚中夹滞，胎枯不下。", ["微", "结"]], "4062": ["病机", "脉皆细濡颇弦，细濡为气血两虚，弦为肝火时炽。形长瘦而脉细濡，色青脉弦，两尺浮滑，汪氏断为气血两虚兼热，气虚为重。气血亏则胎失所养，故屡患横生逆产、子皆不育。脉象紧扣虚与热，宜补阴丸倍参、芪、香附，补虚清火而胎顺。", ["细", "濡", "弦"]], "4063": ["误治", "两尺脉沉绝，他脉平和。两尺候肾与胞宫，沉绝似胎死，然陈氏辨为子悬，因面不赤、舌不青，其子未死。脉沉绝乃胎上迫心、气血壅塞于上，下焦脉气一时不通，非真死胎。医误认死胎，用蓖麻、麝香攻下，几致危殆，紫苏饮降逆安胎而愈。", ["沉", "绝", "平和"]], "4064": ["预后", "原文未出脉名，仅言「两尺脉绝」。震按此提示：两尺候肾与胞宫，脉绝则胎元失养，易误认作子死腹中；然须结合陈氏辨法细审，不可遽断死胎，否则误杀两命。故本条主旨不在脉象本身，而在凭脉断死生之难，属预后判断之警示。", []], "4065": ["其他", "原文未载脉象，仅列胞衣不下诸方：败血入胞者用黑豆酒淬、益母丹，或芒硝童便，或牛膝芒硝，慎斋则用人参砂仁末。震按明言「不知脉证之何如」，故本条重在存方备参，非论脉。病机当分败血壅胞与气虚无力送胞两端，须凭脉证分辨。", []], "4066": ["病机", "原文点明「必脉象细软，口不燥渴，内不烦热，用之方效」。细软为气血不足、脾失健运之象，故恶露不下属虚而无力推荡，非瘀血实阻；参、附、术、归温补健脾则血行而露下。若脉不细软而见实象，则非温补所宜，此案不载脉象，震按讥其「糊涂」。", ["细", "软"]], "4067": ["主病", "「气口脉大」主饮食停滞，气口候脾胃，大则邪实于中，故立斋断为食滞而腹痛发热。误用破血补虚、降火化痰，反伤脾胃，致四肢逆冷、泄泻下坠，转为虚寒变证。脉大在此为停食之实象，与后期虚寒变证相对照，说明凭脉辨虚实之要。", ["大"]], "4068": ["预后", "震按承上案「气口脉大」而辨转归：若脉变为细软，是邪退正复，温补得效；若脉仍大，则非所宜；大而软犹可望敛小；倘「脉大且数，按之有力」，为邪热炽盛、正气难支，温补无益，其死可必。此以脉之变化判预后吉凶，细软与数大对举。", ["大", "细", "软", "数"]], "4069": ["治法", "原文未载脉，震按叹「恨不载脉」。本条主旨在于示人：古人有是病即用是药，不拘产后必大补之套；归脾八珍易用，当归六黄难用，苦寒之剂中病即止。虽缺脉象，然提示临证当凭脉证施治，不可拘泥产后宜温补之说，属治法之变通。", []], "4070": ["病机", "「脉芤而涩」：芤主血虚，涩主血行不畅，合之则为血虚兼瘀。产妇小腹作痛有块，正是瘀血内停、新血不充之候。故用四物养血，加延胡、红花、桃仁、牛膝、木香活血行气，虚瘀并治而愈。脉芤涩与腹痛有块相应，示虚中夹瘀之病机。", ["芤", "涩"]], "4071": ["病机", "「其脉洪数」为热盛之象。产妇小腹作痛，服行气破血药不效，洪数示瘀血内溃、化热成脓，非单纯气滞血瘀。故以瓜子仁汤排脓，太乙膏下脓而愈。洪数在此主瘀热酿痈，与一般产后瘀阻之脉不同，说明脉象转变提示病机由瘀转脓。", ["洪", "数"]], "4072": ["主病", "原文以脉辨产后腹痛之脓成与瘀血：脉洪数主热盛肉腐，故「已有脓」；脉但数则热势稍逊，「微有脓」；脉迟紧为寒凝血滞，主「瘀血」，下之即愈。此以脉象判断病性及治法，紧扣荣卫不调、瘀血停滞之病机。", ["洪", "数", "迟", "紧"]], "4073": ["其他", "原文未载具体脉象，仅言「想诸虚寒证毕现，其脉之大小迟数不足计耶」，强调虚寒重证当以证候为主，脉之大小迟数已非辨证关键。此属对脉诊局限性的讨论，非直接论病机。", []], "4074": ["病机", "脉浮弦而沉涩，右为甚，浮弦主风，沉涩主湿滞血瘀。丹溪断为「受湿」，因产前喜羹汤茶水，湿浊内蕴，与瘀血相搏，故见发搐、气喘、面黑、口臭。下水晶块后愈，证实湿瘀互结之病机。", ["浮", "弦", "沉", "涩"]], "4075": ["病机", "震按指出「脉象浮弦易辨，沉涩难辨」，浮弦为风动之象，沉涩为湿瘀内阻之征。此案发搐、面黑、口臭似瘀血入肺死证，然沉涩脉提示湿浊内壅，非纯瘀血，故丹溪从湿论治而愈。", ["浮", "弦", "沉", "涩"]], "4076": ["病机", "肝脉弦紧，弦主肝风，紧主寒主痛，此肝经血燥生风，风热瘛疭。症见发瘛、遗尿、自汗面赤、时面青，皆肝血不足、风火内动之象。立斋以滋阴血、清肝火为法，用加味逍遥散而诸证悉退。", ["弦", "紧"]], "4077": ["其他", "原文未识出脉名，仅言「不可诊脉」，因手足瘛疭、目上视，脉诊难施。此段重点在叙述难产伤力、恶露绝无、参粥壅塞致神昏瘛疭之病情，非以脉论病机。", []], "4078": ["其他", "震按此案，未载具体脉象，但言「其讲脉与面色极是」，强调产后谵语昏狂有因蓄血、因痰之别。前半段探吐消瘀消痰，后半段于轻剂消瘀中复用人参，示人辨证施治，非专论脉。", []], "4079": ["病机", "六脉俱无，按至尺后脉来实数有力，此热邪深伏、脉道壅遏之象。症见口冷吐水发厥、战栗、唇焦颊赤、便难溲赤，易氏断为「实热症」，热极似水，热入血室，热盛生风。用三黄汤后六脉俱现，证实热退脉出。", ["实", "数"]], "4080": ["其他", "此段为震按评语，称易公案“发明脉理”如“仙传秘诀”，并未具体描述脉象，故无脉象要素可录。其主旨不在论某脉主某病，而在推重该案对脉理的阐发，属医案评述性质，故归入其他，不作病机推断。", []], "4081": ["病机", "脉弦而洪数，弦主痛、主瘀滞，洪数主内热。原文“燥剂搏其血，内热而风生，血蓄而为痛”，正合此脉：姜附温燥搏血，血蓄脐腹作痛故弦；内热生风、谵语目窜故洪数。面赤舌黑、胸腹不胜按，皆热入血室、瘀热互结之征，故断为产后热入血室生风。", ["弦", "洪", "数"]], "4082": ["病机", "此段承前案而申辨：投姜附后始搐搦，是“燥剂搏血而风生”，非虚寒。原文以“舌黑腹不胜按”“面赤洪数之脉”为据，洪数主内热，面赤为热蒸于上；若真虚寒则手足厥冷，今不然。故脉洪数与舌黑拒按相应，说明病机为瘀热内结、热极生风，而非寒证。", ["洪", "数"]], "4083": ["预后", "脉皆浮洪搏指，产后阴血暴虚而孤阳外浮，故浮洪搏指；汗多而脉不为汗衰，是正气外脱、脉证相反，故汪公断为“法在不治”。所幸气不喘、不作泄，尚存一线。原文疑“为凉药所激”，投参耆姜术补敛后“脉敛而病渐安”，正说明浮洪搏指为虚阳外越之危候。", ["浮", "洪"]], "4084": ["预后", "此段为震按，重申“浮洪搏指之脉，产后所大忌”。浮洪搏指与身热口渴、昏瞀头痛并见，貌似伤寒而实为产后气血暴伤、虚阳上浮，故为大忌。原文赞汪公“非大剂人参，岂能挽回”，又云“服五剂而脉敛”，以脉敛验证补虚敛阳之法，属预后判断之论。", ["浮", "洪"]], "4085": ["病机", "六脉浮大洪数，貌似实热，然原文断为“产后暴损气血，孤阳外浮，内真寒而外假热”。浮大洪数乃虚阳浮越之象，非真热；故用清凉则热增剧，投八珍加炮姜则“热减大半”。停参耆一日“复大热如火”，反证此脉此证属气血暴虚、阴寒内盛而格阳于外。", ["浮", "大", "洪", "数"]], "4086": ["病机", "此段为震按，指出病由沐浴发热、渴饮冷、狂谵不食，人易误作伤寒；及用清凉“热增剧”，脉洪数而“用滋阴易，用参姜难”。洪数在此非实热，乃虚阳外浮。投八珍热减大半，停参耆一日复大热如火，证明病宜温补不宜凉散，洪数之脉当从虚寒格阳解。", ["洪", "数"]], "4087": ["病机", "六脉乱而无绪、七八至，是邪热充斥、正气散乱之象；独右关坚硬，右关主脾胃，坚为实邪盘踞。原文谓“风邪面食瘀血皆未消熔，补剂太骤”，蓄血如见鬼，故脉乱数而右关独坚，说明瘀食暑气交结、补涩太早，邪无出路，当消瘀食、解暑气。", ["数", "坚"]], "4088": ["病机", "脉七八至而乱无绪，似热极而虚，然右关独坚硬，为积滞内实之征。数乱之脉非尽属虚，坚硬独见右关，说明实邪结聚中焦，故用芩连证益甚，参术加剧，终以三棱攻积得效。此脉象提示辨脉当参部位与兼象，不可见数乱即断为虚。", ["数", "乱"]], "4089": ["病机", "六脉皆数，产后大泻后发热恶心，吐热不止，昏愦耳聋，眼胞手足虚浮。数脉所主，其邪为热，其正为虚，此数而兼虚，为气血两虚、虚阳外浮之象，非实热。故以十全大补加炮姜温补得效，数脉渐退，说明数脉不可一概作热论。", ["数"]], "4090": ["病机", "数脉之义，其邪为热，其正为虚。此案数脉属虚，故敢用姜桂温补。数脉渐退则正复，若数脉不时，则生恶疮，为虚阳外越、营血不和之变。指出数脉须分虚实，虚者温补，实者清攻，不可见数即断为热而妄用寒凉。", ["数"]], "4091": ["病机", "脉右大于左者三倍且数，产后忧闷，小腹块痛，下午发热，为瘀血内结、郁而化热之候。右脉大数，主积滞实热。后脉大无绪，势甚危急，乃瘀热搏结、腑气不通，故用攻消瘀滞、通下结粪而安。大数之脉在此主实，与虚寒数脉迥别。", ["大", "数"]], "4092": ["病机", "数脉大脉，均为产后所忌，然有虚实之别。前案数大而虚，用温补；此案数大而实，用攻消。石山论浮洪搏指之脉，恐为凉药所激，此则认为积滞尚多。说明同一数大脉，须参证候与脉势，实者攻之，虚者补之，全在圆通活变，不可执一。", ["大", "数"]], "4093": ["病机", "两手脉沉涩兼结，产后神昏胸满、咳喘发热，服药反重。沉涩为邪结于里，结脉为气机阻滞，此胎前伏邪，产后气血虚而邪益内结。法宜表里两和，透邪达滞。前医误投参地归芍敛滞，致彻夜靡宁，说明邪结反补，闭门留寇，脉沉涩结正是邪结之征。", ["沉", "涩", "结"]], "4094": ["病机", "产后痢，腹痛胸满，后重口渴，脉数大者，为暑湿致痢、湿热积滞之实邪。数大主热盛邪实，故用芩连槟朴滑石木香，甚则加大黄殊效。此与前案病异理同，均示产后不可泥于虚而禁攻，脉数大而证实者，当祛邪为急。", ["数", "大"]], "4095": ["病机", "脉弦而紧，产后食冷，呕逆满闷，腹胁刺痛，寒热谵语抽搐，变异多端。弦主痛主瘀，紧主寒主痛，弦紧为寒凉所伤、瘀血停滞下焦之象。按小腹急痛，知瘀血未尽，客于经络而变生诸证。故用大调经散倍琥珀化恶血成水，恶水下行而愈。", ["弦", "紧"]], "4096": ["病机", "产后恶露未尽，气血未复，起抹身而寒气客于经络，营卫失和故乍寒乍热。脉紧主寒、主痛，弦主气机收引、经脉拘急，紧弦并见正是寒邪外客、经络凝滞之象，非单纯瘀血内阻。故以葱白散温通散寒，二帖而安，说明病机重在寒客经络而非恶露本身。", ["紧", "弦"]], "4097": ["病机", "产后气血本虚，误服小柴胡致汗出不止、谵语烦渴、肢体抽搐，已成气血两虚、虚阳外浮之候。脉洪大而重按如无，洪大为外浮之假象，重按无根方是真虚，即气血两虚、阳气欲脱之征。故用十全大补加附子温补固本，非风寒实证可比。", ["洪", "大"]], "4098": ["病机", "震按总结三案脉法：脉弦而紧知为瘀血，因弦紧主收引凝滞，瘀阻脉络则见；脉洪大重按如无知为气血两虚，洪大乃虚阳外浮、按之无根。此段以脉之有力无力辨虚实真假，强调临证须凭脉定病机，故首案用大调经散、次案用葱白散、此案用桂附，皆非通套行血消瘀或平补气血所能治。", ["弦", "紧", "洪", "大"]], "4099": ["病机", "产后病惊，身飘旋转、四肢酸软，众皆以安神补虚治之而反甚。左脉芤且涩，芤主血虚失血、涩主血行瘀滞，左脉候心，合神色不变，知非纯虚，乃因惊致心胞络积血，瘀阻而现似虚之象。下血如漆者一斗遂愈，正合「大实似羸」，说明脉芤涩在此主瘀血内积而非单纯血虚。", ["芤", "涩"]], "4100": ["病机", "震按此证众人必认为虚，唯辨左脉芤涩方能测知心胞积血。芤为血虚之常脉，涩为血滞之征，二者并见而神色不变，提示瘀血内阻、血不循经，非安神补虚可解。此段强调惊是病、因惊又致病，治惊无益，当从脉之芤涩识其积血病机，举此以例其余。", ["芤", "涩"]], "4101": ["病机", "产后未满月，怒气致血流如水，又劳苦汗出、日晡潮热、五心如炙，诸医误用柴芩薄荷苦寒，热愈炽。脉弦大无力，弦为气郁、大为虚象，无力则非实热，合产后失血劳倦，知为蓐劳、气血亏虚而虚热内生。故以四物汤加胡黄连、秦艽、青蒿养血清热，热退身凉。", ["弦", "大"]], "4102": ["病机", "产后发热晡热、吐血便血、盗汗尿频、胸胁胀痛痞闷，误用降火致泻痢肠鸣、呕吐不食、腹痛足冷。脉或浮洪、或沉细、或如无，浮洪为虚阳外浮，沉细如无为气血大虚，面青黄赤白不定，皆虚寒假热之状。时值仲夏而舍时从证，用六君子加炮姜肉桂温补，说明脉之浮洪沉细无常正是大虚之据。", ["浮", "洪", "沉", "细"]], "4103": ["病机", "震按此条脉法可为大虚之据，指上案脉或浮洪、或沉细、或如无，浮洪非实热乃虚阳外越，沉细如无乃气血内竭，脉象无常而按之无根，正是虚寒假热、诸脏虚损之凭据。故舍时从证，以温补固本取效，示人辨大虚当凭脉之无根而非执一象。", []], "4104": ["病机", "脉洪大而重按全无，乃浮取似盛、沉取空虚之象，非真热实火。原文断为「命门火衰，脾土虚寒而假热」，洪大为虚阳外浮之假象，内热晡热、自汗盗汗、口舌糜烂皆假热，吐痰多乃脾虚不能统摄归源。故主火衰土寒、虚阳上浮之病机。", ["洪", "大"]], "4105": ["病机", "脉皆濡缓而弱，濡主湿、缓主脾、弱主气虚，三象合见，说明产后劳力伤胃、脾胃气虚而湿浊内停。原文谓「产中劳力以伤其胃」，勺水粒米弗容、即时泄下，正是胃虚不纳、脾不运化之候，故用参苓白术散健脾渗湿而泻止，非实邪可攻。", ["濡", "缓", "弱"]], "4106": ["病机", "脉来微细，数有七至，微细为阳气衰微、阴血不足，数而无力为虚阳外越之象。原文点明「外露但欲寐少阴证据」，断为「阳脱证也，属少阴」，热渴、语言如抖出皆阳脱虚象，故用生附子、干姜回阳，人尿猪胆汁引阳入阴，此为少阴阳脱之危候。", ["微", "细", "数"]], "4107": ["预后", "此段比较两案脉象以判平险：汪案脉濡缓而弱，虽勺水粒米弗容，然脉尚和缓有胃气，故处方平淡亦可取效；金案脉微细而数有七至，微细数急为阳气欲脱、胃气已败，故险。原文「其平险各别也」正以脉之缓弱与微细数七至辨预后吉凶。", ["濡", "缓", "弱", "微"]], "4108": ["病机", "原文未识脉名，且明言「不凭脉象」，全以病机推求。其病机在乎「痰与血交涌而上」，才侧身便壅绝，显系败血随痰上升；然非血气脾胃之大虚，败血何由随痰上升，故虚为本、痰血上壅为标，方用六君补虚合犀角失笑散消瘀，恰对病机。", []], "4109": ["病机", "脉虚甚，虚为气血不足之象。原文谓难产因气血虚，产后尤虚，收生不谨损破尿胞而淋沥不禁，肌肉破伤在内者亦赖气血充养方可完补。脉虚甚正合气血大虚之机，故以参、术为君峻补气血，使气骤长而脬完，一月而安。", ["虚"]], "4110": ["病机", "尺脉洪数，尺候肾，洪数为火旺之象。原文断疥为肾疳、疮为骨疽，「皆肾经虚证」，乃肾阴亏虚、虚火内炽，故火旺之际必患瘵证。洪数见于尺部，说明火旺在下焦肾经，非实火可泻，故用六味地黄、十全大补滋阴补虚而愈。", ["洪", "数"]], "4111": ["病机", "两手脉俱缓弱，缓弱为脾胃气虚、运化无力之象。前医误作风热，屡用蒺藜、荆芥、羌防、升麻等疏散寒凉，致饮食顿减、遍身发疮、痛痒不可言，乃脾胃更伤。脉缓弱正示中虚，故用六君子汤加减健脾益气，一服饮食进，十帖疮疥如脱。", ["缓", "弱"]], "4112": ["病机", "脉洪大而虚，为元气亏损、虚阳外浮之象，故断为气瘤，肺金侮肝木。脓溃后脉洪数大、按之如无，乃血气益虚、虚火更炽，非实热，故加附子温补而愈。", ["洪", "大", "虚", "数"]], "4113": ["病机", "脉大按之虚，为溃后气血两虚、虚阳外浮之候。午前痒属气虚，午后痒属血虚，皆因瘰疬溃后耗伤气血，非风证，故以十全大补加香附补虚而愈。", ["大", "虚"]], "4114": ["病机", "脉弦劲中兼躁动，左关尺紧细如刀，为肝胆气血虚滞、郁结不舒之象。弦劲主肝病，紧细主虚滞，躁动为郁火内扰，故见瘰疬坚硬、痰咳梦泄，皆肝病延及心脾所致。", ["弦", "紧", "细", "动"]], "4115": ["兼症", "左脉浮滑，右脉稍弱而滑，浮滑主热痰壅肺，弱为气血不足。结合咳甚痰脓带血，断为妊兼肺痈，故以清肺泄肺之剂取效，后脉缓浮示热减而胃伤。", ["浮", "滑", "弱"]], "4116": ["病机", "脉洪数而无伦次，为肾火伤肝、虚阳上浮之危候。面赤吐脓、发热作渴、烦躁引饮，皆火炎于上，然脉无伦次示根本已虚，故用加减八味丸引火归元而安。", ["洪", "数"]], "4117": ["预后", "六脉洪数不减，为足三阴虚损、虚火不敛；后脉洪大浮数、按之无力，且数不时见，乃肺痈已成之兆。洪数浮大而无力，主虚火上炎、血肉腐败，故吐脓血。", ["洪", "数", "大", "浮"]], "4118": ["误治", "右寸关脉浮数，右寸主肺、右关主脾，浮数为风热客肺、脾土亏损之象。前医发表伤津，致咳嗽喘急、大便不通，若再通利则耗津液，必成肺痈，故以补脾益肺而愈。", ["浮", "数"]], "4119": ["其他", "原文未载脉象，仅述射干汤后乍愈而气喘体倦、发热作渴、小便频数，此乃攻邪伤正、气阴两虚之候，故用补中益气合生脉散补气敛阴而愈。", []], "4120": ["病机", "脉来涩涩不调，涩主气滞血瘀、痰食内阻，脉道不畅。患者体肥善饮，壮热呕逆、胸膈隐痛拒按、便溺涩数、舌胎滑，皆胃中痰热壅滞、气血瘀阻之象。张氏据“但呕不嗽”断为胃病而非肺痈，涩脉正示痰瘀胶结、胃络不通，故用凉膈散加石斛、连翘下其稠腻而效。", ["涩"]], "4121": ["主病", "脉滑数，滑主痰湿积滞，数主热，合之示热毒壅聚、血肉腐败。丹溪以“痛病脉当沉细”为常，今反见滑数，知非寻常腹痛，乃肠痈热毒内蕴、气血壅滞成痈之候。故用云母膏丸下脓血一盆而愈，脉象与肠痈主病相应。", ["滑", "数"]], "4122": ["病机", "脉洪数，洪为热盛气壅，数为热急，示瘀血与热毒搏结、壅聚成痈。妇人毒药去胎后当脐右结块、痛不可按、寒热，乃瘀血流溢肠外肓膜之间聚结为痈。洪数之脉正应瘀热壅盛、肉腐成脓之势，故用补气血行结滞排脓之剂，针决出脓而愈。", ["洪", "数"]], "4123": ["主病", "左寸芤而带涩，右寸芤而洪实，两尺两关俱洪数。芤主血虚而瘀，涩主血滞，洪数主热盛，合示热毒瘀血壅结大小肠之间欲作痈。潮热似疟、小腹右块、右脚不能伸缩，皆痈毒内结之症。虞氏据脉断为肠痈脓未成，用五香连翘汤加减而愈。", ["芤", "涩", "洪", "数"]], "4124": ["主病", "芤脉见于肠部，芤主血虚而血积，脉诀云“关内逢芤肠里痈”。妇肠中痛不可忍、大便从小便出，乃痈疡内溃、血瘀成脓之候。李生切脉觉芤见于肠部，断为肠内痈，服云母膏丸下脓血数升而愈，正合芤脉主肠痈积血之旨。", ["芤"]], "4125": ["病机", "脉芤而涩，芤主血虚而瘀，涩主血行滞涩，合示瘀血内阻、血不循经。妇人小腹胀痛而有块，正是瘀血结聚之征。芤涩并见，说明血瘀而兼血虚，故用四物加元胡索、红花、桃仁、牛膝、木香养血活血行滞，二剂血下而愈。", ["芤", "涩"]], "4126": ["病机", "脉洪数，洪为热壅，数为热急，示瘀热内结、气血壅滞。妇人小腹胀痛、大便秘涩、转侧有水声，乃瘀血内停、热结于里之候。洪数之脉应瘀热搏结之势，故用梅仁汤下瘀血，诸证悉退，再以薏苡仁汤调治而愈。", ["洪", "数"]], "4127": ["病机", "脉洪数，洪数主热盛，示痈脓已成、热毒壅盛。妇人脓成胀痛、小便不利，乃痈疡内蓄脓毒、气血壅遏之候。洪数之脉正应脓毒炽盛、热壅气滞之机，故服太乙膏下脓甚多而胀痛顿止，继以栝蒌散、蜡矾丸托里而安。", ["洪", "数"]], "4128": ["主病", "脉洪数者，洪为阳盛气分热炽，数为热邪鼓动，当脐结痛、发热恶寒而见洪数，是热毒壅聚肠腑、气血壅滞成痈之象。洪数主实热，故断为肠痈，后小便间有脓血，正合痈溃之征。投仙方活命饮等不应，乃热毒深结，非轻剂可解，终以云母膏丸服而愈，可见脉证相合则药对病。", ["洪", "数"]], "4129": ["病机", "脉数无力，数虽似热，然无力为元气虚损之征，非实热可比。腹内作痛、腹外微肿而肉色如故，是正气不足、毒不能外发，故脉不洪实而现数而无力。薛氏断为元气虚损，与参、耆、归、术补托，使毒渐发于外而脓成。后误用大黄、山甲引脓从便出，致水泻、自汗盗汗、热渴不食，皆虚损更甚之候，仍用前剂加温补而渐复。", ["数", "虚", "无力"]], "4130": ["主病", "脉洪数而实，洪为热盛，数为热急，实为邪结，三象并见，是热毒壅盛、腑气不通之实热证。小腹肿胀作痛、二便秘结、作渴欲饮冷，皆实热内结之症，与洪数实脉相应。故用黄连解毒散直折其热，二剂热痛顿止、二便调和，继以活命饮而愈，脉证药三者相合。", ["洪", "数", "实"]], "4131": ["预后", "初脉浮数而恶寒，浮为邪在表，数为热，恶寒非表寒乃疽疮之毒外攻，故薛断为疽证。旬余左尺洪数，知脓已成于内。及臀溃脓斗许，气血俱虚，脉洪大而举按皆实，继则按之如无，是洪大无根、气血虚极之候，与发热烦躁、发痉牙关紧相应。脉由实转虚，示正气溃败，故以大补参耆至四斤余救之。", ["浮", "数", "洪", "大"]], "4132": ["兼症", "脉稍实，谓脉象略见实象而非洪实太过，形脉稍实而性躁，是肝气偏旺、气血尚充之征。乳生隐核，因情志拂郁、肝气郁结而成，实脉示正气未虚、病属气滞。故以青皮汤疏肝行气，间以加减四物汤养血行经络，治两月而安。脉实而不虚，故可径用行气之剂，不必大补。", ["实"]], "4133": ["病机", "脉细涩而数，细为阴血不足，涩为气血滞涩，数为热郁于内。左乳痛有核如掌而见此脉，是阴血滞于阳分、郁而化热之象，故曰阴滞于阳。询之已得酒，酒性湿热助火，更增郁滞。治以栝蒌子、石膏、干葛清解阳明，芎、芷、蜂房行散通络，入酒服之，四帖而安，正合细涩数之郁热病机。", ["细", "涩", "数"]], "4134": ["病机", "肝脉微弦，微为虚象，弦为肝木之脉，见于左乳结核赤肿之后，是足三阴虚而兼怒气，肝经郁火未清、风动之征。两目连札乃肝风内动之候，与微弦脉相应。故于八味、清肝解郁汤后更加龙胆草清肝火，并六味地黄丸滋水涵木。若误用清热败毒、化痰行气，则虚其虚而鲜不误者。", ["微", "弦"]], "4135": ["病机", "原文未载脉象，以症测机。内热胁胀、两乳不时作痛、口内辛辣，是肝胆郁热循经上扰；卧而起急则脐下牵痛，乃带脉拘急、气血不畅之征。薛断为带脉为患，用小柴胡汤和解少阳，加青皮疏肝、黄连山栀清火，二剂而愈。此段重在凭症辨带脉受病，非以脉断，故脉象要素从缺。", []], "4136": ["病机", "脉洪数，洪为热盛，数为热急，肝脉候肝，肝脉洪数知热入血室。热入血室，血为热迫，故发热作渴，至夜尤甚；肝经热壅，故两乳忽肿。此脉主热入血室之病机，与发热、口渴、乳肿症候相应。", ["洪", "数"]], "4137": ["病机", "原文未出脉，然论乳汁乃气血所化，冲任盛、脾胃壮则乳多，衰则淡少；屡产无乳或便涩，乃亡津液。此段主病机在气血津液之化源不足，故当滋化源，非通利所能治。与乳少、便涩症候相应。", []], "4138": ["病机", "脉轻取涩、重按弦，涩为血滞，弦为痛为饮。形瘦长、色青苍，知热遗命门，灼津成瘀，故淋发大痛，下如漆和粟。涩弦主瘀热内结之病机，与淋痛、尿浊症候相应。", ["涩", "弦"]], "4139": ["病机", "脉微紧，微为阳虚，紧为寒束。初秋感寒发热而脉微紧，知脏气属阴，寒邪外闭，阳气内弱。温散反泻、气喘，乃阳虚不任疏散，寒邪内陷。此脉主阳虚寒束之病机，与发热、泻、喘症候相应。", ["微", "紧"]], "4140": ["病机", "右关独滑而数，关候脾胃，滑为宿食，数为热。他部大小等而和，知病不在风。乳母嗜酒，酒后乳儿，酒热宿食滞于中焦，故嗜卧、颊赤身不热。此脉主宿食蕴热之病机，与嗜卧、颊赤症候相应。", ["滑", "数"]], "4141": ["病机", "左脉浮洪，右脉颇和。浮为阳为表，洪为热盛，左脉候血，洪主痰热。痰热壅于经络，故左手不能举动；痰热上扰，故病痫。此脉主痰热内壅之病机，与肢废、痫症相应。", ["浮", "洪"]], "4142": ["病机", "脉洪滑，洪为热盛，滑为痰壅。口噤、搐动、发热昏沉，乃痰热内闭，风火相煽。洪滑主痰热生风之病机，与口噤、抽搐、发热、昏沉症候相应。", ["洪", "滑"]], "4143": ["病机", "左脉滑大，右脉沉弱似有似无。右主气，沉弱为气虚；左滑大为肝风之象。脾虚为肝所侮，风由虚生，故手足瘛疭。此脉主气虚肝侮之病机，与瘛疭症候相应。", ["滑", "大", "沉", "弱"]], "4144": ["病机", "脉大而无伦次部位，是脉来散乱无根、至数不匀，与撒手遗溺、目上视、汗大出、喉如曳锯、呼吸甚微并见，显系阴虚阳暴绝、真气将脱之候。杨注“将脱之象”正指此。脉大为虚阳外越，无伦次为胃气已败，故急灸气海、煎人参膏以回元气，非寻常中风闭证可比。", ["大", "散"]], "4145": ["病机", "脉空大而虚，按之无力，是阳气暴散、血不内守之象。患者年五十新娶少妇，又因跪拜劳役，汗如雨下，与丹溪治郑义士案同属阳气暴脱。空大者外浮无根，虚者中气不足，故急煎独参浓汤固脱止汗；后现哭笑，乃阴虚劳火动其精神、五精相并所致。", ["空", "大", "虚"]], "4146": ["预后", "本条未出具体脉名，以“脉又几几欲脱”承前条遗溺上视之绝象，判断证情危重，非灸法不及救；相较之下此条证稍轻，故不必灸。所论在辨脱证轻重与灸法取舍，脉象仅作欲脱之描述，故脉素从略，主旨属预后判断。", []], "4147": ["误治", "脉空大而虚，复汗出如雨，是阳气外脱之确征，故当急固阳气，属中风门脱证治法。然作者特举蔡辅宜中暑案，因室有少妾便断为脱证、妄投独参，实为暑闭，进益元散而愈。可见脉证合参、辨明闭脱至要，不可胸怀成见、温补妄施，否则轻者成锢、重者辄亡。", ["空", "大", "虚"]], "4148": ["病机", "前条脱证脉大无伦，此条闭证脉伏而微，两路重药正由此分。脉大无伦为阳气外越，脉伏而微为邪闭气机、阳郁不达，故须脉与证合参。左瘫不言而健又有痰，痰闭机窍，得间在此，与浦江洪宅妇病疟无脉条相似，皆示不可仅凭一脉定闭脱。", ["大", "伏", "微"]], "4149": ["误治", "本条未出脉名，专斥粗工执“肥白之人阳气必虚”之说，不辨脉证而温补乱投。肥白多虚之论本非定法，若不察脉之虚实、证之闭脱，概以温补，则杀人不用刃。主旨在于批评不凭脉辨证的误治之弊，故脉素从略。", []], "4150": ["治法", "肥人脉沉伏而无火象者，可用三生饮温散寒痰、通壅塞之气；若脉微细，则阳气已虚，必加人参以扶正。然三生饮实非通治中风之药，若虚火冲逆、热痰壅塞而昏愦颠仆，状类中风者，乌附切不可投，甚则姜汤亦不相宜，当以童溺之类清降。", ["沉", "伏", "微", "细"]], "4151": ["病机", "本条以脉辨内伤与外感：内伤之脉皆虚大无力，或微数无力，因劳役过度耗伤中气，故药以补中益气汤甘温为主，有风寒加表药、有停滞加消导、有火少加凉药。外感风寒则伤其形，脉多浮紧有力。作者借许学士医案说明辨脉为内伤外感之要，非另有一种情形。", ["虚", "大", "数", "细"]], "4152": ["病机", "伤寒十余日，身热而脉伏，乃邪热郁闭于里，阳气不能外达，脉道不利所致。脉伏主邪气内闭，非虚寒之候，故身热与脉伏并见，提示热郁深沉，须凭症辨治，不可骤补。", ["伏"]], "4153": ["病机", "发斑与蓄血均可出现脉伏，因邪热壅盛，气血郁滞，脉道不通。斑未出而脉伏，热郁未透；斑既透而脉伏，热毒内闭。吴又可脉厥用承气微下则脉出，与此用白虎类似，皆凭证以治，不可仅凭脉断。", ["伏"]], "4154": ["病机", "伤寒服凉药太过，阳气衰微，阴寒内盛，故身凉、手足厥冷、通身黑斑；六脉沉细，昏沉如尸厥，乃阳衰不能鼓动血脉。沉细主里虚寒，与心头尚温并见，为阴盛格阳之危候，故用参附姜温补回阳。", ["沉", "细"]], "4155": ["主病", "火酒郁热，面赤发斑而脉绝无，乃火郁热极，脉道壅塞；用栀豉汤加葛根、黄连清透，斑出脉见。另一案伤寒过经，遍体黑斑，唇口焦枯，脉大，便结，脉大主热盛邪实，故以三黄石膏汤清下。", ["大"]], "4156": ["治法", "发斑不可专以斑治，须察脉之浮沉以辨表里，病之虚实以定补泻。脉浮主邪在表，脉沉主邪在里；虚则补，实则泻。此条强调凭脉辨证，分别用药，为治斑之要旨。", ["浮", "沉"]], "4157": ["病机", "内伤发斑，脉大无力，因中气不足，气不摄血，故斑不透；阴证发斑，脉沉细无力，因阳虚寒盛，不能鼓动血脉。二者皆属虚寒，故用补中益气、真武汤温补而愈。若疫病壅塞，则脉实，当用下法。", ["大", "沉", "细"]], "4158": ["其他", "此条论伤寒变肠痈，引仲景《伤寒论》与高阳生《脉诀》之言，说明古诀之价值。原文未及具体脉象，故脉象要素为空。主旨在于提示肠痈之变证，不可不知。", []], "4159": ["病机", "积劳感寒，误用麻黄汤发汗，更伤阴液，致目赤鼻衄、痰中带血；脉虚数无力，乃劳倦阴虚，虚热内扰。数而无力为阴虚有热，虚为气阴不足。故以地黄汤滋阴，生脉散加葛根引邪外出，得微汗而津生。", ["虚", "数"]], "4160": ["病机", "脉来细软，细为阴血亏虚，软为正气不足。患者汗后津伤，舌燥无津、神昏沉寐、小溲全无，显系汗多亡阴，阴伤及气，气阴两虚。脉细软正合气阴耗伤之机，故以西洋参、生地、麦冬等益气养阴而获效，后脉和乃阴液渐复之征。", ["细", "软"]], "4161": ["病机", "脉六七至而弦劲，数为热盛，弦劲为邪实内结、热灼津伤。患者误汗误下后，烦躁口干、目赤便秘、腹胀喘急、舌苔黄色，显系阳明腑实、热结阴伤。脉数弦劲正是邪热亢盛、腑气不通之象，故急以黄龙汤下之，通腑泄热而安。", ["数", "弦", "劲"]], "4162": ["病机", "六脉俱无，乍有则甚细，此阳气衰微、鼓动无力之象。患者远行忍饥、相殴脱力，面赤口碎而脉微细，乃阳虚浮越、真寒假热。慎柔以阳虚从脉舍证，用附子理中汤冷服，脉渐有神，正合阳复之机。", ["细"]], "4163": ["病机", "六脉不至而独左寸厥厥动摇，乃邪郁阳遏、正气欲伸之候。患者伤寒七日，躁扰不宁、手足厥逆，脉伏而左寸动摇，知是欲作战汗，非真阳绝。故与热姜汤助汗，汗出则脉自复，此脉动为战汗之先兆。", ["动"]], "4164": ["病机", "此段论温热病谵语之病机，非专论脉。指出谵语有心阳素扰、热邪烁营、痰热蒙蔽等不同，强调脉难全恃，须合舌苔、胸腹、二便参断。虽未出具体脉象，然示人脉证合参之法，以辨虚实寒热之真谛。", []], "4165": ["其他", "此段评述伤寒注家得失，非论脉象。言仲景书经叔和编次或有差误，诸家注解互有短长，喻注分纲虽似井然，临证却难适用。强调初起须分营卫，过半月则难追溯，示人读注当知变通，不可拘泥。", []], "4166": ["预后", "脉已散乱，忽有忽无，状类虾游，此阴液枯竭、阳气浮散之危候。患者热证下痢脓血、舌黑而燥、夜多谵语，阳明热毒炽盛而阴已无。林氏勉与养阴，后脉接续分明、洪数鼓指，乃阴复阳伸、邪热外达之象，故喜曰今生。", ["散", "乱", "洪", "数"]], "4167": ["病机", "此段为按语，论前案脉类虾游之疑难。初时脉虚似虾游，若误作证实脉虚而用温补必死；末后狂热复发，若误作余邪注胃而用白虎、承气亦危。其得生在于养阴血痢止而脉即应指，脉敛而圆，示阴复之机。", []], "4168": ["病机", "原文未提脉象，而论温热病“发热不退”“痉厥昏蒙”“神清而忽间以狂言”等危候，强调“辨明虚实”为要诀。此属邪陷心包、神明欲迷之病机，非脉可凭，故脉象要素为空。", []], "4169": ["病机", "时疫两手俱伏，他医误作“阳证见阴”欲升提。壶仙翁指出“风热之极，火盛则伏”，伏脉非阴脉，乃热邪壅遏、气道不通所致，故用连翘凉膈取解。", ["伏"]], "4170": ["其他", "原文未出脉象，乃俞按语，指出瘟疫病当“以证为则，勿专以脉为凭”，强调脉证合参、不可拘泥于脉，故脉象要素为空。", []], "4171": ["病机", "疫证战汗前脉多伏，杂证痛厥、霍乱、食滞、痰凝等暴病“气道阻塞”亦多伏。伏脉主邪闭气阻，非虚寒，粗工误投温补致毙，故当以证为则。", ["伏"]], "4172": ["误治", "疫证误下后“左弦数，右洪数，但不充指”，弦数主热郁，洪数主阳明热盛，不充指示正气已伤，故知为误下坏证，邪陷挟热下利。", ["弦", "数", "洪", "滑"]], "4173": ["病机", "疫证头面肿盛，脉“浮弦而数”，浮弦数主风热上攻；服柴胡剂后“脉转洪大”，知邪传阳明，洪大主阳明热盛，故改方而愈。", ["浮", "弦", "数", "洪"]], "4174": ["病机", "素嗜酒者醉后受寒，面肿如匏，医误作大头瘟。沈氏诊“六脉细数，右更细软，略一重按即无”，细软微主虚阳上攻，非风热实邪，故断为虚寒。", ["细", "数", "软", "微"]], "4175": ["其他", "原文未出脉象，乃俞东扶辨析“中暍”与“中暑”之名，引《内经》以时令别病名，强调暑病有阴阳之分，非脉象可定，故脉象要素为空。", []], "4176": ["病机", "原文虽列脉迟小涩，但此段主旨是湿病治法，脉象仅作引子。迟小涩提示湿邪困阻气机，脉道不利，气血运行迟缓。湿性黏滞，故脉迟；湿阻气分，脉道不充则小；气机痹阻则涩。此脉象与文中“湿热作痞”“脘中阻痛”等症相应，说明湿邪内蕴、气机不畅之病机。", ["迟", "小", "涩"]], "4177": ["病机", "夜热脉数，的系阴虚；然脉伏且牢，浮取不应，说明热邪深伏于里，郁而不得外达。伏脉主邪闭，牢脉主内实，数脉主热，合而观之，乃阴虚内热、火郁于里之病机。故用升阳散火得效，仍以阴药收功，妙在芎、归合知、柏及从治之炒干姜，以透伏火、滋阴血。", ["数", "伏", "牢"]], "4178": ["病机", "六脉洪大，似属阳热亢盛，然症见身凉、水泻、小水绝无、腰腿足俱冷、腹痛如冰，此乃火郁于内、格阴于外之伏火证。火性炎上，故面目红肿、上热；火郁不能温煦下元，故下冷。洪大脉为火热内盛之象，然因郁闭，故外症反见寒象，此“热极似寒”之病机。", ["洪", "大"]], "4179": ["病机", "脉沉小带伏，沉主里，小主虚，伏主邪闭。症见昏晕、昏睡不醒、身凉不食，似阴证，然小便一二日不解，延至夜不醒，结合房劳内虚，乃虚热内伏、阴气将绝之候。沉小伏脉说明热邪深伏于里，阳气不能外达，故以冷水救之，大汗出而愈，此“热极似寒”之伏火病机。", ["沉", "小", "伏"]], "4180": ["病机", "六脉俱伏，遍体俱冷，无汗，三日不醒，似死证，然气未绝，此脉伏也，热极似寒耳。伏脉主邪闭，热邪深伏于里，阳气不能外达，故身冷无脉。以水湿青布放身上，一时身热，灌冷水而大汗出，说明内热炽盛，郁闭阳气，此伏火之病机，非真寒也。", ["伏"]], "4181": ["病机", "脾脉浮而弦，浮主风，弦主湿，又弦为肝脉。风湿外伤，肝木刑于脾土，而为洞泄、飧泄。浮弦脉象反映风邪外袭、湿邪内蕴，肝气偏亢，乘克脾土，致脾失健运，清浊不分，下利完谷。此脉与“利下物主浑白而完出”相应，说明风湿内侵、肝脾不和之病机。", ["浮", "弦"]], "4182": ["病机", "少阴病下痢，脉微涩，呕而汗出，必数更衣，反少者，当温其上灸之。微为阳气虚衰，涩为阴血不足，微涩脉说明少阴阴阳两虚，元气下脱，脾胃无凭，故泄泻。灸百会以升举下陷之阳气，使天之气复健行，脾土得以凭之，此“陷者举之”之治法，脉微涩正是元气下脱之病机。", ["微", "涩"]], "4183": ["病机", "脉甚弦涩，后转微弱略弦。弦主木旺，涩主气滞血瘀，微弱主虚。患者体素羸弱，情志不舒，木乘土位，治不中窾，煽动内风，故脉弦涩；久病正虚，脉转微弱略弦。症见暮热晡寒、舌鲜红、苔白口苦、溲短、吐水极酸，皆肝木犯胃、虚实夹杂之病机，弦涩脉正是情志不舒、木乘土位之反映。", ["弦", "涩", "微", "弱"]], "4184": ["平脉", "原文述两家闺女“渐渐厌恶粥饭”，仅略啖菱栗枣橘等杂食，然“形色不变，起居如常，六脉均平”，故断为无事。六脉均平即脉来和缓有胃气，无弦紧数促等异常，说明虽废粥饭而胃气未败、脏腑未损，病机不在脾胃虚衰，与绝食者不同，故不处方而许以无事。", ["平"]], "4185": ["其他", "雄按此案仅言夏月患疟，未详脉证，故无可辨之脉。其批评金坛用升散五种、苦寒三种，是使阴阳相离而非使邪与阴阳相离；邹润安亦言人身阴阳不可使之相离。后以枳桔汤加柴、芩、橘、半调其升降，使邪与阴阳相离而愈，说明治疟当重调升降、祛邪而不伤阴阳，非一味升散苦寒。", []], "4186": ["病机", "脉弦细而软，慎柔断为虚、暑、湿三因并存：弦细主虚主暑，软主湿。季夏瘅疟但热不寒、午后热躁谵语，是暑邪成疟；忽腹痛昼夜无间、勺水不进、疟发即厥，乃湿热乘虚内陷、气血壅滞之候。脉不洪数而反细软，正见暑湿伤中、正气已虚，故以芍药甘草汤缓急止痛、天水散清暑利湿，一剂痛失疟止。", ["弦", "细", "软"]], "4187": ["病机", "原文谓“脉象弦细而软，固属暑湿”，弦主肝木、细软主湿滞正虚，合为暑湿乘虚内陷之象；又言“其腹痛，恐兼肝木凌脾”，弦脉应肝，细软示脾土受困，故脉弦细而软既应暑湿内蕴，又提示肝木乘脾致腹痛，与湿热内陷、脾运失司之症相应。", ["弦", "细", "软"]], "4188": ["病机", "六脉虚数，虚为阴血不足，数为热，合之则阴虚内热。原文谓“阴虚而暑入阴分”，疟发于暮、热甚于夜，正属阴分受邪、虚热内扰之象。脉虚数而不洪大，说明非实热，乃阴亏不能制阳，故曰“最难治”。治先升举其阳，后以首乌、生地、龟板等滋阴，佐参、术益气，使阴复热退而愈。", ["虚", "数"]], "4189": ["其他", "原文为雄按评语，明言「脉证俱不载明」，故无脉象可辨。其议在疟疾因脉证缺失而「难以垂训」，并据用药推测「疟久邪入厥阴经」，又批评老姜每剂一两及用桃叶之陋，属对前人医案的评述，非论脉主病，故列其他。", []], "4190": ["病机", "脉虚而软，为阳气虚衰、阴寒内盛之象。虽外见寒热、口渴烦躁、舌赤唇焦、目赤足烙等热症，实属阴盛格阳、虚阳浮越之假热。脉虚软不任按，与面赤足烙、泄泻并见，正合戴阳证候。故沈氏断为真寒假热，径用参、附温补，一剂热定，旬余热退，反证脉象所主乃阳虚寒盛、格阳于上之病机。", []], "4191": ["病机", "此段论疟疾轻重与发作周期之关系，非专论脉。原文虽列脉不数、脉弦数或洪数、脉散、脉细软、脉多微弱、脉洪实等，然皆散见于他书，本段主旨为辨疟发渐早渐晏与寒热长短之病机进退。俞氏强调不可拘日作轻、间日重之说，当视寒热势甚与时短长；发渐早而热退不早则寒热加长、病进，发渐晏而热退不晏则寒热渐短、病衰，示人以动态观察疟势之法。", []], "4192": ["病机", "前诊气口脉虚，形虽困惫而脉虚，说明正气不足，脾胃虚弱，运化失司，故滞下痛作、绝不饮食；虚而兼滞，痰窒咽如絮，乃虚中夹实。朱彦修先补后攻，待正气稍复，再以小承气汤攻下积滞，药下咽觉所苦者自上下，正是脉虚为病本、积滞为病标之机。", ["虚"]], "4193": ["治法", "此段论许学士治伤寒太阳病尺脉不应，用黄耆建中先补后散；本案则先补后攻。虽未明言脉象，但以「尺脉不应」为眼目，说明脉虚为正气不足之征，故先补以扶正，后攻以祛邪。把握得定，故嫌疑不避，强调凭脉辨虚实以定治法先后。", []], "4194": ["病机", "两尺脉似有似无，两寸关弦数，小便短少。尺脉微弱为肾气不足，寸关弦数为湿热积滞壅于中上二焦，故痢下里急后重、白积兼鲜血、饮食减少。高果哉不从尺脉温补，而凭寸关弦数用清理湿热，黄芩、白芍、厚朴、槟榔等取效，说明脉象主湿热积滞而非虚寒。", ["弦", "数"]], "4195": ["预后", "六脉弦细欲绝，面有戴阳之色，所下瘀晦如烂鱼肠脑，噤口粒米不入，发呃神昏。弦细欲绝为正气衰微、阴寒内盛之脉，戴阳为虚阳上浮。张路玉谓「脉无旺气，气无喘促，体无躁扰，可进温补」，以脉不躁疾为可温之机，用保元汤温补，三服后痈毒贲起而安，说明脉象主虚寒，预后尚可。", ["弦", "细"]], "4196": ["误治", "此段为雄按语，强调痈毒滞下可用温补者，必见「六脉弦细欲绝」等虚寒脉证，才为合法。若不辨脉证，但崇景岳动辄温补，则杀人以刃与药无异。虽未列具体脉象，但以「此等脉证」指代前案弦细欲绝之脉，说明脉证合参方可温补，否则即为误治。", []], "4197": ["病机", "脉弦洪而数，或一二至、三四至、五六至辄一止。弦洪数为热毒炽盛、邪滞壅遏之象，歇止为毒邪内陷少阴、气血运行不畅所致。孙见心谓「毒及少阴矣，当急顾其阳明」，用生地、归、芍、丹皮、黄连等清热凉血养阴，服后洪数减、至数相续，说明脉象主热毒壅盛、阴血受伤之病机。", ["弦", "洪", "数"]], "4198": ["病机", "脉软不数，便鲜血、里急后重、时或不禁。脉软为正气不足、脾虚湿困，不数为无实热。前医以凉血药无效，叶天士用生苍术、厚朴、橘皮、甘草、鸡膍胵、砂仁壳、丁香柄丸服全愈，说明脉软不数主脾虚湿滞、气机不畅，非热迫血妄行，故以运脾化湿取效。", ["软", "数"]], "4199": ["病机", "案载脉洪大，不言有力无力，亦不载口渴、舌苔、小便。洪大为热盛之脉，但若虚寒证见洪大，则为阴盛格阳、虚阳外浮之象。俞氏质疑：若果有暑邪，五钱石膏、滑石岂能与大剂参、术、姜、附并取效？故脉洪大在此案当辨有力无力，若无力则为虚寒，温补乃对；若有力则属暑邪，温补反背。", ["洪", "大"]], "4200": ["病机", "左脉浮弦而数，浮为风邪外袭，弦主少阳疟疾，数为热；右软弱中部稍滑，示内伤饮食、脾运不健。原文谓“内伤饮食，外感风邪所致”，故脉象反映外感风邪与内伤食滞并存，疟痢交作，症见小腹痛、汗出、后重、口渴、发热等。", ["浮", "弦", "数", "弱"]], "4201": ["治法", "原文论疟痢并作初起治法，谓“右关脉大可加厚朴”，右关大主腑实邪壅，故加厚朴行气通腑；“右脉软弱为虚”，软弱示脾胃气虚，用药需顾护中气。此段以脉象指导发散、分消及补虚之治法选择。", ["大", "弱"]], "4202": ["病机", "六脉沉伏，沉主里、伏主邪闭，此因误用地黄汤滋腻，致中焦实而脾不运，阳气不能外达，故身强硬、目定口呆、气喘不能吸入。原文谓“病由中焦实，脾不能运耳”，脉沉伏正是阳气郁闭、脾运失职之征。", ["沉", "伏"]], "4203": ["病机", "脉细而弦劲带数，细为阴血不足，弦劲为厥阴风动，数为热。原文述斑出犯风遽隐，遂发痉，手足搐掉，浑身震动，时欲昏晕，显系厥阴风火内动、血虚筋急。脉弦劲带数正是风火相煽、筋脉失养之象，故治以寒热兼施、养血息风。", ["细", "弦", "数"]], "4204": ["病机", "原文未识脉名，然述小腹与腰急痛、紧挽外肾，引《经》云“小肠病者，腰脊控睪而痛”，断为小肠腑病。病由六月伤寒，太阳未尽，寒邪郁火入府，故痛作；待夏时火力全而血脉通，邪始去。此段重在阐明寒邪郁火、太阳入府之病机。", []], "4205": ["病机", "软缓脉主气虚，原文谓“惟汪公于软缓脉多以参、耆加麦冬、黄柏”，并言“陈皮加作七分，气即上冲，此尤气虚之显然者”。软缓为脾胃气弱、运化无力之象，气虚不能镇纳，故气从脐下上冲，治当补气培中。", ["软", "缓"]], "4206": ["病机", "两脉虚涩，虚为正气不足，涩为血少气滞；右尺独见弦急，右尺候下焦，弦急主浊气上逆。原文谓“此下焦浊气上腾，则胸中阳气不布，故饮入于胃，上壅而不下达”，脉象揭示下焦浊阴上逆、中阳不布之病机，故用调胃承气通地道。", ["虚", "涩", "弦", "急"]], "4207": ["病机", "原文未识脉名，然述“必是暴病，或便秘，乃从右尺脉印其机耳”，强调气冲证非皆属虚，亦有下焦浊气上腾之实证。右尺脉弦急为下焦浊气上逆之机，故治用通下宿秽、继培中气，示气冲证当辨虚实。", []], "4208": ["病机", "脉软滑微弦，软滑主痰湿内蕴，微弦主肝阳上扰。患者痰嗽气冲，少腹上冲至胸，迷闷如寐，面目发黄，身热足冷，肤痛拒按，皆痰阻气逆、肝阳上亢之象。脉软滑为痰湿，微弦为肝郁化火，故用开痰降逆、直泄肝阳之法。", ["软", "滑", "微", "弦"]], "4209": ["病机", "脉滑大有力主实痰实火，软大或细软主气虚痰多。眩晕有虚实之分，实者脉滑大有力，为痰火内盛；虚者脉软大或细软，为气虚痰湿。原文以脉辨虚实，实者用二陈、芩、栀，虚者用六君加耆、附，体现凭脉定治。", ["滑", "大", "软", "细"]], "4210": ["病机", "脉缓大重按无力，缓大为虚，重按无力为气虚。此脉主中气虚弱，但缓大中兼有微渴、大便四日一行，为虚中有热。故用参、耆、术补气，佐连柏丸清热，体现脉症合参、虚实兼顾之旨。", ["缓", "大"]], "4211": ["病机", "脉大而数，按之极软，大数似热，极软为虚寒。此乃中气大寒，虚阳外浮之假热象。患者虚损梦遗盗汗，羸顿已极，前服知柏芩连等苦寒，更伤中阳。李士材断为“中气大寒，反为药苦”，用归脾汤加肉桂、人参温补中气而愈。", ["大", "数", "软"]], "4212": ["预后", "脉大而数，按之极软，可温补，补后数脉退则愈，不退则仍不愈。若细而数，按之极软，则死期已近，温补无益。此以脉之大小软细辨预后，大数极软为虚阳可温，细数极软为阴竭难救，强调脉象动态变化对判断转归的意义。", ["大", "数", "软", "细"]], "4213": ["病机", "六脉数大，数主热，大主邪盛。患者发热干咳，呼吸喘急，两颊俱赤，服温纳之剂喘益急，显系肺肝蕴热，热邪壅盛。数大之脉正合实热之象，故用逍遥散加丹皮、苡仁、兰叶清肝泻热，热退则喘止。", ["数", "大"]], "4214": ["病机", "六脉不数，惟左寸涩而细，右关大而软。左寸涩细主心血不足，右关大软主脾虚气弱。患者劳心太过，吐血有痰，喉间如鲠，日晡烦热，乃思虑伤心脾。脉不数说明无实热，涩细大软正合心脾两虚，故用归脾汤补益心脾。", ["涩", "细", "大", "软"]], "4215": ["病机", "此条总结上两条，上条喜脉之数大，为实热可清；此条喜脉之不数，为虚证可补。二人俱系新病，一实一虚，脉象数大与不数形成对比，结合左寸右关异常，说明凭脉辨虚实、定治法之要。数大主实，不数主虚，尚易辨也。", ["数", "大"]], "4216": ["其他", "原文为雄按语，评述前两条凭脉论证虽有卓识而用药未尽善，未直接描述具体脉象，故脉象要素为空。此段主旨在于评论凭脉论证的得失，非论病机或主病，故归为其他。", []], "4217": ["病机", "脉细带数，细为阴伤，数为热郁。患者夏月咳嗽带血、寒热食减形瘦，显系暑热内郁、阴分受损。群医误作虚证，投二地二冬滋阴不效，叶氏以芦根、滑石、杏仁等清透暑湿而愈，正合脉细数主暑热伤阴之病机。", ["细", "数"]], "4218": ["病机", "脉虽弦数而兼软涩，弦数似热，软涩则示气滞血痹、络脉不通。症见痰嗽、寒热、左胁聚瘕、舌紫黯无津、溺涩便艰，皆由暑热吸受、滋补早投，致血痹气滞、升降失调。故断非虚损，乃实邪壅塞之病机。", ["弦", "数", "软", "涩"]], "4219": ["病机", "脉散主阳气动极无制、精血内夺。案中饮酒劳心，营气先伤，心阳下溜，肾阴不涵，络伤血溢，犹如飓风波涛，阳气散越而血失堵御。脉散正合阳气动极、阴不内守之病机，故治当静形体、宁神志，使阴平阳秘。", ["散"]], "4220": ["病机", "脉散时，雄按引申上损下损以脾胃为扼要。此人脾胃素弱，病前先有泄泻，故病后调理于天暑服生脉散时，独嘱便溏则停。脉散在此提示脾胃气弱、中阳不守，治损须顾护脾胃，不可概用滋阴补阳。", ["散"]], "4221": ["预后", "原文设问脉之数乎、大乎、有力乎？若脉至细数无力，兼便溏食减，则苦寒方不可用。细数无力为阴阳亏损之候，损怯证中阳虚易治、阴竭难治，譬盆花泥干根槁，一匙之水难望活。此段以脉之细数无力判断预后与用药宜忌。", ["细", "数"]], "4222": ["预后", "脉甚细数而兼弦涩，细数为真阴亏损，弦涩为络脉瘀滞。患者形瘦能食而脉象如此，雄按断为死证，后果然食后释箸而逝。杨氏亦云凡损症得细数脉无不死者，说明细数脉在虚损证中主阴竭难治、预后不良。", ["细", "数", "弦", "涩"]], "4223": ["病机", "左脉弦、右脉滑，两寸稍短。弦主肝郁风动，滑主痰浊内壅，寸短示上焦气机不畅。患者惊后晕厥、精神恍惚、咳嗽面青、不思谷食，先眷皆卒于瘵，孙氏断为传尸瘵证。脉弦滑短反映痰瘀阻络、肝风挟痰上扰之病机。", ["弦", "滑", "短"]], "4224": ["病机", "脉沉细而疾，沉细为阴亏于内，疾为虚阳躁动。原文谓消渴至冬添躁热、须裸袒置冰，乃“孤阳绝阴必死之证”，脉与证合，示阴竭阳浮、真阴不能维阳，故虽大寒之令而热更甚，属阴阳离决之危候。", ["沉", "细", "疾"]], "4225": ["预后", "久患虚嗽误投桂附，致喘汗大热、欲摇扇，脉洪数无序。洪数为阳盛之象，然见于阴竭之体且“无序”，是孤阳无根、欲飞越于外，非实热可比。原文断为“阴已竭，孤阳欲飞”，辞不治，脉象示阴阳离决之败兆。", ["洪", "数"]], "4226": ["病机", "脉洪大鼓指而按之如无，是外假热而内真寒，洪大乃虚阳浮越，按之如无则根本空虚。服温补后脉转微细如丝，正是虚寒真象显露，故以参附回阳而安。原文“内真寒而外假热”一句，正点明此脉主虚阳外越之机。", ["洪", "大", "微", "细"]], "4227": ["病机", "见证皆火象，惟气息沉沉欲绝为虚象，脉洪大按之如无，则知洪大为假热之浮焰，按之无根为内虚寒之本质。原文据此“决其内虚寒而外假热”，并强调服温补后脉当收敛，示此脉主虚阳外浮而非实火。", ["洪", "大"]], "4228": ["病机", "脉微无力、右尺伏而不起，尺脉沉伏主肾虚，微为阳气不足。原文谓“尺脉沉伏者，肾虚也”，日夜上下循环之热为“肾火之浮游”，子时足底大热为火归就下。脉示肾虚火不归元、虚阳游走之机。", ["微", "伏"]], "4229": ["其他", "此段为俞氏按语，评前案认作肾虚火不归元、大剂补肾寒因热用，与证极合而“与脉似有未合”，并叹其讲理取譬堪嘉惠后人。原文未出具体脉象，故脉象要素为空，主旨属对前案脉证关系的评述。", []], "4230": ["病机", "左弦大、右滑大搏指，弦大为肝胆火郁，滑大为痰凝。原文据“左右者，阴阳之道路”断为“肝胆之火为痰所凝”，因过思不决、木火不得通达而郁痛，夜甚为肝邪实。脉示肝火挟痰、气郁不通之病机。", ["弦", "大", "滑"]], "4231": ["病机", "左脉弦大、右脉虚大，弦大为肝火亢逆，虚大为暑伤元气。原文引“脉虚身热，得之伤暑”，又谓作文劳心、被怒伤肝、为暑所逼，致木火上升而眩晕呕血。脉示木火上冲、气逆血溢，兼暑伤气阴之机。", ["弦", "大", "虚"]], "4232": ["病机", "两关脉洪滑有力，为实热壅盛之象，非阴虚所致；右脉虚大，左脉弦大，合参则知虚中夹实。原文强调“服阴药胀更甚”，说明胀满由实邪阻滞，误补则增剧。右脉虚大主气分不足，左脉弦大主肝郁化火，故大剂清暑清肝取效，脉象揭示虚实夹杂、暑热内蕴之病机。", ["洪", "滑", "虚", "弦"]], "4233": ["病机", "左脉弦洪而数，右洪大，为饮醇积热于内、暑火外侵之象；弦主肝火，洪数主热盛，细数如丝则阴分已亏。原文谓“所服治痧诸药，无不香窜燥烈，诚如火益热矣”，说明燥烈助火，邪无出路，故气涌血随。脉象示热炽阴伤、邪实未去，亟需清解而非滋补。", ["弦", "洪", "数", "细"]], "4234": ["病机", "两尺沉实，沉主里，实主邪结，尺部候下焦，故决其少腹有瘀。原文“因瘀而蒸热，因蒸热而吐血”，说明瘀血内阻，郁而化热，热迫血溢。脉象从下焦瘀滞认得病根，故大下之而病根拔，脉证相应，瘀去则热除血止。", ["沉", "实"]], "4235": ["病机", "六脉短数，短主气损，数主热扰，吐后腹胀、呕酸、不眠，饮滚酒略可，原文断为“积血之证”。酒色邪阳伤正，肝不藏血，脾不统血，中气大虚，血不归络，积血中焦。脉短数示正虚邪滞，故先补脾胃以升阳气，使阴寒消而积血行。", ["短", "数"]], "4236": ["病机", "脉弦大而虚，弦主肝急，大主邪盛，虚主正伤，劳伤咳嗽失血后自汗喘乏，夜烦不宁，为气血两亏、肝脾失调。原文“左胁刺痛，按之漉漉有声”，乃瘀血内停，故先补血后消瘀。脉象示虚中夹瘀，治当兼顾，不可纯补纯攻。", ["弦", "大", "虚"]], "4237": ["病机", "脉弦大而虚，甚则脉散，散为气散不收，虚为血亏，弦大为肝旺脾弱。自汗喘乏，夜烦不宁，为气血浮越；胁痛因斗很，瘀血内着。原文“消瘀不补益，最为得法”，说明脉虽虚而形色壮实，瘀去则正自复，散脉示气耗，不可妄补。", ["弦", "大", "虚", "散"]], "4238": ["病机", "脉散为大气衰不能包固之象，原文以“地居太虚之中，大气举之”为喻，说明大气偶泄则水不安澜，人身亦然。无端吐血最重，因大气衰不能担护，如堤薄水漏、堤塌水决。脉散揭示正气涣散、血失统摄，非仅血热妄行，故治当固大气为主。", ["散"]], "4239": ["其他", "原文未识出脉名，仅言“脉证似虚似实，非寒非热，甚为难辨”，强调病源与用药法俱有精义，十年之病半月而愈。脉象模糊难辨，提示虚实寒热错杂，须结合症候与药后反应细审，不可执一脉定病性，故列其他。", []], "4240": ["病机", "脉两寸皆数，关弦而无力，尺洪滑左甚。数主热，寸数应上焦热；关弦无力为脾胃虚寒，木乘土；尺洪滑主下焦湿热。合症大便燥结、肠风脏毒，断为胃寒肠热之证，热在大肠而寒在脾胃，故以肠风脏毒药为君，养血裹之护胃气。", ["数", "弦", "洪", "滑"]], "4241": ["病机", "左手沉细，右手豁大。沉细为阳不鼓，因内伤寒凉太过，阳气不能外达；豁大为火浮于中，血不归络而虚阳外越。合肠风血下不止、头晕倒地，知非实火，乃寒凉伤中、阳衰血失所统，故用补中益气升阳举陷而愈。", ["沉", "细", "豁", "大"]], "4242": ["病机", "脉弦劲带数，弦劲为肝木亢盛、气机郁勃，数则为热。症见腹胀不思食、易怒，便血屡发，食减形瘦，乃劳神伤脾、肝火怫郁、热迫血下之机。前用逍遥不应，因木火炽而脾土已困，故转见口干咳嗽、溏泻肠鸣，虚象渐露。", ["弦", "劲", "数"]], "4243": ["其他", "原文未识脉名，仅言方与脉不相证对而竟得痊，则脉象必别有可据处。此段非论脉主病，乃提示临证当脉症互参，不可执方以疑脉，亦不可舍脉从方，脉象虽未明言，其可据之处正寓于疗效反证之中。", []], "4244": ["病机", "脉洪数有力为实热，洪数无力为虚热。洪数主热盛，有力则邪实，无力则正虚。溺血属热者多，胞移热于膀胱，故实热宜导赤加栀芩，虚热宜生地归芍。久不止则变虚，久病老年更可转虚寒，脉症合参以定攻补。", ["洪", "数", "有", "力"]], "4245": ["病机", "尺脉沉大，沉为气陷，大为虚张。自汗足冷不能行动，乃脾气下陷，肺失所养而汗出；足为脾肾经行之地，脾阳不舒，肾气亦郁，故冷。脉沉大非实热，乃中气下陷、虚阳不敛之象，故以补脾固肺为本，稍加桂温肾为标。", ["沉", "大"]], "4246": ["病机", "俞按自汗足冷显系下焦虚寒，尺脉当沉细，反见沉大，正见脾气下陷、虚阳浮张之机。粗工舍脉凭证则温补肝肾，凭脉论证则误认湿热，皆隔一层。沉大非实，乃中气不足、清阳不升所致，故当从脾肺论治。", ["沉", "细"]], "4247": ["病机", "六脉涩滞，涩主气机不畅、血行不利。胁痛吐臭痰恶心食不下，乃清气不升，浊气郁于少阳之络，上逆而为臭痰恶心；少阳清阳不升，肝不能散精，故食不下。涩滞正应浊郁络阻、升降失司之病机，故用柴胡升清、栀丹皮清郁。", ["涩", "滞"]], "4248": ["病机", "脉弦滑而数，弦主饮癖，滑主痰积，数主郁热，乃痰饮久积化热之象；痰积左胁，故嗽则左胁大痛，痰出甚臭。热郁于内，故发热谵语、溺赤便闭、口渴苔黄。后脉弦数而劲，劲为阴伤，乃痰热去而液耗，故舌光红少液，法当甘凉养液涵阴。", ["弦", "滑", "数", "劲"]], "4249": ["预后", "脉沉而涩，两尺尤甚，沉为在里，涩主精血亏少，尺部候肾，涩甚则精伤之象。醉而使内，汗出多痰，本已精伤，误服宽膈化痰之药更耗其气，故脉无根，涩象不减，主死期近。此涩脉非痰滞，乃精竭，故曰在法不治。", ["沉", "涩"]], "4250": ["病机", "此案六部沉涩，两尺尤甚，与梁厚斋尺脉浮大按之则涩者轻重自别。沉而细涩，按之欲绝，是脉法无根，精血内竭之候，故主死。若顾明华案亦系涩脉，然先补养后吐下仍愈，彼涩为痰滞，此涩为精伤，脉同而病机异，故生死不同。", ["沉", "涩", "细"]], "4251": ["误治", "原文未出脉象，然承前案而言汗出精伤、脉法无根，固是死证，而所用补中益气加半夏、茯苓等药，升补香燥，反耗其精，故曰不宜用此等药。此条论误治，强调精伤无根之脉，不可更投升散温燥，当以养液固本为要。", []], "4252": ["其他", "此条未详脉证，雄按亦云脉证皆未详述。然述秦景明痰饮久发，呕吐不食，病久结成窠囊，非大涌弗愈，先补后吐，七补七涌，百日窠囊始尽，终以六君子、八味丸收功。此示痰饮窠囊之治，攻补兼施，非凭脉可断，故归其他。", []], "4253": ["病机", "脉洪数有力，左独甚，六脉皆数，数非火而何？洪为火盛，数为热炽，有力为实。痰白本似寒，然脉数有力、胸腹如烙、喘急如雷鸣，皆火迫津液上沸为白沫，故痰白如银。此辨痰色不可专据，当合脉证，火盛灼津，故主实火痰喘。", ["洪", "数", "有力"]], "4254": ["病机", "脉象属虚，膈胀只在五更，余时不胀，显为虚证。虚气上逆，故用人参、鹿角之丸补之，佐茯苓、车前导下敛逆；粟壳、诃子蜜丸服于枕上，留恋胸膈以敛肺化痰。此脉虚主中气不足、肾气上逆，故用药丝丝入扣，皆从虚字着眼。", ["虚"]], "4255": ["病机", "左寸涩，右寸滑，按之如黄豆大且鼓指，关尺皆弦小，左尺迢迢有神。右寸滑为积痰郁滞于肺，左寸涩为痰阻气机，弦小主郁，故食后即大便，乃大肠之气不固。痰积上焦，肺失肃降，通调失职，故用吐法去上焦痰积，大便自实。", ["涩", "滑", "弦", "小"]], "4256": ["病机", "本案未载脉象，然述遗精日久，肾窍漏气如烟雾，形瘁骨痿，大便艰涩色黑，显系肾精亏耗、虚火内炽之候。初用苦寒导下暂快，久则愈导愈秘，因胆汁大黄苦寒、皂角刮削脂膏，反致求润弥燥，此即虚火未清而阴津更伤，脾胃渐败，故肌肉瘦削、眠食日减、胸膈痞闷、嗳气不畅，皆脾肾两虚、气机壅滞之征。", []], "4257": ["病机", "本条为按语，未出脉象，然强调湿痿与阴虚痿见证相似而病源迥异，须参脉色舌苔及便溺以别之。张承溪用术煎治骨痿，不认肾虚而认脾湿，正因湿痿亦见肢体痿弱，若仅凭外形则易混同。脉色舌苔之辨，正在湿则脉濡苔腻、阴虚则脉细数舌红，故曰自有分别，示人凭脉参症以分病机。", []], "4258": ["兼症", "脉至虚弦软滑，虚软为脾脏受戕、中气不足，弦滑乃肝火痰饮动扰之象。症见嘈杂便溏、肠鸣少纳，舌色淡而无液，正是脾虚失运、痰饮内停而肝火乘之。虽肝炎火动，然苦燥凉润皆不可投，故以参、术、甘草健脾，木瓜、薏苡、白芍、牡蛎柔肝化饮，竹茹、兰叶、茯神、橘红清化痰热，数剂而愈，脉症相合。", ["虚", "弦", "软", "滑"]], "4259": ["病机", "脉气口大而软，大为邪气有余或药气壅盛，软为谷气不足、中虚不运。李士材断为药气多而谷气少，且久服辛剂，辛能散气，可治表实而不可治中虚，可理气壅而不可理气弱。呕吐日久，中气已虚，辛散更耗胃气，故以半夏、人参、陈仓米、白蜜甘澜水养胃降逆，十剂而愈，正合脉软主虚之机。", ["大", "软"]], "4260": ["预后", "六脉俱无胃气，惟胃脉略缓，脾脉微缓。无胃气则真脏脉见，主胃气衰败；略缓微缓尚存一线柔和之象，故曰调理脾胃犹可迁延。胸前微痛无休息时，乃丹田阳气不到胸中，隔气无疑。保元汤加山药、沉香，补气温阳降逆，从脾胃缓图，正因脉尚微缓，预后犹可迁延。", ["缓", "微"]], "4261": ["病机", "本条论噎膈反胃之辨，未出脉象。反胃纳而复出，噎膈毫不能纳，噎则能纳而喉中梗塞，膈则全不纳谷。病源纷纭，叶天士主阴液下竭、阳气上结，食管窄隘；徐洄溪主瘀血顽痰逆气阻隔胃气。阴竭而阳结，故食管窄隘，此即噎膈病机之要，与虚劳阴竭阳不结者不同，须凭脉症细辨。", []], "4262": ["病机", "俞按三条治舌瘖，非喉瘖。次条伤寒神昏而瘖，案中不载舌干苔黑便秘烦躁，则神昏者身热人静默默耳，其脉必濡滑无力，参、芪、术服之数日病无进退，可知对证。濡滑无力为气虚痰阻，非实热传少阴。若脉带数则热象未清，然以濡滑无力为主，故全绘虚证情形，示人勿竟以热传心经儱侗为治。", ["濡", "滑", "数"]], "4263": ["病机", "本条未出脉象，论脾足太阴之脉连舌本，饥饱伤胃则贲门壅涩，劳倦伤脾则脾气陷而不升，不能为胃行其津液，故语言不能出。补中益气升举脾阳，则津液行而汗出周身，瘖亦遂愈。此以脾阳下陷、津液不布为舌瘖病机，与热传少阴之瘖迥异，脉当见虚软无力，可参前条濡滑无力之辨。", []], "4264": ["病机", "脉不数不虚，排除虚劳；右寸浮大而滑，右寸主肺，浮为风邪在表，滑为痰，大为邪盛，故断为风痰未解。久服酸收，痰邪被敛，故久而弥盛。治以麻黄、杏仁等宣肺化痰，五剂止，十剂全愈，证明病机为风痰壅肺，非虚损。", ["浮", "大", "滑"]], "4265": ["病机", "左关弦大，左关主肝，弦为肝旺，大为火盛；右寸下半指累累如意珠，右寸主肺，滑为痰壅。多酒多怒，酒助湿热，怒伤肝，肝火迫肺，痰壅肺窍致哑；肝火妄行，血不归经，故吐血溺血。脉象显示有余实证，非阴虚肺痿，故宜清热开郁化痰。", ["弦", "大", "滑"]], "4266": ["病机", "两手脉浮而洪，浮为风邪在表，洪为积热内盛；两关脉滑大有力，关主中焦，滑为痰，大为热。风邪闭郁痰火，怒气相加，迫血上逆，故咳血鼻流清水、喘急碍卧。脉大发热似惧，实为有余实证，非阴虚，故先驱中焦痰火积热。", ["浮", "洪", "滑", "大"]], "4267": ["其他", "此段为俞按评述，未直接描述脉象，仅言“论脉溯因”，强调前案通过脉象追溯病因、细心体察的巧思。无具体脉象要素可录，故脉象为空。主旨属医案评析，非主病或病机专论，归为其他。", []], "4268": ["其他", "此段为俞按评述，未直接描述脉象，仅评述所用诸方摄纳肾阳、温通督脉、疏刷肺气、开豁浊痰，标本兼顾，故宿疾全瘳。无具体脉象要素，故脉象为空。主旨属治法方药评析，归为其他。", []], "4269": ["病机", "两手皆滑大，两尺尤有力。滑主痰食积滞，大主邪实壅盛；尺部有力，说明下焦积滞未去。过食鳗肉卷饼，心腹胀痛，屡用硝黄、承气、十枣等攻下，大便不行，小便点滴，胀大如覆箕，脉象证实为宿食痰积壅塞肠胃之有余实证，非虚候。", ["滑", "大"]], "4270": ["其他", "此段为俞按评述，未直接描述脉象，仅论金液丹、神秘汤的运用，并言神秘汤乃生脉散合二陈汤加减，施于此证恰好。无具体脉象要素，故脉象为空。主旨属方药评析，归为其他。", []], "4271": ["病机", "脉虚大而数，虚为正气不足，大为阴火亢盛，数为热。怔忡善忘、口淡舌燥多汗、四肢疲软发热、小便白浊，皆思虑过度，心阴暗耗，厥阴相火妄动为害。脉虚大数非实火，故用补中益气汤、朱砂安神丸、小坎离丸补益心脾、滋阴降火而安。", ["虚", "大", "数"]], "4272": ["病机", "心脉独虚，肝脉独旺，怔忡不寐。心脉虚为心气不足，肝脉旺为肝阳偏亢，因惊惧而致，惊则气乱，心神不宁，故见怔忡不寐。治以养心阴、清肝火，补心丹常服全愈。", ["虚"]], "4273": ["病机", "本案未明言脉象，但述颠狂复发，发时抽搐、角弓反张、喊声闻外而心明白，止则神识昏瞀。此属肝风内动、痰火扰心之病机，前用清痰清火、补心、归脾皆不应，叶氏以脉辨治，未录脉象。", []], "4274": ["其他", "本条为俞按，评上条不用补、次条不用养阴，认证最清。若狃于归脾、补中、六味、生脉等成方，必致误治。强调辨证精确，不可拘泥套方，未涉及具体脉象。", []], "4275": ["病机", "左寸短弱，关弦大，右寸下半指与关皆滑大，两尺俱洪大。左寸短弱为心气不足，关弦大为肝经瘀血，右寸关滑大为中焦痰浊，两尺洪大为下焦湿热。据此中焦有痰、肝经有瘀血，故血淋窍痛，面热牙疼，渴饮冰水。", ["短", "弱", "弦", "大"]], "4276": ["其他", "俞按强调治淋有经权之法，皆审脉以辨。释“诊”为审，望闻问切四诊均须细审，非独脉也。此段论诊法之要，未出具体脉象。", []], "4277": ["病机", "两寸洪数，知为心火刑金。洪数为火热之象，两寸候心肺，心火亢盛，刑克肺金，肺失肃降，气化不及州都，故小便不通。用黄连清心火，人参、麦冬、五味补肺生脉，一剂而愈。", ["洪", "数"]], "4278": ["病机", "本案未录脉象，述冲暑理事、食冰浸瓜梨致泄泻，医以通利之剂，泻止而二便不通，脐下胀急，立解点滴不出，卧则流之不竭。此通利太过，中气愈陷，气化失司之病机。", []], "4279": ["治法", "脉实者用八正散倍大黄，脉沉实者用升柴二陈二术汤。实脉主邪实，沉实主里实，二便秘涩由脾胃气滞、痰饮食积阻碍浊道，故以通利攻下、升清降浊为治。形弱及老人病后产后则从虚秘治。", ["实", "沉"]], "4280": ["病机", "肾脉沉小而无神，沉主里，小主虚，无神为阳气衰微。肾司二便，肾阳不足则大肠传导无力，故大便燥结不通；胸膈塞闷而有食，亦由肾气不化、中焦壅滞所致。此脉说明病本在肾虚，非实热闭结，故用苁蓉温润补肾、枳壳理气宽肠而效。", ["沉", "小"]], "4281": ["病机", "原文未出脉象，然论“气错”与“血枯”病机不同：姜病成于渐为血枯，此起于暴为气错。气错既久，则血液不能循经而下润于大肠，致大肠燥结，转矢气从前阴而泄。此段辨气错致燥之机，非脉象所主，故脉象要素为空。", []], "4282": ["病机", "六部皆滑大有力，滑主痰，大主热盛，有力为实。痰热壅盛于中焦，上蒙清窍则头痛如破、晕倒不省人事；痰阻胸膈则饱闷、饮汤水停膈不下；怒起气逆，痰随气升，故脉滑大有力。此痰厥头痛之脉，主痰盛实热。", ["滑", "大"]], "4283": ["病机", "右关细涩，左关洪，左尺亦涩。细涩为下焦无阳、阴血不足，洪为阴火上冲。下焦阳虚，阴火上冲而齿痛头肿，故右关细涩、左尺涩；左关洪为肝火升腾。服羌活散火汤后脉渐粗大，是阳气下行；渐和则阳气已至恙所，主向愈。", ["细", "涩", "洪"]], "4284": ["病机", "此段未出具体脉象，乃总论头痛病因，分气虚、积热、肝火、肾虚、痰厥、阳升不降六种，又外因风、寒、湿、暑热，内因血虚、积食。因虽数端，靡不兼风。所论为头痛病机分类，非凭脉断证，故脉象要素为空。", []], "4285": ["病机", "脉沉细涩为据，沉主里，细涩主阴伤血少，弦主饮。原文谓“稍重则绝者，以细涩故也”，与阔大而软之虚寒不同。细涩示内有郁热或停饮，故虽似虚寒而实以湿热治，加黄连、滑石。凡脉弦细涩者俱不用温药，此脉主饮郁化热之机。", ["沉", "细", "涩", "弦"]], "4286": ["病机", "原文未出脉象，强调“还当以脉象别证兼参”，不可仅凭未申时痛厥即断为瘀滞膀胱而用峻药。此段主旨在于脉证合参、慎辨病机，非以脉象主病，故脉象要素为空。", []], "4287": ["病机", "两寸脉洪大，两尺沉微。寸洪大主上焦热盛，尺沉微主下焦阳虚。上热下寒，胃脘痛、胁胀、颧红唇红、食入即吐，为热壅于上；尺沉微示下元不足。阴阳汤调元明粉通降，痛减便行；后唇脸皆红，断有虫，以乌梅、川椒等安蛔而痛止。", ["洪", "大", "沉", "微"]], "4288": ["病机", "原文以“脉如循刀责责”形容小腹痛甚大汗之脉，责责如循刀刃，是紧劲之象，非真脏之散乱。紧主寒主痛，痛甚则气机收引、血行不畅，故脉道劲急；大汗则阳随汗泄，寒凝更甚。丹溪先温下、后加桃仁逐瘀、再入附子温阳，皆凭指下紧劲不散认定寒凝血瘀，非真脏败脉，故攻补有序。", ["紧", "数"]], "4289": ["病机", "原文分两层：尺脉沉实主下焦结粪，沉为在里，实为有形邪结，故断为燥屎内停；若死血内阻，则脉必涩，涩主血行滞涩。两尺绝无而能断结粪，是取脉之巧，非仅凭一途。沉实与涩对举，正示结粪与死血之辨，脉象不同则病机迥异。", ["沉", "实", "涩"]], "4290": ["病机", "跌伤有瘀本宜逐瘀，然丹溪见年老家贫、脉之散大，断为元气虚散，故先补后逐。散大之脉主正气耗散、元气不敛，瘀血虽存而元气已虚，若一味攻逐则正气愈败、瘀终不去。原文强调“元气果虚，则补药惟元气受之”，正说明散大脉示虚为本、瘀为标，攻补须辨虚实。", ["散", "大"]], "4291": ["病机", "脉伏于下、极重按之振指有力，是火热过极、反兼胜己之化，阳证似阴之候。伏为邪遏深沉，然沉取有力则非虚寒，乃实火内郁、阳气不能外达，故见腰膝异痛、四肢痿软而反畏热汤、小便当赤。原文以“振指有力”定其为实热，故用苦寒直折，热药反误。", ["伏"]], "4292": ["病机", "原文论瘀血腰痛，行瘀多用肉桂温通，此案反用知、柏，俞按推测“岂于脉中见相火之强耶”。虽未明言脉象，然以知、柏苦寒泻相火，可知指下必有相火亢盛之象，瘀血兼相火内动，故不用肉桂之温而取苦寒，示脉象决定用药之寒温。", []], "4293": ["病机", "脉皆缓弱无力，缓弱主脾虚气弱，故汪氏断为脾虚；左脉滑者，滑主血热，故知血分有热。脾虚则运化失职、湿浊下注而患白浊，血热则上攻眼目、下扰精室而梦遗。原文以“缓弱无力”定脾虚、“左脉滑”定血热，故用参、耆、苓、术益气健脾，黄柏、龟板清血热，虚实兼顾。", ["缓", "弱", "滑"]], "4294": ["病机", "原文论背暴痛之辨：脉浮紧为伤寒，浮紧主寒邪束表、太阳经气不利；脉沉缓为寒湿，沉主在里，缓主湿滞，寒湿留着经脉故痛。浮紧则用麻黄汤解表散寒，沉缓则用羌活胜湿汤温散寒湿。以脉之浮沉紧缓分表里寒湿，正是凭脉定病机、因机施治。", ["浮", "紧", "沉", "缓"]], "4295": ["病机", "胁下结硬如石，的系积块，脉之沉实有力，沉主里、实主有形邪结，故知积块非虚。若宗养正积自除而用参、术，则助纣为虐；戴人涌法起沉疴，正赖此沉实有力之脉，确认邪实可攻。原文以“沉实有力”定积块为实，说明切脉能辨攻补之宜，不可拘泥补虚之说。", ["沉", "实"]], "4296": ["病机", "左脉弦数，右关洪滑。弦为肝郁，数为热盛，洪滑主痰火壅盛。原文谓「热入血室」，又因「误服刚燥之剂而动痰火」，故左弦数示肝经血分热扰，右关洪滑示中焦痰火胶结。痰火与血热标本交作，故胸胁大腹作痛、谵语如狂、午后及夜痛剧咬人，皆痰火扰神、血热内结之候。", ["弦", "数", "洪", "滑"]], "4297": ["病机", "初诊脉沉细而涩，沉细为下焦元气不足，涩为血少不荣，故足胫痛三年，断为「不能荣养筋骨」。再诊脉兼浮数，浮为虚阳外浮，数为元气愈耗之象，故曰「元气愈耗矣」。脉由沉细转浮数，示虚损加重、根本日衰，与劳则旋作相应，故用滋补、人参膏渐壮元气。", ["沉", "细", "涩", "浮"]], "4298": ["病机", "原文未识脉名，以症论机。忧思不已则脾胃气结不行，饮食失节则脾胃气耗不足，中气一伤则四脏失所。阴气上溢于阳中，故面色黧黑不泽、环唇尤甚；水反侮土，黑色见于唇，为「阴阳相反，病之逆也」。心悬如饥、气短而促，皆中焦化源不足、冲和之气不能灌溉之候。", []], "4299": ["病机", "脉微弦而涩，轻重皆同。弦主气郁，涩主血少，合为「厚味成热，湿痰在膈间」。多食酸梅助湿热之痰随上升之气至头，熏蒸发根之血，血渐枯槁而发落。脉弦涩不因轻重而异，示湿热痰浊阻滞、血不荣发之机，故治以补血升散，湿热解则发长如初。", ["弦", "涩"]], "4300": ["病机", "肝脉弦滑，弦为肝气有余，滑为血盛，故断「非壅热也，乃年壮血盛，肝血并不通」。血盛而经闭三月，肝血壅滞不通，上攻于目则眼疼。此非外感风热，亦非虚损，乃血实闭经之候，故用通经药，经行而愈，示脉弦滑主血盛壅滞之病机。", ["弦", "滑"]], "4301": ["病机", "此段承上案而发议论。肝脉弦滑，弦主肝、滑主血盛，故不误作风痰眼病，而断为「血盛不通」。然俞氏指出孙真人犹须问宫人始得停经三月之信，说明脉弦滑虽示肝血壅盛，仍当合问诊以定经闭，不可仅凭脉断病。主旨在于脉证合参、不可讳疾困医。", ["弦", "滑"]], "4302": ["病机", "两寸关脉俱滑大有力，两尺沉微。滑大有力主中焦痰火壅盛，寸关应上中二焦，故曰「中焦有痰，肝胆有火」；尺沉微示下元不足。怒气触之，火性急速，气乘于络上而不行，故眼眦突生白疱、肿赤头痛；痰火冲上则呕吐眩晕。诸风掉眩属木、诸逆冲上属火，正合滑大之脉。", ["滑", "大", "沉", "微"]], "4303": ["病机", "脉小而数、按之无力，后又脉仍细数。小细为正气不足，数为热，无力为虚。耳游风本属风热壅络，然脉小细数无力示正虚邪陷之险象；复冒风邪则肿痛更甚、神昏谵语。及至咽喉腐烂、悬雍赤紫、手足厥冷、呃逆不止，乃热毒内陷、虚阳欲脱之危候，脉小数为虚热内扰而非实火。", ["小", "数", "细"]], "4304": ["病机", "脉虽软小，然病非格阳，故非死候。软小为气血不足之象，若误作阳虚而投温补，反致贻误。俞氏强调须辨病机，不可执景岳一说，阳证见阴脉方为死候，此案脉软小而病非格阳，当另求治法。", ["软", "小"]], "4305": ["病机", "原文未识脉名，然案中强调“脉象诊得的真”，可知凭脉辨齿痛之病机。齿痛数年，诸药不效，叶氏用酸咸下降之品引肾火归经，示病机为肾火上炎，脉诊当有相应表现，惜原文未载具体脉象。", []], "4306": ["病机", "左手三部平和，右寸尺无恙，独关部杳然不见。关候脾胃，怒则气并于肝，木旺克土，脾土受邪，故关脉不见。形色尪羸而神气安静，脾有积滞，目微黄，恐成黄疸，后果然，服茵陈利水平肝顺气而痊。", []], "4307": ["预后", "关脉不见，目中微带黄色，为脾有积滞发黄之候。俞氏引《金匮》疸病十八日为期，论黄退之难易以判预后：半月一月黄退则他病可治，久黄不退必复现他病致死。此条关脉不见而数剂得痊，示脉症相应、元气尚实者预后佳。", []], "4308": ["病机", "麻多在手足以四末气馁、卫行迟难到，故麻不兼木属气虚，否则风痰。脉浮而软或大而弱为气虚；脉浮而滑、按之不衰为风痰。若麻木兼作，则有寒湿、积痰、死血之殊，脉见沉迟滑实与沉涩而芤之分，各主不同病机。", ["浮", "软", "滑", "芤"]], "4309": ["病机", "左寸忽洪忽涩，迟数无定栖，因好饮冷酒，酒新性热燥，冷饮又犯寒湿，寒热相搏，遂致腿疼筋缩、寸步不能行。脉象乍洪乍涩、迟数不定，正反映寒热错杂、气血壅滞之病机，故以川乌、麻黄、苍术等温散寒湿、通络止痛而效。", ["洪", "涩", "数", "迟"]], "4310": ["病机", "体厚色苍，痛风膝热足冷，痛处皆肿，夜间痛甚，巅顶如芒刺，遍身躁热，小便赤涩，口不作渴，脉沉细带数。沉细为阳虚于内，数为热郁，乃寒湿痹阻、虚阳外浮之病机，故用芪、术、附、独活、细辛温阳散寒除湿而诸证痊。", ["沉", "细", "数"]], "4311": ["病机", "香为脾臭，香极则诸窍大开，关键尽撤，故脉缓筋弛、身软目瞪不食。脉缓为脾胃气弛、筋脉失束之象，非平和之缓。畀入土坎，取诸毒得土而化、四肢百骸得土气则生气自复，仍合治痿独取阳明之义。", ["缓"]], "4312": ["病机", "脉弦细而软，弦主气郁，细软主虚，合之则见脾气已虚而痰阻枢机。原文谓“补之太骤，痰阻枢机，气郁不舒”，故脉不任重按而现软象，非真痿症。四肢痿痹、目瞪不语皆痰气壅塞所致，与弦细软脉相应。", ["弦", "细", "软"]], "4313": ["治法", "此段未出脉象，专论以药对脉、独取阳明之法。首案连用承气，继以参汤送寒下，末案补中益气与大黄补泻不同，总归取阳明。虽无脉可凭，然“以药对脉，确切不移”点明治法必依脉证，非泛论也。", []], "4314": ["病机", "脉必弦数，弦为风动，数为热盛，合之乃热甚生风之象。原文谓“头目如蒙，入夏阳升为甚，议清营热以息内风”，正因弦数脉主肝热化风，故专理上实而不顾下虚，待他日再诊滋填下焦。", ["弦", "数"]], "4315": ["病机", "脉三部虽强，而细涩不流利，细主阴亏，涩主血滞，合之则为阴虚血少、脉道不利。原文作阴虚治，用四物加知、柏、元参、丹皮而愈，并谓“阴虚似肝积”，说明细涩脉非真积，乃阴亏使然。", ["细", "涩"]], "4316": ["病机", "两尺脉洪盛，尺部属肾与膀胱，洪盛为邪实火旺之象。原文以此诠解“肾气传膀胱”之论，谓非此则人皆面墙。洪盛脉主下焦实热，故用桂、附、河车同补肾药善后，紧切不泛。", ["洪", "盛"]], "4317": ["主病", "脉浮大而长，浮大主积，长主气有余，故曰“脾有大积”。然两尺按之软，示下元不足，不可峻攻。攻积后脉转大而虚，按至关部豁如，是积去正虚之征，故以补中益气调补而痊。", ["浮", "大", "长", "虚"]], "4318": ["病机", "脉浮大而长为脾积之脉，与丹溪诸案之沉涩小、微短涩、涩弱等脉大不同。原文强调须以古人各种脉法为正鹄，又须参以色形病情，如两尺软为虚则不可峻攻，两尺洪盛则又当别论，不可执一。", ["浮", "大", "长", "涩"]], "4319": ["病机", "脉大而数，大为虚，数为热，合之则虚而有湿热。原文谓“腹痛呕涎，面色痿黄，此虚而有湿，湿热相兼，虫乃生焉”，故以大数脉主湿热生虫之机，当先下虫积，虫不去则补无益。", ["大", "数"]], "4320": ["病机", "右关脉豁大，关候脾胃，豁大乃脾虚湿盛、痰浊内壅之象。原文谓肝木乘脾、脾虚生痰不生血，右关豁大正应中焦湿痰壅滞，故用乌药磨服、附子制透以温运行积，积行后以补中益气、六君子收功，皆从脾虚湿痰着眼。", ["豁", "大"]], "4321": ["治法", "本条虽列脉弦而数，实借脉以论消积峻剂之戒。弦主积块坚结，数主郁热，然原文重点在桃仁煎、黑神丸等峻厉之剂不可妄试，丹溪每与补药迭进、轻重曲折适至病所，故脉弦数示积热内结，治当攻补兼施而非轻尝峻药。", ["弦", "数"]], "4322": ["病机", "本段未出脉名，专论肾间动气为人之根本。动气即命门真火，生长元气、煦燠元阴，盈亏得于先天，非药石可扩充。壮年无病而阳痿多夭，少年虚损而阳痿死至，皆动气早衰；若以兴阳药强求御女，则速其死。", []], "4323": ["病机", "尺脉洪数，尺候下焦，洪为湿热壅盛，数为热象。脱肛肿痛出水，形实好酒，正是湿热下注而非气虚下陷，故用樗根白皮、川柏清湿热，诃子、没石子、鳖头灰收涩举脱，与补中升提之法迥异。", ["洪", "数"]], "4324": ["病机", "寸关脉滑有力，滑主痰食，有力为实。辰时气血注胃，胃满连及上焦故寸关俱滑；午后惟关脉滑，独显胃实。原文断为怒火食积郁成湿热，上则饮停、下则瘀阻，实证似虚，故主消痰消食、破气破血兼清湿热。", ["滑", "有力"]], "4325": ["其他", "本条辨无脉与反关脉。反关脉多洪大且可推动，乃脉离其部位，非病也，故不足审病情；丹溪治久疟食少经闭两手无脉者，因病因致脉伏，药后食进脉出、经行脉愈，是因病无脉而非向来无脉，二者当别。", ["洪", "大"]], "4326": ["病机", "本段未涉脉象，专辨天癸非月事。引经云女子二七天癸至、任脉通、太冲脉盛，男子二八天癸至、精气溢泻，谓天癸乃天一真水、精血源头，男女皆有；受孕大约两情欢畅、百脉齐到，天癸与男女之精偕至入任脉成胎。", []], "4327": ["病机", "脉大而无力为气虚确据，麻属气虚，气虚不能摄血则崩，故参、耆必用；左脉举之略弦，似有风邪，少加荆、防。原文批评借司天运气张大其说反觉浮泛，强调凭脉断气虚崩漏、以补气摄血为主。", ["大", "无力", "弦"]], "4328": ["病机", "右关洪滑主痰热壅滞中焦，左寸洪数乃心火亢盛，两尺洪大示热势下迫血海。脉洪滑数大，说明痰热内蕴，流滞血海，与误服安胎药致滞、血去多而神昏、痰迷心窍诸症相应，故夜半咬牙乱语、手心热、口噤肢冷，皆痰热蒙蔽心包与胆经之象。", ["洪", "滑", "数", "大"]], "4329": ["病机", "原文未出脉象，俞按强调“察脉审证”，着眼在昏冒胀闷等证，非血去多而犹不止。此段主旨在于辨析病机：虽崩中血去，但不可拘泥脱血益气，当从痰瘀壅滞论治，脉证合参，方不致误。", []], "4330": ["病机", "脉沉而结，沉主里、结主滞，示蓄血内结、气机壅塞。因怒经止，血随气滞，蓄积不散，壅塞隧道，溢而妄行，故崩中不止。脉沉结正是瘀血内阻之征，与“汛至而怒”病史及崩证相应，故用桃仁、大黄决壅去滞，使血归经。", ["沉", "结"]], "4331": ["治法", "原文未出脉象，雄按强调“察脉辨证，而后议治”，反对泥执暴崩宜补之成说。此段主旨为治法原则：治病须脉证合参，若但执暴崩宜补，必致酿成锢疾，提示临床不可拘泥成说而忽视脉象。", []], "4332": ["病机", "六脉俱数主热，左寸滑大示心火挟痰，右关搏指为胃热壅盛，左关软弱乃肝血不足。孕五月血大下，脉数滑大而弱，说明虚火内扰、血热妄行，与午后发战、寒热头痛、腹中硬块、所下血块甚多相应，故先以清热养血，继用补中益气加味。", ["数", "滑", "大", "弱"]], "4333": ["病机", "脉象细软，细主血虚，软主气虚，示气血两虚、脾失健运。恶露不下而用参、术、归、附等药得下者，必脉细软、口不燥渴、内不烦热，方为合治。此段以脉象细软为凭，说明虚证当补，不可妄行攻伐，与平昔怯弱、胎堕后连服行血药之病史相应。", ["细", "软"]], "4334": ["病机", "脉近虚，虚主气血不足。难产伤力、悲戚晕厥后，恶露绝无，参粥壅塞膈上，致神昏瘛疭。脉虚说明正气已伤，然痰食瘀血壅塞为实，故先探吐痰饮粥药，继以消瘀化痰。此段脉虚与神思迷昧、手足瘛疭相应，示虚中夹实之病机。", ["虚"]], "4335": ["病机", "原文未出脉象，俞按评述前半段治法不难，探吐法尤捷；后半段恶露稍行神思即静，昏乱不息仍是畜血形状。此段讲脉与面色极是，但产后谵语昏狂有纯因于痰者，不可不知，强调脉证合参、辨明痰瘀。", []], "4336": ["病机", "脉右大于左者三倍且数，右脉主气分，大为邪盛，数为热，示产后瘀血内结、郁而化热，故小腹块痛、发热、不思饮食；后脉大无绪，为瘀热壅盛、气血逆乱，势急，故见腹胀、便闭、鼻衄、渴热，主瘀热内结之危候。", ["大", "数"]], "4337": ["病机", "脉两手沉涩兼结，沉主里，涩主血少气滞，结主邪气内结，合之示产后气血虚而伏邪内结，故神昏、胸满痛、咳喘发热；前医误补敛邪，脉更不舒，改透邪散结则脉稍舒，明邪结于中、非虚寒可比。", ["沉", "涩", "结"]], "4338": ["病机", "左脉芤涩，芤主血虚，涩主血瘀，左脉候心肝，因惊致心包络积血，血瘀而气机不畅，故身飘、旋转、持身不定、四肢酸软，似虚而实为瘀血内阻，下瘀血如漆者遂愈，即大实似羸之例。", ["芤", "涩"]], "4339": ["病机", "左脉之芤，为血虚而瘀之象，左候心包，故断为心包积血；人但见惊悸虚羸，不知因惊致瘀，瘀血内阻而现虚象，若不辨芤脉则误补，此案示脉象为辨瘀血之关键，非纯虚可补。", ["芤"]], "4340": ["病机", "脉来微细数有七至，微细为阴阳俱虚，数为虚阳外越，七至为疾，示产后疹后泻利，阳脱于上，故神昏、但欲寐、语言颤怯、热渴，少阴证据，属阳脱危候，急温回阳，非热证可清。", ["微", "细", "数"]], "4341": ["病机", "原文未识脉名，俞按不凭脉象而度病机，谓痰与血交涌而上，败血随痰上升，才侧身便壅绝，显系痰血上壅；然必血气脾胃大虚，败血方能随痰上逆，故用六君合犀角、失笑散，补虚与消瘀痰并行，恰对病机。", []], "4342": ["病机", "两手脉皆缓弱，缓弱为脾胃气虚、湿邪内蕴，非风热实邪，故前服蒺藜、荆芥、升麻、葛根等疏散风热反伤脾胃，饮食顿减、发疮痛痒；脉缓弱示病本在脾虚湿滞，故用六君子汤加减健脾化湿而愈。", ["缓", "弱"]], "4343": ["病机", "原文未识脉名，杨曰指出前药虽治此证，服之益甚者，因未审脉象，故与体气相违；强调脉象为辨体气虚实之要，不凭脉则药证相违，病反加重，此条总括前案，示脉诊在辨证中的关键作用。", []], "4344": ["误治", "右寸关脉浮数，浮为表，数为热，似属外感风寒化热。然前医发表后反咳喘食少，此乃脾土亏损，不能生肺金，虚阳外浮之象。若更通利，复耗精液，必致肺痈吐脓。脉浮数在此非实热，乃脾虚肺损、虚火上浮之征，故王宇泰以益气汤补脾生金而愈。", ["浮", "数"]], "4345": ["病机", "左关沉微而缓，右部浮，沉微缓为下焦虚寒、奇经失固，右浮为阳升于上。经漏百日，淋带不止，乃冲任督带不能固摄，病在下焦。血凝成块非血热，食减胃衰，补中益气仅升脾营，滋阴反碍胃气，故先以震灵丹直达冲任固摄。", ["沉", "微", "缓", "浮"]], "4346": ["预后", "脉百至，数促而芤，数促为阳亢气逆，芤为阴血大伤。劳损数年，大汗泄越半载，下焦损伤，冲脉之气震动，诸脉皆逆。胃气戕害，谷食大减，大便不实，生阳不发，入冬可虑。此阴损及阳、胃气将败之候，急固散越之阳，预后堪忧。", ["数", "促", "芤"]], "4347": ["小儿", "稚年纯阳体质，热症最多。病偏右胸高，呼气不利，肺气不能清肃，热郁内蒸，逆传膻中，致天君震动，状若痫症。此肺热壅塞、营卫失和所致。不及周岁，脏腑柔薄，苦寒沉降及腻滞阴药俱在禁例，仍从上治，令上气下行为顺，使营卫两和。", []], "4348": ["病机", "脉小右弦，小为阳虚，弦为寒饮内动。呼吸不利，喉中有声，入夜神迷昏倦，少腹微胀，二便不爽，筋骨如针刺，身重难转侧，皆暴寒入内，阳气痹塞。老年肾真衰乏，水液化痰上泛，寒中少阴，太阳膀胱气化失司，浊气升痰饮逆，最忌喘急神昏，故以小青龙通营卫、开痰饮。", ["小", "弦"]], "4349": ["治法", "尾闾尻骨先痛，继以溲溺淋闭，兼有血瘀。督脉隶于太阳脉络，气坠频溺、点滴不爽，分利清热愈痛，此督脉气陷、瘀阻下焦之证。古贤以柔剂温药升任督之气，按经旨治病，当以温升任督、活血通淋为法，不可一味分利清热。", []], "4350": ["病机", "新产不满百日，天暑汗出气泄，澡浴汤蒸更助开发，阳浮上升，阴弱莫制，遂喉痒咳逆，牵连左胁及气街背部皆痛。产后肝血未充，肾液未足，奇经诸脉悉皆怯弱，阴亏阳炽，血不荣筋。法当味厚质静，流护至阴，兼温奇经，仿阿胶鸡子黄汤。", ["怯", "弱"]], "4351": ["病机", "足厥阴肝经过胃贯膈，上循喉咙。肝阴少藏，阳气有升无降，每交暮夜咳甚如哕，戍亥肝阴旺时肝阳扰胃，阳明脉衰，四肢倦怠，面色青晦。阳化内风，掀越鼓动，为肌浮偏肿。心无液养，似嘈非嘈，似痛非痛，热酿涎沫。治当流护至阴，静制风阳内鼓。", []], "4352": ["病机", "原文未明言脉象，但凭脉论症，述胃痛吐蛔、不纳、口味酸浊、躁热头汗等。病机为胃伤困乏，清阳不司旋运，清浊乱于中，上下不宣，状如关格。肝痛犯胃，攻涤寒热药更伤胃气，故治以大半夏汤宣通清气。", []], "4353": ["病机", "脉左数微弦，寸尺关虚数。数主热，弦主肝郁，虚为阴血不足。肝郁成热，热迫气逆血瘀，肝阴不充，肝阳易动，升多降少，阴不和阳，胃津乏上供涵肺，故燥痒咳呛、吐涎沫、纳少肢软。肝阳逆乘，实系肝阴不足。", ["数", "弦", "虚"]], "4354": ["病机", "脉刚而数，刚为邪实坚劲，数为热。暑湿久伏，与时气秽邪凝合，酿成胶腻之痰，闭塞清明之府，胃家浊液蒸遏不宣，故神呆目定、烦躁呓语。湿位之下燥气乘之，湿转为燥，舌苔黏腻。先滋液以洁烈焰之燔。", ["刚", "数"]], "4355": ["病机", "脉沉而微，沉为里寒，微为无阳。舌白似粉，泻起口渴，身体卧著痛甚，少腹浊阴凝聚为疝瘕。阴邪盘踞，必以阳药通之，归、地护持血液反与阴邪树帜，当以纯刚药直走浊阴凝结之处。", ["沉", "微"]], "4356": ["治法", "原文未出脉象，承前诊阴寒盘踞少腹，非纯阳刚剂直入坚冰之地，阴凝不解。医易肾气汤阴多阳少，立见病加反至不食，药不对症。仿通脉四逆汤法，以纯阳刚剂破阴凝。", []], "4357": ["病机", "脉络空乏，为阳气日薄，阳明络虚，不能束筋骨流利机关。肩痛肢麻、头目如蒙、行动痿弱无力，下虚上实，络热内风沸起，入夏阳升为甚。渗湿利痰不应病，议清营热以泄内风。", ["空"]], "4358": ["病机", "原文未出脉象，述下体痿躄，先有遗泄湿疡，频进渗利阴阳更伤。长冷阳微，饭后吐食，胃阳顿衰，卫外失职。下焦病属精血受伤，两投温通柔剂，通摄兼施。胃府主气，气得下行为顺，吐后停下焦血分药，用扶阳理胃。", []], "4359": ["病机", "脉已虚，长夏湿热，经脉流行气钝，下元络脉已虚，痿弱不耐步趋，常似酸楚，大便或结或溏，都属肝肾为病。益下必佐宣通脉络，乃正治之法，恐夏季后湿热还扰，预为防理。", ["虚"]], "4360": ["病机", "脉沉而缓，沉主里、缓主虚，合之寝食如常而独两腿内外肉脱麻木，知非外感三气，乃年逾五旬阳脉渐衰、𫏋维不用事，阳气不充于脉络，故脉沉缓而肢体失养。", ["沉", "缓"]], "4361": ["病机", "原文未出脉名，然述肾厥由腰脊而升，发时手足厥冷、口吐涎沫、喉如刀刺，显系阴浊自下犯上，循足少阴经脉上循喉咙挟舌本而致，病机为阳不通、浊阴上逆，故以通阳泄浊为主。", []], "4362": ["病机", "疟得汗不解，竟夜汗出、胸痞不饥、形瘦便秘而脉大，大脉见于久疟汗多液耗之后，非实热壅盛，乃阴虚体质、疟邪烁液，清阳痞结脘中，液亏而脉道不敛，故议柔剂存阴却邪。", ["大"]], "4363": ["病机", "脉微而迟，微为阳衰，迟为阴盛，色衰萎黄、久利久泻穷必伤肾，今浮肿渐起目下，是水失火而败，命火式微不能暖下，水气泛滥。若徒见泄泻有红而作脾胃湿热治，必至中满败坏。", ["微", "迟"]], "4364": ["病机", "脉左弦右浮涩，左弦为肝木怫郁，右浮涩为脾土自困、清浊混淆。始由脘痛贯胁，继则腹大高凸、纳减便艰，乃有年操持萦虑太甚，脏真日漓、府阳不运，胀势乃成，故治以通阳为务。", ["弦", "浮", "涩"]], "4365": ["病机", "脉缓弱，缓弱为脾胃阳微之象，脘中痛胀、呕涌清涎，正是脾阳不宣、运化失职，得之积劳伤阳，午后病甚乃阳不用事。故温补极是，而守中腻滞非通府所宜，勿佐用之。", ["缓", "弱"]], "4366": ["病机", "脉来小缓，按之不鼓，小缓为正气不足、非邪实之征。身腴过劳伤阳，呕吐食物、身热无头痛，非外感风寒；间日烦躁渴饮、唇焦舌黑，是内伏热气由募原流布三焦。脉不鼓指，可验其非停聚积滞，故宜甘寒滋养胃阴。", ["小", "缓"]], "4367": ["病机", "脉弦数右大，弦为肝病，数为热，右大为气火亢盛。舌绛面微浮、咳呕上逆、心中热、腹中气撑、暮夜内外皆热，病因忧愁嗔怒，诸气交逆，少火化为壮火，五液皆涸，内风煽动，病属郁劳，难以久延。", ["弦", "数", "大"]], "4368": ["病机", "脉百至为数，右弦数左细微，示邪热入阴，厥阴热炽犯阳明。热迫血妄行故咯血、经水反多；热郁气逆则寒热无汗、呕逆、头痛、目胞紫暗。脉数主热，弦主厥阴，细微为阴伤，故云伏邪在至阴，必熬至枯涸，治宜咸苦清伏热护阴。", ["数", "弦", "细", "微"]], "4369": ["病机", "右脉平和而左寸关弦动甚锐，左属肝心，弦动为木火内炽、肝阳独行。面色赤、体清癯为木火之形，操持烦虑则五志阳炽，火动伤阴，魂不藏而寤多寐少、眩晕自生。脉象示阴不协阳、内风不熄，故治以益阴和阳兼和肝阳。", ["弦", "动"]], "4370": ["病机", "脉弦数主厥阴风木化火，热自内起。情怀抑郁则肝郁化火，侵削阳明，气血内蒸，血海无贮，故腹膨便泄、目泪、经来身痛而渐至经闭，延为干血劳。弦为肝郁，数为热胜，示久郁热胜、正气已亏，治当酸苦泄热为先，和补胃气为佐。", ["弦", "数"]], "4371": ["主病", "脉小无神，为脾胃中气不足之象。少年面青黄、自幼频呕，明是饮食寒暄不调，中气亏虚，运化失职，故咳嗽非外感，乃内伤及肺，不宜疏泄。脉小无神正合虚证，主以小建中汤建中气，中气立则呕咳自平。", ["小"]], "4372": ["病机", "原文未及脉象，然自觉热蒸、不梦自遗，皆奇经虚也。任督分行身之前后，奇经空虚则不能约束，故热蒸而精自遗。辛温颇效而六味加五味不应，因方药仅达下未能约束奇经，故议聚精固摄之法，以固奇经。", []], "4373": ["病机", "脉弦促而芤，弦主肝郁，促为阳动气泄，芤为阴血内虚。望色萎黄少膏泽、纳谷不旺，病已数年，脏阴内虚，阳动乃溢，故春夏阳升气泄、情志不适则血溢上窍。心主血、脾统血、肝藏血，三脏阴亏，治以归脾汤加减和肝脾之阴。", ["弦", "促", "芤"]], "4374": ["预后", "服白通加人尿猪胆汁汤后，脉不微续，仍三五参差，是阳未回、脉气不能接续之象。浊阴蔽塞，舍通阳别无别法，今脉尚参差，故云尚非稳保，议用四逆通脉方以冀阳回脉续。脉微续为生机，不续则危，此段重在预后判断。", ["微"]], "4375": ["病机", "原文未出脉象，而论疟久邪结必成疟母。邪深客阴络，道路深远，故肌肤无汗、能食不运、便溺通调，病不在府；从腹下升逆贯胁腰，推及八脉中病。此奇经痹阻、下焦不通之机，故忆仲景转旋下焦痹阻例以通阳。", []], "4376": ["病机", "原文未出脉名，以“清空溃散”“浊蒙蟠聚”“中无砥柱，木横浊攻”论病机。厥阴风木久侵，阳明胃土伤疲已极，中虚失运，浊阴上蒙，故胸腹胀满、腰痹肌膜浮肿。此属虚症，非有余，故不可呆钝补阳，议通阳明兼泄厥阴，使中土有砥柱而木不横逆。", []], "4377": ["病机", "原文未出脉名，以“眼胞上下，脾肾之脉循行”“倦于开合，太阴脾脉已钝”立论。眼胞属脾肾所主，开合倦怠乃太阴脾脉钝弱、中气不运之征，故甘补为宜。此从经脉循行与症候推断脾虚病机，非据脉象。", []], "4378": ["病机", "“脉弦右大，弦则为饮，大则胃阳已虚”，弦主饮邪内停，右大主胃阳不足。操持积劳伤阳，阳虚则痰饮气逆因虚而聚，故不饥不食、腹鸣气震、四肢痿弱、晨寒足冷。长夏湿土乘脾，虑肌肿腹胀，议通补胃阳为主、疏肝为辅。", ["弦", "大"]], "4379": ["病机", "“脉得右大，来去不整，左部小促”，右大而来去不整，左小促，非少阳伤寒之象。良由小产阴气不复，阳气上冒，故耳聋身热不寐、语言謇涩。阳冒于上、阴亏于下，恐有牵搐暴厥之忧，不可轻浅视之。", ["大", "促"]], "4380": ["预后", "“脉右大，能纳食”，引《金匮》“男子脉大为劳，极虚亦为劳”。大乃烦劳气伤，虚乃情欲致损，二者皆属劳。秋暑失血、初春再发而脉右大能食，说明胃气尚存，故断“安静一年可愈”，以脉症合参判其预后。", ["大", "虚"]], "4381": ["病机", "原文未出脉名，以“少阴脉循喉咙，挟舌本，阴乏上承，阳独自灼”论内因之嗽。肾坎中真阳主封蛰，阴亏不能上承则阳独上灼，病由别经干连及肺，徒治肺无益。肉消形瘦，桂附刚燥，宜温养柔剂、血肉有情，取斑龙加青盐引下。", []], "4382": ["病机", "“脉弱细不调，视色神采不振，兼以呼吸带喘”，弱细不调主中阳衰微、气血壅滞。夏月气泄，饥饱劳疫伤中，宿饮蓄久，气壅血瘀，故胀满、吐瘀、便污。六府以通为用，久病淹淹不敢攻劫，议通三焦阳气、驱锢蔽浊阴，温补兼进。", ["弱", "细"]], "4383": ["病机", "原文未出脉名，仅言“脉神如昨”，而胸满胀更急、鼻尖冷甚、热汗出、吐瘀便垢、神衰吸短，显系阳微浊僭、格拒不通。上下交征当理其中，然理中守剂不能治剧，故护阳通阳仍参苦寒，使浊阴泄一分则阳复一分，安谷之理在焉。", []], "4384": ["病机", "脉数右小左大，数主气机急促，右小示气分不足，左大示血分壅滞。原文谓“奇经冲任二脉为他经之气所束”，气机日钝，血少贮蓄，故经来渐迟、色淡而少；气滞则暮夜腹痛䐜胀、腰髀酸楚。若加暴怒，气逆血沸，须防经漏沸溢。脉象反映冲任受束、气血失和之病机。", ["数", "小", "大"]], "4385": ["病机", "原文未出脉象，然述“寒入厥阴之脉，结为气疝”，痛则胀升、气消无踪，乃寒凝肝脉、气机结聚所致。老年下元已亏，不可破气攻疝，尿管痛或阻溺，系下元虚寒、气化不利。治以温养下元、佐通窍，紧扣寒凝气结、本虚标实之病机。", []], "4386": ["病机", "原文未出脉象，述寒少热多、胎攻冲心痛、上呕青黑涎沫，乃疟邪化热，从四末渐归胃，冲脉属阳明，邪热无由发泄，内陷迫胎，势必坠胎。协热自利，外邪从里而出。热炽壅塞，人参、胶、地反为热邪树帜，故以纯苦气寒、酸苦辛泄两经热邪，外以井泥护胎。", []], "4387": ["病机", "原文未出脉象，言“形脉已衰，当以虚论”。操持思虑，五志阳气有升无降，肝脉绕阴器，气逆拂乱，不司疏泄，故似疝如淋。肝病三法辛酸甘缓，然经云食酸令人癃，小便不爽，大忌酸味。病机为肝气虚逆、疏泄失职，本虚而标实，治当从虚论。", []], "4388": ["病机", "脉必搏大无偏，搏大者阴不敛阳、冲气上逆之象。面赤亮、肌肉瘦削，乃肾精肝血内耗，阴不和阳，冲任不主把持。久损不复，当以味厚质静或血肉有情填实精髓，静养加餐，使精生于谷。肝肾久伤累及八脉，阴伤渐干及阳，非一法可网罗。", ["大"]], "4389": ["病机", "原文未出脉象，述室女神志时惑、月事不来，引《内经》“二阳之病发心脾”。气逆血菀，经纬紊乱，日加郁痹，故聪明清旷失职。情怀致病，草木无情，不易奏功。病机为心脾郁结、气逆血菀，冲任不通，治以上清心窍通神、下调奇脉通经。", []], "4390": ["治法", "原文仅“复脉汤去姜、桂”六字，未出脉象。复脉汤即炙甘草汤，去姜、桂之辛温，留其滋阴复脉之功，适用于阴血亏虚、脉结代或虚数之证。此条属治法，示人据脉证化裁，去温燥之品，专事滋养以复脉气。", []], "4391": ["误治", "原文未出脉象，述冒暑远行，热犯上中，分走营卫为寒热。疟疾当淡泊饮食、清疏胃气。奈何发散不效，复肆行滋补，致肺气壅闭、胃中凝滞，一身气机不通，变成肿胀。病久形消，正气垂寂，不可攻逐，不得已用保和丸缓疏中焦，使府气先通，经脉之气自通。", []], "4392": ["病机", "原文未明言脉象，但述“少腹瘕聚，冲气攻心，呕吐逆上，喉间闭塞”，此乃冲脉气逆、瘕为血痹之象。下焦多血病，症属气聚，病在冲脉，兼及阴维阳维。经水半年不来、寒热越日，皆奇经失和、气血痹阻之征，故病机在冲脉与血痹气聚。", []], "4393": ["病机", "脉缓按之濡弱，缓为脾脉，濡弱主气虚湿滞。谷少不食、厚味运化迟、痛泻、肤腠麻木、骨软筋痛，皆气弱阳微、脾胃少运、湿郁生痰之候。暴风骤冷不安、肛红入夏愈，亦阳虚湿郁、气机不灵之征，故脉症合参为气弱阳微、痰湿内阻。", ["缓", "濡", "弱"]], "4394": ["病机", "原文未出脉名，然述女子四十九天癸当止，阳明脉衰、冲脉力怯，不能聚血于血海。今带淋、肌麻血阻，腰腹甚于他处，是脏阴内损及八脉，有形血去、无形气掀，诸窍百骸攻迫。此阳气独行不得、真阴眷恋之病机，法当介潜咸降酸收。", []], "4395": ["病机", "脉空虚，为产后八脉空虚、气血不复之象。寒在四肢背部、热在心前腹中，即阳虚外寒、阴虚心热之旨。产后气虚自阴分伤及阳位，精虚则气亦虚，故脉空虚而见寒热错杂，治当补精化气、填补奇经散亡。", ["空虚"]], "4396": ["病机", "右弦左濡，弦主肝郁，濡主脾虚湿困。久痔注血致纳食难化，脾营先伤、胃阳继困，府气不宣而大便不爽。温补不能通调，疏滞更损生阳，故东垣治土先达木，不宜过投燥剂，仿治中汤佐疏肝解郁，此脉症示肝郁脾困、府气不畅。", ["弦", "濡"]], "4397": ["病机", "脉百至而左小涩结、右弦大，小涩结为阴液枯槁、气痹血涩，弦大为浊阴渐阻、清阳不升。高年中焦阳微，脘窒纳少，下焦阴枯，溺少便涩，正合噎膈反胃阴枯阳结之机。此无形情志致伤，非痰气瘀血有形可比，故难调理。", ["小", "涩", "结", "弦"]], "4398": ["病机", "右弦左濡，弦为饮，濡为湿。秋凉宿饮上泛咳呛，入夜气冲胃脘、心悸震动，背寒，皆饮属阴邪乘暮夜窃发之征。仲景论脉弦为饮，当治饮不当治咳，故以通阳涤饮为法，用小青龙减麻辛，此脉症示饮邪内伏、阳气不布。", ["弦", "濡"]], "4399": ["病机", "原文未出脉名，述频因小产奇脉不固，经多带下，晨便溏滑，纳谷日少，心悸震动。养血滋腻即脘闷不思纳，是自下焦损伤渐及中焦，脾胃不能转运。奇脉不固于下，中阳困于上，故拟妙香散宣通补中兼顾下，再议中宫宣通、下焦固摄两法分治。", []], "4400": ["病机", "原文谓“产后八脉皆空”，脉空为气血大虚之象，因产育损伤，非一脏一腑之病，故诸恙并起。虚损内因，药饵难效，腹胀洞泄、胁腹㽲痛皆由虚而发，脉空正示根本已亏，病机在虚损。", ["空"]], "4401": ["病机", "原文未出脉名，然述“病久反复，精气损伤，遂成虚怯”，脐下闪闪升触、逆干咳嗽、痰多咽痹，显系“元海无根，冲脉气震”，阴精内枯，阳失眷恋。病机为下元虚衰、冲气上逆，非草木汤液可久持。", []], "4402": ["病机", "脉来浮数，退而细涩，浮数为阳热上扰，细涩为阴血瘀滞。原文谓“肝司藏血，怫郁则血菀于上”，升降混淆为厥，面黄唇白、神昏、目𥉂舌缩、瘛疭，皆瘀热内闭、肾水竭绝、肝虚风动之暴厥病机。", ["浮", "数", "细", "涩"]], "4403": ["病机", "原文未出脉名，述情志郁勃、气逆多升、络血上冒，连次小产则冲任已怯，心嘈震悸、目珠痛、头胀，显系“肝胆厥阳动极”。病机为郁怒引动肝阳，冲任不固，血随气逆，防倒经，治当养肝阴兼通冲脉。", []], "4404": ["病机", "质瘦脉弱，交夏真气发泄，津液因热而伤，致浮阳动搏。心热口渴、头痛胁疼、食下如噎、右耳气闭、语言多而齿戛寒噤、巅胀面浮，皆津伤阳浮之候，脉弱正示气液不足，故议甘凉生津和阳。", ["弱"]], "4405": ["预后", "温邪内迫，经水淋淋不断，二便不通，唇舌俱白，神呆谵妄，脉细小欲绝。时当阳极泄越，阴未复，神魂不摄，原文断为“亡阳昏谵，最属危脱之象”，脉细小欲绝正是阴阳离决之危候，故用救逆法。", ["细", "小"]], "4406": ["病机", "原文未出脉名，述经停两月，嗔怒致阳气升降失和，血随气行，冲任不固而为崩漏，血凝成块非血热。病机为气逆血脱、奇经不摄，故强调“血脱必须益气”，又非升柴所宜，须固摄奇经。", []], "4407": ["病机", "原文未出脉名，述风木司天、阳升之候，五志气火交并于上，肝胆内风鼓动，上盛下虚，故足膝无力；风火乘胃，唇舌麻木、肢节如痿，为中厥之萌。病机为内火召风、上盛下虚，治以苦降辛泄佐微酸。", []], "4408": ["病机", "左脉小弦动数，右手和平略虚，示阴虚阳亢、内风旋动。小弦为肝阴不足、阳扰化风；动数主热，热则真气泄越，故见头晕、流泪、舌生红刺、微咳有痰；足痿无力乃“痿生大热”，热耗津液，风阳升上则下焦无气，故治以补肝肾摄纳、清上安下。", ["小", "弦", "动", "数"]], "4409": ["病机", "原文未识脉名，然述“阳但上冒，阴不下吸”，情志菀结、冬温阳气不潜，交春阳勃然化内风，游行扰络，清窍蒙而舌喑，皆阴虚阳亢使然。阳激则汗泄、不寐、焦烦；肝风犯阳明，暴食自救，胃脉不复则气不振、不束筋骨，鼻准光亮、肌肉浮肿，总属虚风内动。", []], "4410": ["病机", "原文以“脉络之虚”言病机，非具体脉名。嗔怒动阳，春木司升，厥阴内风乘阳明脉络之虚，上凌咽喉、绕耳后，升腾太过则脂液不营四末而指节麻木，为痱中根萌，下虚上实多致巅顶之疾。肝为刚脏，非柔润不能调和，故忌芩连苦降、羌防辛散。", []], "4411": ["主病", "脉濡无热，主阴风湿晦中于脾络。濡为湿象，无热则非火化，湿晦蔽其清阳，致右肢偏痿、口㖞舌歪、声音不出。更因寒滞汤药蔽阻清阳，清气不展。法宗星附六君子汤，益气攻风祛痰；若风中廉泉属任脉病，与太阴脾络有间。", ["濡"]], "4412": ["病机", "脉空旷、脉络交空显然，为素禀阴亏、冲任奇脉空旷之象。春交地中阳气升举，虚人气动随升，络血失养，诸气横逆，故痛从腿肢筋骨上贯心胸，面赤如赭、饥不欲食、耳失聪、寤不成寐，皆阳浮络空使然，先和阳治络。", ["空", "虚"]], "4413": ["病机", "脉弦小数，弦为肝风，小为阴伤，数主热。操持积劳，阳升内风旋动，烁筋损液，故形体日瘦、肩背掣痛、肢节麻木、肤腠瘙痒、目眩耳鸣、口舌麋碎。古谓壮火食气，皆阳气之化，先清血分中热，继养血熄内风，安静勿劳可免痿厥。", ["弦", "小", "数"]], "4414": ["病机", "原文未识脉名，然述“冲脉不静，脉中气逆混扰，气燥热化，风阳交动”。操持怒劳内损乎肝，少阳上聚为瘕，厥阴下结为疝，冲气上逆则少腹气冲至心、竟夕不寐、头眩目花、耳内风雷、四肢麻痹、肌腠如刺如虫行，营液日耗，总属肝风之害，非攻消温补能治。", []], "4415": ["预后", "脉细劲，细为阴亏，劲为风木刚强。平昔肠红阴络久伤，左胁宿瘕，形瘦面青，阴虚阳冒，血络不静，诸阳并而为厥，冲气犯胃为呃，症似蓄血为狂。然脉细劲、咽喉皆痛，乃真阴枯槁、水液无有、风木大震之象，刚剂强镇不能息其厥冒，预后堪忧。", ["细", "劲"]], "4416": ["病机", "原文述‘脉上左部稍振’，未及具体脉象，然据‘水亏。木中风动’及‘下元不司收纳’，可知病机为肾水亏虚，肝阳化风内动。左脉稍振乃阴亏阳浮之兆，非实火，故见左牙痛、目恙，治当温养柔和，忌辛散助阳。", []], "4417": ["病机", "左脉细数而劲，右数大而虚，乃肾精肝血内亏，水不涵木，阳挟内风。细数劲为阴亏阳亢，虚大为中气不足。肝风从左升，冲心则晕厥消渴，犯胃则饮食引动肝肠，病延六七载，阴损已极。", ["细", "数", "劲", "虚"]], "4418": ["病机", "脉小濡而缓，小濡为肾气不足，缓为湿滞。结合右痪舌喑足痱，乃肾纳失司，肝风震突。濡缓不主流动，舌下经脉涩滞，故舌强难言。病起耳后暴肿，兼温热客气，清上轻扬后肿减，治仿地黄饮子浊药清投。", ["濡", "缓"]], "4419": ["病机", "脉右涩大，涩为营血内耗，大为胃逆不降。木火升腾，阻遏清阳，故头重脘痹、耳鸣咽痹、食纳久留。少阳木火盛于寅，犯阳明而上凭诸窍，熏蒸日炽，营血耗无以养心，故寝不肯寐、心摇荡漾。", ["涩", "大"]], "4420": ["病机", "左手三部弦大而坚，为肾藏阴伤、壮火食气；右手浮缓，气口微滑，为痰沫壅塞于鬲。清阳之位被痰气占据，侵及心主，故神识不清、语言错误。此肾气不能上通于心，心藏虚热生风，非燥药所宜。", ["弦", "大", "坚", "滑"]], "4421": ["病机", "原文未出具体脉象，仅言‘脉由阴渐损及阳明胃络’。长夏久热伤真阴，深秋收肃而身中泄越已甚，吸短精浊、消渴眩晕皆肝肾见症。阴损及阳，纳谷减、肢无力，乃阴伤及阳，损症难复。", []], "4422": ["病机", "脉数垂入尺泽穴中，数为阳亢，垂入尺泽为阴精不足、阳失潜藏。阴精未充早泄，龙相内灼，升腾面目则肺受熏蒸、嚏涕交作；胃弱少谷，精浊下注则溺管疼痛；肝阳吸肾阴，善怒多郁，显然肾虚。", ["数"]], "4423": ["治法", "原文未出脉象，言‘少壮精气未旺，致奇脉网维失护’。经云形不足温气、精不足补味，今纳谷如昔，血肉充养，故以饮食补之。此段主论治法，以味补精，非主病脉。", []], "4424": ["病机", "原文未明言脉象，但述“离散之态”“精衰气竭之象”，指精气内夺、阳微畏寒，神气无以拥护，故见行步欹斜、健忘若愦。此非外邪，乃内伤虚损，冬令藏阳之时阳微尤甚，属精气离散之危候，预后不良。", []], "4425": ["病机", "原文未出脉名，然述“阴精走泄于下，阳气郁冒于上，太冲脉衰，厥气上冲”，致陡然痫厥。此阴阳失交，阳随上冲而泄，故治从阴引阳、大封大固，以蛰藏为要，属虚阳上浮、精竭气逆之病机。", []], "4426": ["病机", "虚劳三年，形神大衰，每咳必百脉动掣，乃损伤已极、二气致偏，非草木可振。脉动掣反映气血虚极而脉失和顺，症见食减、便溏、寒热、胁肋攻触，皆病深传遍、脾胃衰败之象，故暂用理阴煎镇逆固摄。", ["动"]], "4427": ["病机", "脉左小右虚，背寒肌冷、痰多微呕、食减不甘，此胃阳已弱，卫气不得拥护，故时作微寒微热。左小右虚反映营卫不足、中阳不振，非实邪，当建立中气以维营卫，偏热偏寒皆非正治。", ["小", "虚"]], "4428": ["病机", "诊脉数左略大，症见足痿、盗汗、梦遗、脊椎凸出，乃先天禀赋怯弱，肝血肾精受戕，奇经八脉乏运用之力。脉数大非实热，是精血内损、虚阳外浮之象，病在筋骨，内应精血损伤。", ["数", "大"]], "4429": ["病机", "脉右劲，因疥疮频浴致卫疏易伤冷热，皮毛内应肺，咳嗽痰多、食不甘、便燥结，胃津日耗不供肺，秋燥上加，渐成老年痰火。脉劲主气燥津伤、肺胃燥热，治宜清气热润燥，畏虚滞补反益枯燥。", ["劲"]], "4430": ["病机", "久咳三年，痰多食少，动则息鸣如喘，脉左搏数右小数，自觉内火燔燎。此五液内耗、阳少制伏，非实火。搏数小数反映虚阳躁动、阴不敛阳，故治以滋水益气，勿损胃为上，治嗽无益于体病。", ["搏", "数", "小"]], "4431": ["病机", "寡居烦劳，脉右搏左涩，气燥在上，血液暗亏。右搏为气燥于上，左涩为血少不濡，由思郁致五志烦煎，非温热补涩之症。晨咳吐涎，从胃治，以血海亦隶阳明，反映气燥血亏、郁热伤阴之病机。", ["搏", "涩"]], "4432": ["病机", "左弱右搏，左主血右主气，弱为虚损，搏为气逆不降。久虚交春不复，夜卧气冲咳甚、行走喘促，是下元根蒂已薄、冬藏不固、春升生气浅少，冲气上逆。故急当固纳摄下，若以辛凉理嗽则更伤下元，致不救。", ["弱", "搏"]], "4433": ["病机", "原文未出脉名，以症测机。肾精下损则阴气上乘、浮阳上灼，故咽喉痛痹、咳嗽喘促；下焦元海不司收纳，冲脉之气上冲为病本。润剂治嗽仅暂减咳，实酿病祸阶；今胃弱便溏，非治嗽可疗，当固真纳气、培扶胃口。", []], "4434": ["病机", "忧愁思虑内伤不足，先损心肺，营卫二气既亏，故不耐烦劳、易受邪。今血止脉耎，耎为虚软无力，形倦不食、呛咳不已、吐痰黏涎，皆土败金枯之象。养正则邪自除，不可麻桂劫散，急与甘缓补法。", ["耎"]], "4435": ["预后", "溃疡流脓经年，脉细色夺，细为阴血亏少，色夺为精血不荣。声嘶食减、咳嗽喉中梗痛，皆漏损脂液、阴失内守、阳失外卫所致。肺痿之疴，本虚难复，故谅难全好，属预后不良之判。", ["细"]], "4436": ["预后", "脉微弱为阳气衰微，面亮载阳乃虚阳浮越，呃逆胁痛、自利，先曾寒热下利，加以劳烦伤阳，高年反复，三焦俱见症，乃欲脱之象。微弱之脉与欲脱相应，故议从中治，急固中阳。", ["微", "弱"]], "4437": ["病机", "食伤肠胃，复病呕吐、发呃下利，诊两脉微涩。微为阳气衰微，涩为阴血滞涩、阳气不运，故断为阳气欲尽、浊阴冲逆。前医姜附杂入耆归牵制，后方代赭重坠又混表药，总属不解，今危急舍理阳驱阴无别法。", ["微", "涩"]], "4438": ["病机", "脉搏劲为气逆脉痹、周行不畅，舌干赤为津伤有热。频吐胃伤，诸经之气上逆，填胸聚脘，出入机逆，故嗳气不展、状如呃忒；肌肉著席而痛转加，是脉痹不通。辛香燥药不受，先议治肺，以肺主一身气化。", ["劲"]], "4439": ["病机", "毒药熏疮，火气逼射肺金，致咳呛痰血、咽干胸闷。诊脉尺浮，尺候下焦，浮为阴气不藏、虚阳外浮，故虑病延及下而成虚损。姑以轻药清上焦、解火气，使火降而阴得藏。", ["浮"]], "4440": ["病机", "脉数涩小结，数主火，涩主血滞，小主阴伤，结主气滞血瘀。原文谓“痰血经年屡发”，因五志过动，相火内起肝胆，操持郁勃动灼，致络血上渗混痰火。此脉示火郁痰瘀互结，非精血损怯，故仍能纳食应酬。若木火劫烁胃伤，则病日加。", ["数", "涩", "小", "结"]], "4441": ["病机", "脉左细右劲数，左细为肝肾阴血亏虚，右劲数为气分火旺。原文谓“纳食不充肌肤，卧眠不能著左”，遇节令痰必带血，是阴血伤延及气分，虚火灼络。损症五六年无攻病之理，脏属阴，议平补足三阴法，节劳安逸可带病永年。", ["细", "劲", "数"]], "4442": ["病机", "原文未识脉名，然述“下有冲突逆气，血涌如泉”，乃肾精肝血不主内守，任脉失担任，冲阳上冲莫制，阳翔为血溢，阳坠为阴遗。腰痛足胫畏冷，皆精夺下损现症。治宜质静填补，重著归下，莫见血投凉，勿因嗽理肺，使元海立基，冲阳不犯上。", []], "4443": ["预后", "原文未识脉名，但言“形色与脉，日现衰惫”，系生气克削。操持怫郁，五志阳动，失血咳呛有年，性情内起之病，草木难安。虑春半后地气升，阳气泄，久病伤损，里真少聚。冬春天冷主藏，总以摄补足三阴脏，扶持带病延年。", []], "4444": ["病机", "脉坚，形瘦久咳失血有年，食物厌恶，夜寝不适。坚脉主阴液亏而虚火内亢，服七味八味从阴引阳不效，此液亏不受桂附之刚。当温养摄纳其下，兼益胃津以供肺，培本为要，不可再投刚燥。", ["坚"]], "4445": ["病机", "右脉长大透寸部，长主阳亢，大主火盛。春分阳气正升，情志之动，厥阳上燔，咳震动络中而失血。食物不欲纳，寐中呻吟呓语，由至阴损及阳明，精气神不相交合。长大透寸示厥阳上逆，议敛摄神气法。", ["长", "大"]], "4446": ["病机", "血大去则络脉皆空，脉弱濡涩，弱濡为气伤，涩为血少。肢节微冷，气伤上逆，若烟雾迷离熏灼喉底，故作呛逆。秋分寒露天气降而身中气反升越，里不肯收摄，虚象何疑。上焦宜降宜通，下焦宜封宜固，安谷崇土。", ["弱", "濡", "涩"]], "4447": ["病机", "原文未识脉名，述忧思怫郁，五志气火内燔，烟辛泄肺，酒热戕胃，精华营液为热蒸化败浊。阳络伤则血外溢，胃络受伤。阳明脉络日衰，背冷右胁酸痛，咳吐不已，胃土愈惫，肝木益横，厥阳愈逆，秽浊自下泛上。中焦胃困，有升无降，壅阻交迫，故著左卧眠。", []], "4448": ["病机", "原文未明言脉象，仅述‘脉不和’，指络脉气血失和。冬藏失司，辛散苦寒误治，致大气开泄，见恹恹衰倦、呼吸有声、胁肋窒痛、咯呛紫血，乃络脉不和、气机壅滞之候，久则关格上下交阻。", []], "4449": ["病机", "脉数左坚，当夏阳气方张，嗔怒引动肝阳勃升，络血上涌。左坚为肝阳独亢，数为阴亏生热。虽血止而咳逆欲呕、眠不得欹左，乃木失水涵、肝阳左升太过，非客邪实火，故宜甘缓制急。", ["数", "坚"]], "4450": ["病机", "脉左弦右小濡，起于忧郁化热，蒸迫脉络，血上溢而凝结成块，离络留瘀。左弦主肝郁，右小濡为气分不足。血后纳食如昔，腑络贮富，漉漉有声乃火气旋动，非有形实邪，治当清阳络、治其因。", ["弦", "濡", "小"]], "4451": ["病机", "左尺微动，右关前动数，尺带数，乃阳不潜伏、冲脉升动之象。心烦劳神，五志皆动，当寐时气机下潜触阳升，络血随咳呛上溢；行走喘促亦助气火。上实下虚，治宜益水生金以制君相之火。", ["数", "动"]], "4452": ["预后", "脉细小如无，素多郁怒，经来即病，冬患胃痛咯血，寒战面赤，惊惕头摇，四肢逆冷，显是肝阳变风、络血沸起而真气衰微。脉细小如无为正气欲脱，故引《内经》肝病暴变之文，势岂轻渺，用镇阴煎制阳逆就下。", ["细", "小"]], "4453": ["病机", "原文未识脉名。胁膈懊𢙐不舒，呕逆带血，因中年操持耗血，血不和气，气攻入络，络中聚血，瘀著为患。病状难以自明，治宜宣通血分以和络，俾不致瘀著，可免噎膈反胃。", []], "4454": ["误治", "脉左动数，尺不附骨，为肾精肝血内夺、弱阴不恋阳，冲阳上逆。前医见血投郁金姜黄韭汁制大黄逐瘀，是误作有余实治，损者更损。咳呕嗳、寒热汗泄皆阴不藏阳之候，当填实下隙，藉有情之属。", ["动", "数"]], "4455": ["病机", "脉左数微弦，寸尺关虚数，乃肝郁成热、热迫气逆血瘀，体质肝阴不充、肝阳已动。左升多右降少，阴不和阳，胃津乏上供涵肺，故燥痒咳呛、吐涎沫，纳少肢软。肝木犯胃，治先理脾胃，俾土厚不為木克。", ["数", "弦", "虚"]], "4456": ["病机", "右脉弦主饮邪内停，左脉濡示阳气不布。秋凉外袭引动宿饮，饮为阴邪乘暮夜上泛，故咳呛气冲、心悸震动。仲景谓弦为饮，背寒为饮，治当通阳涤饮，用小青龙减麻辛法，正是针对饮邪上逆、阳气被遏之病机。", ["弦", "濡"]], "4457": ["病机", "左脉虚涩为精血亏少、脉道不利，右脉缓大为中气亦虚。尾闾痛连脊骨、便后下血、纳谷最少，显系中下交损、八脉全亏。虚涩主阴血不足，缓大主气不敛，故用斑龙丸峻补、归脾膏涵养，守之经年以固形体。", ["虚", "涩", "缓", "大"]], "4458": ["病机", "脉小为阴液损伤、阳气不充之象。泻血二十年，阴络伤而血内溢，久病及阳，阳不固密，故跗膝冷而骨髓热灼，脊椎腰尻酸楚，经水仍至而不得孕育。此奇经亏虚、升固失职，议从奇经升固一法，非凉肝所能治。", ["小"]], "4459": ["误治", "脉小左数，小为阴亏，数为肝胆相火内炽。便实下血乃肝络热腾、血不自宁。医投参耆归桂甘辛温暖，反助相火，火焰风翔上蒙清空，致鼻塞头晕呛咳。下虚上实、阴伤阳浮，此误治之咎，遗患中厥。", ["小", "数"]], "4460": ["病机", "右脉已小，左仍细数，细数为阴亏本象，小为虚阳渐敛。下血阴伤走泄，虚阳上升，前用参耆术桂辛甘助上，致鼻塞耳聋。清上五六日右脉已小，而左脉细数未改，可见下愈虚则上愈实，议滋水制火以治其本。", ["小", "细", "数"]], "4461": ["病机", "脉缓濡弱为阳气不足、湿胜之征。过饮湿胜，大便溏滑似乎不禁，便后血色红紫成块，乃少阴肾脏失司固摄，阳明胃脉但开无合。治腑以通为补，与治脏补法迥异，故先拟暖胃通阳一法，使湿化阳复而固摄有权。", ["缓", "濡", "弱"]], "4462": ["病机", "弦为风，数为热，涩为气结。寒热如疟、便血不已、左胁有块攻痛，皆肝脾之气悒郁不宣，胸中阳和抑而成火，神明不清。肝风自逆则左胁攻楚，风淫热胜、肝伤血不守，故为亡血之由。", ["弦", "数", "涩"]], "4463": ["病机", "右脉涩无神为脾湿内壅、生气不伸，左关独弦为肝热阴火不宁。溺血三月、茎中痛、下多血块，乃肝热迫血妄行；嗳气、形色憔悴，乃脾湿不化。据脉论症，肝脾积热，法当益肝阴以平火、利脾湿以和气。", ["涩", "弦"]], "4464": ["病机", "原文未识脉名，述先寒后热、不饥不食、浮肿喘呛等症。病机为气分郁结，水道阻塞，肺气不降，二肠交阻，水谷蒸腐之湿横趋脉络，致肿渐加。肺位最高主气，治当宣肺，辛通微苦降，非重浊直入中下。", []], "4465": ["病机", "原文未识脉名，述色痿腠疏阳虚体质，厚味蒸痰，频年咳嗽。医用皂荚搜攒，肺伤气泄，沉锢胶浊留胸背募俞。小青龙彻饮就太阳，初服喘缓，但太阳开而阳明未阖，暂开复痹。喘因在肺实肾虚，此上实下虚，耳聋鸣响，治下壮水源熄内风。", []], "4466": ["病机", "脉细尺垂，形瘦食少，身动即气促喘急。细为阴弱，尺垂为肾虚失纳。动则阳化，吸气入而为喘，病在肾不摄纳。治法收摄固真，上病实下焦，宗肾气方法。", ["细"]], "4467": ["病机", "脉大而动搏，形枯汗泄，吸音颇促，神衰呓语。大动为元海根微，不司藏纳，阳从汗出，有昏脱之变。老年痰嗽喘症，温邪扰上中二焦，虽无温之理，然摄固下真以治根本，阳根于阴，不可不讲。", ["大", "动"]], "4468": ["病机", "脉沉而弦，昔肥今瘦为饮。沉主里，弦主饮，下元先亏，气不收摄，痰饮上泛，饮与气涌为咳。痰饮属浊阴之化，滋则助浊滞气。饮伏至阴，肾脏络病，形寒畏风，阳气微弱。饮邪必用温药和之，外饮治脾，内饮治肾。", ["沉", "弦"]], "4469": ["病机", "脉弦右濡，阳微恶寒，饮浊上干，咳吐涎沫，食减胃衰，寒疝窃踞。弦为饮，濡为阳微。阴浊上逆，非离照当空不能退避。反以地黄五味阴药附和其阴，阴霾肆虐。议熟附配生姜，扫群阴驱饮邪，维阳气立基本，尊年急护真阳。", ["弦", "濡"]], "4470": ["病机", "脉来濡弱无神，痰饮咳逆未已。濡弱无神为阳微，浊饮上干为咳不能卧。前用小青龙减麻黄细辛得卧，交惊蛰阳气发泄病势更炽，非前法可效。宗真武汤法，熟附配生姜，通阳逐饮立法。", ["濡", "弱"]], "4471": ["病机", "脉弦右涩，面亮舌白，口干不喜饮，头重岑岑，胸脘痹塞而痛，得嗳气稍舒。弦为饮，涩为饮阻气滞。酒客谷少中虚，痰饮聚蓄，夏令地气上升，饮邪挟气上阻清空。色鲜明为留饮，口干不欲饮水为饮邪未去。漐漐汗出非风寒，辛温发散大禁。", ["弦", "涩"]], "4472": ["病机", "原文未提脉象，但述‘风寒外受，热气内蒸，痰饮日聚于脏之外，脉络之中’，指出外寒引动内饮，饮泛气逆致咳喘气塞、胸膈不思食、呛吐稠痰，病名哮喘伏饮。其病机为痰饮伏于脉络，遇风冷、劳碌、心事不宁则扰动宿饮，气逆上泛，肺气不降，故见咳喘痰稠。", []], "4473": ["病机", "原文引‘脉沉属饮’，沉脉主里，饮邪内伏，故脉沉。冬温阳不潜伏，伏饮上泛乘肺，肺气不降，一身之气交阻，熏灼不休，络血上涌，致咳甚、不得卧、卧则喘甚痹塞。此脉沉说明饮浊内停，病机为伏饮上泛、肺气逆乱，治当开太阳使饮浊下趋。", ["沉"]], "4474": ["病机", "两关脉弦长，关候肝胃，弦主肝阳亢盛，长主气火有余。原文谓‘五火燔燎，而肝阳胃阳尤甚’，动怒则抽掣为肝病，食辛香厚味即病至为胃病，痰火根深。此脉弦长说明肝胃阳亢、痰火内蕴，主肝病动怒抽掣与胃病食辛香即发，治宜静养薄味以清里。", ["弦", "长"]], "4475": ["病机", "原文按胀形‘濡涩’，濡主湿、涩主滞，说明暑湿热气内伏，因劳倦正气泄越而发。症见面垢油亮、目眦黄、头胀如束、胸脘痞闷，皆湿热郁蒸之象。濡涩脉非表症，故不可发散取汗徒伤阳气。此脉说明湿热内伏、气机壅滞，当以劳倦损伤伏邪例诊治。", ["濡", "涩"]], "4476": ["病机", "原文未提脉象，论七疝治法，谓辛香泄肝可治气实，参术升补仅治中虚下陷，与元海奇经中病无补。壮岁至老病根不辍，下焦日衰，升阳一法体症颇合，衰年仅可撑持。此段说明疝病根在奇经下焦，非单纯气实或中虚，病机为下焦日衰、奇经失养，故升补难愈。", []], "4477": ["病机", "脉右弦左涩，弦主肝气结聚，涩主血滞不通。当脐痛连少腹，已属凝聚有形；呕吐黄浊、大便欲解不通，为气滞浊阻；患处漉漉声、痛势稍减，外著体不转移则痛更加，说明气结血瘀。此脉弦涩主肝气疝瘕，病机为肝气凝聚、气血不通，故辛香流气以通则不痛。", ["弦", "涩"]], "4478": ["病机", "原文未提脉象，论七疝在肝，冲脉隶于阳明，肝木乘克胃土，胃翻涌逆，致吐蛔呕吐、汤饮不入、呃忒不止，皆逆乱无已，为脏厥危疴。肝体本刚，相火内寄，一派热燥药饵以刚济刚，有缺折之虞。此段说明疝病及胃、肝胃逆乱之病机，欲泄其浊用朱南阳法。", []], "4479": ["病机", "原文未提脉象，述痛自肾囊渐踞少腹之左，厥阴之脉绕阴器，操持谋虑伤肝，一气结聚变幻形象而痛，病名曰疝。暴疝多寒，久疝多热，泄气痛缓，宣通却病。下焦深远，气热湿郁。此段说明疝病由肝气结聚、气热湿郁下焦所致，病机为肝郁气结、湿热郁滞。", []], "4480": ["病机", "疟母十年，沉痼宿疴，药不能效。原文谓“邪与气血两凝，结聚络脉”，药难入络。疟不离肝胆，疝亦肝病，虚质不可专以辛香，下坠为甚。议有情温通以培生气。此段无脉象描述，主述久疟邪凝络脉、气血结聚之病机，属沉痼难治之证。", []], "4481": ["病机", "脉沉痰多，手体赤疮，宿疝在下，右胁气坠少腹。前议控涎丹逐痹未应，想久聚湿热沉痼，非皮膜经脉之壅。用浚川丸通腑宣壅，黏痰既下，疝仍聚右，盛于寒天冬月。脉沉主里，痰多示湿浊内蕴，久病急攻无效，议辛甘化风，古人以疝为肝病十居八九。", ["沉"]], "4482": ["病机", "泻血五日血止即咳呛，左胁有形如梗，身动眩晕欲仆，交冬人迎脉络结瘿。诊脉虚，左关尺数。此肝肾精血因惊恐忧劳所伤，阳失阴恋，络中空隙，阳化内风，鼓动不息，日就消烁。脉虚为精血亏耗，左关尺数乃阴虚阳浮，内风鼓动，为郁劳之症。", ["虚", "数"]], "4483": ["病机", "病始足胫，自下焦肝肾起病，形不肿非六气湿邪，当从内损门痿躄推求。萸地滋滞久服胃伤，食减呕逆，浊味滞气。经年不复，脏真不能充沛，奇经八脉不司其用。冲脉为病，男子内结七疝，女子带下瘕聚。今精沥内结有形，是精窒气结，犹女子瘕聚。久病形消肉脱，议精血有情涵养生气。", []], "4484": ["病机", "长夏霉天奔走，内踝重坠发斑，下焦痛起，筋掣及腰窝左臂。经云“伤于湿者，下先受之”。下焦奇脉不流行，阴维受邪，久必化热烁血，风动内舍肝胆。诊得右脉缓，左脉实。缓主湿滞，实主邪结，湿热混处血络之中，搜逐甚难。此湿痹失治，延为痿废沉疴，先通营络，参之奇经为治。", ["缓", "实"]], "4485": ["病机", "痹症每以风寒湿三气杂感主治，召恙不同，由暑暍外加湿热、水谷内蕴湿热。外来之邪著于经络，内受之邪著于腑络，故辛解汗出热痛不减。急清阳明而致小愈，病中复反者口鼻复吸暑热也。病后宜薄味，使阳明气爽，清阳流行，肢节脉络舒通，痿痹之根尽拔。温补图速效非壮盛所宜。", []], "4486": ["病机", "左脉弦大，面赤痰多，大便不爽。此劳怒动肝，令阳气不交于阴，阳维阳𫏋二脉无血营养，内风烁筋，跗⿰⻊廉痹痛，暮夜为甚者厥阴旺时也。脉弦主肝旺，大主阳亢，劳怒伤肝，阳不交阴，内风烁筋，病在脉络，故见痹痛夜甚。", ["弦", "大"]], "4487": ["病机", "烦劳郁勃之阳，变现热气内风。内经以热淫风消，必用甘寒。前议谓酒客不喜甘味，且痰多食少，亦忌甘腻滋滞，用清少阳胆热者，酒气先入肝胆也。酒汁湿著肠胃，理肠以通胃，胃肠气机流行，食加滑泄颇腻。今气热当午上冒，经络痹痛减于平日，主以和阳甘寒，宣通经脉佐之。", []], "4488": ["治法", "原文未识脉名，但述“右指仍麻”“戌亥必心热烦蒸”，前法用杞归辛温不效，因“阳动风亦动”，故议去辛用咸，柔肝熄风。此示肝血虚而风阳内动，络脉失养，治当养肝血、熄风通络，兼虑疟邪留滞，可缓攻通逐。", []], "4489": ["病机", "脉弦右大，弦则为饮，大则胃阳已虚。操持萦思，积劳阳虚，致不饥不食、夜卧不安、腹鸣气震、四肢痿弱。阳虚为本，痰饮气逆因虚而聚，长夏湿土乘侮脾胃，虑肌肿腹胀。治以通补理胃阳为主，疏肝为辅。", ["弦", "大"]], "4490": ["病机", "两脉浮虚，浮虽风象，内虚者脉亦浮而无力。周身掣痛、头不可转、手足不能运，以脉参症，当是劳倦伤中，阳明不治。阳明主束筋骨利机关，虚则气血不荣，卫中空虚，营行不利，相搏而痛。法当大补阳明气血，不与风寒湿痹同治。", ["浮", "虚"]], "4491": ["病机", "脉络已虚，长夏湿痹，经脉流行气钝，下元脉络虚，痿弱不能走趋，脊膂酸楚，大便或结或溏，属肝肾奇经为病。治必佐宣通脉络，徒呆补则夏季后必滋湿扰，须预理。", ["虚"]], "4492": ["病机", "脉微而涩，微为阳气虚，涩为阴血伤。去冬下肢独冷，步趋无力，高年内乏藏纳，入夏身动加喘，肉腠麻痹若虫行。此真阳失蛰，胃阳失护，生生意少，非攻病药石所宜，当大封大固，莫令真阳泄尽而暴脱。", ["微", "涩"]], "4493": ["病机", "左脉小濡，血伤骤加惊恐，气郁热升风旋，清神受蒙为厥。厥隶厥阴，左股麻痹，忽爽忽迷，皆肝胆相火内风未宁。热胜津伤，不宜纯与攻涤苦寒。肝为刚脏，柔缓濡润，阳和液复，可免痫症。", ["小", "濡"]], "4494": ["治法", "原文未识脉名，述下焦痿躄，先有遗泄湿疡，频进渗利，阴阳更伤。畏冷阳微，饭后吐食，胃阳顿衰。下焦多精血受伤，投柔剂温通，通摄兼施；胃药另用，扶阳理胃，俾中下两固，合阳明束筋骨利机关之旨。", []], "4495": ["病机", "脉已虚，长夏湿热，经脉流行气钝，下元络脉虚，痿弱不耐步趋，常似酸楚，大便或结或溏，属肝肾为病。益下必佐宣通脉络，徒呆补恐季夏后湿热还扰，须预理。", ["虚"]], "4496": ["病机", "脉实为邪气壅盛之象，此案患者色苍体壮，平素嗜酒醴甘肥，酿成湿火蕴结下焦。脉实反映湿热毒邪深伏络隧，与少腹肿硬、二便涩、足重难行、腿股皮热等症相应。原文明言“湿热不攘，大筋緛短，小筋弛长”，脉实正是邪实壅滞、气血不畅之征，故治以苦辛寒燥佐搜逐络隧。", ["实"]], "4497": ["病机", "此段未识脉名，然述金疮去血伤及营络，又因嗔怒动肝，阳气逆迸化火，频服苦辛泄气致阳泄。形丰而收藏固摄失职，见少腹约束、阳道不举、背脊喜靠、步履无力，皆痿弱之端。病机为下元阳衰、八脉失固，故议通纳之法以涵养生真，使收者收、通者通。", []], "4498": ["病机", "脉脉络空乏，指阳明脉络空虚，因五旬又四阳气日薄，不司束筋骨、流利机关。故见肩痛痹麻、头目如蒙、行动痿弱无力，此下虚上实、络热内风沸起之候。空乏之脉正示气血不充、络脉失养，入夏阳升则风火愈炽，故燥湿利痰不应，当清营热以熄内风。", ["空"]], "4499": ["病机", "此段未识脉名，述勉强摇精致阳缩囊纵，形质伛偻，肛门脐窍收引，咽喉牵绊，食减。病机为精血有形之伤，少厥两阴受损，其气不及充注八脉，故见拘束之状。上年进柔剂阳药反致头巅经脉胀、耳窍鸣，乃藏阴宜静、升阳动药不灵之故，仿丹溪潜阳法。", []], "4500": ["病机", "此段未识脉名，述夏季反复变幻因天地气机大泄，体气久虚无以主持。入秋火热伤气，虚体未能收肃，故肢节时寒、头巅欲冷。病机为病久诸气皆馁，外卫之阳少护，液髓暗枯则血脉不营，阴乏内守，生气渐鲜。故急当温养益气、填补元形，助秋令收藏以为来春生发之用。", []], "4501": ["病机", "脉数动疾，为阳亢阴亏、风火内动之象。高年液涸风动，酒湿气蒸，足趾腐疡，经年麻痹牵掣，已成筋骨之痿；兼火升眩晕、清窍不爽、大便艰涩。数动疾之脉正示阳气不能潜伏，阴液日就枯槁，故温燥之补无益反害，仿丹溪虎潜丸以存津液。", ["数", "动", "疾"]], "4502": ["病机", "此段未识脉名，述肾厥由背脊而升，发时手足逆冷、口吐涎沫、喉如刀刺。病机为足少阴经脉上循喉咙、挟舌本，阴浊自下上犯，循经而至。手足逆冷乃阳为阴遏，涎沫喉刺为浊阴上逆，故仿许学士椒附意，通阳以泄浊阴，使阴浊下行则厥逆自平。", []], "4503": ["病机", "脉空乏，指冲脉空虚。厥属肝病，几番病发都因经水适来，血海贮聚既下，冲脉空乏，风阳交动，故厥暴至。咸寒濡润未应，下焦独冷，喉呛胸痹，思冲脉隶阳明，阳明虚则失阖，厥气上犯莫遏。空乏之脉正示血海空虚、冲脉失养，故取阳明以制肝侮。", ["空"]], "4504": ["病机", "脉左动如数，右小濡弱，左动数乃肝阳亢动化风，右小濡弱为脾虚气弱。病起嗔怒，怒则诸阳皆动，内风为厥，故见寒热汗出心悸、神魂散越。肝藏魂，阳动风旋则魂不守舍，病属厥阴肝病，治当镇固收摄，兼顾肝肾下焦。", ["动", "数", "濡", "弱"]], "4505": ["病机", "原文未出脉名，然述冷气自足上贯于心、口鼻皆冷，病起惊恐内伤肝肾为厥。冲脉隶于肝肾，二脏失藏则冲气沸乱，其脉由至阴而上，故多冷。此乃下焦阳虚，冲气上逆，非外寒直中，病机在肝肾失藏、冲脉不宁。", []], "4506": ["病机", "原文未出脉名，而言阳乘于络、阴脉不安，乃情志内伤、阴阳迭偏之候。操持悲忧惊恐，神志恍惚有似癫痫，病不在一脏。凡动皆阳，阳扰于络则阴不宁，故治宗静以生阴、敛镇摄固，使阴阳复其常度。", []], "4507": ["病机", "原文未出脉名，但言按脉偏于左搏，左搏者营络虚热之象。久久烦劳，心营肺卫先伤，渐损中下，肌肉瘦减、善饥渴饮，壮盛不觉而体衰病发。营络虚热故苦寒莫制其热、甘补无济其虚，此中上消之病，病机在营虚热灼、阴液耗损。", []], "4508": ["病机", "原文未出脉名，述病起忧虑上损，胸心右胁常有不舒。气血内郁少展，支脉中必有痰食气阻，故宜宣通流畅脉络。此非虚损纯补之证，乃郁阻络脉、气机不展，痰食交阻为患，夏季阳气外达，宜因势宣通。", []], "4509": ["病机", "脉右大而缓，左手小数促。右大缓为脾胃劳倦、营卫失和，左小数促为虚热内扰。劳役饥饱嗔怒后病加，面浮足肿、喘、衄、食纳不运，皆脾胃衰而营卫循环失度。仲景谓男子脉大为劳，此劳倦致损，中满胀病将成。", ["大", "缓", "小", "数"]], "4510": ["病机", "脉右小促，左小弦劲。右小促为脾胃气弱，左小弦劲为肝郁阳微。病起脘痛梗突，惊触后食减胀满，便血、爪甲紫，乃肝脾气血不通，久则阳微痹结，上下不行，有否卦之象。前医消补无效，未知通阳之奥。", ["小", "促", "弦", "劲"]], "4511": ["病机", "脉沉弦，由水寒痰滞阻遏气分。平昔湿痰阻气为喘，过食停滞则阴脏之阳不运、阳腑之气不通，二便不爽、跗肿腹满，上下皆不通调。沉为水寒在里，弦为痰滞气阻，当从三焦分治，分消其水寒痰滞。", ["沉", "弦"]], "4512": ["病机", "原文未明言脉象，但述‘脉络气血，不为流行’，致腹满重坠、脐左动气、吐冷沫、身麻语塞，显系肝风日炽、疏泄失职，木侮土位。气血不流则胀满，肝风内动则麻塞，冷沫为肝病吐涎。病机在肝胃，治宜宣通，久恙贵平淡。", []], "4513": ["主病", "脉微而迟，为阳气不足之象。色衰萎黄，因食蟹咸寒损阳，久利久泄伤肾，致水失火而败，浮肿自下起。微迟主虚寒，故非湿热红泻，乃肾阳虚衰、水气不化，治当暖下。", ["微", "迟"]], "4514": ["病机", "脉左弦右浮涩，左弦为肝木怫郁，右浮涩为脾土自困、清浊混淆。始脘痛贯胁，继腹大高凸、二便艰涩，乃有年操持、萦虑太甚所致。肝郁脾困，脏真日纳，腑阳不运，胀势乃成，治以通阳为务。", ["弦", "浮", "涩"]], "4515": ["病机", "脉左小弱，右缓大。左小弱为气血交结、肝血不足；右缓大为太阴不运、阳明愈钝。宿痞梦遗后腹形坚大，纳食腹胀，四肢恶冷，热自里升，衄血牙宣，全是气血交结，非积聚停水。当以脾胃为病薮，缓攻为法。", ["小", "弱", "缓", "大"]], "4516": ["病机", "脉浮大而数，浮大为风热壅盛于外，数为阴虚内热。患风三月，周身流走作肿，手不能握，足不能履，发热口干，此阴虚生内热，热胜则风生，风火相煽，伤筋脉则纵缓不收，逆肉理则攻肿为楚。", ["浮", "大", "数"]], "4517": ["病机", "脉弱细不调，弱细为气血两虚，不调为气血壅滞。夏季目黄神倦，渐至中焦胀满，上吐瘀血，下便污浊，呼吸带喘，宿饮蓄积。脾胃主令时饥饱劳役，减食胀满，气壅血瘀，胀势愈加。六腑以通为用，治宜通阳驱浊，温补兼进。", ["弱", "细"]], "4518": ["其他", "原文未出脉象，但参脉症色形，生阳颇有根蒂。近食蚕豆滞气，腹中微膨，食后口味酸浊，乃久卧重著、脾阳运动之机尚少，火升心烦、动气汗出、遗精未平，总属内损已深。治当培土助纳，兼摄固精气，补脾佐疏胃。", []], "4519": ["病机", "脉小如数，小为阴精不足，数为阳动不藏。肌肉松柔，梦遗精不固，因冬温腠理反疏，阳动不藏，诸气皆升，络血上溢，头面热、目下肉𥆧、心悸怔忡、汗出、足跗肿冷、动则喘，皆少阴肾气失纳、阳浮不潜之征。治当填精镇神，酸收甘缓。", ["小", "数"]], "4520": ["病机", "原文述遗泄有梦属心、无梦属肾，气火下溜如溺出状，茎管中痛，热气上冲咽喉巅顶掀胀，语言怯弱，此为任脉不摄、冲脉气逆。冲任不固则精泄，气逆上冲则咽痛巅胀，便溏食少示中虚，故勿投沉阴腻滞。", []], "4521": ["病机", "案牍神耗，过动天君，阳隧直升直降，水火不交，阴精变为腐浊，精浊与便浊异路，宣利清解无功，病伤在任督。八脉奇经失固，阴精不藏，故浊下不止，治当升固八脉之气以涵阴精。", []], "4522": ["病机", "脉左劲右濡，左劲为肝阳化风，右濡为胃土虚弱。水弱木失滋涵，肝风过膈绕咽达巅，木乘胃土，阳明脉衰不束筋骨，故头晕肢麻、咽中黏着、饥则脘腹痛。壮年见此，已属痱中根萌，治养肝肾之液以熄虚风，补胃土以充络脉。", ["劲", "濡"]], "4523": ["病机", "脉沉细而兼微数，沉细为精血亏虚，微数为伏火内扰。肝亏肾损，精不营筋，故宗筋短缩、足腿消烁、拘挛；伏火灼津，则便结溺沥。此《内经》所谓筋痿、白淫，治宜滋肾舒肝，使精血渐充。", ["沉", "细", "微", "数"]], "4524": ["治法", "浊腻膏淋日下，损人津液，络脉遂槁，八脉隧道纡远，泛然补剂药力罔效。奇经如沟渠满溢流入深河，不与十二经并行，故树根草皮难奏效，须用血肉填补固涩，庶可希效。", []], "4525": ["病机", "勉强攻胎，气血受伤，寒热身痛，乃奇经冲任受病，阳维脉不用事。阳维为病苦寒热，既非外感，辛酸苦寒误治，胃口屡伤，汤饮哕出，便闭半月，吐青绿涎沫，显系肝风大动，将胃口翻空，肠中污水荡漾，危笃若此。", []], "4526": ["病机", "右手涩弱，虚象昭然；左脉空大，按之不实，非肝气肝火有余。产后精血未复，真阴日损，阳气不交于阴，变化内风，上巅犯窍，冲逆肆横，胃掀吐食，攻肠为泻，肌肉皆肿。辛酸苦降重坠，致阳更泄，阴愈涸，烦则震动即厥。", ["涩", "弱", "空", "大"]], "4527": ["病机", "脉短涩无神，阳衰邪伏显然。肌肉微白属气虚，外似丰溢里真大怯，阳虚之体多湿多痰，肌疏汗淋，唇舌俱白，干呕胸痞，烦渴引饮，由脾胃之阳伤残，邪僭居中，留蓄不解，正衰邪炽。寒凉清邪更伤胃阳，杳不纳谷，大便渐涩，急和胃气。", ["短", "涩"]], "4528": ["病机", "脉濡弱，为胃阳受伤、脾不运化之象。原文述“左胁下久有聚气”“纳食酿积于胃脘”，因怫怒动肝，肝木犯胃，胃中阳伤，不能传及小肠，变化失司，故呕逆吞酸、积物上涌、大便数日一行。脉濡弱正合胃阳虚衰、湿浊内停之机，法当温胃阳制肝逆，久延恐成反胃。", ["濡", "弱"]], "4529": ["病机", "壮年形伟而脉小濡，为阳气微弱、浊阴类聚之征。原文谓“口鼻受污浊异气，先入募原”，募原乃胃络分布，浊阴上逆故恶闻秽气、食入呕哕。脉小濡主阳微湿滞，正合本虚标实之病机，故治标用芳香辟秽扶正，治本以温上通阳。", ["小", "濡"]], "4530": ["病机", "脉动，原文引“冲脉动，而诸脉交动也”。少腹属肝，肝厥犯阳明胃腑，故痛呕；病延二年，肝肾内伤，久则奇经诸脉交伤，冲脉动则诸脉皆动。脉动在此主下焦虚损、奇经交伤之病机，故议温通柔润剂，从下焦虚损主治。", ["动"]], "4531": ["病机", "脉弦而小涩，弦主郁怒伤肝，小涩主气滞痰聚、血行不畅。原文述“郁怒之伤，少火皆变壮火，气滞痰聚日拥，清阳莫展，脘管窄隘”，故食入脘痛格拒、必吐清涎，视色苍、眼筋红黄、昔肥今瘦，噎膈渐至。脉弦小涩正合气滞痰瘀阻膈之病机，法当苦降辛通，佐利痰清膈。", ["弦", "小", "涩"]], "4532": ["病机", "脉动，原文谓“冲脉动，则诸脉皆逆”。蛔虫上下出属厥阴乘犯阳明，至阴伏邪既深，不能隔越诸经达于阳分，故寒热后全无汗解；老年冲脉既衰，呕吐时周身牵引直至足心，阴阳跷维不得自固。脉动主冲脉逆气、厥阴伏邪之病机，非单纯胃痰。", ["动"]], "4533": ["病机", "脉沉弦，沉主里、弦主肝。原文述夏秋伏暑发热，误表禁食，胃气受伤，致肝木上干胃土，蛔虫上出，故腹痛呕吐、鼻煤舌绛、面带青晦。脉沉弦正合伏邪内陷、肝胃不和之病机，常虑厥逆，拟泄肝和胃，得痛止呕缓方有转机。", ["沉", "弦"]], "4534": ["病机", "原文谓“诸脉逆乱”，乃久病入络、痰因气滞、气阻血瘀所致。痛非虚症，频吐污浊而大便反秘，医见肢冷误认虚脱，以理中附子温里，不知阳气无形，病发有因，决非阳微欲脱。脉逆乱主气血瘀滞、络脉不通之病机，故宜通瘀清养，非温补可投。", []], "4535": ["病机", "脉得左大右小，左大主肝木亢盛，右小主胃气虚弱。原文述胃痛久而屡发，凝痰聚瘀，老年气衰，纳物呕吐酸苦，完谷而出，呃逆沃热汤不减，胃气掀腾如沸。脉左大右小正合肝木侮胃、胃阳虚衰之病机，故用药远柔用刚，开得上关再商治法。", ["大", "小"]], "4536": ["病机", "脉细弦右涩，细为阴血不足，弦为肝木偏亢，右涩主胃络瘀滞。产后三年经水不转，胃痛得食必呕，汗出形寒，腰左动气闪烁，大便七八日始通，显系厥阴肝木横逆，顺承阳明，胃土久伤，肝木愈横。舌白稍渴，脘中响动，下行痛缓，皆肝胃不和、浊气上僭之象。故脉象反映厥阴体用失调，阳明通降失职。", ["细", "弦", "涩"]], "4537": ["病机", "脉空隙，即脉来中空如芤，主络脉空隙、阴血亏虚。天癸当绝仍来，昔壮年头晕，七年前秋起胃痛若嘈，今春悲哀后麻木头眩，痛发下部，膝胫冷三日，痛引背胁。此久病络脉空隙，厥阳热气因情志郁勃拂逆，气攻乘络，内风旋动，袭阳明，致呕逆不能进食。脉空隙正合络虚风动之机。", ["空"]], "4538": ["病机", "原文未识脉名，然述痛在胁肋游走不一，渐至痰多，手足少力，初病两年寝食如常，今年入夏病甚。此非脏腑之病，乃由经脉继及络脉。经主气络主血，久病血瘀，瘀从便下。诸家不分经络，但忽寒忽热，宜乎无效。服新绛一方小效，乃络方耳。议通少阳阳明之络，通则不痛。病机在络脉血瘀，气机不通。", []], "4539": ["病机", "诊脉动而虚，左部小弱，动为阳动不宁，虚小弱主营络亏损。左胁疼痛，痛势上引，得食稍安，此操持太甚，损及营络，五志之阳动扰不息，咽干舌燥，心悸久痛，津液致伤。症固属虚，但参术归耆未能治及络病。内经肝病三法，宜辛甘润温之补，柔以济刚。脉动而虚正合肝阳动扰、营络虚损之机。", ["动", "虚", "小", "弱"]], "4540": ["病机", "脉细弦数不舒，细为阴血少，弦为肝郁，数为火郁。古人治胁痛五法，或犯寒血滞，或血虚络痛，或血著不通，或肝火抑郁，或暴怒气逆。今是症脉细弦数不舒，此由肝火抑郁，火郁者络自燥，治法必当清润通络。脉象反映肝火内郁、络脉燥急之病机，与胁痛症候相应。", ["细", "弦", "数"]], "4541": ["病机", "诊脉右弦，左小弱涩。右弦主肝木乘胃，左小弱涩为营血不足、络脉涩滞。病起积劳伤阳，操持索思，五志皆逆，肝为将军之官，谋虑出焉，故先胁痛。晡暮阳不用事，其病渐剧，是内伤症，本气不足。日饵辛燥，气泄血耗，六味滋柔腻药非止痛之方。病久必及阳明胃络，肝胃同病，梦寐纷纭，伤及无形。议用甘药少佐摄镇。", ["弦", "小", "弱", "涩"]], "4542": ["病机", "脉来沉而结涩，沉主里，结为气滞，涩为血瘀。小便自利，大便黑色，当脐腹痛，十五年渐发日甚。此郁勃伤及肝脾之络，致血败瘀留，劳役动怒，宿疴乃发。目今冬深闭藏，忌用攻下，议以辛通润血，所谓通则不痛。脉沉结涩正合肝脾络瘀、血败瘀留之病机，与大便黑色、当脐腹痛相应。", ["沉", "结", "涩"]], "4543": ["病机", "脉小涩，小为气血不足，涩为血络瘀滞。久因悒郁，脘痛引及背胁，病入血络，经年延绵。更兼茹素数载，阳明虚馁，肩臂不举。仓猝难于奏效，是缓调为宜。议通血络润补，勿投燥热劫液。脉小涩反映气血两虚、血络瘀阻之病机，与脘痛引背胁、肩臂不举等症相应。", ["小", "涩"]], "4544": ["误治", "原文未识脉名，但述温邪误汗误下之逆。温邪自口鼻入膜原，本非太阳表证，投羌防辛温发汗，劫津伤阴，致身灼热、鼻息鼾、语言难出，甚则惊痫瘛疭；又妄下攻热，更劫液亡阴。脉象虽缺，所论在明误治之害，故归误治。", []], "4545": ["病机", "脉数主热，舌紫渴饮为气分热邪未去，渐次转入血分。数脉为热盛之征，热灼营血则舌紫，热伤津液则渴饮。此段以脉数合舌紫渴饮，断热气由气分内传血分，故于甘寒清气中佐存阴，防热入血分而耗阴。", ["数"]], "4546": ["病机", "脉右搏数，左小，右主气，搏数主热，左小为阴分不足。温邪自口鼻受，上焦先病，气血与热胶固，致清窍不利，面颔肿胀、牙关紧闭，有痹塞之变。脉右搏数正合上焦气分热结，故治当辛凉轻剂宣通，不可重浊攻肠胃。", ["数"]], "4547": ["病机", "脉左数右缓弱，左数主阴分伏热，右缓弱为阳根未固、阴液渐涸。舌赤微渴、喘促自利、溲数、晡热神烦呓语，皆温邪久伏少阴，真阳不肯收纳，阴液亏耗之象。脉数而缓弱并见，示虚中夹热，故立法育阴祛热，浊药轻投。", ["数", "缓", "弱"]], "4548": ["病机", "脉小缓，按之鼓击，小缓为病退之象，鼓击示内伏热气由募原流布三焦。丰腴过劳伤阳，呕吐无表证，间日烦躁渴饮唇焦舌黑，乃伏热内蒸。脉小缓而鼓击，说明邪不盛而热未清，二便通、纳谷，无停滞积聚，故宜甘寒养胃阴，忌辛温消滞苦寒。", ["小", "缓"]], "4549": ["病机", "诊脉较大于早晨，大脉主热盛，示下午药后热势增甚。腹胸肌腠瘾疹，气分湿热有暗泄之机，但舌赤中心干燥、身热甚于早间，为阴分亦被热气蒸伤。脉大与热甚相应，瘦人虑液涸，痰咯不清，养阴碍腻，故先清膈逐秽，继清营滋胃。", ["大"]], "4550": ["预后", "脉形小数，小为病退，数为余热，故为佳兆。皮腠麸脱、思食欲餐，示气血流行、胃气醒豁。但舌赤中心黄苔，热蒸既久，胃津阴液俱伤，咽物若阻、溺痛、痰厚、宿垢未下。脉小数为邪退未净，不可急遽攻夺，当存阴为主，清腑兼之。", ["小", "数"]], "4551": ["预后", "原文未识脉名，仅言脉神颇安，示脉象和缓有神，为病退之兆。然发疹寒战、皮脱如麸，湿热未全泄；病久肌无膏泽、瘦削枯槁，阴液不充。脉神虽安而形瘦阴亏，故虑其反复，主张淡薄调理，清上焦痰热，防病后劳复。", []], "4552": ["病机", "右脉小数，左脉涩弱，示热固在里而阴伤日下。暑湿热内郁，新凉引动伏邪，医者误用发散消食寒凉，致胃汁消亡、真阴尽灼，故见耳聋、神识不慧、嗽甚痰黏、呼吸喉间有音，舌边赤、齿板燥裂，邪留营中，有内闭瘛疭厥逆之变。", ["数", "涩", "弱"]], "4553": ["病机", "脉右缓大、左弱，面垢色减，痰嗽不爽，乃胃中津液为辛散温燥所伤，心营肺卫受热焰蒸迫，致神呆喘急耳聋、清阳阻痹、九窍不利。前用宣解气血、芳香通窍获效，今当清养胃阴肺气，兼顾体素丰厚阳弱不耐沉寒之质。", ["缓", "大", "弱"]], "4554": ["病机", "右脉空大、左脉小芤，为积劳内虚之象；秋暑客邪遂干脏阴，致寒热麻痹、腰痛冷汗、神迷心热烦躁。刮痧略爽而病不解，非经络间病，虑热深劫阴而为痉厥。暑邪入肝则麻痹，入肾为消渴，议清阴分之邪兼养正。", ["空", "大", "芤"]], "4555": ["病机", "脉刚而数，身尚躁热，舌苔黏腻，神呆目定，烦躁呓语，乃暑湿久伏与时气秽邪凝合，酿成胶腻之痰闭塞清明之府，胃家浊液蒸遏不宣。湿位之下燥气乘之，湿转为燥，若无湿痰潮气上蒸则舌苔早已燥刺，今先滋液以清烈焰之燔。", ["刚", "数"]], "4556": ["病机", "脉长而数，症见左胁有痞、腹中块儡外坚、胁下汨汨有声、寒热、胃中不知饥、𩠎杂吞酸，显然厥阴阳明湿热下渗，前阴阳缩而为湿热症。疟痢后肝脏必虚，恶虚就实，议升发阳明胃气、渗泄厥阴湿热，其症自愈。", ["长", "数"]], "4557": ["病机", "脉弦缓，面目肌肤皆黄，舌白滑腻，胸脘膈间胀闭，病名湿温。由濒海潮湿气入口鼻至募原分布三焦，复食水谷腥物与外入秽浊交混，湿甚热郁，三焦隧道气血不通，遂变黄色。湿不去则热不除，当苦辛气寒以逐湿祛秽，不与伤寒同治。", ["弦", "缓"]], "4558": ["病机", "未识脉名，述中年冲气痰升喘急随发随止，从肝肾本病治用地黄饮子浊药轻投，归脾甘温守中与痰饮冲逆相背。七月反复，必有暑湿客气从呼吸而受，肌肤丹疹浮肿速现，腠膜映红，乃上焦先伤失解，漫延中下，三焦皆为病薮，胀在脉络不在腑肠。", []], "4559": ["病机", "脉右缓左急，望色萎瘁晦黯，闻声呼吸不利、语音若在瓮中，症见忽热忽温、头中如裹、腰痛欲拊扪、神识呆钝、昏昏欲寐、肢节瘛痉、咳痰映红、溺溲短缩、便溏带血、不饥不渴、环口微肿、唇干不红、舌白糜腐。此水谷酒腥湿热相并郁蒸，阻挠清气游行，周身气机痹塞，邪属无形先著气分，久延必致有形。", ["缓", "急"]], "4560": ["病机", "原文未出脉名，以“心下痛年余屡发、痛缓能食、目黄溺赤”立论，断为“络脉中凝瘀蕴热，与水谷之气交蒸”。痛缓能食说明病不在胃腑而在络脉，瘀热与水谷交蒸故目黄溺赤；攻之过急必变胀满，故忌温燥，用金铃子散合小柴胡法清络中瘀热。", []], "4561": ["病机", "左脉弦数应厥阴肝木，木郁化风，风性喜伸恶屈，郁极则气盛而风发；右脉空大应太阴脾土，土受木克而气不行，湿胜于中。风遇湿留，壅滞经络，湿停阳瘀，故面目悉黄、烦渴腹满。面见黑滞知并伤肾，浊气下流，非外来风湿之比。", ["弦", "数", "空", "大"]], "4562": ["病机", "脉数主热，暑风客邪内侵募原，营卫不和而发疟。暑必兼湿，湿热皆气，气与邪搏则清浊交混、升降自阻，故目眦黄、舌心干白黄胎、口中黏腻、脘痞不思纳谷。湿遏热自生，治当苦降辛通以开热气痞结，消导攻滞、香燥泄气则置暑热之因于不治。", ["数"]], "4563": ["预后", "脉细涩为气血俱亏、邪阻络隧之象。本湿热与水谷交蒸在气分，当分消清解；初误指伤寒六经，再谬用参术守补，致邪弥漫，神昏喘急、妄谵痉搐，皆邪无出路、内闭外脱。洞利后反加腹满，诸气皆结，脉细涩而按腹膨满，正虚邪实，溃败决裂，故难望挽救。", ["细", "涩"]], "4564": ["病机", "脉小涩主气血久阻为郁。病起疟后，邪留络中，加之食物不和、诵读烦劳，遂左胁连少腹厥气攻胃聚腹，凝著䐜胀。肝得邪助，木势张扬，中土受侮，运纳之权自灭，清阳不展，浊阴日踞，渐为痞满。静处病加、烦动小安，正是气血久阻之郁，故议通络法。", ["小", "涩"]], "4565": ["病机", "原文未出脉名，以“天癸既绝之后阴经空乏”立论。营卫造偏故寒热，温脾胃及露姜治中宫营虚；但畏寒不知热为牝疟，牝属阴，身体重著亦阴象。辛甘理阳用鹿茸自督脉煦提，非姜附但走气分刚暴，驱邪益虚却在营分，引《难经》阳维为病发寒热以证之。", []], "4566": ["预后", "脉沉舌白呃忒，时时烦躁，向系阳虚痰饮。疟发三次即止，非邪去病解，乃邪窒不能宣越。今变病阴冱，痰浊阻塞于中，上下气机不相维续，症势险笃。沉脉主里主阳微，舌白呃忒为阴寒痰浊上逆，舍通阳一法无方可拟，必得中阳流运、疟症复作，庶有愈机。", ["沉"]], "4567": ["误治", "伏暑冒凉发疟，误以羌防苏葱辛温大汗，汗多卫阳大伤，胃津亦被劫干，故渴饮、心烦、无寐。左脉弱为阳伤津劫，右脉促为里热未清，目微黄乃湿蕴未化。嗜酒中虚谷少，易聚湿蕴热，勿谓阳伤骤补，仿《内经》辛散太过当食甘以缓之，是述误治之变。", ["弱", "促"]], "4568": ["病机", "脉微弱而细，为阳气衰微、脾胃气钝之象。原文谓“阳气失护卫”则寒栗汗出，“阳失鼓运”则脾胃气钝，故见形冷汗泄、不饥少纳、脘腹常痞。脉微弱细主正气不足，非邪结客热，故舌明润、不喜饮汤。议理中汤专理脾胃阳气，正合脉证。", ["微", "弱", "细"]], "4569": ["病机", "原文未识脉名，然论疟邪挟怫郁嗔怒，致厥阳肝气横逆，其势锐。肝脉贯膈入胃上循喉咙，疟邪亦由四末扰中，故不饥不食、胃受困。久发频发必伤及络，络聚血之所，久病瘀闭，香燥破血、凝滞滋血皆禁忌。此段重在阐发疟久入络、肝气横逆之病机。", []], "4570": ["病机", "脉得弦数，形色消夺，为冲年阴不生长、劳怯大著之象。弦主肝郁，数主虚热，阴亏阳扰故寒热咳嗽失血、月事不来。原文谓“全是冲年阴不生长”，非有年脾肾虚泻，故不可见病治病，当保胃口以冀经通，务以情怀开爽为要。", ["弦", "数"]], "4571": ["病机", "右脉数、左细数，面垢舌燥、白苔点点、肌肤甲错、左胁动气，为伏暑秋发、里邪炽烈、胃津液劫、阴液大耗之候。数主热，细主阴伤，热病受涸急以救阴为务，苟胃关得苏渐可冀安，否则液枯致危，犯客邪内陷之戒。", ["数", "细"]], "4572": ["病机", "原文未识脉名，论泻痢起于长夏，高年肾阳肝阴先亏，客气内扰阻遏中流，乏砥柱坐镇致狂澜滔天。病经两旬不减，重阴无阳，神识甚清，外邪少而内损多，八脉无权、下无收摄，漏卮不已，理必生阳泄、下焦冷，阴阳二气绝微，治本为宜。", []], "4573": ["预后", "脉弦形衰，舌白不渴，日泻数行，食不下咽，不知饥饱，为噤口痢重病。暑邪与水谷交混，酿湿热积滞，肠胃气窒，久则胃倒气夺、中宫损极、下关不摄。脉弦形衰示胃气衰败，谷不能咽，焉能承受汤药，久痢久泻务在能食，预后堪忧。", ["弦"]], "4574": ["病机", "左脉缓涩为久病阴阳之损，右脉弦大非有余形质之滞，乃脾肾日伤、湿气内淫之象。操持积劳、五志化火，温邪内伏，病经九十日，足跗肿、大便黏滞黄赤、小便不利，肾关枢机已废，二肠失司，水谷酿湿坠下转为瘀腐，必致腹满。", ["缓", "涩", "弦", "大"]], "4575": ["病机", "脉沉缓，肌肉丰盛，为水土禀质、阳气少于运行、水谷聚湿之候。湿布经络则下焦重著病痛，食稍不运便易泄泻，经水色淡，水湿交混。总以太阴脾脏调理，若不中窍恐防胀病。沉缓主湿滞脾弱，故见泄泻、经淡、重著。", ["沉", "缓"]], "4576": ["病机", "原文谓「脉见弦大，非脏阴见病之象」，又言「独大独小，斯为病脉」。弦为肝木之象，大为阳明之脉，今久病少餐而脉反盛大兼弦，是胃气不降、肠中不通，腑失传导变化之司。症见大便窒塞、嗳气频频、痔疮肠红，皆九窍不和属胃病之征，故脉症合参全在胃逆，非脾弱也。", ["弦", "大"]], "4577": ["病机", "原文「脉得左部弦实，气郁血结甚肖」。左关候肝，弦为肝郁，实为邪结，嗔怒则肝木之气贯膈犯胃，胃逆不纳，故汤食下咽嗳噫不已、不饥不食、大便干坚若弹丸。脉弦实正应气郁血结、肝木犯胃之机，故进辛润方法以疏肝润燥。", ["弦", "实"]], "4578": ["病机", "原文「阳明脉大」，环跳尻骨筋掣而痛、足筋皆缩、大便燥艰常秘。老年血枯，内燥风生，春升上僭而下失滋养，肝风木横则胃土必衰，阳明诸脉不主束筋骨、流利机关，故脉大而筋脉失养。此大脉非实热，乃阴亏风动、阳明失润之象。", ["大"]], "4579": ["病机", "本段未识脉名，纯论病机。因大声喊叫，外触惊气，内应肝胆，胆脉络耳，震动其火风之威，郁而阻窍，故右耳失聪。治在少阳，忌食腥浊。其病机为惊气动火、胆络郁阻，属邪干窍闭之类，与肾虚失聪不同。", []], "4580": ["病机", "原文「脉形细数，皆是肾阴久亏，肝阳内风上旋蒙窍」。细为阴血不足，数为虚热内动，年已六旬而脉细数，正合肾阴久亏、水不涵木、肝风上旋蒙蔽耳窍之机。故治以填阴重镇、滋水制木，佐咸味入阴、酸以和阳，非苦寒直降可效。", ["细", "数"]], "4581": ["病机", "本段未识脉名，论高年目暗、血络空虚，气热乘其空隙攻触脉络，液尽而痛、当夜而甚，是热气由阴而上。又推想外科酒调末药必系温散攻坚，因而致痛，故断为虚症。其病机为血络空虚、气热攻触，属虚中夹热之候。", []], "4582": ["病机", "原文「左脉空搏，阳不潜伏，咳吐涎沫」。空搏者脉中空虚无力，左脉候阳升之位，空而不敛，是阳气不能潜伏归根，虚阳上浮。阳不潜藏则津液不布，聚为涎沫而咳吐。此脉主阳虚浮越、根本不固之病机，与咳吐涎沫之症相应。", ["空"]], "4583": ["病机", "原文「脉大，咽干，痰多，咳甚，食下腹闷」，断为风温日久、劳倦内热、津伤液燥。脉大为热盛津伤之象，热灼肺津则咽干痰多咳甚，津伤液燥则食下腹闷。此大脉非实邪壅盛，乃内热耗津、液燥失润之病机，故以津伤液燥为主。", ["大"]], "4584": ["病机", "脉坚搏者，阴分先亏而温邪入肺，邪热内迫、阴不制阳，故脉来坚劲搏指。坚为阴伤邪结，搏为热盛与正气相争。原文兼见咳嗽、夜卧汗出、多失血，皆阴亏热扰之象，故大忌发散苦辛，当从甘润而解，此脉实示温邪伤阴、虚中夹实之机。", ["坚", "搏"]], "4585": ["病机", "脉右搏者，右主肺卫，风温入太阴，气郁热聚，肺失宣降，故咳喘口渴；营卫失和则周身掣痛。搏为邪热壅盛、气机郁迫之象，热聚肺经有动血之虞，故原文特言防失血，示热郁营分、迫血妄行之病机。", ["搏"]], "4586": ["预后", "脉细促者，细为阴血亏少，促为阳气躁动而不相接续。积劳饥饱惊恐已伤内，春仲气泄更耗下元，腰痛足冷为下虚本病；辛散苦降再伤阴阳，致白利口渴、神呆不语。少阴真气重损，脉细促正是阴阳离决之兆，故有昏谵厥脱之虑。", ["细", "促"]], "4587": ["病机", "左脉坚数甚，坚为阴液枯涸、脉失柔润，数为热邪内炽。温邪内伏，少阴水亏液燥，热气上冒，故舌喑不语、得饮微呛微呃，乃中厥之象。老年面赤神昏则阳气浮越，坚数之脉示水亏火旺、本虚标实，最防衰脱。", ["坚", "数"]], "4588": ["主病", "脉弦为暑风内动、少阳枢机不利之象。暑风袭表，清阳被扰则头胀身热；热灼津伤则口渴；胃气上逆则呕痰。弦脉主肝胆、主气机郁滞，暑热与风邪相搏，邪正交争于半表半里，故原文防其转疟，示暑风郁于少阳之病机。", ["弦"]], "4589": ["预后", "脉细数为阴亏热炽，下垂入尺则肾元不固、虚阳有下陷之势。壮年热病而脉神衰惫，潮热耳聋、汗出神昏，皆热邪深入、阴液耗竭之候。上实下虚，虚阳上冒，故怕昏厥在迩，拟复脉法以救阴恋阳，脉象已示正虚邪陷之危。", ["细", "数"]], "4590": ["病机", "脉右弦，右候肺脾，弦主气机郁结、饮邪内停。暑邪入里，三焦俱病，气化不利则中痞；发汗后热不解，知病不在表而在里。弦脉示暑湿郁阻、枢机不利，故进苦胜于辛之法，以苦泄里热、宣通三焦，此脉明里实之机。", ["弦"]], "4591": ["病机", "脉弦左搏，弦为少阳郁热、肝木偏亢，左搏则邪热深入血分、血气壅迫。暑热多日入血，迫血妄行故衄血；热泄身凉而脉仍弦搏，知余邪未净。连日呕逆、发散消食劫耗胃汁，胃气受戕，故虑其变疟或旬日不饥，示血热未清、胃阴受伤之机。", ["弦", "搏"]], "4592": ["病机", "脉左数，下重，为热入血中，阴伤液耗，故暮夜热烦无寐；热迫血妄行则衄血。脉数主热，左脉候血，数而无力为阴伤，胎元失养恐难保。治当益阴清热，减辛散耗气之品，仿苦寒佐咸寒。", ["数"]], "4593": ["病机", "脉形细小搏数，细为阴血不足，数为热，搏指为邪热内迫；舌刺肌燥津涸，呕逆烦冤，食粥乃定，显系胃气已虚、津液告竭，虚热上逆。细小搏数示正虚邪热，清热安胎为主，兼养胃气。", ["细", "数"]], "4594": ["病机", "脉形略起，按之短涩，短涩主气结阳微，非食滞重著。进温中下气后闪烁欲动，知阳微气结有形，浊阴内聚。夏月阴气在里，口食生冷，水寒入脘，脾胃阳弱，津液不运，故烦渴。辛香开气可醒阳宣浊。", ["短", "涩"]], "4595": ["病机", "脉微为阳气衰微，阴寒内盛，阴浊之气上潜。阳虚不能化阴，浊阴上逆，故以真武汤温阳利水、降浊。脉微主虚寒，与阴浊上潜相应，治在温补脾肾之阳。", ["微"]], "4596": ["病机", "脉坚搏，为湿热内侵肠胃，真气不主宣畅，邪气搏结。腹痛泻下白积，微微呕恶，胃气亦弱；睡卧露睛，神已先怯，稚年久延，虑有风搐之变。坚搏示邪实正虚，治以酸苦泄热佐辅正。", ["坚", "搏"]], "4597": ["病机", "脉空大，为劳倦挟湿，脾胃气虚，中阳不运，湿浊内停。潮热耳聋似阳邪，然自利不渴，舌上粉苔，形枯色槁，脉空大无力，显非实症。空大主虚，湿困脾胃，故从脾胃病治。", ["空", "大"]], "4598": ["病机", "脉左搏大，右缓，左盛右弱，示邪深入血分。夏秋暑湿从口鼻入膜原，水谷腥腻助热聚湿，湿胜则肿，热烁为痛。阳明脉束筋骨利机关，今躁痛夜剧，便秘渴饮，九窍不和，属胃病，内外相搏，痹而不通，治以苦辛寒宣之。", ["搏", "大", "缓"]], "4599": ["病机", "脉沉，主里主水，湿邪内胜为热，三焦不通。目黄气喘呛呕脘闷肢冷，潮热汗出略缓复热，口干自利，病九日不解。夏伏至霜降而发，湿郁化热，三焦气机壅塞，故脉沉而病重。", ["沉"]], "4600": ["病机", "脉细为阴伤津枯之象，搏如刃则阴亏而阳亢，虚火内迫。原文谓久热迫蒸，阴伤失守，苦药燥损，津液日枯，故脉细而搏指如刃。里热口渴、舌白、遗泄，皆阴伤失守、热迫下泄之症。此因病致损，非暴感表散可解，当分三焦逐邪，急调其阴。", ["细"]], "4601": ["病机", "脉右搏数，右主胃，数则为热。原文谓夏令伏热至秋而发，即阴气先伤、阳气独发，胃汁受戕。热伏于胃，故右脉搏数；胃汁受伤，故暂忌厚味，进甘药养胃，使内热自罢。此脉数非表邪，乃伏热内蒸、胃阴受灼之征。", ["数"]], "4602": ["病机", "脉短无神，短则气病，无神则正气衰。原文谓不渴思饮、得食欲呕、下利黄水、身热汗出不解、时时谵语，此湿热深陷入里，阻遏中焦，胃气上逆，故呕哕；湿热下迫，故利黄水；谵语为热陷心包之兆。脉短无神，正虚邪陷，防昏厥瘛疭。", ["短"]], "4603": ["病机", "脉小为阳气不振、阴寒内盛之象。原文谓夏秋内伏暑湿皆是阴邪，久疮渐至痞满、形寒，脉小。疮久伤阳，寒湿内阻，中阳不运，故痞满形寒；脉小者，阳气式微，不能鼓动血脉。当温中醒阳，莫以清凉治疮，否则更伤中阳。", ["小"]], "4604": ["病机", "原文未出脉名，但言阳明中虚，其脉不立束筋骨、利关节之用，是脉失柔和、不能束骨之象。冬温失藏，水源乏，肝风鼓动，乘胃入膈，冲咽上巅，右肢肿痛不举。此虚风由血液大耗、空动之地旋起，非辛散寒燥所宜，当以阴阳造偏为理。", []], "4605": ["病机", "脉形渐细，为营卫不振、中焦气虚之征。原文谓容色稍夺，不知饥不欲食，扪之不热而自云热，并不渴饮，间有寒栗。此非实热，乃营卫不和、中阳不运，故脉细而色夺，当治中焦，温养营卫，使气血渐充。", ["细"]], "4606": ["病机", "阳明脉虚，虚则气不足。原文谓冬温失藏，肝木反泄，血海不按期而经下，乃体不足、用太过之象。肝失藏血，疏泄太过，冲任不固，故经下失期；脉虚为阳明气血两亏。法当辛酸甘剂和肝之阴阳，苦降走泄则妨胃劫耗。", ["虚"]], "4607": ["病机", "原文未出脉名，但言肾虚，温邪内侵，形神消烁，废食忘寝，临晚寒热得汗而解。肾虚则根本已亏，温邪乘虚内侵，耗伤形神，故废食忘寝；临晚寒热得汗解，是邪在阴分、正气尚能作汗。议用复脉法，即复其脉气之虚，以救肾阴。", []], "4608": ["治法", "原文仅载“复脉汤去姜，加芍”，未述脉象，故脉素为空。此条属治法，从方测证，当为炙甘草汤加减，去姜之辛散，加芍之酸敛，意在复脉中之阴血，缓肝急而和营。其病机为阴血亏虚、脉道不充，故以复脉为治。", []], "4609": ["病机", "脉左搏右细，左搏为阳升太过，右细为阴血不足；颧赤、气喘、汗泄、竟夕不安，皆冬温伏热内发，阴衰阳冒之象。阳冒于上则颧赤气喘，阴衰于下则汗泄不安，故断为重症，脉象与症候互参，主阴衰阳浮之病机。", ["搏", "细"]], "4610": ["病机", "冬月伏邪至春发为温疟，汗出不解，知非新感。脉虚示正气先馁，先有遗症，故最忌耗散真气。脉虚主正虚，与伏邪内发、汗出不解相应，治当和正解邪，不可峻汗攻邪，以免更伤真气。", ["虚"]], "4611": ["病机", "阴疟脉沉，沉主里、主阴寒；微背寒、肢冷、食入脘痞，皆阳气伤极，不能温煦运化。春深木旺，恐克脾土而变肿胀。脉沉与阳虚里寒症候相应，故药宜理中兼理下焦，毋得祛疟治邪，以护阳气为本。", ["沉"]], "4612": ["病机", "脉弦如刃，弦为肝木偏旺、胃气已虚；烦渴、脘痞、呕吐、蛔虫上越，乃暑热复入三焦，浊气乘逆。病后调养失宜，本虚标实，弦劲如刃示木贼土败，胃虚浊逆，故姑进安胃降逆，冀呕缓气顺。", ["弦"]], "4613": ["病机", "脉弦迟，弦主阴寒内盛、气机不畅，迟主阳虚；形寒、神倦，得之忧思惊恐，卫外阳气暴折，阴寒不正之气外袭。脉弦迟与阳虚寒凝症候相应，将有痎疟病机，宜静摄护阳，使外邪不致深入。", ["弦", "迟"]], "4614": ["病机", "形色脉诊俱虚，虚为正气不足；寒热劫耗胃汁，脘中不知饥饿，二便不爽，皆中宫虚困之象。徒进清凉克消则更伤胃汁。脉虚与胃汁亏耗、元虚之体相应，考古暑病旬日不解，当酸泄苏胃汁，恐滋变病。", ["虚"]], "4615": ["病机", "脉弦，弦为少阳主脉，主气机郁滞；口渴乃少阳寒热乘胃，劫耗津液。脉弦与寒热、口渴症候相应，示邪在少阳，枢机不利，胃津受伤。故可与小柴胡汤和以解邪，使枢机和畅，寒热自解，津液得复。", ["弦"]], "4616": ["病机", "脉左弦右软，左弦为木火尚炽，右软为胃津日损。弦主肝旺，软主胃弱，故见寒热渐早、渴喜热饮。木火内炽则寒热，胃津不足则渴喜热饮。治以生津养胃、和以达邪，正合此病机。", ["弦", "软"]], "4617": ["病机", "脉虚为气衰之象，暴热而脉虚，是元气无归依，虚阳浮越而为浮热。知饥甘谷，里无留滞，说明中焦无实邪。病后调理，当两摄阴阳，以固元气，不可妄攻。", ["虚"]], "4618": ["误治", "暑热从口鼻而入，犯上中，分布营卫，发为寒热疟疾。误用发散祛寒，不知口鼻受热与皮肤受寒迥别；又肆行滋补，参、术、耆、地黏腻中宫，肺气壅闭，胃中滞凝，肿胀自上至下，一身气机不通。此即张戴人所谓邪得补而热盛，如养寇殃良。", []], "4619": ["病机", "阳气发泄，寒热，脉大。脉大为阳盛之象，阳气外泄则寒热，脉应之而大。此非实热内结，乃阳气发泄于外，故见寒热而脉大，当审其虚实，不可纯作实治。", ["大"]], "4620": ["病机", "脉左搏而大，气坠便不爽，究是肝气不疏泄。左脉主肝，搏而大者，肝气郁勃不舒，疏泄失职，故气坠而便不爽。通则不痛，通阴通阳则痛止。议用辛甘酸甘缓，两和体用，以调肝气。", ["搏", "大"]], "4621": ["病机", "面赤、口渴、脉大而空。脉大而空为虚阳外浮之象，劳倦挟痰，中气不足，虚阳上浮故面赤口渴，不可纯作时感治。当辨其内伤劳倦，挟痰为患，治宜补虚化痰，不可妄用表散。", ["大", "空"]], "4622": ["病机", "脉空搏，面赤，舌白，消渴，汗出，昼夜不已，两足畏冷，寒热渐迟。此积劳阳虚，外邪易陷，本虚表热。脉空搏为阳虚气浮，面赤汗出为虚阳外越，两足畏冷为下元虚寒。复加柴、葛、消导，谓之劫津，仍宜和营主治。", ["空", "搏"]], "4623": ["病机", "脉虚，寒热，食少，色夺。夏秋暑热为疟，久延阴伤，木火内灼，喉痛。脉虚为气阴两伤，食少色夺为脾胃虚弱，木火内灼则喉痛。此久疟伤阴，正虚邪恋，治当养阴清火，兼顾脾胃。", ["虚"]], "4624": ["病机", "原文言“色脉并非外感”，且补剂不应，由治错乱。产后下虚，痢止为疟，是营卫交损，阳维为病苦寒热。脉象虽未明言，但色脉不显外感，说明病机在营卫内损，非邪客表，故补剂不应，反因误治乱其气机。", []], "4625": ["主病", "脉如平人，但热不寒、烦渴、身疼、时呕，此温疟也。脉不显疟之弦数，反如平人，说明邪热内蕴而未形于脉，或病势尚浅。仲景桂枝白虎法一剂知，二剂已，紧扣“但热不寒”之温疟主症。", ["平"]], "4626": ["病机", "痰哮触外邪而发，坐不得卧，肾病为多。风寒客太阳，体弱内侵少阴；暑湿热从口鼻受，肺经应邪。久则热邪深入，气血损伤，八脉气衰，为寒为热，渐延损怯。火升喉痛，上热缓必下热炽，刚药难投，柔温佐通奇脉。", []], "4627": ["病机", "久疟针挑汗出乃止，经脉邪去，络脉邪留，胁下结疟母，按之坚、形高突。四年带病仍能食、便通，说明结聚不在肠胃，药入肠胃不效，因络脉附于腑之外廓，病位深在络脉。", []], "4628": ["病机", "下痢十三日，右关前按之实大，肌表畏冷，卧则神混多恶梦，不欲食，喉舌干涸。脉症不符，实大之脉见于下痢，非纯虚象。思夏至后阴不克复，阳欲散越，故议守阴固摄以护阳根，防其外脱。", ["实", "大"]], "4629": ["主病", "脉迟，下利，腹痛，喜热饮，食下则痞胀。迟脉主寒，平昔饮酒，中宫必有湿滞，寒湿内困，脾运不健，故下利、腹痛、喜热饮、食下痞胀。脉迟与症相应，主中焦寒湿。", ["迟"]], "4630": ["病机", "疟痢并作，经邪入里，色脉已属不足。邪从经入里，正气已伤，色脉不足示虚。清邪即当和血，说明病机为邪留血分，正虚邪恋，治当清透余邪兼和血分，不可纯攻。", []], "4631": ["预后", "脉涩，舌绛，耳聋，口渴，下利垢水七日，利后反有喘急。涩脉主阴伤血少，阴气走泄，阳独上冒，有昏厥之危。腹满亦热入之征，非轻谈易易，预后险恶。", ["涩"]], "4632": ["病机", "脉虚濡为气弱湿滞之象。原文述寒热后咽干、少腹微痛、微痢，因劳碌饮食失节致中气已虚，风木自动而心中苦饥。虚濡之脉反映中焦气馁、运化无力，湿浊内滞，故见微痢；风木乘虚扰动，则少腹微痛、咽干。治以甘缓熄风，正合虚濡所主之气虚风动病机。", ["虚", "濡"]], "4633": ["病机", "脉弦主木旺克土。原文虚劳久咳，肠垢自利，乃土虚木乘之候。弦为肝脉，虚劳日久，中气亏虚，肝木失养而亢逆，上刑肺金则久咳，下乘脾土则肠垢自利。此脉弦非实弦，乃虚劳中气不足、风木内动之象，故主肝脾同病之虚损病机。", ["弦"]], "4634": ["病机", "原文未识脉名，仅言形损脉垂。形损指形体消瘦，脉垂为脉气下坠无力，反映中气大虚、升降失司。咳嗽经月为上焦不降，下痢白腻为下焦不固，上下交病，中气衰败不能枢转。故治以建中法，培补中焦以复升降，此脉垂正是中虚不运、上下失交之病机体现。", []], "4635": ["病机", "左脉坚搏，为肾阴不固、疏泄太过之象。原文泄泻食减由脾胃虚弱，产后下损及肾，久泻伤肾，肾司二便而主闭藏，今左脉坚搏不柔，是肾阴亏虚、封藏失职，反见疏泄之象，故泄泻不止。坚搏非实邪，乃阴不守位、虚阳鼓动之候，治以摄固守阴。", ["坚", "搏"]], "4636": ["病机", "脉弦甚于数，弦为肝胆阳动，数因风火鼓烁。操持萦虑致肝胆阳气久动，内风乘胃攻触如饥而不能运食，腹鸣泻水，即久风飧泻。弦甚于数说明风阳亢逆为主，热象次之。形体清瘦禀木火，风火耗劫脂液，故治以补阳明之虚、泄厥阴之阳。", ["弦", "数"]], "4637": ["病机", "右脉弦迟，弦主阳微寒凝，迟主阳衰。胃脘痛至少腹，得泄泻则痛缓，小溲不利，乃中下阳衰、不主运化，膀胱腑气失职。弦迟并见，反映阳气不足、寒滞气机，故痛引少腹；泻后气暂通则痛缓。治以济生法通腑纳下，佐建中理阳，正合阳衰寒凝之病机。", ["弦", "迟"]], "4638": ["病机", "脉虚数为气阴两虚、虚热内扰之象。上咳下泄、食减形夺，乃足三阴亏虚，脾肺肾俱损。虚数之脉非实热，乃阴不敛阳、虚火浮越。原文大忌寒凉治嗽，正因脉虚数属虚损，寒凉更伤生气。当平补足三阴以崇生气，否则延绵成劳怯，此脉示虚损病机。", ["虚", "数"]], "4639": ["其他", "三诊仅记脉数，未附症候。数脉主热，亦主虚阳浮动。结合前案虚数上咳下泄之证，此诊脉数可能示虚热未清或阳气来复。因原文过简，仅能据脉数推断热象或虚阳扰动之机，具体所主需参合前诊症候，故归其他类，存疑待考。", ["数"]], "4640": ["病机", "脉大空搏，大而中空，主气血虚衰，久泻致中下失固，脾肾不摄，故脉象外大内空，按之搏指无力，与久泻相应，示固摄无权。", ["大", "空"]], "4641": ["病机", "脉沉弦，沉主里，弦主饮，饮为阴类，偏于夜分上午冲逆，不得卧，胃纳脾失散布，水湿旁渍，由肿为胀，因胀成喘，皆饮邪内停之机。", ["沉", "弦"]], "4642": ["病机", "脉沉弦，留饮久咳，清阳失司旋转，气机窒塞，沉弦为饮停阳郁之象，腻滞补阳无益，当治饮勿治咳，饮去则咳自止。", ["沉", "弦"]], "4643": ["病机", "怀妊八月，脉沉，气冲不得眠，背冷久咳，因抑郁阳失旋转，浊凝饮结，沉脉主里主饮，阳郁不伸，饮邪上冲，故当治饮不治咳。", ["沉"]], "4644": ["病机", "饮泛浊壅，经脉不通，虽未出脉名，然饮浊壅盛，阻滞经脉，气血运行不畅，病机为饮浊内泛，络脉壅塞。", []], "4645": ["病机", "脉虚饮泛，喘咳浮肿，虚脉主正气不足，饮邪泛溢，肾气不化，水饮上射则喘咳，外溢则浮肿，故以肾气丸涤饮。", ["虚"]], "4646": ["病机", "水结聚，壅遏经隧，呼吸有阻为噫，声在咽底，任脉关冲任，气痹水畜，血化水为肿胀，胸高腹大，下窍久闭，水性就下搏激，病机为水结血瘀，壅遏经隧。", []], "4647": ["病机", "冬至一阳初复，肢麻火升，失藏下虚，气塞心痛喘逆，戌刻冲逆，下起肝藏，厥逆犯上，坐不得卧，产后下虚更极，水谷湿气不循腑，渗入经脉，肝风沸腾，病根在抑郁，肝肾失司，腑气不化。", []], "4648": ["病机", "脉沉实主里实，本案风水浮肿而见沉实，说明水气壅盛于里，三焦经络阻塞、不得流行，故四肢不得屈伸、二便不利、中脘喘急。沉为在里，实为邪盛，非表虚风水可比，故治法先通膀胱经腑，以足太阳司开，使水有出路。", ["沉", "实"]], "4649": ["病机", "原文以脉浮言初病在表，脉沉言经年正馁、里受伤，浮沉对举说明病由表入里、由实转虚。咳嗽继肿、自上焦起，为风水皮水、治节不行、一身气痹；久病脉沉则正虚里伤，故议越婢法，既开太阳之表，又兼顾里伤之机。", ["浮", "沉"]], "4650": ["病机", "脉弦为饮，弦主饮邪内停、气机不利。年高下虚，天冷真气少纳，气冲为咳，说明下焦摄纳无力，饮浊随冲气上逆犯肺，故成哮嗽之症。此脉弦非单纯肝旺，而是饮邪与下虚并见，故谓最难除根，天暖阳气得助则自安。", ["弦"]], "4651": ["病机", "脉沉弦细，沉主里、弦主饮、细主虚，合面赤足冷、吸短有声、昏昏欲寐、下焦淋带不断，显系下虚不摄、饮浊上泛。饮家咳逆当治其饮，外饮属脾以苓桂术甘理脾阳，内饮属肾进肾气以收摄固纳，正合沉细弦所示虚寒夹饮之机。", ["沉", "弦", "细"]], "4652": ["病机", "脉数而形寒肢冷、大汗淋漓、不思纳谷，数非实热，乃阳微痰咳、清气不得旋转所致。酒客素伤脾胃，昔肥今瘦者为饮，阳虚不能温运，故脉数而外寒。宜理其阳，用苓桂术甘汤，温阳化饮以复清阳旋转之职。", ["数"]], "4653": ["病机", "脉小促，小为正气不足，促为邪热内迫、里气上逆。舌黄、语塞、口渴、喘息、下利黑水，皆伏邪在里、客气从热化之象；汗泄甚多而寒热不止，已非暴感。外郁之喘属肺，里热肾不纳气亦喘，故以越婢兼小青龙开太阳、平上逆。", ["小", "促"]], "4654": ["病机", "原文未识脉名，仅言细诊色脉为上实下虚。色痿腠疏属阳虚体质，膏粱厚味凝气蒸痰，咳呛频作；医用皂荚丸搜攒反伤肺气，致喷嚏不已而胶浊仍留。喘病在肺为实、在肾为虚，此上实下虚兼耳聋鸣响，故治下壮水源以熄内风，兼通补阳明。", []], "4655": ["病机", "原文未识脉名，但言色脉素昔遗患。深秋暴冷、哮喘并频嗽，虽有新凉外束，然肾虚气少藏纳才是根本，况曾有失血之症，下元更亏。外寒引动内虚，气不归元而上逆为喘，故议用固摄，纳肾气以平冲逆，非单纯解表可治。", []], "4656": ["病机", "本案论幼年哮喘，因寒热失和、食味不调致饮邪聚络。原文未提脉象，而述“饮邪为阴邪乘”“伏于络脉之中”，说明病机为阴寒饮邪伏络，遇外凉相召而发。饮邪内伏，故发散攻表、涤痰逐里、温补皆无干；治以夏月艾灸肺俞、秋分暖背护阳，正是针对藏阳未旺、饮邪窃发之机。", []], "4657": ["病机", "本案酒客中虚，湿热内阻，经脉之气不主流通，兼长夏湿气升腾，蒸郁发黄。原文未言脉，而明言“本虚标实”，脾胃不和已属内伤，徒以渗利治黄无效。病机为脾虚湿热内蕴，正气已伤，故见食少便溏、不堪任劳；五旬以外阳气日薄，冬月失藏，议脾肾两治以培先后天生气。", []], "4658": ["病机", "久病脉弦，弦为肝木之象，主郁主痛。脾胃大困，水谷失运，气道壅塞，渐生胀满，前曾发黄，皆属肝脾郁结。脉弦见于久病，说明肝郁乘脾、气机壅滞，木不疏土，故运化失职而胀满将生。原文虑“数月内损不复，长夏恐致增剧”，正是肝脾郁结日久、正气渐损之病机。", ["弦"]], "4659": ["病机", "溃疡未合，频进培补，反昼夜微寒潮热，食物日减，形神日损，近日热甚衄血，口干舌绛，肉腠麻木。原文未言脉，而断为“大虚之体，夹杂暑热客气”，深虑液涸昏厥。病机为气阴大虚，暑热内迫，热伤血络则衄血，阴液亏耗则舌绛口干，故议复脉汤以复其脉气。", []], "4660": ["治法", "本条仅列“复脉汤（即炙甘草汤）”方名，承前案大虚之体、暑热客气、液涸昏厥之虑而设。复脉汤为益气滋阴、通阳复脉之剂，主治脉结代、心动悸，气阴两虚之证。原文未及脉象，而方名“复脉”即示其治在复脉气、救阴液，属治法类条文。", []], "4661": ["病机", "本案阴分果虚，经脉有湿热阻塞，下焦发疡，津液不得上涵，遂久咳不止。原文未言脉，而明示病机为阴分亏虚、湿热阻络：湿热下注则发疡，阴津不能上承则久咳。幸未伤及中宫，故以薄味静养图安。此属虚实夹杂，阴亏为本，湿热为标，络脉壅阻而津不上涵。", []], "4662": ["主病", "脉虚主正气不足。督脉虚，腰背痛，神倦，痔血。督脉循脊络肾，总督一身之阳，督脉空虚则腰背失养而痛，阳气不振则神倦；气虚不能摄血，下注肛门则为痔血。脉虚与督脉虚、神倦、痔血相应，说明病本在阳气亏虚、督脉失充，属虚证主病之脉。", ["虚"]], "4663": ["病机", "五朝痘症，神识颇清，全赖苦降之力。论年长出痘，肝中相火、肾藏龙火皆得升腾，少阴脉循咽挟舌，厥阴脉贯膈绕咽，一水不能制二火，恐阻塞咽喉，阳气燔灼，涌吐涎沫如漆如胶，原在难治之条。原文未言脉，而引《经》“火淫于内，治以苦寒，佐以咸寒”，说明病机为水火不济、二火燔灼。", []], "4664": ["病机", "脉右软滑，左觉空弦。软滑主湿痰内蕴，右脉候脾肺，湿痰阻于中焦，故见痞闷、不思饮食；左脉空弦，空为不足，弦主肝木乘脾，结合汗吐下后中气大虚，邪气尚盛，正虚邪恋，故神情困倦、语言无力。此脉象揭示中气大虚而湿热痰邪未化，少阳枢机不利，疟疾仍作。", ["软", "滑", "弦", "空"]], "4665": ["病机", "脉弦滑多带空象。弦滑为风寒湿热浊痰未化之象，空则示元气阳气内虚。虽寒热来势颇轻、呕亦稍定，似属佳兆，然脉见空象，说明正虚已甚，邪未尽而正先虚，故须扶正化邪，恐邪未尽而正先尽。此脉象主正虚邪恋之病机。", ["弦", "滑", "空"]], "4666": ["病机", "脉弦右滑，尽带空濡之象。弦主风邪少阳，滑主湿热浊痰，空濡示元气阳气内虚。白苔满布、面色晦滞，为湿浊痰热内蕴；寒喜热饮、热反不渴，乃兼夹湿浊之征。脉象说明风邪外感引动湿热浊痰，兼夹为患，正虚邪盛，故须化湿、化热、化痰以除兼夹，使风邪寻路而出。", ["弦", "滑", "空", "濡"]], "4667": ["病机", "脉弦而芤。弦主肝阳横逆，芤主阴血不足。伏暑晚发，邪从三焦内陷肝脾，肝阳上逆则肢麻厥逆，旁流中土则麻。脉弦而芤，说明暑邪内陷、肝阳逆而阴血已伤，邪盛正虚，故麻厥并至，不惟邪盛，早见肝阳逆矣。", ["弦", "芤"]], "4668": ["病机", "本段未识脉名，纯论病机。喘出于肾关于肺，标本同病。邪盛正衰，热在上焦，肺为热火所烁，内被肝火上燔，金不生水，水不涵木，木反侮金。此段说明肺肾同病、肝火犯肺之病机，故以复脉汤治下、苇茎汤治上，标本兼顾。", []], "4669": ["病机", "右脉弦数，左脉细小。弦数主暑热化火、内挟饮食积结，右脉候脾胃，故阳明化火伤津，盘踞小肠，口糜便泄转痢；左脉细小主真阴不足。脉象说明暑热化火伤阴，兼饮食积结，邪盛正虚，故便则多痛，邪盛则实，而阴分已伤。", ["弦", "数", "细", "小"]], "4670": ["病机", "右脉弦数者能缓能和，左脉细小按之无神，关部带弦。弦数缓和为邪减佳兆；左脉细小无神主真阴不足，关弦主肝木。真阴不足难以涵养肝木，肝木顺乘中土，加之胃津被热气所伤、下痢所劫，故杳不思纳、干哕恶心。脉象说明邪减而正虚，真阴亏耗、肝木乘土之病机。", ["弦", "数", "细", "小"]], "4671": ["病机", "右寸脉形滑数，关部濡软，左手皆细小按之模糊。滑数主温邪痰热，右寸候肺，故咳呛、气息短促；濡软主湿痰阻中；左细小模糊主元气受伤、真阴不足。脉象说明风邪外感引动温邪，又被湿痰所阻，元气受伤，邪陷手足厥阴，势已危笃，有脱变之虞。", ["滑", "数", "濡", "软"]], "4672": ["病机", "脉象空弦，空为元气本虚，弦为邪结中宫。温邪外感、秽浊内踞，湿痰食滞交结，元气无力化达，故脉见空弦而神情困倦。此非单纯实邪，乃虚中夹实，邪恋肺胃而肾气亦衰，故曰非补不可。", ["空", "弦"]], "4673": ["病机", "左脉空细为阴血亏虚，右脉弦急为邪滞气逆。湿痰邪滞之外又有瘀血在里，邪从上出而不下行，气机逆乱，故呃忒频、呕恶不止。脉弦急示气不平，空细示正虚，虚波暗起可虑。", ["细", "弦", "急"]], "4674": ["病机", "脉尚弦急，说明陈腐之邪仍阻中宫，气机未平。呃轻呕重，因邪欲出而路逆，上而不下，失胃气下行之顺。弦急为邪实气逆之象，犯肺为咳、犯胃为呕，必去尽宿邪方安。", ["弦", "急"]], "4675": ["预后", "脉象稍和，为荡涤宿邪后胃气渐复、下行为顺之兆。呕恶减、呃忒缓、呻吟除、大便通，皆邪去正安之征。脉和示病势向愈，尚须磨荡余邪，可卜旋元吉。", ["和"]], "4676": ["病机", "脉细而数，细为阴虚，数为动火。阳络伤血外溢后脉宜静，今反细数，是虚阳上扰、阴血下虚、气不归元。气急喘促、胸闷胁痛、便黑心悸，皆虚火升动、血不配气之象，非真火乃虚寒。", ["细", "数"]], "4677": ["治法", "本段仅列生脉散加冬瓜子、石决明、葳蕤、枇杷叶、川贝母、薏苡仁、橘红、茯苓、燕窝，未载脉象。方以益气养阴、清肺化痰、平肝和胃为法，从方测证，当属气阴两虚、肺胃痰热、肝阳上扰之候。", []], "4678": ["病机", "未识脉名，据症析机：花甲之年肝肾素虚，肺胃新感，又经消克，因病致虚、因虚益病。外热递减而内热不清，咳嗽痰黏、气促形倦、纳少胃呆、舌苔剥、音不能扬、睡中言语，显系肺胃之热不能外泄上清，势逼下焦，两伤肝肾。", []], "4679": ["病机", "左脉过弦，为肝血内亏、不能涵养肝木，肝性刚强而亢逆。入营吐血、入胃脘疼、上升头眩，皆肝病之甚。脾土弱不能生金制木，木寡于畏，横逆肺金，故咳；湿郁化热上行，耳脓失聪，皆肝脾同病之机。", ["弦"]], "4680": ["病机", "右关弦数而大，弦主湿郁，数主热，大示邪盛。原文述“热胜则肿，火甚则痛”，又见“午后发热，鼻准色赤”及咽痛、舌红光红苔剥，显系脾经伏热，热伤阴气，湿邪下陷，故四肢浮、阴囊肿、小水不利。脉象反映湿热壅盛、阴分受损之病机。", ["弦", "数", "大"]], "4681": ["治法", "本段仅列方药，未述脉象，故脉象要素为空。方用生脉散合粉丹皮、左牡蛎、陈香橼、鲜藿斛、白芍药、抱茯神、伏龙肝、藕汁，意在益气养阴、凉血潜阳、和胃化湿，属治法范畴，非直接论脉。", []], "4682": ["病机", "原文谓“短脉虽长，弦数未罢，且兼滑大”，长脉示元气尚旺，弦数主湿热未清，滑大示食积痰滞交结阳明。症见不饥、饱胀、午后微热、鼻色微红，皆阳明湿热食滞壅阻之象，脉象反映邪实未去、胃府壅滞之病机。", ["长", "弦", "数", "滑"]], "4683": ["治法", "本段仅列方药，未述脉象，故脉象要素为空。方用生脉散合左牡蛎、陈香橼、伏龙肝、鲜藿斛、粉丹皮、炙鸡金、鲜藕汁、白芍药、福泽泻、抱茯神、雪羹饮子，意在益气养阴、潜阳和胃、渗湿消积，属治法范畴。", []], "4684": ["病机", "左脉细长，右关弦数。原文谓“数则为热，弦则为湿，细为阴分之细，长为寿命之长”，长示元阳旺而阴分虚，弦数主湿热郁于阳明。症见舌苔黄浊、气急喘促、心神恍惚、胁背胀逆，皆湿热上熏、中上二焦受累之象，脉象反映湿热壅盛、阴分不足之病机。", ["细", "长", "弦", "数"]], "4685": ["病机", "脉象弦涩，弦主肝胆郁结，涩主营血滞涩。原文述“郁结不解，以致右胁下痛”，又因温补燥烈“既伤营血，又滞浊痰”，致气分日窒、右降不及，症见舌上生苔、大便燥结、面黄色滞，脉象反映肝胆湿热久伤、痰血瘀滞之病机。", ["弦", "涩"]], "4686": ["病机", "次诊“脉之涩象稍和，弦则未改”，涩减示营血渐通，弦存示肝胆郁结未解。原文谓“积下之后，胁部稍能活动”，但“痰血两邪尚有盘踞之意，而未解散”，脉象反映痰血瘀滞虽减而未净、肝郁未舒之病机。", ["涩", "弦"]], "4687": ["病机", "左关脉弦，原文谓“弦主乎湿，亦主乎肝”，右关主脾。木乘土位，湿不自消，脾为湿困，症见五更泄泻、中宫痞、少纳多痰、口舌常干，脉象反映肝郁乘脾、湿浊内困之病机，病在肝脾而不在肾。", ["弦"]], "4688": ["病机", "久痢伤肾，肾虚气不归元，故呼多吸少而喘；龙雷之火随气上逆，则口干、鼻燥、咽痛；脉见有余之象，乃虚阳上浮之假象，非真实邪盛。此脉象反映下虚上盛、火不归元之病机，主肾虚喘逆、虚火上炎之证。", []], "4689": ["病机", "久服知柏苦寒，耗伤真阳，浊阴用事，真阳上越，故烦躁眩晕；尺脉微细，为肾阳衰微、下元虚冷之征，小便不举亦由阳不化气。此脉主肾阳虚衰、阴寒内盛之病机，与少腹作痛、冬至阳微相应。", ["微", "细"]], "4690": ["病机", "脾经素痰为寒所遏，痰阻经络，上则舌本不言，下则四末痛痹，外则四肢冷清，内则神呆。脉象小滑，小为阳气不充，滑为痰湿内盛，故主寒痰壅盛、阳气痹阻之病机，与舌强、痹痛、肢冷诸症相应。", ["小", "滑"]], "4691": ["病机", "鼻衄上流、白浊下注，脉象弦数。弦主湿郁，数主火盛，中宫湿火分头为病，上溢则衄，下渗则浊。此脉示中焦湿火交蒸之病机，主湿热蕴结、上下分注之证，与衄血、白浊相应。", ["弦", "数"]], "4692": ["病机", "寒热之下，下痢胸痞，脉促气短。促为阳盛而阴不能和，邪热内陷阳明之府，与下痢胸痞并见，乃太阳之邪不传经而直入府之象。此脉主邪热内结、气机壅遏之病机，与下痢、胸痞、气短相应。", ["促"]], "4693": ["病机", "尺脉细、关脉弦，尺细为肾精亏虚，关弦为肝木偏旺，肾虚则二阴失养，故大便精窍欲通而腰间苦痛。此脉主肾虚肝郁、精血不足之病机，与腰痛苦痛、二便不利相应，原文明言“肾家之虚也”。", ["细", "弦"]], "4694": ["病机", "肺脉固涩，脾胃脉亦涩，白苔满布，乃中焦湿土先病，累及肺金。涩为湿滞血少，肺失宣降则鼻不闻香臭。此脉主湿困中焦、上累肺金之病机，与白苔、鼻塞失嗅相应，故治当崇土化湿以绝病根。", ["涩"]], "4695": ["病机", "督脉内空，不能统领诸阳敷布于背，故背重如山；脾经湿痰随肾气夹背而上，下则囊肿。脉内空为阳气虚衰、督脉失充之征。此脉主督阳空虚、湿痰上逆之病机，与背重、囊肿上下分病而一以贯之相应。", ["空"]], "4696": ["病机", "脉息沉弦，沉主里，弦主风主痰。症见语言艰涩、口角流涎、肢麻气短，乃内风习习，感召外风，风痰阻络，发为类中。沉弦示风痰内伏，病位在里，故先理风痰，后议大补。", ["沉", "弦"]], "4697": ["病机", "左脉弦数，弦为肝旺，数为火盛。舌红无津，水不足而火有余，阴亏火旺之象。前药火衰大半，然余热未清，故以泻南补北法，滋水制火，使水火既济。", ["弦", "数"]], "4698": ["病机", "痢久一月，脉形弦细，肢体无力，溺清利红，中脘不舒，舌苔湿白。弦细为脾肾阳气暗伤，余邪未净。久痢伤肾，下焦已及，故不独补脾，尤宜补肾，理中兼固下元。", ["弦", "细"]], "4699": ["病机", "脉象浮弦，弦则为痰，浮则为风。风邪外感，痰饮内起，内外合邪，咳嗽并作。然浮见于左者微，见于右者著，知风轻痰重，故治痰之品宜重于驱风，安内攘外。", ["浮", "弦"]], "4700": ["病机", "脉见两弦，弦主痰饮，亦主肝旺。久呕痰涎，非败症，然久吐恐成败。肝阴不足，火本旺，舌红且绉，酒客湿热又胜，用药刚柔相济最难，拟连理汤合戊己法，温中兼清。", ["弦"]], "4701": ["病机", "脉数，溺疼，苔黄，口燥，自汗，神疲。身热渐缓而阴亏留热未平，数脉为热为虚，乃「寒之不寒，责在无水」，阴亏火旺，余热未清，故仍守前法，滋阴清热。", ["数"]], "4702": ["病机", "痹久三气郁而化热，脉象弦数，口舌干腻，小溲带黄。弦为痹为痛，数为热，乃「经热则疼，络热则痹」之候，与初起风寒湿不同，故拟蠲痹法加减，清热通络。", ["弦", "数"]], "4703": ["病机", "失血后气升则头痛目红，气降则阳举梦遗，筋惕肉𥆧，指甲色变，脉息弦细。弦细为肝经伏热袭入肾经，水中火发，虽非真火，亦可畏也。法当清热潜阳，仿乙癸同源例治。", ["弦", "细"]], "4704": ["病机", "脉弦涩而数，弦主痛、涩主瘀、数主热，合之见血分瘀热互结。原文谓痛得食则缓而午前剧、黄昏甚，属阳中之阴、阴中之阴，更见但头汗出、便下色紫，显系酒热所瘀之血病，非气虚不能摄血。瘀者宜消，故脉象紧扣瘀热内阻之机。", ["弦", "涩", "数"]], "4705": ["病机", "脉象细涩，左关带弦。细为阴血枯少，涩为瘀血浊痰阻膈，弦主气机郁滞。原文谓阴枯于下、阳结于上，阳明瘀血浊痰阻膈，致饮食之下为噎为噫，胸中窒塞、吐白沫、食后作胀、大便坚结，势欲成臌，脉象正合阴枯阳结、痰瘀互阻之病机。", ["细", "涩", "弦"]], "4706": ["病机", "次诊脉象细涩，左关带弦，与前诊同。原文谓胸中窒塞稍和、白沫上泛亦缓，系上焦阳气暂得温通，结者能开；然阴血仍枯，故饮食之下不惟为噫为嗳，且兼胀逆不舒、大便坚结。细涩弦之脉，仍主阴血枯涩、气结痰瘀未化，病情正剧时也。", ["细", "涩", "弦"]], "4707": ["病机", "脉息之小者转大，且数且弦。小为正气不足，大为邪势张，数为热，弦为郁。原文谓寒郁之热颇有开泄之机，然所开所泄独在大筋小络，肺胃不能通，气分阴分无力托邪，故见口干苔黑、舌强难言、牙关不开、鼻衄嚏出、胸闷气粗、昏昏默默而睡，脉象示邪热尚在险途。", ["小", "大", "数", "弦"]], "4708": ["病机", "左寸脉沉而缓，沉主里、缓主寒。左寸候心，脉沉缓而舌色淡白，口唇先寒，原文谓阳明胃府久被寒痰所阻，累及于心，子病及母。胃脉环唇口，唇口先寒，正是寒痰阻胃、心火不温之象，故脉沉缓而舌淡，病机在寒痰内阻、心胃阳虚。", ["沉", "缓"]], "4709": ["病机", "脉形弦细，不见缓和。弦主暑湿郁阻三焦、气机不和，细主正气已伤。原文谓身热夜重日轻、首还如裹、背独疼、二便失调、口苦、恶心痞闷，三焦正病而暑气日多，脉不见缓和，示邪留正伤、三焦气机壅滞，用药最难著手。", ["弦", "细"]], "4710": ["病机", "脉数芤细，数为邪热未清，芤为阴血大伤，细为正气不足。原文谓无形之热与有形之湿结而不开，变而为痿，痞热依然不改，就脉而论邪留一半、正已大虚。数芤细并见，正合热邪留恋而营阴已亏之病机，故治以半夏泻心汤专开其痞。", ["数", "芤", "细"]], "4711": ["病机", "原文未识脉名，以营卫血脉立论。谓营行脉中、卫行脉外，血脉盛则营卫流行，血脉衰则营卫不通，不通则痛。痛久病在络，不独气患；五脏内亏、气血不充，阴阳道路难宣，故不可急急攻破，当培土生金、补火生土，使肺气旺而燥金当令。", []], "4712": ["病机", "脉形软弱，为三阴阴气内旺、阳气衰微之征。阳衰则浊阴用事，火土不能合德，故见背脊生胀、两腿作酸、气息短、嗽痰少寐。浊阴之气已加阳位，中下两焦自病，非温通阳气不可，否则旧病复发。", ["软", "弱"]], "4713": ["病机", "脉来四至，未至太息不见五至，亦属迟脉。迟则为寒，又属阳虚。温通后痛止，然真火难生，浊阴窃发，故需阳和之品日进，以温阳散寒，防其反复。", ["迟"]], "4714": ["平脉", "脉已五至，为气血之平。平则营卫调和，阴阳和协，无亢害之机，有承制之力。然此皆药力偏见长，久则药力增气，故宜少不宜壮，壮火食气，少火生气。", ["平"]], "4715": ["主病", "脉紧为凉风暴感，外从皮毛渐入于卫。阳气久虚，护卫失职，故形寒、苔白、背腿胀酸、脘胁苦痛。急须解表，使凉风外达，不使郁久发热。", ["紧"]], "4716": ["病机", "桂枝汤调营卫后，脉之中外自得和谐，病有向安之处。然时病时安，正气盛衰无定，新感凉风、久积阴寒未能一时化尽，原属阳气内亏，不敷布使然。", []], "4717": ["病机", "脉反弦也，显系肝郁暂开，浊阴之气归并中宫。中宫阳气前不能通，后不能运，故胁疼移入下胁，及中脘背胀。需雄烈之品斩关直入，开通阳气，驱逐浊阴。", ["弦"]], "4718": ["主病", "脉象芤数，为热湿交蒸，邪从大便而泄，元气随泻而伤。伤则所蒸之邪内踞，故大腹胀满、足跗浮肿、小溲短赤、饮食减少、精神困倦、口舌干燥。病势有加，每易喘脱。", ["芤", "数"]], "4719": ["主病", "脉数弦急，合色萎肉削、气怯言微、右乳肿痛，为脱营之症。肿痛质热色红，颇有内溃之情。气血大亏，肝脾更病，故饮食减少、神情困倦、腰脊苦疼、口舌干燥、寤寐失常、少腹下坠、气火上炎。", ["数", "弦", "急"]], "4720": ["病机", "脉急虽除而弦数依然，弦主肝郁、主痰，数主肿、主火，痰火交煽，肝郁内结，故结肿坚硬如石。然食少、腰疼、口燥、言微、腹坠，种种虚象，乃营内伤而瘕外形，攻补两难，脉象反映正虚邪结之病机。", ["弦", "数"]], "4721": ["病机", "脉象皆数，右寸关弦而且滑。数主热，弦主风、主痰，滑主痰食。燥风外感引动伏暑化热，兼痰食中结，故脉数而弦滑。结而不开，津液暗伤，将变痉厥，脉象示邪火痰食交结之病机。", ["数", "弦", "滑"]], "4722": ["病机", "不发之时脉静而细弦。细为元阳不足，弦主肝木偏旺。肺伤于悲哀发散，清肃失职，木寡于畏，怒则为哮。脉静而细弦，示本虚标实、肝肺同病之机，故非补非温不可。", ["细", "弦"]], "4723": ["病机", "右脉虽空，形弦大且数；左虽沉，反弦急不静。空为虚，弦大为湿热郁蒸，数为化热伤阴。中虚湿热生痰饮，咳喘溺黄口干，脉象示虚中夹实、湿热伤阴之病机。", ["空", "弦", "大", "数"]], "4724": ["病机", "右脉弦中带数，左虽数偏见濡象。数属暑气，弦濡为风少湿多。风湿外病，伏暑内动，湿遏暑邪，故寒热如疟、面黄苔白、溲赤不渴，脉示热处湿中之病机。", ["弦", "数", "濡"]], "4725": ["病机", "右脉弦象稍和，左濡略弦，数象仍然。弦濡减轻示湿邪暗化，数仍主暑尚留。暑必夹湿，湿去暑自消，脉之转移与病机相应，示暑湿渐解而未尽之候。", ["弦", "濡", "数"]], "4726": ["病机", "脉弦带滞，弦主湿郁，滞为黏滞不畅。湿为黏滞之邪，最难骤愈，脾为湿所浸淫而重滞，故寒热似疟、溲不利、肢体不松。脉象示暑湿尚郁、脾阳受困之病机。", ["弦", "滞"]], "4727": ["病机", "脉弦带数，弦主湿郁、兼涉少阳，数主暑热。但热不寒、咽干带苦，乃暑湿之邪尚留于脾，兼涉少阳。脉象示脾湿未化、少阳郁热之病机，故治以清脾饮佐五苓散。", ["弦", "数"]], "4728": ["病机", "脉来濡数，濡主湿、数主热，正合原文“湿邪退矣，暑犹在也”之暑湿留恋三焦。暑为阳邪，湿为阴邪，湿热交蒸则脉濡数；暑布三焦、气化不利，故“小便未利，胸次时痞，发热两度”。苔黄为湿退化热之象，苔有剥处则阴被暑伤，故脉数中兼濡，示虚中夹实、气阴两伤之机。", ["濡", "数"]], "4729": ["病机", "诊得脉数，原文直断“数者，热也”，热由暑邪所化，暑必夹湿，故午后发热、夜半而衰，如疟之状。中土之邪客涉少阳，故口苦咽干；疹块外发为风之余气透达。所嫌便溏热、腹隐痛，是肠间暑滞未清；舌苔剥落则阴分已亏。脉数在此既主暑热未清，又示虚中留实、正虚邪恋之病机。", ["数"]], "4730": ["病机", "大汗后身热竟退，暑邪已解，然余邪未尽而阴气必伤。脉来濡中带数，濡为湿之余象，数为热之残存，正合“余邪未尽，阴气必伤”之机。故午后微热如疟、舌苔剥落、小便浑浊、饮食少进，皆阴伤余热未清所致。此脉示邪少虚多，故治宜“清养兼施”，清其余热、养其已伤之阴。", ["濡", "数"]], "4731": ["病机", "本段未出脉名，专论病机。原文谓“素体湿热，又挟阴虚”，湿热“出自先天，牢不可破”，与后天外感内伤之湿热不同。因从事膏粱、更多嗜欲，外增湿热、内耗阴精，致“脏腑营卫常有春夏之情，而无秋冬之气”，风火相煽而耳鸣。此论湿热与阴虚并存、先天后天夹杂之病机，非脉象所主。", []], "4732": ["病机", "脉气双弦，弦为肝脉，主气机郁滞、痰饮内动。原文论“阳分比阴分更亏”，秋分燥气加临，膏滋偏阴而阳更衰，阴阳偏胜、功过相抵。霜降始寒，寒气外侵则痰饮内动，弦脉正应寒饮内停、肝气不舒之机。双弦并见，示左右俱有郁滞，与“饮食反减”“病势不解”相应，属虚实夹杂、阴阳两伤之候。", ["弦"]], "4733": ["病机", "本段未出脉名，专析脏腑升降。原文谓“左升太过，右降不及”，左属肝、右属肺，肝反多所横逆之用，肺失清肃之职，木寡于畏而反侮于金。气旋于右，不能透彻于上、归缩于下，邪正相争盘旋胁部，得后与气则快然如衰。此论肝升太过、肺降不及、木侮金之病机，与脉象无直接对应。", []], "4734": ["病机", "右脉弦强，弦为肝脉，强则气火亢盛。原文引“气有余便是火”，气从左边起者肝火也，故以左金丸、当归龙荟丸清泻肝火。右脉弦强，示肝火横逆、气火益炽之机，与“为痈为血”之虑相应。脉弦而强，非虚弦可比，是邪实火旺之象，故治法直指苦寒泻火、左金制木。", ["弦"]], "4735": ["病机", "脉来虚软，虚为正气不足，软为脉体无力，正合原文“元气不足也”之断。右半身不遂而脉虚软，示气虚不能运血、经络失养，非风痰实邪阻络之实证。虚软之脉主元气亏虚，故治法“当温补”，以补气助元、温通经脉。此脉与半身不遂并见，说明病本在虚，不可妄攻。", ["虚", "软"]], "4736": ["病机", "脉数主内热，本案偏枯而见脉数，说明内热壅盛，热灼津液，筋脉失养，故见偏枯。数脉为热象之征，与内热症候相应，提示病机以热为主，非单纯虚损。", ["数"]], "4737": ["病机", "六脉模糊，脉象不清，主阳虚湿痰内阻。阳虚则脉气不充，湿痰阻滞脉络，气血运行不畅，故脉象模糊。右肢偏废为湿痰阻络之症，与阳虚湿痰病机相应。", []], "4738": ["病机", "脉来无力，主阳虚。阳虚则鼓动无力，痰滞脉络，气血不畅，故肢麻言塞。此脉无力与阳虚痰滞相应，防中者，提示中风先兆，病机为阳气虚衰，痰浊阻络。", ["虚"]], "4739": ["病机", "脉象弦大，弦主肝风，大主邪盛。肝风犯胃，胃气上逆，故膈胀呕恶、饮食顿减。弦大之脉反映肝风内动、胃失和降之病机，与膈胀呕恶症候相应，故拟苦泄一法。", ["弦", "大"]], "4740": ["病机", "六脉不静，脉象躁动不宁，主虚风内动。阴虚不能潜阳，风阳上扰，故头晕心悸。脉不静为内风萌动之象，与头晕心悸症候相应，病机属虚风内动。", []], "4741": ["病机", "脉滑主痰，大主风阳亢盛。肝风内煽，挟痰上扰，故头晕多痰。滑大之脉反映风痰壅盛之病机，与头晕多痰症候相应，治宜柔肝熄风。", ["滑", "大"]], "4742": ["病机", "脉来细数，细主阴血不足，数主火旺。失血后阴血亏虚，水弱不能制火，火旺刑金，故气喘咳呛。细数脉与阴亏火旺病机相应，延久成怯，提示预后不良。", ["细", "数"]], "4743": ["病机", "脉来软弱，主阳气虚衰。积劳内伤，阴损及阳，阳气虚弱不能鼓动脉道，故脉软弱。咳血延至气喘，为阴损及阳之候，脉软弱与虚脱先兆相应，故防其虚脱。", ["软", "弱"]], "4744": ["病机", "六脉无力为气血两虚之象，咳血便溏并见，示脾土虚弱不能生金，肺气亦损。脉无力主虚，故断为怯症之渐，治当培土生金，补脾益肺以复气血。", ["无", "力"]], "4745": ["病机", "失血后六脉少力，乃阴血亏耗、阳气亦衰之征。咳呛便溏示肺脾同病，阴络受伤而阳分大亏，脉少力正合虚损之机，故宜扶阳生阴，阴阳并补。", ["少", "力"]], "4746": ["病机", "脉络空虚为精血亏虚之象，遗精咳血耗损阴精，腰背作痛、神色㿠白皆精血不能充养之征。脉空虚主虚，故为怯症之根，当甘温补养以填精血。", ["空", "虚"]], "4747": ["预后", "便溏下血、脾肾两虚，气逆自汗更伤元气，六脉无力示正气衰败。脉无力主虚，虚极则脱，故断为颇有衰脱之险，病情棘手，预后堪忧。", ["无", "力"]], "4748": ["病机", "右寸浮大主肺经风热，风温化热壅肺，气急咳呛、痰多色黄皆热邪犯肺之症。浮为风热在表，大为热盛，右寸应肺，故用泻白法清泻肺热。", ["浮", "大"]], "4749": ["病机", "六脉弦数主阴虚火旺，血溢后阴亏，虚火灼肺，肺络伤而津不上承，故咳呛不止、咽痛失音。弦为阴伤木旺，数为热，脉症合参，殊非小恙。", ["弦", "数"]], "4750": ["病机", "左脉弦大主肝郁化火，七情郁结则肝气不舒，燥火内燃，灼肺则咳逆咽干。弦为肝旺，大为火盛，左脉候肝，故治以仲景法疏肝清热。", ["弦", "大"]], "4751": ["病机", "脉数主热，久咳不已、畏风示肺气虚弱，腠理疏而津液亏，虚热内生故脉数。数而无力为虚热之象，治当固表育阴，补肺气而滋津液。", ["数"]], "4752": ["病机", "脉来弦数，弦为肝旺，数为热盛，肝热循经上射于肺，故见咳呛膈痛。肝热灼肺，肺络受损，有咯血之虞，故曰防络伤咯血。此脉象揭示肝热射肺之病机，主咳呛膈痛，与肝热、肺络伤相应。", ["弦", "数"]], "4753": ["病机", "原文未明言脉象，但言色脉少神，提示脉象失神。脾气虚而津不上承，久咳不已，色脉少神，乃脾虚不能生金，肺失濡养。补土生金法针对脾气虚之本，此段主病机为脾虚及肺，与久咳、色脉少神相应。", []], "4754": ["病机", "脉来无力，为虚损之象。久咳形衰，肺肾并亏，肺虚不能主气，肾虚不能纳气，故脉无力。金水六君法旨在补肺肾之虚，此脉象主肺肾两亏之病机，与久咳、形衰相应。", ["无力"]], "4755": ["病机", "六脉弦大，弦为肝旺，大为火盛，肝火刑金，灼津为痰，故痰嗽不爽。肝火亢盛，易伤肺络，恐络伤动血。此脉象揭示肝火刑金之病机，主痰嗽，与肝火、肺络伤相应。", ["弦", "大"]], "4756": ["病机", "原文未明言脉象，但言色脉少神，提示脉象失神。远年久咳，肝肾虚，水泛为痰，乃肝肾亏虚，水不化气，上泛为痰。急宜培补，此段主病机为肝肾虚水泛，与久咳、色脉少神相应。", []], "4757": ["病机", "脉来细数，细为阴亏，数为虚热，肝肾阴亏，虚火上炎，故久嗽咽痛。阴亏难复，故甚为棘手。此脉象揭示肝肾阴亏之病机，主久嗽咽痛，与阴虚火旺相应。", ["细", "数"]], "4758": ["病机", "脉弱为气血不足之象。久嗽脉弱，先后二天均虚，脾为后天，肾为先天，脾肾两虚，故脉弱。若过投寒凉，必致胃损减食，此脉象主脾肾两虚之病机，与久嗽、胃损减食相应。", ["弱"]], "4759": ["病机", "六脉弦数，弦为肝风，数为热盛，肝风炽盛，化火伤肺阴，故久咳不已，咽干作痛。肝风内动，易伤肺络，惟恐络伤动血。此脉象揭示肝风炽盛、肺阴伤之病机，与久咳、咽干痛相应。", ["弦", "数"]], "4760": ["病机", "久嗽失音而舌红脉弦，弦为气机郁滞之象。原文明言“邪郁肺金，外寒内热”，外寒束表则肺气不宣，内热郁蒸则金实不鸣，故咳久而音哑。脉弦正应邪郁气结、宣降失司之机，非虚损之弦，故仿仲景法以解郁宣肺为治，不可径作阴虚劳嗽论。", ["弦"]], "4761": ["病机", "咳痰带血而六脉洪大，洪大为邪热亢盛、气分燔灼之象。原文断为“温邪伤肺”，温邪上受，热壅肺络，迫血外溢，故痰中带血。脉洪大说明热势方张、正气未衰，此时“不宜早进补”，恐滋腻恋邪、助热伤络，当以清解温邪为先。", ["洪", "大"]], "4762": ["病机", "咳频震络致络伤血溢，脉来弦大。弦主气逆络急，大主邪热有余，咳频震动肺络，络破则痰中带血。此弦大非虚象，乃络伤而气火未平之征，故“只宜薄味，以清上焦”，取轻清之品清肃肺胃，避厚味滋腻壅滞，以免助火复伤血络。", ["弦", "大"]], "4763": ["病机", "咳逆见红而脉象弦大，原文直指“肺胃之火迫血妄行”。弦为火郁气逆，大为热盛，肺胃之火上炎，灼伤阳络，血随气逆而妄行，故咳而见红。脉弦大正是火迫之应，治以甘寒，取甘能缓急、寒能胜热，清降肺胃之火以宁血络。", ["弦", "大"]], "4764": ["病机", "畜血妄行、胸膈作痛而脉弦大，原文断为“阳络伤也”。弦主瘀阻气滞，大主邪实，络伤之后离经之血未净，瘀阻胸膈则作痛，瘀不去则血不归经。故言“杂络之瘀未净，不宜早投滋腻”，滋腻碍瘀，暂用通络一法，正合脉弦大所示瘀实之机。", ["弦", "大"]], "4765": ["预后", "咳逆伤络失血，胸膈作痛，而病久脉虚。虚脉示气血耗伤、络损不复，正虚而邪恋，故原文断“刻难取效”。此非邪实可攻之候，脉虚与久病失血相应，提示正气已馁，恢复需时，属预后判断之语，治当缓图扶正，不可峻攻。", ["虚"]], "4766": ["病机", "热逼阳络而血溢颇多，脉来数大。数为热盛急迫，大为邪热充斥，热迫血络则溢血多，脉数大正是热势鸱张之应。原文嘱“适意静养”，因热盛血溢之际，宜静以制动、安养以缓热迫，避烦扰助火，使血得宁而脉数大渐平。", ["数", "大"]], "4767": ["病机", "上焦郁热、咳血多痰而六脉弦紧。弦紧为气郁寒束、热不得透之象，郁热壅于上焦，肺失清肃则咳而多痰，热伤血络则咳血。紧非纯寒，乃郁结不通之应，故治以清润，清上焦郁热、润肺化痰，使郁开热透而脉转和。", ["弦", "紧"]], "4768": ["病机", "久嗽见红而脉来细数，细为阴血亏少、络脉不充，数为虚火内扰。咳久伤肺，肺络受损则血外溢，故曰'肺络伤也'。细数并见，示阴虚火动、络伤失血之机，非外感实热，故原文告诫'殊非轻恙'，属内伤虚损重候。", ["细", "数"]], "4769": ["病机", "咳血而脉数，原文断为'阴不恋阳'。阴亏不能涵敛阳气，虚阳浮越鼓动血脉故数；阳扰于上，灼伤肺络则咳血。数脉在此非实热，乃阴虚阳浮之征，故称'劳怯之见端'，提示虚劳损怯初萌，不可轻视。", ["数"]], "4770": ["病机", "内伤失血后血虚，血不载气则气喘，阴不恋阳则脉数。阴血亏虚、虚阳不敛，故下午潮热；损及脾胃则饮食日减。原文谓'下损及中'，即下焦阴损上累中焦，脾运日衰，脉数正是阴不敛阳之象，故'最难向愈'。", ["数"]], "4771": ["病机", "大血失后阴血骤损，阴损及阳，阳气亦衰，故'色脉少神'——面色无华、脉象无力少神。此非单纯阴虚，而是阴阳两伤、气血俱亏之候，近于虚怯。原文据此提出'宜甘温纳补'，以甘温扶阳、纳气归元，正合阴损及阳之病机。", []], "4772": ["病机", "骤然咳血、膈闷顿痛、举动气促，脉来洪数，洪为热盛气涌，数为热迫血行。原文断为'温邪震络'，温邪犯肺、热伤血络，络破血溢而咳血；热壅气滞则膈闷顿痛。洪数示邪热尚盛，恐有留瘀未净，故告诫'不必急于止涩'，以免留瘀。", ["洪", "数"]], "4773": ["病机", "心悸遗精而脉虚无力，虚为气血不足、无力鼓动。原文归因'阴不恋阳'，阴亏不能敛阳，心肾不交，故心悸；肾失封藏则遗精。脉虚无力正示阴阳两虚、水火不济之机，故治法'清心固肾'，使水火交合而病渐减。", ["虚"]], "4774": ["病机", "便浊而脉数，数为热象。原文直断'湿热下注也'，湿热蕴结下焦，气化不利、清浊不分，故小便浑浊。数脉在此主热，与湿相合则湿热胶结，故治法'分利'，即清利湿热、分清泌浊，使湿热从小便而去。", ["数"]], "4775": ["病机", "久浊不愈，元气亏虚，脉来无力，无力即虚软不任按之象。久病浊证耗伤中气，脾虚气陷、清浊不分，故浊久不止而脉无力。原文主'建中'以补益中气，佐'升清'以升举清阳，正合元气虚陷、清浊相干之病机。", ["虚"]], "4776": ["病机", "脉来紧大，紧主郁滞，大主热盛，合之则下焦郁热内结。尿血、小腹坚、大便秘，皆热瘀互结之象。紧为气机壅遏，大为邪热亢盛，故断为下焦郁热，恐有瘀滞，与尿血作痛、便秘相应。", ["紧", "大"]], "4777": ["病机", "脉来弦大，弦主痛、主湿热壅滞，大主邪盛。血淋茎痛乃湿热下注膀胱，气机不畅，故脉弦；湿热炽盛，故脉大。法当分利，即分消湿热，通利水道，与脉症相合。", ["弦", "大"]], "4778": ["病机", "统体浮而脉不应指，乃寒湿内阻气分，阳气被遏，不能鼓动脉道，故脉象模糊难应指。浮为湿泛肌表，不应指为气分壅滞、脉气不显。法当温解分清，温散寒湿、分利气机，使湿化气通则脉自显。", []], "4779": ["病机", "六脉模糊，统体浮肿，乃中虚湿困，脾运失职，水湿泛溢肌肤。脉模糊者，湿浊壅遏脉道，气血不畅，非脉气衰绝。法当分利，健脾利湿，使水湿下行，则肿消脉显。", []], "4780": ["病机", "六脉沉微，沉主里、微主阳虚，真火衰微，不能温煦蒸腾，湿浊内停，泛溢为足胀浮肿。火衰则脉沉微，湿浊用事则肿。宜通阳分利，温补真火、通利湿浊，使阳复湿化。", ["沉", "微"]], "4781": ["病机", "脉软主阳气衰微，鼓动无力，兼挟湿邪困阻。腹胀因阳微不运，湿浊内停。软脉非虚劳之软，乃阳虚湿困之象。法当分利，温阳化湿，使阳气振则脉起，湿浊去则胀消。", ["软"]], "4782": ["病机", "六脉模糊，腹膨泄泻，乃阳虚湿困，脾肾阳气不足，水湿内盛，脉道被湿浊壅遏而不清。模糊非无脉，乃湿困阳微之征。恐其中端，即虑其阳气衰败、病势转危，当温阳化湿为治。", []], "4783": ["病机", "脉不应指，腹胀气喘，乃脾肾阳衰，阳气不能鼓动脉道，水湿泛滥，上逆迫肺则喘，中焦不运则胀。脉不应指为阳衰湿盛、脉气不显之候。仿《金匮》肾气法，温补脾肾、化气行水。", []], "4784": ["病机", "失血过多，阴血亏耗，阴伤及阳，阳气亦衰，故腹中膨胀。脉来细数，细为阴血不足、脉道不充，数为虚热内扰、阳浮不敛。此脉示阴伤及阳、气血两亏而兼虚热，主失血后腹胀之候，故宗补火生土法，温阳以生阴血。", ["细", "数"]], "4785": ["病机", "腹鸣作胀而脉来虚软，虚为阳气不足、鼓动无力，软为脾肾阳衰、脉道失充。脾主运化，肾主温煦，脾肾阳衰则水谷不化、气机壅滞，故腹鸣胀满。脉症相合，明示脾肾阳衰为本，法当温补以复其阳。", ["虚", "软"]], "4786": ["病机", "脉来沉细，沉主里、主阳虚不能鼓脉外达，细主阴血不足、脉道不充。脾肾阳衰，纳谷不运，中焦气化无力，故脉沉细而食少。原文谓「近乎膈候」，示阳衰日久、脾胃将败，病势深重，已近噎膈之途。", ["沉", "细"]], "4787": ["病机", "朝食暮吐，六脉沉弱。沉为病在里、阳气不能外达，弱为脉道无力、中阳衰微。中土阳衰，腐熟水谷无权，故朝食暮吐。六脉俱沉弱，示一身阳气衰败、脾胃虚寒，法当补土通阳，温复中焦以助腐熟。", ["沉", "弱"]], "4788": ["病机", "脉来软弱无力，软弱皆阳气虚衰、鼓动不足之象。积劳内伤，阳结于上则纳食哽塞，阴衰于下则大便艰难，上下不通，是为关格之渐。脉弱正合虚劳内伤、阴阳俱损之机，故姑拟温通一法以图幸功。", ["软", "弱"]], "4789": ["病机", "脉来弦数，弦为肝旺气逆、脉道劲急，数为阳热内盛、火动不息。操劳阳亢，肺津胃液日渐消耗，食阻便艰，是关格之见端。弦数示阳亢津伤、气火内郁，故须身心安逸以息火，慎勿徒恃药功。", ["弦", "数"]], "4790": ["病机", "脉细模糊，细为气血不足、脉道不充，模糊为湿浊内阻、脉气不清。中虚挟湿，脾运失职，湿聚成痞，日渐增大。脉细示正虚，模糊示湿滞，正虚湿结，故久防满腹，病势有增无减之虑。", ["细"]], "4791": ["病机", "形衰脉弱，弱为气血虚衰、鼓动无力。左胁下结痞作痛，饮食减少，乃肝木失疏、木邪侮土，脾土受克则运化不及。脉弱示正气已衰，而结痞作痛示邪结未散，正虚邪恋，故症势不轻。", ["弱"]], "4792": ["病机", "右脉弦滑，弦主饮邪内停、气机不利，滑主痰湿壅盛。原文谓「肋痞胀满」而「恐有停饮」，正合弦滑之象：饮停胁下则气机壅滞而痞胀，滑为水饮内聚之征。故以燥土分消，健脾燥湿以化停饮，脉症相参，病机在饮停气滞。", ["弦", "滑"]], "4793": ["病机", "脉软无力，软为阳气不足、鼓动无力之象。原文述「宿痞为患，延至腹满，食减便溏」，痞满食少便溏皆脾运失职，脉软无力正应脾土阳衰、中气不振。故断为「脾土阳衰也，殊非轻恙」，脉之软弱与症之虚寒相合，主阳虚中寒之机。", ["软"]], "4794": ["病机", "原文「脉象模糊」为纯描述，未出具体脉名，故脉素从缺。膈痛吐沫而脉模糊，模糊者脉道不清、中气不振之象。原文断为「中虚积饮」，中阳不足则饮邪内积，饮阻膈间故痛而吐沫，脉之模糊正应中虚饮聚、阳气不运之机，故以燥土通阳为治。", []], "4795": ["病机", "原文仅言「六脉不扬」，未识具体脉名，脉素从缺。不扬者脉气沉抑不显，寒湿僭踞、阳气被遏之征。寒湿内盛则呕逆，阳虚外越则自汗，六脉不扬正合寒湿困阻、阳气不振之病机。故拟平胃理中法，温中燥湿以复脉气。", []], "4796": ["病机", "脉来细软，细为气血不足，软为阳气衰弱。原文「纳食呕吐」，纳食即呕乃脾胃虚而受纳失职，细软之脉正应土气衰微。土衰则木无所畏而乘之，故断「土衰木乘」。脉细软与呕吐并见，主中虚木侮、胃气上逆之机，宗仲景法建中抑木。", ["细", "软"]], "4797": ["病机", "原文「六脉模糊」为纯描述，未出具体脉名，脉素从缺。模糊者脉道不清利，湿、热、痰浊阻遏气机之象。胸次作痛因清阳不运，浊邪痹阻胸阳，脉气因之不显。原文明言「湿、热、痰阻气，清阳不运也」，脉之模糊正应浊阻气滞、阳气不展之病机，故仿平胃法化浊。", []], "4798": ["病机", "脉沉主病在里、阳气不达。原文「胸闷作痛，短气脉沉」，胸阳痹阻则胸闷作痛，气机不畅则短气，脉沉正应清阳失展、气机不利。沉为气郁于里、阳不布散之征，与胸痛短气相合，主胸阳不振、气滞痹阻之病机，故宗《金匮》法通阳宣痹。", ["沉"]], "4799": ["预后", "原文「色脉少神」为纯描述，未出具体脉名，脉素从缺。色脉少神者，色泽脉气皆乏神采，示正气已衰。膈痛频发而络不通，久痛入络、气血瘀滞，色脉少神则提示正气不支。原文「防失血」，虑络瘀日久、血不循经而妄行，故本条主旨在于预后警示，非单纯言病机。", []], "4800": ["病机", "脉数无力，数而无力为虚火浮越之象。原文断为“阴涸阳浮，气散失纳”，阴液枯涸不能恋阳，阳气浮越于上，故喘逆自汗并见。数脉非实热，无力正示正气已散、根不固摄，故治法取“收摄固元”，从本虚论治而非清火。", ["数", "虚"]], "4801": ["病机", "脉沉主里、主虚寒。原文以“脉沉气喘，背冷腰痛”并见，断为“肺肾虚寒”。沉脉示病位在里，阳气不足不能鼓动脉道，肺失温煦则喘，肾阳虚则背冷腰痛。此为里虚寒证，故法当温补，温肺肾之阳以复气化。", ["沉"]], "4802": ["病机", "脉来细为气血不足、元气衰微之象。原文谓“元海根微，气逆上泛”，细脉示下元根本虚衰，不能镇纳，气不归元而反上逆，故举动即喘促。此非实邪壅肺，乃虚气上泛，故理当补纳，补其根本以纳气归元。", ["细"]], "4803": ["病机", "右脉候脾胃，弦主饮邪、滑主痰湿。原文“喘急多痰，右脉弦滑”，断为“中气虚而停饮上逆”。中土虚馁，运化失职，水饮停聚上逆犯肺，故痰多喘急。弦滑并见正是饮邪内停之征，法当燥土祛邪，健运中焦以化饮。", ["弦", "滑"]], "4804": ["病机", "原文未识脉名，仅言“脉来少力”。少力即虚软无力，示正气不足。原文断“此火无根”，喘咳之由非实火，乃虚火上浮、下无根柢，故脉少力。火无根则不可清，必须补纳，引火归元，使虚阳复归下焦。", []], "4805": ["病机", "脉来细软，细为阴血不足，软为气弱不充。原文“金水两虚，易感痰喘”，金虚则肺卫不固易感外邪，水虚则肾不纳气而痰喘。细软之脉正合肺肾两虚、正气不足之候，故理当进补，补金水以固根本。", ["细", "软"]], "4806": ["病机", "左脉候肝，弦主肝旺，数主火盛。原文“肝火挟痰，肢麻头晕，左脉弦数”，弦数为肝经火旺之象，火动生风挟痰上扰清窍，故头晕肢麻。原文“惟恐仆跌”，虑肝风内动、痰火上冲致卒倒，病机在肝火痰扰。", ["弦", "数"]], "4807": ["病机", "脉细弦滑，细示阴伤，弦主风动，滑主痰聚。原文“风温伤肺，肺气不通，痰唾如胶”，风温之邪灼津成痰，痰热胶结阻肺，故脉见细弦滑。细为津伤，弦滑为风痰，故议微辛微苦，辛以宣透、苦以泄热，轻清化解。", ["细", "弦", "滑"]], "4808": ["病机", "六脉紧数，紧主肝火亢盛，数主热象，火性急迫故脉数；紧为弦急之甚，肝火挟痰上扰清窍，故头晕不寐。紧数并见，说明火痰交炽，有升无降，防其仆中，即防肝风内动、气血上逆而致昏仆。", ["紧", "数"]], "4809": ["病机", "脉弦为肝木之象，痰饮挟气，木火上逆，气机郁滞，故膈胀而脉弦。弦主饮癖、主气结，木火犯膈，胃气不降，腻补则助痰碍气，故言不合。此脉说明病机在肝气与痰火相搏，非虚证可补。", ["弦"]], "4810": ["病机", "脉象沉弱不扬，沉主里、弱主虚，中下两焦阳微，阳气不能鼓动脉道，故脉沉弱而不显扬。痰饮上泛、纳食艰运，皆因阳微不能化饮运谷。治以通阳涤饮，正合脉证。", ["沉", "弱"]], "4811": ["预后", "久嗽中虚，痰饮内聚，形衰脉弱，弱脉主气血不足，中虚不能运化，故痰饮内停。形衰与脉弱相应，正虚邪恋，症势非轻，说明预后堪忧，非轻浅之疾。", ["弱"]], "4812": ["预后", "久疟不已，咳逆盗汗，色脉少神，虽未识脉名，但色脉少神即脉无胃气神采，久疟耗伤气血，正虚邪伏，咳逆盗汗为阴伤阳浮，色脉失神，故殊非轻恙，预后不良。", []], "4813": ["病机", "暑湿伤气，寒热腹痛且胀，脉不条达，脉不条达指脉气郁滞不畅，暑湿困阻太阴，气机不利，故脉不条达。太阴疟者，湿邪留恋，脾运失司，寒热腹痛胀满皆由气机壅滞所致。", []], "4814": ["预后", "久泻不止，色脉少神，脾肾阳虚，久泻伤及脾肾，阳气衰微，不能温煦，故色脉少神。色脉少神即脉无神气、面色无华，阳虚至此，殊非轻恙，预后堪虑。", []], "4815": ["病机", "六脉细软，细主阴血不足，软主阳气衰弱，久痢延至腹胀，阴阳两伤，气血俱亏，故脉细软。细软并见，说明正虚已甚，必须温补，以复阴阳。", ["细", "软"]], "4816": ["病机", "久痢迁延，脉见微象，是阳气衰微、命门火衰之征。痢久伤及脾肾，阳气不能鼓动脉道，故脉微。原文直言“命门阳衰”，若不急进温补，阳愈衰则气化不行，水湿停聚，恐延成肿胀。脉微在此提示虚寒本质，主病为久痢阳衰，与温补之治法相应。", ["微"]], "4817": ["病机", "疟后下痢，纳食艰运，六脉沉弱无力。沉为在里，弱为不足，无力示阳气虚馁。疟痢耗伤脾肾，命火衰微，不能腐熟水谷、运化饮食，故纳食艰运。原文断为“命火衰微，必须温补”，脉沉弱无力正是里虚阳衰之据，主脾肾阳虚、火不生土之病机。", ["沉", "弱"]], "4818": ["病机", "湿热内侵，痛泻并作而脉数。数为热象，湿热蕴结肠道，气机壅滞不通则痛，传化失常则泻。脉数反映邪热内盛、正邪相争。原文以“湿热内侵”统之，脉数即热邪之征，主湿热蕴结之痛泻，与清热化湿之治相应，非虚数之候。", ["数"]], "4819": ["病机", "阴虚内热，肠红脉数。数脉主热，此热由阴亏而生，虚火内扰，灼伤肠络则便血肠红。脉数在此反映阴虚不能制阳、虚热内盛之病机。原文点明“阴虚内热”，脉数与肠红相应，主阴虚火旺之下血证，治当滋阴清热，与实热脉数有别。", ["数"]], "4820": ["病机", "两足酸软，六脉浮数无力。浮为虚阳外浮，数为内热，无力示阴亏不敛。原文谓“证属骨痿，由阴虚内热所致”，阴精亏虚，骨失所养则足软成痿；虚热内蒸，脉浮数而无力。此脉主阴虚内热之骨痿，宗虎潜法滋阴降火，与病机相合。", ["浮", "数"]], "4821": ["病机", "筋痿之候，诊左脉弦数。弦为肝脉，数主热，左脉候肝，弦数并见示厥阴郁热内盛。肝主筋，郁热耗伤阴血，筋脉失养则成筋痿。原文断为“由厥阴郁热所致”，宜清营热以舒筋。脉弦数正是肝经郁热之据，主筋痿属厥阴郁热之病机。", ["弦", "数"]], "4822": ["病机", "四肢不用，脉沉少力。沉为在里，少力为阳气不足，脾主四肢，脾肾虚寒则阳气不能温煦四末，故四肢不用。原文直断“脾肾虚寒，急宜温补”，脉沉少力正示里虚寒盛、阳气不振。此脉主脾肾阳虚之痿废，与温补治法相应。", ["沉"]], "4823": ["病机", "足膝痿软，六脉无力。无力为虚，足膝属肝肾所主，肝肾亏虚则筋骨失养而痿软；又挟湿邪，湿性重着，留着下焦。原文谓“肝肾虚而挟湿也，须标本两顾”，六脉无力示正虚为本，湿为标，故主虚实夹杂之痿证，治当补肝肾兼化湿。", []], "4824": ["病机", "六脉弦数，弦主肝郁湿阻、数主热，然原文断为阳虚挟湿，两膝肿痛。阳虚则湿不化，湿郁化热而见数，弦为湿阻气机、经脉不利之象。脉症合参，属本虚标实，湿浊下注膝部，故症势不轻，提示不可纯作实热论治。", ["弦", "数"]], "4825": ["病机", "脉来细软，细为阴血不足、软为阳气无力，原文直指水中无火，即肾阳亏虚、下焦失于温煦。下体痹痛因阳虚不能温养经脉、寒湿留着所致。细软之脉与水中无火相应，故法当温补，以复肾中真火、通利痹阻。", ["细", "软"]], "4826": ["病机", "本段未识脉名，原文以四肢酸痛、间发寒热为据，断为风入脉络使然。风邪外袭，客于脉络，气血运行不畅则酸痛；正邪交争于表则寒热间作。病机在风邪入络、营卫不和，故先宜解散，以疏风通络、调和营卫为治。", []], "4827": ["病机", "脉来弦数，弦属肝胆气郁，数主内有郁热。阳不交阴则寤不成寐，木郁克土则饮食日减，郁热内扰、阴阳失交为其病机。原文暂用半夏泻心法，取辛开苦降以调中焦、和阴阳，说明此弦数非纯实火，兼有中焦痞塞之机。", ["弦", "数"]], "4828": ["病机", "左脉弦大，左候肝胆，弦主肝郁、大主邪盛，原文断为五火内炽。五志化火，肝火循经上扰则心烦头晕，火扰心神则寤不成寐。弦大之脉正是肝火亢盛、气机郁勃之征，故治以苦泄，直折其火、泄其郁热。", ["弦", "大"]], "4829": ["病机", "脉数主热，厥频发而心悸，原文归为肝郁气乱使然。肝郁化火，气机逆乱，上扰心神则心悸，气逆于上则厥。数脉示郁热内动，与肝郁气乱之机相应。先清后补，即先清肝泄热以平逆乱，后补其虚，示标本缓急之序。", ["数"]], "4830": ["病机", "六脉弦紧，弦主肝胆、紧主郁结与痛，原文断为肝胆郁热。郁热内结，气机壅塞则膈胀，热扰神明则神昏。弦紧示郁结深重、邪势鸱张，故惟恐痫厥，提示郁热化风、有上逆蒙窍之虞，当防惊痫昏厥之变。", ["弦", "紧"]], "4831": ["病机", "脉弱为气血不足、阳气衰微之象，原文以形衰脉弱并称，形脉相应，说明正气已虚。当此虚象，虽用半夏、干姜、延胡、蒌皮等温通化痰理气之品，仍须温补以扶根本。弱脉在此主虚，故治当温补，不可专事攻邪。", ["弱"]], "4832": ["病机", "脉来细软，细为气血不足，软为阳气式微，合而示中阳失运。胃痛食减乃中焦虚寒、运化无力所致，故治以温通，温复中阳则痛减食增。", ["细", "软"]], "4833": ["病机", "脉微为阳气衰微之象，腹胀由阳气积衰、气化不行、阴寒内聚而成。法当温理，温阳以化气，则胀满自消。", ["微"]], "4834": ["病机", "脉虚主气血不足，腰痛脉虚乃肾阳亏虚、腰府失养。法当温补，温肾助阳以强腰膝。", ["虚"]], "4835": ["病机", "脉滑主痰，头晕脉滑为内风挟痰上扰清窍。从肝胃调治，肝风平则眩晕止，胃痰化则脉滑减。", ["滑"]], "4836": ["病机", "六脉弦滑，弦主肝火，滑主痰浊，肝火挟痰上扰则头晕耳鸣。清先补后，先清肝化痰，后培补根本。", ["弦", "滑"]], "4837": ["病机", "六脉细软，细为阴血不足，软为阳气不振，阳不恋阴则头晕自汗。法宜培补，补阳以恋阴，阴阳相济则汗止晕除。", ["细", "软"]], "4838": ["病机", "六脉细软，细软为精血亏虚，水不涵木，厥阳化风上扰则烦劳头晕。当从肝肾同治，滋水涵木以息风。", ["细", "软"]], "4839": ["病机", "脉来细数，细为阴亏，数为火动，水亏火动，迫血上溢则头晕鼻衄。治以育阴潜阳，阴复火降则衄止晕平。", ["细", "数"]], "4840": ["病机", "六脉弦数，弦为肝旺，数为热盛。阴虚不能制阳，阳亢化火，迫血妄行，故鼻衄大发。脉弦数正是阴虚阳亢、火热内扰之象，与衄血、心烦、口渴等症相应。", ["弦", "数"]], "4841": ["病机", "脉象弦数，弦主肝胆，数主热。胆热循经移脑，蒸灼清窍，故鼻流秽涕。此脉象揭示胆腑郁热之病机，与鼻渊秽涕、头痛等症相应，治以辛散以疏泄胆热。", ["弦", "数"]], "4842": ["病机", "左脉弦紧，弦为肝郁，紧主寒痛。木火刑金，肝气上逆犯肺，故咽痛失音、咳痰不爽。脉弦紧反映肝经气火内郁、肺失清肃之病机，与咽喉不利、咳痰等症相应。", ["弦", "紧"]], "4843": ["病机", "脉来沉迟，沉主里，迟主寒。下焦阳气失运，阴寒内结，肠道传导无力，故大便闭结。此脉象说明阳虚寒凝、气机不畅之病机，与便秘、腹冷等症相应，治以温润。", ["沉", "迟"]], "4844": ["病机", "六脉不静，即脉象躁动不宁，为阴亏阳亢之征。阴虚不能涵阳，阳亢扰及心神，故心烦口渴；热迫血海，则经下颇多。脉不静反映虚热内扰、阳不潜藏之病机，治以滋补。", []], "4845": ["病机", "脉来细软，细主阴血不足，软主气虚。肝强脾弱，脾失健运，气血生化乏源，故胸痛作胀、癸水不行。此脉象说明气血两虚、肝脾不调之病机，与经闭、胸胀等症相应。", ["细", "软"]], "4846": ["病机", "原文未识脉名，然阴虚内热、经漏淋漓，脉当细数。阴虚生内热，热扰冲任，血海不宁，故漏下不止。此段主旨为阴虚内热之病机，与经漏、烦热等症相应，仿复脉法以滋阴复脉。", []], "4847": ["病机", "六脉无力，为气血亏虚之象。产后结瘕、少腹胀痛，非有形实邪所阻，乃肝胃络虚、气血失养所致。自汗屡泄更伤气阴，故脉无力。此脉说明正虚络滞之病机，不可攻伐，宜温通。", ["无", "力"]], "4848": ["病机", "脉来细软，细为阴血不足，软为阳气衰弱，合之则阴虚及阳，阴阳两虚。带下腹痛而见此脉，说明病本在虚，非实邪为患，故法当温补，温阳以化湿，补虚以止痛。脉症相参，细软无力正是虚象之征。", ["细", "软"]], "4849": ["病机", "经漏后脉络空虚，言失血之后脉道不充，血虚不能养心则心悸，不能上奉则头晕，不能濡养筋骨则酸软，血虚及气、水湿不化则足跗浮肿。脉象虽未明言，然'空虚'二字已示气血亏虚之本质，故曰非轻候，必须进补以复其虚。", []], "4850": ["病机", "中虚肝郁，腹胀食减，色脉神少，言脾胃中气虚弱而肝气郁结，木不疏土，故腹胀食减；气血生化不足，故色脉神少。脉象虽未明载，然'色脉神少'已示脉气虚弱之象。仿逍遥法者，健脾疏肝，标本兼顾，正合中虚肝郁之病机。", []], "4851": ["病机", "脉来弦紧，弦主外邪束表、经气不利，紧主寒主痛。恶寒发热、头痛身疼、脘闷无汗，皆风寒外袭、卫阳被遏之象。卫阳疏而风寒外袭，邪正交争于表，故脉见弦紧。例用辛温解散，汗之则邪从表解，脉紧自缓。", ["弦", "紧"]], "4852": ["病机", "脉紧主寒，邪伤阳经，形寒身热，头痛脘闷，舌白，皆寒邪袭表、阳气被郁之征。紧脉为寒邪收引、营卫凝滞所致，与舌白、形寒相合，确属表寒实证。先宜汗散，使寒从汗解，则紧脉可去，身热可退。", ["紧"]], "4853": ["病机", "脉来弦劲，弦主气机郁滞，劲则邪势鸱张。春温发热、头胀脘闷、舌布白苔，为温邪郁于气分，不得从汗外达，邪郁化热而脉见弦劲。弦劲非虚，乃邪实气郁之象，故拟解肌法，透邪外出，使郁开热达。", ["弦", "劲"]], "4854": ["病机", "得汗后热象不减，烦渴少寐，脉数舌干，数主热盛，舌干示津伤。伏邪未化而津液先伤，热灼阴津，故脉数而舌干。此非单纯表证，乃伏邪内郁、化热伤津之候，法当清解，清热以化伏邪，生津以救阴液。", ["数"]], "4855": ["病机", "湿热伤阴，舌红脉数。数脉主热，舌红为热灼阴伤之征。湿热久蕴，化燥伤阴，故舌红而脉数。此非实热单纯可清，乃湿热与阴伤并见，故仿玉女煎法，清胃热而滋肾阴，标本兼顾，使热清阴复。", ["数"]], "4856": ["病机", "六脉沉数，沉为邪陷于里，数为热盛于内。温热内陷，热深厥亦深，故四肢厥冷而脉沉数，谵语神昏、大便三候不解，皆邪归胃腑、热结阳明之象。脉沉数正是里热壅盛之征，非虚寒厥逆可比。", ["沉", "数"]], "4857": ["病机", "冬温乘阴虚而发，身热不得汗解，脘闷咳逆，舌白脉弦。弦为气机郁滞之象，郁气分尚未施张，故身热无汗、脘闷咳逆。脉弦与舌白并见，说明邪郁气分、肺卫失宣，法当辛散以开郁透邪。", ["弦"]], "4858": ["主病", "暑湿伤其气分，脘闷腹痛，上吐下泻，四肢厥冷，舌腻脉数。数脉主热，暑湿内蕴、气分受伤，故吐泻交作而脉数；四肢厥冷乃湿遏热伏、阳气不达四末所致。舌腻脉数，正是霍乱暑湿之候，例用正气法。", ["数"]], "4859": ["病机", "暑风伤肺，发热汗少，头胀咳呛，舌布白苔，脉左弦数。弦为风邪郁滞，数为暑热内盛，左脉候肝肺气机。暑风闭郁肺卫，故发热汗少、头胀咳呛；舌白苔示邪尚在气分。脉左弦数，正是闭暑之候，姑拟辛解以开闭。", ["弦", "数"]], "4860": ["主病", "左脉弦数，朝凉暮热，汗解渴饮。弦为少阳枢机不利，数为热郁于内；左脉候肝胆，弦数并见，说明邪在少阳、枢机失转。朝凉暮热、汗解渴饮，皆少阳郁热之典型症候，故治从少阳，和解枢机。", ["弦", "数"]], "4861": ["其他", "此段为医论，强调认症为先、施治为后，引喻嘉言“医不难于用药，而难于认症”及丹溪《脉因证治》以认症为先之说。文中未及具体脉象，纯论诊治次第，指出寒热虚实疑似甚多，若辨之不真则见病治病十无一效，故不属脉象主病之列。", []], "4862": ["病机", "脉涩小数，质弱，平昔喜饮。涩为血少气滞，小为脉道不充，数为郁热内扰；质弱而喜饮，酒性先入肝胆，易生嗔怒，烦劳郁热自情怀而升。脉涩小数正合郁劳之病机，气血郁滞兼有郁热，故用药不易奏功，惟怡悦为上。", ["涩", "小", "数"]], "4863": ["病机", "脉弦，舌白，吐涎，食入膈上即涌出，自述由动怒得之，春病至霜降不愈，心中反痛。弦为肝脉，动怒伤肝，肝气犯胃，胃失和降，故吐涎涌食、心中反痛。脉弦正是肝病犯胃之征，故以肝病犯胃治法。", ["弦"]], "4864": ["病机", "原文未载脉象，以“孕育已十一胎，未到七七，天癸已绝，八脉不司约束”立论。多产早衰，阴精耗竭，奇经失约，故脊腰酸痛、足跗麻痹、带淋畏热并见。此属阴虚，虎潜法滋填肝肾以固八脉，正合“壮水之主”之意。", []], "4865": ["病机", "原文未出脉，述白虎法后“渴烦少减，略饥，必形神软倦”，知热势虽挫而津液已伤。热迫阳明，脉络自怯，故形神软倦。以清燥法清气热以涵液，是热退津亏、气液两伤之病机，非复白虎所能胜任。", []], "4866": ["病机", "原文未载脉，据“筋粗强硬，不司舒展”论筋纵筋弛，分寒湿、湿热之异。痘浆未化之毒混处血脉络间两年，攻之不应，已流入阴分，遇风冷辄痛。四肢血少气多，初取阳明，今以生阴为要，宗麋茸六味壮阴通阳，是久病入络、阴伤络阻之机。", []], "4867": ["病机", "原文未出脉，以“疟、痢致伤下焦，奇经八脉皆损”为纲。八脉既损，阳维无以维持护卫，卫疏则汗泄，故倏起寒热、背畏冷、遇风必嗽痰。甘温益气养阴后渐知饥纳食，是脾胃稍复而奇经未固，从虚损门治，主病在八脉失护。", []], "4868": ["病机", "原文未载脉，述嗔怒致心胸痞胀三年，左胁下坚凝有形，触劳忿则寒热无汗。怒伤肝，气郁血痹，日久延成肥气。坚凝有形是气血郁痹之征，寒热无汗为营卫不通。治当宣通营卫、流行脉络，佐入攻坚，使郁开气行则寒热自止。", []], "4869": ["病机", "原文未出脉，言疟伤真阴，七八年来交春即脊背肩胛胀痛，入夏更甚，冬寒乃瘥。春夏天地发泄，脏真既少则升泄病来；督脉行身之背，自阴及阳，故背痛应之。此内伤不复、阴不恋阳之机，惟养静断欲、渐养可希效。", []], "4870": ["病机", "原文未载脉，论三阴疟为阴分伏邪。汗之清之不解，反与腻滞补药，邪无出路，遂致吐衄，寒自背起。背为太阳督脉所过，邪伏阴分而督脉应乎太阳，故寒从背作。此误补闭邪、邪无出路之病机，非单纯虚损可比。", []], "4871": ["病机", "脉右寸独大，右寸候肺，独大为肺金气逆、木火偏亢之象。食下脘中噎阻、背胁气逆而痛，由嗔怒致病，是肝木犯肺、气逆不降。形瘦津少，故清金制木而勿用破气燥血，恐更伤津气。脉症合参，主气逆郁结、肺金受侮之病机。", ["大"]], "4872": ["病机", "脉软为气血不足之象。原文谓忧愁思虑内伤，先损心肺，心主营、肺主卫，二气既亏则脉失充盈而软。血止而脉仍软，形倦不食、呛咳痰黏，皆土败金枯，正气难复，故脉软主虚损不足，非实邪可攻，当急与甘缓补法。", ["软"]], "4873": ["病机", "脉弦缓，弦主湿郁气滞，缓主湿性黏滞。原文言湿温由濒海潮湿秽浊入口鼻至募原，分布三焦，湿甚热郁，气血不通而发黄，胸脘胀闭、舌白滑腻皆湿浊内蕴之征。脉弦缓正合湿邪困阻、气机不畅之病机，故清热消导不效，当以苦辛气寒逐湿祛秽。", ["弦", "缓"]], "4874": ["病机", "脉数为阳动之象。原文述冲年情念萌动，梦遗劳烦更甚，面亮茎举精出、溺后淋沥，是阴虚精窍不固，阳气下坠。脉数非实热，乃阴虚阳扰、相火不藏所致，故议固下阴以和阳，使阴精得固则阳自安。", ["数"]], "4875": ["病机", "脉得弦数，弦主木郁，数主阴伤火动。原文谓幼冲阳虚，泄泻寒热、咳嗽失血、天癸不来，形色消夺，全是冲年阴不生长、劳怯大著。脉弦数正示肝肾阴亏、虚火内扰，非实邪为患，故无见病治病之理，惟保胃口以冀经通。", ["弦", "数"]], "4876": ["病机", "脉细主精血不足，右濡左数示阴伤于下而中宫渐弱。原文言少年形瘦肌槁、遗泄，知识太早致精血难充，脐左动气、食减易饥，是阴伤延及中宫。脉细濡数正合精亏阴伤、虚阳内动之机，故补阴参入柔剂温药，取坎中寓阳之意。", ["细", "濡", "数"]], "4877": ["病机", "脉数左促右小，数主火升，促主郁结，小主阴血亏少。原文谓肝阴不充，相火上燔莫制，嗽久痰带红丝，食减经来从未生育，皆劳怯势成、根本先亏。脉数促小正示肝肾阴亏、虚火内灼，清肺凉药不效，故急养肝肾之阴。", ["数", "促", "小"]], "4878": ["病机", "原文未识脉名，纯以症候言病机。遗泄有梦属心、无梦属肾，气火下溜如溺出状，茎中痛、热气上冲咽喉、巅顶掀胀、语言皆怯，是任脉不摄、冲脉气逆，气火不藏而上逆下泄，故脉象虽缺，病机在冲任失守、虚阳妄动。", []], "4879": ["病机", "脉得左部弦劲，弦劲为肝木失柔、阴血不足之象。原文谓形劳悒郁之伤，肝血胆汁已少，目翳红赤。左部应肝，弦劲示肝阴亏而肝气偏亢，虚火循经上炎于目，故治以凉肝滋液，使肝血得养则弦劲自缓。", ["弦", "劲"]], "4880": ["病机", "原文未提脉象，但述病始足胫，自下焦肝肾起病，形不肿非湿邪，当从内损痿躄推求。久服萸、地滋滞，胃伤食减呕逆，浊味滞气。经年不复，脏真不充，奇经八脉不司其用。冲脉为病，精沥内结有形，精空气结如女子瘕聚。久病形消肉脱，议精血有情涵养生气。病机为肝肾内损，奇经失养，精空气结。", []], "4881": ["病机", "原文未提脉象，述堕胎十八次，冲任奇脉血液无存。厥气入络，为胀为痛，或冲逆犯膈，八脉皆不为用，淹淹渐成损怯。病机为冲任奇脉血液亏虚，厥气入络，八脉失用，渐成虚损。", []], "4882": ["病机", "原文未提脉象，述产后腹坚有形，气聚不通，渐成胀满，乃冲脉为病。大便秘阻，血药润滑不应，柔腻气愈凝滞。引徐之才云肾恶燥，以辛润之。病机为冲脉为病，气聚不通，血药柔腻反凝滞气机。", []], "4883": ["病机", "原文未提脉象，述精腐瘀血阻闭溺窍为痛，似淋非淋，久则阳维脉伤，寒热起，五液枯耗为便难，乃虚症也。病机为精腐瘀血阻闭溺窍，久伤阳维，五液枯耗，属虚症。", []], "4884": ["病机", "脉缓主脾虚湿盛，肢冷涌涎、脐上痛坠、泄泻，皆脾阳不振、湿浊内停之象。原文称“脾厥”，以辛香醒中，兼解少阳之郁。脉缓在此非平和之缓，乃脾虚湿困、气机壅滞之缓，故主脾厥。", ["缓"]], "4885": ["病机", "原文未提脉象，述疟发三日，三月不止，邪留在阴，热解无汗，气冲胸闷，痰涎甚多，寒起腰髀及背部，议从督脉升阳。病机为邪留阴分，督脉阳虚，痰涎内阻，气冲胸闷。", []], "4886": ["病机", "左脉小濡，小主不足，濡主湿滞，此血伤惊恐，气郁热升风旋，清神受蒙为厥。厥隶厥阴，左股麻痹，忽爽忽迷，肝胆相火内风未宁。热胜津伤，脉小濡示阴血亏耗，不宜纯与攻涤苦寒，宜柔缓濡润，阳和液复。", ["小", "濡"]], "4887": ["病机", "左脉细数而劲，细为阴亏，数为热，劲为风阳暴张；右数大而虚，虚为胃气不足。此肾精肝血内亏，水不涵木，阳夹内风，暴起莫制，指臂拘挛，口目㖞斜在左。肝风阳气从左升，冲气撞心，消渴晕厥，仲景列于厥阴篇。肝木犯胃阳土，饮食热气引动肝阳即发。", ["细", "数", "劲", "虚"]], "4888": ["病机", "形充而脉弦，饮食如常，说明病不在脾胃纳运，而在络脉。左胁久胀、肿溃收结后胁痛入夜更甚、仅能仰卧不可转侧，是支脉结饮阻遏周行气机，络气不通则痛。脉弦主饮主痛，结饮滞络故脉弦而不和，病根非外非内，治宜通其脉络。", ["弦", "结"]], "4889": ["病机", "原文未出脉名，以经脉直行、络脉横行、经气注络、络气还经为常度立论。今络脉窒塞，气行闪烁为痛，病位在云门上焦，属清气流行之所，故取轻扬宣气，使络气还经。湿痰便血亦由上焦气痹、络伤所致，引《灵枢》上焦如雾以明宣气之要。", []], "4890": ["病机", "饱食后虚里痛胀，吐后势减而发寒热，因吐动中，营卫周行参差，脉中脉外不相应。纳物主胃、运化在脾，阳健失司则浊阴僭窃。脉沉弦细属阴象，症脉俱虚，故有反胃格胀之虞，法当暖中，以火生土，温补佐宣通，守中非法。", ["沉", "弦", "细", "虚"]], "4891": ["病机", "久痢肛坠，脉左坚沉，温剂不受，是阴伤不司收纳，非寒湿内结。左坚沉示下焦阴分受损、气机固结，桃花汤少减而未全效，故当与甘酸柔缓，养阴和络，不可再投温燥。", ["坚", "沉"]], "4892": ["病机", "原文未出脉名。肩背肢末为阳气游行之所，牵制不和是络脉中病。先舒经、后参耆术附两法不应，知非单纯气虚，乃客气袭入脉中，灸刺无功，故议酒醴通和血脉，以辛温走窜通络。", []], "4893": ["病机", "原文未出脉名。伏邪留于少阴、厥阴之间，发为三日疟，百日不愈，邪伤真阴，梦遗盗汗、津枯便难。养阴虽有理，但深沉疟邪非纯补可拔，故早服鳖甲煎丸追拔扫除，午后服复脉汤加减养阴通阳，攻补兼施。", []], "4894": ["病机", "脉沉而迟，沉主里、迟主寒，示阳虚阴盛。向有寒疝瘕泄，继肠血不已，跗臁麻木无力，因膏粱酒醴酿湿内著，中年肾阳日衰，肝风肆横，阳明胃络空乏，无以束筋流利机关，日加委顿，乃阳虚也，仿劫胃水法。", ["沉", "迟"]], "4895": ["病机", "脉虚涩，虚为气不足，涩为血少气滞。咽中时痹不妨食物，大便干燥，是肺中气不下降、不主运行；消渴心热皆气郁为热，非实火。故治当宣降肺气、润养阴血，不可苦寒直折。", ["虚", "涩"]], "4896": ["病机", "脉沉微，沉为阴位，微为阳衰，直指脾胃阳气消乏。疟久六七十候，寒热邪聚中宫，阳气伤则浊阴盘踞，故痞胀不能纳食运化。脉沉微正是阳伤阴踞之征，与痞胀、不食、三年不愈相应。治当温通，使浊走阳回，若但泄气宽胀则中州愈困。", ["沉", "微"]], "4897": ["病机", "脉大弦缓，大属气虚，弦为土虚木乘，缓主湿滞。目黄、纳后脘滞痛、腹鸣泄泻，皆脾胃阳困、清浊升降失度之象。濒海潮湿外蒸，怀抱少畅内郁，湿郁困阳，故脉见大弦缓。辛香调气醒中，使阳气流行则湿郁可去，忌腥膻重味。", ["大", "弦", "缓"]], "4898": ["病机", "原文未出脉名，然述肾精下损、浮阳上灼、冲气上冲，病机在元海不司收纳。咽喉痛痹、咳喘促，皆下虚冲逆所致。前医日进润剂治嗽，反伤胃弱便溏，是酿病之祸阶。当固真纳气、培扶胃口，希冀加谷则吉，非治嗽可疗。", []], "4899": ["病机", "原文未出脉名，述冲任脉病，久治无功。经来色淡淋漓、少腹攻触㽲痛、晨必瘕泄，皆奇经脉络失养、阳不摄阴之征。阴疟延虚，更伤冲任。治当通阳摄阴，非破泄真气、偏寒偏热所能取效。", []], "4900": ["病机", "脉左坚，左关尺候肝肾，坚为阴亏阳亢、络脉失柔之象。便后纯血，食减力疲，是中年阴亏，虚火迫血下溢，兼脾运不健。脉左坚与便血、疲乏相应，主阴亏为本，非实热可攻。", ["坚"]], "4901": ["预后", "脉虚而左关尺数，虚为精血亏耗，数为阳失阴恋、内风鼓动。泻血后咳呛、胁下梗、眩晕欲仆，皆肝肾精血因惊恐忧劳所伤，络空风动。人迎结瘿亦络脉瘀滞之征。四旬以外生气已浅，非治病可却，唯屏绝家务、开怀颐养，望其病缓。", ["虚", "数"]], "4902": ["病机", "原文未出脉名，述阳明主束筋骨利机关，今行走皆艰、纳谷甚少、腹中气攻、头痛，自悲忧五年日加衰惫。此忧悲愁伤意，阳明气馁，筋骨失束，肢废不用，与《灵枢》痿论意伤肢废之旨相合。", []], "4903": ["误治", "原文未出脉名，述蓐劳下损及八脉，医投清内热滋阴，致胃伤食减、寒热、冲气上逆而咳。咳药治肺与下虚内损无涉，带淋骨热、髓竭液枯，蓐损较平常损怯更难。勉与血肉有情，望加谷悠久，见误治之弊。", []], "4904": ["病机", "原文谓怒伤肝、恐伤肾，真脏内损，烦劳扰动阳气，值春木令而络血上溢，失血过多则阴气下空、阳无所附，上触清府，木反乘金，故咳呛气促、肺俞恶寒。脉弦数者，弦为肝木之象，数为阳热内扰之征，正合木火刑金、下损及上之病机，故断为下损之疾。", ["弦", "数"]], "4905": ["病机", "原文述舌喑强缩、干涸无津，邪已入膻中而神识昏蒙，积劳心血及虚，热竟入矣。诊脉虚小无力，虚为正气不足，小为脉道不充，正合心血积虚、邪热内陷之候。故用至宝丹凉开，因俱补则热闭，先清透再议，脉虚小正是虚体受邪、不可纯补之据。", ["虚", "小"]], "4906": ["病机", "原文述吸短欲躁，午后至更深为甚，此热入阴中，子后清阳用事稍和；又心中不舒、热熏脚楚。虽未明言脉象，然以吸短、躁扰、午后夜甚为据，判为邪少虚多之候，故仿仲景复脉汤法，以复阴液、扶正气，使邪不与虚相搏。此段重在辨病机而非凭脉。", []], "4907": ["病机", "脉微弱而细，微为阳衰，弱为气馁，细为血少，合鼻准独明、昼日形冷汗泄、不饥少纳、脘腹常痞，正是阳气失护卫而寒栗汗出，阳失鼓运而脾胃气钝。前用养营血药柔软，阳不骤苏，故议理中汤专理脾胃阳气，以脉微弱细为阳气虚馁之凭。", ["微", "弱", "细"]], "4908": ["病机", "原文未明言脉形，只云诊得脉无神，舌色白，病在上焦气分。劳倦伏邪，初起误用柴胡、紫苏三阳混散，津液被劫，热邪上结，故胸中懊𢙐、神烦谵语、渴欲冷饮。脉无神示正气已伤而邪未透，冬温聘泄、老人积劳，七日不退，故断为重症，不可轻谈。", []], "4909": ["病机", "此段未言脉象，专论厥症病机：情怀失旷，肝胆郁勃，阳气直上无制。肝脉贯膈入胃、循绕咽喉，故病发由脘至咽、四肢逆冷；上升之气自肝而出，中夹相火，其病为甚。治以苦降、辛宣、酸泄，使阳和气平，再峻补阳明，因胃土久受木戕，土虚则木易乘克。", []], "4910": ["病机", "原文未载脉象，述肝风夹阳上逆为厥，得之恼怒惊忧，属七情之病。厥阴肝脉贯膈乘胃，故脘中不饥、不思纳谷，是木犯土位；头晕目眩乃肝风独行至高，精华之血不得营。前用苦降、酸泄、辛宣半月不愈，故议兼重镇之品，镇潜上逆之阳。", []], "4911": ["病机", "形弱脉小，形脉相应，小为脉道不充、气血不足之象。腰痹酸软、足跟痛，皆下元精血暗亏之征，未老先衰，防致痿痹。脉小正合精血亏虚，故温养宜柔，勿以桂、附刚愎燥烈，以免耗伤已亏之精血，当以柔润温养为法。", ["小"]], "4912": ["病机", "脉濡大，濡为湿盛，大为虚象，示壮年形充而内虚，脾土不运，湿浊久溏；木失土培，虚风上扰，故眩晕、目泪暗出。入冬尻骨跟痛、耳鸣，皆下元摄纳失职，虚风内动之征。", ["濡", "大"]], "4913": ["病机", "原文未明脉名，然述四肢冷汗、气喘、胸腹胀闷、脉绝厥逆，显系阳微欲脱、阴阳离决之候。太阳开则小水自利，阳明伤则失阖而浊逆，通脉四逆汤回阳驱阴，正为此设。", []], "4914": ["预后", "服药后脉微继者生，暴出者死。微而续继，为阳气渐回、胃气尚存之象；暴出则虚阳外越，残灯复明，乃阴阳离决之危候，故主死。此以脉之继与暴出判预后吉凶。", ["微"]], "4915": ["预后", "劳复虚寒泄下，绝谷胃损，络血洞下，昏乱无神，脉诊三五参差，乃阴阳脱根、真气不相维续之候。脉来参差无序，胃气已败，故恐坏于子丑二时，勉用大封固法以挽垂绝。", []], "4916": ["病机", "脉右缓左急，右缓为湿郁气分，左急为肝风内动。症见头如裹、昏寐、瘛痉、咳痰映红、便溏带血，皆湿热郁蒸、阻挠清气，营卫不主循环，升降失司，邪著气分，久延必致血分。", ["缓", "急"]], "4917": ["病机", "原文未出脉名，论疟不离少阳厥阴。肝气横逆，势锐扰中，故不饥不食；久发频发必伤及络，络聚血而久病血瘀，香燥破血、凝滞滋血皆禁忌，示治疟当分气血、慎攻破。", []], "4918": ["病机", "脉左数，左主肝与下焦，数为热。上热下冷、淋带不止，乃内热湿郁，久则元虚，湿热下注而肾气不固，故淋带缠绵；虚阳上浮则上热，下元不足则下冷。", ["数"]], "4919": ["病机", "关格脉数俱盛四倍，阴阳结邪相离，不复相管，羸不及天地精气则危。此由甘肥积热、酒性慓悍，伤脏腑津液，致清浊升降失常，故治以清通清滋，尚可希冀。", ["数"]], "4920": ["病机", "脉空隙为络脉空隙之象，失血半年，营液暗伤，络脉不充，故脉道空虚。心悸怔忡、胁左时动，皆营液亏虚、络脉失养、肝风内动之候。治以甘缓平补，正合虚则补之、络虚则通补之意。", ["空"]], "4921": ["病机", "脉细弦数不舒，细为血虚，弦为肝郁，数为火郁。胁痛由肝火抑郁，火郁则络燥，故脉不舒。此与寒滞、血著、暴怒诸痛不同，治当清润通络，以解郁火而润络燥。", ["细", "弦", "数"]], "4922": ["病机", "脉转劲为胃伤气逆、诸经之气上逆之象。频吐伤胃，气逆填胸聚脘，出入机逆，周行脉痹，故脉劲而舌干赤、嗳气不展如呃忒。辛香燥药不受，先议治肺以主气化，使气降则脉劲可缓。", ["劲"]], "4923": ["预后", "尸厥脉动而身静，气闭于外而气血未乱，通阳则生；大厥则脉乱，气血并走于上，根蒂空虚，三阳并羸，气返则生，不返则危。此以脉之动乱辨厥之轻重与预后吉凶。", ["动", "乱"]], "4924": ["病机", "脉数如浮，重按无力，非足三阳实热，乃阴虚失藏、伏寒化热、春令阳升、伏邪外发之象。发热自利、烦倦咳嘶、渴喜热饮，皆津液暗耗、虚靡不振之候，故宗春温下利治。", ["数", "浮"]], "4925": ["误治", "温邪从口鼻直入膜原，本非太阳客邪，羌防辛温发汗，强汗劫津伤阳，妄下劫液亡阴，致上窍不纳、下窍不便，甚则鼻鼾语难、惊痫瘛疭。此论温病误汗误下之逆，与伤寒足经传变不同。", []], "4926": ["预后", "脉左大急疾，右小微弱，左脉大疾为阴分大耗、虚阳外扰，右脉微弱为气弱。脐旁动气、肌肤枯燥，血脱阴伤，当暑月何以堪此？拟九龙法通补兼施，动气减则病可平和，示预后之险。", ["大", "急", "疾", "微"]], "4927": ["病机", "脉小弦为木气欲升而湿遏之象。素有浊阴上干，近湿气淫蒸，新旧合邪，壮热吐苦、哕逆、舌微白，皆湿浊内蕴、木郁不达之候。治以苦辛劫湿，先治新邪后治痼疾。", ["小", "弦"]], "4928": ["病机", "脉来和静为邪退正安之象，然舌苔已退而时或烦热、胸中未适，说明燥邪虽减未尽，余热内扰，故神识尚未全复。脉和静提示正气渐和，非邪盛之候，故治法以滋燥为先，养阴润燥以清余邪。", ["和", "静"]], "4929": ["治法", "邪脉悉退而见微迟和缓，是邪去正虚、胃气未复之象。微迟为阳气不足，和缓为胃气尚存，故用平调营卫使胃气自复，复脉汤主之。此段以脉象转和缓为邪退可复之征，主在调补而非攻邪。", ["微", "迟", "缓"]], "4930": ["病机", "脉小缓按之不为鼓击，说明伏邪客病本轻，非实热壅盛之候。丰腴过劳阳气受伤，内伏热气流布三焦，然脉不鼓击、二便通、略能纳谷，可征无停滞积聚。故不宜辛温表散、苦温消滞、苦寒沉降，当以甘寒养胃阴消息之。", ["小", "缓"]], "4931": ["病机", "脉坚劲不和，为暑热湿邪内著、脾胃气机壅滞之征。八旬又二，渴饮停脘欲吐、冷呃、自利稀水、小便不利，皆湿浊内阻、气化不利所致。脉坚劲说明邪实而正气尚能抗争，然尊年不敢过用清消，议清暑益气以苏脾胃。", ["坚", "劲"]], "4932": ["病机", "脉弦呕吐、心中懊𢙐、不纳水谷、倏冷忽热，为嗔怒七情兼客邪伏气，肝胆气逆、暑热内扰之象。弦脉主气郁邪阻，故见呕吐懊𢙐；汗多不宜表散，当清暑和中为正治，使气机调畅则诸症自解。", ["弦"]], "4933": ["病机", "左虚大、右涩小弱，为积劳元伤、正气亏虚之象。虚大为元气外浮，涩小弱为脏液劫烁、血脉不充。故见目瞑短气、遗尿肢掉、神识渐迷、晡时烦躁，乃内风欲扰、有痉厥之虑。当与甘药益气养液，不可攻表里以速其散越。", ["虚", "大", "涩", "小"]], "4934": ["病机", "脉转数、舌红，为湿中化热之征。面肿消、肤痛、汗减、耳鸣、咽呛、肛痔，说明湿热乘窍流布，营卫不通。数脉主热，故仍清气邪、佐通营卫，用桂枝白虎汤清泄阳明气分湿热，使邪从表里分消。", ["数"]], "4935": ["病机", "脉细数舌绛，烦渴时热，病九日邪气稍衰而正气已亏。细为阴液不足，数为余热未清，舌绛为热入营阴之象。故不宜再作有余治，当顾护正气、清养阴液，不可一味攻邪以伤已亏之正。", ["细", "数"]], "4936": ["病机", "脉软为正气不足之象，高年脾胃气阴两虚，运化失司则咳痰欲呕，饥时甚者胃中空虚、虚气上逆也。时邪虽未清，然脉不弦不数，知非实邪壅盛，乃正虚邪恋。软脉主虚，故治宜养胃阴、润肺降逆，用麦冬汤，不可攻伐。", ["软"]], "4937": ["病机", "脉数舌红，热象显然。先厥后热，邪气蕴伏日久，从传染而得，今脉数示热蒸营卫，头疼干呕、脘闷多痰皆热邪内郁、胃气上逆之征。数脉主热，热盛则虑其再厥，故当清透蕴伏之热，防厥逆复作。", ["数"]], "4938": ["病机", "脉缓舌色灰黄，缓非平和之缓，乃湿浊内蕴、阳气不运之象。头疼、周身掣痛、发热不止，皆时疫湿温之邪郁遏肌表经络。湿性黏滞故脉缓，舌灰黄为湿浊熏蒸。最忌辛温重药助湿，拟渗湿法使湿从下泄。", ["缓"]], "4939": ["病机", "左数右缓，左主血右主气，数示热郁，缓示湿滞。舌白发热自汗、溺痛、身半以上掣痛，皆湿邪痹阻、郁而化热之象。湿浊上蒙清窍则虑神昏厥逆，故用轻清渗湿方，使湿去热清，窍机得灵。", ["数", "缓"]], "4940": ["病机", "脉细舌灰白，细为阳气不足、湿郁不化之象。湿温半月余，邪虽解而余湿未尽，中宫阳气郁遏，失宣畅之机，故渴不多饮、膨闷不知饥。舌喜香味亦阳气郁而求宣之征。治宜护持胃阳、宣浊驱湿，不可再攻伐伤正。", ["细"]], "4941": ["病机", "脉促神倦，促为阳盛而阴不能济、正气已伤之象。温邪半月不解，发散消导反伤正气，内风乘虚上扰，故目上视、咳痰欲喘、唇燥舌红。促脉示正虚邪陷、风动于内，虑有痉厥之变，姑与甘缓法扶正熄风。", ["促"]], "4942": ["病机", "脉虚细无力，虚细为营阴亏耗、气血不足之象。热止后汗多，汗出伤阴，心悸头晕、寐多惊恐，皆营阴受伤、心神失养所致。舌红亦阴伤之征。虚细无力说明正虚未复，理宜和阳存阴，不可再事清泄。", ["虚", "细"]], "4943": ["病机", "左脉微数、右关微弦，弦为肝旺，数示郁热。胸脘痞闷、右眼角赤，皆肝木乘坤土、木郁化火之象。梦寐惊惕乃脾藏意、肾藏志而志意不藏，由七情内扰、六淫外侮所致。脉弦数说明肝脾失调，调养失宜则反复难愈。", ["数", "弦"]], "4944": ["病机", "原文“六脉略和”指脉象趋于平和，为邪退正复之象，但“舌胎已退，胸脘稍宽”而“微觉呆滞，大便干燥”，说明阴液枯竭、阳气郁结，脉和仅为相对缓和，非真健康。脉和而见阴枯阳结，故治以通阳佐润燥，调养静摄。", ["和"]], "4945": ["病机", "原文未识脉名，但“诊脉气和病情减”提示脉气渐和，阳气尚未全振。久病阴阳互伤，阳病久必伤阴，阴病久必伤阳，故病久调养失慎易反复。进苓桂术甘汤宣上鬲之阳，紧扣“阳气尚未全振”之机。", []], "4946": ["病机", "原文“脉神俱安”示脉象安和，但大便艰涩、脐间隐痛，乃高年肾阴暗亏，血液不能灌溉四旁，肠中枯燥所致。脉安而症见阴亏肠燥，故拟通幽汤润之，病机在肾阴暗亏、血枯肠燥。", []], "4947": ["病机", "原文“色脉非是有余”指脉症不显实象，而“语謇神呆，犹气机未为灵转”，说明湿为阴邪，阻滞气机，非单纯寒热。湿邪黏滞，故身体稍转动而神机未复，病机重在湿阻气机、非有余之证。", []], "4948": ["病机", "脉缓舌白带灰黑色，心中烦热、汗多渴饮、嘈杂如饥、肛中气坠，乃湿热内蕴而兼中气不足。脉缓主湿，舌灰黑为湿郁化热，但平昔脱肛，寒凉难投，故病机为湿热夹虚、中气下陷，治以和中法。", ["缓"]], "4949": ["病机", "左脉数，舌白目黄，遍身发黄，左腰胁痹痛，卧则气逆，嗳气咳呛则痛不可忍，系湿热著于络中，气机阻遏不宣。脉数主热，湿热交蒸故发黄；时邪方张，攻病难投，轻药为稳，病机为湿热阻络、气机壅遏。", ["数"]], "4950": ["病机", "原文未识脉名，述中年冲气痰升、喘急随发随止，从肝肾本病治，但肌肤丹疹浮肿甚速，腠膜映红，系夏秋口鼻受暑湿客气，上焦先伤，延漫中下，三焦皆为病薮。病机为伏邪引动宿病，上焦失解，三焦气机壅滞。", []], "4951": ["病机", "脉现左细右搏，左细为阴气先伤，右搏为阳热亢盛。积劳伏热，值冬温发，痰喘气促、左胁刺痛，系左升不已、右降失职；高年五液已衰，炎上之威莫制。病机为下虚不摄、阴伤阳亢，内伤兼症不与外感同法。", ["细", "搏"]], "4952": ["病机", "原文未出脉名，以“口中干燥，小水全无”言泉源已竭、阴液无以上承，又谓“湿热壅于胃口”致噤口利症；下元衰惫则冲脉气震高突。此段论攻病保真两难，病机属阴液枯竭、湿热壅阻、下元虚衰并见，非单一脉象可赅。", []], "4953": ["治法", "痢止咳频而脉虚形寒多悸，脉虚为气阳不足，形寒多悸乃中阳式微、心神不宁。前痢后咳，中气已伤，故进甘缓法，小建中去姜加玉竹，以建中气、养胃阴，使虚寒得复而咳痢可缓。", ["虚"]], "4954": ["病机", "稚年频伤风咳嗽、汗出痰多，乃卫外不固、肺易偏伤；春升气泄而指握无力、足疲语謇呕恶，原文谓“卫应乎胃，胃属阳明，其脉主司束筋骨，以流利九窍”，四肢属脾胃，舌为心苗，脾窍通焉。久伤气分乘气泄而病，属虚症，治充脾胃脉络。", []], "4955": ["病机", "脉虚数为阴亏于下、燥烁于上之象。虚为阴液不足，数为燥热内生，故见喉干舌燥欲咳。原文明言“非客病也”，即非外邪客表，乃内伤阴亏燥热，病本在下焦阴分，上灼肺喉。", ["虚", "数"]], "4956": ["预后", "脉细咳逆、不得侧眠、肌消色夺、经闭食减便溏，细脉主阴血亏少，久病损及三阴，渐至胃气欲败。原文谓“药饵难挽”，拟建中法冀胃旺纳谷，庶几带疾延年，故以预后判断为主。", ["细"]], "4957": ["病机", "脉沉而咳、不能著枕而卧，沉主里主下，老年下元虚衰，气不摄纳，浊气痰饮皆阴象，乘暮夜阴时寐发。发散清润皆非，当以小青龙开太阳撤饮下趋，病机在阳虚饮逆、气不归元。", ["沉"]], "4958": ["病机", "砭刺“引动脉中之气血”得小效，动脉示气血壅阻搏击。寒湿痹阻经络，久蓄蒸腐血液变热成脓，附骨痈疡延为漏卮，损及真气精髓，倐热蒸蒸、喉燥呛咳、纳减，属损症，草木攻邪反加剥斫。", ["动"]], "4959": ["病机", "酒客伏湿，脉数非必热盛，乃湿郁化热、蒸迫脉道；汗多咳嗽、食不易运，病在手足太阴。数脉在此示湿热内蕴、脾肺气机不利，与酒湿伏邪相应，故以运脾化湿清肺为治。", ["数"]], "4960": ["病机", "脉细软涩，细为营血不足，软为气馁不充，涩则血行滞涩。原文谓“气冲失血，寐欲遗精”，是阴血下夺、虚阳上冲之象；又见“纳谷不运，神思日倦”，显系操持太过、心脾两伤、上下失交。脉象正合中焦营虚、气血不能奉养之机，故治取中焦，使心脾之营自旺。", ["细", "软", "涩"]], "4961": ["病机", "稚年吐衄多属热伤，今脉小而不洪数，肌松而不充腠，是胃气已虚、阳升无制之征。原文谓“食少胃虚，阳升已露一斑”，脉小示中气不足，肌松示卫外不固，虚阳因而上浮。故不用苦寒直折，而进甘凉益胃，养胃阴以潜阳，使中焦安而升者自降。", ["小"]], "4962": ["病机", "秋暑失血、初春再发，而脉右大，右主肺胃，大为烦劳伤气、虚阳外浮之象。原文引《金匮》“脉大为劳，极虚亦为劳”，又分“脉大为劳，是烦劳伤气；脉虚为劳，是情欲致损”，正说明大与虚同属劳损，一由气耗，一由精伤。能纳食则胃气尚存，故谓病根驱尽可愈。", ["大", "虚"]], "4963": ["病机", "右寸浮数，余脉虚涩。浮数为肺有虚热上浮，虚涩则脾肺营血俱亏。原文谓失血后寒热已止，而“喉中作痒咳嗽，大便又不坚固”，咳属肺燥，便溏属脾虚，故断为“脾肺俱亏”，正处润肺碍脾、补脾碍肺之两难。脉虚涩示气血不充，浮数示虚热未清，故宜清心静气以渐复。", ["虚", "涩", "浮", "数"]], "4964": ["病机", "脉沉细而兼微数，沉细为肝肾精血亏虚，微数为阴亏而伏火内动。原文谓“精不营筋，又有伏火”，故见腰膝酸疼、宗筋短缩、筋肉拘挛等肝亏肾损之候，即《内经》“发为筋痿”之谓。精血不充则筋骨失养，伏火内灼则便涩溺淋，治宜滋肾舒肝，使精血渐充而筋骨柔和。", ["沉", "细", "微", "数"]], "4965": ["病机", "本段未载脉象，专论夏秋病机。原文谓“天地气机大泄，身气久虚，无以主持”，又谓“久热气伤，虚体未能收肃”，故肢节时寒、头巅欲冷。其机在病久诸气交馁，外卫之阳少护，液髓暗耗而血脉不营、阴乏内守，皆“生气之浅鲜”。治当温养益气、填补充形，顺秋冬收藏之势。", []], "4966": ["病机", "本段未出脉象，专论音哑之病机。原文谓“阳邪搏于三阴”，并举少阴之脉循喉咙、太阴之脉连舌本、厥阴之脉出咽喉，说明三阴经脉皆上络咽喉，阳邪搏结则音窍不利。既属阳邪搏阴，非单纯表邪，故叹“正未易治”，提示其病机深涉阴分，治难速效。", []], "4967": ["病机", "本段未载脉象，而言“气血索然，八脉失养”。原文述未交四九而天癸先绝，脊痛连腰胯、膝跗无力、伛偻气喘、耳鸣头晕、上热下冷，断为“奇经脉病，渐成痿痹废弃之疴”。督带维𫏋失养，诸脉隶肝肾阳明之间，故所患不专一所；交冬反现泄越之象，是失藏失固，治以补方中宣通八脉。", []], "4968": ["预后", "原文以“脉沉则生，浮则危”辨肠澼下白沫之预后。脉沉为肺气下移、阳陷于阴，气机尚能内守，故生；脉浮则虚阳欲散、真气欲离，故危。此以脉之沉浮判断阳气内陷与外脱之势，非主病之脉。", ["沉", "浮"]], "4969": ["病机", "原文述“勉强摇精”致阳缩囊纵、肛门脐窍收引、咽喉牵绊，乃少厥两阴精血有形损伤，气不及充注八脉，见症皆拘束之状。前服柔剂阳药反头巅经脉胀、耳窍鸣，是藏阴宜静而升阳动药不灵，故仿丹溪潜阳法。", []], "4970": ["病机", "原文谓夏季天地气机大泄，体虚无以主持，入秋火热气伤，虚体未能收肃，故肢节时寒、头巅欲冷。病久诸气皆馁，外卫之阳少护，液髓暗枯则血脉不营、阴乏内守，皆生气渐鲜之机，故急当温养益气、填补充形。", []], "4971": ["病机", "原文论浊腻膏淋日下最易损人津液，络脉遂槁；八脉隧道纡远，泛然补剂药力罔效。奇经如沟渠，满溢流入深河，不与十二经并行，故树根草皮难奏效，须用血肉填补固涩。此述久淋伤津、奇经失养之病机与治法。", []], "4972": ["主病", "原文载瓜果水寒、暴凉迅风内外两因，舌白渴不能饮、脘胀烦不寐、微呕无热，此足太阴中寒。已见冷汗肢厥，脉弱濡伏，乃寒湿内盛、阳气被遏、脉道不显之象，医犹以疲敝方药，故喻为隔靴搔痒。", ["弱", "濡", "伏"]], "4973": ["病机", "原文脉缓、身痛汗出、热解复热，谓水谷之气与湿并阻于气分，郁而成热。脉缓主湿滞气分、脾运不健，湿郁则热，故徒进清热不应，治宜利湿宣通，气分湿去则热自解。此以脉缓合症辨湿郁气分之病机。", ["缓"]], "4974": ["妇人", "原文脉右虚左弦，身麻肢冷、胎中胀闷、不饥吞酸，由中虚肝气内动。右虚主中气不足，左弦主肝气内动；五六月脾胃司胎，体质不受苦寒，故非清火酸泄气分所宜。此妊娠脉症合参，辨中虚肝动之机。", ["虚", "弦"]], "4975": ["病机", "原文述阳明脉衰、厥阴风动，经络交亏，故麻木痛痹、肢节重著，久而成痿。阳明主润宗筋，脉衰则气血不充；厥阴风动则筋脉失养。经络交亏，久病成痿，当以护阳之剂，此明病机与治则。", []], "4976": ["病机", "脉濡数主中暑。濡为体虚湿滞，数因暑热鼓动。暑为阳邪，昼行阳分，故脉势张而烦渴；夜静属阴，邪逼于内则多言呓语。原文谓“暑伤气”，本属虚症，故不可凝寒苦清以伐元气，脉象揭示正虚邪盛之机。", ["濡", "数"]], "4977": ["病机", "脉浮缓主风湿郁表。浮为邪在表，缓因湿性黏滞、营卫不和。身热汗出而热不为汗衰，是风湿相搏、瘀热郁蒸为黄。原文“风湿郁表，瘀热为黄”点明病机，脉浮缓正合表湿未解、热瘀发黄之候。", ["浮", "缓"]], "4978": ["病机", "脉浮滑主热邪入里、邪结阳分。浮示邪偏上焦，滑为痰热内壅。脘痞按之痛，是痰热互结心下；脉浮滑恰应“邪结阳分”，故拟小陷胸汤以清热涤痰开结。", ["浮", "滑"]], "4979": ["病机", "脉濡涩数主阳明蓄血。濡为湿滞，涩因血瘀，数由热蒸。至暮昏乱、身热未尽、腹痛便黑，皆瘀热互结阳明之征。原文“阳明蓄血”点明病机，脉象示湿瘀热交阻，故拟桃仁承气逐瘀泄热。", ["濡", "涩", "数"]], "4980": ["病机", "脉浮缓主风湿相搏于太阳之表。浮为邪在表，缓因湿滞、阳虚不运。身重、汗出、疼痛，是风湿郁表、营卫不通。原文“阳虚邪客”点明正虚邪客之机，故当通营卫以固表，拟桂枝附子汤温经散湿。", ["浮", "缓"]], "4981": ["病机", "脉沉微主少阴中寒。沉为病在里，微为阳气衰微。下利、呕逆、身痛、四肢厥冷，皆少阴阳虚阴盛之候。原文“少阴中寒”点明病机，脉沉微正示里阳不振，故应四逆汤急救其里以回阳。", ["沉", "微"]], "4982": ["病机", "脉微主少阴格阳。微为阳气虚极，下利厥逆是阴寒内盛，烦躁、面赤戴阳乃虚阳上浮、格拒于上。原文“格阳于上也”点明病机，脉微正示真阳衰微，故用白通去猪胆汁以纯阳破阴、招纳浮阳。", ["微"]], "4983": ["病机", "脉濡主体气素薄、炎暑烁金。濡为气虚湿滞，暑热耗气伤津，故懒倦、多汗、口渴。原文“炎暑烁金”点明暑热伤肺、气津两伤之机，脉濡正合虚体受暑、气不运湿之候，故当益气以保水之源。", ["濡"]], "4984": ["病机", "牝疟四日一发，脉沉弦迟。沉为里，弦主邪在少阳、疟邪深伏，迟则阳气不振。原文谓“阳气与中气乏竭”，故发必大吐大汗，吐汗更伤中阳。脉沉弦迟正示邪伏而正虚，非单纯和解可治，应扶阳补中以固元气，使卫气与邪相得而疟自止。", ["沉", "弦", "迟"]], "4985": ["主病", "脉洪大，兼烦渴汗出，为阳明中暍之候。洪大者，阳明热盛，气分燔灼，热迫津泄则汗出，热灼胃津则烦渴。原文断为“的系白虎汤候”，正以脉洪大与烦渴汗出相应，主阳明气分大热，宜白虎汤清泄里热、保津止渴。", ["洪", "大"]], "4986": ["病机", "脉沉微，腹痛吐利汗出，为太阴寒伤。沉主里，微主阳虚，寒邪内伤太阴，中阳不振，故腹痛吐利；阳虚不能固表则汗出。原文拟冷香饮子，正取温中散寒、扶阳止泻之意。脉沉微与吐利汗出并见，示里寒阳虚，非热利可比。", ["沉", "微"]], "4987": ["病机", "此段未言脉，专论久病入络。原文谓“凡久病必入络脉”，症由肝络过膈入胃，致胃翻呕吐、胀满，皆从肝出。医不明入络之理，药过胃肠而已，故非入络之方弗能效。议病发疏理肝木，病缓安胃土，示络病当以通络疏肝为要，非见吐治吐。", []], "4988": ["病机", "正当生旺之年而须色变，脉象弱芤。弱为精气不足，芤为阴血虚而脉道不充，故原文断为“男子精气衰薄，不为生育之征”。发属心火、眉主肝木、须应肾水，色不向荣即内不足之外候。法当宁心神、寡欲养精，从根本培补，非徒求子。", ["弱", "芤"]], "4989": ["病机", "此段未言脉，论滞痰阻经脉之气、瘀浊阻络脉之血，故病甚难治。经水将至必腹痛坚胀，乃气血壅阻络脉之征。前用乌骨鸡丸暂缓，今议经来时用回生丹，经过则宣通络血中气，使瘀浊去而胀满免。主旨明络脉气血瘀滞之病机与通络治法。", []], "4990": ["病机", "咳呛频多、呕吐涎沫，原文断为冲脉气冲不司收摄，肝肾阴气不足。咽喉久痛，缘少阴、厥阴脉循喉，阳气扰动无制，多属阴亏。脉形细动，细为阴亏，动为阳扰不宁，故不受温补肺药，久进必伤胃口。示病本在肝肾阴亏、冲气上逆，非肺家本病。", ["细", "动"]], "4991": ["病机", "此段未言脉，论生产频多、经水失期，冲脉厥气直攻心下，引胁环少腹，呕吐黑水，便出稀黑。黑为胃底之水、肠中之水，经年累月则病伤胃惫。原文谓“何暇见病治病”，务在安眠进食，仿仲景胃虚上逆例，示冲气上逆而胃虚，当先安胃固本。", []], "4992": ["病机", "原文未明言脉象，但述“两膝骨痛，暮夜甚，暖熨少安”，知寒湿阴邪从下受，痘后经脉留邪，新邪举发，病名曰痹。痹者气血凝滞，久则邪与气血混处，故取效颇迟。长夏发泄，宜针刺以行经络气血，使邪难容留，佐活络丹逐邪。", []], "4993": ["病机", "脉动为阳乘，虚数主阴乏。情志郁怒，气火燔灼，产育频经，奇经不固，阳乘脉动则经来如崩，阴络伤而内溢。脉来虚数，肌肉易热，乃阴乏不主内守，浮阳扰越外翔。形症及脉，难用温暖，故以震灵丹固下，通摄兼进。", ["动", "虚", "数"]], "4994": ["病机", "原文未出脉，述渴热向愈，更衣用力后阴囊忽大，为宿疝举发。明言阴虚气坠，非子和七疝同法。身前陷坠，任脉失担任，小便通调，故以酸甘定议，养阴缓急，非攻下所宜。", []], "4995": ["病机", "原文未出脉，述湿热下注，质薄肾虚，秋冬外邪犯肺，肺气失降，气隧壅塞，水谷气蒸变湿，横渍经脉，膀胱气痹，小溲不爽，湿坠大肠便稀，痹塞自下壅逆及上，喘息气冲，坐不得卧，甚于夜者，阴邪暮夜用事。治宗小青龙开鬼门、洁净腑。", []], "4996": ["预后", "夏至阴气不生，损不能复，当大热气泄愈甚，百脉诸气皆空，脂液尽耗，难望再醒。寒热乃身中阴阳互乘，阳由阴上越则顶巅痛，风木之火入中则呕逆呛咳，总由液涸神竭。进两仪煎、琼玉膏扶至稍凉再酌，示预后不良。", ["空"]], "4997": ["病机", "初春脉动而不鼓，收藏之司浅，阳动不藏。壮年未育，晨吐黑痰，皆水亏火炎、精气不充之象。胃旺能纳谷，则化源未绝，当专理下焦，补肾填精，不必以痰为虑，勿妄攻痰。", ["动"]], "4998": ["病机", "脉动于右，右主气，气热易升，阴不上承，故能食不能充津液。入春嗽血不止，乃气热升迫，阳络伤而血外溢。治养少阴之阴，使阴承阳降，勿苦降碍胃，以胃气能食为要。", ["动"]], "4999": ["预后", "脉涩无神，便溏食少，肛疮两月未合，已成漏症，延绵有痼疾之虞。涩为血少气滞，无神则胃气衰，嗔怒气扰中焦隐痛，耗气劫夺万难再饵。议东垣益气汤减黄耆，加木瓜、白芍，姜、枣制肝木，扶中兼柔肝。", ["涩"]]});